P.entries["item:or-kalar-s-head"] = {n="Or'Kalar's Head",s="Or'Kalar's Head är ett bevis på att Hammerfalls attacker har en farlig källa. Korin Fel ber dig att ta med det till henne vid utposten.",h="Or'Kalar's Head är ett bevis på att Hammerfalls attacker har en farlig källa.",kw={"arathi highlands","hammerfall","korin fel","mug'thol","or'kalar","or'kalar's head","stromgarde","the tower of arathor"},ang={["faction:Horde"]="Som medlem av Horde kan du hjälpa till att skydda Hammerfall och Korin Fels make från Or'Kalars attack."},sec={{t="Ett hot mot Hammerfall",b="Korin Fel skickar dig för att hitta Or'Kalar nära Tower of Arathor. Ogryn tjänar Mug'thol i Stromgarde och hyser ett starkt hat mot Korin Fels make, som besegrade honom för flera år sedan. Korin tror att Or'Kalar har gillrat en fälla för hennes make. Hon ber dig döda honom och ta med hans huvud till Hammerfall."}},faq={{q="Vem är Or'Kalar?",a="Or'Kalar är ett ogre i Stromgarde som tjänar Mug'thol och hatar Korin Fels make för att han besegrade honom för flera år sedan.",al={"or kalar","or'kalar identitet"}},{q="Varför vill Korin Fel att Or'Kalar dödas?",a="Korin tror att Or'Kalar har gillrat en fälla för hennes make och vill att ogret dödas för att skydda honom och Hammerfall.",al={"varför döda or'kalar","korins begäran"}},{q="Var hittar jag Or'Kalar?",a="Or'Kalar finns nära Tower of Arathor i Arathi Highlands.",al={"or'kalar plats","tornets ogre"}},{q="Vem tar emot Or'Kalar's Head?",a="Korin Fel tar emot Or'Kalar's Head vid utposten i Hammerfall.",al={"vart lämna huvudet","korin fel huvud"}}},fp="15,129,22.293.0,16.112.0,38.111.0,26.62.0,29.61.0"}
P.entries["item:oracle-crystal"] = {n="Oracle Crystal",s="Oracle Crystal är ett föremål som nagas tillverkar och deras orakel använder längs Desolaces kust. Maurin Bonesplitter söker efter en när han riktar sin uppmärksamhet mot en demonfurste.",h="Oracle Crystal är ett föremål som nagas tillverkar och deras orakel använder längs Desolaces kust.",kw={"azrethoc","desolace","maurin bonesplitter","naga","orakel","oracle crystal","slitherblade"},sec={{t="Nagatillverkning",b="Maurin Bonesplitter vill ha en Oracle Crystal från Slitherblade-nagorna längs Desolaces nordvästra kust. Nagorna tillverkar kristallerna åt sina orakel, som håller till bland de vidsträckta korallreven ute till havs. Maurin värdesätter kristallen och tänker använda den när han söker efter demonfursten Azrethoc."}},faq={{q="Vad är en Oracle Crystal?",a="En Oracle Crystal är ett föremål som nagorna tillverkar åt sina orakel att använda.",al={"oracle crystal","vad är kristallen","nagakristall"}},{q="Vem vill ha Oracle Crystal?",a="Maurin Bonesplitter ber om en Oracle Crystal när han jagar demonfursten Azrethoc.",al={"vem behöver kristallen","maurins kristall","bonesplitter vill ha"}},{q="Var kan jag hitta en Oracle Crystal?",a="Slitherblade-oraklen håller till ute till havs längs Desolaces nordvästra kust.",al={"var finns kristallen","oracle crystal-plats","hitta nagakristallen"}},{q="Vem använder Oracle Crystals?",a="Nagorna tillverkar Oracle Crystals åt sina orakel att använda.",al={"vem använder den","nagaorakel","kristallens syfte"}}},fp="14,164,10.291.0,26.77.0,29.85.0,35.81.0,25.56.0"}
P.entries["item:ordanus-head"] = {n="Ordanus' Head",s="Ordanus' Head är den fasansfulla trofé som togs från Keeper Ordanus vid Raynewood Retreat i Ashenvale. Den hämtades åt blodmagikern Braelyn Firehand och är ett obestridligt bevis på att en av Cenarius äldsta söner har fallit för arkan hämnd.",h="Ordanus' Head är den fasansfulla trofé som togs från Keeper Ordanus vid Raynewood Retreat i Ashenvale.",kw={"ashenvale","braelyn firehand","cenarius","lundens väktare","ordanus","ordanus' head","raynewood retreat","stonetalon","sunrock retreat"},ang={["class:Druid"]="För en druid är det en bister påminnelse om den bittra, blodiga fiendskap som arkanbesvärjare fortfarande hyser mot vildmarkens beskyddare att bära huvudet av en av Cenarius äldre söner.",["faction:Horde"]="Att fälla Ordanus och överlämna hans huvud till Braelyn hjälper horden att befästa sitt fäste längs Stonetalon och Ashenvales omstridda gränser och försvagar det lokala nattalviska ledarskapet."},sec={{t="Ett gammalt groll",b="Keeper Ordanus var en uråldrig väktare av lunden och en av skogsguden Cenarius äldre söner. När Braelyn Firehand på sin mästares order besteg höjderna i Stonetalon Mountains ville hon sätta stopp för druidernas kvävande av magin på toppen och utkräva hämnd på Ordanus. Men väktaren fördes i hemlighet till hjärtat av Ashenvale innan hon hann slå till. Med arkan skådning spanade hon genom skogens trädkronor och fann hans fristad i Raynewood Retreats grenar. Hon krävde hans avhuggna huvud som bevis på att den vilda halvgudens arrogans till slut hade fått sitt svar."},{t="Högmodets pris",b="Braelyn bär på ett gammalt agg mot Ordanus, som hon kände för länge sedan, och hatar druidernas försök att stävja magins flöde. I livet ansåg sig Ordanus stå över till och med den uråldriga Highborne-adeln. Genom att ta hans huvud slår Firehand symboliskt tillbaka mot Cenarius arv och förklarar att ingen väktare av vildmarken kan hejda den råa magiska kraftens återkomst."}},faq={{q="Vem var Keeper Ordanus?",a="Keeper Ordanus var en uråldrig väktare av lunden och en av Cenarius äldre söner. För länge sedan drabbade han samman med den nattalviska adelns arkanutövare och blev känd för sitt djupa förakt för dem som utövade arkan konst.",al={"vem är ordanus","ordanus bakgrund","vad är ordanus"}},{q="Var samlar man in huvudet?",a="Huvudet tas från Keeper Ordanus på den upphöjda träplattformen vid Raynewood Retreat, en befäst nattalvisk bosättning uppe bland trädkronorna i centrala Ashenvale.",al={"var hittar man ordanus huvud","ordanus plats","ordanus vid raynewood retreat"}},{q="Varför vill Braelyn Firehand ha hans huvud?",a="Braelyn Firehand kände Ordanus för länge sedan och avskydde hans arrogans, eftersom han ansåg sig stå över till och med Highborne. Hon hatar också druiderna och Cenarius söner för att de försöker hejda magins flöde och förde bort Ordanus från toppen innan hon hann fram till honom.",al={"varför vill braelyn ha ordanus huvud","braelyns agg","varför döda ordanus"}},{q="Vad händer när huvudet har lämnats över?",a="När Ordanus' Head överlämnas till Braelyn vid Sunrock Retreat är hennes blodsskuld reglerad, och hon belönar legosoldaten med den mäktiga gåva hon lovade.",al={"lämna in ordanus huvud","efter ordanus död","braelyn firehands uppdragsbelöning"}}},fx={e1459048={q="Var kommer Ordanus' Head ifrån?",a="Denna dystra trofé tas direkt från Keeper Ordanus, en av skogshalvguden Cenarius äldsta söner. Ordanus ansågs en gång vara trygg på toppen av Stonetalon Peak, men flydde till Ashenvale och tog sin tillflykt högt uppe i Raynewood Retreat innan han jagades ned.",al={"ordanus' heads ursprung","var kom ordanus' head ifrån","vem tillhör ordanus' head"}}},fp="13,146,22.579.0,19.368.1,23.225.0,29.161.0,40.265.0,41.141.1"}
P.entries["item:orendil-s-cure"] = {n="Orendil's Cure",s="Orendil's Cure är en läkande dryck som örtkännaren Orendil Broadleaf blandade till i norra Ashenvale. Den tillverkas av den sällsynta örten Bathran's Hair och ska behandla den mystiska, dödliga sjukdom som drabbat Relara Whitemoon i Astranaar.",h="Orendil's Cure är en läkande dryck som örtkännaren Orendil Broadleaf blandade till i norra Ashenvale.",kw={"ashenvale","astranaar","bathran's hair","orendil broadleaf","orendil's cure","pelturas whitemoon","relara"},ang={["profession:Herbalism"]="Botemedlet visar den stora läkande kraften hos Ashenvales inhemska växter, särskilt Bathran's Hair, som bara trivs i vissa skuggiga delar av skogen.",["race:NightElf"]="För Night Elves i Astranaar är det brådskande att rädda Relara. Det kräver både eremiters skogskunskap, som Orendils, och gudomlig tro på Elune."},sec={{t="En fars hopp",b="När unga Relara Whitemoon blev dödligt sjuk i Astranaar hjälpte inga vanliga läkemedel mot hennes åkomma. Hennes förtvivlade far, Pelturas Whitemoon, vände sig till Orendil Broadleaf, en eremit och mästare på naturmedicin som bodde i Ashenvales norra trakter. Orendil använde knippen av den sällsynta växten Bathran's Hair, plockade bland de hemsökta ruinerna av Bathran's Haunt, för att brygga denna skräddarsydda blandning. När flaskan anländer får Pelturas ett hopp han knappt hade kvar, men läkemedlet bromsar bara sjukdomen, så Pelturas måste söka vidare efter de botemedel Orendil föreslog."}},faq={{q="Vad används Orendil's Cure till?",a="Läkemedlet är framtaget för att lindra och behandla Relara Whitemoon, ett ungt Night Elf-barn i Astranaar som plötsligt drabbats av en svår sjukdom.",al={"orendils botemedel syfte","vad gör botemedlet","vem är botemedlet till för"}},{q="Vem tillverkade läkemedlet?",a="Det tillreddes av Orendil Broadleaf, en tillbakadragen Night Elf-örtkännare som bor i Ashenvales norra skogar och är känd för sin kunskap om skogens växter och läkemedel.",al={"vem gjorde orendils botemedel","skaparen av orendils botemedel"}},{q="Vilka ingredienser användes?",a="Den viktigaste ingrediensen är Bathran's Hair, en skör och ovanlig växt som plockas bland ruinerna av Bathran's Haunt i norra Ashenvale.",al={"botemedlets ingredienser","vad innehåller orendils botemedel"}},{q="Botar drycken barnet helt?",a="Inte helt. Pelturas upptäcker senare att Orendil's Cure bara bromsade sjukdomen som spred sig i hans dotter, så han söker ett starkare botemedel som Orendil hade föreslagit: Elune's Tear.",al={"botade det relara","är relara botad"}}},fx={["8e86537e"]={q="Vad är Orendil's Cure?",a="Orendil's Cure är en läkande brygd som örtkunnige Orendil Broadleaf tillreder i norra Ashenvale. Den är framtagen som en specialbehandling för ett plötsligt och allvarligt sjukdomsfall och är ett desperat försök att rädda livet på ett ungt Night Elf-barn som drabbats av en mystisk åkomma.",al={"orendil's cure i berättelsen","vad är orendil's cure","orendils läkemedel"}},["6add91d1"]={q="Varför behövs Orendil's Cure?",a="I Astranaar ligger Pelturas Whitemoons unga dotter Relara dödssjuk. När vanliga behandlingar inte hjälpte sökte hennes far desperat hjälp hos Orendil Broadleaf. Örtkunnige Orendil tillredde denna särskilda blandning i hopp om att stabilisera barnet innan sjukdomen tar hennes liv.",al={"varför behövs orendil's cure","vem behöver orendil's cure","varför leverera orendil's cure"}}},fp="14,163,15.497.0,32.142.0,21.161.0,38.126.0,43.152.1"}
P.entries["item:orwin-s-shovel"] = {n="Orwin's Shovel",s="Orwin Gizzmick lånar ut sin spade i Camp Mojache så att du kan leta efter Gordunni-kobolt. Det blåskimrande mineralet ligger begravt vid Gordunni Outpost, där ogres vaktar det noga.",h="Orwin Gizzmick lånar ut sin spade i Camp Mojache så att du kan leta efter Gordunni-kobolt.",kw={"camp mojache","feralas","gordunni-kobolt","gordunni outpost","orwin gizzmick","orwins spade","spade"},ang={["profession:Mining"]="Som gruvarbetare känner du till värdet av en begravd åder. Orwin's Shovel leder dig till kobolt som gömmer sig bland Gordunni-ogres."},sec={{t="En prospektörs verktyg",b="Orwin Gizzmick har just kommit till Feralas, och mineralet som Gordunni-ogres begravt har fångat hans intresse. Från Camp Mojache skickar han dig norrut med sin spade för att samla kobolt från deras utpost. Det blå skenet visar var du ska gräva. Orwin tänker ta med sig proverna vidare och hitta en köpare."}},faq={{q="Vem äger Orwin's Shovel?",a="Orwin Gizzmick lånar ut sin spade från Camp Mojache så att du kan gräva upp Gordunni-kobolt.",al={"orwins spade","vem har spaden"}},{q="Vad används Orwin's Shovel till?",a="Orwin's Shovel används för att gräva upp Gordunni-kobolt vid Gordunni Outpost i Feralas.",al={"spadens syfte","vad gräver jag med","koboltspade"}},{q="Var använder jag Orwin's Shovel?",a="Du använder Orwin's Shovel vid Gordunni Outpost norr om Camp Mojache, där kobolten ligger begravd.",al={"var används spaden","spade vid gordunni outpost","var gräver man efter kobolt"}},{q="Varför vill Orwin ha Gordunni-kobolt?",a="Orwin hoppas hitta någon som betalar bra för kobolten medan han fortsätter sina resor.",al={"varför kobolt","orwin vill ha kobolt","koboltköpare"}}},fp="14,175,19.298.0,24.89.0,27.84.0,30.97.0,36.89.0"}
P.entries["item:oslow-s-toolbox"] = {n="Oslow's Toolbox",s="Oslow's Toolbox innehåller de viktiga byggverktyg som Foreman Oslow behöver i Lakeshire. På vägen från Goldshire fraktades förnödenheterna över Lake Everstill, men sänktes av en orcisk katapultbeskjutning.",h="Oslow's Toolbox innehåller de viktiga byggverktyg som Foreman Oslow behöver i Lakeshire.",kw={"foreman oslow","lake everstill","lakeshire","oslow","redridge","sjunken kista","de förlorade verktygen","verktygslåda"},ang={["faction:Alliance"]="Eftersom Lakeshire nästan är isolerat under Blackrocks belägring är det avgörande att återta Oslows förnödenheter för att hålla stadens försvarsverk intakta."},sec={{t="En ödesdiger överfart",b="Att underhålla Lakeshires försvar och infrastruktur är en utmattande utmaning, särskilt när Blackrock-orcher belägrar Redridge Mountains. Foreman Oslow beordrade att en viktig uppsättning byggverktyg skulle hämtas från Goldshire. Eftersom huvudbron in till Lakeshire hade förstörts av fienden måste lasten lastas i en roddbåt för att ta sig över Lake Everstill. Överfarten avbröts plötsligt när Blackrock-styrkor träffade båten med en katapultsalva, så att båten och Oslows tunga kista sjönk rakt ner i det murlocfyllda djupet."}},faq={{q="Varför ligger Oslow's Toolbox på sjöns botten?",a="Verktygslasten fraktades från Goldshire. Eftersom bron till Lakeshire hade förstörts under belägringen måste förnödenheterna ta sig över Lake Everstill med båt. Blackrock-orcher besköt roddbåten med en katapult och sänkte den, så att verktygslådan hamnade på sjöbotten.",al={"varför ligger verktygslådan i vattnet","hur förlorade oslow sina verktyg","berättelsen om den sjunkna verktygslådan"}},{q="Vem äger verktygslådan?",a="Verktygslådan tillhör Foreman Oslow, arbetsledaren som ansvarar för byggen och reparationer i Lakeshire. Utan rätt utrustning är det nästan omöjligt att underhålla stadens befästningar medan attackerna fortsätter.",al={"vem är oslow","oslow ägare","foreman oslows verktyg"}},{q="Var i Lake Everstill sjönk verktygen?",a="Verktygen ligger i en sjunken kista nära vraket efter den förstörda roddbåten i Lake Everstill, bland undervattensklippor söder om ett framträdande murlocläger vid strandkanten.",al={"verktygslådans plats","var finns den sjunkna kistan","var sjönk båten"}},{q="Vilka faror vaktar den sjunkna kistan?",a="Vattnen kring vraket är fulla av fientliga murloc och rovgiriga vattenlevande bestar, däribland farliga Lake Threshers som stryker omkring i sjöns djupare delar.",al={"faror nära verktygslådan","fiender i lake everstill","vad vaktar oslows verktyg"}}},fx={["543d5407"]={q="Varför behöver Foreman Oslow få tillbaka sin verktygslåda?",a="Lakeshire är hårt belägrat, avskuret från omvärlden och i desperat behov av förnödenheter. Som stadens förman behöver Oslow sin utrustning för att underhålla och reparera Lakeshires byggnader och försvar. Leveransvagnen från Goldshire kunde inte ta sig över den förstörda bron, och när ersättningsverktygen gick förlorade i sjön avstannade viktigt byggarbete. Att hitta dem är avgörande för stadens överlevnad.",al={"varför vill oslow ha verktygslådan","varför behöver oslow verktyg","varför hämta oslows verktygslåda"}}},fp="15,106,18.372.0,49.208.0,22.198.0,43.173.0,36.144.0"}
P.entries["item:osric-s-crate"] = {n="Osric's Crate",s="Vid Sentinel Hill för Osric's Crate med sig rustning från Stormwind till People's Militia. Försvararna möter Defias Brotherhood och kringströvande gnoller utan Stormwinds armé.",h="Vid Sentinel Hill för Osric's Crate med sig rustning från Stormwind till People's Militia.",kw={"dungar longdrink","grip","osric","osric's crate","peoples militia","quartermaster lewis","sentinel hill","westfall"},ang={["faction:Alliance"]="För Alliansen bidrar varje sändning med vapen och rustningar som når Sentinel Hill till att hindra Defias Brotherhood från att ta kungarikets västra gränser."},sec={{t="Förnödenheter till fronten",b="Westfall står inför Defias Brotherhood och kringströvande gnoller, medan Stormwinds armé fortfarande är frånvarande. Vid Sentinel Hill måste People's Militia klara sig utan kronans formella stöd. Osric's Crate innehåller nytillverkad rustning från huvudstaden, skickad till Quartermaster Lewis för att fördelas bland frivilligkämparna."},{t="Bevingat kurirnätverk",b="Gripar för lådan från Dungar Longdrinks tillhåll i Stormwinds Trade District till Thor vid Sentinel Hill. Färden undviker de farliga vägarna genom Elwynn Forest och över gränsen till Westfall, där banditer kan överfalla resande. Gripar hjälper till att hålla gränsgarnisonerna försörjda under krigstid."}},faq={{q="Vad finns i Osric's Crate?",a="Osric's Crate innehåller skyddande rustning tillverkad i Stormwind. Quartermaster Lewis tar emot leveransen och förbereder sig på att fördela den bland kämparna som försvarar Sentinel Hill.",al={"vad finns i lådan","innehållet i osrics låda","osrics lådinnehåll"}},{q="Vem är Osric?",a="Osric är en rustningsmakare i Stormwind som förberedde sändningen till People's Militia, som håller stånd i Westfall.",al={"vem är osric","vem skickade osrics låda"}},{q="Vem tar emot lådan?",a="Quartermaster Lewis tar emot lådan. Han sköter förnödenheter och utrustning åt People's Militia vid Sentinel Hill i Westfall.",al={"vart ska lådan","vem ska jag ge osric's crate till","lådans mottagare"}},{q="Varför levereras lådan med grip?",a="Banditer och laglösa gör vägarna genom Stormwind, Elwynn Forest och Westfall farliga. Gripfärden från Dungar Longdrink i Stormwind till Thor vid Sentinel Hill för fram rustningen snabbt och säkert.",al={"varför flyga med lådan","varför använda gripar","osrics lådfärd"}}},fx={["34d354cb"]={q="Vad är Osric's Crate?",a="Osric's Crate är en rustningsleverans från Stormwind City. Den är avsedd för försvararna vid Sentinel Hill i Westfall, som desperat saknar utrustning medan de håller stånd mot Defias Brotherhood.",al={"vad är osric's crate","föremålet osric's crate","vad finns i osric's crate"}},["091b5cbb"]={q="Var kommer Osric's Crate ifrån, och vem tillverkade den?",a="Lådan kommer från Stormwind City, där Osric packade och skickade den för att förse People's Militia. Gryphon Master Dungar Longdrink anförtror den åt dig så att du kan flyga med den på en gryphon tvärs över riket till Westfall.",al={"vem tillverkade osric's crate","var kom osric's crate ifrån","osric's crates ursprung"}},["11fb3015"]={q="Varför vill någon ha Osric's Crate?",a="Quartermaster Lewis och People's Militia vid Sentinel Hill behöver rustningen där inne omedelbart. Westfall har övergivits av kungens styrkor och översvämmats av laglösa, så varje skyddsutrustning är avgörande för att hålla försvararna vid liv.",al={"varför leverera osric's crate","varför vill lewis ha osric's crate","syftet med osric's crate"}}},fp="13,181,22.237.0,22.301.0,29.174.0,13.101.0,23.128.0,38.199.0"}
P.entries["item:overdue-package"] = {n="Overdue Package",s="Overdue Package är en av varorna som Krinkle Goodsteel behöver i sitt arbete i Gadgetzan. Den står i hans liggare tillsammans med material från flera avlägsna platser.",h="Overdue Package är en av varorna som Krinkle Goodsteel behöver i sitt arbete i Gadgetzan.",kw={"beezil's wreck","skadad låda","dustwallow marsh","gadgetzan","goodsteels liggare","krinkle goodsteel","försenat paket"},sec={{t="Bland varorna",b="Krinkle Goodsteel i Gadgetzan samlar in varor från Searing Gorge och längre bort. I hans liggare står Overdue Package bland dem, tillsammans med ett kristallbensskaft och en balanserad flameberge. Paketet ligger i en skadad låda vid Beezil's Wreck i Dustwallow Marsh."}},faq={{q="Vad är Overdue Package?",a="Overdue Package är en av varorna som står i Krinkle Goodsteels liggare för hans arbete i Gadgetzan.",al={"försenat paket","paket till krinkle","goodsteels paket"}},{q="Var finns paketet?",a="Overdue Package ligger i en skadad låda vid Beezil's Wreck i Dustwallow Marsh.",al={"var finns paketet","paketets plats","hitta försenat paket"}},{q="Vem vill ha paketet?",a="Krinkle Goodsteel i Gadgetzan söker efter Overdue Package tillsammans med de andra varorna i sin liggare.",al={"vem vill ha det","krinkle goodsteels paket","paket till vem"}},{q="Varför är det försenat?",a="Namnet visar att det är försenat, men ingen anledning till dröjsmålet anges.",al={"varför försenat","försenat paket","vad är försenat"}}},fp="15,166,15.262.0,28.102.0,21.80.0,22.98.0,18.67.0"}
P.entries["item:package-of-empty-ooze-containers"] = {n="Package of Empty Ooze Containers",s="Det här paketet är en uppsättning specialiserade, tomma provburkar som tillhandahålls av gnomforskaren Laris Geardawdle i Ironforge. De är avsedda för farlig provtagning i Felwoods fördärvade skogar och utformade för att säkert förvara besmittade och förbannade slemextrakt utan att lösas upp.",h="Det här paketet är en uppsättning specialiserade, tomma provburkar som tillhandahålls av gnomforskaren Laris...",kw={"behållare","förbannad","felwood","ironforge","burkar","laris geardawdle","slem","paket","slemmassa","besmittad"},ang={["faction:Alliance"]="Att samla in de här proverna hjälper Alliance att hålla jämna steg med den oroande forskning som Forsakens Royal Apothecary Society bedriver.",["race:Gnome"]="Laris Geardawdle ser den här slemforskningen som ett viktigt tillfälle att visa dvärgarna i Ironforge att det var mödan värt att ta emot gnomiska flyktingar."},sec={{t="Forskningsutrustning för fältarbete",b="Uppsättningen innehåller ett dussin tomma burkar, fördelade mellan behållare avsedda för förbannat och besmittat slem, och sattes ihop av Laris Geardawdle för orädda resenärer på väg till Felwood. Eftersom råa slemprover är ökänt frätande och gärna smälter vanlig packning är tåligt, förseglat glas nödvändigt för att transportera de sura resterna över kontinenterna tillbaka till uppfinnarens arbetsbänk i Ironforge."},{t="Slemmets mysterium",b="Geardawdles intresse för slem är långt ifrån en enkel excentrisk hobby. Han har lagt märke till att forskare från Forsaken och Royal Apothecary Society regelbundet samlar in dessa märkliga organismer runtom i Azeroth, och misstänker att slem kan dölja djupa hemligheter om världens ursprung. Geardawdle teoretiserar att slemmassor kan vara ursprungliga utsöndringar med koppling till själva planetens skapelse, och han förlitar sig på fältagenter som använder den här utrustningen för att samla bevisen han behöver för att vinna anseende inom Explorers' League."}},faq={{q="Vad finns i paketet med tomma slembehållare?",a="Paketet innehåller tolv provburkar: sex tomma burkar avsedda för förbannat slem och sex för besmittat slem.",al={"paketinnehåll","vad innehåller paketet","slem i burkar"}},{q="Vem tillhandahåller det här paketet?",a="Det delas ut till Alliance-äventyrare av Laris Geardawdle, en gnomisk lärd och forskare verksam i Ironforge.",al={"vem ger burkarna","laris geardawdles uppdragsföremål","var får jag slem paketet"}},{q="Var är behållarna tänkta att användas?",a="De är avsedda att användas i Felwoods fördärvade vildmark, där äventyrare måste besegra besmittade och förbannade slemmassor för att samla rester direkt från de fällda varelserna.",al={"var använder jag slem burkarna","vilken zon har slem","slem burk plats"}},{q="Varför vill Laris Geardawdle ha de här slemproverna?",a="Laris har lagt märke till att Forsakens Royal Apothecary Society samlar in slem runtom i världen och vill avslöja dess hemligheter. Han hyser också en okonventionell teori om att slemmassor kan vara ursprungliga utsöndringar med koppling till Azeroths skapelse, och hoppas att ett bevis ska ge honom anseende inom Explorers' League.",al={"varför samla slem","geardawdles forskning","varför vill laris ha slem"}}},fx={d8bf9111={q="Vad är Package of Empty Ooze Containers?",a="Det är ett fältkit som gnomforskaren Laris Geardawdle satt ihop i Ironforge. Paketet innehåller särskilt förberedda burkar för att samla in och förvara prover på ett säkert sätt. Proverna hämtas från de korrumperade slem och geléer som finns i Felwood.",al={"vad är package of empty ooze containers","paketet med slembehållare","bunt med tomma slembehållare"}}},fp="32,181,24.324.0,23.402.0,52.91.0,26.110.0,44.137.0,50.260.0"}
P.entries["item:painted-gnoll-armband"] = {n="Painted Gnoll Armband",s="Vid Westbrook Garrison är Painted Gnoll Armbands bevis på att Riverpaw-gnoller har dödats. De märkta banden kommer från flockar som tränger mot Elwynn Forests västra gräns.",h="Vid Westbrook Garrison är Painted Gnoll Armbands bevis på att Riverpaw-gnoller har dödats.",kw={"belöning","deputy rainer","elwynn forest","gnoller","painted gnoll armband","riverpaw","stone cairn lake","westbrook garrison"},ang={["faction:Alliance"]="Som äventyrare i Alliansen hjälper du Westbrook Garrison att hålla Stormwinds västra gräns genom att samla in armbanden, medan stadens stående armé är upptagen på annat håll."},sec={{t="Riverpaws troféer",b="Riverpaw-krigare och asätare bär grova armband målade med enkla stam-mönster. Banden kommer från gnoller längs Elwynn Forests vildmarksgränser. För Stormwinds försvarare utgör flockarna ett växande hot nära Stone Cairn Lake och i skogarna söder om Westbrook Garrison."},{t="Belöning från Westbrook Garrison",b="Stormwinds armé är utspridd över hela kungariket, så Westbrook Garrison har svårt att säkra den västra gränsen. Deputy Rainer utlovar en stående belöning för att döda Riverpaw-outtrunners och -runts. Deras målade armband bevisar dödsfallen och hjälper ställföreträdarna att räkna belöningarna och tunna ut flockarna nära de närliggande jordbruken."}},faq={{q="Varför vill Westbrook Garrison ha armbanden?",a="Deputy Rainer vid Westbrook Garrison samlar in armbanden som bevis på att Riverpaw-gnoller har dödats. Garnisonens trupper kan inte ensamma hantera flockarna som tränger fram, så Stormwind betalar belöningar till äventyrare som kommer tillbaka med troféerna.",al={"varför armband","vem vill ha målade gnollarmband","deputy rainer belöning"}},{q="Vilka gnoller bär de här målade armbanden?",a="Riverpaw-gnoller bär de målade armbanden. Riverpaw Outrunners och Riverpaw Runts härjar i skogarna söder om Westbrook Garrison och längs stränderna runt Stone Cairn Lake.",al={"var faller armbanden","vem släpper painted gnoll armband","vilka gnoller har armband"}},{q="Varför finns Riverpaw-gnoller i Elwynn Forest?",a="Riverpaw-flockar har trängt österut längs Elwynn Forests gränser och slagit läger nära Stone Cairn Lake och skogsbrynen. Eftersom kungarikets militära närvaro har minskat jagar och rotar de efter föda och hotar närliggande bosättningar.",al={"varför är gnoller här","gnollinvasion i elwynn","riverpaw i elwynn"}},{q="Vad betyder färgen på armbanden?",a="Färgen markerar troféer tagna från Riverpaw-gnoller och hjälper till att bevisa dödsfallen för Deputy Rainer. Mönstren har ingen angiven rang eller betydelse.",al={"varför är de målade","gnollarmbandens märken"}}},fx={["586b453e"]={q="Vad är ett Painted Gnoll Armband?",a="Ett Painted Gnoll Armband är en grov prydnad som Riverpaw-gnolls bär. Flokken tillverkar och målar armbanden för att markera sin närvaro i Elwynn Forests gränstrakter. För Stormwind Army är de ett obestridligt fysiskt bevis på att en plundrande gnoll har dödats.",al={"vad är painted gnoll armband","painted gnoll armband i berättelsen","gnollarmband"}}},fp="21,142,22.279.0,29.306.0,48.226.0,41.166.0,41.226.0,54.140.0"}
P.entries["item:panther-cage-key"] = {n="Panther Cage Key",s="Panther Cage Key är en liten metallnyckel som Wizlo Bearingshiner har vid Whitereach Post. Den öppnar en förstärkt bur med ett rasande, fångat rovdjur i spillrorna efter en överfallen karavan i Thousand Needles.",h="Panther Cage Key är en liten metallnyckel som Wizlo Bearingshiner har vid Whitereach Post.",kw={"centaur","hypercapacitor gizmo","panther cage key","thousand needles","whitereach post","wizlo bearingshiner"},ang={["faction:Horde"]="Genom att hjälpa Wizlo bidrar du till att säkra vägarna runt Whitereach Post i Thousand Needles efter centaurernas plundringar.",["profession:Engineering"]="Nyckeln öppnar buren där en tinkares instabila prototyp förvaras. Det visar att excentriska uppfinnare kan gömma sina ömtåligaste mekanismer på de farligaste platserna."},sec={{t="Ett osäkert lås",b="När centaurplundrare anföll och plundrade en karavan norr om Whitereach Post undkom goblintinkaren Wizlo Bearingshiner med knapp nöd. Bland spillrorna av vagnar och plundrad last lämnade rövarna en sak helt orörd: en stadig bur med en våldsam, sällsynt panter. Runt rovdjurets hals hängde Wizlos främsta uppfinning, en Hypercapacitor Gizmo. Centaurerna ville inte närma sig det morrande odjuret och höll sig därför på avstånd från buren. Wizlos nyckel blev det enda sättet att öppna dörren och hämta apparaten."}},faq={{q="Vem ger dig Panther Cage Key?",a="Wizlo Bearingshiner ger nyckeln till äventyrare. Han är en goblintinkare som vilar vid Whitereach Post i nordvästra Thousand Needles.",al={"vem ger panternyckeln","var får man tag på panterbursnyckeln","var hittar man panterbursnyckeln"}},{q="Vad öppnar nyckeln?",a="Den öppnar en järnbur bland de trasiga vagnarna från en förstörd karavan strax norr om Whitereach Post. Där inne finns en rasande, farlig panter.",al={"vad öppnar panternyckeln","var finns panterburen","var är buren"}},{q="Varför plundrade inte centaurerna buren?",a="Centaurerna plundrade resten av karavanen, men pantern i buren var så våldsam och hotfull att inte ens rövarna vågade röra den.",al={"varför lämnade centaurerna pantern","är centaurerna rädda för pantern"}},{q="Vad finns i buren utöver odjuret?",a="Wizlos främsta Hypercapacitor Gizmo sitter fast runt panterns hals. Den som vill få tillbaka uppfinningen måste därför låsa upp buren och möta rovdjuret på nära håll.",al={"varför öppna buren","vad har pantern runt halsen"}}},fx={b335554a={q="Varför vill Wizlo Bearingshiner ha tillbaka Panther Cage Key?",a="Wizlo Bearingshiner ger dig nyckeln enbart för att du ska kunna öppna buren vid hans förstörda karavan och döda den vilda pantern där inne. Odjuret bär hans dyrbara Hypercapacitor Gizmo runt halsen. När du är klar vill han ha tillbaka nyckeln tillsammans med sin uppfinning, så att karavanresterna och hans farliga ägodel kan redovisas fullständigt.",al={"varför behövs panther cage key","varför behöver wizlo nyckeln","varför vill någon ha panther cage key"}}},fp="16,160,17.423.0,34.115.0,25.142.0,37.137.0,42.139.0"}
P.entries["item:parker-s-lunch"] = {n="Parker's Lunch",s="Parker's Lunch är en nylagad måltid som Darcy har packat i Lakeshire. Den är avsedd för Guard Parker under hans patrull och ger en enkel inblick i de vardagliga banden och små bekvämligheterna bland Redridges försvarare.",h="Parker's Lunch är en nylagad måltid som Darcy har packat i Lakeshire.",kw={"en gratis måltid","darcy","guard parker","lakeshire","parker's lunch","redridge"},ang={["faction:Alliance"]="Medan huvudstaden dröjer med att skicka förstärkningar är den lokala solidariteten mellan stadsborna och de få kvarvarande vakterna det som håller Lakeshire i gång.",["profession:Cooking"]="En varm, färdigpackad måltid är ofta den enda tröst som hjälper gränsvakterna att uthärda långa arbetspass och fientliga vilddjur i vildmarken."},sec={{t="En måltid för färden",b="Medan Redridge Mountains skakas av gnollernas och Blackrock-orchernas attacker fortgår vardagens små gester. Darcy, servitris på värdshuset i Lakeshire, packar den här näringsrika måltiden åt Guard Parker, som patrullerar den oskyddade vägen söderut mot Duskwood. Redridges garnison är hårt ansträngd och isolerad från Stormwinds hjälp, så enskilda vakter måste hålla långa, ensamma vakter. Att leverera paketet mättar inte bara en vaktpost, utan inleder också en långvarig, blygsam uppvaktning mellan de två stadsborna."}},faq={{q="Vem lagade Parker's Lunch?",a="Måltiden lagades av Darcy, en servitris på värdshuset i Lakeshire. Hon oroar sig för Guard Parker när han är ute på farlig patrull och förlitar sig på resande äventyrare för att leverera den säkert till honom.",al={"vem lagade parker's lunch","vem gav mig parker's lunch","darcy redridge måltid"}},{q="Var hittar man Guard Parker?",a="Guard Parker patrullerar den stora grusvägen som går sydväst från Lakeshire mot gränsen till Duskwood. Han går fram och tillbaka längs vägen och håller utkik efter kringströvande gnoller.",al={"guard parker plats","var är guard parker","hitta guard parker"}},{q="Vad gör Guard Parker efter att ha fått sin måltid?",a="Parker blir djupt rörd av Darcys omtanke. Tacksam över den varma maten under sin svåra patrull söker han snart ett sätt att återgälda hennes vänlighet och ber om hjälp med att skicka färska påskliljor från örtkunniga.",al={"uppföljning på parker's lunch","darcy och parker","parkers reaktion på måltiden"}},{q="Varför levererar inte Darcy måltiden själv?",a="Vägarna utanför Lakeshire kryllar av aggressiva Redridge-gnoller och Blackrock-invaderare. Guard Parker har stridsträning och rustning som hjälper honom att överleva patrulleringen, men vanliga stadsbor som Darcy kan inte tryggt riskera färden ensamma.",al={"varför kan inte darcy ta med den","varför leverera måltid i redridge"}}},fx={["2351e721"]={q="Vad är Parker's Lunch?",a="Parker's Lunch är en färdigpackad måltid som Darcy, en värdshusvärds assistent i Lakeshire, har gjort i ordning. Hon packade den särskilt för att ge Guard Parker kraft, eftersom han tillbringar långa och utmattande timmar med att patrullera de förrädiska vägarna söderut mot Duskwood.",al={"vad är parkers lunch","föremålet parkers lunch"}},b73a829b={q="Varför måste Guard Parker få sin lunch levererad?",a="Guard Parker är stationerad långt från Lakeshires relativa trygghet och håller vakt mot kringströvande gnoller och Blackrock-orcher längs gränsvägen. Eftersom han inte kan lämna sin post för att återvända till värdshuset är han beroende av vänliga stadsbor som Darcy och förbipasserande resenärer för att få mat under tjänstgöringen.",al={"varför leverera parkers lunch","varför vill parker ha lunch","varför behöver guard parker lunch"}}},fp="14,154,19.382.0,28.143.0,32.148.0,52.147.1,44.158.0"}
P.entries["item:partially-filled-vessel"] = {n="Partially Filled Vessel",s="Partially Filled Vessel är en förtrollad behållare som används för att transportera välsignat månbrunnsvatten över Teldrassil. Tenaron Stormgrip i Aldrassil ger den till unga Night Elf-noviser, och i den bärs vatten från Shadowglen mot bosättningen Dolanaar.",h="Partially Filled Vessel är en förtrollad behållare som används för att transportera välsignat månbrunnsvatten...",kw={"aldrassil","corithras moonrage","crown of the earth","dolanaar","månbrunn","partially filled vessel","shadowglen","tenaron stormgrip","behållare"},ang={["class:Druid"]="Att transportera det helgade vattnet är en viktig plikt i tjänst hos Cenarion Circles pågående arbete med att vårda och undersöka världsträdets hälsa.",["race:NightElf"]="Att bära den här behållaren är en övergångsrit som för unga Night Elf bort från Shadowglens fristad och in i det större ansvaret att vårda Teldrassil."},sec={{t="En helig leverans",b="Bland Aldrassils grenar samlar kaldorei-noviser välsignat vatten från Shadowglens avskilda månbrunn. Tenaron Stormgrip häller det rena provet i den särskilda behållaren och förbereder den för färden över världsträdet. Behållaren är bara delvis fylld eftersom färden just har börjat; till slut måste mer heligt vatten samlas från olika delar av Teldrassil för att vårda öns hälsa."},{t="Vidare till Dolanaar",b="För att bära behållaren måste du färdas söderut genom dalens portar och följa kullerstensvägarna västerut till Dolanaar. Färden markerar en ung äventyrares avfärd från Shadowglens skyddade barnkammare ut i Teldrassils vidsträckta vildmarker. Vid månbrunnen mitt i Dolanaar tar Corithras Moonrage hand om behållaren och leder ritualens nästa fas."}},faq={{q="Vad finns i behållaren?",a="Den innehåller rent månbrunnsvatten från den heliga källan i Shadowglen, som druiden Tenaron Stormgrip hällde i behållaren.",al={"vad finns i behållaren","behållarens innehåll","vilket vatten finns i den"}},{q="Varför är den bara delvis fylld?",a="Månbrunnen i Shadowglen ger bara det första provet. Arbetet med att vårda Teldrassil kräver att vatten samlas från flera månbrunnar runt om i trädet innan behållaren är full.",al={"varför bara delvis fylld","varför är den inte full"}},{q="Vem ska jag lämna behållaren till?",a="Bär behållaren söderut ut ur Shadowglen och följ kullerstensvägen västerut till Dolanaar. Lämna den där till Corithras Moonrage, som vårdar stadens månbrunn.",al={"vem får behållaren","var ska jag lämna den","lämna in behållaren"}},{q="Varför transporteras månbrunnsvatten runt Teldrassil?",a="Druiderna och prästinnorna vakar över och ger näring åt Teldrassil genom månbrunnarnas vatten. Genom att transportera vatten mellan brunnarna bevaras deras välsignelser bland det nyvuxna världsträdets plågade grenar.",al={"varför transportera månbrunnsvatten","vattnets syfte","varför flytta vatten"}}},fx={["5f4a3df1"]={q="Vad är Partially Filled Vessel?",a="Partially Filled Vessel är en förtrollad behållare som Night Elf-druider använder för att samla in och transportera Teldrassils månkällors heliga vatten. När Tenaron Stormgrip skickar iväg dig från Shadowglen häller han det välsignade månkällsvatten du samlat i den här behållaren, så att det heliga arbetet kan fortsätta bland världsträdets grenar.",al={"historien bakom partially filled vessel","vad är det här för behållare","vad är partially filled vessel"}},["4f920d4c"]={q="Varifrån kommer Partially Filled Vessel och vem gjorde den?",a="Tenaron Stormgrip, en av de äldre druiderna som är stationerade högst upp i Aldrassil i Shadowglen, ger dig behållaren. När du har hämtat vatten från Shadowglens månkällor häller Tenaron din flaska i behållaren och påbörjar insamlingen. Han anförtror dig att föra den vidare ut i Teldrassils vidsträckta områden.",al={"vem gjorde behållaren","varifrån kom behållaren","behållarens ursprung"}},["089d2d88"]={q="Varför vill Corithras Moonrage ha Partially Filled Vessel?",a="Corithras Moonrage väntar på behållaren vid månkällan i Dolanaar för att fortsätta en viktig druidsyssla som kallas Crown of the Earth. Att samla in Teldrassils vatten är nödvändigt för att inspektera och vårda det unga världsträdet. Corithras behöver vattnet du hämtade från Aldrassil innan han kan visa dig nästa steg i ritualen.",al={"varför vill corithras ha den","varför ta behållaren till dolanaar","varför ta behållaren till corithras"}}},fp="23,159,17.262.0,18.309.0,26.93.0,32.142.0,29.159.0,52.198.0"}
P.entries["item:paw-of-sin-dall"] = {n="Paw of Sin'Dall",s="Ajeck Rouack ber dig spåra Sin'Dall, en svårfångad tiger i Stranglethorn Vale, och återvända med bevis på jakten.",h="Ajeck Rouack ber dig spåra Sin'Dall, en svårfångad tiger i Stranglethorn Vale, och återvända med bevis på...",kw={"ajeck rouack","nesingwary's expedition","paw of sin'dall","sin'dall","stranglethorn vale","tiger","tigerjaktens mästare"},ang={["class:Hunter"]="Som jägare får du en utmaning av Ajeck Rouack: spåra och döda Sin'Dall och sedan återvända med bevis på jakten."},sec={{t="Bevis på jakten",b="Vid Nesingwary's Expedition skickar Ajeck Rouack dig efter Sin'Dall, en svårfångad tiger som spårats i flera veckor. Han ber dig återvända med hennes tass som bevis på jakten. Ta med den tillbaka, så kommer han att hylla dig som en sann mästare på tigerjakt."}},faq={{q="Vem är Sin'Dall?",a="Sin'Dall är en svårfångad tiger i Stranglethorn Vale, jagad av Ajeck Rouack och spårarna vid Nesingwary's Expedition.",al={"sin'dall tiger","vem är sin'dall"}},{q="Varför vill Ajeck ha Sin'Dalls tass?",a="Ajeck Rouack ber dig ta med Sin'Dalls tass som bevis på att du jagade och dödade henne.",al={"tass som bevis","varför tassen"}},{q="Vart ska jag ta Paw of Sin'Dall?",a="Ta Paw of Sin'Dall till Ajeck Rouack vid Nesingwary's Expedition.",al={"vart tassen ska","ajeck rouacks tass"}},{q="Vad bevisar tassen?",a="Tassen bevisar för Ajeck Rouack att du slutförde jakten på Sin'Dall.",al={"tassens betydelse","sin'dall bevis"}}},fp="15,114,17.225.0,16.119.0,35.86.1,36.69.0,24.72.1"}
P.entries["item:pendant-of-shadow"] = {n="Pendant of Shadow",s="Pendant of Shadow är en mörk talisman som bärs av den avfällige häxmästaren Morganth högst upp i Tower of Ilgalar i Redridge Mountains. När den förs till magikern Theocritus i Tower of Azora blir den ett obestridligt bevis på att den förrädiske besvärjaren har undanröjts innan hans ondskefulla planer kunde bära frukt.",h="Pendant of Shadow är en mörk talisman som bärs av den avfällige häxmästaren Morganth högst upp i Tower of...",kw={"morganth","pendant of shadow","redridge","scythe of elune","theocritus","tower of azora","tower of ilgalar"},ang={["class:Mage"]="Att återta den mörka talismanen på Theocritus uppdrag visar vilket ständigt ansvar magiker har att hålla vårdslösa, avfälliga besvärjare som hotar riket under uppsikt.",["class:Warlock"]="Morganth visar hur farligt det är att dra till sig för mycket uppmärksamhet från Tower of Azora när man söker efter oberäkneliga, förbjudna artefakter som Scythe of Elune."},sec={{t="En mörk häxmästares tecken",b="Pendant of Shadow, som den förrädiske häxmästaren Morganth håller i sitt näste i Tower of Ilgalar, är genomsyrad av mörk trolldom. Morganth försökte avslöja hemligheterna bakom Scythe of Elune, en uråldrig relik med enorm och oberäknelig kraft. Magikern Theocritus fruktade den förödelse häxmästaren kunde släppa lös över Redridge Mountains och kungariket Stormwind. Därför gav han äventyrare i uppdrag att infiltrera Ilgalar, sätta stopp för Morganths planer och ta talismanen ur hans händer som bevis på hans död."}},faq={{q="Var hittar jag Pendant of Shadow?",a="Häxmästaren Morganth bär på hänget. Han håller till allra högst upp i Tower of Ilgalar i nordöstra Redridge Mountains.",al={"pendant of shadow plats","var finns pendant of shadow","hur får man pendant of shadow"}},{q="Vem vill ha Pendant of Shadow?",a="Talismanen ska lämnas till magikern Theocritus, som håller till i Tower of Azora i östra Elwynn Forest.",al={"vem tar pendant of shadow","lämna in pendant of shadow","theocritus pendant"}},{q="Varför behöver Theocritus hänget?",a="Theocritus behöver hänget som ett konkret bevis på att Morganth har dödats och att hans jakt på den farliga Scythe of Elune har upphört.",al={"varför theocritus vill ha den","syftet med pendant of shadow"}},{q="Vilket hot utgjorde Morganth med hänget?",a="Morganth letade efter den svårfunna Scythe of Elune. Theocritus fruktade att om den mörke häxmästaren fick tag på artefakten skulle han släppa lös katastrofala krafter över Redridge och det omgivande kungariket.",al={"vad gjorde morganth","morganths historia"}}},fx={d0e37f9a={q="Vad är Pendant of Shadow?",a="Pendant of Shadow är en mörk talisman som bärs av den avfällige trollkarlen Morganth högst upp i Tower of Ilgalar i Redridge Mountains. Hänget är direkt knutet till Morganths ondskefulla planer och mörka konster. Det fungerar som bevis på hans nederlag för magikern Theocritus, som fruktar den förödelse Morganth skulle kunna släppa lös över Stormwind om han inte stoppas.",al={"vad är pendant of shadow","historien bakom pendant of shadow","information om pendant of shadow"}}},fp="17,180,23.403.1,38.99.0,32.92.0,38.121.1,47.171.1"}
P.entries["item:pendant-of-the-sea-lion"] = {n="Pendant of the Sea Lion",s="Pendant of the Sea Lion är en helig druidisk talisman som förenar smidighet i vatten med uthållighet. Den sätts samman vid Shrine of Remulos i Moonglade och visar att en novis är redo att bemästra sin vattenform.",h="Pendant of the Sea Lion är en helig druidisk talisman som förenar smidighet i vatten med uthållighet.",kw={"vattenform","dendrite starblaze","mathrengyl bearwalker","moonglade","pendant of the sea lion","remulos","turak runetotem"},ang={["class:Druid"]="Att sätta samman den här talismanen är en viktig milstolpe i en druids träning. Då låses förmågan upp att andas under vatten och simma med sjölejonets obehindrade fart.",["race:Tauren"]="För Shu'halo som vandrar på Cenarion Circles stig hedrar återlämnandet av hänget till Turak Runetotem både förfäderna och Moonglades läror."},sec={{t="En gåva från djupet",b="För att göra anspråk på sjölejonets vattenaspekt måste en druid visa att hen kan bemästra vattnets största faror. Hänget skapas genom att två olika halvor återfinns: den ena står för smidigheten som krävs för att glida förbi rovdjur i vattnet, den andra ger uthålligheten som behövs för att klara långvariga dyk. De två delarna förs till Shrine of Remulos i Moonglade och fogas samman till en helhet."},{t="Bevis på mästerskap",b="När hänget har smitts förs det färdiga hänget till äldre mentorer, som Turak Runetotem på de höga Elder Rise i Thunder Bluff eller Mathrengyl Bearwalker i Darnassus. Talismanen är ett obestridligt bevis på novisens prövningar under Dendrite Starblaze och ger de äldre rätt att lära ut hemligheterna bakom att skifta till en vattenform."}},faq={{q="Vad är syftet med Pendant of the Sea Lion?",a="Det visar att en druidnovis har klarat prövningarna i smidighet och uthållighet i vatten och är redo att lära sig sin vattenform.",al={"vad gör pendant of the sea lion","användning av sjölejonshänget","varför skaffa pendant of the sea lion"}},{q="Var sätts hänget samman?",a="De två halvorna, som står för smidighet och uthållighet, måste fogas samman vid Shrine of Remulos i den heliga fristaden Moonglade.",al={"hur tillverka sjölejonshänget","var förena hängets halvor"}},{q="Vem ska jag lämna hänget till i Thunder Bluff?",a="Taurendruider lämnar det färdiga hänget till Turak Runetotem på Elder Rise i Thunder Bluff för att slutföra sin träning.",al={"vem tar emot hänget i thunder bluff","turak runetotem hänge","lämna in vattenform för horden"}},{q="Kan nattalver också få det här hänget?",a="Ja. Nattalvdruider genomgår samma prövning i Moonglade, men tar i stället sitt ihopsatta hänge till Mathrengyl Bearwalker i Darnassus.",al={"alliansens sjölejonshänge","sjölejonshänge darnassus"}}},fx={["203d1c94"]={q="Vad är Pendant of the Sea Lion?",a="Pendant of the Sea Lion är en helig druidisk talisman som symboliserar herravälde över vattnet. Den står för den smidighet som krävs för att undvika farliga vattenrovdjur och den stora uthållighet som behövs för att stanna under ytan utan att komma upp. Druider bär denna förenade relik som ett konkret bevis på att de förstår naturens vilda balans innan de antar en vattenform.",al={"vad är pendant of the sea lion","information om sea lion-hänget","historien bakom sea lion-hänget"}},ad633d46={q="Varifrån kommer Pendant of the Sea Lion och vem gjorde den?",a="Unga druider som genomgår Trial of the Sea Lion smider talismanen. Den skapas genom att två separata delar hämtas från prövningens platser: Half Pendant of Aquatic Agility och Half Pendant of Aquatic Endurance. Delarna förs samman framför Shrine of Remulos i Moonglade, där aspekterna förenas till ett enda heligt emblem.",al={"vem gjorde pendant of the sea lion","sea lion-hängets ursprung","hur skapas pendant of the sea lion"}},["384283bf"]={q="Varför vill någon ha Pendant of the Sea Lion?",a="Druidernas mentorer kräver att få se det färdiga hänget som ett obestridligt bevis på din träning. I Thunder Bluff behöver Turak Runetotem medaljongen för att bekräfta att du klarat prövningarna i Moonglade innan han förmedlar vattenformens hemligheter. Dendrite Starblaze i Moonglade granskar också den förenade reliken för att bekräfta att prövningen är avklarad.",al={"varför vill någon ha pendant of the sea lion","vem vill ha sea lion-hänget","varför visa pendant of the sea lion"}}},fp="23,154,19.299.0,16.307.0,51.119.0,31.128.0,49.89.0,39.130.0"}
P.entries["item:perenolde-tiara"] = {n="Perenolde Tiara",s="I Ruins of Alterac har ett smycke från familjen Perenolde, prytt med smaragder, dykt upp igen. Dvärghantverkare i Ironforge tillverkade det, och samlare i Stormwind söker det nu.",h="I Ruins of Alterac har ett smycke från familjen Perenolde, prytt med smaragder, dykt upp igen.",kw={"alterac","smaragder","grel'borg","ironforge","girigbuk","perenolde","remington","ridgewell","tiara"},ang={["faction:Alliance"]="Som medlem av Alliansen möter du en bitter påminnelse om huset Perenolde, vars förräderi under andra kriget nästan förstörde Lordaerons ursprungliga allians.",["race:Dwarf"]="Som dvärg kan du se Ironforges ädelstenshantverk i smaragderna som stadens mästersmyckesmeder slipade och infattade åt nordens mänskliga kungligheter."},sec={{t="En relik från ett förlorat kungarike",b="Familjen Perenolde styrde Alterac innan kungariket föll under andra kriget. Bland deras skatter fanns en utsökt tiara, tillverkad av mästersmyckesmeder i Ironforge och prydd med lysande smaragder. När kung Aiden Perenoldes förräderi ledde till Alteracs undergång försvann tiaran i förödelsen bland de höga klipporna."},{t="Den giriges pris",b="Grel'borg the Miser, en ogremagiker, grävde fram tiaran när han letade efter övergivna rikedomar i Alteracs ruiner. Ryktet om den bevarade reliken nådde Count Remington Ridgewell, en förmögen adelsman i Stormwind som samlar berömda reliker till familjens museum. Nu försöker greven ta tiaran från ogret."}},faq={{q="Vad är Perenolde Tiara?",a="Perenolde Tiara är ett arvegods från Alteracs kungliga familj Perenolde. Dvärgsmyckesmeder i Ironforge tillverkade den och prydde den med smaragder innan den gick förlorad när kungariket föll.",al={"perenolde tiara berättelse","vad är den här tiaran","alteracs tiara"}},{q="Vem har tiaran nu?",a="Grel'borg the Miser, en ogremagiker, hittade tiaran bland Alteracs snötäckta ruiner. Han vaktar den medan han letar efter fler skatter i det förstörda kungariket.",al={"var finns tiaran","vem släpper tiaran","grel'borg tiara"}},{q="Varför vill Count Remington Ridgewell ha den?",a="Count Remington Ridgewell samlar historiska och prestigefyllda antikviteter till familjens museum i Stormwind. Han vill ha tiaran som en kronjuvel från ett fallit människokungarike.",al={"vem vill ha tiaran","varför vill remington ha den","remington ridgewells motiv"}},{q="Vilka var familjen Perenolde?",a="Familjen Perenolde styrde kungariket Alterac. Under andra kriget förrådde kung Aiden Perenolde Alliansen och gick över till orchernas hord, och hans rike föll i ruiner.",al={"familjen perenolde","huset perenolde","alteracs härskare"}}},fx={da959daa={q="Varifrån kommer Perenolde Tiara och vem gjorde den?",a="Diademet kommer från det förstörda nordliga kungariket Alterac, där det var ett högt skattat släktklenod i den kungliga ätten Perenolde. Det sägs inte ha smitts av mänskliga hantverkare, utan ha tillverkats av mästerliga dvärgsmyckare i Ironforge, som prydde det utsirade smycket med de finaste smaragderna.",al={"vem gjorde perenolde tiara","perenolde tiaras ursprung","var smiddes diademet"}}},fp="15,167,27.319.0,17.295.0,28.187.0,28.152.0,43.172.0,24.161.0"}
P.entries["item:pestlezugg-s-un-goro-report"] = {n="Pestlezugg's Un'Goro Report",s="Pestlezuggs Un'Goro-rapport förmedlar hans senaste rön från Gadgetzan till ledare i Darnassus eller Orgrimmar. Han hoppas att de tar hotet från silithiderna på allvar och hjälper till att bekämpa det.",h="Pestlezuggs Un'Goro-rapport förmedlar hans senaste rön från Gadgetzan till ledare i Darnassus eller Orgrimmar.",kw={"lugnet före stormen","darnassus","gadgetzan","gracina spiritmight","orgrimmar","pestlezugg","silithid","un'goro-rapport","zilzibin drumlore"},ang={["faction:Alliance"]="Som resenär för Alliance för du Pestlezuggs varning till Gracina Spiritmight i Darnassus, där hon hoppas att ledarna tar hotet från silithiderna på allvar.",["faction:Horde"]="Som resenär för Horde tar du Pestlezuggs varning till Zilzibin Drumlore i Orgrimmar, i hopp om att Thrall får höra fakta."},sec={{t="En rapport från Gadgetzan",b="I Gadgetzan skickar Pestlezugg sina senaste rön om silithiderna till någon som kan nå ledarna. Rapporten går till Gracina Spiritmight vid Temple of the Moon i Darnassus eller till Zilzibin Drumlore i Orgrimmar. Pestlezugg tror att faran är för stor för att Gadgetzan ska kunna möta den på egen hand."},{t="Att hörsamma varningen",b="Pestlezugg fruktar att hatet mellan Alliance och Horde gör båda sidor blinda för hotet från silithiderna. Gracina säger att Alliance avfärdar faror som inte kommer från Horde, medan Hordes ledare är splittrade av motstridiga råd. Båda mottagarna uppmanar till fortsatta insatser mot silithiderna."}},faq={{q="Vem skrev rapporten?",a="Pestlezugg, som arbetar i Gadgetzan, skrev rapporten om sina senaste rön om silithiderna.",al={"vem är pestlezugg","pestlezuggs rapport","rapportens författare"}},{q="Vad står det i Pestlezuggs rapport?",a="Rapporten innehåller Pestlezuggs senaste rön om hotet från silithiderna.",al={"vad står det i rapporten","silithidrapport","rapportens innehåll"}},{q="Vart skickas rapporten?",a="Rapporten förs till Gracina Spiritmight vid Temple of the Moon i Darnassus eller till Zilzibin Drumlore i Orgrimmar.",al={"vart ska rapporten","rapportens destination","vart skickas den"}},{q="Varför skickar Pestlezugg den?",a="Pestlezugg tror inte att Gadgetzan kan möta hotet från silithiderna på egen hand och hoppas att ledarna kan agera utifrån hans rön.",al={"varför skicka rapporten","varför behöver pestlezugg hjälp","gadgetzan behöver hjälp"}},{q="Vad tycker Gracina om varningen?",a="Gracina säger att Alliance förbiser hot som inte kommer från Horde, och hon uppmanar till fortsatta insatser mot silithiderna.",al={"gracina om silithiderna","alliance svar","varför ignorerar alliance hotet"}},{q="Hur reagerar Horde?",a="Zilzibin säger att Horde distraheras av motstridiga råd, men han tror att Thrall kanske skulle agera om fakta nådde honom.",al={"hordes svar","thrall och silithiderna","zilzibins rapport"}}},fp="27,174,23.300.0,19.299.1,21.95.0,31.71.0,25.122.0,28.110.0,39.129.0,27.122.0"}
P.entries["item:phial-of-scrying"] = {n="Phial of Scrying",s="Phial of Scrying är ett förtrollat kärl som tillhandahålls av den uråldrige lärde Onu i Darkshore. När det används frammanar det en spådomsskål som möjliggör kontakt på avstånd genom de fördärvade skogarna.",h="Phial of Scrying är ett förtrollat kärl som tillhandahålls av den uråldrige lärde Onu i Darkshore.",kw={"darkshore","the master's glaive","onu","phial of scrying","spådomsskål","twilight's hammer"},ang={["class:Druid"]="Druider känner igen spådomsskålar som en harmonisk blandning av naturligt vatten och kontaktmagi, som låter skogens väktare utbyta viskningar över fördärvad mark.",["race:NightElf"]="För nattalverna i Darkshore är uråldriga spådomsredskap som spådomsvatten oumbärliga för att hålla vakt över heliga skogar som invaderats av främmande kulter."},sec={{t="En lins över Darkshore",b="Phial of Scrying anförtros åt spejare som undersöker Darkshore på djupet. Den innehåller mystiska vatten som frammanar en tillfällig spådomsskål på marken. Detta verktyg möjliggör spådom på långa avstånd, så att resande som beger sig in i farliga områden som Master's Glaive kan tala direkt med Onu utan att genast behöva återvända till hans lund."},{t="Kulten avslöjas",b="Onu tillhandahåller flaskan särskilt för att övervaka den oroande närvaron av kultister från Twilight's Hammer. Genom att upprätta en spådomslänk på platsen där den uråldrige fallne mästaren spetsades av en väldig glaive, bekräftar spejaren att mörka kultister samlas kring de uråldriga kvarlevorna och söker efter skärvor av glömd kraft som dröjer kvar även efter döden."}},faq={{q="Vad gör Phial of Scrying?",a="När flaskan öppnas frammanar den en magisk spådomsskål på marken, så att en äventyrare ute i fält kan kontakta och tala med den uråldrige lärde Onu över stora avstånd.",al={"använd phial of scrying","spådomsskålens funktion","vad används flaskan till"}},{q="Vem tillhandahåller Phial of Scrying?",a="Den uråldrige trädmannen Onu anförtror flaskan åt spejare i Darkshore när han ber dem rekognoscera Master's Glaive i söder.",al={"vem ger phial of scrying","var får jag flaskan"}},{q="Vad händer om flaskan försvinner eller tar slut?",a="Om flaskan försvinner eller används innan du har slutfört ditt uppdrag kan Onu ge dig en ny medan han mediterar i Darkshore.",al={"förlorad phial of scrying","få en ny flaska","ersätta flaskan"}},{q="Varför skådar Onu in i Master's Glaive?",a="Onu vet att det var vid Master's Glaive som en gammal härskare föll och ber dig leta efter kultister från Twilight's Hammer där. Deras syfte avslöjas allt eftersom undersökningen fortsätter.",al={"varför skåda in i master's glaive","onus uppdrag vid glaive"}}},fx={["92e56a99"]={q="Vad är Phial of Scrying?",a="Phial of Scrying är en förtrollad behållare med mystiskt vatten från den uråldrige kunskapsväktaren Onu. När du häller ut vattnet ute i fält skapas en tillfällig skådningsskål som fungerar som en magisk förbindelse. Den låter dig upprätta en direkt andlig kontakt med den uråldrige över väldiga avstånd.",al={"vad är phial of scrying","historien bakom phial of scrying","förklaring av scrying-flaskan"}},["16c85a4e"]={q="Varför vill Onu att du använder Phial of Scrying?",a="Onu ber dig söka igenom Master's Glaive efter medlemmar i kulten Twilight's Hammer. Flaskan låter dig skapa en skådningsskål och tala med honom efter att du genomsökt platsen, utan att först återvända till hans lund.",al={"varför använda phial of scrying","varför vill onu ha flaskan","varför behövs phial of scrying"}}},fp="16,173,23.242.0,19.313.1,34.155.0,34.122.0,47.120.0,44.171.0"}
P.entries["item:piece-of-krom-zar-s-banner"] = {n="Piece of Krom'zar's Banner",s="Vid Regthar Deathgates bunker väster om The Crossroads markerar en trasig fana det misslyckade anfallet. Warlord Krom'zar ledde Kolkars vedergällningsstyrka från Desolace.",h="Vid Regthar Deathgates bunker väster om The Crossroads markerar en trasig fana det misslyckade anfallet.",kw={"baner","kentaur","motanfall","crossroads","deathgate","kolkar","krom'zar","regthar"},ang={["faction:Horde"]="Att besegra Krom'zar och ta hans baner stoppar en stor centauroffensiv. De norra vägarna mellan Durotar, Mulgore och The Crossroads är säkra.",["race:Tauren"]="Som tauren vet du att centaurernas aggression länge har plågat de nomadiska stammarna. Krom'zars förtrupp är förintad, och stigarna mot Mulgore är tryggare."},sec={{t="Trofé från kentaurernas anfall",b="Warlord Krom'zar ledde ett krigsband österut från Desolace för att slå tillbaka. Kolkarhövdingar över hela The Barrens hade fallit, och de rasande centaurerna anföll försvarsbunkrarna väster om The Crossroads. En remsa från Krom'zars fallna baner ger Regthar Deathgate bevis för att anfallet slogs tillbaka och att de södra handelsvägarna bevarades åt Horden."}},faq={{q="Vad används den här banerbiten till?",a="För den trasiga tygbiten till Regthar Deathgate vid hans bunker väster om The Crossroads. Den bevisar att Warlord Krom'zar dödades och att hans plundringsstyrka krossades, vilket avslutade försvaret av norra The Barrens.",al={"banerbitens syfte","varför behålla banerbiten","vad gör jag med banerbiten"}},{q="Vem var krigshövding Krom'zar?",a="Krom'zar var en Kolkarbefälhavare från Desolace. Han ledde en direkt motattack mot Hordens utposter efter att lokala Kolkarledare dödats.",al={"vem är kromzar","krom'zar i historien","krigshövding krom'zar"}},{q="Varför anföll Kolkar bunkern?",a="Efter att Barak, Verog, Hezrul och de andra lokala hövdingarna fallit samlade de rasande centaurerna förstärkningar från Desolace för att hämnas på Hordens närvaro väster om The Crossroads.",al={"varför motanfall","varför kolkar-invasionen","orsak till motanfallet i barrens"}},{q="Får Thrall höra om segern?",a="Ja. Regthar Deathgate lovar att skicka besked direkt till Warchief Thrall i Orgrimmar och hylla försvararna som slog tillbaka invasionen.",al={"thralls belöning","vet thrall om det"}}},fx={["92115071"]={q="Vad är Piece of Krom'zar's Banner?",a="Det är en avsliten bit från krigsbaneret som tillhör krigsherren Krom'zar, befälhavare för den hämndlystna Kolkar-centaurarmé som marscherade från Desolace in i The Barrens. För Hordens styrkor som försvarar de västra bunkrarna är den ett obestridligt fysiskt bevis på att krigsherren fallit i strid och att invasionen har brutits.",al={"vad är piece of kromzars banner","kromzars banerbit","vad är banerfragmentet"}},caa193f6={q="Varifrån kommer Piece of Krom'zar's Banner?",a="Krigsherren Krom'zar och hans Kolkar-här bar baneret in i The Barrens. De hade färdats hela vägen från sitt hemland i Desolace för att hämnas på Horden. När Krom'zar drar ut i strid utanför de västra bunkrarna och stupar, blir baneret kvar på slagfältet, där den här biten kan rivas loss.",al={"varifrån kom kromzars baner","vem gjorde kromzars baner","kromzars baners ursprung"}},["7a980ed6"]={q="Varför vill Regthar Deathgate ha en Piece of Krom'zar's Banner?",a="Regthar Deathgate behöver konkreta bevis på att den invaderande Kolkar-armén har krossats avgörande. Den avslitna banerbiten bekräftar att krigsherren Krom'zar dödades framför Hordens bunkrar. Då kan Regthar officiellt förklara invasionen över och sända bud om ditt hjältemod direkt till krigshövding Thrall.",al={"varför vill regthar ha baneret","varför ta kromzars baner till regthar","varför behövs kromzars baner"}}},fp="26,163,31.357.0,35.193.0,25.140.0,37.197.0,33.139.0"}
P.entries["item:plainstrider-beak"] = {n="Plainstrider Beak",s="Över The Barrens tar jägare med sig Plainstrider-näbbar tillbaka till The Crossroads. Jaktledare använder dem som bevis på att fåglar som hotade de lokala förråden har gallrats ut.",h="Över The Barrens tar jägare med sig Plainstrider-näbbar tillbaka till The Crossroads.",kw={"barrens","crossroads","plainstrider beak","plainstrider-hotet","sergra darkthorn","tallstrider"},ang={["class:Hunter"]="Som jägare får du en tidig lektion i att smyga dig på och säkra byten över Kalimdors öppna slätter när du fäller plainstriders och samlar in deras näbbar.",["faction:Horde"]="Som medlem av Horde hjälper du till att skydda handels- och försörjningslederna som förser utposten när du gallrar ut de besvärliga flockarna öster om The Crossroads."},sec={{t="Ett mått på jakten",b="Plainstriders letar föda runt The Crossroads och hotar dess förråd. Större, snabbfotade och argsinta plainstriders strövar omkring på savannen i området. Sergra Darkthorn ber jägare som anländer att ta med deras näbbar som bevis på att flockarna har gallrats bort från försörjningslederna och förråden."}},faq={{q="Varför vill Sergra Darkthorn ha Plainstrider Beaks?",a="Sergra Darkthorn ber jägare att gallra ut plainstriders eftersom fåglarna stör matförråden runt The Crossroads. Deras näbbar visar att jakten har minskat hotet mot de lokala förråden.",al={"varför samla näbbar","sergra plainstrider beak uppdrag","varför näbbar"}},{q="Vilka varelser ger dessa näbbar?",a="Jägare tar näbbarna från större, snabbfotade och argsinta plainstriders som strövar omkring på savannen i The Barrens.",al={"vad släpper plainstrider beaks","källor till plainstrider beak","var får man tag på näbbar"}},{q="Varför ger inte alla plainstriders en näbb när de dödas?",a="I kampen kan snabba, sprattlande fåglar få en näbb som är sprucken, krossad eller obrukbar som rent jakttrofé. Jägare samlar bara in hela näbbar.",al={"varför så låg droppchans","plainstrider beak droppar inte"}}},fx={["7e2762f5"]={q="Vad är en Plainstrider Beak?",a="En Plainstrider Beak är näbben från de flygoförmögna, långbenta fåglar som strövar över The Barrens savann. Jägare samlar in de hårda och spetsiga näbbarna som konkret bevis på att de har gallrat ut de besvärliga fåglar som hotar de lokala förråden.",al={"föremålet plainstrider beak","vad är plainstrider beak","plainstrider-näbbar"}},["6978f6b2"]={q="Varifrån kommer en Plainstrider Beak?",a="Näbbarna kommer direkt från de olika raserna av slättlöpare i The Barrens, till exempel större, snabba och argsinta slättlöpare. Jägare tar dem som troféer och bevis på en lyckad gallring ute på de torra slätterna.",al={"var får man tag på plainstrider beak","vilka fiender släpper plainstrider beak","plainstrider beaks källa"}}},fp="17,120,21.282.0,50.177.0,34.101.0,54.148.0"}
P.entries["item:plainstrider-feather"] = {n="Plainstrider Feather",s="Fjädrar från de snabba fåglarna som strövar över Mulgore-slätterna är viktiga material som unga jägare samlar på Red Cloud Mesa. Taurerna i Camp Narache använder dem främst till kläder och stamprydnader och hedrar samtidigt varelserna som försörjer byn.",h="Fjädrar från de snabba fåglarna som strövar över Mulgore-slätterna är viktiga material som unga jägare samlar...",kw={"camp narache","fjäder","grull hawkwind","mulgore","plainstrider","red cloud mesa","jakten börjar"},ang={["class:Hunter"]="Att smyga sig på snabba plainstriders över Red Cloud Mesa ger en invigd ett första prov i tålamod, spårning och respekt för bytet.",["race:Tauren"]="För en ung taur är det en viktig första läxa att samla fjädrar från en plainstrider och förstå att inget från Jordmodernas varelser får tas för givet. Varje del av bytet används till mat och kläder."},sec={{t="En jägares första offergåva",b="På Red Cloud Mesa lär sig unga taur tidigt att överlevnad kräver skarp spårningsförmåga och jakt. Plainstriders springer fritt över den gräsbevuxna platån och ger både mat och användbara material. När de plockar deras tåliga fjädrar kan lägret tillverka traditionella kläder och utrustning. Att överlämna fjädrarna tillsammans med färskt kött till Grull Hawkwind visar respekt för stammens behov och är det allra första provet på vägen mot att erkännas av Chief Hawkwind och välkomnas till Thunder Bluff."}},faq={{q="Vad används Plainstrider Feathers till?",a="Taurerna i Camp Narache använder dem främst till kläder och ceremoniella föremål. Grull Hawkwind samlar in dem från oerfarna jägare för att fylla på stammens förråd.",al={"fjädrarnas syfte","användning av plainstriderfjädrar","varför samla fjädrar"}},{q="Vem samlar Plainstrider Feathers på Red Cloud Mesa?",a="Grull Hawkwind ber om dem på Camp Naraches vägnar för att fylla på byns förråd och pröva om de unga jägarna har den disciplin som krävs för att försörja stammen.",al={"vem vill ha fjädrar","vem behöver fjädrar","grull hawkwinds fjädrar"}},{q="Var finns plainstriders?",a="De strövar över de öppna grässlätterna på Red Cloud Mesa och genom hela The Rolling Plains i Mulgore.",al={"var plainstriders finns","plainstriders plats","fjäderfarm"}},{q="Varför behöver Grull Hawkwind dessa fjädrar till stamriterna?",a="Jakt är en hörnsten i taurkulturen och bedrivs både för överlevnad och nöjes skull. Att återvända med kött och fjäderdräkt visar Chief Hawkwind att en invigd kan försörja stammen innan färden fortsätter till Thunder Bluff.",al={"jakten börjar berättelse","taurernas prövningsjakt","varför jaga plainstriders"}}},fx={f2ff74a3={q="Vad är en Plainstrider Feather?",a="En Plainstrider Feather är en fjäder från de stora, flygoförmögna fåglar som vandrar över Mulgore gräsmarker. Tauren på Red Cloud Mesa tar vara på allt som skördas från jorden, med stor respekt. De stadiga, färggranna fjädrarna används både som praktiskt material till vardagskläder och som traditionella prydnader.",al={"vad är plainstrider feather","information om plainstrider feather","plainstrider-fjädrar"}},["8bb68bd8"]={q="Varifrån kommer Plainstrider Feathers?",a="Fjädrarna växer naturligt på de vilda slättlöpare som strövar kring Red Cloud Mesa och över de vidsträckta slätterna i Mulgore. De tillverkas inte av dödliga händer, utan samlas in av jägare efter en lyckad jakt på den öppna prärien.",al={"plainstrider feathers källa","var får man tag på plainstrider-fjädrar","vem gjorde plainstrider feather"}}},fp="20,225,25.400.0,40.153.0,52.186.0,33.85.0,64.179.0"}
P.entries["item:plainstrider-kidney"] = {n="Plainstrider Kidney",s="Över The Barrens samlar jägare in Plainstrider Kidney för Kalimdors ovanliga bryggtraditioner. Organet faller de flesta resenärer i smaken, men är nödvändigt för ett exotiskt bryggverk.",h="Över The Barrens samlar jägare in Plainstrider Kidney för Kalimdors ovanliga bryggtraditioner.",kw={"brewmaster drohn","chen stormstout","plainstrider","plainstrider kidney","ratchet","stormstout","the barrens"},ang={["class:Hunter"]="Som jägare måste du ta ur plainstriders varsamt över savannen, så att deras inre organ förblir intakta inför bytet med bryggmästarna i Ratchet.",["profession:Cooking"]="Som kock kanske du ryggar tillbaka inför tanken på att jäsa fågelnjurar till fin sprit. I Kalimdors vildmark innebär överlevnad ofta att ta tillvara på varje del av bytet."},sec={{t="En okonventionell bryggingrediens",b="The Barrens vidsträckta, torra slätter är hem åt höga, flygoförmögna plainstriders. Jägare tar ofta deras fjädrar och kött till verktyg och enkla måltider, medan Brewmaster Drohn i Ratchet söker deras inälvor av ett annat skäl. Drohn säger att plainstrider-njurar behövs för att återskapa Chen Stormstouts legendariskt starka ale. Han hävdar att njurarna ger brygden en unik kick, enligt en tradition som förts vidare genom en okonventionell rad bryggmästare."}},faq={{q="Vad används en Plainstrider Kidney till?",a="Brewmaster Drohn i Ratchet behöver plainstrider-njurar för att återskapa en legendarisk sats Stormstout-ale. Han säger att hans mentor lärde sig receptet direkt av Chen Stormstout, den kringvandrande pandarenbryggmästaren.",al={"användning av plainstrider kidney","varför behöver jag plainstrider-njurar","syftet med plainstrider kidney"}},{q="Varför skulle någon brygga öl med djurorgan?",a="Kalimdors exotiska brygder använder ofta delar från härdiga lokala vilda djur för att ge dem starka, minnesvärda smaker och en tydlig kick. Brewmaster Drohn säger att tillverkningen av sådana kraftiga, vilda brygder påminner honom om okonventionella skapelser som troggbrygd.",al={"njure i öl","varför njure i stormstout","djurdelar i alkohol"}},{q="Vilka varelser ger dessa njurar?",a="Flera arter plainstriders som springer över The Barrens ger dessa njurar, däribland fleeting, ornery och greater plainstriders.",al={"var får man plainstrider-njurar","vilka släpper plainstrider kidney","källa till plainstrider kidney"}},{q="Vilka andra ingredienser behövs tillsammans med njurarna?",a="Brewmaster Drohn ber om fem plainstrider-njurar, fem savannah lion-tänder och ett thunder lizard-horn för att färdigställa sin brygd.",al={"andra bryggingredienser","vad mer behöver drohn","stormstout-ingredienser"}}},fx={d14d143c={q="Vad är en Plainstrider Kidney?",a="Det är ett inre organ från de stora, flygoförmögna slättlöpare som strövar över The Barrens savanner. De flesta jägare kastar sådana inälvor eller lämnar dem till asätare, men vissa egendomliga bryggare uppskattar dem som potenta och ovanliga tillsatser i exotiska spritsorter.",al={"vad är plainstrider kidney","information om plainstrider kidney","berätta om plainstrider kidney"}},["4fd58422"]={q="Varifrån kommer Plainstrider Kidney?",a="Dessa organ tas direkt från de vilda plainstriders som hör hemma i The Barrens, däribland större, argsinta och snabba varianter. De är naturliga delar av fåglarnas anatomi, inte tillverkade varor, men för att få tag på ett måste du jaga de snabba och aggressiva fågeldjuren över slätterna.",al={"källa till plainstrider kidney","var får man tag på plainstrider kidney","plainstrider kidney ursprung"}},["53f4067b"]={q="Varför vill Brewmaster Drohn ha Plainstrider Kidney?",a="Brewmaster Drohn i Ratchet söker efter dessa njurar för att återskapa Chen Stormstouts legendariska och kraftfulla brygd, som bär hans namn. Chen förde vidare det okonventionella receptet till D्रोhns mentor, och Drohn behöver njurarna tillsammans med lejontänder och ett Thunder Lizard Horn för att brygga den mustiga ölen med dess karaktäristiska, kraftiga sting.",al={"varför behövs plainstrider kidneys","vem vill ha plainstrider kidneys","plainstrider kidney användning drohn"}}},fp="19,181,32.415.0,39.198.0,46.215.0,36.86.0,56.126.0"}
P.entries["item:plainstrider-meat"] = {n="Plainstrider Meat",s="Plainstrider Meat är färskt kött från de flygoförmögna fåglar som strövar omkring på Mulgore. För unga tauren som blir vuxna på Red Cloud Mesa är insamlingen både ett viktigt vinterförråd och en central övergångsrit.",h="Plainstrider Meat är färskt kött från de flygoförmögna fåglar som strövar omkring på Mulgore.",kw={"camp narache","chief hawkwind","grull hawkwind","mulgore","plainstrider","plainstrider meat","red cloud mesa","jakten börjar"},ang={["class:Hunter"]="Den snabba plainstridern ger unga jägare ett tidigt prov på deras spårningsförmåga och träffsäkerhet på Mulgore öppna slätter.",["race:Tauren"]="För taurenungdomar som ger sig ut på Red Cloud Mesa är jakten på plainstriders det första praktiska steget mot att vinna Chief Hawkwinds respekt och förtjäna rätten att gå in i Thunder Bluff."},sec={{t="Föda till mesan",b="Taurernas liv är oupplösligt knutet till landet, där vördnad för naturen balanseras mot överlevnadens praktiska krav. På Red Cloud Mesa är bosättningen Camp Narache starkt beroende av villebråd från de omgivande gräsmarkerna. Plainstrider-kött ger byn viktiga matförråd när lagren börjar sina, medan fåglarnas fjädrar används till kläder och ceremoniella utsmyckningar."},{t="En ung jägares prov",b="Att jaga plainstriders är ett av de första proven för ungdomar som vill vinna stammens respekt. Grull Hawkwind skickar blivande jägare att smyga sig på de snabba fåglarna över mesan och samla kött och fjädrar för att visa sin spårningsförmåga och självständighet innan de möter hans far, Chief Hawkwind."}},faq={{q="Vad används Plainstrider Meat till?",a="Unga jägare samlar Plainstrider Meat på Red Cloud Mesa för att fylla på Camp Naraches sinande matförråd, en viktig uppgift som Grull Hawkwind ger dem.",al={"varför plainstrider meat","plainstrider meat-uppdrag","vad gör jag med plainstrider meat"}},{q="Vem ber om köttet?",a="Grull Hawkwind, son till Chief Hawkwind, ber de invigda att jaga mesans plainstriders för att fylla på stammens matförråd och visa att de duger som försörjare.",al={"vem vill ha plainstrider meat","grull hawkwind kött"}},{q="Var hittar man Plainstrider Meat?",a="Det kommer från de flygoförmögna plainstriders som strövar omkring på Mulgore gräsmarker, särskilt bland Red Cloud Mesas böljande kullar.",al={"var hittar man plainstrider meat","plainstrider-platser","samla plainstrider meat"}},{q="Varför är det viktigt för taurerna att jaga plainstriders?",a="Taurerna jagar både av praktiska skäl och som en andlig disciplin. Att föra tillbaka villebråd till lägret visar vördnad för Jordmodern, självständighet och förmågan att försörja stammen.",al={"taurernas jaktkultur","varför jaga plainstriders"}}},fx={f404715e={q="Vad är Plainstrider Meat?",a="Plainstrider Meat är färskt viltkött från de flygoförmögna fåglar som strövar omkring på Mulgore-slätterna. För tauren på Red Cloud Mesa är det ett viktigt baslivsmedel, som samlas in genom traditionell jakt och håller bosättningen vid liv samtidigt som bandet mellan jägare och byte hedras.",al={"information om plainstrider meat","vad är plainstrider meat","historien om plainstrider meat"}},["00c8b7f8"]={q="Varifrån kommer Plainstrider Meat?",a="Plainstrider Meat kommer från de vilda plainstriders som hör hemma i Mulgore. Unga jägare får köttet direkt från djuren som strövar kring Red Cloud Mesa under sina första jaktriter för stammen.",al={"varifrån kommer plainstrider meat","plainstrider meat ursprung","hur får man tag på plainstrider meat"}},f1043112={q="Varför behövs Plainstrider Meat i Camp Narache?",a="Matförråden i Camp Narache börjar sina, och stammen förlitar sig på skicklig jakt för att fylla på dem. Grull Hawkwind ber unga jägare att samla Plainstrider Meat för att mätta byn och visa Chief Hawkwind vad de går för.",al={"varför behövs plainstrider meat","plainstrider meat användning","varför samla plainstrider meat"}}},fp="17,165,23.293.0,22.221.0,35.116.0,23.135.0,37.99.0,64.176.0"}
P.entries["item:plainstrider-scale"] = {n="Plainstrider Scale",s="En seg, tålig fjäll från tallstriders som strövar över Mulgore vidsträckta slätter. Det är en viktig ingrediens i ett traditionellt läkemedel som Maur Raincaller tillreder för att motverka en häftig infektion.",h="En seg, tålig fjäll från tallstriders som strövar över Mulgore vidsträckta slätter.",kw={"bloodhoof village","maur raincaller","mazzranache","mulgore","plainstrider","läkemedel","fjäll","tallstrider"},ang={["race:Tauren"]="Att samla läkemedel från markerna speglar de traditionella överlevnadskunskaper som unga jägare lär sig i Mulgore, där varje del av slätternas djurliv tas till vara för att försörja stammen."},sec={{t="En sällsynt ingrediens",b="Plainstriders är mest kända för sina mjuka fjädrar och magra kött, men deras kraftiga ben täcks av sega, skyddande fjäll. Fjällen står emot det karga busklandskapet och rovdjurens klor. Det krävs tålamod att hitta ett helt fjäll som duger till medicin, eftersom bara vissa plainstriders i Mulgore har fjäll som är tillräckligt fasta för att malas och användas i folkmedicin."},{t="Botemedel mot ett giftigt bett",b="När Maur Raincaller i Bloodhoof Village stötte på Mazzranache, en legendarisk strider känd för sina demoniskt röda ögon och sitt giftiga bett, fick han ett svårt sår i axeln. Maur har fallit i en omtöcknad feber och behöver ett Plainstrider Scale tillsammans med ett varghjärta, ett pumalårben och en swoopkräva för att rena den spridande infektionen innan den blir dödlig."}},faq={{q="Vad används Plainstrider Scale till?",a="Det är en viktig medicinalingrediens som samlas in åt Maur Raincaller i Bloodhoof Village. Tillsammans med delar från andra rovdjur i Mulgore kokas den till ett läkemedel mot ett infekterat, giftigt sår som den vildsinta tallstridern Mazzranache har orsakat.",al={"vad gör plainstrider scale","användning av plainstrider scale","varför behövs plainstrider scale"}},{q="Var hittar du Plainstrider Scale?",a="Fjällen får du genom att jaga de vilda plainstriders som strövar omkring på de öppna gräsmarkerna i Mulgore.",al={"var hittar man plainstrider scale","hur får man plainstrider scale","plainstrider scale plats"}},{q="Varför är Maur Raincaller infekterad?",a="När Maur färdades över slätterna överföll och bet Mazzranache honom i axeln. Den skräckinjagande tallstridern är ökänd för sitt giftiga bett och sina karmosinröda ögon. Bettet gav honom en förvärrad, omtöcknad feber som vanlig vila inte kan bota.",al={"hur blev maur sjuk","varför är maur sjuk","mazzranaches bett"}},{q="Vilka andra ingredienser behöver Maur till sitt läkemedel?",a="Förutom Plainstrider Scale behöver Maur ett Prairie Wolf Heart, ett Flatland Cougar Femur och en Swoop Gizzard för att färdigställa medicinalblandningen.",al={"maur raincallers ingredienser","botemedel mot mazzranache","mazzranache uppdragsföremål"}}},fx={["95a4c3dd"]={q="Vad är Plainstrider Scale?",a="Det är en tålig, specialiserad fjälltyp från de högbenta striders som strövar över Mulgore vindpinade gräsmarker. Fåglar och striders är främst kända för sin fjäderdräkt och sina vassa näbbar, men deras robusta ben och fötter bär grova, hårda fjäll som står emot de karga slätterna. Schamaner och örtläkare värdesätter dessa sällsynta, täta fjäll för deras skyddande egenskaper när de tillreder särskilda omslag och läkemedel.",al={"vad är plainstrider scale","plainstrider scale","plainstrider scales"}},d7ded3c8={q="Varifrån kommer Plainstrider Scale?",a="Det är en naturlig del av ett djur, tagen direkt från de vilda plainstriders som strövar omkring i Mulgore. Ingen tillverkar den; jägare tar den från benen på fallna striders över slätterna och samlar bara de tåligaste fjällen för medicinska beredningar.",al={"källa till plainstrider scale","varifrån kommer plainstrider scale","vem tillverkade plainstrider scale"}}},fp="18,142,17.156.0,28.325.1,40.203.0,39.85.0,32.167.0,53.115.0"}
P.entries["item:plainstrider-talon"] = {n="Plainstrider Talon",s="En Plainstrider Talon är en vass klo från de stora, flygoförmögna plainstriders som hör hemma i Mulgore. Tauren-schamaner använder sådana klor tillsammans med andra naturliga ingredienser för att skapa heliga reningstotemer när landets vattenkällor förorenas.",h="En Plainstrider Talon är en vass klo från de stora, flygoförmögna plainstriders som hör hemma i Mulgore.",kw={"bloodhoof village","reningstotem","mulgore","mull thunderhorn","plainstrider","plainstrider talon","förgiftat vatten","winterhoof water well"},ang={["class:Shaman"]="Att använda djurens kroppsdelar, som klor, för att skapa reningstotemer är ett uttryck för traditionell tauren-schamanism. Kraften hämtas direkt från landets naturliga andar.",["race:Tauren"]="Att hedra Mulgore djurlivs offer är centralt för taurenjakten. Varje fällt djur bidrar till att hela Jordmodern när goblinernas exploatering slår till."},sec={{t="Slätternas band",b="De stora, flygoförmögna plainstriders strövar över Mulgore öppna gräsmarker. De förlitar sig på starka ben och vassa klor för att försvara sig mot rovdjur och söka föda i den hårda präriejorden. För tauren i Bloodhoof Village bär varje del av ett jagat djur på en andlig resonans. När Venture Company-goblins förorenade heliga källor som Winterhoof Water Well sökte schamanen Mull Thunderhorn efter plainstrider-klor och prärievargstassar. I taurenritualer gör insamling av ingredienser från traktens rovdjur och födosökare det möjligt att kanalisera landets andliga essens till totemer som kan driva bort onaturliga gifter."}},faq={{q="Vilka varelser släpper Plainstrider Talon?",a="Plainstrider-klor tas från vuxna plainstriders, åldrade plainstriders och den ökända stridern Mazzranache på Mulgore gräsmarker.",al={"vem släpper plainstrider talon","var får man tag på plainstrider talons","källa till plainstrider talon"}},{q="Vad används Plainstrider Talons till?",a="Mull Thunderhorn i Bloodhoof Village behöver plainstrider-klor och prärievargstassar för att skapa en reningstotem som används för att rena det förorenade Winterhoof Water Well.",al={"användning av plainstrider talon","varför behöver jag klor","uppdrag med plainstrider talon"}},{q="Varför behöver Mull Thunderhorn djurdelar för att rena vattnet?",a="Tauren-schamanism bygger på harmoni med Mulgore naturliga andar. Genom att binda delar av det lokala djurlivet i ritualens totem åkallar schamanen landets råa kraft för att bekämpa främmande föroreningar som Venture Company-goblins fört in.",al={"varför djurtassar och klor","schamanens reningsritual med klor"}},{q="Vem förgiftade vattenkällorna i Mulgore?",a="Goblins, särskilt agenter från Venture Company som verkar i Mulgore, och deras hantlangare har förorenat stammarnas heliga vattenkällor. Det stör den lokala miljön och hotar taurenstammarna.",al={"vem förorenade källorna","vem förgiftade vattnet i mulgore","vem förgiftade vattnet"}}},fx={fdecb439={q="Vad är Plainstrider Talon?",a="Plainstrider Talon är den vassa klo som tas från de stora, flygoförmögna plainstriders som strövar omkring i Mulgore. Dessa snabba fåglar använder klorna naturligt till försvar och födosök över slätterna, men klorna har också en medfödd koppling till naturen. För tauren står sådana material för landets styrka och kan kanaliseras genom schamanritualer.",al={"vad är plainstrider talon","historien om plainstrider talons","plainstrider-klor"}},["07c33870"]={q="Varifrån kommer Plainstrider Talons?",a="Dessa klor tas från de vuxna plainstriders som strövar över Mulgore öppna slätter, sydväst om Bloodhoof Village. Jägare samlar dem från vuxna och gamla plainstriders, eller från sällsynta djur som Mazzranache, som offergåvor från landet.",al={"källa till plainstrider talon","var får man tag på plainstrider talons","plainstrider talon ursprung"}},["826885d3"]={q="Varför vill Mull Thunderhorn ha Plainstrider Talons?",a="Mull Thunderhorn i Bloodhoof Village behöver klorna för att tillverka en renande totem till Winterhoof Water Well. Gobliner och deras lakejer i Venture Company har förorenat det heliga vattnet, och Mull måste åkalla den ursprungliga essensen hos Mulgore inhemska djur för att motverka giftet och återställa brunnens renhet.",al={"varför vill mull ha klor","varför behövs plainstrider talon","plainstrider talon användning"}}},fp="18,188,19.568.0,41.136.0,38.171.0,63.212.0,40.189.0"}
P.entries["item:podrig-s-order"] = {n="Podrig's Order",s="Podrig's Order är en skriftlig militär rekvisition, författad av Deathguard Podrig vid The Sepulcher. Den begär en ny leverans vapen från Undercity-handlaren Gordon Wendham, så att Silverpines Forsaken-garnison förblir ordentligt beväpnad.",h="Podrig's Order är en skriftlig militär rekvisition, författad av Deathguard Podrig vid The Sepulcher.",kw={"gordon wendham","hadrec","karos razok","podrig","podrig's order","the sepulcher","silverpine"},ang={["profession:Blacksmithing"]="Smidda vapen är livsviktiga vid frontlinjen, där de pågående striderna hela tiden tömmer garnisonens förråd.",["race:Undead"]="Rekvisitionen visar den livsviktiga försörjningslinjen mellan Undercity och avlägsna utposter som The Sepulcher, så att Mörka damens soldater förblir ordentligt beväpnade mot Scourge."},sec={{t="The Sepulcher beväpnas",b="Silverpine Forest är en osäker gränsbygd för Forsaken, inklämd mellan en framryckande Scourge, förvildade bestar och andra hot som lurar i närheten. Efter en inventering av utrustningen, utförd av Deathguard Podrig på Executor Hadrecs order, visade sig The Sepulchers förråd vara till största delen tillräckliga, men ersättningsvapen var oroväckande få. Den officiella skrivelsen specificerar vilka klingor och vapen som behövs för att hålla Deathguards vid utposten stridsberedda."},{t="Sändning via Bat Handler",b="Eftersom vapen inte är lätta att smida i Silverpines fuktiga kryptor riktas begäran till Gordon Wendham, en vapenhandlare i Undercitys livliga Trade Quarter. För att påskynda beställningen bär kurirer dokumentet direkt till batmästaren Karos Razok och utnyttjar Forsakens flygrutter för att snabbt få fram nya förnödenheter från huvudstaden."}},faq={{q="Vad står det i Podrig's Order?",a="Det är en officiell rekvisition som listar ersättningsvapen som Deathguards vid The Sepulcher behöver efter vanliga förluster i fält.",al={"vad står det i ordern","innehållet i podrig's order","detaljer om podrig's order"}},{q="Vem skrev Podrig's Order?",a="Den utformades av Deathguard Podrig på Executor Hadrecs uppdrag, efter en inventering av The Sepulchers vapenförråd.",al={"vem skrev den","författaren till podrig's order"}},{q="Vem tar emot ordern?",a="Den är avsedd för Gordon Wendham, en vapenhandlare som bedriver verksamhet i Undercitys Trade Quarter.",al={"vem får ordern","vart skickas podrig's order","mottagaren av podrig's order"}},{q="Varför behöver The Sepulcher nya vapen?",a="Ständiga skärmytslingar mot Scourge och andra fientliga styrkor i Silverpine Forest leder ofta till att försvarande Deathguards får utrustning förstörd eller förlorad.",al={"varför behövs vapen","vapenbrist vid the sepulcher"}}},fx={["92a3bbc0"]={q="Vad är Podrig's Order?",a="Podrig's Order är ett officiellt rekvisitionsdokument från Forsaken, skrivet för att säkra nya vapen till utposten vid The Sepulcher. Dokumentet skrevs av Podrig på uppdrag av Executor Hadrec och listar ersättningsvapen som garnisonens Deathguards behöver för att överleva sina pågående sammandrabbningar med Scourge och andra fasor som lurar i Silverpine Forest.",al={"vad är podrigs order","föremålet podrig order","podrigs rekvisition"}},["6fc9fe58"]={q="Varför behöver Gordon Wendham Podrig's Order?",a="Som vapenhandlare i Undercitys Trade Quarter behöver Gordon Wendham den formella rekvisitionen för att verifiera och uppfylla garnisonens leveransbegäran. Utan detta verifierade register kan The Sepulcher inte få den nödvändiga leveransen av klingor och utrustning till sina Deathguards vid frontlinjen.",al={"varför vill gordon wendham ha ordern","varför ta podrigs order till undercity","varför behövs podrig order"}}},fp="14,82,20.335.0,24.268.0,34.124.0,25.121.0,23.96.0,40.152.0"}
P.entries["item:pork-belly-pie"] = {n="Pork Belly Pie",s="I Elwynn Forest vill Billy Maclure ha en paj från The Stonefield Farm innan han berättar om ett försvunnet halsband. Auntie Bernice Stonefield bakar den trots fejden mellan familjerna.",h="I Elwynn Forest vill Billy Maclure ha en paj från The Stonefield Farm innan han berättar om ett försvunnet...",kw={"auntie bernice stonefield","tillbaka till billy","billy maclure","elwynn forest","maclure","pork belly pie","stonefield"},ang={["faction:Alliance"]="För alliansresenärer som hjälper till på landsbygden i Elwynn avslöjar leveransen av pajer de djupt rotade grälen i Stormwinds lantliga hjärtland.",["profession:Cooking"]="Auntie Bernices hemlagade paj har inflytande även mitt i familjernas fejd, men receptet förblir en hemlighet."},sec={{t="En muta mellan rivaliserande gårdar",b="Familjerna Stonefield och Maclure har grälat om mark och stolthet i åratal i Elwynn Forest. Unge Billy Maclure har en svaghet för Auntie Bernices fläskpaj. När ett värdefullt halsband från familjen Stonefield försvinner vägrar Billy berätta vad han vet tills en äventyrare kommer med en varm bit. Bernice bakar pajen motvilligt och önskar att den girige pojken ska sätta den i halsen."}},faq={{q="Vad används Pork Belly Pie till?",a="Auntie Bernice Stonefield bakar pajen för att få unge Billy Maclure att prata. Han vet något om det försvunna halsbandet från familjen Stonefield, men vägrar säga något innan han får smaka hennes matlagning.",al={"pajens användning","varför fläskpaj","vad gör jag med pajen"}},{q="Vem bakar Pork Belly Pie?",a="Auntie Bernice Stonefield bakar pajen på Stonefield Farm. Hon hyser agg mot Billy Maclure och hans familj, men lagar den för att hjälpa till att återfå familjens försvunna halsband.",al={"vem bakade pajen","pajbagare","granny stonefields paj"}},{q="Varför vill Billy Maclure ha mat från en rivaliserande familj?",a="Billy Maclure vill ha Auntie Bernices matlagning trots fejden mellan familjerna Stonefield och Maclure. Han vill ha fläskpaj mer än han bryr sig om att hålla fast vid familjens agg.",al={"varför billy vill ha paj","varför maclure vill ha mat från stonefield"}},{q="Kan spelare äta Pork Belly Pie?",a="Nej. Pajen är avsedd för Billy Maclure och kan inte ätas för att återställa hälsa eller mana.",al={"kan jag äta den","går pork belly pie att äta"}}},fx={["6505ed9f"]={q="Vad är Pork Belly Pie?",a="Det är en smakrik köttpaj bakad med fläsksida, berömd för att vara utsökt trots den bittra fejden mellan de två jordbrukarfamiljerna i södra Elwynn Forest. Den tillagas färsk i Stonefield-köket och fungerar som en aptitretande muta för att locka information ur Maclure-pojken Billy, som hävdar att minnet bara fungerar när magen är full.",al={"vad är pork belly pie","historien om pork belly pie","om pork belly pie"}}},fp="14,167,29.366.0,36.188.0,29.161.0,53.181.0,35.85.0"}
P.entries["item:powdered-azurite"] = {n="Powdered Azurite",s="I Hillsbrad Foothills bryts Powdered Azurite i Azurelode Mine. Thun'grim Firegaze behöver det för att smida brutal rustning åt Horde-krigare på frammarsch.",h="I Hillsbrad Foothills bryts Powdered Azurite i Azurelode Mine.",kw={"azurelode mine","azurit","brutal rustning","hillsbrad","powdered azurite","reagens","thun'grim firegaze"},ang={["class:Warrior"]="Som krigare sätts din uthållighet på prov när du samlar Powdered Azurite i främmande land, och du förser Thun'grim Firegaze med reagenserna han behöver för att smida din rustning med vild styrka.",["faction:Horde"]="Som medlem av Horde innebär det att lägga beslag på detta förädlade pulver att slå till djupt inne i Eastern Kingdoms och ta resurser från Alliansens händer i Hillsbrad Foothills."},sec={{t="Ett sällsynt mineraliskt ämne",b="Powdered Azurite kommer från mineralådrorna under Hillsbrad Foothills. Mänskliga arbetare bryter den blå stenen i Azurelode Mine och mal den sedan till pulver och packar den för handel och metallarbete. En skicklig smed blandar pulvret med täta metaller för att göra rustningen mer hållbar och motståndskraftig."},{t="Att smida brutal rustning",b="Hordes smeder värdesätter Powdered Azurite för dess styrka i metallarbete, trots att det kommer från tunnlar som hålls av människor på andra sidan Great Sea. Thun'grim Firegaze, en åldrande rustningssmed bland orcher i The Barrens, ber om små mängder tillsammans med raffinerat järn och eldfängda reagenser. När pulvret blandas i smältan hjälper det honom att hamra fram de tunga plåtarna till hans Brutal Armor."}},faq={{q="Vad används Powdered Azurite till?",a="Thun'grim Firegaze använder Powdered Azurite tillsammans med järntackor och flyktiga reagenser för att smida delar av Brutal Armor åt Hordes mästare.",al={"användning av powdered azurite","vad är powdered azurite"}},{q="Var hittar man Powdered Azurite?",a="Mänskliga gruvarbetare samlar Powdered Azurite i Azurelode Mine, längs Hillsbrad Foothills södra kust i Eastern Kingdoms.",al={"var hittar man powdered azurite","powdered azurite plats","vem släpper powdered azurite"}},{q="Varför behöver en smed i The Barrens reagenser från Hillsbrad?",a="Thun'grim Firegaze söker fina material till rustningar värdiga legendariska krigare. Järn är lätt att hitta, men Azurelode-mineralets härdande egenskaper gör det värt att skicka hans mästare över havet för att hämta det.",al={"varför hillsbrad","thungrim källa till mineral"}}},fx={["139f7c50"]={q="Vad är Powdered Azurite?",a="Powdered Azurite är ett krossat blått mineralreagens som utvinns ur djupa ådror i Hillsbrad Foothills. Mästersmeder uppskattar det för dess unika metallurgiska egenskaper; det fina pulvret kan legeras med eller härdas in i basmetaller under smide. Det värdesätts särskilt av Horde-rustmästaren Thun'grim Firegaze, som använder det tillsammans med exotiska reagens för att tillverka tung, slitstark ringbrynja värdig berömda krigare.",al={"vad är azuritpulver","historien om powdered azurite","föremålet powdered azurite"}},["720f3d61"]={q="Varifrån kommer Powdered Azurite, och vem bröt den?",a="Ämnet bryts i Azurelode Mine, som ligger längs de södra kullarna i Hillsbrad Foothills. Mänskliga gruvarbetare i Azurelodes underjordiska schakt gräver fram rå azuritmalm och mal den till ett raffinerat pulver. Eftersom gruvan fortfarande kontrolleras helt av Hillsbrads mänskliga arbetare måste du ta pulvret direkt från gruvarbetarna under jord.",al={"var får man tag på powdered azurite","vem bryter powdered azurite","källa till powdered azurite"}}},fp="16,168,23.218.0,20.366.0,34.133.0,36.128.0,67.193.0"}
P.entries["item:powers-of-the-void"] = {n="Powers of the Void",s="En stulen bok väcker Drusilla La Salles intresse i Northshire. Powers of the Void förvarades i en avspärrad del av Northshire Abbeys bibliotek, tills en novis tog den när han lämnade klostret för att gå med i Defias Brotherhood. Drusilla vill få tillbaka den för sina egna studier i mörk magi.",h="En stulen bok väcker Drusilla La Salles intresse i Northshire.",kw={"defias brotherhood","drusilla la salle","imp","khadgar","northshire abbey","powers of the void","stulna böcker","den stulna boken","demonhäxmästare"},ang={["class:Warlock"]="Som demonhäxmästare prövas din vilja att förtjäna undervisning i att åkalla en imp när du hämtar den stulna boken.",["race:Human"]="Som människa kan du se att Northshires Holy Order förvarar farliga magiska skrifter tillsammans med kyrkliga texter, dolda för novisernas blickar."},sec={{t="En avspärrad bok i Northshire",b="Powers of the Void förvarades bakom bevakade hyllor i Northshire Abbeys bibliotek. Klostrets arkiv innehåller heliga skrifter och kyrkliga handlingar, liksom lärda verk om skuggans och netherenergiers krafter. Boken tros ha skrivits av ärkemagikern Khadgar. Eftersom ämnet var farligt höll klostrets ledning boken under bevakning och borta från nyfikna besökare. Därför kunde Northshires demonlärarmentor, Drusilla La Salle, inte bläddra i den utan att väcka prästerskapets misstankar."},{t="Defias stöld och återhämtning",b="En novis från Northshire tog med sig boken när han bröt sina löften för att gå med i Defias Brotherhood. På flykten till de närliggande vingårdarna tog han flera värdefulla böcker från klostret. Drusilla skickar lovande demonlärlingar till Defias banditläger för att hämta boken ur deras tält. Hon vill åt den mörka kunskapen för sina egna studier, och uppdraget prövar om en lärling har mod nog att binda utomvärldsliga demoner."}},faq={{q="Vad är Powers of the Void?",a="Powers of the Void är en sällsynt ockult bok om skuggans och netherenergiers krafter, som tros ha skrivits av ärkemagikern Khadgar. Den förvarades i en avspärrad del av Northshire Abbeys bibliotek innan den stals.",al={"vad är powers of the void","boken powers of the void","vad är den stulna boken"}},{q="Varför låstes boken in i Northshire Abbey?",a="Northshire Abbey förvarar historiska arkiv, däribland farliga texter om förbjuden magi. Böcker om Void-energier och demonologi låses in för att hindra noviser och egensinniga magiker från att missbruka dem.",al={"varför fanns den i klostret","varför hade prästerna den","biblioteksflygeln i northshire"}},{q="Hur fick Defias Brotherhood tag på boken?",a="En novis från Northshire Abbey lämnade klostret för att gå med i Defias Brotherhood och tog flera värdefulla böcker från det avspärrade biblioteket. Han gömde dem i banditlägret i Northshires vingårdar.",al={"vem stal boken","defias stulna böcker","hur fick defias tag på den"}},{q="Varför vill Drusilla La Salle ha Powers of the Void?",a="Drusilla La Salle är Northshires demonlärarmentor och vill använda bokens kunskap i sin egen mörka konst. Hon kunde inte gå in i klostrets säkrade bibliotek utan att väcka misstankar.",al={"varför vill drusilla ha den","vem vill ha boken","drusilla la salle stulen bok"}},{q="Vad bevisar det för Drusilla att du hämtar boken?",a="Att hämta boken prövar om en lärling har mod nog att binda demoner. Drusilla låter dem genomgå provet innan hon lär dem att åkalla sin första imp.",al={"varför behöver demonhäxmästare boken","prov i att åkalla en imp","belöning för stulen bok"}}},fx={["082e56cb"]={q="Vem skrev Powers of the Void?",a="Den magiska avhandlingen tros ha skrivits av den legendariske ärkemagikern Khadgar, som studerade många djupgående och farliga aspekter av magi innan han färdades bortom The Dark Portal. Dess förbjudna insikter om tomrummets djupare krafter ansågs alldeles för farliga för vanlig läsning, så prästerna och lärda vid Northshire Abbey låste in den i en skyddad del av biblioteket tills en förrädisk novis stal den.",al={"författaren till powers of the void","vem skapade powers of the void","skaparen av powers of the void"}}},fp="18,251,28.476.0,25.427.0,27.217.0,47.198.0,44.183.0,51.175.0,48.147.0"}
P.entries["item:prairie-alpha-tooth"] = {n="Prairie Alpha Tooth",s="En Prairie Alpha Tooth tas från de våldsamma flockledarna som strövar på slätterna runt Thunder Bluff. Enligt tauren-traditionen används dessa tänder som kraftfulla offergåvor för att rena och hedra landets dyrbara vattenkällor.",h="En Prairie Alpha Tooth tas från de våldsamma flockledarna som strövar på slätterna runt Thunder Bluff.",kw={"bloodhoof village","mulgore","mull thunderhorn","prairie alpha tooth","alfavarg på prärien","vattenbrunn","wildmane totem"},ang={["class:Shaman"]="Vattenbrunnarnas andar måste blidkas genom balans med jorden, och ett offer av en toppredators huggtänder förankrar den naturliga harmonin.",["race:Tauren"]="Att ta huggtanden från en alfavarg på prärien uttrycker jägarens heliga plikt att med vördnad skörda det som behövs och återföra den uråldriga kraften för att läka den förgiftade jorden."},sec={{t="En renande offergåva",b="Mulgore-vattenbrunnarna är livsviktiga för tauren, och deras andliga renhet måste bevaras genom riter av vördnad och offer. För att rena Wildmane Well behöver Mull Thunderhorn från Bloodhoof Village tänder från alfavargarna på prärien som jagar i skuggan av Thunder Bluff. Som de främsta rovdjuren på de böljande grässlätterna står dessa alfavargar för vildmarkens råa styrka. Att offra deras tänder hedrar balansen mellan jägare, byte och jordens andar."}},faq={{q="Vad används en Prairie Alpha Tooth till?",a="Mull Thunderhorn använder åtta sådana tänder i en ritual för att rena Wildmane Well, den sista förorenade vattenbrunnen nära Bloodhoof Village.",al={"syftet med alfavargstand","vad används vargtänder till i mulgore","wildmane totem-föremål"}},{q="Var strövar Prairie Wolf Alphas?",a="Alfavargar på prärien stryker omkring på de öppna grässlätterna i centrala och norra Mulgore, särskilt runt klipporna vid foten av Thunder Bluff.",al={"var finns alfavargar på prärien","platser för alfavargar","platser för alfavargar på prärien"}},{q="Varför behövs vargtänder i en ritual för att rena vatten?",a="Tauren-riter hedrar naturens balans. För att rena brunnarna behövs heliga delar från landets våldsamma inhemska bestar, som symboliserar både offret och livskraften hos Mulgore-vildlivet.",al={"varför vargtänder för vatten","lore om mull thunderhorns tandritual"}}},fx={f1f3b80c={q="Vad är Prairie Alpha Tooth?",a="Prairie Alpha Tooth är en tand från en alfavarg på prärien, en av de våldsammaste flockledarna som stryker omkring på Mulgore-slätterna. Bland tauren står dessa huggtänder för styrkan och anden hos landets främsta rovdjur och har andlig betydelse när de offras i ritualer.",al={"prairie alpha tooth","vad är prairie alpha tooth","alfavargstand från prärien"}},["0674aadd"]={q="Varifrån kommer Prairie Alpha Tooth?",a="Dessa tänder tas från alfavargar på prärien som strövar över Mulgore gräsmarker, särskilt nära foten av Thunder Bluff i norr. De är naturliga huggtänder från levande rovdjur och tas direkt från djuren under jakten, inte tillverkade av dödliga händer.",al={"varifrån kommer prairie alpha teeth","prairie alpha tooth ursprung","vem släpper prairie alpha tooth"}}},fp="19,134,20.357.0,39.147.0,34.146.0,53.169.0"}
P.entries["item:prairie-wolf-heart"] = {n="Prairie Wolf Heart",s="Ett Prairie Wolf Heart är ett livsviktigt organ som tas från vargarna som strövar över Mulgore gräsmarker. Det är en nödvändig ingrediens i en brådskande huskur som Maur Raincaller tillreder i Bloodhoof Village för att motverka en giftig infektion.",h="Ett Prairie Wolf Heart är ett livsviktigt organ som tas från vargarna som strövar över Mulgore gräsmarker.",kw={"bloodhoof village","maur raincaller","mazzranache","mulgore","prairie stalker","prairie wolf heart","varghjärta"},ang={["class:Hunter"]="Att spåra upp särskilda vargflockar på slätterna visar på en tidig förståelse för villebråd och rovdjurens ekologi i Mulgore.",["race:Tauren"]="Att använda delar från fällda djur för att tillreda överlevnadskurer speglar taurenfolkets pragmatiska, jordnära traditioner i Mulgore vildmark."},sec={{t="En kur mot ett giftigt bett",b="Slätternas vargar är våldsamma rovdjur, härdiga och uthålliga bland Mulgore vida grässlätter. Maur Raincaller söker deras hjärtan. Han är en tauren som bor i Bloodhoof Village och föll offer för den legendariska plainstridern Mazzranache. Maur träffades av varelsens virulenta gift, som framkallar feber, och förlitar sig på traditionell slättmedicin för att hejda giftet från att sprida sig. Tillsammans med andra kraftfulla ingredienser som cougar bone och bird gizzard ger den livsviktiga essensen från en nyligen fälld prärievarg de renande egenskaper som krävs för att tillreda ett botemedel innan delirium blir dödligt."}},faq={{q="Vad används ett Prairie Wolf Heart till?",a="Det samlas in åt Maur Raincaller i Bloodhoof Village. Maur behöver det tillsammans med flera andra djurdelar för att brygga en kraftfull huskur mot ett giftigt bett från den ökända stridern Mazzranache.",al={"användning av varghjärta","varför samla varghjärta","syftet med prairie wolf heart"}},{q="Var får man tag på ett Prairie Wolf Heart?",a="Det tas från kropparna efter prairie wolves, prairie wolf alphas och prairie stalkers som jagar över Mulgore böljande slätter.",al={"varghjärtats plats","vem fäller varghjärta","hitta prairie wolf heart"}},{q="Varför behöver Maur Raincaller djurorgan för att behandla sitt sår?",a="Mazzranache tillfogar ett fruktansvärt, infekterat bett som orsakar feber och delirium. Maur använder traditionella taurenkurer från slätterna, tillredda av kraftfulla ingredienser: wolf heart, cougar femur, plainstrider scale och swoop gizzard. De ska rena infektionen innan den blir dödlig.",al={"varför varghjärta i medicin","maurs kur"}},{q="Går det att använda vilket varghjärta som helst till kuren?",a="Maur Raincaller ber helt enkelt om ett varghjärta. Det som samlas in till kuren tas från prairie wolves, prairie wolf alphas eller prairie stalkers som jagar på Mulgore slätter.",al={"vilket varghjärta som helst","vilka vargar fäller det"}}},fx={ee1c9772={q="Vad är Prairie Wolf Heart?",a="Prairie Wolf Heart är ett organ från rovvargarna som strövar över Mulgore böljande slätter. Det har litet värde i vanlig handel, men hjärtat från ett vilt djur är en eftertraktad ingrediens i traditionell taurenmedicin. Det är ett av flera kraftfulla reagens som behövs för att brygga läkemedel som kan rena kroppen från våldsamma naturliga gifter och djupa infektioner.",al={"vad är prairie wolf heart","prairie wolf heart","om prairie wolf heart"}},["1392571f"]={q="Varifrån kommer Prairie Wolf Heart?",a="Hjärtat tas direkt från vilda prärievargar, alfavargar på prärien och präriesmygare som hör hemma på Mulgore gräsbevuxna platåer. Det är ett naturligt biologiskt organ från ett fällt rovdjur, inte ett föremål tillverkat av dödliga händer.",al={"varifrån kommer prairie wolf heart","prairie wolf heart ursprung","vem tillverkade prairie wolf heart"}}},fp="18,89,28.330.0,38.170.0,43.121.0,63.220.0,42.143.0"}
P.entries["item:prairie-wolf-paw"] = {n="Prairie Wolf Paw",s="Prairie Wolf Paws samlas in från rovdjuren som strövar över Mulgore slätter. Schamaner, som Mull Thunderhorn i Bloodhoof Village, använder dem som organiska beståndsdelar för att binda landets naturliga kraft i renande totem.",h="Prairie Wolf Paws samlas in från rovdjuren som strövar över Mulgore slätter.",kw={"bloodhoof village","mulgore","mull thunderhorn","plainstrider talon","förgiftat vatten","prairie wolf","prairie wolf paw","winterhoof water well"},ang={["class:Shaman"]="Att skapa reningstotem av lokala djurdelar visar den elementära principen att använda landets levande essens för att rena onaturligt fördärv.",["race:Tauren"]="För tauren är det en högtidlig förvaltarplikt att samla in vargtassar. De åkallar landets inhemska bestar för att hela förfädernas vattenkällor, som förorenats av goblinernas girighet."},sec={{t="Slätternas naturliga reagenser",b="Prairie wolves smyger genom de böljande gräsen i Mulgore och jagar i flock tillsammans med prairie stalkers och deras flockledare. Varelserna är farliga för unga jägare och den lokala boskapen, men de är djupt sammanflätade med slätternas andliga balans. Taurenschamaner ser vargens tassar inte bara som troféer, utan som viktiga kanaler för jordens inneboende livskraft."},{t="Att rena källorna",b="När gobliners verksamhet förorenade Mulgore heliga vattenreserver behövde schamanen Mull Thunderhorn landets fysiska hjälp för att motverka föroreningen. Tillsammans med plainstrider-klor ger vargtassarna den råa andliga resonans som krävs för att skapa renande totem, och inleda det viktiga arbetet med att rena Winterhoof Water Well."}},faq={{q="Vilka varelser släpper Prairie Wolf Paw?",a="De samlas in från prairie wolves, prairie stalkers och prairie wolf alphas som jagar över Mulgore slätter, främst sydväst om Bloodhoof Village.",al={"vem släpper prairie wolf paw","var får man prairie wolf paws","prairie wolf paw källa"}},{q="Vem vill ha Prairie Wolf Paws?",a="Mull Thunderhorn, en taurenschaman i Bloodhoof Village, ber om dem för att hjälpa till att skapa ett renande totem som återställer de förorenade vattenkällorna.",al={"vem behöver prairie wolf paws","mull thunderhorn vargtassar","lämna in prairie wolf paw"}},{q="Varför behövs vargtassar för att rena vatten?",a="Taurenschamanismen bygger på att kanalisera landets naturliga livskraft för att motverka fördärv. Vargtassarna gör det, tillsammans med fågelklor, möjligt för schamanen att binda Mulgore levande ande i ett elementartotem som kan rena bort goblinernas gifter.",al={"varför vargtassar","prairie wolf paw bakgrund","varför vill mull ha tassar"}},{q="Vilken vattenkälla hjälper tassarna till att rena?",a="Tassarna samlas in specifikt för att skapa reningstotemet till Winterhoof Water Well, som förgiftades av goblinintränglingar och deras agenter.",al={"vilken källa","rena winterhoof well"}}},fx={["94c15e4c"]={q="Vad är Prairie Wolf Paw?",a="Prairie Wolf Paw är en naturlig ritualkomponent som tas från de vilda hunddjuren på Mulgore-slätterna. Tassarna är mer än troféer: de bär på landets levande essens och är därför värdefulla för tauren-schamaner som skapar totem för att hela och bevara jorden.",al={"prairie wolf paw","vad är prairie wolf paws","vargtass mulgore"}},["7a637be5"]={q="Var kommer Prairie Wolf Paws ifrån?",a="Tassarna tas direkt från prairie wolves, prairie stalkers och wolf alphas som hör hemma på Mulgore gräsbevuxna platåer. De är naturliga delar av vildmarken, som jägare tar för att erbjuda landets styrka när det behövs i andlig nöd.",al={"var kommer prairie wolf paws ifrån","prairie wolf paw källa","vem släpper vargtassar"}}},fp="16,198,30.301.0,19.306.0,39.155.0,28.130.0,42.193.0,44.116.0"}
P.entries["item:prayer-to-elune"] = {n="Prayer to Elune",s="Prayer to Elune är inristad på en gyllene tavla bland Twilight’s Hammers tillhörigheter. Den innehåller en vädjan till Astarii Starseeker vid Temple of the Moon.",h="Prayer to Elune är inristad på en gyllene tavla bland Twilight’s Hammers tillhörigheter.",kw={"astarii starseeker","darnassus","elune","gyllene tavla","bön till elune","searing gorge","temple of the moon","twilight’s hammer"},ang={["race:NightElf"]="Som Night Elf känner du Elune som ditt folks gudinna; den här tavlan bär en bön avsedd att nå henne."},sec={{t="En gyllene tavla",b="Bland Twilight’s Hammers tillhörigheter i Searing Gorge finns en gyllene tavla med en bön till Elune. Astarii Starseeker vid Temple of the Moon i Darnassus ber att den ska föras till henne, så att bönen kan nå sin gudinna."}},faq={{q="Vad är Prayer to Elune?",a="Prayer to Elune är en bön inristad på en gyllene tavla.",al={"bönetavla","bön till elune","vilken bön"}},{q="Var finns bönen?",a="Den gyllene tavlan finns bland Twilight’s Hammers tillhörigheter i Searing Gorge.",al={"var finns tavlan","hitta bönen","bönens plats"}},{q="Vem vill ha tavlan?",a="Astarii Starseeker vid Temple of the Moon i Darnassus ber om bönen.",al={"vem vill ha den","astariis bön","vem ska få den"}},{q="Varför vill Astarii ha den?",a="Astarii vill få tillbaka bönen så att Elune kan höra den.",al={"varför tavlan","varför bön till elune","vad är den till för"}}},fp="15,177,15.233.0,28.60.0,20.83.0,21.78.0,25.62.0"}
P.entries["item:pridewing-venom-sac"] = {n="Pridewing Venom Sac",s="Pridewing Venom Sac samlas in från de dödliga wyverner som häckar kring Mirkfallon Lake i Stonetalon Mountains. Nattalverna i Astranaar vill lägga upp ett förråd och förstöra säckarna efter underrättelser om att Hordens agenter samlar in det kraftiga giftet för hemliga mord.",h="Pridewing Venom Sac samlas in från de dödliga wyverner som häckar kring Mirkfallon Lake i Stonetalon...",kw={"astranaar","mirkfallon lake","pridewing","shindrell swiftfire","stonetalon","giftsäck","wyvern"},ang={["faction:Alliance"]="Att neka Horden tillgång till pridewing-gift är avgörande för att skydda gränspatruller från osynliga lönnmördare längs de omstridda gränserna mellan Stonetalon och Ashenvale.",["race:NightElf"]="Väktarnas ledning beklagar att behöva gallra bland oskyldiga vilddjur, men att skydda alvernas liv från förgiftade klingor går före naturens harmoni."},sec={{t="Ett hot bland klipporna",b="Pridewings i Stonetalon är farliga flygande rovdjur som hör hemma på topparna söder om Ashenvale, särskilt kring Mirkfallon Lake. Vilda wyverner är naturligt giftiga, men Alliansens underrättelser från Theramore tyder på att Hordens lönnmördare har börjat mjölka dem på gift för att bestryka klingor som används i hemliga räder mot nattalvernas bosättningar. För att skydda sitt folk och störa fiendens förråd anlitar väktarna i Astranaar spejare för att jaga bestarna och samla in giftkörtlarna innan Horden hinner lägga beslag på dem."}},faq={{q="Vilka varelser ger Pridewing Venom Sac?",a="De här giftsäckarna tas från de olika wyverner som lever bland klipporna nära Mirkfallon Lake i Stonetalon Mountains, däribland unga pridewings, skyhunters, patriarchs och consorts.",al={"var får man tag på pridewing venom sac","vem släpper pridewing venom sac","källor till pridewing-gift"}},{q="Varför vill Astranaar ha Pridewing Venom Sac?",a="Shindrell Swiftfire fick rapporter om att Hordens agenter samlar in pridewing-gift för att bestryka vapen som används vid tysta mord på Alliansens folk. Genom att förstöra eller beslagta körtlarna förekommer man dessa angrepp.",al={"varför samla giftsäckar","shindrell swiftfire gift"}},{q="Vem tar emot de här giftsäckarna i Ashenvale?",a="Shindrell Swiftfire, som är stationerad i nattalvernas stad Astranaar i Ashenvale, samlar in dem för att skydda sitt folk från hemliga angrepp.",al={"vem tar emot pridewing-gift","lämna in pridewing-uppdrag"}},{q="Är pridewings naturligt förbundna med Horden?",a="Nej. De vilda pridewings kring Mirkfallon Lake är bestar som inte frivilligt hjälper Horden, även om orc-agenter utnyttjar deras giftiga natur i sin krigföring.",al={"är pridewings med horden","arbetar pridewings för orcher"}}},fx={e2bba8d5={q="Vad är Pridewing Venom Sac?",a="Pridewing Venom Sac är ett organ som tas från pridewing-wyvernerna som häckar i Stonetalon Mountains. Det innehåller de kraftiga naturliga gifter som dessa bevingade rovdjur producerar för att oskadliggöra sina byten. I den bräckliga kraftmätningen mellan nattalverna och Horden har giftet blivit ett eftertraktat vapen för dolda attacker, vilket har fått försvararna i Astranaar att reagera.",al={"vad är pridewing venom sac","föremålet pridewing venom sac","vad är pridewing venom sacs"}},["816b56c2"]={q="Var kommer Pridewing Venom Sac ifrån?",a="Säckarna tas direkt ur kropparna på pridewings, våldsamma vilda wyverner som håller till nära Mirkfallon Lake i Stonetalon Mountains. Eftersom de är naturliga organ som bestarna själva producerar, inte tillverkade varor, måste du jaga wyvernerna bland klipporna och säkra giftet innan Hordens agenter hinner ta det.",al={"pridewing venom sac källa","var kommer pridewing venom sacs ifrån","vem släpper pridewing venom sac"}}},fp="19,193,21.446.0,43.97.0,45.181.0,42.133.0,51.133.0"}
P.entries["item:prismatic-punch-card"] = {n="Prismatic Punch Card",s="Prismatic Punch Card är datakortet med högsta säkerhetsklassning i den fallna staden Gnomeregan. Det uppgraderas stegvis via en serie Matrix Punchograph-terminaler och innehåller data som gnomernas flyktingar i Ironforge desperat söker efter.",h="Prismatic Punch Card är datakortet med högsta säkerhetsklassning i den fallna staden Gnomeregan.",kw={"castpipe","data rescue","engineering labs","gnomeregan","matrix punchograph","prismatic punch card"},ang={["profession:Engineering"]="Den stegvisa hålkortskodningen och det automatiserade terminalnätverket visar den höga standarden på datormaskineriet som Gnomeregans uppfinnare byggde.",["race:Gnome"]="Det avancerade Punchograph-säkerhetssystemet är ett lysande exempel på gnomernas uppfinningsrikedom och byråkrati, som levde vidare ostört även efter att deras hem gick under."},sec={{t="En fråga om säkerhet",b="När gnomerna flydde från trogginvasionen och den giftiga strålningen i Gnomeregan lämnades enorma mängder forskning och samhällsregister kvar i djupet. För att skydda system med hög säkerhetsklass använde gnomerna ett säkerhetsprotokoll med allt högre krav. För att komma åt terminalen Matrix Punchograph 3005-D i de nedre delarna av Engineering Labs måste man gå igenom en serie hålkort: börja med ett enkelt White Punch Card och uppgradera det via gula, blå och röda behörighetsnivåer vid särskilda terminaler, innan det slutliga Prismatic Punch Card stämplas. Dess kodade säkerhetsnivå anges skämtsamt som i väntan på att ett helt nytt tal ska uppfinnas."},{t="Det viktiga meddelandet",b="Master Mechanic Castpipe, som nu är stationerad bland flyktingarnas enklaver i Ironforge, skickar modiga äventyrare tillbaka in i Gnomegregans förorenade korridorer på ett uppdrag för att rädda kritiskt viktiga data. Castpipe beskriver måldata som helt livsviktiga och omöjliga att klara sig utan, men det avkodade binära meddelandet på det slutliga Prismatic Punch Card avslöjar en roande sanning om gnomernas vardagsliv: ett automatiskt meddelande som talar om för Castpipe att hans tvätt är klar att hämtas."}},faq={{q="Hur skapar du ett Prismatic Punch Card?",a="Du får ett Prismatic Punch Card genom att sätta in ett Red Punch Card i en Matrix Punchograph 3005-D-terminal på den nedre nivån av Engineering Labs i Gnomeregan. För att nå dit måste du uppgradera ett White Punch Card stegvis via terminalerna av modell A, B och C i komplexet.",al={"hur får man prismatic punch card","skapa prismatic punch card","sekvens för uppgradering av hålkort"}},{q="Vilka data finns lagrade på Prismatic Punch Card?",a="Kortet förklarar att dess säkerhetsklassning är så hög att ett nytt tal måste uppfinnas, följt av en lång sträng binärkod. Master Mechanic Castpipe hävdar att informationen är mycket viktig.",al={"vad står det på kortet","översättning av hålkortets binärkod","avkodat hålkort"}},{q="Vem vill ha Prismatic Punch Card?",a="Master Mechanic Castpipe, en landsförvisad gnomingenjör som bor i Ironforge, begär kortet under uppdraget Data Rescue. Han anser att innehållet är brådskande och ovärderlig information som lämnades kvar under evakueringen av Gnomeregan.",al={"vem lämnar in prismatic punch card","castpipes uppdrag","vem behöver kortet"}},{q="Var finns Matrix Punchograph-terminalerna?",a="Terminalerna är utspridda i Gnomeregan utifrån behörighetsnivå. Punchograph 3005-A finns nära Train Depot vid ytan och ingången till Workshop. Modell B finns i Dormitory, bortom Clean Zone. Modell C står längre in i komplexet, och modell D finns i de nedre delarna av Engineering Labs.",al={"terminalernas platser","var finns punchograph-terminalerna","var stansar man hålkort"}}},fx={f4168582={q="Vad är Prismatic Punch Card?",a="Prismatic Punch Card är ett datakort med oerhört hög säkerhetsklassning, skapat av beräkningssystemen i Gnomeregan. Den automatiska säkerhetsklassningen sägs vara så hög att gnomernas matematik ännu inte har uppfunnit ett tillräckligt stort tal för att beskriva den. I själva verket innehåller kortet kodad binärtext från terminaler djupt inne i staden och är den högsta nivån i gnomernas graderade protokoll för datahämtning.",al={"vad är prismatic punch card","prismatic punch card bakgrund","prismatic card gnomeregan"}},["7551673e"]={q="Varifrån kommer Prismatic Punch Card, och vem skapade det?",a="Kortet skapas djupt inne i den fallna staden Gnomeregan av Matrix Punchograph 3005-D, en automatiserad terminal med hög säkerhet på den lägre nivån i Engineering Labs. Det tillverkas inte för hand, utan kodas av gnomernas mekaniserade nätverk när en användare matar in ett korrekt uppgraderat Red Punch Card i apparaten.",al={"prismatic punch card ursprung","vem skapade prismatic punch card","var får man prismatic punch card"}}},fp="20,134,20.538.0,22.316.1,41.204.0,48.169.1,35.200.0,51.268.0"}
P.entries["item:pristine-crawler-leg"] = {n="Pristine Crawler Leg"}
P.entries["item:pristine-spider-silk"] = {n="Pristine Spider Silk",s="Magiker i Stormwind söker Pristine Spider Silk till kåpor vävda för att tåla förtrollningar. Den fina tråden kommer från giftiga spindlar i Duskwood.",h="Magiker i Stormwind söker Pristine Spider Silk till kåpor vävda för att tåla förtrollningar.",kw={"black widow hatchling","carrion recluse","duskwood","magikerkåpa","pristine spider silk","wizard's sanctum","wynne larson"},ang={["class:Mage"]="Som magiker i Stormwind skickas du till Duskwood för att samla den här fina tråden och förtjäna en kåpa som passar din växande arkana förmåga.",["profession:Tailoring"]="Som skräddare arbetar du med fin, tålig tråd som samlats från dödliga spindlar, ett utsökt naturmaterial för magiska kåpor."},sec={{t="Den arkana väven",b="Magiker i Stormwind behöver silke som är starkt nog att tåla förtrollningar och en adeptas slitage. Skräddare använder vanligt spindelsilke, men trådarna som samlas från carrion recluses och black widow hatchlings i Duskwood är tåligare. Magiker från Wizard's Sanctum skickar blivande adepter in i skogarna för att samla silket. Mästerskräddaren Wynne Larson väver sedan en kåpa av det åt en adept."}},faq={{q="Varifrån kommer Pristine Spider Silk?",a="Pristine Spider Silk kommer från carrion recluses och black widow hatchlings i Duskwood.",al={"var man hittar pristine spider silk","vem som fäller pristine spider silk","pristine spider silk-plats"}},{q="Vem tillverkar plagg av det här silket?",a="Wynne Larson, en klädmakare i Mage Quarter i Stormwind, väver det insamlade silket till en kåpa åt Wizard's Sanctum.",al={"vem som använder pristine spider silk","vem som väver silke till kåpor","wynne larsons kåpa"}},{q="Varför behöver magikerna just det här silket?",a="Magikerna behöver silke som är tåligt nog för att en adepts kåpa ska tåla förtrollningar och slitage. Silket från spindlarna i Duskwood har den styrka och kvalitet som krävs.",al={"varför pristine silk","användning av magiskt spindelsilke"}}},fx={dfaa8e27={q="Vad är Pristine Spider Silk?",a="Pristine Spider Silk är ett exceptionellt fint och obefläckat spindelnät spunnet av spindlarna som hemsöker Duskwood. Till skillnad från de vanliga, trasiga näten som klänger på träden i den mörka skogen räknas bara de renaste, oskadade trådarna som pristine. Skräddare och magiker värdesätter silket högt för dess överlägsna kvalitet och struktur. Det används som grundtyg för särskilda plagg åt magiker i träning.",al={"pristine spider silk","vad är pristine silk","föremålet pristine silk"}}},fp="20,108,18.366.0,42.88.0,35.120.0,44.157.0"}
P.entries["item:pristine-tigress-fang"] = {n="Pristine Tigress Fang",s="En Pristine Tigress Fang är ett exemplar som Far Seer Mok'thardin söker vid Grom'gol Base Camp. Skicket är viktigt för hans förtrollningar åt Horde.",h="En Pristine Tigress Fang är ett exemplar som Far Seer Mok'thardin söker vid Grom'gol Base Camp.",kw={"förtrollning","huggtand","grom'gol","mizjah ruins","mok'thardin","pristine tigress fang","stranglethorn","tiger"},ang={["faction:Horde"]="Mok'thardin söker huggtanden och Shadowmaw-klorna för att tämja djungelns magi åt Horde."},sec={{t="Ett fint exemplar",b="På andra sidan floden, sydost om Mizjah Ruins, strövar Stranglethorn Tigresses omkring i djungeln. Far Seer Mok'thardin ber om en huggtand i perfekt skick, tillsammans med Shadowmaw Panther-klor. Han säger att hans ritualer redan har visat sig fungera, och han tänker tämja djungelns magi åt Horde."}},faq={{q="Vem vill ha Pristine Tigress Fang?",a="Far Seer Mok'thardin vid Grom'gol Base Camp vill ha en Pristine Tigress Fang till sina förtrollningar.",al={"vem vill ha huggtanden","mok'thardins huggtand","huggtand åt vem"}},{q="Varför måste huggtanden vara i perfekt skick?",a="Mok'thardin säger att bara en huggtand i perfekt skick duger för hans arbete med djungelns magi.",al={"varför perfekt skick","perfekt huggtand","huggtandens skick"}},{q="Var kan jag hitta Pristine Tigress Fang?",a="Stranglethorn Tigresses i Stranglethorn Vale bär på Pristine Tigress Fangs. Mok'thardin pekar ut djungeln sydost om Mizjah Ruins, på andra sidan floden.",al={"var finns huggtanden","tigerns huggtand plats","huggtand från tigrar"}},{q="Vad mer behöver Mok'thardin?",a="Mok'thardin ber också om åtta Shadowmaw Claws utöver Pristine Tigress Fang.",al={"vad mer behöver han","klor också","mok'thardin behöver"}},{q="Vad försöker Mok'thardin göra?",a="Mok'thardin försöker tämja kraften i djungelns magi åt Horde genom mäktiga förtrollningar.",al={"mok'thardins magi","djungelförtrollning","varför vill han ha den"}}},fp="21,144,15.292.0,36.94.0,38.96.0,41.153.0,32.84.0,33.105.0"}
P.entries["item:prowler-claws"] = {n="Prowler Claws",s="I The Barrens förs Prowler Claws tillbaka till Sergra Darkthorn vid The Crossroads. De visar att en jägare kan spåra och besegra rovdjuren som stryker över slätterna.",h="I The Barrens förs Prowler Claws tillbaka till Sergra Darkthorn vid The Crossroads.",kw={"the barrens","the crossroads","prowler claws","prowlers i the barrens","savannah prowler","sergra darkthorn"},ang={["class:Hunter"]="Som jägare sätts din förmåga att smyga, spåra och hantera bestar på nära håll på prov när du spårar upp savannah prowlers och tar deras klor.",["faction:Horde"]="Som medlem av Horden skyddar du budbärare, karavaner och nybyggare längs Kalimdors centrala vägar genom att hjälpa till att minska antalet prowlers kring The Crossroads."},sec={{t="Troféer från smygjägaren",b="Savannah Prowlers gömmer sig i The Barrens höga gräs och väntar tålmodigt och listigt på att slå till. Dessa stora kattdjur överfaller varelser som kommer in på deras jaktmarker, till skillnad från betande plainstriders och zhevra. Att ta deras böjda klor innebär att möta rovdjur som förlitar sig på smygande och försvarar sitt revir. För Hordens krigare och spejare visar jakten om de kan spåra en förföljare genom dess eget område och göra den till byte."},{t="Bevis för jägmästarinnan",b="Sergra Darkthorn, jägarinnan vid The Crossroads, ber noviser att ta med sig Prowler Claws innan de möter större prövningar. Klorna visar att en jägare kan följa spår genom savannens gräs och stå emot ett rovdjurs angrepp. De som återvänder med dem har bevisat att de kan hålla sig alerta bland slätternas farliga bestar."}},faq={{q="Var får jag tag på Prowler Claws?",a="Savannah Prowlers strövar omkring på The Barrens centrala gräsmarker, särskilt slätterna sydväst om The Crossroads. Ta deras klor och för tillbaka dem.",al={"var finns prowler claw","hur får man prowler claws","var hittar man prowler claws"}},{q="Vem vill ha klorna och varför?",a="Sergra Darkthorn, en erfaren jägarinna vid The Crossroads, vill ha sju Prowler Claws. När du lämnar dem till henne sätts din förmåga att spåra och kämpa mot farliga rovdjur på prov.",al={"vem behöver prowler claws","lämna in prowler claws","sergra klouppdrag"}},{q="Varför anses Savannah Prowlers vara ett betydelsefullt byte?",a="Savannah Prowlers är skygga köttätare som smyger på resenärer och byten från det höga snåret. Jakten prövar om du kan undvika ett bakhåll och besegra ett listigt, dödligt odjur.",al={"varför jaga prowlers","farliga prowlers"}}},fx={["551eb0e2"]={q="Vad är Prowler Claws?",a="Prowler Claws är rakbladsvassa klor från tassarna på savannah prowlers, de dödliga kattrovdjur som smyger genom Barrens höga savanngräs. För jägarna vid Crossroads är troféerna ett bevis på att du kan spåra och fälla ett listigt, dödligt odjur utan att själv bli dess byte.",al={"vad är prowler claws","föremålet prowler claws","om prowler claws"}},c8bad4fe={q="Var kommer Prowler Claws ifrån?",a="Klorna kommer direkt från savannah prowlers som strövar omkring på Barrens-slätterna, särskilt gräsmarkerna sydväst om Crossroads. Jägare som är skickliga nog att fälla de stora kattdjuren tar klorna som naturliga troféer från deras kroppar.",al={"var kommer prowler claws ifrån","prowler claws källa","hur får man prowler claws"}}},fp="13,154,23.425.0,22.323.0,29.143.0,30.170.0,56.179.0"}
P.entries["item:pulsing-blue-shard"] = {n="Pulsing Blue Shard",s="Pulsing Blue Shards är sällsynta kristaller som tas från Ironjaw Basilisks i Stranglethorn Vale. Kin'weelay behöver deras magi för att kontrollera Mind's Eye.",h="Pulsing Blue Shards är sällsynta kristaller som tas från Ironjaw Basilisks i Stranglethorn Vale.",kw={"blå kristallskärvor","crystalvein mine","ironjaw basilisk","kin'weelay","mind's eye","pulsing blue shard","stranglethorn","yenniku"},sec={{t="En sjungande kristall",b="Kin'weelay, en troll vid Grom'gol Base Camp, ber dig ta med Pulsing Blue Shards från Ironjaw Basilisks i Crystalvein Mine. Han behöver deras magi till Mind's Eye, en juvel som sägs rymma stor kraft."}},faq={{q="Vad är Pulsing Blue Shards?",a="Pulsing Blue Shards är sällsynta kristaller som tas från Ironjaw Basilisks i Stranglethorn Vale. Deras magi kan hjälpa Kin'weelay att kontrollera Mind's Eye.",al={"blå kristallskärva","pulserande kristall"}},{q="Vem behöver kristallerna?",a="Kin'weelay vid Grom'gol Base Camp behöver Pulsing Blue Shards för sitt arbete med Mind's Eye.",al={"vem vill ha blå kristallskärvor","kin'weelay kristallskärvor"}},{q="Var kommer kristallerna ifrån?",a="Ironjaw Basilisks i Crystalvein Mine ger Pulsing Blue Shards.",al={"var hittar man kristallskärvor","crystalvein kristallskärvor"}},{q="Vad är Mind's Eye?",a="Mind's Eye är en juvel som gömts djupt i Stranglethorn Vale och sägs rymma stor kraft. Kin'weelay tror att kristallerna kan hjälpa honom att böja dess magi efter sin vilja.",al={"mind's eye","sjungande kristaller"}},{q="Varför vill Kin'weelay ha dem?",a="Kin'weelay behöver kristallernas magi för att kontrollera Mind's Eye, som han hoppas kunna använda för att föra tillbaka Yenniku från mörkret.",al={"varför kristallskärvor","vad används kristallskärvor till"}}},fp="18,145,17.203.0,29.145.0,21.92.0,30.64.0,23.158.0,30.124.1"}
P.entries["item:pupellyverbos-port"] = {n="Pupellyverbos Port",s="En låda Pupellyverbos Port föll överbord nära Hinterlands under en storm. Whiskey Slim i Booty Bay behöver få tillbaka flaskorna innan kaptenen upptäcker att de saknas.",h="En låda Pupellyverbos Port föll överbord nära Hinterlands under en storm.",kw={"booty bay","hinterlands","förlorad grogg","overlook cliffs","kapare","pupellyverbos port","storm","whiskey slim"},sec={{t="Förlorad till havs",b="Utanför Overlook Cliffs träffade en storm skeppet som fraktade Pupellyverbos Port mot Stormwind. Kaptenen hade tagit lådan från en kapare, och Whiskey Slim bröt upp den för att få mod när vågorna växte. En väldig våg svepte flaskorna överbord. Nu ligger groggen utspridd längs stranden, och Slim fruktar kaptenens vrede."}},faq={{q="Vad är Pupellyverbos Port?",a="Pupellyverbos Port är en grogg som fraktas i en låda ombord på ett skepp på väg till Stormwind.",al={"pupellyverbos","vad är det för portvin","pupellyverbos-sprit"}},{q="Hur kom flaskorna bort?",a="En storm nära Overlook Cliffs skickade en väldig våg över skeppet och svepte flaskorna ner i havet.",al={"vart tog flaskorna vägen","hur försvann spriten","vad hände med groggen"}},{q="Vem letar efter spriten?",a="Whiskey Slim i Booty Bay vill få tillbaka de förlorade flaskorna innan kaptenen får veta att de saknas.",al={"vem vill ha spriten","whiskey slim-flaskor","slims grogg"}},{q="Varifrån kom lådan?",a="Kaptenens besättning lade beslag på lådan från en kapare på väg mot Stormwind.",al={"vem hade lådan","sprittens ursprung","kaparens sprit"}}},fp="18,177,11.329.0,27.82.0,29.100.0,28.101.0,30.86.0"}
P.entries["item:pure-hearts"] = {n="Pure Hearts",s="Pure Hearts är rituella reagenser som Carendin Halgar ger till Fördärvade häxmästare i Undercity. De används för att locka fram en succubus genom Twisting Nether, så att utövaren kan besegra och binda demonen.",h="Pure Hearts är rituella reagenser som Carendin Halgar ger till Fördärvade häxmästare i Undercity.",kw={"carendin halgar","magic quarter","pure hearts","succubus","kallelse","bindningen","undercity"},ang={["class:Warlock"]="För Fördärvade häxmästare är det en avgörande milstolpe inom demonologi att skaffa och använda dessa hjärtan: ett bevis på deras mentala styrka mot Twisting Nethers förföriska lockelser.",["race:Undead"]="Mitt bland Undercitys förruttnelse och pest visar bruket av helt obefläckade hjärtan för att manipulera demoniska begär den kalla, pragmatiska trolldom som Fördärvade utövar."},sec={{t="Lockbete för Nether",b="Demonologi bygger på att utnyttja grundläggande begär och andliga svagheter. För att kalla en succubus till Magic Quarter i Undercity ger Carendin Halgar häxmästare Pure Hearts. När de placeras på kallelsecirkeln fungerar dessa obefläckade andliga essenser som ett kraftfullt lockbete och drar den förföriska demonen genom Twisting Nether in i de dödligas värld. När demonen visar sig måste häxmästaren stå emot hennes förtrollande sinnescharm och slå ner henne i strid. Genom att övervinna succubusen hävdar häxmästaren mystisk dominans och förvisar henne tillbaka till Twisting Nether, tills Carendin lär häxmästaren besvärjelsen som låter henne kallas fram när som helst."}},faq={{q="Vad används Pure Hearts till?",a="De fungerar som den mystiska katalysator som används vid kallelsecirkeln i Undercitys Magic Quarter för att locka fram en succubus genom tomrummet, så att en häxmästare kan strida mot och binda henne.",al={"användning av pure hearts","varför pure hearts","vad gör pure hearts"}},{q="Vem ger ut Pure Hearts?",a="Carendin Halgar, den Fördärvade häxmästartränaren i Magic Quarter under Ruins of Lordaeron, ger dem till blivande utövare som är redo att bemästra kallelsen av en succubus.",al={"vem ger pure hearts","uppdragsgivare för pure hearts"}},{q="Varför reagerar en succubus på Pure Hearts?",a="Succubi frodas av fördärv, förförelse och att korrumpera oskuld. Strålglansen från obefläckade, rena hjärtan är ett oemotståndligt lockbete genom Twisting Nether som drar dem rakt in i häxmästarens förberedda kallelsecirkel.",al={"varför succubus vill ha pure hearts","lore om pure hearts"}},{q="Får man behålla Pure Hearts efter ritualen?",a="Nej. När succubusen har kallats fram och kuvats återlämnas resterna av Pure Hearts till Carendin Halgar som bevis på att bindningsprovet är avklarat.",al={"behåller jag pure hearts","vad händer med pure hearts"}}},fx={["105bfa16"]={q="Vad är Pure Hearts?",a="Pure Hearts är kraftfulla ritualkomponenter som används av Fördärvade häxmästare i Undercity. När de kastas på en kallelsecirkel fungerar deras orörda essens som lockbete genom den virvlande Nether och öppnar en reva som är särskilt utformad för att locka till sig och kalla en farlig succuba till dig.",al={"vad är pure hearts","föremålet pure hearts","pure hearts häxmästare"}},["3abadf0f"]={q="Varför skulle någon vilja ha Pure Hearts?",a="En blivande häxmästare behöver Pure Hearts för att fullborda den farliga bindningsritualen för en succuba. Utan detta orörda lockbete som överbryggar tomrummet kan du inte dra demonen in i den dödliga världen för att kuva henne och bemästra konsten att kalla henne till din tjänst.",al={"varför vill man ha pure hearts","pure hearts syfte","varför efterfrågas pure hearts"}}},fp="11,206,19.499.0,34.183.0,29.123.0,43.149.0,52.151.0"}
P.entries["item:purified-kor-gem"] = {n="Purified Kor Gem",s="En Purified Kor Gem är en sällsynt, välsignad kristall som vapensmeden Jordan Stilwell utanför Ironforge behöver. Den har fläckats av mörka krafter och måste återtas från Kalimdors djup och renas med alvmagi innan den kan smidas till ett heligt vapen för Ljuset.",h="En Purified Kor Gem är en sällsynt, välsignad kristall som vapensmeden Jordan Stilwell utanför Ironforge...",kw={"auberdine","blackfathom deeps","corrupted kor gem","dun morogh","jordan stilwell","purified kor gem","test of righteousness","thundris windweaver"},ang={["class:Paladin"]="Att skaffa och rena ädelstenen visar en paladins hängivenhet. Färden går från Kalimdors djup tillbaka till Dun Morogh, där ett ikoniskt vapen för Ljuset ska smidas.",["faction:Alliance"]="För att få tag på den renade ädelstenen samarbetar alliansens folk. Alvernas visdom i Auberdine hjälper en mänsklig smed på Dun Moroghs sluttningar."},sec={{t="Från korruption till helighet",b="Stenen börjar sin färd som en Corrupted Kor Gem i de vidriga nagornas ägo, där de lurar i Blackfathom Deeps, djupt under Ashenvales kust. För att rena stenen från dess vattenburna skuggsmitta måste en paladin söka upp nattalven Thundris Windweaver i Auberdine. Med hjälp av både arkan och naturlig magi driver Thundris ut korruptionen ur stenen och förvandlar den till den strålande Purified Kor Gem. Först i detta fläckfria skick kan den tjäna som kanal för helig kraft."},{t="Smedens mästerverk",b="Utanför Ironforge, bland de snötäckta klipporna i Dun Morogh, behöver den mänsklige vapensmeden Jordan Stilwell ädelstenen som en nyckelkomponent för att smida ett mästerverk till vapen. Stilwell har länge haft ritningar till ett vapen värdigt Silver Hand, men saknat de exotiska material som krävs för att förverkliga sina planer. Purified Kor Gem ger tillsammans med Whitestone Oak Lumber och sällsynt malm den andliga kärna som behövs för att kanalisera paladinens rättmätiga vrede."}},faq={{q="Vad används Purified Kor Gem till?",a="Den lämnas till smeden Jordan Stilwell, som håller till utanför Ironforges portar i Dun Morogh. Stilwell använder den välsignade ädelstenen som en viktig komponent när han smider ett helgat vapen åt en paladin som genomgår sina prövningar.",al={"användning av purified kor gem","varför behöver jag kor gem","vad används kor gem till"}},{q="Var kommer ädelstenen ifrån?",a="Stenen kommer från ruinerna under jorden i Blackfathom Deeps vid Ashenvales kust, där nagorna håller den som en korrumperad artefakt.",al={"kor gems ursprung","var tappar man kor gem","vem tappar kor gem"}},{q="Vem renar ädelstenen?",a="Thundris Windweaver, en alvisk lärd som bor i kustbosättningen Auberdine i Darkshore, renar bort de mörka krafterna från Corrupted Kor Gem och återställer den till ett rent skick.",al={"hur renar man kor gem","vem renar kor gem","thundris windweaver kor gem"}},{q="Kan vilken äventyrare som helst använda Purified Kor Gem?",a="Paladiner som genomgår Test of Righteousness söker särskilt efter ädelstenen. Jordan Stilwell utför sitt hantverk åt heliga krigare som kommer till honom med den renade kristallen och andra sällsynta material.",al={"är kor gem bara för paladiner","kan alla använda purified kor gem"}}},fx={a30b14db={q="Vad är Purified Kor Gem?",a="Purified Kor Gem är en sällsynt, helgad mineral som renats från oren besmittelse. Den återfanns först som en fördärvad sten hos naga i Blackfathom Deeps. Thundris Windweaver i Auberdine har mödosamt renat den från dess mörka inflytande, så att dess vilande egenskaper tryggt kan användas i heliga verk.",al={"vad är purified kor gem","vad betyder purified kor gem","information om purified kor gem"}}},fp="16,161,27.299.0,23.338.0,38.161.0,29.83.0,21.114.0,52.161.0"}
P.entries["item:putrid-claw"] = {n="Putrid Claw",s="Putrid Claws är de förruttnade händer som huggits av från viljelösa odöda som strövar omkring i skogarna väster om Brill. Deathguard Dillinger samlar in dem som definitivt bevis på att hotet från den framryckande Scourge nära den gamla bron hålls stången.",h="Putrid Claws är de förruttnade händer som huggits av från viljelösa odöda som strövar omkring i skogarna...",kw={"ett rutten uppdrag","brill","deathguard dillinger","putrid claw","ravaged corpse","rotting dead","scourge","tirisfal glades"},ang={["race:Undead"]="För nyblivna Forsaken som lämnar Deathknell är det en tidig påminnelse om att friheten kräver ett ständigt försvar mot de viljelösa höljen de en gång liknade, att rensa bort denna viljelösa Scourge."},sec={{t="Trofé från de viljelösa",b="Inte ens i sitt eget hemland är Forsaken helt skyddade från Lich Kings räckvidd. Skaror av viljelös Scourge, ruttnande döda och härjade lik, vandrar regelbundet över de östra gränserna in i Tirisfal Glades och samlas längs vägarna och nära den gamla bron väster om Brill. För att skydda resenärer och garnisonens försörjningslinjer utfäster Deathguards belöningar för dessa kringströvande fasor. En avhuggen förruttnad klo är ett otvetydigt, fysiskt bevis på att ännu ett hasande lik har oskadliggjorts för gott."}},faq={{q="Vad används Putrid Claws till?",a="Deathguard Dillinger, som är stationerad i Brill, samlar in dem som belöning för att bekräfta att lokala Forsaken-rekryter decimerar den Scourge som strövar omkring i Tirisfal Glades.",al={"användning av putrid claw","varför samla in putrid claws","vem vill ha putrid claws"}},{q="Var kommer Putrid Claws ifrån?",a="De tas från ruttnande döda och härjade lik som strövar omkring i de hemsökta skogarna väster om Brill, särskilt nära den gamla flodbron.",al={"var får man tag på putrid claws","vad släpper putrid claw","vad släpper rotting dead"}},{q="Varför finns Scourge i Tirisfal Glades?",a="Efter Lordaerons förödelse strömmar rester av Lich Kings viljelösa Scourge ständigt västerut över gränserna in i Tirisfal och hotar vägar och bosättningar om de inte aktivt decimeras.",al={"varför finns zombies nära brill","scourge i tirisfal"}},{q="Varför låter Forsaken inte bara de viljelösa odöda ströva fritt?",a="Till skillnad från Forsaken, som bröt sig fria under Queen Sylvanas och återfick sin vilja, lyder den viljelösa Scourge bara mörka instinkter eller Lich Kings kvardröjande befallningar. De angriper alla levande eller fria odöda de får syn på.",al={"forsaken mot viljelösa zombies","varför döda andra odöda"}}},fx={["37750c4d"]={q="Vad är Putrid Claw?",a="Putrid Claw är den avhuggna, ruttnande handen från en viljelös zombie som tillhör Scourge. De förruttnade bihangen tas från de vandrande lik som hemsöker Tirisfal Glades som bevis på att de har förstörts.",al={"vad är putrid claw","information om putrid claws","bakgrund om putrid claw"}}},fp="11,191,22.354.0,31.155.0,32.140.0,38.170.0,59.205.0"}
P.entries["item:pyrewood-shackle"] = {n="Pyrewood Shackle",s="Pyrewood Shackles är förtrollade bojor som bärs av de hårt prövade invånarna i Pyrewood Village i södra Silverpine Forest. De är genomsyrade av Archmage Arugals märkliga magi och tycks spela en roll i det mörka öde som drabbar byborna när natten faller över byn.",h="Pyrewood Shackles är förtrollade bojor som bärs av de hårt prövade invånarna i Pyrewood Village i södra...",kw={"arugal","dawnweaver","moonrage","pyrewood","the sepulcher","boja","silverpine","worgen"},ang={["class:Mage"]="Magiker som studerar Arugals verk känner igen den vårdslösa användningen av transmutations- och bindningsmagi, invävd i vanligt stål.",["race:Undead"]="Forsaken-lärda vid The Sepulcher ser Arugals hejdlösa trolldom som ett allvarligt hot mot sina gränser. Därför är det avgörande att samla in de här förtrollade bojorna för att neutralisera Shadowfang Keeps inflytande."},sec={{t="Arugals bindningsmagi",b="Den förbannade byn Pyrewood döljer en oroande hemlighet: på dagen lever invånarna vanliga liv och ser ut som typiska människor, men när solen går ner förvandlas de till vilda Moonrage worgen. Archmage Arugal fjättrade byborna med förtrollade bojor som en del av sina förvridna experiment med worgenmagi. Dalar Dawnweaver, en magisk forskare stationerad vid The Sepulcher för Forsaken, studerar bojorna för att tyda förtrollningarna bakom deras dubbla tillvaro. Genom att samla in och analysera den kvarvarande energin i bojorna söker Dawnweaver en djupare förståelse för Arugals magi, i hopp om att bryta den galne ärkemagikerns grepp om regionen."}},faq={{q="Vad används Pyrewood Shackles till?",a="Dalar Dawnweaver vid The Sepulcher ber om bojorna för att studera deras förtrollningar. Genom att utvinna deras magi hoppas han kunna tyda Archmage Arugals besvärjelser och hitta ett sätt att undanröja ärkemagikerns inflytande i Silverpine Forest.",al={"användning av pyrewood shackles","varför samla in bojor","dalar dawnweaver bojor"}},{q="Vem bär de här bojorna?",a="Bojorna bärs av de förbannade invånarna i Pyrewood Village i södra Silverpine Forest. De har dem på sig både när de ser ut som människor på dagen och när de förvandlas till Moonrage worgen om natten.",al={"vem släpper pyrewood shackles","bojkällan","var hittar man pyrewood shackles"}},{q="Varför förvandlas byborna om natten?",a="Archmage Arugal utsatte Pyrewoods invånare för hänsynslösa magiska experiment och förtrollningar. Bojorna upprätthåller en förtrollning som får dem att se ut som vanliga människor i dagsljus, men när mörkret faller visar de sina vilda worgenformer.",al={"varför förvandlas pyrewood till worgen","pyrewood villages förbannelse","pyrewoods varulighemlighet"}},{q="Vem är Dalar Dawnweaver?",a="Dalar Dawnweaver är en Forsaken-magiker som bor vid The Sepulcher i Silverpine Forest. Han studerar aktivt de magiska anomalier som Archmage Arugal lämnade efter sig och fokuserar på att dissekera och bryta ärkemagikerns förvridna förbannelser.",al={"dalar dawnweaver","vem är dalar"}}},fx={b92f5faa={q="Vad är Pyrewood Shackle?",a="Pyrewood Shackle är en förtrollad boja som sitter på de olyckliga invånarna i Pyrewood Village i södra Silverpine Forest. Bojorna är genomsyrade av den vansinnige magikern Archmage Arugals märkliga, hänsynslösa trolldom och binder byborna direkt till hans vilja samtidigt som de döljer den mörka förbannelse som drabbat dem.",al={"pyrewood shackle","vad är pyrewood shackles","pyrewood shackles"}},f6bcbb50={q="Varifrån kommer Pyrewood Shackle, och vem skapade den?",a="Archmage Arugal, den avfällige magikern från Dalaran som bosatte sig i Shadowfang Keep, smidde bojorna och satte dem på byborna. Han lade dem på Pyrewoods bönder som en del av sina förvridna förtrollningar. De hölls under hans kontroll medan deras förvandling till vargar doldes av en dagsljusillusion av vanligt människoliv.",al={"vem skapade pyrewood shackles","pyrewood shackle ursprung","var kommer bojorna ifrån"}},["98d012f7"]={q="Varför vill någon ha Pyrewood Shackles?",a="Dalar Dawnweaver, en ambitiös Fördärvad magiker som bedriver forskning vid The Sepulcher, söker dessa förtrollade bojor för att studera Arugals magi. Genom att suga åt sig deras kvarvarande energi hoppas Dalar kunna reda ut den märkliga förtrollning som får byborna att se mänskliga ut på dagen och förvandlas till glupska Moonrage worgen efter skymningen, för att till sist bryta Arugals besvärjelser.",al={"varför samla pyrewood shackles","vem behöver pyrewood shackles","pyrewood shackle syfte"}}},fp="16,141,22.410.1,36.176.0,27.155.1,40.234.1,24.167.0"}
P.entries["item:quinn-s-potion"] = {n="Quinn's Potion",s="Quinn's Potion är en läkande brygd som Apothecary Renferrel tillredde i The Sepulcher. Den ska stabilisera och stärka den sårade Deathstalker Quinn Yorick efter en katastrofal spaningspatrull i Silverpine Forest.",h="Quinn's Potion är en läkande brygd som Apothecary Renferrel tillredde i The Sepulcher.",kw={"apothecary renferrel","deathstalker","the ivar patch","quinn yorick","quinn's potion","the sepulcher","silverpine"},ang={["race:Undead"]="Royal Apothecary Society lägger sällan arbete på enkla fältkurer, om de inte direkt räddar Forsaken-spejare som är avgörande för att säkra Silverpines gränser."},sec={{t="Renferrels kur",b="När Deathstalker Quinn Yorick blev svårt misshandlad och sattes ur strid nära The Ivar Patch nådde budet Royal Apothecary Society i The Sepulcher. Apothecary Renferrel blandade hastigt till denna specialbrygd för att hjälpa Quinn att återhämta sig. Renferrel låter sällan mindre fältskador avleda honom från sin större och mer olycksbådande forskning åt Lady Sylvanas, men han gav den läkande brygden för att få den skadade spejaren på benen och i stånd att resa."}},faq={{q="Vad används Quinn's Potion till?",a="Drycken är sammansatt för att hjälpa Deathstalker Quinn Yorick att återhämta sig. Han ligger skadad i Silverpine Forests norra skogar. När han dricker den återfår han tillräckligt med krafter för att kunna resa igen.",al={"syftet med quinn's potion","vad gör quinn's potion","varför brygga quinn's potion"}},{q="Vem bryggde den här drycken?",a="Apothecary Renferrel, en alkemist i Royal Apothecary Society som är stationerad i The Sepulchers kryptor, tillredde brygden.",al={"vem gjorde quinn's potion","vem bryggde den","renferrels dryck"}},{q="Vart ska drycken levereras?",a="Den måste föras norr om The Sepulcher till Quinn Yorick, som söker skydd nära gården som kallas The Ivar Patch.",al={"vart ska jag ta drycken","quinns plats","var quinn yorick finns"}},{q="Varför behövde Quinn Yorick en dryck?",a="Quinn ingick i en Deathstalker-patrull som spanade i norra Silverpine Forest. Vid The Ivar Patch angreps spejarna av ghoul-varelsen Ivar the Foul, och Quinn blev svårt skadad och lämnades kvar där.",al={"varför är quinn skadad","vad hände med quinn yorick","quinn skadad"}}},fx={["52098f03"]={q="Vad är Quinn's Potion?",a="Det är en stärkande brygd som Apothecary Renferrel blandar vid The Sepulcher. Den har utformats särskilt för att hjälpa den skadade spejaren Quinn Yorick. Brygden ger honom kraften att återhämta sig från sina sår och få tillbaka tillräcklig rörlighet för att kunna resa.",al={"quinns brygd","vad är den här brygden","vad är quinn's brygd"}}},fp="14,154,16.415.0,32.156.0,23.123.0,43.109.0,41.169.0"}
P.entries["item:rackmore-s-golden-key"] = {n="Rackmore's Golden Key",s="På Ranazjar Isle hjälper Rackmore’s Golden Key dig att öppna kistan där en sjöman gömde sin skatt. Slitherblade naga håller nyckeln bland de utspridda resterna av hans resa.",h="På Ranazjar Isle hjälper Rackmore’s Golden Key dig att öppna kistan där en sjöman gömde sin skatt.",kw={"desolace","gyllene nyckel","rackmore","rackmore's golden key","ranazjar isle","slitherblade naga","skatt"},sec={{t="En sjömans gömma",b="Rackmores loggbok berättar hur hans skepp var på väg till Feathermoon Stronghold när sjöfarande varelser gick till attack. För att skydda sin skatt från dem gömde han en kista på Ranazjar Isle. Det krävs två nycklar för att öppna den: en av silver och en av guld. Slitherblade naga håller Golden Key, och Rackmore’s Silver Key måste också hittas."}},faq={{q="Vad öppnar Rackmore’s Golden Key?",a="Rackmore’s Golden Key öppnar kistan som gömts på Ranazjar Isle, tillsammans med Rackmore’s Silver Key.",al={"gyllene nyckel","rackmore-nyckel","vad är guldnyckeln till"}},{q="Var finns Rackmores skattkista?",a="Rackmore gömde sin kista på Ranazjar Isle efter att sjöfarande varelser gått till attack mot hans skepp.",al={"var finns rackmores kista","var är kistan","ranazjar-skatt"}},{q="Vem har Golden Key?",a="Slitherblade naga i Desolace har Rackmore’s Golden Key.",al={"vem har rackmores nyckel","naga-nyckel","slitherblade-nyckel"}},{q="Varför gömde Rackmore sin skatt?",a="Rackmore gömde kistan för att skydda sin skatt från de sjöfarande varelser som gick till attack mot hans skepp.",al={"varför gömma kistan","rackmores skattberättelse","varför är skatten gömd"}}},fp="21,173,18.317.0,39.103.0,37.84.0,23.63.0,35.96.0"}
P.entries["item:rackmore-s-silver-key"] = {n="Rackmore's Silver Key",s="Rackmore’s Silver Key är försvunnen bland makrurorna i Desolace. De som söker efter Rackmore’s gömda skatt letar efter den.",h="Rackmore’s Silver Key är försvunnen bland makrurorna i Desolace.",kw={"desolace","drysnap crawler","drysnap pincer","gyllene nyckel","rackmore","rackmore’s chest","rackmore's silver key","ranazjar isle","silvernyckel"},sec={{t="Den förlorade nyckeln",b="Rackmores loggbok berättar att hans skepp var på väg till Feathermoon Stronghold när sjöfarande varelser anföll. För att skydda skatten från fiender gömde han kistan på Ranazjar Isle. Silvernyckeln försvann, och kistan förblir låst tills den hittas tillsammans med sin gyllene motsvarighet."}},faq={{q="Vad öppnar Rackmore’s Silver Key?",a="Rackmore’s Silver Key är en av två nycklar som behövs för att öppna Rackmore’s Chest på Ranazjar Isle. Den gyllene nyckeln är den andra.",al={"silvernyckelns syfte","vad öppnar nyckeln","rackmores nyckel"}},{q="Var hittar jag Rackmore’s Silver Key?",a="Drysnap Pincers och Drysnap Crawlers i Desolace bär på Rackmore’s Silver Key.",al={"silvernyckelns plats","var finns nyckeln","hitta rackmore’s silver key"}},{q="Vem var Rackmore?",a="Rackmore ägde en skattkista som gömdes på Ranazjar Isle efter att hans skepp hade attackerats.",al={"rackmores bakgrund","vem var rackmore","rackmore"}},{q="Varför är Rackmores skatt gömd?",a="Rackmore gömde sin kista på Ranazjar Isle för att hindra att skatten hamnade i händerna på varelserna som anföll hans skepp.",al={"varför kistan är gömd","varför rackmores skatt","gömd skatt"}},{q="Vad hände med Rackmores skepp?",a="Rackmores loggbok berättar att sjöfarande varelser anföll hans skepp när det var på väg till Feathermoon Stronghold.",al={"skeppet anfölls","rackmores skepp","vad hände med skeppet"}}},fp="21,126,12.282.0,39.123.0,41.79.0,17.95.0,36.129.0,35.108.0"}
P.entries["item:rage-scar-yeti-hide"] = {n="Rage Scar Yeti Hide",s="Rage Scar Yeti Hide kommer från yetierna i Rage Scar Hold i norra Feralas. Pratt McGrubben och Jangdor Swiftstrider behöver skinnen i sitt läderarbete.",h="Rage Scar Yeti Hide kommer från yetierna i Rage Scar Hold i norra Feralas.",kw={"feralas","jangdor swiftstrider","läder","pratt mcgrubben","rage scar hold","rage scar yeti hide","rage scar-yetier","yetiskinn"},sec={{t="Ett bättre skinn",b="I norra Feralas ger yetierna i Rage Scar Hold skinn som läderarbetare värdesätter. Pratt McGrubben vid Feathermoon Stronghold och Jangdor Swiftstrider vid Camp Mojache behöver tio var till sitt arbete. De hoppas att skinnen ska visa sig vara lika tåliga som thorium när de har garvats."}},faq={{q="Varifrån kommer Rage Scar Yeti Hides?",a="Rage Scar Yeti Hides kommer från yetierna i Rage Scar Hold i norra Feralas.",al={"var får man tag på yetiskinn","källa till rage scar-skinn"}},{q="Vem vill ha skinnen?",a="Pratt McGrubben vid Feathermoon Stronghold och Jangdor Swiftstrider vid Camp Mojache behöver båda Rage Scar Yeti Hides.",al={"vem behöver skinnen","vem ska ha skinnet"}},{q="Varför är skinnen värdefulla?",a="Skinnet kan bli ovanligt tåligt när det har garvats, vilket gör det lovande för läderarbete.",al={"varför vill de ha yetiskinn","skinnets kvalitet"}},{q="Hur många skinn behövs?",a="Pratt McGrubben och Jangdor Swiftstrider ber båda om tio Rage Scar Yeti Hides.",al={"hur många","tio skinn"}}},fp="19,164,13.267.0,40.80.0,22.114.0,27.93.0,26.79.0"}
P.entries["item:ran-bloodtooth-s-skull"] = {n="Ran Bloodtooth's Skull",s="Ran Bloodtooth's Skull är en makaber trofé som tagits från de korrumperade furbolgernas hövding i Ashenvale. När den förs tillbaka till nattalverna i Astranaar blir den ett konkret bevis på att ett våldsamt hot mot skogsriket har undanröjts.",h="Ran Bloodtooth's Skull är en makaber trofé som tagits från de korrumperade furbolgernas hövding i Ashenvale.",kw={"ashenvale","astranaar","bloodtooths skalle","bloodtooth","furbolg","raene wolfrunner","raenes rening","ran bloodtooth"},ang={["faction:Alliance"]="Att överlämna denna dystra trofé visar att Alliansens mästare är redo att försvara Ashenvales sårbara gränser tillsammans med Sentinels.",["race:NightElf"]="För nattalverna är återtagandet av skallen en sorgsen seger. Den hedrar Teronis oavslutade uppdrag, men påminner också om hur djupt den demoniska korruptionen har härjat bland deras tidigare furbolgallierade."},sec={{t="En trofé från Ashenvales försvar",b="Ashenvales skogar har lidit svårt av demonisk besmittelse och vildmarkens fördärv, som drivit en gång fredliga furbolgstammar till mordiskt vansinne. En av de mest vildsinta fientliga hövdingarna var Ran Bloodtooth. När hans skalle återtas får nattalvernas Sentinels ett otvetydigt bevis på att besten har fallit, vilket bryter hans grepp om traktens furbolger och ger den hårt prövade staden Astranaar en viss respit."},{t="Hedra de fallna",b="När skallen överlämnas till Sentinel Raene Wolfrunner i Astranaar markerar den slutet på en undersökning som inleddes av den fallne spejaren Teronis. Tillsammans med Dartol's Rod, den återuppbyggda stav som Teronis gett sig av för att hitta, visas Ran Bloodtooth's Skull upp som ett vittnesmål om modet hos dem som kämpade för att bevara den heliga skogen."}},faq={{q="Vem var Ran Bloodtooth?",a="Ran Bloodtooth var en hövding bland de korrumperade furbolgerna i Ashenvale, och nattalvernas Sentinels betraktade honom som ett av de största hoten i området.",al={"vem är ran bloodtooth","ran bloodtooths bakgrund","vem var bloodtooth"}},{q="Varför vill Sentinels ha hans skalle?",a="Raene Wolfrunner i Astranaar tar emot skallen som bevis på att Ran Bloodtooth har besegrats. Den placeras tillsammans med Dartol's Rod som en symbol för segern och till minne av dem som stupade när de försvarade Ashenvale.",al={"varför behöver jag skallen","raene wolfrunners skalle","vad ska skallen användas till"}},{q="Vem var Teronis?",a="Teronis var en nära vän sedan länge till Raene Wolfrunner och hjälpte Sentinels i Ashenvale. Han gav sig av för att hitta en ädelsten till en stav som den döde magikern Dartol tillverkat, i hopp om att den skulle hejda furbolgernas attacker, men dödades av murlocs vid Lake Falathim. Raene Wolfrunner och besökande äventyrare tog över hans uppdrag.",al={"teronis bakgrund","vem är teronis","teronis astranaar"}}},fx={["4d0a3ce4"]={q="Vad är Ran Bloodtooth's Skull?",a="Det är Ran Bloodtooths avhuggna kranium. Han var ett av de våldsammaste och farligaste fördärvade furbolghoten som strök omkring i Ashenvale. Kraniet tas som bevis på att han besegrats och markerar slutet på den terror han riktade mot Sentinels och skogen.",al={"ran bloodtooths kranium","vad är rans kranium","ran bloodtooths huvud"}},f5c7858d={q="Varifrån kommer Ran Bloodtooth's Skull?",a="Kraniet tas direkt från Ran Bloodtooth efter att du dödat honom i Ashenvale. Det är ingen artefakt som dödliga händer har smitt eller tillverkat, utan en dyster trofé från hövdingen själv.",al={"varifrån kom rans kranium","vem skapade ran bloodtooths kranium","ran bloodtooths kranium källa"}}},fp="22,115,31.284.0,19.305.1,23.136.0,36.164.0,16.287.0"}
P.entries["item:ransom-letter"] = {n="Ransom Letter",s="Ransom Letter är ett hot från tjuvarna som håller Narains bok i Tanaris. Dess utklippta och inklistrade ord kräver pengar och ett möte utan sällskap.",h="Ransom Letter är ett hot från tjuvarna som håller Narains bok i Tanaris.",kw={"gnom","narain","synsk","lösen","ransom letter","lösensedel","stulen bok","tanaris"},ang={["race:Gnome"]="Som gnom kanske du känner igen Narains stolthet över sina synska förmågor. Den stulna boken och lös hotet gör honom rasande."},sec={{t="Ett utklippt hot",b="Narains försvunna bok leder till ett lösenkrav i Tanaris. Brevets ord är utklippta ur olika typsnitt och fastklistrade på pergament. Det lovar att boken ska återlämnas om kraven uppfylls och ger sedan utförliga instruktioner på tre sidor. Meddelandet avslutas med en rak order: ta med pengarna och kom ensam."},{t="Narains vrede",b="När Narain läser lösensedeln blir han knallröd i ansiktet. Gnomens löfte är att lära kidnapparna vad det innebär att ge sig på en synsk. Hans stulna bok har blivit en källa till både vrede och krav på betalning."}},faq={{q="Vem skrev lösensedeln?",a="Brevskrivaren namnges inte. Det står att kidnapparna har Narains bok och kräver pengar i utbyte.",al={"brevets skribent","vem skickade det","författare till lösensedel"}},{q="Vems bok blev stulen?",a="Boken tillhör Narain, en gnom i Tanaris.",al={"vem äger boken","narains bok","stulen bok"}},{q="Vad kräver brevet?",a="Kidnapparna kräver pengar och beordrar mottagaren att komma ensam.",al={"vad vill de ha","lösenkrav","ta med pengar"}},{q="Varför består brevet av utklippta ord?",a="Texten består av olika typsnitt som klistrats fast på pergament. Brevet förklarar inte varför de valt den metoden.",al={"typsnitt i lösensedel","utklippt och inklistrat brev","konstigt brev"}},{q="Hur reagerar Narain?",a="Narain blir knallröd i ansiktet och lovar att lära kidnapparna en läxa.",al={"narain arg","gnomens reaktion","vad säger narain"}}},fp="13,141,16.325.0,16.207.1,28.116.0,22.47.0,28.66.0,42.107.0,22.79.1"}
P.entries["item:raptor-head"] = {n="Raptor Head",s="Över hela The Barrens ger Raptor Head-troféer utdelning hos Gazrog vid The Crossroads. Vaktstyrkans lön försvann från ett vakttorn, och en vild raptor ertappades med stölden.",h="Över hela The Barrens ger Raptor Head-troféer utdelning hos Gazrog vid The Crossroads.",kw={"the barrens","the crossroads","gazrog","raptor head","raptortjuvar","stolen silver","sunscale"},ang={["class:Hunter"]="Att spåra Sunscale-raptors genom The Barrens torra snårmark sätter din skicklighet på prov mot savannens mest aggressiva och listiga flockjägare.",["faction:Horde"]="The Crossroads är hjärtat för hordens resor i centrala Kalimdor. När de tjuvaktiga rovdjuren röjs undan säkras garnisonens förnödenheter och löneutbetalningar."},sec={{t="The Crossroads belöning",b="En stulen kista med vaktstyrkans lön har lämnat vakttornet vid The Crossroads utan silver. Till försvararnas stora förvåning ertappade de en vild raptor på bar gärning. Gazrog har utlyst en belöning för de listiga reptiler som stryker omkring i The Barrens. Ta deras avhuggna huvuden till utposten, så gallras rovdjuren ut innan de hinner stjäla mer förnödenheter från horden."}},faq={{q="Varför vill Gazrog ha raptorhuvuden?",a="En kista med en leverans silver avsedd som lön åt vakterna vid The Crossroads stals från deras torn. Till allas förvåning ertappades en raptor på bar gärning. Gazrog vill att bestarna jagas över hela The Barrens så att de inte kan plundra bosättningen igen.",al={"varför samla raptorhuvuden","gazrog raptorer","belöning för raptorhuvuden"}},{q="Varför skulle vilda raptorer stjäla silver?",a="Gazrog medger att han inte har någon aning om varför vilddjur skulle vilja ha metallmynt. Raptors i Kalimdor är ökända för sin oroande list, och stölden gör vakterna vid The Crossroads generade och ivriga efter hämnd.",al={"varför vill raptorer ha silver","raptorer som stjäl mynt","mysteriet med raptortjuvarna"}},{q="Vilka raptorer kan man ta huvudena från?",a="Huvud kan fås från Sunscale-raptors som strövar omkring i centrala och södra The Barrens, bland annat Sunscale Lashtails, Screechers och Scytheclaws. Även ökända bestar som Ishamuhale och Takk the Leaper ger huvuden.",al={"var får man raptorhuvuden","vilka raptorer ger huvuden","raptorer i the barrens"}},{q="Vad händer när jag lämnar in huvudena?",a="När Gazrog fått tolv huvuden och raptorhotet minskat riktas uppmärksamheten mot att spåra vart den stulna silverleveransen egentligen fördes.",al={"vad händer efter raptortjuvarna","efter att ha samlat raptorhuvuden"}}},fx={["377da5ba"]={q="Varifrån kommer ett Raptor Head?",a="De här huvudena kommer direkt från de rovgiriga raptorer som stryker omkring på Barrens savanner och bergsryggar. Sunscale Lashtails, Screechers, Scytheclaws och andra framstående jägare på slätterna lämnar efter sig sådana när de dödas. De är biologiska kvarlevor som samlas in i fält, inte något som någon tillverkar, utan troféer från en lyckad jakt.",al={"varifrån kommer raptor heads","raptor head ursprung","vem skapade raptor head"}},f6102aac={q="Vad är Raptor Head?",a="Raptor Head är en avhuggen trofé och ett bevis på belöningen från raptorer som strövar omkring i Barrens, däribland lokala Sunscale-flockar och ökända bestar som Ishamuhale eller Takk the Leaper. Myndigheterna vid Crossroads kräver dessa makabra bevis för att styrka att de listiga rovdjur som hotar deras försörjningsleder och vakter har fällts.",al={"vad är raptor head","föremålet raptor head","vad är raptor heads"}}},fp="11,150,24.355.0,34.228.0,36.207.0,32.207.0,40.139.0"}
P.entries["item:rare-earth"] = {n="Rare Earth",s="Rare Earth är ett särskilt paket mineralrik jord från Darnassus för botaniska experiment på Teldrassil. Det skickas med bud från Dolanaar till örtkännaren Denalan vid hans läger nära Lake Al'Ameth.",h="Rare Earth är ett särskilt paket mineralrik jord från Darnassus för botaniska experiment på Teldrassil.",kw={"darnassus","denalan","dolanaar","örtmedicin","lake al'ameth","rare earth","syral bladeleaf"},ang={["profession:Herbalism"]="Örtkunniga uppskattar de omsorgsfulla insatserna från forskare som Syral Bladeleaf och Denalan, som studerar hur särskild jord kan förändra tillväxten och egenskaperna hos Teldrassils plantor.",["race:NightElf"]="För nattalver som vårdar sitt unga Världsträd ger varje botaniskt experiment vid Lake Al'Ameth insikt i hur livet anpassar sig till Teldrassils otämjda grenar."},sec={{t="Jord från Darnassus",b="Det nyväxta ekosystemet på Teldrassil kräver noggrann observation och omsorg, så örtkunniga över hela ön studerar hur olika växter reagerar på främmande eller näringsberikad jord. Just den här sällsynta jorden beställdes direkt från Darnassus av Denalan, en excentrisk botaniker som håller till längs den östra stranden av Lake Al'Ameth. Efter att ha blivit liggande under transporten och anlänt sent till Dolanaar låter örtkännaren Syral Bladeleaf resenärer på väg söderut leverera den ömtåliga jorden till Denalan innan dess kraft avtar."}},faq={{q="Vad används Rare Earth till?",a="Den sällsynta jorden är avsedd för Denalan, en örtkännare och botanisk forskare som slagit läger vid Lake Al'Ameths stränder. Han använder särskilda mineralföreningar och näringsberikad jord från Darnassus för att odla och experimentera med Teldrassils inhemska växter.",al={"användning av rare earth","vad gör denalan med rare earth","rare earths syfte"}},{q="Vem skickar Rare Earth till Denalan?",a="Syral Bladeleaf, en örtkännare i staden Dolanaar, har paketet. Det anlände sent från Darnassus, och hon ber äventyrare på väg söderut mot Lake Al'Ameth att leverera det åt henne.",al={"vem ger rare earth","var får man tag på rare earth","syral bladeleafs paket"}},{q="Varför oroade sig Denalan för leveransen?",a="Försändelsen blev försenad på vägen till Dolanaar, så Denalan fick vänta länge vid sjön. När han tar emot den oroar han sig genast för om jorden fortfarande är fräsch och livskraftig nog för hans botaniska experiment.",al={"är rare earth förstörd","denalans färska jord","varför är jorden sen"}}},fx={e720b4cb={q="Vad är Rare Earth?",a="Rare Earth är en leverans av särskilt utvald, bördig jord som skickas från Darnassus. Den förbereds och förpackas omsorgsfullt för känslig forskning inom jordbruk och botanik. Jorden behåller särskilda näringsämnen och måste levereras färsk för att behålla sin verkan i ömtåliga odlingsexperiment.",al={"vad är rare earth","föremålet rare earth","rare earth i berättelsen"}},["5312d2a9"]={q="Varför vill Denalan ha Rare Earth?",a="Denalan är en örtkunnig forskare som håller till vid Lake Al'Ameths östra strand. Där studerar och undersöker han Teldrassils lokala växtliv. Han förlitar sig på den här sällsynta, näringsrika jorden från Darnassus för att vårda sina ömtåliga planteringar och utveckla sitt botaniska arbete på ön.",al={"varför vill denalan ha rare earth","varför vilja ha rare earth","varför behövs rare earth"}}},fp="10,160,17.313.0,28.170.0,36.170.0,43.172.0"}
P.entries["item:raschal-s-report"] = {n="Raschal's Report",s="Raschal's Report berättar om ett silithidangrepp i sydöstra Feralas. Shandris Feathermoon skickar en kopia till Gracina Spiritmight i Temple of the Moon.",h="Raschal's Report berättar om ett silithidangrepp i sydöstra Feralas.",kw={"darnassus","feralas","gracina spiritmight","raschal","raschals rapport","shandris feathermoon","silithider","sydöstra feralas","temple of the moon"},ang={["class:Priest"]="Som präst bär du rapporten till Gracina Spiritmight, en prästinna vars kunskap om sådana varelser kan hjälpa Feralas försvarare.",["race:NightElf"]="Som nattalv tar du Shandris Feathermoons rapport till Gracina Spiritmight i Temple of the Moon, där hon känner igen silithidernas hot mot Feralas."},sec={{t="En kopia till Darnassus",b="I Feathermoon Stronghold ger Shandris Feathermoon dig en kopia av Raschal's Report om silithiderna i sydöstra Feralas. Huvudrapporten arkiveras i Darnassus. Den här kopian är till Gracina Spiritmight, en prästinna i Temple of the Moon som känner till sådana varelser."},{t="Temple of the Moons råd",b="Gracina Spiritmight tar emot dig i Temple of the Moon, där hon känner igen faran som beskrivs i Raschal's Report. Hon identifierar insekterna som silithider och varnar för att de snabbt kommer att förtära Feralas. Enligt henne är de verktyg för ett stort hot mot både Horde och Alliance, och hon ber om styrkan att besegra dem."}},faq={{q="Vad är Raschal's Report?",a="Raschal's Report beskriver silithidangreppet i sydöstra Feralas.",al={"raschals rapport","vad rapporten innehåller"}},{q="Vem är Raschal's Report till för?",a="En kopia av Raschal's Report är avsedd för Gracina Spiritmight, en prästinna vid Temple of the Moon i Darnassus.",al={"vem som får rapporten","rapport till gracina"}},{q="Vem ber dig att bära rapporten?",a="Shandris Feathermoon ger dig en kopia av Raschal's Report till Gracina Spiritmight.",al={"vem som skickade mig","shandris rapport"}},{q="Vad är det för insekter i rapporten?",a="Gracina identifierar insekterna som beskrivs i Raschal's Report som silithider.",al={"insekter i feralas","vad silithider är"}},{q="Varför behöver Gracina rapporten?",a="Gracina har omfattande kunskap om varelser som silithiderna, och Shandris tror att rapporten kommer att vara till nytta för dem alla.",al={"varför lämna den till gracina","rapport till templet"}}},fp="16,164,20.288.0,20.329.0,25.76.0,28.112.0,33.90.0,35.73.0,33.125.0"}
P.entries["item:rattlecage-skull"] = {n="Rattlecage Skull",s="Rattlecage Skull är kvarlevor av tanklösa odöda som strövar omkring i Deathknells förstörda utkanter. Noviser bland Forsaken-warlocks måste samla dessa förkalkade troféer åt Venya Marthand för att visa sin gryende viljestyrka och kvalificera sig för de mörka konsterna inom åkallan.",h="Rattlecage Skull är kvarlevor av tanklösa odöda som strövar omkring i Deathknells förstörda utkanter.",kw={"deathknell","åkalla en imp","piercing the veil","rattlecage skeleton","rattlecage skull","tirisfal glades","venya marthand"},ang={["class:Warlock"]="För Forsaken-warlocks är insamlingen av skallarna den första milstolpen i deras disciplin. Den visar att de har den kalla viljestyrka som krävs för att förslava sin första demon.",["race:Undead"]="Att krossa mindre, tanklösa skelett understryker Forsakens tro på att man hävdar sin dominans med ren viljestyrka och skiljer odöda med fri vilja från tanklösa slavar."},sec={{t="Ett prov för noviser",b="I Deathknells sollösa marker får nyuppståndna Forsaken med fallenhet för mörk magi vägledning av Venya Marthand. För att bevisa att en nybörjare har styrkan att kuva varelser från andra plan och få dem att lyda, ger Venya dem i uppgift att betvinga de kvarvarande Rattlecage Skeletons nära den förstörda smedjan. Att fälla dessa mindre odöda och hämta deras avhuggna skallar är både ett praktiskt prov i disciplin och en grund för ritualer innan de får lära sig att öppna en väg till tomrummet och förslava sin första demoniska tjänare."}},faq={{q="Vad används Rattlecage Skulls till?",a="Venya Marthand samlar in dem i Deathknell. Forsaken-warlocks måste ge henne tre skallar för att visa sin koncentration och beslutsamhet innan hon lär dem riterna för att åkalla och binda en imp.",al={"vad är rattlecage skulls","vad används rattlecage skull till","vem vill ha rattlecage skulls"}},{q="Var kommer Rattlecage Skulls ifrån?",a="De tas från de krossade kvarlevorna av Rattlecage Skeletons, tanklösa odöda som vandrar längs de igenvuxna vägarna och bland ruinerna nära Deathknells övergivna smedja.",al={"var hittar man rattlecage skulls","vem släpper rattlecage skulls","rattlecage skulls plats"}},{q="Varför kräver Venya Marthand skallarna till ett prov för warlocks?",a="Venya anser att makten undflyr de okunniga och att mästerskap kräver att man böjer yttre krafter efter sin vilja. Att döda de tanklösa skeletten och ta deras huvuden visar att en lärling har den grundläggande viljestyrka som krävs för att kontrollera kaotiska energier i stället för att uppslukas av dem.",al={"varför skallar till warlocks","venya marthands prov"}},{q="Vilka kunskaper får man efter att ha samlat skallarna?",a="När skallarna har överlämnats lär Venya Marthand ut den hemliga ritual som krävs för att kalla fram och binda en imp. Därmed får unga warlocks sin första verkliga demoniska tjänare.",al={"vad får man av rattlecage skulls","belöning för piercing the veil"}}},fx={["9627b388"]={q="Vad är en Rattlecage Skull?",a="En Rattlecage Skull är det avhuggna huvudet från ett Rattlecage Skeleton, en av de tanklösa odöda som vandrar omkring på de fördärvade markerna nära Deathknells övergivna smedja. För blivande Forsaken- häxmästare är de här dystra troféerna bevis på grundläggande magisk beslutsamhet och koncentration. De visar att en novis kan konfrontera och besegra de vandrande döda.",al={"vad är rattlecage skull","rattlecage skull i berättelsen"}}},fp="16,155,17.352.0,36.172.0,37.145.0,68.239.0,55.160.0"}
P.entries["item:raven-claw-talisman"] = {n="Raven Claw Talisman",s="Raven Claw Talisman är en helig Night Elf-relik knuten till Druids of the Talon. Den förvaras djupt inne i Ban'ethil Barrow Den på Teldrassil och är en av de fyra nödvändiga Relics of Wakening som krävs för att tryggt leda sovande druider tillbaka från The Emerald Dream.",h="Raven Claw Talisman är en helig Night Elf-relik knuten till Druids of the Talon.",kw={"athridas bearmantle","ban'ethil","gravkulle","dolanaar","druids of the talon","raven claw talisman","relics of wakening","teldrassil"},ang={["class:Druid"]="Talismanen är en symbol för Druids of the Talon och visar hur rituella fokus skyddar en druids ande när den vandrar i The Emerald Dream.",["race:NightElf"]="När du återfår reliken skyddar du både den uråldriga Night Elf-traditionen och livet på de sovande fränder som hotas av Gnarlpine furbolgs vansinne."},sec={{t="En nyckel till uppvaknandet",b="Raven Claw Talisman bevaras i en särskild kista i Ban'ethil Barrow Den, den underjordiska helgedomen där Teldrassils Druids of the Talon gick in i djup meditativ slummer. Druidernas dvala är en känslig andlig gräns. Om en druids band till den vakna världen bryts utan rätt ceremoniellt fokus riskerar anden att bli kvar i The Emerald Dream för alltid. Tillsammans med Black Feather Quill, Sapphire of Sky och Rune of Nesting behöver Athridas Bearmantle talismanen i Dolanaar för att utföra uppvakningsritualen och tryggt föra tillbaka de sovande."},{t="Hotet i gravkullen",b="När korrumperade Gnarlpine furbolgs invaderade Ban'ethil Barrow Den hamnade de heliga kistorna och de sovande druiderna i omedelbar fara. Furbolgernas vanhelgande skar av helgedomen från hjälp utifrån och utsatte relikerna för risken att gå förlorade eller förstöras. Athridas Bearmantle ger Teldrassils försvarare i uppdrag att trotsa gravkullens vindlande jordgångar och säkra Raven Claw Talisman innan de fördrivna druiderna går förlorade för The Emerald Dream för alltid."}},faq={{q="Vad används Raven Claw Talisman till?",a="Den är en av fyra heliga Relics of Wakening som behövs för ritualen som väcker Druids of the Talon ur deras djupa dvala i The Emerald Dream.",al={"vad gör raven claw talisman","raven claw talisman syfte","varför behöver jag raven claw talisman"}},{q="Var finns Raven Claw Talisman?",a="Den ligger i Chest of the Raven Claw, förvarad i de jordiga tunnlarna i Ban'ethil Barrow Den, väster om Dolanaar på Teldrassil.",al={"var finns raven claw talisman","var finns chest of the raven claw","hur hittar jag raven claw talisman"}},{q="Vem behöver Raven Claw Talisman?",a="Athridas Bearmantle, en Night Elf-druid stationerad i Dolanaar, behöver talismanen för att förbereda uppvakningsriterna för sina fördrivna fränder.",al={"vem vill ha raven claw talisman","vem tar emot raven claw talisman","vem lämnar jag in det till"}},{q="Varför kan inte druiderna vakna utan den?",a="Att träda in i The Emerald Dream genom druidisk dvala kräver en komplex och känslig trans. Utan Relics of Wakening som särskilt fokus för att förankra uppvakningsritualen riskerar den sovandes ande att förbli vilse i drömmen för alltid.",al={"varför behöver druider reliker för att vakna","varför relics of wakening","kan druider vakna utan reliker"}}},fx={["33636b37"]={q="Vad är Raven Claw Talisman?",a="Raven Claw Talisman är en av de fyra heliga Relics of Wakening som förvaras av Druids of the Talon. Den ligger i en särskild kista inne i Ban'ethil Barrow Den och är en viktig del av den känsliga ritual som krävs för att tryggt väcka druider ur deras dvala i Emerald Dream.",al={"vad är raven claw talisman","information om raven claw talisman","reliken raven claw talisman"}}},fp="19,210,18.440.0,28.413.0,41.164.0,39.153.0,34.139.0,40.175.0"}
P.entries["item:razorflank-s-medallion"] = {n="Razorflank's Medallion",s="Razorflank's Medallion är ett personligt kännetecken som Charlga Razorflank bär. Hon är häxan som styr Razorfen Kraul. Medaljongen återfanns i hjärtat av quilboarernas fäste och är ett obestridligt bevis på att matriarken har besegrats.",h="Razorflank's Medallion är ett personligt kännetecken som Charlga Razorflank bär.",kw={"agamaggan","charlga razorflank","falfindel waywarder","lonebrow","razorfen kraul","razorflank's medallion","thalanaar"},ang={["faction:Alliance"]="När medaljongen återtas hämnas den fallna spanaren Heralath och dvärgen och utforskaren Lonebrow. Samtidigt säkras Thalanaars gränsväg in i Feralas.",["race:NightElf"]="När Charlga dödas och hennes medaljong tas i besittning kan Night Elf tryggt undersöka Agamaggans fördärvade heliga viloplatser."},sec={{t="Bevis på häxans fall",b="Charlga Razorflank bär själv medaljongen. Den representerar häxans auktoritet över quilboarerna i Razorfen. När Falfindel Waywarder vid Thalanaar får höra om de fallna utforskarnas öden, som Heralath och dvärgen Lonebrow, ger han Alliansens äventyrare i uppdrag att slå till direkt mot quilboarernas ledare. När häxans medaljong visas upp bekräftar den hennes död. Det lugnar Night Elf-väktarna som bevakar Feralas gränser, eftersom de samlade styrkorna i Kraul har förlorat sin ledare."}},faq={{q="Vem bär Razorflank's Medallion?",a="Medaljongen tillhör Charlga Razorflank, häxan och den obestridda ledaren för quilboarerna i Razorfen Kraul. Hon bär den på sig djupt inne i fästets taggiga labyrinter.",al={"vem släpper razorflanks medaljong","källa till razorflanks medaljong","charlgas medaljong"}},{q="Vem vill att medaljongen ska föras till dem?",a="Falfindel Waywarder, som är stationerad vid gränsposten Thalanaar mellan Feralas och Thousand Needles, ber om medaljongen. Han vill ha den som slutgiltigt bevis på att Charlga har dödats.",al={"vem vill ha razorflanks medaljong","lämna in razorflanks medaljong","falfindels medaljong"}},{q="Varför behöver Falfindel bevis på att Charlga är död?",a="Charlga samlade en fientlig quilboarstyrka i Razorfen Kraul, hotade de omgivande områdena och orsakade spanare som Heralath och Lonebrow döden. När medaljongen förs tillbaka försäkras Night Elf om att det omedelbara hotet är undanröjt, så att deras undersökningar av området kan fortsätta.",al={"varför döda charlga","medaljongens syfte","varför behövs medaljongen"}}},fx={b119a669={q="Vad är Razorflank's Medallion?",a="Razorflank's Medallion är en personlig ägodel som bärs av Charlga Razorflank, den gamla häxan och ledaren för quilboar som bor djupt inne i Razorfen Kraul. Den är mer än en enkel prydnad. Den är en tydlig symbol för hennes makt över de svärmande stammarna i Kraul och den främsta trofén efter hennes fall.",al={"vad är razorflank medallion","razorflanks medallion i berättelsen","charlga razorflanks medallion"}}},fp="22,157,25.393.0,35.98.0,41.100.0,49.269.0"}
P.entries["item:reagent-pouch-shaman"] = {n="Reagent Pouch",s="Burning Blade-kultister i Durotar bär på ingredienser till en shamans första Fire Sapta. Telf Joolam använder dem tillsammans med Fire Tar från Razormane-quilboar för att brygga drycken som låter en ung shaman skåda eldens rike.",h="Burning Blade-kultister i Durotar bär på ingredienser till en shamans första Fire Sapta.",kw={"burning blade","call of fire","durotar","dustwind cave","fire sapta","fire totem","reagent pouch","telf joolam"},ang={["class:Shaman"]="Som shaman är återhämtningen av påsen en övergångsrit på vägen mot att förtjäna din Fire Totem. Den lär dig att fördärvade elementkrafter kan återtas och tjäna balansen.",["class:Warlock"]="Som häxmästare känner du igen påsarna som trolldomsutrustning för felkultister. Deras rituella element är avsedda för demonisk pyromanti, inte för gemenskap med naturen."},sec={{t="Flammans beståndsdelar",b="Burning Blade-kultister bär på ingredienser till en ung shamans första Fire Sapta. Eremiten Telf Joolam använder pulvren och oljorna i deras påsar tillsammans med Fire Tar från Razormane-quilboar. Tillsammans blir ingredienserna en dryck som låter shamanen skåda eldens rike och stämma sig med lågornas andar."},{t="Besudlade källor, ren syn",b="Burning Blade-kultister vänder lågan mot förstörelse och felmagi, men elementen i deras påsar hör fortfarande till hetta och förbränning. Shamaner lär att elementens krafter står i spänning med varandra: eld skapar lika väl som den förstör. En shaman kan ta kultisternas redskap och använda elementen för att väcka en sann gemenskap med andarna."}},faq={{q="Vad används Reagent Pouch till?",a="Telf Joolam använder ingredienserna för att brygga en Fire Sapta. När en shaman dricker den får hen visionär syn som låter hen söka elementandar och göra anspråk på Fire Totem.",al={"användning av reagent pouch","vad gör reagent pouch","reagent pouch schamanuppdrag"}},{q="Var hittar jag en Reagent Pouch?",a="Du kan hitta en påse hos Burning Blade-kultister i Dustwind Cave, bland de klippiga höjderna nordost om Razor Hill i Durotar.",al={"reagent pouch byte","var får man reagent pouch","burning blade-pungens plats"}},{q="Varför behöver en schaman reagenser från häxmästare?",a="Burning Blade-kultister fyller sina påsar med ingredienser knutna till eldmagi. Deras lågneritualer gör ingredienserna till användbara katalysatorer när en Fire Sapta bryggs.",al={"varför föremål från häxmästare","varför burning blade-reagenser","schaman använder fel-föremål"}}},fx={ad39cae0={q="Vad är Reagent Pouch?",a="Det är en liten påse som bärs av Burning Blade-kultister, fylld med de rituella örter, askor och ockulta katalysatorer som de använder för att driva sina mörka besvärjelser. Påsen är avsedd för mörk magi, men den höga koncentrationen av eldkomponenter gör den till en kraftfull samling råa elementmaterial.",al={"vad är reagent pouch","reagent pouch i berättelsen","burning blade reagent pouch"}},["2a611680"]={q="Varifrån kommer Reagent Pouch?",a="Påsarna sätts samman och bärs av Burning Blade-kultister som gömmer sig i grottorna i Durotar och Barrens. De här häxmästarna samlar in och förvarar särskilda komponenter för sina destruktiva riter, så att de alltid har dem nära till hands när de kastar eld- och skuggmagi.",al={"reagent pouchs ursprung","vem skapade reagent pouch","varifrån kom reagent pouch"}}},fp="13,209,23.316.0,28.307.0,35.189.0,32.126.0,40.160.0"}
P.entries["item:reconstructed-tome"] = {n="Reconstructed Tome",s="I händerna på warlocks samlar Reconstructed Tome sektens splittrade läror. Dess sidor innehåller riter för att kalla fram och binda en felhunter från Twisting Nether.",h="I händerna på warlocks samlar Reconstructed Tome sektens splittrade läror.",kw={"bindning","dragonmaw","feljägare","ratchet","reconstructed tome","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="Som warlock öppnar det att sammanställa Reconstructed Tome de mörka riterna för att kuva en felhunter. Dess hunger efter magi kan vändas mot fientliga besvärjare."},sec={{t="En grimoar fogas samman",b="Warlocks från Alliance och Horde söker efter de sönderrivna bladen ur Tome of the Cabal. De sätter ihop grimoaren igen och rådfrågar ockulta lärda, som ivrigt vill få en glimt av dess sällsynta läror innan den färdiga boken lämnas ifrån sig."},{t="Nyckeln till feljägaren",b="Strahad Farsan, en mästare på att kalla fram demoner nära Ratchets hamn i The Barrens, tar emot den återställda boken och kanaleringsstavar som tagits från Dragonmaw-besvärjare. Dess ritualer ger hans akolyter besvärjelser som hjälper en warlock att kalla fram en glupsk felhunter, kuva den och binda den till sin vilja."}},faq={{q="Vad används Reconstructed Tome till?",a="Reconstructed Tome innehåller sektens läror och ritualer för att kalla fram och binda en felhunter. En warlock tar med den och kanaleringsstavar till Strahad Farsan i Ratchet för ritualen.",al={"syftet med reconstructed tome","varför behövs reconstructed tome","användning av reconstructed tome"}},{q="Vem är Strahad Farsan?",a="Strahad Farsan är en expert på att kalla fram demoner och bor ovanför Ratchets hamn i The Barrens. Han övervakar prövningar för warlocks som vill kuva farligare demoner.",al={"vem är strahad","strahad farsans roll"}},{q="Varför vill de lärda som granskar boken ha en kopia?",a="De lärda som hjälper till att tyda de sönderrivna sidorna finner sektens ockulta texter sällsynta och fascinerande. Dvärgiska och Forsaken-forskare åtrår den demoniska kunskapen, som går bortom vad de brukar läsa.",al={"vem översatte den","lärda och reconstructed tome"}},{q="Vad behövs mer till ritualen utöver boken?",a="Strahad behöver tre kanaleringsstavar så att hans akolyter kan upprätthålla kallelseritualen. Dragonmaw-besvärjare i Wetlands har stavarna.",al={"andra föremål som behövs","vad behövs till reconstructed tome"}}},fx={a9385a16={q="Vad är Reconstructed Tome?",a="Reconstructed Tome är den hopfogade versionen av Tome of the Cabal, en förbjuden grimoar som innehåller esoteriska demonritualer. När de utspridda sidorna och inbindningsmaterialen har samlats in från olika delar av världen sätter lärda mödosamt ihop den fragmenterade texten, så att dess mörka kunskap kan tydas och användas.",al={"vad är reconstructed tome","reconstructed tome i berättelsen","boken tome of the cabal"}},d276d405={q="Varifrån kommer Reconstructed Tome, och vem skapade den?",a="Boken är den återfunna formen av den forntida Tome of the Cabal. Häxmästare sätter ihop dess sönderrivna kapitel och slitna inbindning efter att äventyrliga utövare har hämtat de utspridda delarna från farliga platser på kontinenterna.",al={"reconstructed tomes ursprung","vem skapade reconstructed tome","varifrån kom reconstructed tome"}},["04500ccd"]={q="Varför vill man ha Reconstructed Tome?",a="Häxmästare och mörka lärda söker efter boken för de kraftfulla, förbjudna hemligheter som står på dess återfunna sidor. Strahad Farsan behöver dess särskilda riter för att vägleda en blivande häxmästare genom att frammana och binda en våldsam demonisk felhunter. Lokala lärda vill ha ett exemplar enbart för dess sällsynta och fascinerande magiska kunskap.",al={"varför vill man ha reconstructed tome","varför vill strahad ha reconstructed tome","syftet med reconstructed tome"}}},fp="18,172,22.250.0,20.291.1,40.182.0,22.160.0,51.199.0,54.146.0"}
P.entries["item:recruitment-letter"] = {n="Recruitment Letter",s="Takrin Pathseeker skickar lovande äventyrare från Durotar västerut för att tjänstgöra i The Barrens. I brevet hänvisar han stridsdugliga frivilliga till gränsutposten som drivs av Kargal Battlescar.",h="Takrin Pathseeker skickar lovande äventyrare från Durotar västerut för att tjänstgöra i The Barrens.",kw={"barrens","värvad soldat i horden","the crossroads","kargal battlescar","razor hill","recruitment letter","takrin pathseeker"},ang={["faction:Horde"]="Som medlem av Horden markerar brevet att du går från lokalt försvar i Durotar till aktiv militärtjänst vid Kalimdors gränsland.",["race:Orc"]="Som ung ork är det ett tidigt steg mot att vinna ära under överhövding Thralls nya Horde att visa upp ett undertecknat tjänstgöringsbrev för en veteran som Kargal Battlescar."},sec={{t="Värvning till gränslandet",b="Takrin Pathseeker ser unga krigare och spejare visa vad de går för kring Razor Hill. Han väljer ut dem som verkar starka nog för tjänst vid fronten och ger dem ett brev med order om tjänstgöring i The Barrens. På andra sidan bron över Southfury River lämnar rekryterna Durotars skyddade röda jord och ansluter sig till Hordens försvar mot quilboar, centaurer och alliansens spejare."},{t="Anmälan hos Battlescar",b="Kargal Battlescar tar emot rekryterna vid utposten på andra sidan floden. Den härdade veteranen sköter utposten och bedömer varje värnpliktig innan han godkänner värvningen. En godkänd rekryt skickas snart längre västerut till The Crossroads, där gränsutposterna är hårt ansträngda."}},faq={{q="Vem skrev värvningsbrevet?",a="Takrin Pathseeker delar ut brevet. Orkspejaren är stationerad längs vägen från Razor Hill och håller utkik efter dugliga rekryter på väg västerut.",al={"vem delar ut värvningsbrevet","vem skrev det","takrin pathseeker brev"}},{q="Vart ska brevet lämnas?",a="Du tar brevet till Kargal Battlescar vid orkernas vaktpost på andra sidan bron över Southfury River, vid gränsen mellan Durotar och The Barrens.",al={"var lämnar jag värvningsbrevet","lämna in värvningsbrevet","vem ska jag ge det till"}},{q="Vad händer när brevet har undertecknats?",a="Kargal undertecknar dokumentet för att formalisera din värvning och beordrar dig sedan längre in på slätterna, till The Crossroads, där förstärkningar behövs omedelbart.",al={"vad händer när kargal har skrivit under","nästa uppdrag efter recruitment letter"}},{q="Varför tvångsrekryterar Horden äventyrare i Barrens?",a="Horden värvar äventyrare eftersom The Barrens är ett vidsträckt och farligt land som förbinder viktiga bosättningar i Horden. Centaurklaner, aggressiva Bristleback-quilboar och alliansens operationer håller hotet konstant, och befälhavarna vid fronten behöver varje arbetsför hand.",al={"varför rekryterar de","varför tvångsrekrytering i barrens"}}},fx={e6a35429={q="Vad är Recruitment Letter?",a="Recruitment Letter är ett officiellt inkallelsebrev som utfärdas till dugliga äventyrare i Durotar. Scout Takrin Pathseeker överlämnar det till dem som verkar starka nog att hjälpa Hordens växande närvaro i Barrens hårda gränsland. Brevet rekommenderar dem till befälhavarna vid militärposteringarna.",al={"vad är recruitment letter","recruitment letters syfte","vad är det här brevet"}},["6a5949ec"]={q="Varför vill Kargal Battlescar ha Recruitment Letter?",a="Kargal Battlescar befälhavare leder gränsposteringen som skyddar bron in till Barrens och behöver desperat dugliga rekryter för att förstärka gränsen. Det undertecknade brevet bekräftar att Scout Takrin Pathseeker har granskat dig och att du är redo att skickas dit Horden behöver dig mest.",al={"varför vill kargal ha brevet","varför lämna in recruitment letter","inlämnat recruitment letter"}}},fp="18,168,27.348.0,23.286.0,34.141.0,34.139.0,39.174.0,57.263.0"}
P.entries["item:red-burlap-bandana"] = {n="Red Burlap Bandana",s="I Northshire Valley samlar Deputy Willem in röda bandanor av säckväv från dödade Defias-tjuvar nära klostrets vingårdar. Tyget märker ut lågt rankade landsvägsrövare och ficktjuvar i Defias Brotherhood.",h="I Northshire Valley samlar Deputy Willem in röda bandanor av säckväv från dödade Defias-tjuvar nära klostrets...",kw={"bandana","tjuvarnas brödraskap","defias","mask","northshire","red burlap bandana","willem"},ang={["class:Rogue"]="Som en blivande skurk kan du lära dig av Northshires klumpiga fotknektar hur snabbt odisciplinerade fredlösa blir lätta mål för den lokala ordningsmakten.",["faction:Alliance"]="Som medlem av Alliance kan du se de röda bandanorna nå fram till tröskeln till Northshire Abbey, ett tecken på att Stormwind håller på att förlora kontrollen över rikets landsbygdsgränser."},sec={{t="Ett märke från Defias Brotherhood",b="Röda masker av säckväv utmärker de vanliga medlemmarna i Defias Brotherhood. Billigt, grovt tyg färgat rött döljer tjuvarnas ansikten och visar deras lojalitet mot det växande upproret. I Northshire bär unga rekryter och vanliga busar dessa halsdukar in i de östra fruktodlingarna. De lokala vakterna känner igen det iögonfallande röda tyget som bevis på att tjuvar har dödats i närheten."}},faq={{q="Varför vill Deputy Willem ha de här bandanorna?",a="Deputy Willem samlar in bandanorna som bevis på att en äventyrare har dödat busar från Defias nära Northshire Abbey. Tjuvarna bär det röda tyget öppet, vilket bekräftar att belöningen har hämtats ut.",al={"varför samla bandanor","willems bandanor","lämna in till tjuvarnas brödraskap"}},{q="Vem bär de röda bandanorna av säckväv?",a="Fotknektar och busar i Defias Brotherhood bär de röda bandanorna av säckväv. Det grova tyget döljer deras ansikten och visar deras lojalitet mot fredlösa.",al={"vem bär röd bandana","defias-maskernas bakgrund","vem släpper röda bandanor"}},{q="Varför är Defias-tjuvar verksamma i Northshire?",a="Defias-spejare och rövare slår läger på andra sidan bäcken öster om Northshire Abbey för att leta efter och stjäla förnödenheter. Klostrets garnison är hårt ansatt, så de närliggande fruktodlingarna ligger öppna för landsvägsrövare.",al={"varför är defias i northshire","tjuvar nära klostret"}},{q="Vad gör bandanorna röda?",a="Billig säckväv behandlad med scharlakansrött färgämne ger bandanorna deras röda färg. Nyansen är Defias Brotherhoods baner och uniform, så medlemmarna kan känna igen varandra ute i fält.",al={"varför är defias-masker röda","betydelsen av rött tyg"}}},fx={c4ebebb0={q="Vad är Red Burlap Bandana?",a="Red Burlap Bandana är den karakteristiska tygmask som bärs av medlemmar i Defias Brotherhood. Den är billigt tillverkad av grov säckväv och färgad röd. Den döljer bärarens ansikte och visar att personen tillhör det laglösa gänget. I Northshire är den ett direkt bevis på att en skurk har varit verksam öster om floden.",al={"red burlap bandanas identitet","vad är röda bandanas","defias bandana i berättelsen"}}},fp="18,180,25.319.0,43.189.0,34.148.0,47.188.0,28.172.0"}
P.entries["item:red-leather-bandana"] = {n="Red Leather Bandana",s="I Westfall markerar Red Leather Bandanas dem som trotsar Stormwinds krona. Defias Brotherhood bär dem som ansiktsskydd och tecken på sin sak.",h="I Westfall markerar Red Leather Bandanas dem som trotsar Stormwinds krona.",kw={"brödraskap","defias","galiaan","mask","red leather bandana","sentinel hill","westfall"},ang={["class:Rogue"]="Som skurk känner du igen den karmosinröda masken som ett tecken på underjordisk banditverksamhet i människornas länder, buren av tjuvar som organiserats med militär precision.",["faction:Alliance"]="För Alliansen markerar varje röd bandana som tas från en fallen fredlös en stråtrövare mindre som hotar Westfalls svältande bönder och hårt ansatta milis."},sec={{t="Brotherhoods märke",b="På Westfalls fält och övergivna gårdar bär stråtrövare, plundrare och upproriska arbetare karmosinröda bandanas för att dölja sina ansikten. People's Militia vid Sentinel Hill ser var och en som ett bevis på lojalitet mot Edwin VanCleefs laglösa brödraskap. Scout Galiaan samlar in bandanas från resande för att följa Brotherhoods rörelser och krympande antal i regionen."}},faq={{q="Varför bär Defias röda bandanas av läder?",a="Defias bär röda bandanas för att dölja sina ansikten när de plundrar gårdar och vägar, och för att visa sin lojalitet mot Edwin VanCleefs uppror mot Stormwind.",al={"defias-mask","varför röd bandana","defias-bandanas betydelse"}},{q="Vem vill att bandanas ska samlas in i Westfall?",a="Scout Galiaan från People's Militia vid Sentinel Hill ber resande att samla in bandanas. Han använder dem för att spåra gängets rörelser och bekräfta att kringströvande banditer har dödats.",al={"vem samlar in röda bandanas","galiaans bandana-uppdrag","lämna in bandana vid sentinel hill"}},{q="Var hittar man de här bandanas?",a="Defias skurkar, stråtrövare och smugglare bär de här bandanas vid läger, på fält och i gruvor runt om i Westfall.",al={"röd bandana byte","odla röda bandanas","vem släpper red leather bandana"}}},fp="19,153,23.372.1,44.153.1,47.179.0,31.112.0"}
P.entries["item:red-linen-bandana"] = {n="Red Linen Bandana",s="I hela Elwynn Forest känns Defias Brotherhood igen på Red Linen Bandana. Tyget döljer bärarens ansikte och kan komma traktens bosättare till nytta.",h="I hela Elwynn Forest känns Defias Brotherhood igen på Red Linen Bandana.",kw={"defiasmask","eastvale","elwynn forest","linne","red linen bandana","sara timberlain"},ang={["class:Rogue"]="Som skurk känner du igen det karmosinröda tyget knutet över nedre delen av ansiktet som ett kännetecken för landsvägsrövare och ficktjuvar i skogarna kring huvudstaden.",["profession:Tailoring"]="På landsbygden i Elwynn kan vävare använda linnet från banditernas masker till arbetskläder."},sec={{t="Defias märke",b="I hela Elwynn Forest bär fullvärdiga Defias-agenter vävda röda linnesnibbar. I Northshire Valley använder lägre rankade noviser och vanliga busar i stället grova säckvävsmasker. Det karmosinröda tyget döljer ett ansikte och visar lojalitet mot Edwin VanCleefs laglösa brödraskap. Det signalerar också deras uppror mot Stormwinds krona."},{t="Återbrukat tyg",b="Sara Timberlain vid Eastvale Logging Camp ber resenärer samla in snibbar från laglösa läger. Maskerna är knutna till banditer, men är gjorda av fint linne. Efter tvätt och sömnad kan bosättarna göra tåliga kläder och bandage av tyget åt skogens arbetare."}},faq={{q="Varför bär Defias röda linnesnibbar?",a="Defias-agenter bär röda linnesnibbar för att dölja ansiktet och visa sin lojalitet mot Edwin VanCleefs brödraskap och sitt trots mot Stormwind.",al={"vad defiasmasken betyder","varför röda masker","defias röd snibb"}},{q="Hur skiljer de sig från maskerna i Northshire?",a="Busar i Northshire Valley bär grova säckvävsmasker, medan etablerade Defias-agenter i hela Elwynn Forest bär finare rött linne.",al={"säckväv jämfört med linne","masker i northshire","säckvävssnibb"}},{q="Vem vill samla in snibbarna?",a="Sara Timberlain vid Eastvale Logging Camp vill ha snibbarna. Hon tvättar och repar upp maskerna för att väva praktiska kläder.",al={"vem tar emot röda linnesnibbar","sara timberlain snibb","lämna in snibbuppdrag"}},{q="Vilka fiender bär röda linnesnibbar?",a="Defias-agenter i hela Elwynn Forest bär röda linnesnibbar, däribland Defias Bandits, Ambushers, Rogue Wizards, hamnarbetare och ledare som Morgan the Collector.",al={"vem släpper red linen bandana","var man farmar snibbar","defias-snibbdropp"}}},fp="17,190,18.223.0,16.251.0,42.165.0,54.122.0,36.127.0,39.178.0"}
P.entries["item:red-wool-bandana"] = {n="Red Wool Bandana",s="Red Wool Bandana är provisoriska symboler som tillverkas av fängslade Defias-gangstrar i Stormwind Stockade. De slits från fängelsets yllefiltar och blir trotsiga tecken på brödraskap, även bakom galler.",h="Red Wool Bandana är provisoriska symboler som tillverkas av fängslade Defias-gangstrar i Stormwind Stockade.",kw={"defias","mac raskol","nikova raskol","red wool bandana","stormwind","blodets färg","the stockade"},ang={["faction:Alliance"]="För Alliansens försvarare är återtagandet av bandanorna en dyster rättvisegärning för unge Mac Raskol och ett slag mot upprorsmakarna som håller stadens fängelse.",["profession:Tailoring"]="De här grovt tillverkade bandanorna visar hur även grova yllefiltar kan repas upp och få nytt bruk i desperata händer i fångenskap."},sec={{t="Sydda i trots",b="Även djupt innanför de höga stenmurarna i Stormwind Stockade vägrar medlemmar av Defias Brotherhood att ge upp sin identitet. Med tygbitar som rivits från fängelsets yllefiltar tillverkar fångarna i hemlighet röda bandanas att bära som kännetecken. För vakterna är halsdukarna smuggelgods som utlöser dödliga myterier. För fångarna visar de att brödraskapet och upproret lever vidare, även i kedjor."},{t="En mormors hämnd",b="Bandanorna blev beryktade efter att den fjortonårige fängelsevakten Mac Raskol upptäckte fångar som rev sönder filtar för att tillverka dem. När han försökte tillrättavisa fångarna högg Defias-fångarna honom i ryggen. Efter hans död söker hans sörjande mormor Nikova upp äventyrare och ber dem bege sig in i fängelsehålan där upploppet pågår, döda upprorsmakarna och hämta det scharlakansröda tyget som bevis på hämnden."}},faq={{q="Var får fångarna tag på bandanorna i The Stockade?",a="Defias-fångar tillverkar dem genom att riva sönder sina yllefiltar från fängelset. Trots att de är avväpnade och fängslade gör de sina torftiga bäddar till trotsiga symboler att bära i cellerna.",al={"var bandanor kommer ifrån","bandanornas källa i fängelset","hur röda bandanor tillverkas"}},{q="Vem vill att bandanorna samlas in?",a="Nikova Raskol, en sörjande mormor i Stormwind, ber äventyrare samla in dem. Hennes fjortonårige sonson Mac var vakt i The Stockade och mördades av fångar efter att han kommit på dem med att tillverka bandanorna.",al={"vem behöver red wool bandana","uppdragsgivare för blodets färg","nikova raskol bandana"}},{q="Varför bryr sig fångarna så mycket om att bära röda halsdukar?",a="Defias Brotherhood bär röda masker och bandanas som sina främsta gängfärger och uniform. Bakom galler låter tillverkningen och bärandet av tygbitarna fångarna behålla sin rang, moral och sammanhållning.",al={"varför röda bandanor","defias röda symbol","röd bandanas betydelse"}},{q="Vilka fångar bär dem?",a="Nästan alla upproriska Defias-medlemmar i The Stockade bär dem, däribland Defias Captives, Inmates, Prisoners, Insurgents och Convicts.",al={"vem släpper red wool bandana","bandanadrops i fängelset"}}},fx={["7f0c1a2a"]={q="Vad är Red Wool Bandana?",a="Red Wool Bandana är en hemmagjord röd halsduk som tillverkas av fängslade medlemmar i Defias Brotherhood inne i Stormwind Stockade. Fångarna river sönder och färgar sina ullfiltar från fängelset för att göra tygmärken som öppet visar deras lojalitet till Brotherhood och bevarar deras gängidentitet bakom galler.",al={"vad är red wool bandana","föremålet red wool bandana","röd bandana från stockade"}}},fp="16,166,20.335.0,25.366.0,54.181.0,35.218.0,60.156.0,25.134.0"}
P.entries["item:remaining-drops-of-purest-water"] = {n="Remaining Drops of Purest Water",s="Över Kalimdor och Lordaeron samlar shamaner det Brine behöver till en brygd. De sista dropparna väntar på en farofylld färd.",h="Över Kalimdor och Lordaeron samlar shamaner det Brine behöver till en brygd.",kw={"brazier of everfount","brine","call of water","korrumperad manifestation","det renaste vattnet","silverpine forest","water totem"},ang={["class:Shaman"]="Som shaman bär du dropparna från det torra The Barrens till Silverpines pestdrabbade kust som en del av dina prövningar för att bemästra vatten. Denna pilgrimsfärd är avgörande för att du ska få ditt Water Totem.",["faction:Horde"]="Som medlem av Horde färdas du från Hordens områden i Kalimdor till de utsatta Forsaken-besittningarna i Silverpine. Pilgrimsfärden för med sig andlig rening mot Scourges pest över detta avstånd."},sec={{t="Ett botemedel för besudlat vatten",b="Brine bereder en vattenbrygd i The Barrens av vatten som samlats över Kalimdor och Lordaeron. En del av den ger shamaner syner av avlägsna element. De återstående dropparna sparas för ett svårare syfte. Shamaner bär dem till Silverpine Forests kust, nära The Sepulcher, där Brazier of Everfount står. Där bränns dropparna tillsammans med armbanden från en fallen, besudlad elementarvarelse. Det rena vattnet bryter igenom de odödas plagas fördärv och kallar på en obefläckad vattenande, som möter shamanerna och fullbordar deras förening med elementet."}},faq={{q="Vad används dropparna till?",a="Dropparna hälls på Brazier of Everfount vid Silverpine Forests kust tillsammans med armbanden från en fördärvad vattenmanifestation. Ritualen renar den fördärvade elementarhelgedomen och åkallar en ofördärvad vattenande.",al={"vad används dropparna till","dropparnas syfte","användning av det renaste vattnet"}},{q="Varifrån kommer vätskan?",a="De är den återstående delen av en renande brygd som beretts av Brine, en orchisk shaman som bor på en kulle i södra The Barrens. Han gör den under de andliga prövningarna för blivande shamaner.",al={"vem tillredde det renaste vattnet","dropparnas ursprung","brines vattendroppar"}},{q="Varför utförs ritualen ända borta i Silverpine Forest?",a="En vattenhelgedom vid Silverpines kust, väster om The Sepulcher, fördärvades av odödhetens pest. Dess elementarandar blev fientliga och förvridna. Att rena den pölen prövar en shamans hängivenhet och mästerskap över stora avstånd.",al={"varför silverpine forest","varför resa till silverpine forest","silverpine forests vattenhelgedom"}},{q="Vad händer när dropparna vidrör fyrfatet?",a="När dropparna hälls på eldfatet tillsammans med de fördärvade armbanden fräser de i lågorna. Besvärjelsen renar de kvarvarande pestspåren och åkallar en ren vattenmanifestation.",al={"fyrfatsritual","vad händer vid fyrfatet","ritualen vid brazier of everfount"}}},fx={db79eea5={q="Vad är Remaining Drops of Purest Water?",a="Den här lilla flaskan innehåller de sista resterna av den renande dryck som eremiten Brine bryggde i södra Barrens. Den kraftfulla vätskan är laddad med vatten från Barrens, Tarren Mill och Ashenvale och har en enormt renande verkan. Det finns bara några droppar kvar, men deras koncentrerade renhet räcker för att tränga igenom kvardröjande fördärv när de används i elementritualer.",al={"vad är remaining drops of purest water","vad är purest water drops","drops of purest water i berättelsen"}},["55d7092f"]={q="Varför vill Islen Waterseer att du använder Remaining Drops of Purest Water?",a="Islen Waterseer vill att du häller dropparna över Brazier of Everfount i Silverpine Forest. En helig vattenhelgedom där har dukat under för de odödas pest, som gjort att dess lokala andar inte längre hör shamanernas böner. Om du offrar de sista dropparna tillsammans med armbanden från en fallen, fördärvad manifestation kan eldfatet tända en reningsritual som är kraftfull nog att kalla fram en ren vattenande.",al={"varför använda drops of purest water","varför behövs remaining drops of purest water","varför behövs drops of purest water"}}},fp="31,152,27.549.0,30.221.0,31.181.0,61.235.0,41.179.0"}
P.entries["item:remedy-of-arugal"] = {n="Remedy of Arugal",s="Remedy of Arugal är en besvärjelse som skrevs ned av magikern Arugal under hans tidiga experiment med worgenmagi.",h="Remedy of Arugal är en besvärjelse som skrevs ned av magikern Arugal under hans tidiga experiment med...",kw={"arugal","arugal's folly","dalar dawnweaver","dammiga trollböcker","moonrage","remedy of arugal","the sepulcher","silverpine forest"},ang={["class:Mage"]="Fördärvade magiker kommer att dela Dalar Dawnweavers yrkesmässiga förakt för Arugals klumpiga, vårdslösa experiment, men inser samtidigt faran med okontrollerad åkallningsmagi.",["race:Undead"]="För de Fördärvade är det livsviktigt att säkra den här besvärjelsen tidigt, så att de kan slå tillbaka mot de vilda worgen som hotar Silverpine Forests gränser."},sec={{t="En magikers kvarlämnade skrifter",b="Innan ärkemagikern Arugal lade beslag på Shadowfang Keep tog han sin tillflykt till en övergiven vetegård norr om flodbron i Silverpine Forest. Där dokumenterade han sina märkliga konster i dammiga trollböcker, bland bortglömda jordbruksredskap och ruttnande golvplankor. Rullen med titeln Remedy of Arugal finns bland anteckningarna och beskriver tidiga metoder och magiska formler som han utarbetade medan han prövade de farliga förvandlingar som förbannade traktens invånare."},{t="De bortglömda granskar",b="Dalar Dawnweaver, en skicklig Fördärvad besvärjare verksam från The Sepulcher, hyser föga respekt för Arugals börd och avfärdar den forne Dalaran-trollkarlens intellekt som bräckligt och genomskinligt. Ändå inser Dawnweaver att det är brådskande att förstå den exakta mekaniken bakom worgenförbannelsen. Genom att återta Remedy of Arugal förser Fördärvade agenter Dawnweaver med den grundläggande arkanan som krävs för att hejda Arugals växande hot och trygga Silverpine åt Lady Sylvanas."}},faq={{q="Vad är Remedy of Arugal?",a="Det är en magisk formel som den förrädiske magikern Arugal skrev ned. Det är ingen läkande dryck, utan en nedtecknad besvärjelse med de arkaniska tekniker han använde när han först började experimentera med worgenmagi i Silverpine Forest.",al={"vad är remedy of arugal","arugals remedy-föremål","remedy-besvärjelse"}},{q="Var lämnades Remedy?",a="Arugal lämnade den bland dammiga trollböcker på övervåningen i en övergiven vetegård, strax norr om bron som går över floden i Silverpine Forest.",al={"var hittar man remedy of arugal","remedy of arugal plats","gårdens trollbok"}},{q="Varför vill Dalar Dawnweaver ha besvärjelsen?",a="Dalar Dawnweaver vill analysera den specifika magi som Arugal använde, så att de Fördärvade kan utveckla motmedel. Förhoppningen är att vända trollkarlens egna metoder mot honom och trygga trakten.",al={"varför vill dalar ha remedy","dalar dawnweaver remedy"}},{q="Vem vaktar trollböckerna på gården?",a="Gården kryllar av Arugals varglika träl. När någon försöker röra de dammiga trollböckerna på andra våningen kastar sig en Moonrage Darkrunner fram ur skuggorna för att försvara sin herres tillhörigheter.",al={"vad anfaller på gården","bakhåll vid trollboken"}}},fx={["157696b2"]={q="Varifrån kommer Remedy of Arugal, och vem skapade den?",a="Remedy of Arugal är en besvärjelse som är nedtecknad av ärkemagikern Arugal själv under hans första tid i Silverpine Forest. När hans planer började ta form bodde han en kort tid på en vetegård norr om den stora flodbron. Där lämnade han efter sig dammiga spellböcker med sina efterforskningar.",al={"vem skapade remedy of arugal","remedy of arugals ursprung","varifrån kom remedy of arugal"}}},fp="16,96,18.379.0,17.375.0,29.124.0,33.136.0,42.113.0,38.171.0"}
P.entries["item:rendered-spores"] = {n="Rendered Spores",s="Rendered Spores är en flyktig emulsion som framställs av svampprover från The Barrens. Apothecary Helbrim tillverkar blandningen vid The Crossroads, men den bryts snabbt ner om den inte snarast förs till Apothecary Zamah under Thunder Bluff för stabilisering.",h="Rendered Spores är en flyktig emulsion som framställs av svampprover från The Barrens.",kw={"apothecary helbrim","apothecary zamah","the barrens","the crossroads","emulsion","the pools of vision","rendered spores","thunder bluff"},ang={["race:Tauren"]="Att Forsaken-apotekare experimenterar med märklig flora från The Barrens i de heliga The Pools of Vision speglar den oroliga men praktiska allians som har formats i Thunder Bluff.",["race:Undead"]="Royal Apothecary Society söker ständigt efter nya biologiska ämnen över hela Kalimdor för att hjälpa Forsaken. De förlitar sig på snabba kurirer för att knyta samman fältforskare som Helbrim med laboratoriespecialister som Zamah."},sec={{t="En flyktig blandning",b="Efter att ha hämtat märkliga svampsporer från svampar nära The Barrens fuktiga oaser bearbetar Apothecary Helbrim dem till en aktiv kemisk emulsion som kallas Rendered Spores. Den varsamma extraktionen suspenderar svamparnas kraftfulla ämnen i ett flytande medium, men lösningen är kemiskt instabil. Den behåller sin verkan i bara fyrtiofem minuter innan den bryts ner och blir helt oanvändbar för vetenskapliga studier."},{t="Leverans till The Pools of Vision",b="Eftersom Helbrim saknar nödvändig utrustning och tid vid sin avlägsna utpost för att slutföra reningen måste emulsionen snabbt föras direkt till hans Forsaken-kollega, Apothecary Zamah. Zamah håller till i de underjordiska The Pools of Vision under Spirit Rise i Thunder Bluff och har den specialutrustning och de reagenser som krävs för att återförsluta och färdigställa bearbetningen av sporerna åt Royal Apothecary Society."}},faq={{q="Vad används Rendered Spores till?",a="De är svampmaterial som Apothecary Helbrim har extraherat och omvandlat till en emulsion för Royal Apothecary Societys forskning. Apothecary Zamah använder den kraftfulla blandningen i Thunder Bluff för att fortsätta deras undersökning av de märkliga växter som sprider sig över The Barrens.",al={"syftet med rendered spores","vad gör zamah med sporerna","varför rendered spores"}},{q="Varför har emulsionen en tidsgräns?",a="Den kemiska emulsion som Helbrim skapar är mycket flyktig och börjar brytas ner så snart den blandas. Den behåller sin verkan i bara fyrtiofem minuter, så en kurir måste snabbt föra den över slätterna till Thunder Bluff innan den blir verkningslös.",al={"varför är rendered spores tidsbegränsade","varför blir sporerna förstörda","hur länge varar rendered spores"}},{q="Vem skapade dessa sporer?",a="Apothecary Helbrim, en Forsaken-forskare stationerad vid The Crossroads i The Barrens, omvandlade råa svampsporer från svampar nära oaserna till denna instabila flytande blandning.",al={"vem skapade rendered spores","vem omvandlar sporerna","helbrims sporer"}},{q="Vart ska blandningen föras?",a="Sporerna måste levereras till Apothecary Zamah. Hon bor djupt inne i The Pools of Vision, ett grottsystem dolt under Spirit Rise i taurenfolkets huvudstad Thunder Bluff.",al={"vart ska rendered spores föras","zamahs plats","var ligger pools of vision"}}},fx={["7897c588"]={q="Vad är Rendered Spores?",a="Rendered Spores är ett bearbetat extrakt från märkliga svampar som samlats in runtom i Barrens. Apothecary Helbrim kokade och smälte ner de råa sporerna till en flyktig och instabil vätskeemulsion. Han förberedde blandningen noggrant för vidare alkemiska studier av Royal Apothecary Society.",al={"vad är rendered spores","information om rendered spores"}}},fp="15,153,18.219.0,31.310.0,34.217.0,40.211.0,25.134.0,34.120.0"}
P.entries["item:renferrel-s-findings"] = {n="Renferrel's Findings",s="Renferrel's Findings är en samling forskningsanteckningar sammanställda av Apothecary Renferrel i Silverpine Forest. Dessa dokument har anförtrotts åt hordens kurirer och för med sig viktiga uppgifter söderut till Apothecary Lydon i Tarren Mill, för att hjälpa till att brygga de Fördärvades nya farsot.",h="Renferrel's Findings är en samling forskningsanteckningar sammanställda av Apothecary Renferrel i Silverpine...",kw={"forskningsresultat","lydon","ny farsot","renferrel","royal apothecary society","the sepulcher","tarren mill"},ang={["faction:Horde"]="Kurirer som transporterar Renferrel's Findings hjälper till att befästa hordens fotfäste i Lordaeron och knyter samman isolerade utposter som The Sepulcher och Tarren Mill.",["race:Undead"]="Forskningen i dokumenten tjänar Sylvanas Windrunners yttersta ambition: att fullända en ny farsot som utrotar både Scourge och de levande fiender som tränger in på de Fördärvades marker."},sec={{t="En farsot under utveckling",b="Royal Apothecary Society arbetar outtröttligt på order av den mörka damen, Lady Sylvanas Windrunner, för att skapa en ny farsot. För att nå detta genombrott krävs ett ständigt samarbete mellan forskare spridda över Lordaeron. Apothecary Renferrel är stationerad vid The Sepulcher i Silverpine Forest. Han sammanställer dessa rön för att dokumentera sina framsteg och experiment, och skickar uppgifterna söderut till Tarren Mill så att andra forskare kan bygga vidare på hans resultat."},{t="Till Tarren Mill",b="Att föra de här dokumenten över gränsen från Silverpine till Hillsbrad Foothills utgör en viktig länk i de Fördärvades alkemistiska nätverk. I Tarren Mill väntar Apothecary Lydon ivrigt på Renferrel's Findings för att jämföra uppgifterna och utveckla sina egna brygder mot de levande och Scourge. Utan pålitliga kurirer som färdas längs Hillsbrads omstridda vägar skulle sällskapets decentraliserade forskning snabbt stanna av."}},faq={{q="Vad finns i Renferrel's Findings?",a="Paketet innehåller de senaste experimentella uppgifterna och forskningsanteckningarna som Apothecary Renferrel samlat under sitt arbete i Silverpine Forest, särskilt om framställningen av en ny farsot åt de Fördärvade.",al={"vad är forskningsresultaten","renferrels forskning","vad finns i anteckningarna"}},{q="Vem ska ta emot forskningsmaterialet?",a="Apothecary Lydon tar emot dokumenten. Han forskar om farsoter i Tarren Mill, en bosättning för de Fördärvade i Hillsbrad Foothills.",al={"vem får renferrels forskningsresultat","vart skickas forskningsresultaten","mottagare av leveransen"}},{q="Varför delar apotekarna anteckningar?",a="Lady Sylvanas Windrunner har satt Royal Apothecary Society under enorm press att uppfinna en ny farsot. Apotekarna tror att genombrottet kommer mycket snabbare om de samordnar sig och jämför resultat i stället för att arbeta var för sig.",al={"varför dela forskningsresultat","varför skicka till lydon","kommunikation mellan apotekare"}},{q="Var utför Apothecary Renferrel sina experiment?",a="Apothecary Renferrel är stationerad vid The Sepulcher, den främsta utposten för de Fördärvade, mitt i Silverpine Forest.",al={"var är renferrel","apothecary renferrels plats","vem skrev renferrels forskningsresultat"}}},fx={f680c460={q="Vad är Renferrel's Findings?",a="Renferrel's Findings är en samling alkemiska anteckningar och forskningsdokument som har sammanställts av Apothecary Renferrel. De beskriver hans pågående experiment på uppdrag av Royal Apothecary Society och är avsedda att delas direkt med hans kollegor i Lordaeron.",al={"vad är renferrels findings","föremålet renferrels findings","vad är de här fynden"}},bf8d559a={q="Varifrån kommer Renferrel's Findings, och vem skapade dem?",a="De här dokumenten skrevs av Apothecary Renferrel, en ambitiös forskare stationerad vid The Sepulcher i Silverpine Forest. På uppdrag av Forsaken antecknade han noggrant sina framsteg och genombrott när han blandade experimentella brygder.",al={"vem skrev renferrel's findings","varifrån kommer renferrel's findings","renferrel's findings skapare"}},["21b2c0f4"]={q="Varför vill någon ha Renferrel's Findings?",a="Royal Apothecary Society är under hård press från Lady Sylvanas Windrunner att ta fram en ny pest. Renferrel tror att samarbete kommer att påskynda deras mörka arbete och skickade därför sin forskning till Apothecary Lydon i Tarren Mill. Lydon vill gärna studera sin kollegas metoder och använda dem i sitt eget arbete.",al={"varför lämna över renferrel's findings","vem vill ha renferrel's findings","varför vill lydon ha renferrel's findings"}}},fp="20,209,23.354.0,14.377.0,36.173.0,41.139.0,39.189.0,56.127.0"}
P.entries["item:report-on-the-defias-brotherhood"] = {n="Report on the Defias Brotherhood",s="I Stormwind Keep når en rapport om Defias Brotherhood det kungliga hovet med resultatet av en lång utredning. Stadsarkitekten Baros Alexston överlämnar den till äventyraren som avslöjade konspirationen.",h="I Stormwind Keep når en rapport om Defias Brotherhood det kungliga hovet med resultatet av en lång utredning.",kw={"audiens hos kungen","baros alexston","defias","rapport","stormwind keep","vancleef","westfall"},ang={["faction:Alliance"]="När du levererar rapporten når den kungliga hovet efter den långa kampen för att säkra Westfall och varna Stormwinds ledare för upproret vid rikets gränser.",["race:Human"]="Som människa i riket bär du på en rapport som speglar den olösta konflikten mellan Stormwinds adelshus och stenhuggarna som återuppbyggde staden."},sec={{t="En rapport till tronen",b="Stadsarkitekten Baros Alexston sammanställde en rapport åt Stormwinds ledare efter en lång utredning av oroligheterna i Westfall och närliggande områden. Han anförtrodde dokumentet åt äventyraren som nystade upp konspirationen. Rapporten förs till Stormwind Keep, där den ska åtfölja en personlig audiens om konspiratörernas planer och faran de utgör för kungariket."},{t="Mottagandet i borgen",b="Kung Varian Wrynn är bortrest på en diplomatisk resa när kuriren når tronsalen. Kungliga rådgivare och förmyndarregeringen, som styr för barnekungen Anduin, tar emot rapporten i hans ställe. De berömmer kuriren för att ha stoppat VanCleefs planer. Lady Katrana Prestor hör till hovets närvarande personer när varningarna når förmyndarregeringen."}},faq={{q="Vad är Report on the Defias Brotherhood?",a="Report on the Defias Brotherhood är en officiell rapport från Baros Alexston med underrättelser om Edwin VanCleef, hans underjordiska armé och den större Defias-konspirationen mot Stormwind.",al={"vad är den här rapporten","defiasrapport föremål","baros alexstons rapport"}},{q="Vem skrev rapporten?",a="Baros Alexston, Stormwinds stadsarkitekt, sammanställde rapporten. Han arbetade en gång tillsammans med stenhuggarna, innan de bröt sig loss och bildade Defias Brotherhood.",al={"vem skrev defiasrapporten","rapportens författare"}},{q="Varför levererar jag detta till Stormwind Keep?",a="Baros Alexston anser att äventyraren som avslöjade konspirationen förtjänar att lägga fram resultaten inför tronen och få kungligt erkännande för att ha skyddat riket.",al={"varför levererar jag detta","leverans inför kungen"}},{q="Läser kung Varian rapporten?",a="Nej. Kung Varian Wrynn är bortrest på en diplomatisk resa när du når Stormwind Keep. Hans hov och förmyndarregeringen tar emot rapporten i hans ställe.",al={"läser kungen rapporten","audiens hos varian wrynn"}}},fp="32,178,25.367.0,21.337.1,45.170.1,22.160.1,43.182.0,33.138.0"}
P.entries["item:resonite-crystal"] = {n="Resonite Crystal",s="Resonite Crystal är sällsynta mineralprover som kobolder bryter inne i Boulderslide Cavern i Stonetalon Mountains. Deras febrila grävande har väckt oro hos Mor'rogal vid Sun Rock Retreat.",h="Resonite Crystal är sällsynta mineralprover som kobolder bryter inne i Boulderslide Cavern i Stonetalon...",kw={"boulderslide","kristall","jordbunden","kobold","mor'rogal","resonite","stonetalon","titaner"},ang={["class:Shaman"]="Resonite Crystal bär på en oroande resonans för schamaner, som kan känna igen den vilande, ursprungliga jordmagin som titanernas skapelser lämnat efter sig, djupt begravda under bergen.",["profession:Mining"]="Till skillnad från vanliga koppar- eller tennådror är Resonite en mineralformation med mycket hög koncentration. För att utvinna den måste man tränga förbi aggressiva kobolder och ner i de djupaste underjordiska lagren."},sec={{t="Uråldrig resonans",b="Djupt inne i Boulderslide Ravine ligger Resonite Crystal, som blivit målet för koboldernas plötsliga, febrila grävande. Vanliga grottgruvarbetare söker oftast efter vardagliga malmer eller glänsande prydnader, men koboldernas besatthet av just dessa formationer oroade genast schamanerna vid Sun Rock Retreat. Vid närmare undersökning visar det sig att stenarna brummar av en svag magisk resonans, knuten till världens ursprungliga skapelse. Mor'rogal identifierade dessa svaga energier som spår av jordisk magi, ett tecken på att de grävande varelserna brutit igenom till ett forntida lager som skapats av titanerna."},{t="Att röra vid jorden",b="Upptäckten av Resonite bekräftar oroande nyheter för Hordens närvaro i Stonetalon: koboldgrävarna har nått så djupt att de stört de forntida jordbundna. Titanerna formade de jordbundna direkt för att hugga ut och forma världens grundvalar, och därför dröjer sig rester av magi envist kvar i den omgivande stenen. Genom att samla in dessa kristaller hoppas Hordens agenter kunna tyda koboldernas febrila avsikter och vända den förtrollade stenens egen kraft mot de slumrande krafter som störts där nere."}},faq={{q="Var finns Resonite Crystal?",a="Resonite Crystal finns inne i Boulderslide Cavern, en djup grotta i Boulderslide Ravine, i den sydöstra delen av Stonetalon Mountains.",al={"resonite-plats","var hittar man resonite","farma resonite crystal"}},{q="Varför bryter kobolderna Resonite Crystal?",a="Kobolderna bryter febrilt de sällsynta kristallerna, men Mor'rogal vet ännu inte varför. Han ber om prover och en undersökning av grottans djup för att förstå deras verksamhet.",al={"varför bryter kobolder","koboldernas kristallplan","kobolder i boulderslide"}},{q="Vilken kraft finns i en Resonite Crystal?",a="Mor'rogal misstänker att kristallerna har koppling till något oroande under bergen. Deras magiska natur blir tydlig när prover och nyheter från grottan når honom.",al={"resonite crystals magi","vad är resonite","är resonite magiskt"}},{q="Vem studerar kristallerna?",a="Mor'rogal, en tauren vid Sun Rock Retreat i Stonetalon Mountains, undersöker kristallerna för att förstå den plötsliga ökningen av koboldernas aktivitet och hitta ett sätt att bekämpa ondskan som grävts fram.",al={"vem vill ha resonite","mor'rogal kristaller","resonite vid sun rock retreat"}},{q="Vilka är de jordbundna som nämns i samband med kristallen?",a="De jordbundna är varelser som sägs ha skapats av titanerna för att forma landet. Deras möjliga koppling till Resonite undersöks under Mor'rogals uppdrag.",al={"vad är de jordbundna","jordbundna och titanerna"}}},fx={c14b6c8c={q="Vad är Resonite Crystal?",a="Resonite är en sällsynt mineralkristall som finns i Boulderslide Cavern i Stonetalon Mountains. Koboldernas febrila grävande har oroat Mor'rogal, som ber om prover och nyheter från grottan för att undersöka saken.",al={"vad är resonite","resonite crystal bakgrund","resonite-malm"}},af246400={q="Varför vill någon ha Resonite Crystal?",a="Mor'rogal vill ha malmprover för att förstå koboldernas febrila grävande och ta reda på vad som finns under Boulderslide Ravine. Han ber en äventyrare att utforska grottan och samla in kristallerna.",al={"varför samla resonite crystal","vem vill ha resonite crystal","vad används resonite crystal till"}}},fp="16,131,17.290.1,17.334.1,34.123.0,45.172.0,44.170.0,31.194.0,60.129.0"}
P.entries["item:restabilization-cog"] = {n="Restabilization Cog",s="Restabilization Cogs är precisionskomponenter som bärgats från de spetälska gnomerna som strövar omkring utanför de bestrålade ruinerna av Gnomeregan. I Kharanos behöver de gnomiska uppfinnarna dessa oskadade delar för att bygga Recombobulator, en ambitiös maskin som ska häva den spetälska mutationen.",h="Restabilization Cogs är precisionskomponenter som bärgats från de spetälska gnomerna som strövar omkring...",kw={"dun morogh","gibblewilt","gnomeregan","kharanos","spetälsk gnom","operation recombobulation","razzle sprysprocket","restabilization cog"},ang={["profession:Engineering"]="Restabilization Cogs exakta toleranser visar på klassisk gnomisk formgivning. De är byggda för att tåla oberäknelig friktion och balansera känsliga mekaniska enheter som Recombobulator.",["race:Gnome"]="För de landsflyktiga gnomerna i Dun Morogh är det en sorgsen plikt att hämta dessa komponenter: att plocka maskindelar från fördärvade fränder i det desperata hoppet om att bygga ett botemedel för Gnomeregans fallna."},sec={{t="Komponenter till ett botemedel",b="När strålning översvämmade Gnomeregan i ett katastrofalt försök att utplåna de invaderande troggarna förvandlades otaliga gnomer till sjuka och fientliga spetälska gnomer. Trots sin galenskap bär dessa drabbade landsflyktingar fortfarande på avancerade gnomiska maskiner och delar som kan bärgas. Uppfinnarna Ozzie Togglevolt och Razzle Sprysprocket tror att den fruktansvärda förvandlingen kan hävas systematiskt. För att färdigställa sin prototyp, Recombobulation Device, behöver de äventyrare som hämtar viktiga delar direkt från de drabbade utanför Gnomeregans portar, däribland oskadade Restabilization Cogs som balanserar maskinens inre förbränningssystem."}},faq={{q="Vad används en Restabilization Cog till?",a="Uppfinnaren Razzle Sprysprocket i Kharanos behöver Restabilization Cogs. Tillsammans med Gyromechanic Gears är de viktiga konstruktionsdelar till Recombobulator, en experimentell uppfinning som ska bota bestrålade spetälska gnomer.",al={"kugghjulets syfte","vad gör restabilization cog","varför samla kugghjul"}},{q="Var hittar man dessa kugghjul?",a="De bärs av de vansinniga spetälska gnomerna och den förvirrade Gibblewilt, som strövar omkring vid portarna och i skyttegravarna utanför Gnomeregan i västra Dun Morogh.",al={"var finns restabilization cog","vem släpper kugghjul","var kan man samla kugghjul"}},{q="Kan Recombobulator verkligen bota de spetälska gnomerna?",a="Razzle Sprysprocket och Ozzie Togglevolt är övertygade om att rätt kalibrerade maskiner kan häva mutationen. Gnomisk ingenjörskonst är dock ökänd för att vara oberäknelig, och det återstår att se om Recombobulator verkligen kan återställa deras folks kroppar och sinnen.",al={"fungerar recombobulator","finns det botemedel mot spetälska gnomer"}}},fx={["8ac7e8f1"]={q="Vad är Restabilization Cog?",a="Restabilization Cog är en precisionskomponent som räddats från fallna maskiner och bestrålade spetälskegnomer som strövar utanför den förstörda staden Gnomeregan. Kugghjulen håller komplicerade gnomiska apparater i jämvikt och uppskattas av uppfinnare som behöver stabila, färdigbearbetade delar till nyckfulla uppfinningar som Ozzie Togglevolt's Recombobulator.",al={"vad är restabilization cog","restabilization cog bakgrund","om restabilization cog"}},ceb0040c={q="Varifrån kommer Restabilization Cog?",a="Kugghjulen kommer från Gnomeregans omfattande mekaniska verkstäder. När staden evakuerades efter det katastrofala strålningsutsläppet förde oräkneliga automatiserade apparater och de tragiska överlevande som dukade under för spetälskegalskapen med sig de standardiserade delarna ut i snön utanför portarna.",al={"vem skapade restabilization cog","restabilization cog ursprung","varifrån kommer restabilization cog"}}},fp="19,156,21.476.0,39.203.0,30.142.0,54.220.0"}
P.entries["item:rin-ji-s-secret-quest-item"] = {n="Rin'ji's Secret",s="I Hinterlands kan en tavla med Witherbark-trollskrift dölja något värdefullt. Oran Snakewrithe i Undercitys Magic Quarter får i uppdrag att tyda den.",h="I Hinterlands kan en tavla med Witherbark-trollskrift dölja något värdefullt.",kw={"hinterlands","magic quarter","oran snakewrithe","rin'ji","hemlighet","tavla","troll","undercity","witherbark"},ang={["race:Troll"]="Tavlan bär ristningar från Witherbark trolls, så mysteriet rör en trollstams historia och traditioner."},sec={{t="Trollristningar",b="Rin'ji's Secret är en tavla som hittats bland oroligheterna i Hinterlands. På ytan finns ristningar från Witherbark trolls, men betydelsen är okänd. Oran Snakewrithe, en lärd person med kunskap om Witherbark trolls i Undercity, kanske kan läsa den."}},faq={{q="Vad är Rin'ji's Secret?",a="Rin'ji's Secret är en tavla täckt av ristningar från Witherbark trolls. Betydelsen är ett mysterium.",al={"rin'ji hemlighet","rin'ji tavla","vad är tavlan"}},{q="Vem kan läsa tavlan?",a="Oran Snakewrithe, en lärd person med kunskap om Witherbark trolls i Undercitys Magic Quarter, kanske kan tyda tavlan.",al={"vem tyder den","oran tavla","lärd i magic quarter"}},{q="Varifrån kommer tavlan?",a="Tavlan har koppling till Rin'jis bekymmer i Hinterlands.",al={"var hittad","hinterlands tavla","rin'jis plats"}},{q="Är Rin'ji's Secret värdefull?",a="Tavlan kan vara värdefull, men dess värde är osäkert tills ristningarna har tolkats.",al={"tavlans värde","värdefull tavla","rin'ji hemlighet värde"}}},fp="15,166,14.245.0,24.91.0,24.114.0,25.59.0,28.89.0"}
P.entries["item:ring-of-zoram"] = {n="Ring of Zoram",s="Ring of Zoram är ett urgammalt Kaldorei-arv från den sjunkna staden Zorams storhetstid före den stora Sundringen. Stadens härskare bar en gång ringen, som var nyckeln till låset på en forntida, sjunken statuett. Nyligen hamnade den hos de framryckande naga längs kusten.",h="Ring of Zoram är ett urgammalt Kaldorei-arv från den sjunkna staden Zorams storhetstid före den stora...",kw={"ancient statuette","ashenvale","lady vespia","ring of zoram","ruuzel","talen","the zoram strand"},ang={["faction:Alliance"]="Om du återtar ringen från naga hjälper du nattalven och lärde Talen att återta stulen kaldorei-historia längs Ashenvales omstridda gränser.",["race:NightElf"]="Ringen är ett påtagligt arv från tiden före Sundringen, från en tid innan kaldoreiriket slets sönder av magiskt övermod och stigande hav."},sec={{t="Ringen från den sjunkna staden",b="Innan Evighetens brunn kollapsade och haven slukade Kalimdors västra delar var Zoram en kustpärla i nattalvernas rike. Ring of Zoram tillhörde stadens härskare, och ett märkligt chiffer står skrivet på ringens insida med nattalvernas språk. När den stora Sundringen slet sönder kontinenten för tiotusen år sedan sjönk ringen med staden och försvann under de dånande tidvattnen vid det som nu är The Zoram Strand."},{t="Naga återtar ringen",b="I årtusenden låg ringen begravd under slam och ruiner, tills naga började genomsöka Ashenvales kust. Ruuzel, en nagaledare som bor på en liten ö utanför den norra stranden, hittade artefakten bland de sjunkna lämningarna. Lärda som nattalven Talen söker ringen inte bara för dess ålder, utan också för att den är den enda nyckeln som kan låsa upp andra reliker från djupet, däribland forntida, förseglade statuetter som bärgats från havsbotten."}},faq={{q="Vad används Ring of Zoram till?",a="Ringen tillhörde Zorams härskare innan Sundringen dränkte staden, och den är nyckeln till ett forntida lås. I dag söker Talen efter den för att öppna en låst forntida statuett som bärgats från de sjunkna ruinerna.",al={"ring of zorams syfte","vad gör ringen","ring of zorams historia"}},{q="Vem har Ring of Zoram?",a="Kustnaga som invaderade The Zoram Strand bärgade ringen från ruinerna. Den hålls främst av deras ledare Ruuzel på en ö utanför nordkusten, men även en annan framstående naga vid namn Lady Vespia har setts bära den.",al={"vem har ringen","ring of zoram byte","var hittar man ring of zoram"}},{q="Varför vill Talen ha ringen?",a="Talen vill avslöja hemligheterna hos den forntida statuett som bärgats från The Zoram Strand. Utan Ring of Zoram som nyckel går statuettens urgamla mekanism inte att öppna.",al={"varför vill talen ha ringen","talens ringuppdrag"}},{q="Vad hände med staden Zoram?",a="Zoram var en forntida nattalvstad vid Kalimdors västra kust före den stora Sundringen för tiotusen år sedan. När Evighetens brunn imploderade förstördes staden och dränktes under vågorna. Endast The Zoram Strand blev kvar.",al={"vad hände med zoram","zorams historia"}}},fx={["7e40c0d5"]={q="Vad är Ring of Zoram?",a="Ring of Zoram är en forntida relik som en gång bars av härskarna i den sjunkna staden Zoram, innan den stora förkastningens vågor dränkte den. En märklig kod på nattalviska står skriven på insidan av ringen, som är nyckeln till den forntida låsmekanismen på en statyett som återfunnits bland ruinerna.",al={"vad är ring of zoram","ring of zoram bakgrund","föremålet ring of zoram"}},["770adfa7"]={q="Varifrån kommer Ring of Zoram, och vem skapade den?",a="Ringen kommer från den nattalviska staden Zoram, som låg vid kusten i det forntida Kalimdor före förkastningen. Den tillhörde stadens härskare innan våldsamma flodvågor dränkte Zoram för tiotusen år sedan. Reliken försvann i havet tills nagor nyligen bärgade upp den från ruinerna.",al={"ring of zoram ursprung","vem skapade ring of zoram","varifrån kommer ring of zoram"}}},fp="13,163,23.386.0,23.375.0,35.192.0,32.200.0,29.173.0,31.228.0"}
P.entries["item:robo-mechanical-guts"] = {n="Robo-Mechanical Guts",s="Robo-Mechanical Guts är bärgade kugghjul, ledningar och maskininnandömen från de felande konstruktioner som strövar omkring i ruinerna av Gnomeregan. Gnomiska ingenjörer i Stormwind behöver just dessa komponenter för att reparera tunga tunnelmaskiner som ska hjälpa till att återta Gnomeregan i Dun Morogh.",h="Robo-Mechanical Guts är bärgade kugghjul, ledningar och maskininnandömen från de felande konstruktioner som...",kw={"urverk","dun morogh","gnomeregan","gyrodrillmatiska grävmaskiner","robo-mechanical guts","shoni","stormwind"},ang={["profession:Engineering"]="Varje bärgad härva av ledningar och gyrokugghjul påminner om höjdpunkten inom gnomisk automatisk konstruktion, nu tragiskt förvildad av strålning och isolering.",["race:Gnome"]="Det känns vemodigt att plocka isär de förrymda urverksvakterna från ditt förlorade hem, men när deras inre maskineri återanvänds får du de konkreta delar som behövs för att återta Gnomeregan."},sec={{t="Bärgning till flottan",b="När övertekniker Gelbin Mekkatorque och de överlevande gnomerna evakuerade Gnomeregan lämnades tusentals automatiserade mekanismer, urverksvakter och industr robotar kvar där inne. I stadens radioaktiva efterspel fortsätter maskinerna att vandra genom korridorerna på egen hand. I Stormwind City vill uppfinnaren Shoni sätta ihop en flotta gyrodrillmatiska grävmaskiner för att tränga igenom Gnomeregans försvar och återta den förlorade staden. Eftersom färska råmaterial saknas skickar hon djärva äventyrare till de förorenade salarna i Gnomeregan för att skära loss fungerande robotinnandömen – fjädrar, ledningar och gyroskopdelar – och rusta upp grävmaskinerna."}},faq={{q="Vad används Robo-Mechanical Guts till?",a="Shoni samlar in dem i Stormwind City för att reparera en flotta gyrodrillmatiska grävmaskiner, specialbyggda tunnelmaskiner som ska stödja försöken att återta Gnomeregan i Dun Morogh.",al={"vad robotinnandömen används till","användning av robo-mechanical guts","varför samla mekaniska innandömen"}},{q="Var hittar du komponenterna?",a="De kan bärgas från olika fientliga urverksautomater, mekaniska robotar och förorenade fiender som strövar omkring både i utkanten och i djupet av Gnomeregan.",al={"var hittar man robo-mechanical guts","var robotinnandömen droppar","robotdelar från gnomeregan"}},{q="Vem är Shoni och varför behöver hon så många delar?",a="Shoni är en ambitiös gnomisk ingenjör stationerad i Dwarven District i Stormwind. Hon har fått i uppdrag att förbereda en hel division underjordiska grävmaskiner, närmare fyra hundra till antalet, för att bryta igenom de ockuperade ruinerna av Gnomeregan.",al={"vem är shoni","shoni i stormwind","flotta med gyrodrillmatiska grävmaskiner"}}},fx={b1d0efc3={q="Vad är Robo-Mechanical Guts?",a="Det är ett virrvarr av inre maskineri, kugghjul, ledningar och användbara mekaniska delar som plockats från urverksautomaterna som strövar omkring i Gnomeregan. För ett otränat öga ser det mest ut som skrot, men de fungerande mekanismerna ger påhittiga gnomiska ingenjörer viktiga rådelar till avancerade fordonsprojekt.",al={"vad är robo-mechanical guts","föremålet robo-mechanical guts","vad är robo guts"}},cf2ae288={q="Varifrån kommer Robo-Mechanical Guts, och vem skapade dem?",a="Delarna kommer från verkstäderna i Gnomeregan, där gnomiska uppfinnare tillverkade dem för att driva stadens automatiserade arbetsstyrka och försvar. När strålningskatastrofen slog till och High Tinker Mekkatorque beordrade evakuering lämnades oräkneliga mekaniska konstruktioner kvar. De strövar fortfarande genom de förstörda gångarna med sina inre mekanismer intakta.",al={"vem skapade robo-mechanical guts","varifrån kommer robo-mechanical guts","robo-mechanical guts ursprung"}},f52d09f9={q="Varför vill någon ha Robo-Mechanical Guts?",a="Shoni the Shilent i Stormwind behöver dem desperat som reservdelar för att reparera en hel flotta gyrodrillmatiska grävmaskiner. Huvudstaden har begränsade förråd, så hon ser de förrymda mekanismerna i Gnomeregan som ett ymnigt skrotupplag som kan hålla hennes ingenjörsflotta i drift.",al={"varför samla robo-mechanical guts","vem vill ha robo-mechanical guts","varför vill shoni ha robo-mechanical guts"}}},fp="20,161,21.513.0,39.171.0,35.145.0,49.191.0"}
P.entries["item:roc-gizzard"] = {n="Roc Gizzard"}
P.entries["item:rock-elemental-shard"] = {n="Rock Elemental Shard",s="Rock Elemental Shards är fragment som samlas in från rock elementals i Badlands. Jarkal Mossmeld behöver dem bland flera reagenser för att fylla på sitt alkemiska lager.",h="Rock Elemental Shards är fragment som samlas in från rock elementals i Badlands.",kw={"alkemiska reagenser","badlands","jarkal mossmeld","kargath","rock elemental shard","rock elementals"},ang={["faction:Horde"]="Som medlem av Horde kan du ta med reagenserna från Badlands till Jarkal Mossmeld i Kargath, där han erbjuder mynt för dem."},sec={{t="Stenreagenser",b="I Kargath ber Jarkal Mossmeld om fem Rock Elemental Shards, buzzard gizzards och crag coyote fangs. Han är en alkemist som vill fylla på sitt lager och erbjuder mynt för de insamlade reagenserna."}},faq={{q="Vad används Rock Elemental Shards till?",a="Jarkal Mossmeld i Kargath behöver fem Rock Elemental Shards för att fylla på sitt alkemiska lager.",al={"användning av fragment","varför fragment","vad behöver jarkal"}},{q="Var kommer Rock Elemental Shards ifrån?",a="Rock Elemental Shards kommer från rock elementals i Badlands.",al={"fragmentens källa","var finns fragment","hitta rock shards"}},{q="Vem vill ha fragmenten?",a="Jarkal Mossmeld, en alkemist i Kargath, ber om fem Rock Elemental Shards.",al={"vem behöver fragment","jarkal och fragment","vem är jarkal"}},{q="Vad mer behöver Jarkal?",a="Jarkal ber också om fem buzzard gizzards och tio crag coyote fangs.",al={"andra reagenser","vad behöver jarkal","inälvor och huggtänder"}}},fp="20,168,14.210.0,35.95.0,41.64.0,21.78.0,27.69.0"}
P.entries["item:rocket-car-parts"] = {n="Rocket Car Parts",s="Rocket Car Parts är de utspridda, förvridna metallresterna efter höghastighetskrascher över The Shimmering Flats i Thousand Needles. De skapas ständigt när vårdslösa gnomer och gobliner pressar experimentella fartåk över gränsen, och samlas in av lycksökare som vill förvandla olyckor på racerbanan till snabba pengar.",h="Rocket Car Parts är de utspridda, förvridna metallresterna efter höghastighetskrascher över The Shimmering...",kw={"ingenjörskonst","gnom","goblin","kravel koalbeard","mirage raceway","rocket car parts","bärgning","the shimmering flats","thousand needles"},ang={["profession:Engineering"]="De utspridda brända kugghjulen och sönderslagna avgasrören över saltöknen vittnar om gnomers och gobliners ingenjörskonsts kaotiska ytterligheter.",["race:Dwarf"]="Medan gnomer och gobliner bara bryr sig om själva loppet visar företagsamma dvärgar som Kravel Koalbeard att den verkliga vinsten finns i att samla in vrakdelarna de lämnar efter sig."},sec={{t="Fart, vrak och smart handel",b="Mirage Raceway i The Shimmering Flats är skådeplatsen för en ändlös och explosiv rivalitet mellan gobliners och gnomers ingenjörskonst. I jakten på oslagbar markhastighet drabbas förarna regelbundet av katastrofala haverier, explosiva feltändningar och våldsamma krascher som sprider metall över saltöknens vidder. De övergivna resterna, från böjda cylindrar och brända kugghjul till krossad plåt, blir inte liggande länge. Asätare och handelsmän, framför allt den opportunistiska dvärgen Kravel Koalbeard, anlitar förbipasserande äventyrare för att söka igenom den bländande vita vidsträckta slätten och samla in skrotet. Eftersom båda racinglagen ständigt är desperata efter reservdelar till nästa prototyp kan vrakdelarna lätt säljas tillbaka direkt till lagen som kraschade dem."}},faq={{q="Var kommer alla de här raketbilsdelarna ifrån?",a="De är resterna efter ständiga krascher, explosioner och mekaniska fel vid Mirage Raceway. Gnom- och goblinförare pressar regelbundet sina flyktiga, experimentella raketdrivna fordon tills de går sönder över Thousand Needles vidsträckta saltöken.",al={"varför ligger det delar på saltöknen","raketbilsskrotets ursprung","var kommer delarna ifrån"}},{q="Vem köper det här upphittade skrotet?",a="Handelsmän som dvärgen Kravel Koalbeard samlar in vrakdelar från vandrare och säljer sedan kugghjul, plåt och mojänger vidare till gnomerna och goblinerna, som alltid behöver reservdelar för att reparera och förbättra sina racerbilar.",al={"vem vill ha raketbilsdelar","kravel koalbeard raketbilsdelar","vem köper vrakdelarna"}},{q="Är det farligt att leta efter delarna?",a="Själva skrotet är ofarliga vrakdelar, även om de ibland bär kusliga spår av våldsamma krascher, som avhuggna kroppsdelar som klämts fast i metallen. Den största faran kommer från saltöknens fientliga djurliv, däribland basilisks, svedda scorpider och rovlystna saltgamarsom stryker omkring bland skrothögarna.",al={"är det säkert att plocka upp delar","faror när man samlar delar"}},{q="Bryr sig gnomerna och goblinerna om att delarna kommer från kraschade bilar?",a="Inte det minsta. Varken gnom- eller goblinkonkurrenter är känsliga för återvunnet material. Deras enda prioritet är att få tag på fungerande manicker, kugghjul och plåt så att de kan bygga ihop något snabbt nog att köra om varandra på banan.",al={"bryr sig förarna om vrakdelar","varför återanvänder gobliner skrot"}}},fx={["9a01e74a"]={q="Vad är Rocket Car Parts?",a="Det är spillror från fartfyllda tävlingsolyckor runt The Shimmering Flats. Skrotet består av lösa kugghjul, cylindrar, tillbucklade metallplåtar och räddade manicker. Delarna satt en gång fastbultade på de dånande experimentfordon som goblin- och gnomiska fartfantomer byggde för att tävla vid Mirage Raceway.",al={"vad är rocket car parts","rocket car parts bakgrund","vad är det här för delar"}}},fp="16,216,34.487.0,46.227.0,31.210.0,36.213.0,68.161.0"}
P.entries["item:rod-of-channeling"] = {n="Rod of Channeling",s="I Wetlands bär Dragonmaw-spellcasters Rod of Channeling. Warlocks som vill frammana en felhunter samlar in tre åt Strahad Farsans akolyter, så att de kan stabilisera ritualcirkeln i Ratchet.",h="I Wetlands bär Dragonmaw-spellcasters Rod of Channeling.",kw={"angerfang encampment","bonewarder","dragonmaw","felhunter","rod of channeling","shadowwarder","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="Som warlock samlar du in tre Rods of Channeling under prövningarna i Tome of the Cabal. De hjälper dig att hålla ritualen under kontroll när du binder din första felhunter."},sec={{t="Bindningens redskap",b="Warlocks behöver mer än viljestyrka för att binda en oberäknelig felhunter. Strahad Farsan ber om tre likadana stavar så att hans akolyter kan kanalisera magi tillsammans och stabilisera cirkeln medan warlocken binder besten. Dragonmaw darkcasters bär stavarna för sina egna ritualer. Bonewarders och shadowwarders bär dem vid Angerfang Encampment och bland ruinerna i Wetlands. Strider sliter på stavarna och ger dem hack, men de kan fortfarande fokusera kaotisk netherenergi."}},faq={{q="Vad används Rod of Channeling till?",a="Stavarna förs till Strahad Farsan ovanför Ratchet. Hans akolyter använder dem för att kanalisera magi och stabilisera cirkeln som krävs för att frammana och binda en fientlig felhunter.",al={"vad är rod of channeling","syftet med rod of channeling","varför behöver jag rod of channeling"}},{q="Var hittar man Rods of Channeling?",a="Dragonmaw-spellcasters bär stavarna i Wetlands, särskilt Dragonmaw Bonewarders och Shadowwarders kring Angerfang Encampment.",al={"var hittar jag rods of channeling","vem släpper rod of channeling","rod of channeling-plats"}},{q="Varför behöver Strahad tre stavar?",a="Strahads akolyter hjälper till med ritualen för att frammana en felhunter. Var och en behöver en fokusstav för att hålla kanalen stabil medan warlocken betvingar besten.",al={"varför tre stavar","varför tre rods of channeling"}},{q="Varför använder Dragonmaw dessa stavar?",a="Dragonmaw-klanen använder stavarna i sin mörka shamanism och skuggmagi, rester från Old Horde. Dess bonewarders och shadowwarders kanaliserar förbannelser, nekromanti och skuggmagi i sina pågående territoriella krig i Wetlands.",al={"dragonmaw-stavar","varför har dragonmaw dem"}}},fx={af4e8f1c={q="Vad är Rod of Channeling?",a="Rod of Channeling är ett magiskt fokus som besvärjare använder för att samla och styra instabila magiska energier. Stavarna användes först av Dragonmawklanens mörka magiker i Wetlands. I händerna på erfarna häxmästare kan de fungera som kraftfulla ritualredskap som stabiliserar avancerade besvärjelser för att frammana varelser.",al={"vad är rod of channeling","rod of channeling bakgrund","om rod of channeling"}}},fp="17,163,22.464.0,39.158.0,38.133.0,33.140.0,39.227.0"}
P.entries["item:rokaro-s-letter"] = {n="Rokaro's Letter",s="Rokaro’s Letter förmedlar en begäran från Shadowprey Village till Myranda the Hag i Western Plaguelands. Rokaro hoppas att hennes förmåga att förklä sig kan hjälpa mot Black Dragonflight.",h="Rokaro’s Letter förmedlar en begäran från Shadowprey Village till Myranda the Hag i Western Plaguelands.",kw={"black dragonflight","desolace","förklädnad","illusion","myranda the hag","rokaro","rokaro’s letter","shadowprey village","sorrow hill","western plaguelands"},ang={["faction:Horde"]="Som medlem av Horde framför du Rokaros vädjan till en före detta illusionist från Lordaeron, i hopp om hjälp mot Black Dragonflight."},sec={{t="Ett meddelande till Myranda",b="I Shadowprey Village i Desolace skickar Rokaro dig med ett meddelande till Myranda the Hag vid Sorrow Hill. Hon var en gång Lordaerons främsta illusionist, och Rokaro tror att hennes förmåga att förklä sig kan lura Black Dragonflight. Han ber dig lämna brevet till henne så att hon kan avgöra om saken förtjänar hennes hjälp."},{t="Vad brevet innehåller",b="När Myranda läser Rokaro’s Letter vid Sorrow Hill upptäcker hon att det är avsiktligt blankt. Tystnaden skyddar brevet: om budbäraren tillfångatogs eller dödades skulle inga nedskrivna planer kunna hittas. Myranda förstår Rokaros försiktighet och går med på att hjälpa till, eftersom hon minns en tjänst hon är skyldig Warchief."}},faq={{q="Vem skrev Rokaro’s Letter?",a="Rokaro skickade brevet från Shadowprey Village i Desolace till Myranda the Hag.",al={"vem skickade brevet","rokaro brev","brev från rokaro"}},{q="Vart ska brevet?",a="Brevet är avsett för Myranda the Hag vid Sorrow Hill i Western Plaguelands.",al={"vart ska det lämnas","brevets destination","myrandas plats"}},{q="Varför behöver Rokaro Myranda?",a="Rokaro vill ha hjälp av Myrandas skicklighet inom illusion och förklädnad för att lura Black Dragonflight.",al={"varför myranda","behöver en illusionist","hjälp med förklädnad"}},{q="Vad står det i brevet?",a="Rokaro’s Letter är avsiktligt blankt, så att inga nedskrivna planer kan avslöjas om budbäraren tillfångatas eller dödas.",al={"brevets innehåll","är brevet blankt","vad står skrivet"}},{q="Varför är brevet blankt?",a="Det tomma brevet skyddar sitt syfte genom att inte innehålla någon skriftlig information som fienderna kan hitta.",al={"varför är brevet blankt","tomt brev","hemligt meddelande"}},{q="Går Myranda med på att hjälpa?",a="Ja. Myranda går med på att hjälpa till och hänvisar till en tjänst hon är skyldig Warchief.",al={"kommer myranda att hjälpa","myranda säger ja","går hon med på det"}}},fp="15,184,20.326.0,15.288.1,28.78.0,32.82.0,29.94.0,25.112.1,24.101.1,27.66.1"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="Rolf and Malakai's Medallions",s="Rolf and Malakai's Medallions bär rikets insignier, men deras ägare försvann under patrullering i östra Elwynn Forest. Guard Thomas söker efter medaljongerna för att få veta vad som hände hans män.",h="Rolf and Malakai's Medallions bär rikets insignier, men deras ägare försvann under patrullering i östra...",kw={"eastvale","elwynn","guard thomas","malakai","medaljonger","murloc","rolf","stormwind-vakt"},ang={["faction:Alliance"]="Till och med i hjärtat av Alliansen utsätts lokala vakter för livsfara när de skyddar landsbygdens handelsvägar.",["race:Human"]="För människorna i Elwynn markerar medaljongerna förlusten av söner och försvarare. Deras död visar hur sårbart riket är medan dess militär är upptagen på annat håll."},sec={{t="En dyster bekräftelse",b="Guard Thomas, befälhavare vid stationen i östra Elwynn, fruktade det värsta när Rolf och Malakai försvann längs flodbankarna. Deras medaljonger bekräftar att vakterna dödades av murlocs som trängde in i området. För Stormwind-garnisonen markerar medaljongerna förlusten av soldater som höll stånd mot vildmarkens hot medan rikets militär var hårt ansträngd."},{t="Tjänstens kännetecken",b="Mänskliga vakter på stadsvakt och landsbygdspatrull bär identifikationsmedaljonger som visar deras lojalitet och befogenhet under kronan. När du återlämnar Rolf and Malakai's Medallions till Guard Thomas kan han redovisa sina saknade män, rapportera deras uppoffring i sin fältrapport och varna för aggressiva murlocstammar som slår sig ned nära handelsvägarna."}},faq={{q="Vad är Rolf and Malakai's Medallions?",a="Det är tjänsteidentifikationer som bars av Rolf och Malakai, Stormwind-vakter som överfölls och dödades av murlocs när de var posterade i östra Elwynn Forest.",al={"vad är medaljongerna","rolfs medaljong","malakais medaljong"}},{q="Vem tillhör medaljongerna?",a="De tillhörde vakterna Rolf och Malakai, som tjänstgjorde under Guard Thomas och bevakade floden och vägarna mellan Goldshire och Eastvale Logging Camp.",al={"vilka var rolf och malakai","vems medaljonger"}},{q="Vem ska jag lämna medaljongerna till?",a="Lämna dem till Guard Thomas, som håller vakt vid den östra bron på vägen mellan Goldshire och Eastvale Logging Camp.",al={"vem vill ha medaljongerna","var lämnar jag in dem","lämna in medaljongerna"}},{q="Varför är medaljongerna viktiga för Guard Thomas?",a="Guard Thomas skickade ut båda vakterna på patrull och fruktade att de hade mött en ond bråd död. Medaljongerna bekräftar att de har dött, så att han kan rapportera deras uppoffring och varna Stormwind för det växande murloc-hotet.",al={"varför vill thomas ha dem","guard thomas reaktion"}}},fp="29,178,19.339.0,17.358.0,39.180.1,34.161.0,39.135.0,51.197.1"}
P.entries["item:roon-s-kodo-horn"] = {n="Roon's Kodo Horn",s="Roon’s Kodo Horn är en gåva från en taurenjägare i Desolace. Det förmedlar en inbjudan till Hemet Nesingwary Jr. i Stranglethorn och påminner om vänskapen mellan Roon och hans far.",h="Roon’s Kodo Horn är en gåva från en taurenjägare i Desolace.",kw={"desolace","grom'gol base camp","hemet nesingwary","hemet nesingwary jr","kodo horn","roon","roon wildmane","roons kodo-horn","stranglethorn"},ang={["race:Dwarf"]="Som dvärg bär du en gåva som påminner om vänskapen mellan Hemet och Roon Wildmane, trots fiendskapen mellan deras folk.",["race:Tauren"]="Som tauren kanske du känner till hornet som Roon Wildmanes gåva och hälsning till Hemet Nesingwary Jr."},sec={{t="En jägares gåva",b="Hemet Nesingwary Jr. jagar i Stranglethorn, norr om Grom'gol Base Camp. Hans far jagade en gång sida vid sida med Roon Wildmane i Desolace, och de lade fiendskapen mellan sina folk åt sidan. Roon ger dig sitt kodo-horn att ta med till den yngre Nesingwary. Gåvan bär med sig en hälsning från en gammal jaktkamrat."}},faq={{q="Vem är Roon?",a="Roon Wildmane är en taurenjägare från Desolace som en gång jagade tillsammans med Hemet Nesingwary.",al={"roon","roon wildmane","taurenjägare"}},{q="Varför ge Hemet Jr. hornet?",a="Roon skickar hornet som en gåva och hälsning till Hemet Nesingwary Jr., son till hans gamla följeslagare.",al={"varför horn","roons gåva","horn till hemet"}},{q="Var hittar jag Hemet Jr.?",a="Hemet Nesingwary Jr. finns i Stranglethorn, norr om Grom'gol Base Camp.",al={"var finns hemet","hemets plats","hemet i stranglethorn"}},{q="Vem var Hemets far?",a="Hemet var dvärgen som jagade storvilt med Roon Wildmane i Desolace.",al={"hemets pappa","hemet senior","gamle hemet"}},{q="Vad betyder hornet för Roon?",a="Hornet är Roons gåva till Hemet Nesingwary Jr. och förmedlar Roons hälsning.",al={"hornets betydelse","varför kodo-horn","roons kodo-horn"}},{q="Kom Roon och Hemet överens?",a="Ja. Roon säger att han och Hemet jagade tillsammans i många dagar och glömde fiendskapen mellan sina folk.",al={"roon och hemet","vänskap mellan dvärg och tauren","var de vänner"}}},fp="16,183,15.307.0,12.90.0,28.93.0,27.70.0,23.75.0,32.75.0,29.102.0"}
P.entries["item:rot-blossom"] = {n="Rot Blossom",s="Rot Blossoms är motbjudande, nekrotiska växter som växer bland Duskwoods skändade gravar. De får näring från den fördärvade jorden och odödas kvarlevor, och eftersöks för sina kraftfulla, osunda alkemiska egenskaper.",h="Rot Blossoms är motbjudande, nekrotiska växter som växer bland Duskwoods skändade gravar.",kw={"althea ebonlocke","darkshire","duskwood","rot blossom","skeletal fiend","skeletal horror","tranquil gardens cemetery","zombie juice"},ang={["faction:Alliance"]="Att ge sig ut i den förbannade jorden för att samla dessa morbida blommor blir också en tjänst åt Night Watch och hjälper till att hålla Darkshires gränser fria från glupska skelett.",["profession:Herbalism"]="Till skillnad från vanliga örter som får näring av ljus och regn är Rot Blossoms vedervärdiga botaniska avvikelser, som enbart lever av nekrotisk förruttnelse och gravjord. De är ett dystert exempel på fördärvad växtlighet."},sec={{t="Flora från kryptorna",b="Duskwoods onaturliga fördärv ger upphov till bisarra och obehagliga växter, och ingen är mer oroande än Rot Blossom. Dessa morbida blommor slår rot i den vanhelgade jorden på begravningsplatser som Tranquil Gardens Cemetery och frodas nära döden. Lokala rykten säger att de till och med kan slå rot i de vandrande dödas spruckna skallar, särskilt hos Skeletal Horrors och Skeletal Fiends som stryker omkring i gravhögarna. För Darkshires invånare är skörden både en dyster syssla och en farlig nödvändighet, eftersom den som rör upp jorden måste trotsa de rastlösa döda."},{t="Ett makabert ämne",b="Trots sitt motbjudande väsen fyller Rot Blossoms ett särskilt syfte i lokala brygder. Blommorna innehåller mörka essenser som krävs för att brygga Zombie Juice, en vedervärdig dryck med koppling till Duskwoods makabra kamp för överlevnad. De som skickas ut för att samla blommorna hjälper ofta Night Watch utan att mena det, eftersom de samtidigt rensar ut de rastlösa skelett som vandrar bland de hemsökta gravarna."}},faq={{q="Var hittar man Rot Blossoms?",a="Rot Blossoms växer i den fördärvade jorden på Duskwoods begravningsplatser, särskilt på Tranquil Gardens Cemetery, och sägs skjuta upp ur kvarlevorna av odöda skelettbestar.",al={"var växer rot blossoms","rot blossom plats","hitta rot blossoms"}},{q="Vad används Rot Blossoms till?",a="De är en viktig ingrediens som lokala bryggare och alkemister använder för att destillera en kraftfull, vedervärdig blandning som kallas Zombie Juice.",al={"rot blossom användning","varför samla rot blossoms","vad gör rot blossoms användbara"}},{q="Varför växer blommorna i skelett?",a="Duskwoods kvardröjande mörka magi smittar både jorden och de rastlösa döda. Rot Blossoms får näring direkt från nekrotiskt fördärv och förruttnelse, vilket låter dem gro i skallarna och bröstkorgarna på vandrande skelett.",al={"rot blossoms i skallar","skeletal horror-blomma","skelett rot blossom"}},{q="Hur hjälper insamling av Rot Blossoms Darkshire?",a="Den som ger sig in på platser som Tranquil Gardens för att samla blommorna måste förr eller senare fälla de Skeletal Horrors och Fiends som hemsöker området, vilket ger välbehövlig lättnad åt Althea Ebonlocke och den hårt ansatta Night Watch.",al={"althea ebonlocke rot blossom","night watch rot blossom","hjälpa darkshire"}}},fx={["93f3afdd"]={q="Vad är Rot Blossom?",a="Rot Blossom är en kuslig botanisk egenhet som slår rot på de pesthärjade gravplatserna i Duskwood. De här dystra blommorna växer inte i frisk jord, utan frodas bland förruttnelsen och gror ofta inne i de ihåliga skallarna på odöda Skeletal Horrors och Skeletal Fiends. Blommorna är fyllda av orena energier och eftertraktas av egendomliga lokalbor som brygger kraftfulla blandningar av förruttnelsen.",al={"vad är rot blossom","föremålet rot blossom"}}},fp="11,152,19.329.0,21.281.0,32.165.0,31.94.0,40.188.0,47.215.0"}
P.entries["item:rot-hide-ichor"] = {n="Rot Hide Ichor",s="Rot Hide Ichor är en motbjudande kroppsvätska som utvinns ur de odöda Rot Hide-gnollerna, vilka härjar på Fenris Isle i Lordamere Lake. Apothecary Renferrel samlar in prover av ämnet vid The Sepulcher för att avslöja ursprunget till gnollernas fördärv och utarbeta en strategi mot dem.",h="Rot Hide Ichor är en motbjudande kroppsvätska som utvinns ur de odöda Rot Hide-gnollerna, vilka härjar på...",kw={"apothecary renferrel","fenris isle","lordamere lake","rot hide-gnoller","rot hide ichor","the sepulcher","silverpine forest"},ang={["race:Undead"]="För Forsaken är studiet av vätskan avgörande militär underrättelse för att säkra Silverpines östra flank och stärka Royal Apothecary Societys kunskaper inom pestvetenskap."},sec={{t="En farsot i blodet",b="Rot Hide-gnollerna på Fenris Isle är inga vanliga vilddjur; de är synligt förruttnade och förvridna av en onaturlig pest. I stället för vanligt blod pumpar en giftig vätska genom deras ådror och håller deras animerade kroppar vid liv. Royal Apothecary Society misstänker att vätskan bär på hemligheten bakom hur flocken fördärvades och vem som styr dem från det inifrån raserade fästet på Fenris Isle."},{t="Apotekarens forskning",b="Apothecary Renferrel samlar in flaskor med vätskan för att analysera dess egenskaper vid The Sepulcher. Genom att isolera de kemiska och magiska beståndsdelar som driver gnollerna hoppas Forsaken hitta deras svagheter innan de skickar trupper över Lordamere Lake för ett fullskaligt anfall."}},faq={{q="Var kommer Rot Hide Ichor ifrån?",a="Den samlas in från kropparna hos Rot Hide-gnollerna som bor över hela Fenris Isle, i Lordamere Lake öster om Silverpine Forests fastland.",al={"var får man tag på rot hide ichor","hur hittar man rot hide ichor","gnollvätskans plats"}},{q="Varför vill Apothecary Renferrel ha vätskan?",a="Renferrel vill undersöka den märkliga vätskan för att ta reda på vad som fördärvade gnollerna och hitta fysiska eller alkemiska svagheter som Forsaken kan utnyttja innan de anfaller ön.",al={"varför behöver renferrel vätskan","anledningen till renferrels uppdrag","syftet med rot hide ichor"}},{q="Är Rot Hide-gnollerna Scourge?",a="De är odöda gnoller som förvridits av pest, men Forsaken undersöker aktivt exakt vem eller vad som skapade dem och styr deras närvaro på Fenris Isle.",al={"är rot hides scourge","vem styr rot hides","vad är rot hide-gnoller"}},{q="Har alla gnoller den här vätskan?",a="Nej. Vätskan är unik för Rot Hide-flocken, vars kött och blod har fördärvats av motbjudande nekromantiska farsoter.",al={"släpper alla gnoller vätska","vanligt gnollblod"}}},fx={c332bd61={q="Vad är Rot Hide Ichor?",a="Rot Hide Ichor är en märklig, onaturlig vätska som strömmar genom kropparna på Rot Hide-kobolderna på Fenris Isle. Det är inte vanligt blod. Royal Apothecary Society tror att det fördärvade ämnet orsakar koboldernas förvridna, odödliknande natur och ökade motståndskraft.",al={"vad är rot hide ichor","rot hide-vätska","vad är vätskan"}}},fp="14,168,21.303.0,19.267.0,36.117.0,46.166.0,32.142.0,30.109.0"}
P.entries["item:rough-quartz"] = {n="Rough Quartz",s="I Durotar kommer Rough Quartz från en Minor Manifestation of Earth. En shaman för stenen till en äldste, som binder in den i den första Earth Totem.",h="I Durotar kommer Rough Quartz från en Minor Manifestation of Earth.",kw={"call of earth","canaga earthcaller","earth totem","minor manifestation of earth","rough quartz","valley of trials"},ang={["class:Shaman"]="Som shaman markerar Rough Quartz din första kontakt med jordens element. Den förankrar dina besvärjelser och visar din väg som en kanal för andarna."},sec={{t="Earth Totems hjärta",b="Rough Quartz är en gåva från en Minor Manifestation of Earth till en shaman som kommunicerar med andarna i Durotar eller Mulgore. För det otränade ögat ser den ut som en vanlig ökensten. Stenen står för uthållighet, tålamod och orubblig styrka. I Valley of Trials binder Canaga Earthcaller in den i snidat trä för att skapa en Earth Totem. Kvartsen blir det andliga fokus som förenar en ung shaman med Azeroths levande jord."}},faq={{q="Vad används Rough Quartz till?",a="En äldre shaman binder in Rough Quartz i invigdas första Earth Totem som dess andliga kärna. Stenen visar också att novisen har kommunicerat med jordelementets ande.",al={"vad gör rough quartz","användning av rough quartz","varför behöver jag rough quartz"}},{q="Vem ger dig Rough Quartz?",a="En Minor Manifestation of Earth ger dig Rough Quartz när du har kommunicerat med anden under ritualen Call of Earth i Durotar eller Mulgore.",al={"var får jag rough quartz","vem släpper rough quartz"}},{q="Vem ska jag lämna stenen till i Durotar?",a="Ta Rough Quartz till Canaga Earthcaller, shamantränaren i Valley of Trials. Canaga formar den till din Earth Totem.",al={"var lämnar jag in rough quartz","lämna in rough quartz","vem tar emot rough quartz"}},{q="Används kvartsen till något annat?",a="Nej. Rough Quartz är enbart ett heligt ritualföremål för att skapa en Earth Totem och har ingen användning i vanlig handel.",al={"kan jag sälja rough quartz","används rough quartz vid tillverkning"}}},fx={f25f16be={q="Vad är Rough Quartz?",a="Rough Quartz är en liten elementär sten som en Minor Manifestation of Earth ger till blivande schamaner. Stenen är anspråkslös till storlek och utseende, men visar att en lärling har klarat jordens rit och förenat sig med elementaranden. Den är ett synligt bevis på deras band.",al={"vad är rough quartz","föremålet rough quartz","vad rough quartz betyder"}},["871e2ee1"]={q="Varför vill Canaga Earthcaller ha Rough Quartz?",a="Canaga Earthcaller behöver Rough Quartz som bevis på att du har hörsammat kallelsen och förenat dig med elementaranden. Han använder stenen som kärna i ditt första Earth Totem, så att du kan få en starkare förbindelse med jorden och kasta besvärjelser som hämtar kraft direkt från den.",al={"varför behövs rough quartz","vad rough quartz används till","varför ta med rough quartz till canaga"}}},fp="12,143,24.439.0,40.172.0,31.143.0,40.127.0,38.102.0"}
P.entries["item:rumbleshot-s-ammo"] = {n="Rumbleshot's Ammo",s="Rumbleshot's Ammo är en borttappad ammunitionslåda på väg till vapensmeden Hegnar Rumbleshot i Dun Morogh. En rädd kurir flydde från hungriga wendigos och lämnade den tunga lådan i snön nära The Grizzled Den.",h="Rumbleshot's Ammo är en borttappad ammunitionslåda på väg till vapensmeden Hegnar Rumbleshot i Dun Morogh.",kw={"ammunition","låda","dun morogh","the grizzled den","hegnar","loslor","rumbleshot","wendigo"},ang={["class:Hunter"]="För skyttar som färdas genom Dun Moroghs bitande kyla ger torrt krut och välfyllt ammunitionsförråd hos Hegnar en stadig tillgång på ammunition till dvärgarnas skjutvapen.",["profession:Engineering"]="Dvärgarnas ingenjörer och mekaniker är starkt beroende av ett jämnt flöde av ammunition och krut för att testa sina egentillverkade skjutvapen och experimentella vapen."},sec={{t="En förlorad leverans",b="Hegnar Rumbleshot driver en vapenbutik vid vägen längs bergsstigen från Coldridge Pass mot Anvilmar. Ironforge-skyttar, bergsklättrare och dvärgarnas mortarlag övar ständigt på de snöiga höjderna, så hans förråd tar slut nästan lika fort som krut fattar eld. Den här leveransen med ammunition skickades av Loslor från Kharanos, men nådde aldrig hyllorna. Kuriren som skulle frakta den slog läger för nära The Grizzled Dens rovgiriga wendigos, fick panik när de anföll och flydde för livet. Den tunga Supply Crate blev kvar djupt inne i bestarnas jaktmarker."}},faq={{q="Vem är Hegnar Rumbleshot?",a="Hegnar Rumbleshot är en dvärgisk vapensmed som driver en butik vid vägen mot Anvilmar. Han förser lokala skyttar, jägare och militärer med ammunition, som de förbrukar snabbt när de övar bland klipporna i Dun Morogh.",al={"rumbleshot","vem är hegnar","vapenförsäljare"}},{q="Hur kom ammunitionslådan bort?",a="En kurir som fått i uppdrag att leverera lådan gjorde misstaget att slå läger nära ingången till The Grizzled Den. När lyanas revirhävdande wendigos anföll lägret flydde den skräckslagna kuriren och lämnade den tunga lådan i snön.",al={"varför försvann ammunitionen","vad hände med ammunitionen","kurir ammunition"}},{q="Var ligger The Grizzled Den?",a="The Grizzled Den är ett grottsystem uthugget i bergen sydväst om Kharanos. Där håller Dun Moroghs ökända, våldsamma wendigos till, vilket gör de omgivande sluttningarna farliga för ensamma resenärer.",al={"var ligger the grizzled den","var finns wendigogrottan"}}},fx={["4221fe47"]={q="Vad är Rumbleshot's Ammo?",a="Det är en låda med färsk ammunition till Hegnar Rumbleshot's butik längs vägen till Anvilmar. Dvärgiska gevärsskyttar och mortarlag i trakten övar ständigt, så Hegnar behöver regelbundna storleveranser som den här för att fylla hyllorna och förse kunderna med vapen.",al={"vad är rumbleshot's ammo","ammunitionslåda från rumbleshot","vad är det här för ammunition"}},["008970c2"]={q="Varifrån kommer Rumbleshot's Ammo?",a="Lådan skickades av Loslor Rudge från Kharanos. Tyvärr överfölls kuriren som skulle föra den sydväst mot Anvilmar av våldsamma wendigor nära The Grizzled Den. Kuriren flydde och övergav hela leveransen i snön.",al={"vem skapade rumbleshot's ammo","varifrån kommer rumbleshot's ammo","vem skickade ammunitionen"}},["6d6b5eaa"]={q="Varför behöver Hegnar Rumbleshot den här ammunitionen?",a="Hegnar håller på att få slut på lagret. Bergsbor, gevärsskyttar och mortarlag i trakten förbrukar krut och skott i rasande takt under målövningarna. Många ivriga köpare väntar på att den färska leveransen ska komma.",al={"varför behövs rumbleshot's ammo","varför vill någon ha rumbleshot's ammo","vem behöver rumbleshot's ammo"}}},fp="17,177,19.477.0,25.175.0,32.152.0,26.171.0"}
P.entries["item:rune-inscribed-parchment"] = {n="Rune-Inscribed Parchment",s="I Valley of Trials ger Gornek blivande orciska shamaner ett meddelande från Shikrik. Det kallar dem att bli andliga ledare och förmedlare åt elementandar.",h="I Valley of Trials ger Gornek blivande orciska shamaner ett meddelande från Shikrik.",kw={"durotar","gornek","pergament","rune-inscribed parchment","schaman","shikrik","valley of trials"},ang={["class:Shaman"]="Som shaman markerar den här anteckningen ditt allra första steg på elementens väg. Under Shikriks ledning lär du dig att vörda förfäderna och bemästra elementen.",["race:Orc"]="Som orc för du vidare förfädernas visdom i Durotar. Återupptäckten av den shamanistiska traditionen är central för den nya Horden."},sec={{t="En kallelse till andarna",b="Nya orciska shamaner börjar sin träning under erfarna uppsyningsmän i Valley of Trials. Medan en lärling utför de första prövningarna åt Gornek ger han dem ett runbestrött dokument från Shikrik, den lokale shamaninstruktören. Meddelandet kallar dem till djupare gemenskap med elementen. Bland orcerna förmedlar shamaner kontakten mellan de levande och deras förfäder. Skriften markerar en övergång från rå styrka till disciplinerad vördnad för förfäderna."}},faq={{q="Vad är Rune-Inscribed Parchment?",a="Gornek ger det handskrivna meddelandet till nya orciska shamaner i Valley of Trials. Det instruerar dem att söka upp Shikrik för formell undervisning.",al={"runpergament","vad är det här för föremål","schamanpergament"}},{q="Vem skrev pergamentet?",a="Shikrik, shamantränaren i Valley of Trials, skrev pergamentet för att lära unga lärlingar om elementens och förfädernas andars vägar.",al={"vem skickade pergamentet","pergamentets författare"}},{q="Varför anses schamaner vara utvalda bland orcerna?",a="Orciska shamaner vägleder sitt folk som andliga ledare, lyssnar till elementandar och förmedlar deras förfäders kraft. Shikrik påminner lärlingarna om att deras plikt omfattar att hela allierade och rikta elementens vrede mot fienderna.",al={"varför bli schaman","orcschamanens roll"}}},fx={["00232829"]={q="Varför vill Shikrik att du läser Rune-Inscribed Parchment?",a="Shikrik skickade det här meddelandet genom Gornek för att kalla dig direkt till sig. Eftersom hon förstått att du är utvald att vägleda ditt folks andliga liv tänker hon inleda din formella utbildning i förbindelse med förfäderna, mästerskap över elementen och en orks shamans riter.",al={"varför läsa rune-inscribed parchment","varför skickar shikrik ett pergament","syftet med rune-inscribed parchment"}}},fp="24,154,24.414.0,37.140.0,24.153.0,49.220.0"}
P.entries["item:rune-inscribed-pendant"] = {n="Rune-Inscribed Pendant",s="Rune-Inscribed Pendant är en magisk prydnad som återfunnits i Dalarans leveranser till Ambermill. Kirin Tor värdesätter dessa pendanter, som leder kraftfulla arkana energier.",h="Rune-Inscribed Pendant är en magisk prydnad som återfunnits i Dalarans leveranser till Ambermill.",kw={"allister","ambermill","dalar dawnweaver","dalaran","kirin tor","pendant","rune-inscribed pendant","the sepulcher"},ang={["class:Mage"]="Magiker känner lätt igen Kirin Tors hantverk. Runorna som ristats in i pendanten är utformade för att stabilisera flyktiga strömmar när kraftfulla besvärjelser kanaliseras.",["race:Undead"]="För de Fördömda som vaktar Silverpine Forest ger beslagtagna fokusredskap från Dalaran, som denna pendant, viktiga underrättelser om mänskligt motstånd som samlas bakom Ambermills murar."},sec={{t="Kirin Tor-relik",b="Bland lådor med kartografisk utrustning på väg till Dalarans enklav i Ambermill hittades denna pendant med intrikata arkana inskrifter. Högt uppsatta Kirin Tor-magiker använder ofta sådana artefakter för att fokusera och förstärka sina besvärjelser. Att så många kanaliseringspendanter förs in i området väcker genast misstankar hos de Fördömda vid The Sepulcher och signalerar ett nära förestående projekt med enorm magisk kraft."},{t="En ledtråd om Ambermills planer",b="När Shadow Priest Allister får se den vid The Sepulcher inser han hotet från Dalarans befästa position, men lämnar reliken till Dalar Dawnweaver för närmare granskning. Dawnweaver identifierar pendanten som en viktig del av magikernas verksamhet och drar slutsatsen att Kirin Tor samlar på sig arkana fokusredskap för att understödja omfattande defensiv eller offensiv magi bakom Ambermills gränser."}},faq={{q="Vad används Rune-Inscribed Pendant till?",a="Kirin Tor-magiker använder pendanten för att kanalisera och styra stora flöden av magisk energi. Den fungerar som ett arkanat fokus för avancerad magi, inte som en enkel prydnad.",al={"vad gör pendanten","pendantens syfte","användning av runependant"}},{q="Varifrån kommer pendanten?",a="Den beslagtas från leveranser på väg till Ambermill i Silverpine Forest, där resterna av Kirin Tor har befäst sig kraftigt.",al={"var hittar jag pendanten","pendantens ursprung","var hittades den"}},{q="Vem analyserar pendanten vid The Sepulcher?",a="Efter att Shadow Priest Allister snabbt har undersökt den tillsammans med beslagtagna kartor skickar han den till Dalar Dawnweaver, en arkan specialist vid The Sepulcher som känner igen Kirin Tors hantverk.",al={"vem undersöker pendanten","vem vill ha pendanten","dalaran-pendant"}},{q="Varför oroar den de Fördömda?",a="Leveransen av stora mängder kanaliseringspendanter tyder på att Kirin Tor i Ambermill förbereder ett omfattande magiskt företag som hotar de Fördömdas grepp om Silverpine Forest.",al={"varför bryr sig de fördömda","hotet från ambermill","varför är pendanten farlig"}}},fx={bf28d080={q="Vad är Rune-Inscribed Pendant?",a="Det är en mystisk artefakt som skapats och används av Dalarans mäktiga magiker. Kirin Tor använder ofta sådana smycken för att fokusera och kanalisera väldiga magiska energier. De är ledare för starka mystiska krafter, inte enkla prydnader.",al={"vad är rune-inscribed pendant","vad är runhänget","vad är dalaran pendant"}}},fp="22,166,15.327.0,27.338.1,44.111.0,33.125.0,42.165.0,40.185.0"}
P.entries["item:rune-inscribed-tablet"] = {n="Rune-Inscribed Tablet",s="I Valley of Trials ger Gornek unga Darkspear-trollschamaner ett budskap i sten. Det skickar lovande mystiker till Shikrik för att inleda sin formella förbindelse med elementen.",h="I Valley of Trials ger Gornek unga Darkspear-trollschamaner ett budskap i sten.",kw={"darkspear","durotar","gornek","rune-inscribed tablet","schaman","shikrik","tränare","valley of trials"},ang={["class:Shaman"]="Som schaman markerar tavlan ditt första officiella steg mot att bemästra jord, eld, vatten och luft. Den påminner dig om att din styrka flödar från förfädernas andar.",["race:Troll"]="Som Darkspear-troll svarar du på en orkisk tränares kallelse, ett tecken på det växande bandet och den gemensamma andliga vägen mellan ditt folk och dess nya allierade i Horden."},sec={{t="En kallelse till andarna",b="Gornek ger den runristade stenen till de invigda som visar sitt mod i Valley of Trials. Trollschamanen Ishi-yo skickade den för att leda dem till Shikrik, schamantränaren. För Darkspear Trolls inleder tavlan en gemensam väg med orcherna, där deras gamla andliga traditioner förenas med det schamanistiska arvet som hövding Thrall har förnyat."}},faq={{q="Vad används Rune-Inscribed Tablet till?",a="Gornek ger tavlan till unga trollschamaner i Valley of Trials. Den leder dem till Shikrik för att inleda sin formella andliga utbildning.",al={"tavlans syfte","vad gör tavlan","användning av runristad tavla"}},{q="Vem skickar tavlan?",a="Trollschamanen Ishi-yo skickar tavlan. Den leder den invigde till Shikrik, orkschamantränaren strax utanför The Den i Valley of Trials, som vet att de är på väg.",al={"vem skrev tavlan","tavlans avsändare","vem ristade den"}},{q="Vem får den här tavlan?",a="Gornek ger den här tavlan till nyanlända Darkspear-trollschamaner som deras första klasskallelse i Durotar.",al={"vem får rune-inscribed tablet","vilken klass får tavlan"}}},fx={cd2cca59={q="Vad är Rune-Inscribed Tablet?",a="Rune-Inscribed Tablet är en skriftlig kallelse till trollshamaner under utbildning i Valley of Trials. Den är märkt med shamanistiska runor och fungerar som ett personligt meddelande som skickas genom Gornek för att presentera lovande rekryter direkt för deras lokala tränare.",al={"vad är rune-inscribed tablet","berättelsen om rune-inscribed tablet","vad är den här tabletten"}},["33b46b09"]={q="Varför vill Shikrik att du tar emot Rune-Inscribed Tablet?",a="Tabletten kommer egentligen från Ishi-yo, trollshamanen som gav dig dina första lektioner. Gornek gissar bara att den kommer från Shikrik. Ishi-yo skickar dig vidare till Shikrik, som redan väntar dig. Hon vill förankra dig i elementen och dina förfäders andar, så att du en dag kan vägleda och skydda Hordens byar och städer, precis som Thrall vägleder själva Horden.",al={"varför skickar shikrik tabletten","varför behövs den här tabletten","shikriks rune-inscribed tablet"}}},fp="21,159,24.315.0,43.130.0,21.178.0,25.105.0"}
P.entries["item:rune-of-nesting"] = {n="Rune of Nesting",s="Rune of Nesting är en av de fyra heliga Relics of Wakening som förvaras i Ban'ethil Barrow Den på Teldrassil. Den är en viktig del av den känsliga druidritual som krävs för att tryggt kalla sovande Druids of the Talon tillbaka från The Emerald Dream.",h="Rune of Nesting är en av de fyra heliga Relics of Wakening som förvaras i Ban'ethil Barrow Den på Teldrassil.",kw={"athridas bearmantle","ban'ethil barrow den","chest of nesting","druids of the talon","emerald dream","relics of wakening","rune of nesting"},ang={["class:Druid"]="För druider symboliserar Rune of Nesting Cenarion Circles heliga ritualer och visar hur sårbara de sovande fränderna är när heliga fristäder blir överfallna.",["race:NightElf"]="Vanhelgandet av gravhögarna och förlusten av dessa uppvakningsreliker vittnar om den växande korruption som plågar Teldrassils djurliv och furbolger."},sec={{t="Ett heligt redskap för uppvaknande",b="Night Elf-druider går in i djup, cyklisk dvala i underjordiska gravhögar för att komma i kontakt med naturen genom The Emerald Dream. Att vakna ur denna djupa trans handlar inte bara om att börja röra på sig; det krävs en noggrant utförd ritual med heliga redskap. Rune of Nesting, som förvaras säkert i Chest of Nesting djupt inne i de vindlande kamrarna i Ban'ethil Barrow Den, förankrar processen. Tillsammans med Raven Claw Talisman, Black Feather Quill och Sapphire of Sky fungerar runan som en kanal för att kalla tillbaka Druids of the Talon till den vakna världen."},{t="Kris i Ban'ethil",b="När korrumperade Gnarlpine-furbolger översvämmade Ban'ethil Barrow Den svävade gravhögens sovande försvarare i omedelbar fara. Utan tillgång till sina reliker riskerade druiderna att bli kvar i The Emerald Dream för alltid medan inkräktarna vanhelgade deras fristad. Om Rune of Nesting och dess tillhörande föremål återtas kan Athridas Bearmantle i Dolanaar förbereda ritualen som krävs för att tryggt väcka de hotade druiderna."}},faq={{q="Vad används Rune of Nesting till?",a="Den är en av de fyra Relics of Wakening som Athridas Bearmantle behöver för att utföra ritualen som tryggt väcker Druids of the Talon ur deras djupa slummer i The Emerald Dream.",al={"vad gör rune of nesting","rune of nestings syfte"}},{q="Var finns Rune of Nesting?",a="Den förvaras i Chest of Nesting, som ligger i de underjordiska tunnlarna i Ban'ethil Barrow Den, väster om Dolanaar på Teldrassil.",al={"var finns rune of nesting","var finns chest of nesting"}},{q="Varför kan de sovande druiderna inte bara vakna av sig själva?",a="Att träda in i The Emerald Dream under dvala är ett känsligt, transliknande tillstånd. Utan vägledning från heliga reliker och en uppvakningsritual kan det vara omöjligt att återvända, så att deras sinnen driver omkring medan deras fysiska kroppar är utsatta för fara.",al={"varför behöver druider en uppvakningsritual","varför kan druider inte vakna"}},{q="Vilka andra reliker behövs tillsammans med Rune of Nesting?",a="Hela ritualen kräver fyra Relics of Wakening: Rune of Nesting, Raven Claw Talisman, Black Feather Quill och Sapphire of Sky.",al={"andra relics of wakening","föremål i relics of wakening"}}},fx={["375c0565"]={q="Vad är Rune of Nesting?",a="Rune of Nesting är en av de fyra heliga Relics of Wakening som Druids of the Talon förvarar i Teldrassil. Den ligger i en särskild kista i Ban'ethil Barrow Den och bär på de specialiserade förtrollningar som krävs för att utföra uppvakningsritualen korrekt för druider som vilar i djup gemenskap med Emerald Dream.",al={"rune of nesting","vad är rune of nesting","berättelsen om rune of nesting"}}},fp="15,179,28.497.0,19.354.0,37.212.0,35.133.0,58.204.0,59.139.0"}
P.entries["item:runes-of-summoning"] = {n="Runes of Summoning",s="Runes of Summoning är ett ritualföremål som tillhandahålls av häxmästaren Carendin Halgar i Magic Quarter i Undercity. De används för att kalla fram en obunden voidwalker till en åkallningscirkel, så att en blivande häxmästare kan kuva den efter sin vilja.",h="Runes of Summoning är ett ritualföremål som tillhandahålls av häxmästaren Carendin Halgar i Magic Quarter i...",kw={"carendin halgar","magic quarter","runes of summoning","bindningen","undercity","voidwalker","häxmästare"},ang={["class:Warlock"]="Forsaken-häxmästare använder runorna för att bevisa sin dominans över Void och förvandla en kaotisk skugga till en trogen tjänare som består.",["race:Undead"]="I Undercitys underjordiska djup kringgår Forsaken-utövare gamla tabun och binder voidvarelser direkt under Ruins of Lordaeron."},sec={{t="Kuvande i Magic Quarter",b="I Undercitys Magic Quarter studerar Forsaken-utövare av de mörka konsterna hur Nether kan manipuleras. Carendin Halgar anförtror endast Runes of Summoning åt häxmästare som har förberett sig på att ta kontroll över en voidwalker. När utövaren kastar runorna i den aktiva åkallningscirkeln nedanför Halgars plats sliter de upp slöjan till Void och drar fram en varelse som måste besegras och bindas i tjänst."}},faq={{q="Vad används Runes of Summoning till?",a="De används i åkallningscirkeln i Undercitys Magic Quarter för att dra en obunden voidwalker från Nether in i den fysiska världen, så att en häxmästare kan besegra och kuva den.",al={"runorna för åkallning syfte","vad gör runorna för åkallning","hur använder man runorna för åkallning"}},{q="Vem tillhandahåller Runes of Summoning?",a="Carendin Halgar, Forsaken-häxmästaren som håller till i Undercitys Magic Quarter, tillhandahåller dem under det sista steget i utbildningen för att binda en voidwalker.",al={"vem ger runorna för åkallning","tränare för runorna för åkallning","carendin halgars runor"}},{q="Var måste runorna aktiveras?",a="De måste tas till den lila åkallningscirkeln direkt nedanför Carendin Halgars plattform i Magic Quarter.",al={"var använder jag runorna för åkallning","runorna för åkallning plats","åkallningscirkel undercity"}},{q="Vad händer när varelsen har åkallats?",a="Voidwalkern anfaller omedelbart. Häxmästaren måste kuva den med magi och vapenmakt. När den har besegrats blir varelsen en tjänare, och Carendin Halgar lär ut den permanenta besvärjelsen som åkallar den.",al={"vad händer efter att runorna har använts","voidwalker kuvad","efter att voidwalker har åkallats"}}},fx={["1ce5479a"]={q="Vad är Runes of Summoning?",a="Runes of Summoning är en särskild ritualkatalysator som ges till blivande förnekarkriglockor i Undercity. När runorna förs till kallelsens cirkel i Magic Quarter fokuserar de magiska energier för att slita upp en passage och dra fram en obunden voidwalker från Nether.",al={"vad är runes of summoning","runes of summoning","föremålet runes of summoning"}},["0508549c"]={q="Varför vill Carendin Halgar ha tillbaka Runes of Summoning?",a="Carendin Halgar ger dig runorna specifikt som ett mästarprov. När du aktiverat dem och besegrat den tillkallade voidwalkern i strid visar det att du har betvingat varelsen. Då kan han lära dig den permanenta besvärjelsen för att kalla fram och styra voidwalkers.",al={"varför lämna tillbaka runes of summoning","varför vill carendin ha runorna","lämna tillbaka runes of summoning"}}},fp="18,188,32.366.0,41.187.0,36.155.0,34.110.0,42.200.0"}
P.entries["item:ryedol-s-lucky-pick"] = {n="Ryedol's Lucky Pick",s="Ryedol’s Lucky Pick är ett gruvverktyg som försvann när Shadowforge-dvärgar anföll Hammertoe’s Digsite i Badlands. Prospector Ryedol hoppas få tillbaka det.",h="Ryedol’s Lucky Pick är ett gruvverktyg som försvann när Shadowforge-dvärgar anföll Hammertoe’s Digsite i...",kw={"badlands","dark iron","hammertoe's digsite","lucky pick","prospector ryedol","ryedol’s lucky pick","shadowforge"},ang={["race:Dwarf"]="Som dvärg kan du hjälpa Prospector Ryedol att återfå sitt verktyg efter Shadowforge-anfallet mot Hammertoe’s Digsite."},sec={{t="Ett verktyg för en prospektör",b="Prospector Ryedol arbetar söder om Hammertoe’s Digsite i Badlands. Shadowforge-klanen anföll utgrävningsplatsen och dödade nästan alla där, även Ryedols chef, Hammertoe. Ryedol lyckades fly, men hans lyckohacka blev kvar. Han ber dig leta efter verktyget bland Dark Iron-dvärgarna."}},faq={{q="Vem äger Ryedol’s Lucky Pick?",a="Prospector Ryedol äger hackan och vill få den tillbaka.",al={"ryedols hacka","ägare till lucky pick"}},{q="Var försvann hackan?",a="Hackan blev kvar vid Hammertoe’s Digsite i Badlands efter Shadowforge-klanens attack.",al={"var hackan försvann","hackans plats"}},{q="Vem har Ryedol’s Lucky Pick?",a="En av Shadowforge-dvärgarna vid Hammertoe’s Digsite har hackan.",al={"vem har hackan","shadowforge-hacka"}},{q="Varför vill Ryedol ha tillbaka hackan?",a="Det är Ryedols lyckohacka, och han ber dig hämta tillbaka den från Shadowforge-dvärgarna.",al={"varför lucky pick","ryedol behöver hackan"}}},fp="19,156,21.309.0,31.54.0,24.95.0,30.69.0,35.88.0"}
P.entries["item:sack-of-murloc-heads"] = {n="Sack of Murloc Heads",s="Sack of Murloc Heads är en makaber samling som plockats ihop längs stränderna i Hillsbrad Foothills. Den har satts ihop som bevis på militära insatser mot traktens strandplågor och prackas på förbipasserande äventyrare av Lieutenant Farren Orinelle, som ber dem leverera den till Marshal Redpath i Southshore.",h="Sack of Murloc Heads är en makaber samling som plockats ihop längs stränderna i Hillsbrad Foothills.",kw={"belöning","farren orinelle","huvuden","hillsbrad","marshal redpath","murloc","southshore"},ang={["faction:Alliance"]="Leveransen visar hur bristfällig logistiken är och vilka oglamorösa vardagsbördor Southshores försvarare bär när de håller ihop den norra alliansenklaven."},sec={{t="Byråkrati och strandplågor",b="Southshore är ständigt belägrat av Syndicate-outlaws, Forsaken-skärmytslingar och vilda murlocs som trängs längs kusten. För att få stöd och uppskattning från stadens ledning måste lokala officerare visa att kustens hot aktivt bekämpas. Lieutenant Farren Orinelle samlar bevis i form av avhuggna huvuden, men lasten är så motbjudande och han själv så äckelmagad att han lämnar över den droppande säcken till resenärer i stället för att själv överlämna de fasansfulla bevisen till Marshal Redpath."}},faq={{q="Vad är Sack of Murloc Heads?",a="Det är en säck av grovt tyg fylld med avhuggna murloc-huvuden från Hillsbrads västra stränder. Den fungerar som ett konkret bevis för Southshores garnisonschef på att kusten har säkrats.",al={"säck med huvuden","murloc-säck","vad är det här för föremål"}},{q="Varför levererar inte Lieutenant Farren den själv?",a="Farren tycker att det är motbjudande att bära omkring på en stinkande påse med ruttnande fiskvarelseh huvuden. Han vill hålla uniformen och händerna rena och låter därför en hjälpsam äventyrare sköta det obehagliga ärendet i Southshore.",al={"varför farren låter dig bära den","farrens ursäkt","lata farren"}},{q="Vem tar emot säcken?",a="Säcken levereras till Marshal Redpath, befälhavaren som övervakar Southshores försvar och bedömer stadens säkerhet. Han kräver konkreta bevis på försvarsinsatserna.",al={"vem får huvudena","vart ska jag ta den","lämna in till marshal redpath"}},{q="Varför kräver Southshore murloc-huvuden som bevis?",a="Murlocs plundrar ständigt kusterna och hotar hamnen. Officerarna förväntas kontrollera att patrullerna håller områdets försvar, och konkreta troféer säkerställer att ingen soldat bara tar åt sig äran för en vakt som inte gjort något.",al={"varför samla murloc-huvuden","bevis på dödade fiender"}}},fx={["3f14ed35"]={q="Varifrån kommer Sack of Murloc Heads, och vem gjorde den?",a="Säcken är fylld med huvudena från murlocerna du jagade längs Hillsbrad Foothills södra kust. Lieutenant Farren Orinelle packade dem för att överlämna dem till sin befälhavare, men lämnar snabbt tillbaka det motbjudande paketet till dig så att du kan leverera det i hans ställe.",al={"vem gjorde säcken med murloc-huvuden","varifrån kom säcken med huvuden","vem gav sack of murloc heads"}}},fp="20,217,29.433.0,33.166.0,47.170.0,22.139.0,50.248.0"}
P.entries["item:sack-of-supplies"] = {n="Sack of Supplies",s="En karavanlast på väg till Rezlak ligger utspridd bland harpiornas boplatser i Razorwind Canyon. Dustwind-harpiorna lade beslag på varorna när de färdades genom Durotar.",h="En karavanlast på väg till Rezlak ligger utspridd bland harpiornas boplatser i Razorwind Canyon.",kw={"durotar","dustwind-harpior","gazlowe","razorwind canyon","rezlak","sack of supplies"},ang={["faction:Horde"]="Genom att återta förnödenheterna från traktens rovdjur kan byggarbetet vid Orgrimmars gränsmarker fortsätta utan kostsamma förseningar."},sec={{t="En plundrad karavan",b="Rezlak behöver regelbundna leveranser till sitt arbete utanför Orgrimmar. Gobliningenjören har fått uppdraget av Gazlowe i Ratchet och bygger åt Horde. En karavan med en utlovad leverans passerade nära kanjonvägen söder om Orgrimmar, där Dustwind-harpiorna överföll den. De släpade lasten till sina boplatser i Razorwind Canyon och spred säckarna bland jord och rasbranter intill sina häckningsplatser."}},faq={{q="Vad finns i förrådssäckarna?",a="Säckarna innehåller byggmaterial och handelsvaror till Gazlowes ingenjörsarbete, avsedda att stödja orciska byggprojekt nära Orgrimmar. Utan dem har Rezlak inga förnödenheter för att slutföra sitt arbete.",al={"innehåll i förrådssäckar","vad finns i säckarna","rezlaks förråd"}},{q="Vem stal förråden?",a="Dustwind-harpiorna stal förnödenheterna. De är en vild fågelliknande ras som håller till i Razorwind Canyons höga klippskrevor och raviner.",al={"vem tog förråden","vem stal säckarna"}},{q="Vem är Rezlak?",a="Rezlak är en gobliningenjör som Gazlowe skickade från Ratchet för att hjälpa Horde att bygga och underhålla infrastruktur längs vägarna i Durotar.",al={"vem är rezlak","rezlaks bakgrund"}}},fx={["812e6d27"]={q="Varifrån kommer de här säckarna med förnödenheter?",a="Säckarna ingick i en leverans som skickades till Durotar för Gazlowes och hans gobliningenjörers räkning. De skulle hjälpa orcherna att bygga och underhålla sina bosättningar, men karavanen som fraktade dem överfölls och plundrades längs vägen innan den nådde fram.",al={"sack of supplies ursprung","varifrån kom förnödenheterna","vem gjorde försörjningssäckarna"}},["55ee41bd"]={q="Varför vill Rezlak ha de här säckarna med förnödenheter?",a="Rezlak kan inte utföra byggarbetet som Gazlowe tilldelat honom utan rätt utrustning och material. Harpyor från Razorwind Canyon plundrade karavanen med hans verktyg och förnödenheter, så goblinförmannen kan inte komma vidare förrän någon återfår den stulna lasten.",al={"varför vill rezlak ha förnödenheter","varför behövs säckarna med förnödenheter","varför blåser det i öknen förnödenheter"}}},fp="16,156,19.381.0,34.197.0,23.118.0,14.122.0"}
P.entries["item:salty-scorpid-venom"] = {n="Salty Scorpid Venom",s="Salty Scorpid Venom är en frätande vätska som utvinns ur skorpioner som stryker omkring i The Shimmering Flats i Thousand Needles. Den är full av naturliga salter från ökenmarken och uppskattas av gnomiska raketförare som försöker utveckla ett flyktigt bränsle med extremt hög temperatur.",h="Salty Scorpid Venom är en frätande vätska som utvinns ur skorpioner som stryker omkring i The Shimmering...",kw={"fizzle brassbolts","mirage raceway","salty scorpid venom","scorpid reaver","scorpid terror","skorpiongift","the shimmering flats","thousand needles"},ang={["profession:Engineering"]="Uppfinnare som mekar i The Shimmering Flats letar ständigt efter alternativ till vanlig olja och kol och testar organiska gifter som flyktiga förbränningsacceleratorer.",["race:Gnome"]="Bara gnomisk uppfinningsrikedom skulle kunna komma på tanken att ta dödligt ökenväsengift, blanda det med nega-katalysatorer och spruta in det i en raketmotor bara för att kapa några sekunder på varvtiden."},sec={{t="Ett flyktigt förbränningsämne",b="Skorpionerna som kryper omkring på den torra vidsträckta marken i The Shimmering Flats har anpassat sig till en miljö med ovanligt mycket mineraler. Under generationer har giftet från djur som Scorpid Reavers och Scorpid Terrors tagit upp enorma mängder salt från trakten. I stället för att brygga motgifter eller vanliga gifter uppskattar gnomiska uppfinnare som Fizzle Brassbolts denna frätande blandning som en möjlig tillsats i bränsle för högförbränningsmotorer."},{t="Bränsle i kapplöpningen",b="På Mirage Raceway driver ingenjörstävlingen mellan gnomer och gobliner uppfinnare till att prova allt farligare material i sina raketbilar. Fizzle Brassbolts tror att om han kokar ner det saltbemängda giftet, behandlar det med särskilda katalysatorer och blandar det i drivmedelstankarna, får han den brännande hetta som krävs för att köra ifrån goblinförarna på saltmarkerna."}},faq={{q="Vilka varelser producerar Salty Scorpid Venom?",a="Det samlas in från de farliga skorpioner som strövar på saltmarkerna i Thousand Needles, särskilt Scorpid Reavers och Scorpid Terrors.",al={"vem släpper salty scorpid venom","var hittar man skorpiongift","skorpiongiftets källa"}},{q="Varför är giftet så salt?",a="Skorpionerna lever helt och hållet på den mineralbelagda marken i The Shimmering Flats. Deras kroppar tar upp de koncentrerade salterna från den uttorkade sjöbottnen, vilket ger deras giftkörtlar en tydlig salthalt.",al={"varför är det salt","förklaring till saltmarksgift","skorpionernas salt i historien"}},{q="Vem vill ha giftet och varför?",a="Fizzle Brassbolts, en gnomisk ingenjör på Mirage Raceway, vill ha giftet för att ta fram en experimentell bränsleblandning som brinner tillräckligt hett för att driva hans raketbil till seger.",al={"vem behöver skorpiongift","varför vill fizzle ha gift","fizzle brassbolts uppdragsföremål"}}},fx={["9840b612"]={q="Vad är Salty Scorpid Venom?",a="Det är en kraftfull, mineralrik vätska som utvinns ur skorpionerna som stryker omkring i Shimmering Flats. Den hårda, uttorkade saltbassängen har fått traktens skräckskorpioner och plundrare att utveckla ett ovanligt salthaltigt gift. Det är dödligt som naturligt toxin, men dess reaktiva kemiska egenskaper gör det mycket intressantare för mekaniker som råreagens än som ett enkelt gift.",al={"vad är salty scorpid venom","salty scorpid venom","skorpiongift i saltslätten"}}},fp="19,215,27.321.0,27.317.0,43.99.0,26.173.0,29.181.0"}
P.entries["item:samophlange-item"] = {n="Samophlange",s="I The Barrens gömmer sig Samophlange inuti en automatisk kontrollpanel. Goblinmekaniker kan inte förklara vad den märkliga komponenten gör.",h="I The Barrens gömmer sig Samophlange inuti en automatisk kontrollpanel.",kw={"the barrens","konsol","ratchet","samophlange","sputtervalve","tinkers union","undermine"},ang={["profession:Engineering"]="Som ingenjör kanske du känner igen Samophlange som en onödigt komplicerad konstruktion. Dess utsmyckade utsida döljer en så ömtålig mekanism att den går sönder när den läggs på golvet."},sec={{t="En förbryllande konstruktion",b="Samophlange ligger inuti en kontrollpanel i The Barrens, bakom en labyrint av ledningar och ihåliga rör. Det krävs ett noggrant sökande för att få loss komponenten ur sitt hölje. Den ser ut att vara en viktig del av urverks- och ångmaskineri, men goblinuppfinnare kan inte förstå vad den är till för. De tänker skicka den till Tinkers' Union i Undermine, men den ömtåliga delen kanske inte överlever ovarsam hantering."},{t="Nyfikenhet och katastrof",b="Sputtervalve, en ingenjör i Ratchet, planerar att skicka Samophlange till de främsta tänkarna i Tinkers' Union för undersökning. Goblinernas nyfikenhet sätter käppar i hjulen för planen. När Sputtervalve lägger ner den ömtåliga apparaten för att undersöka dess inre delar går den ofta sönder och blir skrot."}},faq={{q="Vad är en Samophlange?",a="Samophlange är en märklig mekanisk komponent som tagits från en kontrollpanel i The Barrens. Dess syfte är okänt, och panelen runt den är full av rör och ledningar som verkar vara till ingen nytta.",al={"vad gör en samophlange","samophlanges syfte","vad är det här för föremål"}},{q="Vem vill ha Samophlange?",a="Sputtervalve, en ingenjör i Ratchet, vill att Samophlange förs till honom så att han kan undersöka den och skicka den till Tinkers' Union.",al={"vem behöver samophlange","vem ska jag ge samophlange till"}},{q="Vad gör Sputtervalve med den?",a="Sputtervalve planerar att skicka Samophlange till Undermine för att Tinkers' Union ska undersöka den. Först lägger han ner den för att inspektera den, och den ömtåliga mekanismen går sönder.",al={"sputtervalve samophlange","vad händer med samophlange"}},{q="Var kommer Samophlange ifrån?",a="Samophlange sitter inuti en fungerande kontrollpanel i norra The Barrens, bakom lager av förvirrande och till synes onödig maskinutrustning.",al={"samophlanges plats","var hittar man den"}}},fp="11,140,22.353.0,25.264.1,22.204.0,26.124.0,34.156.1,36.142.0"}
P.entries["item:samophlange-manual"] = {n="Samophlange Manual",s="I Orgrimmar söker Rilli Greasygob efter de utspridda sidorna ur Samophlange Manual. Handboken innehåller instruktioner för att reparera och använda Venture Companys samophlange.",h="I Orgrimmar söker Rilli Greasygob efter de utspridda sidorna ur Samophlange Manual.",kw={"the barrens","boss copperplug","boulder lode mine","ingenjörskonst","handbok","rilli greasygob","samophlange","sputtervalve","venture company"},ang={["faction:Horde"]="Manualen låter gobliner på Hordes sida i Orgrimmar studera och använda företagets borrmaskineri på nya sätt, mitt framför näsan på Venture Company.",["profession:Engineering"]="Manualen avslöjar Venture Companys skyddade teknik och visar hur goblinernas mekaniker vaktar affärshemligheter och fungerande ritningar från sina gelikar."},sec={{t="Apparatens hemligheter",b="Boss Copperplug vaktade Venture Companys kunskap om samophlangen. Den ambitiöse förmannen höll manualens sidor undan från de flesta arbetarna och gav lösa blad endast till sina mest lojala underställda. När apparaten gled företaget ur händerna kunde ingen reparera den utan att samla ihop den sönderrivna dokumentationen från Copperplug och hans besättning vid Boulder Lode Mine."},{t="En rival med ambitioner",b="Rilli Greasygob lämnade Venture Company och slog sig ner i Orgrimmar för att lära sig hur samophlangen byggdes. Copperplug hade aldrig tyckt om honom, så Rilli är beroende av företagsamma resenärer som hämtar manualens omslag och lösa blad. När handboken satts ihop får goblinernas mekaniker, som arbetar tillsammans med Horde, en sällsynt inblick i Venture Companys ingenjörskonst."}},faq={{q="Vad är Samophlange Manual?",a="Samophlange Manual förklarar hur man använder och reparerar Venture Companys komplexa, egensinniga mekaniska apparat.",al={"vad är samophlange manual","samophlange-bok","samophlange-handbok"}},{q="Vem ägde handboken från början?",a="Boss Copperplug, en förman för Venture Company vid Boulder Lode Mine i nordöstra The Barrens, behöll manualen. Han vaktade dess hemligheter och gav enskilda sidor endast till sina mest betrodda arbetare.",al={"vem har handboken","boss copperplugs handbok","vem skrev handboken"}},{q="Varför är handboken uppdelad i sidor?",a="Boss Copperplug delade upp manualen för att hindra rivaler och underställda han inte litade på från att förstå hela apparaten. Han behöll omslaget och fördelade fem särskilda sidor bland sina gruvarbetare och operatörer.",al={"varför hitta handbokens sidor","utspridda sidor ur handboken","varför saknas sidor"}},{q="Vem vill läsa den färdiga handboken?",a="Rilli Greasygob, en ingenjör i Orgrimmar, vill ha den återställda manualen för att förstå och reparera den trasiga samophlangen som hämtats från The Barrens.",al={"vem behöver handboken","rilli greasygob","vem vill ha samophlange manual"}},{q="Vad används en samophlange till?",a="Ingen utanför Venture Company verkar veta vad en samophlange används till. Företaget experimenterade med en vid en liten forskningsplats sydväst om Sludge Fen i The Barrens, men inte ens ingenjörerna som studerade den kunde begripa särskilt mycket av den.",al={"vad gör samophlange","samophlanges syfte","samophlange syfte"}}},fp="18,165,26.354.0,18.351.0,31.117.0,32.197.0,34.191.0,39.147.0,31.252.0"}
P.entries["item:sample-elven-gem"] = {n="Sample Elven Gem",s="Sample Elven Gem är ett bevis på en skatt som Shakes O’Breen’s besättning har hittat. Fleet Master Seahorn i Booty Bay behöver den som besked om deras upptäckt.",h="Sample Elven Gem är ett bevis på en skatt som Shakes O’Breen’s besättning har hittat.",kw={"booty bay","alvisk ädelsten","fleet master seahorn","sample elven gem","shakes o’breen","sjunken skatt","skatt"},sec={{t="Ett prov åt Seahorn",b="Shakes O’Breen’s besättning har hittat en skatt, men lågvatten och vaksamma varelser hindrar dem från att ge sig av. De behöver att du tar Sample Elven Gem till Fleet Master Seahorn i Booty Bay. Ädelstenen bevisar att de har hittat skatten och berättar för Seahorn att de försöker bärga mer."}},faq={{q="Vad är Sample Elven Gem?",a="Sample Elven Gem är ett bevis på skatten som Shakes O’Breen’s besättning upptäckte.",al={"prov på ädelsten","prov på alvisk ädelsten"}},{q="Vem gav mig Sample Elven Gem?",a="Shakes O’Breen gav dig Sample Elven Gem att ta med till Fleet Master Seahorn.",al={"vem gav mig ädelstenen","shakes ädelsten"}},{q="Vem behöver ädelstenen?",a="Fleet Master Seahorn i Booty Bay behöver Sample Elven Gem som bevis på besättningens upptäckt.",al={"vem vill ha den här ädelstenen","ädelsten till seahorn"}},{q="Varför kan inte Shakes O’Breen’s besättning ge sig av?",a="Tidvattnet är för lågt, och varelserna som besättningen störde håller uppsikt över deras rörelser.",al={"varför fast","varför kan de inte ge sig av"}}},fp="16,150,20.265.0,29.83.0,33.87.0,18.96.0,44.87.0"}
P.entries["item:sample-ichor"] = {n="Sample Ichor",s="Den här flaskan innehåller ett renat extrakt av den vidriga vätska som håller Silverpine Forests Rot Hide-gnoller vid liv. Apothecary Renferrel destillerade ner ämnet till dess grundbeståndsdelar, men spår av både nekromanti och häxmästarmagi finns kvar.",h="Den här flaskan innehåller ett renat extrakt av den vidriga vätska som håller Silverpine Forests Rot...",kw={"apothecary renferrel","bethor iceshard","magic quarter","rot hide","rot hides ursprung","sample ichor","silverpine","undercity"},ang={["class:Mage"]="Bethor Iceshard använder specialiserade spådomsbesvärjelser för att läsa resterna i provet. Det visar värdet av klassisk arkan analys när man möter mörk trolldom.",["class:Warlock"]="Apothecary Renferrel upptäcker särskilt häxmästarkonst invävd i nekromantin i ikorn, vilket antyder att felfyllda seder hjälpte till att binda dessa odöda bestar."},sec={{t="Att nysta upp Rot Hides",b="Rot Hide-gnollerna som stryker omkring i Silverpine Forest är inga vanliga bestar. Efter att ha hämtat prover från varelserna och deras kvarlevor reducerade Apothecary Renferrel från Royal Apothecary Society den vidriga vätskan till dess beståndsdelar. Den kemiska analysen visade att ikorn var konstgjort och framställt genom en förening av mörka skolor: nekromantiska riter sammanflätade med häxmästarmagi. Eftersom hantverket bakom det gränsar till arkan kunskap bortom enkel alkemi förpackade Renferrel provet och skickade det till Undercity, där Bethor Iceshard skulle undersöka det med spådomskonst."}},faq={{q="Vad är Sample Ichor?",a="Det är ett renat extrakt som Apothecary Renferrel framställt av kroppsvätskor från Rot Hide-gnollerna. Renferrel separerade det i dess grundbeståndsdelar för att analysera de magiska metoder som använts för att skapa de vandrande döda bestarna.",al={"sample ichor","vad är det här ikorn","vad är sample ichor"}},{q="Vem behöver se provet?",a="Provet måste levereras till Bethor Iceshard, en odöd magiker som är stationerad i Magic Quarter i Undercity. Bethors expertis inom spådomskonst och magiska traditioner gör att han kan identifiera magiska spår som vanlig alkemi inte kan urskilja.",al={"vem ska jag lämna ikorn till","lämna in sample ichor","bethor iceshard ikorn"}},{q="Vilken sorts magi finns i ikorn?",a="Renferrel upptäckte en kombination av häxmästar- och nekromantisk magi bunden i vätskan. När Bethor Iceshard undersöker flaskan noterar han att den är genomsyrad av kraftfulla, uråldriga förtrollningar som kräver en djupare spådom för att blottläggas helt.",al={"vilken magi finns i ikorn","typ av ikornmagi","rot hide-magi"}},{q="Varför analyserade inte apotekarna det färdigt själva?",a="Royal Apothecary Society är skickligt inom alkemi, gifter och kroppsliga farsoter, men att tyda komplexa arkanvävar kräver en specialiserad magiker. Bethor Iceshard är skicklig på att identifiera magiska skolor och nysta upp esoteriska besvärjelser som går bortom en apotekares vanliga utrustning.",al={"varför skickade apotekaren det till bethor","varför analyserade inte apotekaren rot hide-ikornet"}}},fx={f4e4cc11={q="Varifrån kommer Sample Ichor, och vem gjorde det?",a="Apothecary Renferrel framställde den här flaskan genom att bryta ned rått ichor som samlats in från rot hide-gnollerna i Silverpine Forest. Hans första analys visade att den som skapade ursprungsämnet hade genomsyrat det med både nekromanti och kriglocksmagi, men vem som egentligen låg bakom skapelsen återstår att ta reda på.",al={"sample ichors ursprung","varifrån kom sample ichor","vem gjorde sample ichor"}},["045e6062"]={q="Varför vill Bethor Iceshard ha Sample Ichor?",a="Apothecary Renferrel nådde gränsen för den alkemiska vetenskapen när han försökte ta reda på vad som skapat rot hides. Han skickade det här renade provet till Bethor Iceshard i Undercitys Magic Quarter, eftersom Bethor har djupa kunskaper i mystiska och mörka konster. Det gör att han kan använda spådomsmagi för att identifiera de svårtydda besvärjelser som vävts in i vätskan.",al={"varför vill bethor ha sample ichor","varför efterfrågas sample ichor","sample ichors syfte för bethor"}}},fp="12,164,24.380.0,25.196.0,29.202.0,39.183.0,59.236.0"}
P.entries["item:sample-of-zanzil-s-altered-mixture"] = {n="Sample of Zanzil's Altered Mixture",s="En kurir för Sample of Zanzil's Altered Mixture över havet till Tarren Mill. Brygden kommer från häxdoktorn Zanzil och försvagar den som bär den. Serge Hinott kan hitta ett botemedel och avslöja hur giftet fungerar.",h="En kurir för Sample of Zanzil's Altered Mixture över havet till Tarren Mill.",kw={"förändrad blandning","hillsbrad","gifter","skurk","serge hinott","the sludge fen","tarren mill","zanzil"},ang={["class:Rogue"]="Som skurk i Horden bär du det här farliga provet till Serge Hinott, vars lektioner handlar om att brygga, hantera och använda dödliga gifter.",["faction:Horde"]="Som resenär i Horden för du brygden över en kontinent med zeppelinare och längs vägar, från Kalimdor till de Fördömdas områden i Lordaeron."},sec={{t="En giftig symbol",b="En agent bär blandningen efter att ha infiltrerat Venture Company's torn nära The Sludge Fen i The Barrens. Provet kommer från ett gömställe i Gallywix's lockbox, och Zanzils brygd har gjort agenten sjuk. Shenthul skickar den drabbade agenten över Great Sea med provet. I Tarren Mill i Hillsbrad Foothills har apotekaren Serge Hinott den ovanliga skickligheten att isolera giftet och ta reda på vad det består av."},{t="Giftkonstens hemligheter",b="Serge Hinott undersöker den förändrade blandningen för att hjälpa den drabbade kuriren och avslöja hur man brygger och hanterar kraftfulla gifter ute på fältet. Hordens skurkar söker den här kunskapen för att bemästra de mörkare konsterna i sitt yrke."}},faq={{q="Vad är det här för blandning?",a="Det är en alkemisk brygd med koppling till häxdoktorn Zanzil, som återfanns i Venture Company's torn nära The Sludge Fen i The Barrens. Det kraftiga giftet orsakar långvariga, försvagande effekter hos alla som rör vid det direkt.",al={"vad är zanzil's mixture","prov på zanzils förändrade blandning","zanzils giftprov"}},{q="Varför ska jag ta den till Serge Hinott?",a="Serge Hinott är apotekare i Tarren Mill i Hillsbrad Foothills. Hans kunskap kan neutralisera brygdens effekter och ge ett tillförlitligt botemedel innan giftet orsakar bestående skada.",al={"vem är serge hinott","varför ta den till tarren mill","botemedel mot zanzil's mixture"}},{q="Vem är Zanzil?",a="Zanzil the Outcast är en djungeltrollshäxdoktor som är känd för att skapa elixir, gifter och mutagener som framkallar vansinne. Hans giftiga recept har spridits från hans hemtrakter i djungeln till legosoldater och industriella verksamheter som Venture Company.",al={"vem är zanzil","zanzil the outcast","zanzils historia"}},{q="Hur tar jag mig till Tarren Mill för att lämna över den?",a="Ta zeppelinaren från Durotar till Undercity i Tirisfal Glades. Följ sedan huvudvägen söderut genom Silverpine Forest och skyltarna österut in i Hillsbrad Foothills till Tarren Mill.",al={"hur tar man sig till tarren mill","resa till hillsbrad","vägbeskrivning till tarren mill"}}},fp="34,213,13.394.0,22.207.1,21.236.0,41.185.0,14.243.0,43.189.0"}
P.entries["item:sample-snapjaw-shell"] = {n="Sample Snapjaw Shell",s="Över hela The Barrens bär Sample Snapjaw Shells på kvarvarande livskraft från sötvattensoaser. Taurendruider skickar dem över Stora havet för att hjälpa till att läka Silverpine Forest.",h="Över hela The Barrens bär Sample Snapjaw Shells på kvarvarande livskraft från sötvattensoaser.",kw={"barrens","mura runetotem","oas","sample snapjaw shell","the sepulcher","silverpine","snapjaw","sköldpaddsskal"},ang={["class:Druid"]="För druider i Cenarion Circle ger studiet av oasernas snapjaw viktiga lärdomar om hur livet håller ut och hur härjad mark kan läkas.",["race:Tauren"]="Som tauren kan du se skalets resa som ett åtagande gentemot Jordmodern. Ditt folk för med sig hjälp och naturlig läkekraft över havet, även till sina odöda allierade."},sec={{t="En gnista av oasens liv",b="Snapjaw trivs i The Barrens frodiga, märkliga oaser. Deras tåliga skal behåller ett svagt inre sken och pulserar av energi långt efter att de skilts från djuret. Taurendruider som följer landets snabba förändringar ser i dessa pansarskal en motståndskraftig gnista från Kalimdors vildmark. Deras livskraft visar hur livet kan blomstra även i hårda, torra omgivningar."},{t="Att hela avlägsna länder",b="Taurennaturalister skickar kurirer över havet med skal till Mura Runetotem vid Sepulcher. Mura är stationerad i Silverpine Forests härjade vidder och söker sätt att hjälpa Forsaken att läka de norra länderna. Hon studerar livskraften som bevarats i snapjawens pansar och hoppas hitta något som kan förnya en sjuk skog och återge döende jord sin växtkraft."}},faq={{q="Vad gör det här snapjaw-skalet speciellt?",a="Ett Sample Snapjaw Shell behåller ett svagt inre sken och en livspuls långt efter att det samlats in. Det kommer från snapjaw i närheten av The Barrens märkliga sötvattensoaser, där de naturliga energierna är ovanligt starka.",al={"varför skalet är speciellt","vad är ett snapjaw-skal","lysande skal"}},{q="Vem behöver det här provet?",a="Mura Runetotem, en taurendruid, behöver skalet vid Sepulcher i Silverpine Forest. Hon är där för att hjälpa Forsaken att hitta sätt att läka döende marker.",al={"vem vill ha skalet","var lämnar jag skalet","mura runetotem uppdrag"}},{q="Varför skicka ett skal från Barrens ända till Silverpine?",a="Silverpines skog är sjuk och härjad, medan livet plötsligt har blomstrat vid oaserna i The Barrens och hållit i sig. Druider hoppas att livskraften hos Kalimdors djur kan lära dem att läka Lordaerons skadade jord.",al={"varför skicka det till silverpine","skalets koppling till silverpine"}},{q="Är skalet farligt eller förgiftat?",a="Nej. Skalet utstrålar ren livskraft snarare än mörk magi. Druiderna ser den kvarvarande energin i The Barrens mystiska, plötsliga tillväxt som en naturlig motståndskraft värd att odla.",al={"är skalet ont","är skalet fördärvat"}}},fx={["6161673b"]={q="Vad är Sample Snapjaw Shell?",a="Det är ett prov från skalet på en snapjaw-sköldpadda som hittats i Barrens torra trakter. Skalet är genomsyrat av en märklig, pulserande livskraft och har bevarats noggrant så att dess ovanliga livsenergi kan undersökas långt från Kalimdors slätter.",al={"vad är sample snapjaw shell","föremålet snapjaw-skal"}},c3ef5b23={q="Varifrån kommer Sample Snapjaw Shell?",a="Det kommer från vilda snapjaw-sköldpaddor som lever kring oaserna och vattendragen i Barrens. Hordens äventyrare samlade in det naturliga skalet i Kalimdor, och taurendruiderna valde det som ett representativt prov på den blomstrande livskraften i det solstekta ödemarkslandskapet.",al={"snapjaw-skalets ursprung","varifrån kom snapjaw-skalet","vem gjorde sample snapjaw shell"}}},fp="20,149,21.326.0,21.350.0,38.194.0,22.140.0,51.200.0,34.157.0"}
P.entries["item:samuel-s-remains"] = {n="Samuel's Remains",s="Samuel's Remains är de jordiska kvarlevorna efter Samuel Fipps, en före detta invånare i Tirisfal Glades som föll för Scourge. Äventyrare samlar in dem nära Deathknell och begraver dem bredvid hans hustru Marla för att uppfylla hennes sista önskan.",h="Samuel's Remains är de jordiska kvarlevorna efter Samuel Fipps, en före detta invånare i Tirisfal Glades som...",kw={"deathknell","marla fipps","marlas grav","marlas sista önskan","novice elreth","samuel fipps","samuel's remains"},ang={["race:Undead"]="Att begrava Samuels kvarlevor blir en tidig lektion i Forsakens identitet: respekten för de tragiskt döda visar den avgörande moraliska skiljelinjen mellan fria odöda och Scourges tanklösa trälar."},sec={{t="En tragisk återförening",b="Innan de odödas pest svepte över Lordaeron levde Samuel Fipps fridfullt med sin hustru Marla. När smittan slog till dukade Samuel under och bands i Scourges tanklösa tjänst. Marla undkom att bli odöd, men föll för handen på den make hon älskade. Trots detta grymma slut önskade hon sig inte hämnd, utan att få vara tillsammans för evigt: hon bad att begravas bredvid Samuel när hans förbannade kropp väl hade fått vila. Novice Elreth i Deathknell värvar nyvakna Forsaken för att spåra upp Samuels kringirrande kropp nordost om bosättningen, hämta hans ben och begrava dem på den främsta raden i den lokala kyrkogården."}},faq={{q="Vem var Samuel Fipps?",a="Samuel Fipps var en människa som levde i Tirisfal Glades före det tredje kriget. När Scourges pest trängde in dukade han under och återuppstod som en odöd träl under Lich King. Driven av tanklös hunger dödade han till slut sin egen hustru Marla.",al={"samuel fipps","vem är samuel","samuels bakgrund"}},{q="Var hittar man Samuels kvarlevor?",a="De hämtas från Samuel Fipps själv, som strövar bland lägrets ruiner längs vägen nordost om Deathknell. När man gör slut på hans tanklösa tillvaro går det att hämta hans jordiska kvarlevor.",al={"hitta samuels kvarlevor","var är samuel fipps","samuels plats"}},{q="Varför begraver Forsaken honom bredvid hans hustru?",a="Marlas sista önskan var att vila bredvid sin älskade make, trots att det var han som dödade henne. Novice Elreth hedrar denna önskan för att visa att de nybefriade Forsaken fortfarande hyser medkänsla och respekt för de döda, och har kvar den mänsklighet som skiljer dem från Scourge.",al={"varför begrava samuel","marlas grav","marlas sista önskan"}}},fx={["29aac9a9"]={q="Varifrån kommer Samuel's Remains?",a="Det här är de fysiska kvarlevorna efter den dödlige Samuel Fipps, en tidigare invånare i Tirisfal Glades som föll offer för odödhetens pest och blev en viljelös pjäs i Scourges tjänst. Efter att ha strövat omkring i vildmarken nordost om Deathknell slås hans odöda kropp ned, så att kvarlevorna äntligen kan samlas in och begravas.",al={"samuels kvarlevors ursprung","varifrån kommer samuels kvarlevor","vem gjorde samuels kvarlevor"}}},fp="16,88,16.522.0,21.221.0,33.177.0,45.258.0"}
P.entries["item:sapphire-of-aku-mai"] = {n="Sapphire of Aku'Mai",s="Aku'mais safirer är lysande, vattenmättade mineralkluster som växer längs de underjordiska gångarna i Blackfathom Deeps. De framryckande naga har börjat skörda dessa ädelstenar, vilket får Earthen Ring att söka upp dem innan deras kraftfulla arkaniska kraft kan utnyttjas.",h="Aku'mais safirer är lysande, vattenmättade mineralkluster som växer längs de underjordiska gångarna i...",kw={"aku'mai","blackfathom deeps","kristaller","je'neu sancrea","naga","safir","vattenandar","the zoram strand"},ang={["class:Mage"]="Den naturliga vattenmättnaden gör dessa råa safirer mycket eftertraktade som ledare för kraftfulla arkaniska komponenter.",["class:Shaman"]="Shamaner i Earthen Ring som Je'neu Sancrea kan lätt uppfatta vattenandarna som är bundna till dessa ädelstenar och ser nagaernas skörd som ett elementärt hot."},sec={{t="Ädelstenar från djupet",b="Sapphires of Aku'Mai har upptäckts i de vattenfyllda grottmynningarna till Blackfathom Deeps längs Ashenvales Zoram Strand och är kristallformationer rika på elementarenergi. Vattnets andar håller sig tätt till dem, vilket gör dem till utmärkta katalysatorer för magiska verk. När spejare rapporterade att de underjordiska naga hade börjat bryta loss dessa kluster från grottväggarna, sökte shamanen Je'neu Sancrea hjälp från äventyrare för att beslagta dem. I ormfolkets händer skulle stenarna lätt kunna användas för att driva förödande arkaniska ritualer."}},faq={{q="Vad är en Sapphire of Aku'Mai?",a="Det är lysande safirkristaller som kantar väggarna i Blackfathom Deeps. De är nära knutna till vattnets elementarandar och bär på en stark arkanisk och elementar resonans.",al={"vad är denna kristall","sapphire of aku'mai-historia","vad är dessa ädelstenar"}},{q="Varför samlar naga på dessa safirer?",a="Deras exakta avsikter är fortfarande okända, men Je'neu Sancrea misstänker att naga tänkte utnyttja kristallernas rika vatten- och arkaniska energier för farlig trolldom i det nedsänkta templet.",al={"varför vill naga ha safirer","naga skördar kristaller"}},{q="Vem letar efter dessa safirer?",a="Je'neu Sancrea, en shaman i Earthen Ring som är stationerad vid Zoram'gar Outpost längs The Zoram Strand i Ashenvale, ger resenärer i uppdrag att samla in dem så att de inte hamnar i naga-händer.",al={"vem vill ha sapphires of akumai","vem lämnar in essence of akumai"}},{q="Är kristallerna direkt kopplade till besten Aku'mai?",a="De är uppkallade efter Aku'mai, den monstruösa hydran som lever i djupet, men kristallerna växer naturligt på grottväggarna. Namnet speglar att de finns nära den mörka närvaro som lurar bland ruinerna.",al={"koppling till aku'mai","kommer den från aku'mai"}}},fx={["12f03799"]={q="Varifrån kommer Sapphires of Aku'Mai, och vem gjorde dem?",a="De här stora safiranhopningarna växer naturligt på grottväggarna i de första tunnlarna i Blackfathom Deeps. De är inte skapade av dödliga händer, utan naturliga mineralbildningar genomsyrade av grottans omgivande energier. Vattenandar dras naturligt till kristallerna och ger dem en inneboende elementär kraft.",al={"sapphire of aku'mais ursprung","vem gjorde sapphire of aku'mai","varifrån kommer sapphires of aku'mai"}}},fp="19,179,16.380.0,30.139.0,44.176.0,35.158.0,54.186.0"}
P.entries["item:sapphire-of-sky"] = {n="Sapphire of Sky",s="Sapphire of Sky är en av fyra heliga Relics of Wakening som nattalverna förvarar i Ban'ethil Barrow Den. Den är en oumbärlig fokuspunkt för att tryggt kalla sovande Druids of the Talon tillbaka från The Emerald Dream.",h="Sapphire of Sky är en av fyra heliga Relics of Wakening som nattalverna förvarar i Ban'ethil Barrow Den.",kw={"athridas bearmantle","ban'ethil barrow den","chest of the sky","druid of the talon","emerald dream","relics of wakening","sapphire of sky"},ang={["class:Druid"]="Safiren visar hur omsorgsfulla ritualer krävs när man sänder sin ande till The Emerald Dream, och hur lätt en sådan samhörighet kan bli dödlig utan heliga ankare.",["race:NightElf"]="Att bevara de heliga artefakterna i Ban'ethil Barrow Den är avgörande för att skydda Teldrassils sköra ordning medan korruptionen tilltar."},sec={{t="Väckningsritualen",b="Djupt inne bland Teldrassils rötter står Druids of the Talon i förbindelse med vildmarken medan de vilar i dvala i Ban'ethil Barrow Den. Att vakna ur sådana djupa transliknande tillstånd och återvända till den vakna världen är en känslig och farlig process. För att skydda övergången förlitar sig druiderna på fyra välsignade artefakter som kallas Relics of Wakening: Black Feather Quill, Raven Claw Talisman, Rune of Nesting och Sapphire of Sky. Utan denna resonanta ädelsten förblir harmonin som krävs för att kalla sovande andar tillbaka från The Emerald Dream ofullständig, vilket gör dem sårbara för att bli fångade där för evigt."},{t="Hotet i Ban'ethil",b="När korrumperade Gnarlpine-furbolger tog över Ban'ethil Barrow Den lämnades de heliga artefakterna kvar i sina utsmyckade förvaringsplatser. Sapphire of Sky ligger säkert förvarad i Chest of the Sky, bland de slingrande underjordiska gångarna. Medan druiderna fortfarande sover och furbolgerna härjar omkring dem är det brådskande för Athridas Bearmantle i Dolanaar att hämta denna ädelsten tillsammans med de andra relikerna, innan de sovande går förlorade för alltid."}},faq={{q="Vad är Sapphire of Sky?",a="Det är en helig ädelsten och en av de fyra Relics of Wakening som förvaras i Ban'ethil Barrow Den. Tillsammans med tre fågeltalismaner hjälper den till att leda Druids of the Talon tryggt ut ur The Emerald Dream.",al={"sapphire of sky berättelse","vad är den här ädelstenen","himmelsafir"}},{q="Var förvaras Sapphire of Sky?",a="Den förvaras i Chest of the Sky, i den underjordiska labyrinten i centrala Teldrassil, i Ban'ethil Barrow Den.",al={"var hittar man sapphire of sky","var finns chest of the sky","safirens plats"}},{q="Varför behövs safiren just nu?",a="Korrumperade Gnarlpine-furbolger invaderade Ban'ethil Barrow Den och utsatte de sovande druiderna för stor fara. Druider i djup trans kan inte bara vakna av sig själva. Athridas Bearmantle behöver safiren och de andra relikerna för att utföra den känsliga väckningsritualen innan de sovande går förlorade för alltid.",al={"varför hämta safiren","syftet med relics of wakening"}},{q="Vem använder artefakten?",a="Druids of the Talon och ritualväktare som Athridas Bearmantle använder den under gemensamma riter för att väcka sovande bröder ur deras djupa samhörighet med naturen.",al={"vem använder sapphire of sky","druidernas ritualädelsten"}}},fp="15,171,19.457.0,23.394.0,28.199.0,34.132.0,37.295.0,23.152.0"}
P.entries["item:sara-balloo-s-plea"] = {n="Sara Balloo's Plea",s="Sara Balloo's Plea är ett handskrivet brev från en sörjande änka i Ironforge. Sorgen gör att hon inte klarar av att möta monarken, så hon ber en betrodd Alliance-mästare att överlämna brevet till King Magni Bronzebeard.",h="Sara Balloo's Plea är ett handskrivet brev från en sörjande änka i Ironforge.",kw={"a kings tribute","high seat","ironforge","magni bronzebeard","sara balloo","sara balloo's plea"},ang={["faction:Alliance"]="Sara anförtro sin vädjan enbart åt mästare som är erkända för sin tjänst för Alliance. Hon litar på att deras rykte ger hennes vädjan företräde hos kungligheten.",["race:Dwarf"]="För dvärgar är det en handling av djup samhörighet att bära Saras budskap till High Seat. Det ser till att ingen bergsman eller invånare förblir ohörd av King Magni, inte ens i sorgen."},sec={{t="En änkas vädjan",b="Sara Balloo's Plea skrevs efter en djup personlig tragedi och är en ödmjuk vädjan direkt till Ironforges tron. I sitt förtvivlade tillstånd vågar Sara inte själv gå till High Seat, utan söker en äventyrare som visat lojalitet och mod mot Alliance och kan överlämna hennes ord. Hon ber King Magni Bronzebeard att lyssna och rikta sin blick mot den privata sorgen och de uppoffringar som vanliga dvärgfamiljer gör i rikets tjänst."}},faq={{q="Vad är Sara Balloo's Plea?",a="Det är ett handskrivet brev från Sara Balloo, adresserat till King Magni Bronzebeard. Hon ber om hans kungliga uppmärksamhet medan hon sörjer i avskildhet.",al={"sara balloos vädjan","änkas brev ironforge","saras brev"}},{q="Varför behöver Sara Balloo någon annan som överlämnar brevet?",a="Sara är överväldigad av sorg och tror att hennes vädjan skulle bli lidande om hon visade sig inför kungen av Ironforge i ett sådant känslomässigt tillstånd. Därför förlitar hon sig på en Alliance-mästare.",al={"varför överlämna brevet","varför kan sara inte gå","saras sorg"}},{q="Vem får meddelandet?",a="Brevet är adresserat direkt till King Magni Bronzebeard och överlämnas till honom i High Seat i Ironforge.",al={"vem får vädjan","vem ska brevet till","brev till magni"}},{q="Vad leder det till att brevet överlämnas?",a="När brevet överlämnas får King Magni veta om Sara Balloo's sorg och inleder ett kungligt svar som hedrar hennes stupade familj.",al={"vädjans uppdragskedja","koppling till a kings tribute","vad händer sedan"}}},fx={["2b83ea9f"]={q="Varifrån kommer Sara Balloo's Plea, och vem skrev det?",a="Den här skrivna lappen har Sara Balloo själv författat. Hon är en sörjande dvärgkvinna i Ironforge. Förkrossad av sorg skrev hon meddelandet för att vädja till Ironforges tron och anförtrodde det åt en alliansmästare, i stället för att själv försöka göra den känslomässigt svåra resan till High Seat.",al={"vem skrev sara balloos vädjan","varifrån kom sara balloos vädjan","vem gjorde sara balloos vädjan"}},["4ac5e6cf"]={q="Varför vill någon ha Sara Balloo's Plea?",a="King Magni Bronzebeard behöver brevet för att kunna höra en sörjande undersåtes vädjan. Sara Balloo klarar inte av att stå inför monarken i sitt sorgsna tillstånd, så hon förlitar sig på att du överlämnar vädjan direkt till Ironforges härskare.",al={"varför behövs sara balloos vädjan","vem vill ha sara balloos vädjan","varför leverera sara balloos vädjan"}}},fp="18,110,16.229.0,27.127.0,53.166.0,26.76.0,40.136.1"}
P.entries["item:sarilus-foulborne-s-head"] = {n="Sarilus Foulborne's Head",s="Sarilus Foulborne's Head är en makaber trofé från en odöd trollkarl som vanhelgade vattnen i norra Kalimdor. Den fördes över gränsen från The Barrens till Ashenvale och är ett obestridligt bevis på att Sentinels har dödat den inblandande magikern.",h="Sarilus Foulborne's Head är en makaber trofé från en odöd trollkarl som vanhelgade vattnen i norra Kalimdor.",kw={"the barrens","dreadmist peak","huvud","magiker som frambesvärjer","sarilus foulborne","silverwind refuge","velene starstrike","vattenelementarer"},ang={["faction:Alliance"]="För att genomföra anfallet måste du infiltrera djupt in i fientligt hordterritorium i The Barrens och döda en farlig, självsvåldig besvärjare.",["race:NightElf"]="När Foulbornes huvud tas får Sentinels sin hämnd på en hänsynslös magisk vanhelgare som skändade landets andar."},sec={{t="En vanhelgare tystad",b="Högt uppe på Dreadmist Peak i norra The Barrens väckte den förfallne besvärjaren Sarilus Foulborne nattalvernas vrede genom att fördärva och binda svärmar av vattenelementarer. Från sin post vid Silverwind Refuge kände Sentinel Velene Starstrike igen hans vidriga verk och skickade mästare över gränsen in på hordens territorium för att sätta stopp för hans hänsynslösa experiment. Att hugga av magikerns huvud var det enda bevis Starstrike godtog för att bekräfta att hans hånfulla flin för alltid hade suddats ut, och det säkrade en viss ro åt Ashenvales plågade vatten."}},faq={{q="Vem var Sarilus Foulborne?",a="Sarilus Foulborne var en odöd magiker som slog sig ner på toppen av Dreadmist Peak i norra The Barrens. Han väckte nattalvernas vrede genom att förvrida och frammana stora mängder vattenelementarer, vilket fick Sentinel Velene Starstrike att beordra hans död.",al={"vem är sarilus","sarilus foulborne bakgrund","vem är foulborne"}},{q="Varför vill Sentinel Velene Starstrike ha hans huvud?",a="Velene Starstrike ville vara helt säker på att den arrogante trollkarlen var död. Sarilus hade öppet hånat henne medan han vanhelgade områdets vattenandar, och hans avhuggna huvud var det enda bevis hon godtog på att hotet var undanröjt.",al={"varför ta hans huvud","velene starstrike huvud","dödsbevis"}},{q="Var finns Sarilus Foulborne?",a="Han håller till allra högst upp på Dreadmist Peak, ett klippigt berg i norra The Barrens, strax söder om gränsen till Ashenvale.",al={"var finns foulborne","sarilus plats","magiker på dreadmist peak"}},{q="Varför vanhelgade Foulborne vattenelementarer?",a="Foulborne använde magiska besvärjelser för att kuva mängder av vattenelementarer och fördärvade dem i processen. Hans hänsynslösa manipulation rubbade den naturliga balansen i vattnen nära Ashenvale och utlöste en snabb vedergällning från Sentinels.",al={"varför fördärva elementarer","vattenelementarers fördärv","foulbornes motiv"}}},fx={a996e76e={q="Varifrån kommer Sarilus Foulborne's Head?",a="Det här avhuggna huvudet kommer direkt från Sarilus Foulborne, en förnekarmagiker som slagit sig ned på toppen av Dreadmist Peak i norra Barrens. Foulborne verkade nära gränsen till Ashenvale och ägnade dagarna åt att skända vattenelementarandar och provocera nattalverna, tills Sentinel Velene Starstrike skickade en äventyrare in på fiendens territorium för att sätta stopp för hans hån.",al={"sarilus huvudets ursprung","varifrån kom foulbornes huvud"}}},fp="24,177,18.497.1,26.241.1,50.217.0,35.104.1,44.240.0"}
P.entries["item:sarkoth-s-mangled-claw"] = {n="Sarkoth's Mangled Claw",s="Längs de södra branterna i Valley of Trials bär Sarkoth's Mangled Claw spåren efter en sårad jägare. Hana'zua krossade skorpionens klo och lämnade ett ärr innan dess giftiga gadd fällde honom.",h="Längs de södra branterna i Valley of Trials bär Sarkoth's Mangled Claw spåren efter en sårad jägare.",kw={"klo","durotar","hana'zua","manglad klo","sarkoth","skorpok","valley of trials"},ang={["faction:Horde"]="Som medlem av Horde är trofén från Valley of Trials ett tidigt prov på mod och kampstyrka i Durotars hårda vildmark.",["race:Troll"]="Som troll ger du en döende Darkspear-frände en viss värdighet när du tar klon till Hana'zua. Han får veta att hans sista hugg sårade besten innan slutet."},sec={{t="En trofé för hämnd",b="Hana'zua, en ung Darkspear-troll, mötte Sarkoth när han jagade i Valley of Trials. Den väldiga skorpionens giftiga gadd trängde in i hans bröst och lämnade honom blödande under ett träd i närheten. Innan hugget träffade krossade Hana'zua bestens klo. Den avhuggna, sönderslagna klon bevisar att Sarkoth har dödats. För den sårade jägaren är ärret på besten ett bevis på att hans desperata hugg satte sina spår, och det sista han har kvar av sin krigarära medan giftet sprider sig genom hans ådror."}},faq={{q="Varför är klon tilltygad?",a="Sarkoths klo krossades i en desperat duell med Hana'zua, en trolljägare. Sarkoth stack Hana'zua i bröstet, men trollet hann slå till besten innan dess klo kunde sluta sig om hans ben.",al={"varför är klon trasig","vem krossade sarkoths klo","lore om den manglade klon"}},{q="Vem vill ha Sarkoth's Mangled Claw?",a="Hana'zua ber om klon. Han är svårt sårad under ett träd i Valley of Trials och fruktar att han kommer att dö där. Han vill att Sarkoth ska dödas för att hans ära ska upprätthållas; att få se dådet utfört stärker honom att hålla ut tills Gornek skickar hjälp.",al={"vem behöver sarkoths klo","vem lämnade in den","hanazuas klo"}},{q="Var kommer klon ifrån?",a="Klon kommer från Sarkoth, en stor och aggressiv skorpion som stryker omkring på den upphöjda platån längs de södra klipporna i Valley of Trials i Durotar.",al={"sarkoths plats","var finns sarkoth","var får man tag på manglad klo"}}},fx={["5a9dc5fc"]={q="Vad är Sarkoth's Mangled Claw?",a="Det är den avhuggna kloarmen från Sarkoth, en ovanligt stor och våldsam skorpid som stryker omkring på den södra platån ovanför Valley of Trials. Kloarmen bär svåra sprickskador som den svårt sårade Darkspear-trollen Hana'zua åsamkade under deras desperata kamp. Den är ett obestridligt bevis på att det monstruösa odjuret äntligen har dödats.",al={"vad är sarkoths mangled claw","sarkoths kloarm betydelse","sönderslagen kloarm"}}},fp="22,191,21.449.0,24.189.0,33.219.0,30.147.0"}
P.entries["item:sarltooth-s-talon"] = {n="Sarltooth's Talon",s="Sarltooth's Talon är en avhuggen klo från alfaryptorn som håller till ovanför Whelgar's Excavation Site i Wetlands. Den är ett påtagligt bevis för dvärgen Ormer Ironbraid på att det våldsamma odjur som ödelade den arkeologiska utgrävningen har dödats.",h="Sarltooth's Talon är en avhuggen klo från alfaryptorn som håller till ovanför Whelgar's Excavation Site i...",kw={"utgrävning","ormer ironbraid","raptor","sarltooth","klo","wetlands","whelgar"},ang={["class:Hunter"]="Att spåra upp en listig flockledare som Sarltooth och ta en klo som trofé är ett klassiskt prov på prickskytte och förmåga att bemästra bestar.",["race:Dwarf"]="När klon återtas får de fallna dvärgarkeologerna äntligen sin hämnd. De miste livet när de tjänade Explorers' League på uppdrag av King Magni Bronzebeard."},sec={{t="En trofé för hämnd",b="När raptorer invaderade Whelgar's Excavation Site och massakrerade dvärgexpeditionen såg Ormer Ironbraid på från höjden ovanför, oförmögen att stoppa slakten. Han pekade ut en enorm, hotfull raptor — Sarltooth — som den troliga flockledaren bakom anfallet. För att hämnas sina fallna fränder krävde Ormer att odjuret skulle dö och bad om en av dess grymma klor som bevis. Att hugga av klon markerar slutet på Sarltooths terrorvälde över de forntida dvärgruinerna."}},faq={{q="Var kommer Sarltooth's Talon ifrån?",a="Klon skärs loss från Sarltooth, en stor alfaryptor som stryker omkring på de västra höjderna med utsikt över Whelgar's Excavation Site i Wetlands.",al={"vem släpper sarltooths talon","sarltooths plats","hur får man klon"}},{q="Vem vill ha Sarltooth's Talon?",a="Ormer Ironbraid, en dvärg som är stationerad vid utsiktspunkten ovanför Whelgar's Excavation Site, ber om klon för att bekräfta att odjuret som massakrerade hans besättning har fällts.",al={"vem tar emot klon","var lämnar man in klon","ormer ironbraids uppdrag"}},{q="Varför behöver Ormer Ironbraid bevis på Sarltooths död?",a="Ormer tror att Sarltooth ledde raptorflocken som drev bort och dödade dvärggrävarna. Han ser klon som en symbol för rättvisa och ett avslut för sina fallna kollegor.",al={"varför döda sarltooth","vad gjorde sarltooth"}},{q="Vad hände med dvärgarna vid utgrävningsplatsen?",a="Dvärgarnas utgrävning skulle hitta forntida artefakter åt Explorers' League, men vilda raptorer överföll arbetarna, massakrerade de flesta och drev de överlevande till den närliggande höjden.",al={"whelgars excavation sites bakgrund","varför finns det raptorer vid utgrävningen"}}},fx={["28fc0e8a"]={q="Vad är Sarltooth's Talon?",a="Det är en avhuggen klo från Sarltooth, den våldsamma raptor som misstänks leda den vilda flock som övertog Whelgar's Excavation Site. Ormer Ironbraid kräver klon som obestridligt bevis på att odjuret har dödats och att de fallna dvärgiska utgrävarna har blivit hämnade.",al={"vad är sarltooths talon","sarltooths talon bakgrund"}}},fp="17,153,21.384.0,39.137.0,28.174.0,57.173.0,52.167.0"}
P.entries["item:sathrah-s-sacrifice"] = {n="Sathrah's Sacrifice",s="Sathrah's Sacrifice består av de silverglänsande spinnvårtorna från Lady Sathrah, en mäktig spindel som lever i Teldrassil. Priestess A'moora ger dem till äventyrare, som sedan lägger gåvan i fontänen vid Temple of the Moon för att rena varelsen från fördärvet och låta hennes ande få ro.",h="Sathrah's Sacrifice består av de silverglänsande spinnvårtorna från Lady Sathrah, en mäktig spindel som lever...",kw={"darnassus","elune","lady sathrah","priestess a'moora","sathrah's sacrifice","silvery spinnerets","spindel","teldrassil","temple of the moon"},ang={["class:Priest"]="Präster som tjänar The Sisterhood of Elune ser ritualen som en högtidlig handling av gudomlig barmhärtighet. De använder heligt vatten för att rena smitta i stället för att bara kasta bort ett fällt djur.",["race:NightElf"]="För nattalver är det en sorgsen plikt att avliva fördärvat djurliv. När Lady Sathrahs ande återförs till Elunes nåd kan livet i Teldrassil till slut återfödas, fritt från vansinne."},sec={{t="Renande i heligt vatten",b="Lady Sathrah var en vördnadsvärd varelse i Teldrassil, men föll offer för det krypande vansinne och fördärv som drabbade det stora trädets grenar. På uppdrag av The Sisterhood of Elune hämtar äventyrare hennes silverglänsande spinnvårtor, inte som enkla troféer utan som en vigd gåva. När kvarlevorna sänks ned i den heliga fontänen vid Temple of the Moon sköljs den onda smitta som förgiftade Sathrahs sinne bort. Riten befriar hennes plågade själ och låter hennes ande visa sig fridfullt i helgedomen, med löftet om återfödelse under Elunes nåd."}},faq={{q="Vad är Sathrah's Sacrifice?",a="Sathrah's Sacrifice är en rituell gåva av Lady Sathrahs silverglänsande spinnvårtor. Hon var en fördärvad jättespindel som dödades i Teldrassil. The Sisterhood of Elune använder gåvan i en reningsrit för att rena varelsens själ.",al={"vad är spinnvårtorna","föremålet sathrah's sacrifice","lady sathrahs offergåva"}},{q="Varför måste spinnvårtorna läggas i fontänen?",a="Den centrala fontänen i Temple of the Moon i Darnassus innehåller heligt vatten som vigts åt Elune. När Sathrahs kvarlevor sänks ned i bassängen sköljs det onda fördärv som drev henne till vansinne bort, och hennes ande befrias från plågan.",al={"varför templets fontän","varför offra sathrah","vad gör fontänen"}},{q="Vad händer när gåvan överlämnas?",a="När kvarlevorna läggs i det heliga vattnet renas fördärvet, och Lady Sathrahs vålnad visar sig. Hon vandrar lugnt runt bassängen som ett tecken på att hennes själ har fått ro.",al={"vad händer vid fontänen","sathrahs ande visar sig","händelse vid fontänen"}},{q="Vem leder ritualen?",a="Priestess A'moora, en tjänare åt The Sisterhood of Elune som tjänstgör i Temple of the Moon, uppmanar äventyrare att låta varelsen få ro och offra hennes kvarlevor till gudinnan.",al={"vem ger sathrah's sacrifice","priestess a'mooras uppdrag","vem renar sathrah"}}},fx={c7289e92={q="Var kommer Sathrah's Sacrifice ifrån?",a="Priestess A'moora tillredde offergåvan direkt av de silvriga spinnvårtorna från Lady Sathrah, en stor spindel som fälldes i Teldrassil efter att ha fallit i vansinne och korrumperats.",al={"sathrahs sacrifice ursprung","varifrån kom sathrahs sacrifice","vem skapade sathrahs sacrifice"}},b18748b3={q="Varför vill Priestess A'moora ha Sathrah's Sacrifice?",a="Priestess A'moora behöver offergåvan så att den kan läggas i Temple of the Moons heliga vatten. Genom denna gåva till Elune kan korrumperingen som förvrängde Lady Sathrah i livet äntligen renas bort. Då får det stora odjuret ro och hennes ande kan återfödas förnyad.",al={"varför efterfrågas sathrahs sacrifice","varför offra sathrahs sacrifice","vad används sathrahs sacrifice till"}}},fp="19,171,31.542.0,28.176.0,50.196.0,44.187.1,25.187.0"}
P.entries["item:satyr-horns"] = {n="Satyr Horns",s="Satyr Horns är dystra troféer från de fördärvade satyrer som hemsöker Ashenvales uråldriga skogar. De är eftertraktade både av sörjande skogsvånare som söker hämnd och av giriga handelsmän från Ratchet, och utgör ett obestridligt bevis på att ännu en tjänare åt den brinnande legionen har fallit.",h="Satyr Horns är dystra troféer från de fördärvade satyrer som hemsöker Ashenvales uråldriga skogar.",kw={"anilia","forest song","illiyana","night run","pixel","satyr horns","satyrnaar","splintertree post","xavian"},ang={["faction:Horde"]="Från Splintertree Post röjer Hordens krigare undan de vidriga satyrer som hotar deras timmerverksamhet, samtidigt som de tjänar på goblinköpare på väg till Ratchet.",["race:NightElf"]="För kaldorei är det en bitter plikt att ta hornen från satyrerna och rena deras förfäders skog från släktingar som frivilligt bytte sitt arv mot demonisk träldom."},sec={{t="Hämndens och handelns troféer",b="De böjda hornen från Ashenvales satyrer är tydliga tecken på demoniskt fördärv som slagit rot i den heliga skogen. För dryaden Illiyana vid The Shrine of Aessina handlar insamlingen av dessa avhuggna horn om sorg och hämnd för hennes förlorade syster Anilia. För utomstående handelsmän som den kringresande goblinen Pixel, som vilar vid Splintertree Post, står hornen däremot för en möjlighet till snabba pengar. Efterfrågan på satyrhorn har ökat kraftigt i den neutrala hamnen Ratchet, där dessa makabra lämningar efter dödade demoner blivit lukrativa handelsvaror för alla som vågar jaga dem som bär hornen."},{t="Rensa ut de fördärvade enklaverna",b="Satyr Horns kan inte köpas från vanliga handlare; de måste skäras loss direkt från bestarna som lurar i skogens mörka hörn. Satyrerna håller stånd på flera platser i Ashenvale, mest ökänt i de fördärvade lundarna i Xavian, de skuggiga hålorna i Satyrnaar och ruinerna i Night Run. När enklaverna rensas befrias landet från kvarvarande demoniskt fördärv, samtidigt som både sörjande väktare och ivriga handelsmän får bevis på att satyrerna har gallrats ut."}},faq={{q="Varför vill Illiyana ha Satyr Horns?",a="Illiyana vill ha Satyr Horns för att hämnas sin fallna syster Anilia, som mördades av Ashenvales satyrer. Hornen från de dödade demonerna visar att deras antal minskar och skänker hennes systers ande ro.",al={"illiyana horn","anilia satyrer","forest song uppdrag"}},{q="Varför samlar Pixel på Satyr Horns?",a="Pixel är en företagsam resenär som stannar vid Splintertree Post på väg till Ratchet. Hon har fått veta att satyrhorn betingar ett högt pris i goblinhamnen och anlitar äventyrare för att sköta den farliga jakten åt henne innan hon reser vidare.",al={"pixel splintertree","varför vill pixel ha horn","ratchet satyrhorn"}},{q="Var hittar man lättast satyrer med sådana horn?",a="Satyrer håller till i flera fördärvade områden i Ashenvale. Större grupper finns i Xavian och Satyrnaar i nordost samt i Night Run i skogens östra mittdel.",al={"satyrplatser ashenvale","var finns satyrer","satyrernas läger"}},{q="Vad är satyrer, och varför har de horn?",a="Satyrer är uråldriga nattalver som förvandlats till bestialiska, demoniska varelser genom de demoniska pakter som slöts under de uråldriga krigens tid. Deras getklövar, svansar och onda horn är fysiska tecken på det demoniska fördärv som den brinnande legionen skänkte dem.",al={"vad är en satyr","varför har satyrer horn"}}},fx={["2131c67f"]={q="Vad är Satyr Horns?",a="Satyr Horns är de böjda, demoniska horn som skärs av från huvuden på dödade satyrer som lurar i Ashenvale. Som demoniska förvridningar av forntida nattalver bär satyrerna dessa hotfulla utväxter som tecken på sin förbannelse. I äventyrarnas händer tjänar de främst som dystra bevis på en satyrs död eller som värdefulla, exotiska kuriositeter som säljs runtom i Kalimdor.",al={"vad är satyr horns","satyr horns föremål","satyrhorn betydelse"}},["8a39621c"]={q="Varför vill någon ha Satyr Horns?",a="Olika fraktioner söker satyrhorn av helt olika skäl. För dryaden Illiyana vid Forest Song är de obestridliga troféer som visar att hon fått hämnd på de korrumperade demoner som mördade hennes syster Anilia. Samtidigt samlar opportunistiska köpmän som Pixel in dem för att sälja dem i den livliga hamnen Ratchet, där det finns stor efterfrågan på exotiska alkemiska ingredienser, kuriositeter och odjursdelar.",al={"vem vill ha satyr horns","varför samla satyr horns","varför efterfrågas satyr horns"}}},fp="11,163,34.327.0,30.359.0,35.170.0,36.223.0,58.155.0,44.212.0"}
P.entries["item:savannah-lion-tusk"] = {n="Savannah Lion Tusk",s="I The Barrens går savannalejontänder från jakttroféer till ingredienser i Chen Stormstouts legendariskt starka öl.",h="I The Barrens går savannalejontänder från jakttroféer till ingredienser i Chen Stormstouts legendariskt...",kw={"the barrens","brewmaster drohn","chen stormstout","dishu","humar","ratchet","savannah lion tusk"},ang={["class:Hunter"]="Som jägare sätts din skicklighet på prov när du spårar de vildsinta flockarna genom The Barrens. Deras farliga betar kan bli dödliga i strid och värdefulla för lokala bryggare."},sec={{t="En ovanlig bryggingrediens",b="De stora kattdjuren som strövar omkring i The Barrens har vassa, tunga betar. Prowlers, huntresses, flockar som styrs av patriarker och bestar som Humar the Pridelord har alla sådana. Resenärer tar ofta med sig tänderna som bevis på en lyckad jakt. Brewmaster Drohn i Ratchet använder betarna tillsammans med plainstrider-njurar och åsködlehorn för att återskapa Chen Stormstouts berömda namnbrygd, ett starkt öl med en legendarisk rivighet som få dödligas strupar tål."}},faq={{q="Varför behöver Brewmaster Drohn Savannah Lion Tusks?",a="Brewmaster Drohn i Ratchet behöver betarna för att återskapa Chen Stormstouts namnbrygd. Hans mentor förde receptet vidare till honom, och betarna är en av tre ingredienser från The Barrens som behövs för att återskapa ölets distinkta smak och rivighet.",al={"varför betar till öl","drohn lejonbetar","brewmaster drohns recept"}},{q="Vilka bestar har Savannah Lion Tusks?",a="Medlemmar av savannalejonens flockar i hela The Barrens har betarna. Dit hör Savannah Highmanes, Patriarchs, Matriarchs, Huntresses, Prowlers och sällsynta bestar som Dishu och Humar the Pridelord.",al={"var faller lejonbetar","vem släpper lejonbetar","savannah lion tusks källa"}},{q="Har lejon verkligen betar?",a="Savannens stora kattdjur har överdimensionerade hörntänder som växer sig framträdande och tjocka i Kalimdors karga vildmarker. Lokala jägare och nybyggare kallar dem betar.",al={"varför kallas lejontänder betar","lejonbetar eller huggtänder","lejonbetars anatomi"}}},fx={["98d362c4"]={q="Vad är en Savannah Lion Tusk?",a="En Savannah Lion Tusk är en vass hörntand från de rovdjurskatter som stryker omkring på The Barrens solstekta slätter. De kallas betar, men är egentligen de väldiga huggtänderna hos savannens lejon, som dominerar de lokala jaktmarkerna. Förutom att vara dystra troféer för den som överlever i vildmarken får dessa tåliga delar ovanliga användningsområden hos lokalbor som vet hur man utvinner deras egenskaper.",al={"vad är savannah lion tusk","savannah lion tusk bakgrund","lejonbete"}},ea601034={q="Var kommer en Savannah Lion Tusk ifrån?",a="Dessa betar kommer direkt från de vilda lejonflockar som jagar på Kalimdors centrala savanner. Alla lejonraser som stryker omkring i The Barrens, från strykare och jägarinnor till mäktiga patriarker och högmanar, har dessa vassa huggtänder. De använder dem för att fälla slättstridare och försvara sitt revir mot andra rovdjur.",al={"varifrån kommer lejonbetar","vem släpper lejonbetar","lejonbetarnas ursprung"}}},fp="18,104,28.414.0,51.240.0,39.188.0,29.151.0"}
P.entries["item:sawtooth-snapper-claw"] = {n="Sawtooth Snapper Claw",s="Sawtooth Snapper Claws kommer från murlocerna längs kusten vid Swamp of Sorrows. Tok'Kar förbereder dem som vapen för att hjälpa till att försvara Stonard.",h="Sawtooth Snapper Claws kommer från murlocerna längs kusten vid Swamp of Sorrows.",kw={"kust","murloc","sawtooth snapper","sawtooth snapper claw","stonard","swamp of sorrows","tok'kar","vapen"},ang={["faction:Horde"]="Tok'Kar hjälper till att försvara Stonard, en orcbosättning, mot hot längs kusten."},sec={{t="Klor till Stonard",b="Längs kusten vid Swamp of Sorrows ber Tok'Kar om Sawtooth Snapper Claws för att stärka Stonards försvar. Sawtooth snappers är murlocer, och deras klor blir utmärkta vapen när de förbereds på rätt sätt. Tok'Kar är stationerad vid kusten för att hålla utkik efter hot och varna Stonard om faran blir för stor."}},faq={{q="Var kommer Sawtooth Snapper Claws från?",a="Sawtooth Snapper Claws kommer från sawtooth snappers längs kusten vid Swamp of Sorrows.",al={"var klorna kommer ifrån","varifrån klor"}},{q="Vem vill ha klorna?",a="Tok'Kar vill ha Sawtooth Snapper Claws för att förbereda vapen till Stonards försvar.",al={"vem vill ha snapperklor","tok'kar klor"}},{q="Varför behöver Tok'Kar klorna?",a="Tok'Kar säger att klorna blir utmärkta vapen när de förbereds på rätt sätt, så att Stonard har fler vapen redo vid ett angrepp.",al={"varför klor","vad klorna är till för"}},{q="Vad gör Tok'Kar vid kusten?",a="Tok'Kar och hans styrka bevakar kusten för att skydda Stonard eller varna bosättningen om ett hot blir för stort.",al={"tok'kars uppgift","varför tok'kar är där"}}},fp="21,135,17.306.0,42.84.0,20.78.0,32.113.0,35.96.0"}
P.entries["item:scaber-stalk"] = {n="Scaber Stalk",s="Scaber Stalk är sällsynta svampar som frodas i den fuktiga, avskilda grottan bakom Cliffspring Falls i Darkshore. Örtkunniga och alkemister värdesätter dem för deras ovanliga egenskaper, och Barithras Moonshade behöver dem till sina brygder.",h="Scaber Stalk är sällsynta svampar som frodas i den fuktiga, avskilda grottan bakom Cliffspring Falls i...",kw={"auberdine","barithras moonshade","grottsvampar","cliffspring falls","darkshore","death cap","scaber stalk"},ang={["profession:Herbalism"]="Dessa svampar under jord är inga vanliga handelsörter, men de ger värdefulla insikter i hur särskilda grottklimat och inträngande skuggor påverkar svamplivet.",["race:NightElf"]="Nattalverna lyssnar till varningarna från Grove of the Ancients och närmar sig insamlingen av dessa grottsvampar med stor försiktighet, eftersom en korrumperande närvaro härjar nära Cliffspring Falls."},sec={{t="Ett sällsynt svampfynd",b="Scaber Stalk är svårfunna svampar som växer djupt inne i grottan bakom Cliffspring Falls, längs bergen i nordöstra Darkshore. Till skillnad från vanliga skogsväxter trivs de bleka svamparna bara i det avskilda fuktdunklet i grottsystemet under jord. Den avlägsna och farliga livsmiljön gör dem mycket svåra att samla in. Därför anlitar alkemister som Barithras Moonshade i Auberdine djärva spejare som vågar sig in i mörkret."},{t="En skugga vid fallen",b="Att samla Scaber Stalk är långt farligare än vanlig örtplockning. De uråldriga trädandarna i Grove of the Ancients varnade de lokala nattalverna, eftersom de känt hur en mörk och växande ondska slagit rot i grottan vid Cliffspring Falls. Alkemister värdesätter svamparna tillsammans med sällsynta Death Cap för experimentella brygder, men den som samlar dem möter förr eller senare den illvilja som slagit rot under bergen."}},faq={{q="Var växer Scaber Stalk?",a="Scaber Stalk växer endast i den fuktiga grottan bakom Cliffspring Falls, längs bergsryggen i nordöstra Darkshore.",al={"scaber stalk plats","var finns scaber stalk","scaber stalk grotta"}},{q="Vem vill ha Scaber Stalk?",a="Barithras Moonshade, en nattalvsk lärd som bor i Auberdine, söker efter Scaber Stalk och Death Cap för att brygga en särskild dryck.",al={"vem använder scaber stalk","barithras moonshade svampar","vem behöver scaber stalk"}},{q="Varför samlade inte Barithras Moonshade svamparna själv?",a="Barithras varnades av Grove of the Ancients för att inte gå in i grottan. Andarna hade känt att en farlig ny ondska tagit sin tillflykt bakom vattenfallet.",al={"varför hämtar han dem inte själv","barithras varning","varning vid cliffspring-grottan"}},{q="Vad mer växer tillsammans med Scaber Stalk?",a="Grottan hyser också den dödliga svampen Death Cap, ett annat sällsynt fynd som Barithras behöver för sin alkemi.",al={"andra svampar i grottan","death cap och scaber stalk","svampar vid cliffspring"}}},fx={f5b84e96={q="Vad är en Scaber Stalk?",a="En Scaber Stalk är en sällsynt grottsvamp som hör hemma i den skuggiga grotta bakom Cliffspring Falls i Darkshore. Underjordiska svampar är vanliga i norra Kalimdor, men den här sorten trivs i fuktiga, mörka grottor där onda krafter huserar.",al={"vad är scaber stalk","information om scaber stalk","scaber stalk svamp"}},["053fa90e"]={q="Varför vill någon ha Scaber Stalks?",a="Barithras Moonshade i Auberdine söker Scaber Stalks som en viktig ingrediens till särskilda brygder. Eftersom dessa kraftfulla svampar bara växer i den avskilda grottan nära Cliffspring Falls måste örtkunniga och alkemister förlita sig på äventyrliga resenärer som skördar dem.",al={"varför samla scaber stalk","scaber stalk användning","vad används scaber stalks till"}}},fp="12,91,22.313.0,21.337.1,28.101.0,24.98.0,58.141.0,40.122.0"}
P.entries["item:scale-of-old-murk-eye"] = {n="Scale of Old Murk-Eye",s="På Westfalls kust terroriserar Old Murk-Eye stranden. Captain Grayson, spöket vid Westfall Lighthouse, behöver en fjäll från murlocken som bevis på att den är död.",h="På Westfalls kust terroriserar Old Murk-Eye stranden.",kw={"captain grayson","kustplåga","murlock","old murk-eye","scale of old murk-eye","westfall","westfall lighthouse"},ang={["faction:Alliance"]="Som allianssjöman på väg över Stora havet mot Stormwind kan du hjälpa till att stoppa Old Murk-Eyes attacker, hålla fyren i Westfall tänd och hindra fartyg från att gå på klipporna."},sec={{t="Trofé från en kustplåga",b="Old Murk-Eye förvandlade Westfalls kust till en dödsfälla. Captain Grayson, spöket som är bundet till Westfall Lighthouse, säger att den listiga murlocken samlade murlocker med svagare vilja för att plundra stranden. Murk-Eye drev bort fyrvaktarens familj, så fyren var släckt när Graysons skepp gick på klipporna. När familjen återvände för att tända fyren igen anföll Murk-Eye på nytt och slaktade dem. Grayson söker ett fjäll från varelsen som bevis på att kusten är fri från dess farligaste rovdjur."}},faq={{q="Vad används Scale of Old Murk-Eye till?",a="Captain Grayson behöver fjället som bevis på att Old Murk-Eye är död. Spöket hemsöker den klippiga ön Westfall Lighthouse och söker hämnd, eftersom Murk-Eye lämnade fyren släckt när Graysons skepp förliste och sedan slaktade fyrvaktarens familj.",al={"vem vill ha fjället","lämna in murk-eyes fjäll","vad används scale of old murk-eye till"}},{q="Vem är Old Murk-Eye?",a="Old Murk-Eye är en grym och listig murlockledare som strövar längs Westfalls sandstränder. Han kan organisera och tvinga sina fränder att utföra dödliga, samordnade räder mot utposter längs kusten.",al={"vem är murk-eye","murk-eyes bakgrund","old murk-eye"}},{q="Varför angrep Old Murk-Eye fyren?",a="Old Murk-Eye anföll först fyren för att driva bort fyrvaktaren och hans familj och lämna kusten i mörker. När de återvände för att tända fyren igen samlade han sina fränder till ännu ett anfall och mördade hela familjen, så att skeppen inte kunde se de farliga grunden nära kusten.",al={"varför anfalla fyren","fyranfall","murk-eye och fyren"}}},fx={["6e72b95e"]={q="Vad är Scale of Old Murk-Eye?",a="Det är en hård, särpräglad fjäll från skinnet på Old Murk-Eye, den ökände murlocledaren som terroriserar Westfalls kust. Att bära den är ett obestridligt bevis på att den dödliga kustplundraren äntligen har dödats.",al={"vad är scale of old murk-eye","scale of old murk-eye föremål","murk-eyes fjäll"}},["383f15e9"]={q="Var kommer Scale of Old Murk-Eye ifrån?",a="Fjället kommer från Old Murk-Eyes naturliga skinn. Han är en ovanligt slug och våldsam murloc som stryker omkring längs Westfalls kust. Den smiddes eller tillverkades inte av dödliga händer, utan togs från hans kropp efter att han besegrats i strid.",al={"scale of old murk-eye ursprung","var får man scale of old murk-eye","vem skapade scale of old murk-eye"}},e7059369={q="Varför vill Captain Grayson ha Scale of Old Murk-Eye?",a="Captain Grayson, spöket efter en sjökapten som dröjer sig kvar vid Westfall Lighthouse, söker hämnd och avslut. Old Murk-Eye skrämde bort fyrvaktarens familj, så fyren var släckt den natt Graysons skepp gick på klipporna. När familjen återvände plundrade han igen och slaktade dem. Grayson kräver fjället som obestridligt bevis på att odjuret är dött och att kusten är tryggare.",al={"varför vill grayson ha fjället","varför efterfrågas scale of old murk-eye","vem vill ha scale of old murk-eye"}}},fp="21,165,27.481.0,43.240.0,20.178.0,43.277.0"}
P.entries["item:scarlet-armband"] = {n="Scarlet Armband",s="Scarlet Armbands är kännetecken som bärs av medlemmar i Scarlet Crusade och visar deras fanatiska hängivenhet åt att utrota alla odöda. I Deathknell kräver Executor Arren att du lämnar in dem som bevis på att spirande Forsaken har slagit tillbaka mot fanatikerna som tränger in på deras område.",h="Scarlet Armbands är kännetecken som bärs av medlemmar i Scarlet Crusade och visar deras fanatiska hängivenhet...",kw={"deathknell","executor arren","scarlet armband","scarlet convert","scarlet crusade","scarlet initiate","tirisfal glades"},ang={["race:Undead"]="För nyuppståndna Forsaken är insamlingen av armbanden en dyster introduktion till de levandes hat. Den visar att överlevnad kräver ett skoningslöst försvar mot Crusade."},sec={{t="Ett fanatismens märke",b="Scarlet Armband bärs på ärmen av både Scarlet Initiates och nyomvända, och är det tydliga kännetecknet för Scarlet Crusade. För de nyuppståndna Forsaken som kommer ut ur Deathknell är de här remsorna av rött tyg ett dödligt hot precis utanför dörren. Crusade gör ingen skillnad mellan Scourges tanklösa undersåtar och Dark Ladys viljestarka undersåtar. I deras ögon måste varje vandrande lik brännas på bål. Executor Arren gör insamlingen av armbanden till en dyster övergångsrit. Den bekräftar att fiendens spejare sydost om bosättningen har dödats och bevisar att nya Forsaken kan försvara sin spirande nation."}},faq={{q="Varför vill Executor Arren ha Scarlet Armbands?",a="Executor Arren kräver armbanden som bevis på att Scarlet Crusades läger, som tränger sig på sydost om Deathknell, rensas ut. Crusade utgör ett omedelbart existentiellt hot mot nyvaknade Forsaken, och när du samlar in dessa tecken säkerställer du att deras främsta spejare och rekryter har eliminerats.",al={"varför samla armband","arrens armbandsuppdrag","scarlet armbands syfte"}},{q="Vem bär de här armbanden?",a="Armbanden bärs av Scarlet Crusades medlemmar av lägre rang som är stationerade nära Deathknell, särskilt Scarlet Initiates, Scarlet Converts och budbäraren Meven Korgal.",al={"vem släpper scarlet armbands","var hittar man armband"}},{q="Varför hatar Scarlet Crusade Forsaken?",a="Drivna av extrem fanatism vägrar Scarlet Crusade att se någon skillnad mellan Lich Kings tanklösa Scourge och de viljestarka Forsaken. De ser alla odöda som styggelser som måste utrotas för gott.",al={"varför anfaller scarlet odöda","crusade mot forsaken","scarlet fanatiker"}},{q="Var ligger lägret där armbanden kan hittas?",a="Lägret ligger strax sydost om Deathknell i Tirisfal Glades, bland kullarna bortom bosättningens utkant.",al={"scarlet-lägrets plats","scarlet-lägret vid deathknell","var finns scarlet converts"}}},fx={["365b2391"]={q="Vad är en Scarlet Armband?",a="En Scarlet Armband är en bit karmosinrött tyg som bärs av noviser och omvända inom Scarlet Crusade. Den fungerar som kännetecken för den fanatiska mänskliga orden och visar att bäraren är en korsfarare som svurit att utrota alla odöda från Lordaeron, oavsett om de tjänar Scourge eller har en fri vilja som Forsaken.",al={"vad är scarlet armband","scarlet armband betydelse","scarlet armband bakgrund"}}},fp="15,158,21.513.0,46.244.0,25.169.0,47.204.0,52.110.0"}
P.entries["item:scarlet-crusade-documents"] = {n="Scarlet Crusade Documents",s="Dessa beslagtagna papper bars av en budbärare från Scarlet Crusade vid korstågets läger nära Deathknell. De innehåller order till korstågets fältbefälhavare runt om i Tirisfal Glades och ger Forsaken de exakta militära underrättelser som behövs för att rikta in sig på korstågets regionala ledning.",h="Dessa beslagtagna papper bars av en budbärare från Scarlet Crusade vid korstågets läger nära Deathknell.",kw={"brill","deathknell","executor arren","executor zygand","meven korgal","scarlet crusade documents","den röde budbäraren","viktiga underrättelser"},ang={["race:Undead"]="Att bära dessa beslagtagna papper markerar en nyväckt Forsakens övergång från Deathknells kyrkogårdsprov till den större krigsinsatsen som leds från Brill."},sec={{t="Beslagtagna order",b="Kuriren Meven Korgal bar dessa dokument vid korstågets läger sydost om Deathknell. Direktiven, utfärdade på Highlords order, riktar sig till kaptenerna i korstågets regionala kommando i Tirisfal: Captain Perrine ska förstärka det sydvästra tornet ytterligare och samla information om de odöda i Brill, Captain Vachon ska slå ner de odödas rörelser nära det norra tornet, och Captain Melrose ska bevaka gränserna mot Plaguelands. Dokumenten avslöjar namn, poster och order för Scarlet Crusades fältofficerare stationerade runt om i Tirisfal Glades och förvandlar en annars rutinmässig kurirfärd till ett katastrofalt underrättelseläckage för fanatikerna."},{t="Leverans till Brill",b="Executor Arren insåg snabbt att de lokala styrkorna i Deathknell inte kunde utnyttja hela bredden av underrättelserna. I stället blir den beslagtagna akten ett nyväckt Forsakens pass ut ur Deathknell. Dokumenten förs nordost förbi Cold Hearth Manor till Brill och överlämnas direkt till Executor Zygand utanför Brill Town Hall. Med dessa order i hand planerar Forsakens militära ledning snabba halshuggningsanfall mot Scarlet-befälhavare som är förskansade runt om i Glades."}},faq={{q="Vem bar de här dokumenten?",a="De bars av Meven Korgal, en kurir från Scarlet Crusade som påträffades vid korstågets läger sydost om Deathknell.",al={"vem tappade dessa","budbärare från scarlet crusade","meven korgal"}},{q="Vilken information finns i dokumenten?",a="Bunten innehåller direktiv, utfärdade på Highlords order, till kaptenerna i korstågets regionala kommando i Tirisfal: Captain Perrine ska förstärka det sydvästra tornet och spana på de odöda i Brill, Captain Vachon ska hantera de odödas rörelser nära det norra tornet, och Captain Melrose ska bevaka gränserna mot Plaguelands.",al={"vad står det i papperen","dokumentens innehåll"}},{q="Vem behöver se de här dokumenten?",a="Efter att ha hämtats åt Executor Arren i Deathknell anförtros de åt dig för leverans till Executor Zygand, som leder de regionala militära insatserna utanför Brill Town Hall.",al={"vart ska jag ta dem","vem ska jag ge dokumenten till"}},{q="Varför är de här dokumenten viktiga för Forsaken?",a="De beslagtagna orderna pekar ut var korstågets officerare är utplacerade runt om i Tirisfal Glades och ger Forsaken övertaget för att eliminera fiendens ledning och krossa fanatikernas regionala stridsmoral.",al={"varför vill forsaken ha dem","dokument från scarlet crusade viktiga"}}},fx={b6ac443b={q="Vad är Scarlet Crusade Documents?",a="Det är en bunt hemliga militära dokument, stridsrapporter och order som bars av en kurir från Scarlet Crusade. Större delen av bunten består av vanliga spaningsrapporter och propaganda om skärmytslingar med Forsaken, men den innehåller också detaljerade operativa instruktioner avsedda för korstågets officerare runtom i Tirisfal Glades.",al={"vad är dokumenten","information om scarlet crusade documents","scarlet documents föremål"}},["5f5d9cee"]={q="Varifrån kommer Scarlet Crusade Documents?",a="Det är direktiv som utfärdats på korstågets högherres order till kaptenerna vid dess regionala befäl i Tirisfal. De anförtroddes åt en kurir vid namn Meven Korgal, som Forsaken hittade vid korstågets läger sydost om Deathknell.",al={"vem skrev scarlet crusade documents","scarlet documents ursprung","varifrån kom dokumenten"}}},fp="25,243,18.495.0,17.427.0,33.115.0,41.295.0,33.180.0,50.172.0"}
P.entries["item:scarlet-insignia-ring"] = {n="Scarlet Insignia Ring",s="En Scarlet Insignia Ring är en signetring som bärs av medlemmar i Scarlet Crusade, förlagda över hela Tirisfal Glades. För Brills Forsaken-försvarare är ringarna ett makabert bevis på att ännu en fanatiker har utplånats från Lordaerons jord.",h="En Scarlet Insignia Ring är en signetring som bärs av medlemmar i Scarlet Crusade, förlagda över hela...",kw={"brill","deathguard burgess","executor zygand","dödsbevis","scarlet crusade","scarlet insignia ring","tirisfal glades","varimathras"},ang={["faction:Horde"]="Insamlingen av ringarna hjälper den spirande Horden att säkra sitt fotfäste i Eastern Kingdoms genom att försvaga de fanatiska korsfararna som omger Undercity.",["race:Undead"]="För Forsaken är det en direkt förklaring att Tirisfal tillhör de döda att slita ringarna från döda korsfarare, och därmed fullföljs orderna från den mörka damen och Varimathras."},sec={{t="Zealotiska tecken",b="Varje stridande medlem av Scarlet Crusade i Tirisfal Glades – från nya neofyter och fanatiska munkbröder till erfarna kaptener som Melrache och Perrine – bär en insigniering. Ringarna är märkta med korstågets brinnande symbol och visar vem som är broder och syster i en organisation uppslukad av paranoia. För utomstående och fiender fyller smyckena däremot helt andra syften: de är omisskännliga kännetecken för Lordaerons mest fanatiska mänskliga kvarleva."},{t="Dreadlordens byte",b="På direkt order av Varimathras, Lady Sylvanas dreadlordlöjtnant, samlar Deathguard Burgess i Brill aktivt in ringarna. Forsaken ser Scarlet Crusade som en outhärdlig pest som krälar över deras nytagna hemland. För Forsaken-rekryter räknas det som ett obestridligt bevis på död och en direkt bekräftelse på lojaliteten mot Undercitys tron att föra tillbaka högar av ringar till Brill."}},faq={{q="Vem bär de här insignieringarna?",a="Nästan alla medlemmar av Scarlet Crusade som är stationerade i Tirisfal Glades bär en. Det gäller både vanliga soldater som neofyter, missionärer, zeloter och förtrupper, och fältbefäl som Captain Perrine, Captain Melrache och Captain Vachon.",al={"vem släpper ringar","vilka korsfarare har ringar","ringbärare"}},{q="Varför vill Deathguard Burgess ha Scarlet Insignia Rings?",a="Deathguard Burgess samlar in ringarna som fysiska bevis på att Scarlet Crusaders dödas. På order från Varimathras och den mörka damen använder Forsaken-garnisonen i Brill ringarna för att mäta en rekryts lojalitet och förmåga att rensa ut människor från Lordaeron.",al={"varför samla ringar","orsak till dödsbevis","burgess ringar"}},{q="Vad står symbolen på ringen för?",a="Ringen bär Scarlet Crusades märke, som symboliserar deras heliga krig för att utrota all odödhet från Lordaeron. Korstågsriddarna bär den med brinnande stolthet och ser den som ett rättfärdighetens tecken, samtidigt som deras besatthet driver dem att slakta alla som inte tillhör deras orden.",al={"scarlets symbol","vad är insignian","ringens emblem"}},{q="Vilken roll har Varimathras i insamlingen av ringarna?",a="Varimathras är Sylvanas Windrunners främste löjtnant i Undercity. Han övervakar de strategiska militära insatserna för att utplåna fientliga levande människor i Tirisfal Glades, vilket gör utrotningen av Scarlet Crusade till en högsta prioritet för Forsaken-befäl som Executor Zygand och Deathguard Burgess.",al={"varimathras order","varför vill varimathras ha ringar","dreadlordens inblandning"}}},fx={d4097e42={q="Vad är en Scarlet Insignia Ring?",a="En Scarlet Insignia Ring är en kännetecknande ring som bärs av medlemmar i Scarlet Crusade runtom i Tirisfal Glades. Den bär den militanta ordens emblem och visar att bäraren stöder dess fanatiska korståg för att utrota de odöda. För Forsaken som försvarar sina nya gränser är ringarna obestridliga bevis på att en fiendesoldat eller officer har dödats.",al={"vad är scarlet insignia ring","scarlet insignia ring bakgrund","vad är det här för ringar"}}},fp="21,155,18.319.0,23.321.0,31.226.0,56.262.0,45.244.0,58.256.0"}
P.entries["item:scavenged-goods"] = {n="Scavenged Goods",s="Scavenged Goods är diverse kasserad utrustning och förnödenheter som packats i utrustningslådor runt Deathknell. Nyligen uppväckta Forsaken hämtar dem så att den ständiga strömmen av nya rekryter kan få vapen och kläder.",h="Scavenged Goods är diverse kasserad utrustning och förnödenheter som packats i utrustningslådor runt...",kw={"deathguard saltain","deathknell","utrustningslådor","forsaken-förnödenheter","scavenged goods","leta skrot i deathknell"},ang={["race:Undead"]="För Forsaken är det nödvändigt att leta rätt på kasserad utrustning för att överleva. Det befäster den hårda sanningen att de levande inte kommer att hjälpa dem eller visa dem nåd."},sec={{t="Att klara sig på egen hand",b="När nya Forsaken kravlar sig upp ur jorden på Deathknells kyrkogård vaknar de med föga mer än ruttnande svepningar. Närliggande bosättningar och kungariken hjälper inte de odöda, så de är helt beroende av vad de kan rädda. Deathguard Saltain samordnar insamlingen av kasserade vapen, verktyg och kläder som lagrats i förrådslådor runt byn och delar ut dem direkt till nästa grupp uppväckta rekryter."}},faq={{q="Vad används Scavenged Goods till?",a="Deathguard Saltain samlar in dem för att utrusta nya Forsaken-rekryter som reser sig från kyrkogården. Utan resterna som räddas från lådor i närheten skulle nyuppväckta odöda tvingas stappla ut i Tirisfal Glades helt utan vapen eller kläder.",al={"syftet med scavenged goods","varför samla in scavenged goods","vad gör saltain med scavenged goods"}},{q="Var finns de här varorna?",a="De hämtas från utrustningslådor som står utanför stugor och runt ruinerade byggnader i Deathknell.",al={"var hittar man scavenged goods","scavenged goods plats","var finns utrustningslådorna"}},{q="Vem ber om Scavenged Goods?",a="Deathguard Saltain, en officer stationerad i Deathknell, skickar nyvakna Forsaken för att samla in de här förnödenheterna. Det lär dem att klara sig själva och förbereder dem på kommande grupper.",al={"vem vill ha scavenged goods","deathguard saltain uppdrag"}}},fx={f565021a={q="Vad är Scavenged Goods?",a="Det är diverse användbar utrustning, kläder och redskap som tagits till vara från gamla lådor utspridda runt Deathknell. De är inte felfria vapen, utan överblivna saker från stadens forna liv som fortfarande kan komma nyvaknade Forsaken till nytta.",al={"vad är scavenged goods"}},["0b2267aa"]={q="Varifrån kommer Scavenged Goods?",a="De kommer från utrustningslådor som övergivits bland Deathknells ruiner. Förr tillhörde de Lordaerons levande invånare, innan riket föll för pesten. Förråden blev kvarlämnade i ruinerna tills Forsaken började återta staden och använda den som uppmarschområde.",al={"scavenged goods ursprung","vem skapade scavenged goods","varifrån kom scavenged goods"}},["36f8df02"]={q="Varför vill Deathguard Saltain ha Scavenged Goods?",a="Forsaken väcker ständigt nyuppståndna döda från kyrkogården, och de nya rekryterna kommer ut i världen med nästan ingenting. Deathguard Saltain samlar in de tillvaratagna sakerna så att de nyvakna odöda får grundläggande kläder och utrustning, i stället för att gå i tjänst obeväpnade och oskyddade.",al={"varför vill saltain ha scavenged goods","varför samla scavenged goods","varför behövs scavenged goods"}}},fp="15,161,22.332.0,34.183.0,28.96.0,33.170.0"}
P.entries["item:scavenger-paw"] = {n="Scavenger Paw",s="Scavenger Paws är avhuggna lemmar från de unga och raggiga vargar som strövar omkring i kullarna vid Deathknell. Nyligen uppvaknade Forsaken samlar in dem åt lokala vårdare, som syr ihop dem till enkel skyddsutrustning.",h="Scavenger Paws är avhuggna lemmar från de unga och raggiga vargar som strövar omkring i kullarna vid...",kw={"deathknell","novice elreth","ragged scavenger","scavenger paw","the damned","young scavenger"},ang={["profession:Tailoring"]="Novice Elreths grovhuggna hopfogning av vargtassar och fladdermusvingar visar hur improviserat sömnadsarbete håller de spirande Forsaken-bosättningarna vid liv.",["race:Undead"]="När de vaknar med förruttnande kött och knappt någon utrustning är insamling av delar från lokala rovdjur ofta det första steget mot att få ihop tillräckligt med rustning för att uthärda farorna i Tirisfal."},sec={{t="Hoplappad rustning i Deathknell",b="Det råder brist på resurser för de nyss återvända i Deathknell. Med Scourge och Scarlet Crusade som pressar på mot Tirisfal tas varje bit skinn och ben till vara. Novice Elreth, assistent åt Shadow Priest Sarvis, samlar in tassar från de lokala asätarvargarna och fladdermusvingar för att tillverka användbara kläder och rustningar åt desorienterade Forsaken som just stigit upp ur sina gravar."}},faq={{q="Vad används Scavenger Paws till?",a="Novice Elreth samlar in dem i Deathknell och syr enkla rustningar och kläder av råa djurdelar åt nyuppvaknade Forsaken-rekryter.",al={"scavenger paw syfte","användning av tassar","varför samla tassar"}},{q="Var hittar man dem?",a="De tas från Young Scavengers och Ragged Scavengers, de vilda vargar som strövar omkring i skogarna och på fälten närmast Deathknell.",al={"var tassar faller","var få tag på tassar","vilka vargar släpper tassar"}},{q="Vem ber om tassarna?",a="Novice Elreth, som hjälper Shadow Priest Sarvis med att ta hand om skadade rekryter, sy utrustning och utrusta dem som skickas ut i fält.",al={"vem vill ha scavenger paws","uppdragsgivare för tassar","novice elreth tassar"}}},fx={["41bb56d4"]={q="Vad är Scavenger Paw?",a="Scavenger Paw är den avskurna tassen från en asätarvarg som strövar omkring i Tirisfal Glades hemsökta skogar nära Deathknell. De här hållbara djurdelarna verkar vara dystra troféer, men tjänar som råmaterial åt de nyvaknade Forsaken, som måste ta till vara på varje bit av den inhemska faunan för att tillverka det nödvändigaste och överleva.",al={"scavenger paw betydelse","vad är scavenger paws","vad är scavenger paw"}},["366465d3"]={q="Varifrån kommer Scavenger Paw?",a="Tassarna tas från de unga, raggiga asätarvargarna som stryker omkring i utkanten av Deathknell. De här vilddjuren smyger genom de vissna gläntorna strax utanför byns murar och letar efter kadaver i det fördärvade landskapet. Därför blir de lätt byte för nya Forsaken-rekryter som vill bevisa sin styrka.",al={"scavenger paw ursprung","var får man tag på scavenger paw","asätarvargtassar"}},f83538b8={q="Varför vill någon ha Scavenger Paws?",a="Novice Elreth i Deathknell samlar in dem för att sy rustningar och slitstarka kläder åt nyvaknade Forsaken-soldater. Det råder desperat brist på resurser för de nyfödda fria odöda, och Elreth fogar samman skinn, vingar och tassar till utrustning som kan skydda dig mot de viljelösa odöda och Scarlet Crusaders som hotar tillflyktsorten.",al={"varför samla scavenger paws","vem behöver scavenger paws","scavenger paws användning och bakgrund"}}},fp="13,178,27.408.0,33.132.0,23.117.0,24.158.0"}
P.entries["item:sceptre-of-light"] = {n="Sceptre of Light",s="Sceptre of Light är en relik som sägs kunna sänka städer under havet. En siare från Burning Blade har den i Thunder Axe Fortress i Desolace.",h="Sceptre of Light är en relik som sägs kunna sänka städer under havet.",kw={"azore aldamort","burning blade","desolace","ethel rethor","naga","sceptre of light","siareg","thunder axe fortress"},sec={{t="En siares pris",b="Från ett vakttorn i Thunder Axe Fortress studerar en siare från Burning Blade Sceptre of Light. Det sägs att Burning Blade tog den från naga. Legender säger att dess kraft kan sänka hela städer under havet, så Azore Aldamort i Ethel Rethor vill få den tillbaka."}},faq={{q="Vad gör Sceptre of Light?",a="Enligt legenden kan Sceptre of Light sänka hela städer under havet.",al={"sceptre of light kraft","vad kan den göra","sceptre of light"}},{q="Vem har Sceptre of Light?",a="En siare från Burning Blade studerar Sceptre of Light från ett vakttorn i Thunder Axe Fortress.",al={"vem har den","vem har sceptre of light","burning blade sceptre of light"}},{q="Var finns Sceptre of Light?",a="Sceptre of Light finns i Thunder Axe Fortress i Desolace.",al={"var finns sceptre of light","sceptre of light plats","thunder axe sceptre of light"}},{q="Vem vill ha tillbaka spiran?",a="Azore Aldamort i tornet i Ethel Rethor vill ha tillbaka Sceptre of Light.",al={"vem vill ha den","azore sceptre of light","ethel rethor"}},{q="Var fick Burning Blade tag på den?",a="Det sägs att Burning Blade fick Sceptre of Light från naga.",al={"naga sceptre of light","varifrån","sceptre of light ursprung"}}},fp="16,135,16.270.0,34.72.0,29.92.0,30.65.0,31.80.0,35.81.0"}
P.entries["item:scorched-spider-fang"] = {n="Scorched Spider Fang",s="I Wetlands hämtas Scorched Spider Fangs från Cave Stalkers och Leech Stalkers. Furen Longbeard i Stormwind behöver femtio för att stärka ringbrynjor åt Alliansens krigare.",h="I Wetlands hämtas Scorched Spider Fangs från Cave Stalkers och Leech Stalkers.",kw={"cave stalker","eldhärdad ringbrynja","furen longbeard","leech stalker","scorched spider fang","stormwind","wetlands"},ang={["class:Warrior"]="Som krigare ställs du inför Furen Longbeards prövning: att samla femtio huggtänder. Arbetet sätter din uthållighet på prov och ger dig råmaterialet till din ringbrynja.",["profession:Blacksmithing"]="Som smed kan du se hur Furen använder bränd kitin och huggtänder i ringbrynjelänkar och följer sällsynta dvärgsmedstraditioner som går utöver vanlig smältning."},sec={{t="En dvärgssmeds formel",b="I Stormwind använder smeden Furen Longbeard ovanliga metoder för att stärka ringbrynjor. Han ber om femtio brända huggtänder från Wetlands jättespindlar. Deras täta, giftiga och hårdnade substans förstärker ringbrynjans länkar när han härdar dem."},{t="Wetlands förföljare",b="Cave Stalkers och Leech Stalkers bär på huggtänderna Furen behöver. De lever i Wetlands sjunkna dalar och hålor, där fukt och förruttnelse omger deras hårdnade, brända käkar. Att samla femtio innebär att ge sig in i djupa håligheter och möta spindlarna i svärmar."}},faq={{q="Vad används Scorched Spider Fangs till?",a="Furen Longbeard i Stormwind behöver femtio Scorched Spider Fangs för att smida slitstarka bröstharnesk åt Alliansens krigare. Arbetet kräver också komponenter från Stonetalon och Razorfen Kraul.",al={"vad gör jag med scorched spider fangs","scorched spider fang användning","vem behöver scorched spider fangs"}},{q="Var hittar jag Scorched Spider Fangs?",a="Cave Stalkers och Leech Stalkers i Wetlands bär Scorched Spider Fangs. Leta i deras fuktiga hålor, på sluttningar och i utgrävningsgrottor.",al={"var scorched spider fang faller","vilka spindlar släpper scorched spider fang","var farmar jag scorched spider fangs"}},{q="Varför behöver en smed så många spindelhuggtänder för att tillverka rustning?",a="Furen Longbeard använder ovanliga dvärgmetoder för att stärka ringbrynjor. Han behandlar länkarna med hårdnade huggtänder, flogiston och besthorn.",al={"varför 50 huggtänder","varför behöver furen spindelhuggtänder"}},{q="Kan vilken äventyrare som helst samla in och lämna in huggtänderna?",a="Alla som färdas genom Wetlands kan döda spindlarna och ta deras käkar. Furen beställer rustningen endast åt blivande krigare som vill förtjäna eldhärdad ringbrynja.",al={"är scorched spider fang bara för krigare","vem kan lämna in scorched spider fangs"}}},fx={a7a99cbb={q="Vad är Scorched Spider Fang?",a="Scorched Spider Fang är en förhårdnad, värmebehandlad giftig tand från rovdjursspindlar som Cave Stalkers och Leech Stalkers i Wetlands. Deras svärtade, sköra utseende döljer en enastående täthet, vilket gör dem eftertraktade bland skickliga rustningsmakare som söker sällsynta komponenter för avancerade smidestekniker.",al={"vad är scorched spider fang","scorched spider fangs","bränd spindelhuggtand"}},c6d8f632={q="Varifrån kommer Scorched Spider Fangs?",a="De här huggtänderna har inte tillverkats av dödliga händer, utan tas direkt från Wetlands jättespindlar, särskilt Leech Stalkers och Cave Stalkers. Ständig kontakt med underjordiska element och giftets naturliga alkemi ger huggtänderna deras svärtade, eldhärdade motståndskraft.",al={"varifrån kommer scorched spider fangs","scorched spider fang ursprung","scorched spider fang källa"}}},fp="20,165,25.253.0,24.267.0,40.185.0,39.138.0,62.133.0,51.175.0"}
P.entries["item:scorpashi-venom"] = {n="Scorpashi Venom",s="Scorpashi venom är ett reagens från skorpionerna som strövar omkring i Desolace. Kreldig Ungor behöver det till en lista över material som Reclaimers Inc. har begärt.",h="Scorpashi venom är ett reagens från skorpionerna som strövar omkring i Desolace.",kw={"skinn från åldrade kodos","desolace","kreldig ungor","leftwitch","reclaimers inc","scorpashi","scorpashi venom"},ang={["class:Mage"]="Leftwitchs lista efterfrågar Scorpashi venom, ett av de märkligare reagens en magiker kan söka efter."},sec={{t="En magikers lista",b="Kreldig Ungor samlar material i Desolace åt Reclaimers Inc. efter en lista som Leftwitch har sammanställt. Scorpashi venom är ett av föremålen magikern behöver, tillsammans med skinn från åldrade kodos. Kreldig vill gärna bli klar med listan och återvända till Ironforge."}},faq={{q="Vad används Scorpashi venom till?",a="Leftwitch behöver Scorpashi venom till en lista över material som Kreldig Ungor samlar in åt Reclaimers Inc.",al={"användning av scorpashi venom","varför samla gift","gift som reagens"}},{q="Vem behöver giftet?",a="Kreldig Ungor samlar in giftet i Desolace åt Reclaimers Inc. efter Leftwitchs lista.",al={"vem vill ha scorpashi venom","kreldigs gift","vem behöver det"}},{q="Var kommer Scorpashi venom från?",a="Scorpashi venom kommer från skorpionerna som finns överallt i Desolace.",al={"var hittar man gift","scorpashis plats","giftets källa"}},{q="Vilket annat material finns på Leftwitchs lista?",a="Kreldig behöver också skinn från åldrade kodos. Leftwitchs instruktioner anger åldrade kodos, inte döende eller uråldriga.",al={"annat reagens","vad mer behöver kreldig","skinn från åldrade kodos"}}},fp="15,147,15.257.0,33.104.0,20.100.0,37.67.0,45.120.0"}
P.entries["item:scrap-metal-scrounging"] = {n="Scrap Metal",s="Scrap Metal hämtas från ogres i Dustbelch Grotto i Badlands. Sigrun behöver det för att bygga försvar och förnödenheter till ett litet läger.",h="Scrap Metal hämtas från ogres i Dustbelch Grotto i Badlands.",kw={"badlands","läger","dustbelch grotto","explorers' league","ironforge","ogres","skrotmetall","skrotsamling","sigrun"},ang={["profession:Engineering"]="Som ingenjör förstår du varför Sigrun behöver skrotmetall: lägret saknar material till försvar och andra förnödenheter.",["race:Dwarf"]="Som dvärg vet du kanske att lägret väntar på besked från Ironforge medan Sigrun får klara sig med förnödenheterna som finns till hands."},sec={{t="Till lägret",b="Sigrun behöver skrotmetall till försvar och andra förnödenheter i lägret i Badlands. Ogres i Dustbelch Grotto västerut bär på det, och lägret har inte mycket i reserv. Tills besked kommer från Ironforge eller Explorers' League hjälper varje bit."}},faq={{q="Vad används skrotmetall till?",a="Sigrun behöver skrotmetall för att bygga försvar och andra förnödenheter till lägret i Badlands.",al={"användning av skrotmetall","varför samla skrot","metall till sigrun"}},{q="Var kan jag hitta skrotmetall?",a="Ogres i Dustbelch Grotto, väster om Sigruns läger i Badlands, bär på skrotmetall.",al={"plats för skrotmetall","var finns metall","metall från dustbelch"}},{q="Vem vill ha skrotmetallen?",a="Sigrun vill ha skrotmetall för att hjälpa till att förse och försvara lägret.",al={"vem behöver metall","sigruns skrot","metall till vem"}},{q="Varför samlar Sigrun på förnödenheter?",a="Sigrun har ont om material till lägrets försvar och andra förnödenheter, så hon samlar ihop vad hon kan.",al={"lägret behöver förnödenheter","varför leta skrot","sigruns försvar"}}},fp="11,141,12.251.0,24.98.0,29.88.0,26.60.0,33.105.0"}
P.entries["item:scrimshank-s-surveying-gear"] = {n="Scrimshank's Surveying Gear",s="Scrimshank's Surveying Gear ligger under Tanaris sand, i Gaping Chasm. Senior Surveyor Fizzledowser behöver fynden för att undersöka öknens märkliga insekter.",h="Scrimshank's Surveying Gear ligger under Tanaris sand, i Gaping Chasm.",kw={"fizzledowser","the gaping chasm","goblin","junior surveyor","scrimshank","silithid","mätutrustning","tanaris"},sec={{t="Under sanden",b="I Gaping Chasm i Tanaris är Scrimshank's Surveying Gear det enda som återstår efter den försvunne Junior Surveyor. Hans överordnade, Fizzledowser, skickade ut honom i öknen efter rapporter om märkliga insekter. Maskinen innehåller Scrimshanks sista anteckningar, som kan hjälpa till att förklara faran som hotar Gadgetzan."}},faq={{q="Vad är Scrimshank's Surveying Gear?",a="Det är mätutrustningen som tillhör Junior Surveyor Scrimshank. Den hittades under Tanaris, i Gaping Chasm.",al={"scrimshanks utrustning","mätmaskin","vad är utrustningen"}},{q="Var finns mätutrustningen?",a="Scrimshank's Surveying Gear ligger i Gaping Chasm under Tanaris.",al={"utrustningens plats","var finns scrimshanks saker","utrustning i gaping chasm"}},{q="Vem var Scrimshank?",a="Junior Surveyor Scrimshank var Senior Surveyor Fizzledowsers assistent. Han skickades för att undersöka märkliga insekter i Gaping Chasm.",al={"junior surveyor","scrimshanks bakgrund","vem är scrimshank"}},{q="Varför vill Fizzledowser ha utrustningen?",a="Fizzledowser hoppas att Scrimshanks anteckningar ska hjälpa till att avslöja vad som händer med de märkliga insekterna i öknen.",al={"varför utrustningen är viktig","fizzledowser vill ha den","vad den registrerade"}}},fp="27,178,17.297.0,36.103.0,28.69.0,19.126.0,36.111.0"}
P.entries["item:scroll-of-messaging"] = {n="Scroll of Messaging",s="Scroll of Messaging är ett förtrollat pergament med en särskild magisk överföringsbesvärjelse. Det införskaffas åt gnomingenjören Gaxim Rustfizzle i Stonetalon Mountains och har ett ovanligt syfte: att ge den magiska utlösare som behövs för att detonera fjärrstyrda sprängladdningar.",h="Scroll of Messaging är ett förtrollat pergament med en särskild magisk överföringsbesvärjelse.",kw={"sprängladdningar","gaxim rustfizzle","ng-5","fjärrdetonator","scroll of messaging","stonetalon","venture company"},ang={["faction:Alliance"]="Pergamentet spelar en viktig roll när Alliansens agenter saboterar Venture Companys maskiner och hejdar deras miljöförstörelse i Stonetalon.",["profession:Engineering"]="I sann gnomisk innovationsanda visar pergamentet hur teoretisk magi kan användas som en fjärrmottagare för mekanisk sprängning."},sec={{t="Ett explosivt meddelande",b="Scroll of Messaging är till synes en magisk skrift för kommunikation över långa avstånd, men Gaxim Rustfizzle har en betydligt mer omstörtande användning i åtanke. Genom att kombinera dess överföringsbesvärjelse med flyktiga NG-5-laddningar planerar gnomen att skapa en fjärrutlöst sprängladdning. Explosionen ska skapa en massiv avledning vid Venture Companys skogsavverkningsverksamhet i Stonetalon, så att agenter kan smita förbi vakterna och stjäla skyddade ingenjörsritningar och konfidentiell korrespondens."}},faq={{q="Vad används Scroll of Messaging till?",a="Trots att den är skriven som en meddelandebesvärjelse använder Gaxim Rustfizzle dess överföringsmagi för att skapa en fjärrutlösare. Kombinerad med explosiva NG-5 låter den honom utlösa en explosion på säkert avstånd.",al={"användning av scroll of messaging","vad gör scroll of messaging","varför gaxim vill ha scroll"}},{q="Vem får det här pergamentet?",a="Pergamentet levereras till Gaxim Rustfizzle, en gnomingenjör som står på Alliansens sida och arbetar i Stonetalon Mountains.",al={"vem får scroll of messaging","var lämnar jag scroll of messaging","mottagare av pergamentet"}},{q="Varför behöver Gaxim en fjärrstyrd sprängladdning?",a="Gaxim behöver skapa en stor avledning vid Venture Companys verksamhet i området. Kaoset ger skydd när man tar sig in i deras anläggning, stjäl värdefulla ingenjörsritningar och hämtar dokument för att stoppa deras aggressiva kalavverkning av skogen.",al={"varför gaxim behöver sprängladdning","varför spränga venture company","avledning i stonetalon"}},{q="Vad är NG-5?",a="NG-5 är en explosiv kemisk laddning som Gaxim Rustfizzle använder. Tillsammans med den magiska signalen som står inskriven på Scroll of Messaging blir den en improviserad fjärrdetonator.",al={"ng-5","vad är ng-5","ng5 sprängladdning"}}},fx={["2071477e"]={q="Vad är Scroll of Messaging?",a="Scroll of Messaging är ett förtrollat pergament med en mystisk besvärjelse. Gaxim Rustfizzle sökte upp det som en okonventionell katalysator att kombinera med sin flyktiga sprängblandning, NG-5. Med den kan han tillverka en fjärrutlöst laddning mot Venture Companys verksamhet i Stonetalon.",al={"vad är scroll of messaging","scroll of messaging bakgrund","om scroll of messaging"}}},fp="19,98,18.314.0,41.152.0,25.84.0,39.220.0,13.130.0"}
P.entries["item:scroll-of-myzrael"] = {n="Scroll of Myzrael",s="Scroll of Myzrael används vid Shards of Myzrael i Arathi Highlands för att kalla henne tillbaka.",h="Scroll of Myzrael används vid Shards of Myzrael i Arathi Highlands för att kalla henne tillbaka.",kw={"arathi highlands","eldritch shackles","myzrael","prinsessa","scroll of myzrael","shards of myzrael","frammaning"},sec={{t="Vid Shards",b="Vid Shards of Myzrael i Arathi Highlands kallar rullen fram varelsen som hålls fången under dem. Myzrael måste besegras, och hennes Eldritch Shackles bindas vid skärvorna. Syftet är att hålla henne fången medan hennes kraft växer."}},faq={{q="Vad gör Scroll of Myzrael?",a="Scroll of Myzrael används för att frammana Myzrael vid Shards of Myzrael i Arathi Highlands.",al={"användning av scroll of myzrael","vad är rullen till för","frammana myzrael"}},{q="Var använder jag rullen?",a="Rullen används vid Shards of Myzrael i Arathi Highlands, där Myzrael först påträffades.",al={"var finns rullen","var ligger myzraels skärvor","var frammana henne"}},{q="Varför frammana Myzrael?",a="Myzrael måste besegras innan hennes kraft växer, och sedan bindas på nytt vid skärvorna med sina Eldritch Shackles.",al={"varför frammana myzrael","vad är poängen","varför kalla på henne"}},{q="Vad är Eldritch Shackles till för?",a="Eldritch Shackles binds vid Shards of Myzrael för att fånga henne igen.",al={"eldritch shackles syfte","myzraels shackles","hur binda henne"}}},fp="17,103,13.232.0,35.97.0,26.105.0,19.107.1,35.75.1"}
P.entries["item:sea-creature-bones"] = {n="Sea Creature Bones",s="Sea Creature Bones är skelettprover som samlats in från de väldiga kadavren av havsdjur som sköljs upp längs Darkshores dimhöljda kust. Dessa kvarlevor skickas direkt till Temple of the Moon i Darnassus och är centrala för en pågående undersökning av vad som får dessa stora bestar att gå på grund på stränderna.",h="Sea Creature Bones är skelettprover som samlats in från de väldiga kadavren av havsdjur som sköljs upp längs...",kw={"auberdine","strandat havsdjur","darkshore","greymist murlocs","gwennyth bly'leggonde","mist's edge","sea creature bones","temple of the moon"},ang={["class:Druid"]="De oförklarliga dödsfallen bland uråldriga rovdjur i havet tyder på en djupgående störning i vattnen utanför Kalimdor och oroar varje väktare som värnar om den ekologiska balansen.",["race:NightElf"]="De plötsliga massstrandningarna längs Darkshore oroar nattalverna djupt. De vördar naturens harmoni och ser dessa strandningar som ett mörkt omen som kräver Temple of the Moons uppmärksamhet."},sec={{t="Ett förebud på stranden",b="Darkshores dimhöljda stränder har nyligen bevittnat en oroväckande ökning av väldiga havsdjur, däribland jättelika threshers som är mycket större än de som lever i de lokala grunda vattnen. De kastar sig upp på grunt vatten tills de dör. Nattalverna ser detta som ett illavarslande förebud. Gwennyth Bly'Leggonde, en utredare som skickats från Temple of the Moon till Auberdine, samlar benprover från dessa strandade leviataner för att skicka dem med hippogryf till Darnassus för noggrann undersökning."},{t="Asätare och kadaver",b="Det är farligt att samla in benen, eftersom de väldiga kadavren oundvikligen lockar till sig lokala asätare. Kustens Greymist murlocs svärmar ofta kring de döda och döende leviatanerna, äter av kvarlevorna och försvarar matplatserna aggressivt. Murlocs är alldeles för svaga för att själva jaga så kolossala varelser, men deras opportunistiska närvaro längs Mist's Edge tvingar utredare och äventyrare att kämpa sig igenom asätarflockarna för att säkra användbara benfragment för studier."}},faq={{q="Varför sköljs dessa varelser upp på stranden?",a="Den exakta orsaken är fortfarande okänd. Enstaka strandningar är en naturlig fara, men deras plötsliga och dramatiska ökning anses onaturlig och oroande av Elunes prästinnor, vilket har lett till en formell undersökning.",al={"varför går threshers på grund","döda valar i darkshore","varför går havsdjur på grund i darkshore"}},{q="Vem vill ha benen?",a="Gwennyth Bly'Leggonde, en utredare stationerad i Auberdine, samlar in benen på uppdrag av Temple of the Moon i Darnassus. Där hoppas lärda och prästinnor kunna ta reda på vad som stör havet.",al={"vem hämtar benen","vem lämnar in sea creature bones","gwennyth i darkshore"}},{q="Dödade murlocs dessa jättelika bestar?",a="Nej. De lokala Greymist murlocs är alldeles för svaga för att fälla havsdjur av den storleken. De är bara asätare som samlas i stora antal för att äta av kadavren när de väl spolats upp på stranden.",al={"dödade murlocs threshers","dödade greymist murlocs havsmonster"}},{q="Var hämtas benen?",a="De hämtas direkt från de väldiga kadavren som strandat längs Darkshores kust, särskilt på sandstränderna söder om Auberdine och längs Mist's Edge.",al={"var hittar man sea creature bones","platser med strandade havsdjur"}}},fx={["90a4db20"]={q="Vad är Sea Creature Bones?",a="Det är skelettrester som bärgats från ett enormt havsdjurs kadaver, närmare bestämt en ovanligt stor haj som strandat längs Darkshores dimmiga kust. Lokala Greymist-murlocker har plockat åt sig av de väldiga kvarlevorna, som är viktiga fysiska bevis för forskare som försöker förstå varför havets jättar dör på land.",al={"vad är sea creature bones","sea creature bones bakgrund","jätteben i darkshore"}},cb40613a={q="Varifrån kommer Sea Creature Bones?",a="Benen kommer från en kolossal haj, mycket större än någon väntat sig i Darkshores vatten, som av okänd anledning kastade sig upp på stränderna vid Mist's Edge söder om Auberdine. Benen skapades inte och dödades inte av lokala rovdjur. De tillhör naturligt djuphavsdjur som av mystiska skäl tog sig upp på land för att dö.",al={"varifrån kommer sea creature bones","sea creature bones ursprung","strandat havsdjurs ursprung"}}},fp="18,223,22.411.0,22.319.0,39.208.0,22.166.0,40.143.0,35.129.0"}
P.entries["item:sea-turtle-remains"] = {n="Sea Turtle Remains",s="Sea Turtle Remains är skelettprover som bärgats från kadavren efter jättelika havssköldpaddor längs Darkshores kust. De är viktiga prover för Night Elf-forskare i Auberdine, som undersöker den oroande ökningen av strandade havsdjur.",h="Sea Turtle Remains är skelettprover som bärgats från kadavren efter jättelika havssköldpaddor längs...",kw={"auberdine","strandad havssköldpadda","darkshore","gwennyth bly'leggonde","sea turtle remains","teldrassil","temple of the moon","uppspolad på stranden"},ang={["class:Druid"]="Den onaturliga döden bland vilda jättelika havsdjur tyder på en djupare fördärvelse som rubbar naturens balans längs Kalimdors kust.",["race:NightElf"]="Att havsdjur i mängder strandas alldeles utanför din förfäders kust är ett illavarslande tecken, särskilt eftersom misstankarna pekar mot vattnen kring Teldrassil."},sec={{t="En oroande strandning",b="Jättelika havsdjur har börjat strandas längs hela Darkshores dimhöljda kust, medan andra ligger under ytan nära vrak strax utanför land. Gwennyth Bly'Leggonde, som är stationerad i Auberdine, övervakar insamlingen av skelettfragment och vävnad från kadavren. Temple of the Moon i Darnassus begär proverna skyndsamt och oroar sig för teorier om att djuren flyr från en onaturlig störning i vattnen kring det nyvuxna världsträdet Teldrassil."},{t="Asätare i grunda vatten",b="Att bärga kvarlevorna är farligt arbete. Murlocstammar längs kusten samlas regelbundet kring de enorma kadavren, gnager benen rena och bygger bon intill dem. De lärda behöver färska benfragment och vävnad innan asätarna förstör alla spår som kan förklara djurens dödliga vandring."}},faq={{q="Vad används kvarlevorna till?",a="Gwennyth Bly'Leggonde samlar in kvarlevorna i Auberdine. Hon förbereder dem åt de lärda och prästinnorna vid Temple of the Moon i Darnassus, som försöker ta reda på varför så många havsdjur dör längs Darkshore.",al={"varför samla in sköldpaddsrester","vad används sköldpaddsben till","sköldpaddsuppdrag darkshore"}},{q="Varför strandas havssköldpaddor i Darkshore?",a="Orsaken utreds fortfarande, men forskarna befarar att havslivet flyr från något oroväckande i vattnen kring Teldrassil. Strandningarna är inga enstaka händelser, utan tyder på en utbredd ekologisk kris.",al={"varför dör sköldpaddor","strandade sköldpaddor darkshore","strandade havsdjur"}},{q="Var hittar man kadavren?",a="Jättelika skelett efter havssköldpaddor ligger utspridda längs Darkshores kust. Några finns i grunt vatten nära skeppsvrak väster om Auberdine, medan andra ligger på stränder omgivna av murlocläger.",al={"platser med sköldpaddsrester","var hittar man skelett efter havssköldpadda"}},{q="Vem undersöker kvarlevorna?",a="Gwennyth Bly'Leggonde, forskare i Auberdine, samlar in fynden och skickar utförliga rapporter direkt till The Sisterhood of Elune vid Temple of the Moon i Darnassus.",al={"vem vill ha kvarlevorna","gwennyth blyleggonde"}}},fx={dfe0d6c5={q="Vad är Sea Turtle Remains?",a="Det är skelettprover från jättelika havssköldpaddor som spolats upp längs Darkshores kust eller dött på grunt vatten. Lokala rovdjur och murlocker har plockat åt sig av dem, men ben och vävnad finns kvar och ger fysiska ledtrådar om djurens sista stunder.",al={"vad är sea turtle remains","sea turtle remains bakgrund"}},be90da46={q="Varifrån kommer Sea Turtle Remains?",a="De samlas direkt från väldiga skelett som ligger längs stränderna och i kustvattnen vid Darkshore, bland annat i närheten av Auberdine. De är naturliga lämningar efter havsdjur, inte tillverkade föremål, och blir kvar när döende sköldpaddor simmar upp på land och dör.",al={"varifrån kommer sea turtle remains","sea turtle remains ursprung","sea turtle remains källa"}}},fp="18,149,19.379.0,26.287.0,32.199.0,53.195.0,32.181.0,30.150.0"}
P.entries["item:seahorn-s-sealed-letter"] = {n="Seahorn's Sealed Letter",s="Seahorn's Sealed Letter för med sig hemlig korrespondens från Booty Bay till Shakes O'Breen utanför Arathi coast. Blackwater Raiders räknar med att brevet kommer fram säkert.",h="Seahorn's Sealed Letter för med sig hemlig korrespondens från Booty Bay till Shakes O'Breen utanför Arathi...",kw={"arathi coast","blackwater raiders","booty bay","seahorn","förseglat brev","hemlig korrespondens","shakes o'breen"},sec={{t="Ett förseglat meddelande",b="Från Booty Bay ber Seahorn dig att ta hans förseglade brev till Shakes O'Breen, vars skepp ligger utanför Arathi coast. Seahorns flotta väntar i bukten på förnödenheter, medan oroväckande angelägenheter hopar sig både nära och långt borta. Han ber om förtroende såväl som säker färd. Blackwater Raiders väntar på besked om att meddelandet nått fram."}},faq={{q="Vem skickade det förseglade brevet?",a="Seahorn skickade det förseglade brevet från Booty Bay. Han ber att det når Shakes O'Breen säkert och i förtroende.",al={"vem skrev brevet","seahorn brev","brev från seahorn"}},{q="Vem ska ta emot det?",a="Shakes O'Breen, vars skepp ligger för ankar utanför Arathi coast, är brevets avsedda mottagare.",al={"vem får brevet","leverera till vem","shakes brev"}},{q="Varför behöver Seahorn ett bud?",a="Seahorn behöver få den förseglade korrespondensen till Shakes O'Breen medan hans flotta sitter fast i Booty Bay och väntar på förnödenheter.",al={"varför leverera det","vad finns i brevet","hemligt meddelande"}},{q="Vad händer om jag levererar det säkert?",a="Blackwater Raiders är tacksamma för den långa och farofyllda resan, och Seahorn blir nöjd när meddelandet når mottagaren.",al={"vad får man för att leverera","blackwater raiders","seahorn nöjd"}}},fp="23,166,16.341.0,27.109.0,30.88.0,32.122.0,36.133.1"}
P.entries["item:sealed-description-of-thredd-s-visitor"] = {n="Sealed Description of Thredd's Visitor",s="Warden Thelwater förseglar en rapport om en besökare hos Bazil Thredd i Stormwind Stockade. Den hemliga redogörelsen hjälper till att spåra en hemlig agent som rör sig i Stormwinds politiska och kriminella kretsar.",h="Warden Thelwater förseglar en rapport om en besökare hos Bazil Thredd i Stormwind Stockade.",kw={"baros alexston","bazil thredd","maelik","mathias shaw","förseglad beskrivning","stockade","warden thelwater"},ang={["class:Rogue"]="Som rogue kan du se hur falska namn, förfalskade handlingar och besök i en fängelsecell fångade Mathias Shaws uppmärksamhet när han jämförde mannens utseende med SI:7:s underrättelser.",["faction:Alliance"]="Som medlem av Alliansen kan du se svagheten i Stormwinds säkerhet: konspiratörer kan passera genom portarna till The Stockade med förfalskade handlingar."},sec={{t="En mystisk beskyddare",b="Fången Bazil Thredd tillbringade år i The Stockade utan att få besök. Sedan började en tystlåten man komma en eller två gånger i veckan, med giltiga identitetshandlingar i namnet Maelik. Warden Thelwater lade märke till de ovanliga besöken och skrev ner hur mannen såg ut. Han förseglade beskrivningen så att inga nyfikna ögon skulle kunna läsa den innan rätt utredare hann agera."},{t="Från stenhuggare till spioner",b="Stadsarkitekten Baros Alexston hittade ingen tydlig matchning i beskrivningen, men misstänkte att besökaren kunde ha kopplingar till Defias-upproret. Alexston skickade det förseglade kuvertet till Master Mathias Shaw, som leder Stormwinds underrättelsetjänst SI:7. Shaw kände igen mannen som en dödlig legosoldat som använder namn som Marzon och numera utför smutsiga uppdrag åt Lord Gregor Lescovar."}},faq={{q="Vem skrev beskrivningen?",a="Warden Thelwater, övervakare i Stormwind Stockade, skrev och förseglade dokumentet. Han blev misstänksam när en okänd man började besöka den fängslade Defias-ledaren Bazil Thredd regelbundet.",al={"vem skrev det","beskrivningens författare","vem skrev anteckningen"}},{q="Vem är besökaren som beskrivs i dokumentet?",a="Besökaren använde handlingar i namnet Maelik. Warden Thelwater antecknade hans utseende så att utredare skulle kunna identifiera honom.",al={"vem besökte thredd","vem är maelik","besökarens identitet"}},{q="Varför träffade besökaren Bazil Thredd?",a="Thelwater blev misstänksam när Thredd började få regelbundna besök efter år utan några alls. Den förseglade beskrivningen utreds för att ta reda på besökarens syfte.",al={"varför besöka thredd","thredds besökares syfte"}},{q="Vart ska det förseglade dokumentet lämnas?",a="Ta först dokumentet till stadsarkitekten Baros Alexston i Stormwind. Efter att ha granskat den främmande beskrivningen ber Alexston dig att lämna det till Master Mathias Shaw vid SI:7:s högkvarter i Old Town.",al={"vart ska jag lämna det","vem vill ha beskrivningen"}}},fx={["7193ccc9"]={q="Varför är beskrivningen av Thredds besökare så viktig?",a="I åratal satt Bazil Thredd övergiven i Stockade utan att få en enda besökare. När en mystisk person med papper i namnet ”Maelik” plötsligt började besöka honom varje vecka, misstänkte Warden Thelwater en djupare konspiration. Att avslöja besökarens identitet är avgörande för att ta reda på vem i Stormwind som samordnar sig med Defias Brotherhoods fängslade ledning. Därför söker utredarna upp Mathias Shaws underrättelsenätverk för att identifiera den skuggiga mellanhanden.",al={"varför vill de ha beskrivningen","varför efterfrågas den förseglade beskrivningen av thredd","varför är beskrivningen av besökaren viktig"}}},fp="38,215,19.325.0,25.380.1,27.196.0,42.127.2,46.153.2,49.206.1"}
P.entries["item:sealed-envelope"] = {n="Sealed Envelope",s="Detta väl förseglade paket innehåller konfidentiella tekniska dokument och stulna ritningar från Venture Company. Den landsförvisade gobliningenjören Fizziks har sammanställt dem för leverans till Sputtervalve i Ratchet.",h="Detta väl förseglade paket innehåller konfidentiella tekniska dokument och stulna ritningar från Venture...",kw={"ritningar","fizziks","ratchet","sealed envelope","sputtervalve","stonetalon","super reaper 6000","venture company"},ang={["faction:Horde"]="När pappren förs söderut från Stonetalon hjälper det Ratchets neutrala gobliner att motarbeta Venture Companys aggressiva och hänsynslösa avverkning.",["profession:Engineering"]="Kuvertet innehåller tekniska ritningar till Super Reaper 6000, en av de mest destruktiva och lönsamma mekaniska automatiseringar som gobliner har konstruerat."},sec={{t="Företagsspionage",b="När gobliningenjören Fizziks plötsligt sparkades från Venture Companys skogsavverkning i Stonetalon Mountains lämnade han inte tomhänt. Han stoppade interna handböcker, arbetsrutiner och tekniska specifikationer i kuvertet och lyckades smuggla ut företagets hemligheter under näsan på sina forna uppsyningsmän. Bland de stulna dokumenten är ritningarna till Super Reaper 6000 mest värdefulla. Det är en förödande maskin för industriell kalavverkning."},{t="Leverans till Ratchet",b="I stället för att låta de farliga företagshemligheterna förbli gömda skickar Fizziks paketet söderut till Sputtervalve, en ingenjör som bor i den neutrala goblinhamnen Ratchet. Affärsrivalerna i Steamwheedle Cartel hyser inte mycket personlig tillgivenhet eller tillit till Fizziks, men ritningarnas ingenjörsvärde går inte att förneka. Dokumenten ger en tydlig inblick i Venture Companys mekaniska uppfinningsrikedom och ger oberoende ingenjörer en chans att dra nytta av företagets avancerade avverkningsteknik."}},faq={{q="Vad finns i Sealed Envelope?",a="Kuvertet innehåller interna dokument från Venture Company, tekniska handböcker för drift och ritningarna till Super Reaper 6000, en maskin för skogsröjning. Fizziks stal allt under sin hastiga avfärd.",al={"kuvertets innehåll","vad finns i sealed envelope","föremål i sealed envelope"}},{q="Vem sammanställde paketet?",a="Paketet sammanställdes av Fizziks, en missnöjd gobliningenjör som sparkades av Venture Company från deras avverkning i Stonetalon Mountains.",al={"vem gjorde kuvertet","vem gav sealed envelope","fizziks kuvert"}},{q="Vem ska ta emot det?",a="Det är adresserat till Sputtervalve, en goblinmekaniker som bor i hamnstaden Ratchet i The Barrens.",al={"vem får kuvertet","vart ska kuvertet","leverans till sputtervalve"}},{q="Varför vill Sputtervalve ha dokumenten?",a="Sputtervalve ogillar Venture Company och är på sin vakt mot Fizziks, men dokumenten innehåller värdefulla förbättringar och ritningar. De låter utomstående mekaniker förstå och använda företagets kraftfulla mekaniska konstruktioner.",al={"varför sputtervalve vill ha det","venture company teknik ratchet"}}},fp="15,109,19.315.0,19.342.0,35.192.0,25.138.0,30.99.0,43.185.0"}
P.entries["item:sealed-letter-to-archmage-malin"] = {n="Sealed Letter to Archmage Malin",s="Det förseglade brevet för med sig nyheter från Arathi Highlands till Archmage Malin i Stormwind. Malin får höra från sina följeslagare där.",h="Det förseglade brevet för med sig nyheter från Arathi Highlands till Archmage Malin i Stormwind.",kw={"arathi highlands","archmage malin","kryten","mage quarter","malin","förseglat brev","skuerto","stormwind","trelane"},sec={{t="Nyheter från Arathi",b="I Mage Quarter i Stormwind öppnar Archmage Malin brevet och känner igen nyheterna det för med sig. Trelane kommer att bli glad, och Kryten och Skuerto längtar efter att ta sig tillbaka till Stormwind. Malin tackar budbäraren och erbjuder hjälp inför den fortsatta resan."}},faq={{q="Vem är brevet till?",a="Det förseglade brevet är adresserat till Archmage Malin i Mage Quarter i Stormwind.",al={"brev till malin","malins brev"}},{q="Varifrån kommer brevet?",a="Brevet kommer från Arathi Highlands, där Kryten och Skuerto säger att de snart är hemma.",al={"brev från arathi","varifrån kommer brevet"}},{q="Vad står det i brevet?",a="Det berättar för Archmage Malin att Kryten och Skuerto snart är hemma.",al={"brevets innehåll","vad står det i brevet"}},{q="Vem är Kryten?",a="Kryten är en av följeslagarna som väntas återvända till Stormwind med Skuerto.",al={"kryten brev","vem är kryten"}},{q="Vem är Skuerto?",a="Skuerto är en av följeslagarna som väntas återvända till Stormwind med Kryten.",al={"skuerto brev","vem är skuerto"}}},fp="31,127,16.250.0,22.77.0,32.92.1,25.66.1,14.77.0,15.77.0"}
P.entries["item:sealed-note-to-advisor-belgrum"] = {n="Sealed Note to Advisor Belgrum",s="Historian Karniks förseglade brev för med sig en varning från Badlands till Advisor Belgrum. Innehållet visar nästa steg mot Shadowforge dwarves.",h="Historian Karniks förseglade brev för med sig en varning från Badlands till Advisor Belgrum.",kw={"advisor belgrum","badlands","hammertoe","historian karnik","förmedla en varning om ett hot","förseglat brev","shadowforge"},sec={{t="En varning förmedlas",b="I Badlands bär du Historian Karniks brev till Advisor Belgrum. Karnik ber dig berätta för Belgrum vad du bevittnade och be om hans råd. Samtidigt vänder sig Karnik till anden hos Hammertoe i hopp om att den kan hjälpa till att stoppa Shadowforge dwarves verksamhet."}},faq={{q="Vem skrev det förseglade brevet?",a="Historian Karnik skickade brevet till Advisor Belgrum.",al={"brevets avsändare","vem skickade brevet"}},{q="Vem är brevet till?",a="Brevet är adresserat till Advisor Belgrum.",al={"vem får brevet","brev till belgrum"}},{q="Vad handlar brevet om?",a="Karnik säger att brevet ska förklara vad du bevittnade och ber Belgrum om råd om hur ni ska gå vidare.",al={"vad står det","brevets innehåll"}},{q="Varför skickar Karnik brevet?",a="Karnik vill att Belgrum ska få höra vad du bevittnade och avgöra hur ni ska gå vidare.",al={"varför bära brevet","karniks meddelande"}},{q="Vad gör Karnik medan du bär brevet?",a="Karnik planerar att tala med anden hos Hammertoe i hopp om att den kan hjälpa till att stoppa Shadowforge dwarves verksamhet i Badlands.",al={"vad gör karnik","hammertoes ande"}}},fp="30,152,17.256.0,26.50.0,20.41.0,23.101.0,31.83.0,40.123.0"}
P.entries["item:sealed-note-to-elling"] = {n="Sealed Note to Elling",s="Jorgen skickar ett förseglat meddelande genom Stormwind till Elling Trias, ägaren till Trias' Cheese. Fiskarens meddelande drar in Trias i en diskret utredning om en försvunnen diplomat.",h="Jorgen skickar ett förseglat meddelande genom Stormwind till Elling Trias, ägaren till Trias' Cheese.",kw={"elling trias","jorgen","sealed note to elling","stormwind","den försvunna diplomaten","trade district","trias cheese"},ang={["class:Rogue"]="Som skurk med kännedom om Stormwinds skuggnätverk kanske du känner igen Elling Trias som mer än en osthandlare. Den här diskreta korrespondensen passar nätverkens arbete.",["faction:Alliance"]="Som medlem av Alliansen för du Jorgens meddelande i Kronans tjänst och hjälper till att föra fram en utredning som är avgörande för Stormwinds politiska stabilitet."},sec={{t="En diskret överlämning",b="Jorgen ger strikta instruktioner om det förseglade meddelandet i Stormwind: lämna det i Elling Trias händer och håll tyst. Insatserna lämnar inget utrymme för obetänksamt prat. Trias driver en ostbutik i Trade District, där Jorgens meddelande för utredningen om diplomatens försvinnande till hans disk."}},faq={{q="Vad står det i det förseglade meddelandet?",a="Meddelandet förblir förseglat tills det når Elling Trias. Det innehåller Jorgens rapport och hänvisar budbäraren till Trias för vidare undersökningar av diplomatens försvinnande.",al={"meddelandets innehåll","vad står det i meddelandet","brevets text"}},{q="Varför får en osthandlare hemlig information?",a="Elling Trias driver en anspråkslös ostbutik i Trade District som täckmantel. Bakom den fasaden har han ett omfattande nätverk av öron och ögon över hela staden, vilket gör honom värdefull i känsliga utredningar.",al={"varför elling trias","varför ostbutik","är trias spion"}},{q="Vem är Jorgen?",a="Jorgen är en fiskare som håller till nere vid vattnet i Stormwinds Valley of Heroes. Han har en viss historia med Elling Trias och Bishop DeLavey, som anlitar honom för diskreta ärenden som ska hållas utom nyfikna ögon.",al={"vem skrev meddelandet","jorgens historia","väktaren jorgen"}},{q="Vad handlar fallet med den försvunna diplomaten om?",a="En diplomat från Stormwind som skickades till Theramore för att träffa Jaina Proudmoore kom aldrig fram. Kungliga myndigheter utreder i tysthet varje misstänkt spår för att undvika att skapa panik på gatorna.",al={"den försvunna diplomatens historia","vem är diplomaten","varför försvunnen diplomat"}}},fx={["76232759"]={q="Vad är Sealed Note to Elling?",a="Det är ett konfidentiellt meddelande som Jorgen har gett dig och som bara Elling Trias ska få läsa och höra. Det är förseglat med vax för att bevara hemligheten och innehåller brådskande information om utredningen av den försvunne diplomaten. Du har fått det i förtroende för att lämna över det säkert i Stormwind.",al={"vad är sealed note to elling","föremålet sealed note to elling","vad är jorgens brev"}},["2cd529f3"]={q="Varifrån kommer Sealed Note to Elling?",a="Jorgen skrev och förseglade brevet. Efter att ha förhört personer och granskat spåren efter rikets försvunne diplomat skriver Jorgen det här diskreta meddelandet och lämnar det direkt till dig, så att du kan ta det till Elling Trias.",al={"vem skrev sealed note to elling","varifrån kom det förseglade brevet","vem gav sealed note to elling"}},["92e95eae"]={q="Varför behövs Sealed Note to Elling?",a="Diplomatens försvinnande är en ytterst känslig fråga som rör rikets säkerhet. Jorgen kan inte tala öppet på gatorna, så brevet fungerar som en diskret introduktion och överlämning av underrättelser till Elling Trias. På så vis blir Trias delaktig i utredningen utan att väcka nyfikna blickar.",al={"varför lämna över det förseglade brevet","varför behöver elling trias brevet","varför är jorgens brev viktigt"}}},fp="21,176,16.297.0,39.169.0,53.235.0,14.197.0,40.177.0"}
P.entries["item:sealed-note-to-watcher-backus"] = {n="Sealed Note to Watcher Backus",s="I Stormwind skickar Elling Trias ett förseglat brev till Watcher Backus i Duskwood. Han ber vakten i Night Watch rapportera Defias-aktivitet nära Darkshire.",h="I Stormwind skickar Elling Trias ett förseglat brev till Watcher Backus i Duskwood.",kw={"darkshire","duskwood","elling trias","night watch","förseglat brev","den försvunna diplomaten","watcher backus"},ang={["class:Rogue"]="Trias förlitar sig på en vanlig vakt för lokal information, ett sätt att samla underrättelser långt bortom stadsmurarna.",["faction:Alliance"]="Brevet visar hur personliga band och informella underrättelser hjälper till att hålla Alliansens splittrade territorier samman när de officiella kanalerna sviktar."},sec={{t="Ett ord till vakten",b="Elling Trias går med på att använda sina kontakter för att hjälpa till att leta efter den försvunna diplomaten. Han förseglar ett brev till Watcher Backus, en vakt i Night Watch som är stationerad i Duskwood. Trias skickar en resenär söderut genom skogen för att överlämna det personligen. Han hoppas att Backus rapporterar om han ser några Defias nära Darkshire."},{t="Trias långväga ögon",b="Elling Trias säljer ost i Stormwinds Trade District och har kontakter utanför staden. Hans brev når Watcher Backus, en vakt i Darkshires vaksamma Night Watch. Staden hotas av odöda och vildsinta bestar, men Backus tar varmt emot Trias meddelande. Deras band visar att Trias har vunnit respekt även utanför Stormwind."}},faq={{q="Vem skrev brevet?",a="Elling Trias skrev brevet. Han äger Trias' Cheese i Stormwind Citys Trade District och arbetar i hemlighet som spion och informationsmäklare.",al={"vem skrev förseglat brev till watcher backus","brevets författare","vem överlämnar brevet"}},{q="Varför skickas det till Watcher Backus?",a="Watcher Backus tjänstgör i Darkshires Night Watch och är en betrodd kontakt till Elling Trias. Trias ber honom rapportera lokala iakttagelser eller rykten om Defias Brotherhoods aktivitet runt Duskwood.",al={"vem är watcher backus","varför skicka till backus","vad har backus för roll"}},{q="Var finns Watcher Backus?",a="Watcher Backus patrullerar vägen strax norr om Darkshire i Duskwood och håller utkik efter hot som närmar sig staden genom skogen.",al={"var finns backus","watcher backus plats","hitta watcher backus"}},{q="Vad händer när brevet har överlämnats?",a="Backus känner igen Trias namn och litar på hans begäran. Han lägger sin vanliga försiktighet mot resenärer åt sidan och går med på att undersöka misstänkt aktivitet i skogen.",al={"vad säger backus","efter att brevet överlämnats"}}},fx={["8647b8fc"]={q="Vad är Sealed Note to Watcher Backus?",a="Det är ett konfidentiellt meddelande skrivet av Elling Trias, Stormwinds främste osthandlare, och avsett för Watcher Backus i Duskwood. Trias skickar det med dig för att få Backus hjälp att samla underrättelser om Defias Brotherhoods lokala verksamhet som en del av den pågående utredningen av den försvunne diplomaten.",al={"vad är sealed note to watcher backus","syftet med sealed note to watcher backus","trias brev till backus"}}},fp="29,149,20.285.0,25.309.1,20.137.0,39.189.0,34.110.0,41.163.0"}
P.entries["item:sealed-venom-container"] = {n="Sealed Venom Container",s="The Sealed Venom Container innehåller gift från giftiga varelser i Silithus. I Gadgetzan söker en ingenjör efter det för att arbeta med en apparat som kan tala med de döda.",h="The Sealed Venom Container innehåller gift från giftiga varelser i Silithus.",kw={"kommunicera med de döda","gadgetzan","mux manascrambler","förseglad giftbehållare","silithus","övernaturlig apparat","gift"},sec={{t="Gift till Gadgetzan",b="Gift från Silithus förvaras i The Sealed Venom Container. Provet är avsett för en ingenjör i Gadgetzan som studerar det övernaturliga. Han bygger en apparat för att kommunicera med de döda, och giftet är betalning för hans arbete."}},faq={{q="Vad finns i The Sealed Venom Container?",a="The Sealed Venom Container innehåller gift som samlats in från giftiga varelser i Silithus.",al={"vad finns i giftbehållaren","giftbehållarens innehåll"}},{q="Vart ska behållaren?",a="Behållaren är avsedd för en ingenjör i Gadgetzan som arbetar med en apparat för att tala med de döda.",al={"vart lämna giftet","giftbehållarens destination"}},{q="Vem vill ha giftet?",a="Mux Manascrambler, en ingenjör i Gadgetzan med intresse för det övernaturliga, vill ha giftet.",al={"vem behöver behållaren","mux gift"}},{q="Varför behöver ingenjören gift?",a="Giftet är betalning för Mux Manascramblers arbete med en apparat som kan kommunicera med de döda.",al={"vad används giftet till","varför ge mux gift"}}},fp="22,171,19.233.0,38.86.0,28.102.0,20.98.0,33.97.0"}
P.entries["item:searing-collar"] = {n="Searing Collar",s="Vid Skull Rock i Durotar bär Burning Blades kultister brännande halsringar under sina riter. De upphettade ringarna bränner deras kött när kultisterna öppnar sig för demonisk kraft.",h="Vid Skull Rock i Durotar bär Burning Blades kultister brännande halsringar under sina riter.",kw={"burning blade","demon","durotar","ondskans magi","margoz","searing collar","skull rock"},ang={["class:Warlock"]="Som häxmästare kanske du känner igen brännande halsringar som grova ledare som kanaliserar avgrundsmagiens korruption in i dödligt kött.",["race:Orc"]="Som orc är det en dyster påminnelse om att skuggan av demoniskt slaveri fortfarande dröjer sig kvar att finna kultister som använder dessa halsringar vid Durotars tröskel."},sec={{t="Redskap för fördärv",b="Burning Blade samlas för mörka riter i Skull Rock, strax öster om Orgrimmar. Kultister, noviser och busar bär brännande halsringar runt halsen och uthärdar hettan som märker och sargar deras hud. Margoz, en eremit, studerar de grymma föremålen. Han misstänker att brännskadorna och förtrollningarna bundna till metallen öppnar bärarna för demoniska energier. Vilken roll spelar halsringarna i korruptionen som sprider sig genom orcsamhället under Hordens näsa?"}},faq={{q="Vad är en Searing Collar?",a="Burning Blades kultister bär brännande halsringar runt halsen under ritualer. Den upphettade metallen bränner deras kött och hjälper dem att öppna sig för demonisk kraft.",al={"vad är searing collars","searing collar-lore","vad gör halsringen"}},{q="Vilka bär halsringarna?",a="Medlemmar av Burning Blade som gömmer sig inne i Skull Rock bär halsringarna, däribland kultister, fanatiker, busar, lärlingar och noviser.",al={"vem använder dem","vem fäller searing collars","burning blade-halsringar"}},{q="Varför bränner kultisterna sin egen hud?",a="Burning Blade använder den brännande metallen i sina ritualer. Genom att uthärda brännskadorna och den demoniska förtrollningen öppnar kultisterna sina kroppar och sinnen för demonisk kraft.",al={"varför bränna sin hud","varför bära searing collar","halsringens syfte"}},{q="Vem vill undersöka Searing Collars?",a="Margoz, en utredare som slagit läger i Durotar, samlar in brännande halsringar för att studera deras förtrollningar och avslöja Burning Blades inflytande.",al={"vem behöver searing collars","vem studerar halsringarna","margoz halsringar"}}},fp="14,140,25.448.0,25.149.0,24.139.0,41.162.0,41.141.0"}
P.entries["item:searing-coral"] = {n="Searing Coral",s="Searing Coral är ett sällsynt, motståndskraftigt mineralämne som utvinns ur levande järnkoraller utanför Wetlands kust. Det uppskattas av uppfinnare och smeder och har anmärkningsvärda värmeegenskaper som gör att det kan smältas och smidas till skyddande rustning.",h="Searing Coral är ett sällsynt, motståndskraftigt mineralämne som utvinns ur levande järnkoraller utanför...",kw={"furen longbeard","järnkorall","ironforge","klockmort spannerspan","menethil harbor","searing coral","krigarrustning","wetlands"},ang={["class:Warrior"]="Att samla Searing Coral är ett avgörande steg för att bevisa ditt engagemang för Ironforges mästersmeder och få en skräddarsydd bröstplåt, utformad för att tåla hård strid vid frontlinjen.",["profession:Blacksmithing"]="Användningen av Searing Coral visar hur gnomisk uppfinningsrikedom kan förenas med klassiskt dvärgsmide och förvandla havsmineraler till härdad plåt."},sec={{t="En sällsynt kustresurs",b="Searing Coral växer endast i det kyliga havsvattnet längs kusten söder om Menethil Harbor i Wetlands. Trots att den trivs i kallt saltvatten ger denna unika havsorganism ett mineralrikt material som tål extrem värme. De som skördar den trotsar Wetlands förrädiska bränningar och kustens rovdjur för att bända loss de hårdnade formationerna."},{t="Användning i smide",b="Searing Coral hörde traditionellt inte hemma inom dvärgarnas metallurgi, men väckte nyfikna sinnen i Ironforge. Gnomiska hantverkare som Klockmort Spannerspan anpassar metoderna från den erfarne rustningssmeden Furen Longbeard och smälter och hamrar korallen direkt i metallegeringar för att skapa lätt rustning som är exceptionellt hållbar för blivande krigare."}},faq={{q="Var växer Searing Coral?",a="Searing Coral skördas från havsbotten längs strandlinjen söder om Menethil Harbor i Wetlands. Den växer i naturliga bestånd av järnkorall under det grunda kustvattnet.",al={"searing coral plats","var hittar man searing coral","järnkorall plats"}},{q="Vem vill ha Searing Coral i Ironforge?",a="Klockmort Spannerspan, en gnomisk konstruktör som bor i Tinkertown i Ironforge, söker efter Searing Coral. Han använder den för att experimentera med smidesmetoder som han lärt sig av den legendariske dvärgrustmästaren Furen Longbeard.",al={"vem använder searing coral","klockmort spannerspan korall","furen longbeard korall"}},{q="Hur kan korall smidas till rustning?",a="Searing Coral har en ovanligt tät och värmetålig struktur. När den smälts i en smedja och hamras in i metallegeringar förstärker den kompositplåten, vilket ger exceptionellt tålig skyddsutrustning.",al={"korallsmide","kan man smälta korall","searing coral metallurgi"}},{q="Är det farligt att skörda Searing Coral?",a="Korallen är ofarlig att samla in när du väl hittat den, men skörden kräver att du simmar genom det öppna vattnet utanför Wetlands kust, där vilda murlocer och aggressiva vattenlevande bestar strövar omkring.",al={"är searing coral het","skörda järnkorall"}}},fx={["3e3d13aa"]={q="Vad är Searing Coral?",a="Searing Coral är en sällsynt, mineralrik marin växt som tas från Iron Coral-formationer under vågorna längs Wetlands kust, söder om Menethil Harbor. Trots att den kommer från havet kan dess täta och ovanliga egenskaper göra att skickliga smeder smälter, hamrar och bearbetar den som metall.",al={"vad är searing coral","information om searing coral","searing coral bakgrund"}},["1c0d8f00"]={q="Varifrån kommer Searing Coral?",a="Searing Coral är en naturlig vattenväxt, inte ett tillverkat föremål. Den växer bara på en känd plats i världen: bland järnkorallbankarna under kustvattnen söder om Menethil Harbor i Wetlands.",al={"searing coral ursprung","varifrån kommer searing coral","vem skapade searing coral"}}},fp="13,170,23.267.0,23.290.0,30.115.0,37.187.0,35.198.0,38.167.0"}
P.entries["item:secure-crate"] = {n="Secure Crate",s="I The Barrens väntar en Secure Crate på en resenär som kan ta den till Ratchet. Inuti finns drycker och alkemiska varor på väg till Eastern Kingdoms.",h="I The Barrens väntar en Secure Crate på en resenär som kan ta den till Ratchet.",kw={"the barrens","blackwater cove","potions","ratchet","ingredienser","secure crate","frakt","wharfmaster dizzywig"},ang={["faction:Horde"]="Som resenär i Horde vet du att Ratchets neutrala hamn förbinder Kalimdor och Eastern Kingdoms genom goblinernas sjöfart.",["profession:Herbalism"]="Som örtmästare ser du hur alkemister och örtmästare på varsin sida om havet förlitar sig på handelsleder i gränslandet för att byta råvaror."},sec={{t="En kurirs last",b="Kurirer, karavaner och goblinskepp fraktar varor mellan Kalimdor och Eastern Kingdoms. När en karavan i The Barrens missar sin avgång tar resenärer med sig ömtålig last som den här Secure Crate ner till kusten. Den innehåller drycker, alkemiska varor och reagenser till kompanjoner på andra sidan Great Sea. Lådan är förseglad för att stå emot färden längs lederna i The Barrens och havsstänket under resan."},{t="Genom Ratchets hamn",b="Lådans färd över land slutar vid kajerna i Ratchet, där Wharfmaster Dizzywig ansvarar för frakten. Ratchet är en neutral hamn för varor som korsar havet, även last på väg till Blackwater Cove. Dizzywig arbetar efter Steamwheedle Cartels bokföring och registrerar paket och fraktgods innan han lastar dem på nästa avgående fartyg. Ratchet förbinder den gamla världen med gränslandet."}},faq={{q="Vad finns i Secure Crate?",a="Secure Crate innehåller drycker, alkemiska reagenser och andra förnödenheter till kompanjoner i Eastern Kingdoms.",al={"lådans innehåll","vad finns i lådan","föremål i secure crate"}},{q="Vart ska lådan skickas?",a="Ta den till Wharfmaster Dizzywig vid kajerna i Ratchet. Han bokar den på ett handelsfartyg på väg till Blackwater Cove i den gamla världen.",al={"lådans destination","vart ska secure crate"}},{q="Varför fick en äventyrare lådan i stället för en karavan?",a="Avsändaren hann inte ta sig till Ratchet i tid, och handelskaravanen hade redan gett sig av enligt tidtabellen. En anlitad kurir måste få lådan till kajerna innan tidvattnet vänder.",al={"varför har jag lådan","missad karavan"}},{q="Vem tar emot lådan i Ratchet?",a="Wharfmaster Dizzywig tar emot lådan vid kajerna i Ratchet och för in den i sin fraktjournal innan han lastar den på nästa fartyg som seglar med tidvattnet.",al={"vem får lådan","dizzywig och lådan"}}},fx={e5dd21c1={q="Vad är Secure Crate?",a="Secure Crate är en välpackad försändelse med en blandning av brygder, reagenser och andra värdefulla förnödenheter. Den är ordentligt emballerad så att det ömtåliga innehållet klarar en lång resa med karavan och fartyg över havet till Eastern Kingdoms.",al={"vad är secure crate","secure crate bakgrund","om secure crate"}},["4df2d75b"]={q="Varifrån kommer Secure Crate, och vem packade den?",a="Lådan kommer från The Barrens och har packats och förseglats av en alkemist eller lärd som behövde exportera sina alkemiska förnödenheter omgående. Eftersom personen missade den vanliga handelskaravanen och inte hade tid att själv resa till kusten, förbereddes lådan för att bäras direkt till hamnen i Ratchet.",al={"vem packade secure crate","varifrån kom secure crate","secure crate ursprung"}},b7ad6ca4={q="Varför vill någon ha Secure Crate?",a="Bundsförvanter i Eastern Kingdoms på andra sidan havet väntar på de här viktiga reagenserna och brygderna. Wharfmaster Dizzywig i Ratchet behöver få lådan levererad till sina kajer, så att han kan föra in den i sin handelsbok och stuva ombord den på nästa fartyg till Blackwater Cove.",al={"varför vill någon ha secure crate","vem behöver secure crate","varför vill dizzywig ha secure crate"}}},fp="12,139,17.376.0,27.382.0,32.111.0,30.151.0,62.163.0,31.158.0"}
P.entries["item:senir-s-report"] = {n="Senir's Report",s="Senir's Report är en avsänd rapport skriven av Mountaineer Senir Whitebeard, som beskriver hotet från Frostmane-trollen i Dun Morogh. Den innehåller iakttagelser som samlats in på kunglig befallning och ska till Senator Barin Redstone i Ironforge.",h="Senir's Report är en avsänd rapport skriven av Mountaineer Senir Whitebeard, som beskriver hotet från...",kw={"barin redstone","frostmane","ironforge","magni bronzebeard","senat","senir whitebeard","senir's report","rapporterna"},ang={["faction:Alliance"]="Att hantera Senir's Report bidrar till försvaret av Dun Morogh samtidigt som du måste navigera Ironforges styrande klass taggiga interna politik.",["race:Dwarf"]="När du bär Senir's Report får du se den skarpa politiska klyftan mellan King Magni Bronzebeards kungliga dekret och den traditionella auktoritet som senaten i Ironforge kräver."},sec={{t="En kunglig befallning",b="Den här fältrapporten skrevs efter spaningsuppdrag mot Frostmane-trollen, som håller till bland klipporna i Dun Morogh. Den innehåller bergsvakternas iakttagelser och är avsedd för dvärgarnas senat. Senir Whitebeard, som var posterad ute i de kalla förbergen, skrev dokumentet och bifogade sin bror Grelin's Report om Coldridge Valley. Där står det att Grelin agerade med tillstånd från King Magni Bronzebeard. Senir ber äventyrare att föra fynden direkt till Senator Barin Redstone i High Seat i Ironforge, och råder försiktigt budbärarna att utelämna hur mycket hjälp utifrån han behövde för att sammanställa rapporten."},{t="Spänningar i High Seat",b="När dokumentet når det kungliga hovet utlöser det omedelbart ett ramaskri. Senator Barin Redstone läser Whitebeards redogörelse och upprörs inte bara över hotet från trollen, utan också över den verkställande makt som åberopas. Att Magni går förbi den lagstiftande kontrollen och att Whitebeard följer kungliga order utan insyn väcker gammal bitterhet i dvärgarnas senat. Det visar den politiska spänningen mellan King Magni Bronzebeards beslutsamma styre och de upprörda senatorerna, som kräver kontroll över processen."}},faq={{q="Vad är Senir's Report?",a="Det är en officiell skriftlig rapport av Mountaineer Senir Whitebeard som sammanfattar hans undersökningar av Frostmane-trollen i Dun Morogh. Den ska överlämnas direkt till dvärgarnas senat i Ironforge.",al={"senirs rapport","vad är den här rapporten","rapporten"}},{q="Vem ska ta emot rapporten?",a="Rapporten är adresserad till Senator Barin Redstone, en butter dvärgpolitiker nära King Magni Bronzebeards tron i High Seat i Ironforge.",al={"vem får rapporten","vem ska jag ge rapporten till","rapportens mottagare"}},{q="Varför blir Senator Redstone så arg när han läser den?",a="Senator Redstone är rasande eftersom den bifogade rapporten från Senirs bror, Grelin Whitebeard, visar att Grelin agerade på uppdrag av King Magni i stället för att rådfråga dvärgarnas senat. Redstone ogillar att kronan agerar på egen hand i försvarsfrågor utan senatens godkännande.",al={"varför är barin arg","varför är senatorn arg","redstones reaktion"}},{q="Varför ber Senir dig att inte nämna att du hjälpte honom?",a="Senir Whitebeard vill att hans överordnade ska tro att han utförde det farliga spaningsarbetet i de snötäckta kullarna helt på egen hand. Han vill skydda sitt rykte som en flitig och duglig bergsvakt.",al={"varför hålla tyst","senirs hemlighet","senirs erkännande"}}},fx={["078e838e"]={q="Varifrån kommer Senir's Report, och vem skrev den?",a="Senir Whitebeard skrev själv rapporten i Dun Morogh efter att ha spanat på de lokala hoten från Frostmane-trollen och säkrat hjälp med att hantera Frostmane Hold. Förutom sina egna iakttagelser innehåller den hans bror Grelin's Report om Coldridge Valley, som Grelin skrev på uppdrag av King Magni Bronzebeard. Rapporten förmedlar båda deras redogörelser från den snöiga gränstrakten till huvudstadens stora salar.",al={"vem skrev senir's report","varifrån kommer senir's report","författaren till senir's report"}},e0c0da53={q="Varför vill någon ha Senir's Report?",a="Senator Barin Redstone och Ironforge-senaten behöver officiella fältrapporter för att följa utvecklingen i regionen och militära insatser i Dun Morogh. Men eftersom just den här rapporten hävdar att King Magni ensam har rätt att styra lokala militära insatser, väger den tungt politiskt. Den informerar senaten om kungliga beslut som de anser kringgår deras tillsyn.",al={"varför lämna in senir's report","varför behöver redstone senir's report","syftet med senir's report"}}},fp="14,133,17.399.0,25.430.1,23.143.0,38.131.0,56.253.1,50.210.0"}
P.entries["item:serena-s-head"] = {n="Serena's Head",s="I Dry Hills i norra The Barrens söker man efter Serena Bloodfeathers huvud som bevis på att hon är död. Darsok Swiftdagger tänker visa upp det på en Horde-försörjningsvagn som varning för fler harpyattacker.",h="I Dry Hills i norra The Barrens söker man efter Serena Bloodfeathers huvud som bevis på att hon är död.",kw={"the crossroads","darsok swiftdagger","the dry hills","harpy","rexxar","serena bloodfeather","serena's head","witchwing"},ang={["class:Rogue"]="Darsok Swiftdagger uppskattar rent och hänsynslöst arbete. Han lovordar legosoldater som smyger sig bakom fiendens utkiksplatser och dödar sitt mål utan att tveka.",["faction:Horde"]="Hordes karavaner förbinder Durotar med Mulgore och de avlägsna utposterna. Att visa upp Serenas huvud på en försörjningsvagn förkunnar Hordes herravälde över de vilda ödemarkerna."},sec={{t="En varning längs vägen",b="Serena Bloodfeather ledde Witchwing-harpierna i Dry Hills i attacker mot handeln genom norra The Barrens. Hennes angrepp på Hordes försörjningslinjer blev allt brutalare eftersom hennes syster hade fallit för bestmästaren Rexxar. Darsok Swiftdagger, en orcisk skurk, beordrade att Serena skulle jagas för att knäcka flockens moral. Han vill att hennes avhuggna huvud ska sättas upp på en karavan på väg därifrån, så att harpior som spanar från klipporna ser varningen."}},faq={{q="Varför vill Darsok Swiftdagger ha Serenas huvud?",a="Darsok vill ha bevis för att Serena Bloodfeather är död och planerar att sätta upp hennes huvud på en Horde-försörjningskaravan. Han hoppas att uppvisningen ska skrämma bort de Witchwing-harpior som överlevt från resenärer.",al={"varför ta serenas huvud","darsok serenas huvud","vad gör darsok med huvudet"}},{q="Varför angrep Serena Bloodfeather Horde-karavaner?",a="Serena Bloodfeather anföll Hordes karavaner för att hämnas sin syster, som halvojätten och mästaren Rexxar hade dödat. Hon slog till mot Hordes försörjningslinjer och vägfarare över hela The Barrens.",al={"varför angrep serena karavaner","serena bloodfeathers motiv","harpyangrepp the barrens"}},{q="Varifrån kommer den här trofén?",a="Trofén tas från Serena Bloodfeather, matriarken som håller till bland klipporna i Dry Hills, längst i nordvästra The Barrens.",al={"var hittar man serenas huvud","serena bloodfeathers plats","hur får man tag på serenas huvud"}}},fx={["29e11954"]={q="Vad är Serena's Head?",a="Serena's Head är det avhuggna huvudet från Serena Bloodfeather, den hämndlystna matriarken i harpyflocken Witchwing i norra The Barrens. När du tar det får hennes räder mot Crossroads försörjningsvägar ett slut, och det blir ett obestridligt bevis på att harpyhotet har slagits tillbaka vid själva källan.",al={"vad är serena's head","serena bloodfeathers huvud","föremålet serena's head"}}},fp="13,176,21.411.1,47.194.0,53.175.1,33.126.0"}
P.entries["item:serpentbloom"] = {n="Serpentbloom",s="Serpentbloom är en sällsynt underjordisk ört som bara växer i Wailing Caverns mörka djup. Dess kraftfulla naturliga egenskaper har väckt stort intresse hos Forsakens Royal Apothecary Society.",h="Serpentbloom är en sällsynt underjordisk ört som bara växer i Wailing Caverns mörka djup.",kw={"apothecary zamah","the barrens","ört","royal apothecary society","serpentbloom","thunder bluff","wailing caverns"},ang={["profession:Herbalism"]="Tränade örtmedicinare har den skarpa blick som krävs för att hitta dessa sällsynta grottblommor där andra bara ser fuktig sten.",["race:Undead"]="Genom att skaffa Serpentbloom hjälper du Apothecary Zamah och Royal Apothecary Society att söka efter växtresurser i främmande länder för att stärka Forsaken."},sec={{t="En sällsynt underjordisk växt",b="Serpentbloom växer endast i Wailing Caverns fuktiga, skuggiga gångar under The Barrens. Växten har sina rötter i ett ekosystem som förvridits av okontrollerade krafter från Emerald Dream och frodas långt från solljus. Giftiga ormar ligger ofta och ruvar bland stjälkarna. Grottsystemet är fullt av fientliga bestar och korrumperade druider, så få som vågar sig in återvänder med användbara exemplar."},{t="Apotekarnas intresse",b="Apothecary Zamah samlar in Serpentbloom på uppdrag av Royal Apothecary Society of Undercity från Pools of Vision under Thunder Bluff. Forsaken söker ständigt efter giftiga, märkliga och kemiskt kraftfulla växter runtom i Kalimdor för att främja sin forskning åt Dark Lady. Zamah tror att en omfattande skörd av Serpentbloom kan leda till värdefulla genombrott inom Forsakens alkemi."}},faq={{q="Var växer Serpentbloom?",a="Serpentbloom finns bara djupt inne i Wailing Caverns, ett vindlande grottsystem sydväst om The Crossroads i The Barrens. Den klamrar sig fast vid marken i grottans mörka, fuktiga skrymslen.",al={"var hittar man serpentbloom","serpentblooms plats","ört i wailing caverns"}},{q="Varför vill Royal Apothecary Society ha Serpentbloom?",a="Apothecary Zamah, en agent för Royal Apothecary Society som är stationerad i Thunder Bluff, söker växten för sin forskning. Forsaken undersöker ovanliga och farliga växter från hela Kalimdor för att utveckla nya kemiska blandningar och främja Sylvanas Windrunners övergripande mål.",al={"vem vill ha serpentbloom","apothecary zamahs ört","varför samla serpentbloom"}},{q="Varför är det farligt att skörda Serpentbloom?",a="Wailing Caverns är fulla av rovödlor, krokolisker och korrumperade druider, men även själva örten döljer ofta giftiga ormar. Om växten störs går de gömda ormarna ofta till anfall.",al={"serpentblooms faror","serpentbloom orm"}},{q="Kan örtkunniga hitta Serpentbloom lättare?",a="Ja. De som har tränat i örtmedicin är naturligt skickliga på att upptäcka växtlighet och kan spåra bestånd av Serpentbloom i grottans skuggiga hörn.",al={"hitta serpentbloom med örtmedicin","spåra serpentbloom"}}},fx={bee22cd2={q="Vad är Serpentbloom?",a="Serpentbloom är en ytterst sällsynt växt som hör hemma i de mörkaste delarna av Wailing Caverns i The Barrens. Den växer i fuktiga underjordiska djup och känns igen på sina ormlika egenskaper. Om du stör den lockar det ofta fram aggressiva ormar som ligger gömda bland rötterna.",al={"vad är serpentbloom","örten serpentbloom","information om serpentbloom"}}},fp="12,133,25.327.0,19.368.0,29.186.0,56.295.0,41.163.0,45.131.0"}
P.entries["item:sethir-s-journal"] = {n="Sethir's Journal",s="Sethir's Journal är en personlig anteckningsbok som den svårfångade satyren Sethir the Ancient bär med sig i Teldrassil. Den stjäls obemärkt och bekräftar att fördärvet från Kalimdors fastland sprider sig till Världsträdet.",h="Sethir's Journal är en personlig anteckningsbok som den svårfångade satyren Sethir the Ancient bär med sig i...",kw={"darkshore","ödet kallar","the oracle glade","satyr","sethir the ancient","sethir's journal","syurna","teldrassil"},ang={["class:Rogue"]="Att hämta journalen visar att smygande infiltration och fickstöld kan avslöja avgörande information där frontsoldater och diplomater misslyckades fullständigt.",["race:NightElf"]="Journalen ger oroande bevis för att Teldrassil inte är immunt mot det uråldriga demoniska fördärv som sprider sig över Kalimdors fastland."},sec={{t="En ledtråd om smittan",b="Teldrassil restes i hopp om att återvinna alvernas odödlighet, men en osynlig sjukdom har fått allt större fäste bland dess grenar. Syurna i Darnassus misstänkte att Sethir the Ancient, en ensam satyr som lurade på en avlägsen gren nära The Oracle Glade, hade svaren. Tidigare spejare hade bara mötts av döden när de försökte förhandla direkt eller använda öppet våld, så en försiktig fickstöld gav till slut Sethirs journal. Anteckningarna avslöjar en dyster sanning: den mystiska farsot som förgiftar skogarna och vattnen på andra sidan havet i Darkshore har nått ända in i Teldrassil."}},faq={{q="Vad är Sethir's Journal?",a="Det är en journal som Sethir the Ancient bär med sig. Han är en fientlig satyr som håller till bland de yttre grenarna nära The Oracle Glade i Teldrassil. Den innehåller anteckningar om det fördärv som sprider sig i området.",al={"vad är sethirs journal","sethirs journals bakgrund","vem äger sethirs journal"}},{q="Hur får man tag på journalen?",a="Eftersom tidigare försök att förhandla med eller strida mot Sethir slutade i misslyckande och död måste journalen stjälas direkt ur hans packning med hjälp av smygande.",al={"hur får jag tag på sethirs journal","var får man tag på sethirs journal","stjäla från sethir"}},{q="Vad avslöjar journalen?",a="Enligt skurkarnas tränare Syurna bevisar journalen att den märkliga sjukdom som härjar i Darkshores skogar och vatten har spridit sig till Teldrassil.",al={"vad står det i sethirs journal","vad finns i sethirs journal"}},{q="Vem är Sethir the Ancient?",a="Sethir är en ensam satyr som håller till på en avskild gren i utkanten av The Oracle Glade. Han är känd för att våldsamt ge sig på inkräktare och har viktig information om fördärvet som sprider sig i Världsträdet.",al={"vem är sethir","sethir the ancient"}}},fx={["3d18c972"]={q="Varifrån kommer Sethir's Journal, och vem skrev den?",a="Dagboken tillhör Sethir the Ancient, en fientlig satyr som lurar på en hög trädgren i utkanten av The Oracle Glade i Teldrassil. Han bar med sig sina personliga anteckningar och andra handlingar och behöll dagboken tills skurkar i Darnassus försökte stjäla den i smyg. De ville ta reda på vilken korruption som sprider sig över världsträdet.",al={"vem skrev sethir's journal","sethir's journals ursprung","ursprunget till sethir's journal"}}},fp="16,144,19.475.1,25.171.0,28.130.0,29.130.0,26.207.0"}
P.entries["item:sevren-s-orders"] = {n="Sevren's Orders",s="Sevren's Orders är skriftliga order från Magistrate Sevren i Brill. De beordrar en beprövad Forsaken-agent att rapportera till Bethor Iceshard, en mäktig magiker stationerad i Undercitys Magic Quarter.",h="Sevren's Orders är skriftliga order från Magistrate Sevren i Brill.",kw={"bethor iceshard","brill","magic quarter","magistrate sevren","förlupen lich","sevren's orders","undercity"},ang={["class:Mage"]="För utövare av arkana konster ger leveransen av orderna en audiens hos Bethor Iceshard, en av de främsta besvärjarna i Forsaken-riket.",["race:Undead"]="Att bära Sevren's sigill markerar en agents övergång från lokal tjänst i Tirisfal till att direkt bistå Undercitys arkana elit."},sec={{t="Kallelse till huvudstaden",b="När Forsaken befäster sitt grepp om Ruins of Lordaeron kallas skickliga agenter som visat sitt värde mot Scourge i Tirisfal Glades söderut till huvudstaden. Magistrate Sevren har utfärdat de skriftliga orderna som en officiell introduktion och fullmakt för Bethor Iceshard, en av Dark Ladys främsta utövare av arkana konster i Magic Quarter. Sevren vet inte mycket mer än att uppdraget innebär att ta kontakt med en förlupen lich, men kallelsen bär Undercitys ärkemagikers fulla auktoritet."}},faq={{q="Vem skrev orderna?",a="Magistrate Sevren, Forsaken-förvaltaren som sköter stadens angelägenheter i Brill i Tirisfal Glades, skrev orderna.",al={"författaren till sevren's orders","vem är sevren","vem utfärdar sevren's orders"}},{q="Vem ska ta emot orderna?",a="De är adresserade till Bethor Iceshard, en högt uppsatt Forsaken-magiker i Undercitys Magic Quarter.",al={"vem får orderna","var ska jag lämna sevren's orders","vem är bethor iceshard"}},{q="Vilket uppdrag nämns i orderna?",a="Uppdraget går ut på att rekrytera en vilsekommen lich som kan hjälpa Forsaken. Det är ett farligt uppdrag som kräver en agent som redan visat sig kunna hantera Scourge.",al={"vad är lich-uppdraget","vad vill bethor","uppdraget med den förlupna lich"}},{q="Varför valdes jag att leverera dem?",a="Bethor bad om en operativ som bevisat sin förmåga mot Scourge. Magistrate Sevren ansåg att dina insatser i Tirisfal Glades räckte för att du skulle klara Bethors farliga uppdrag.",al={"varför jag","varför valde sevren mig"}}},fx={["59d8f724"]={q="Vad är Sevren's Orders?",a="Sevren's Orders är en officiell skrivelse från Magistrate Sevren i Brill. Den fungerar som formell fullmakt och visar att du är en beprövad agent som har kämpat effektivt mot Scourge och är redo för ett känsligt uppdrag.",al={"vad är sevrens order","föremålet sevren's orders","vad är det här för dokument"}},["680dc8a1"]={q="Varför vill Bethor Iceshard ha Sevren's Orders?",a="Bethor Iceshard, en framstående magiker i Undercitys Magic Quarter, krävde att Sevren skulle skicka en agent som kunde hantera ett farligt uppdrag med en förrädisk lich. När du visar upp ordern bevisar du att du är Sevren's utvalda agent och att det är befogat att ingripa mot den mäktiga magikern.",al={"varför lämna in sevren's orders","varför vill bethor ha ordern","vem behöver sevren's orders"}}},fp="15,150,22.460.0,23.76.0,40.107.0,44.139.0,33.157.0"}
P.entries["item:shackle-key-stranglethorn-vale"] = {n="Shackle Key",s="Shackle Key finns hos King Mukla på Jaguero Isle. Princess Poobah behöver den för att fly från fångenskapen.",h="Shackle Key finns hos King Mukla på Jaguero Isle.",kw={"fångenskap","jaguero isle","king mukla","princess poobah","boja","shackle key","stranglethorn vale"},sec={{t="En fången prinsessa",b="Princess Poobah är fastkedjad på Jaguero Isle, där King Mukla håller henne kvar mot hennes vilja. Nyckeln till hennes boja är vägen till frihet, och hon ber om hjälp från alla som vågar möta den mäktige Skymane-kungen."}},faq={{q="Vad låser Shackle Key upp?",a="Shackle Key låser upp bojan som håller Princess Poobah fången på Jaguero Isle.",al={"vad är nyckeln till för","vad låser nyckeln upp"}},{q="Vem har Shackle Key?",a="King Mukla har Shackle Key på Jaguero Isle.",al={"vem har nyckeln","muklas nyckel"}},{q="Var hålls Princess Poobah fången?",a="Princess Poobah hålls fången på Jaguero Isle i Stranglethorn Vale.",al={"var är poobah","poobah fången"}},{q="Varför behöver Princess Poobah nyckeln?",a="Princess Poobah behöver Shackle Key för att befria sig från kedjan som håller henne fången.",al={"varför behövs nyckeln","befria poobah"}}},fp="11,104,18.208.0,31.82.0,24.47.0,30.62.0,38.89.0"}
P.entries["item:shackle-key-the-hinterlands"] = {n="Shackle Key",s="Shackle Key hålls av Hitah'ya the Keeper i en grotta nära Jintha'alor. Elder Torntusk behöver den för att lossa sina bojor och återvända hem.",h="Shackle Key hålls av Hitah'ya the Keeper i en grotta nära Jintha'alor.",kw={"bojor","elder torntusk","the hinterlands","hitah'ya the keeper","jintha'alor","shackle key"},sec={{t="Den fjättrade äldsten",b="Vid Jintha'alor i The Hinterlands väntar Elder Torntusk på nyckeln till sina bojor. Hitah'ya the Keeper håller den i en närliggande grotta och är välbevakad. Ta tillbaka nyckeln till Torntusk så att han kan befrias och återvända hem."}},faq={{q="Vem har Shackle Key?",a="Hitah'ya the Keeper håller Shackle Key i en grotta nära Jintha'alor.",al={"vem har nyckeln","nyckelns innehavare","hitahya nyckel"}},{q="Vad är Shackle Key till för?",a="Shackle Key lossar Elder Torntusks bojor så att han kan återvända hem.",al={"vad nyckeln gör","nyckelns syfte","torntusk nyckel"}},{q="Var finns nyckeln?",a="Hitah'ya the Keeper håller nyckeln i en grotta nära Jintha'alor i The Hinterlands.",al={"nyckelns plats","var nyckeln finns","närliggande grotta"}},{q="Vem behöver nyckeln?",a="Elder Torntusk vid Jintha'alor behöver nyckeln för att befria sig från sina bojor.",al={"vem vill ha nyckeln","vem behöver den","elder torntusk"}}},fp="11,138,15.218.0,24.69.0,28.72.0,17.80.0,18.78.0"}
P.entries["item:shadow-hunter-knife"] = {n="Shadow Hunter Knife",s="Shadow Hunter Knife är ett Witherbark-trollblad som Apprentice Kryten söker efter vid Refuge Pointe. Det hör ihop med stammens skuggjägares riter.",h="Shadow Hunter Knife är ett Witherbark-trollblad som Apprentice Kryten söker efter vid Refuge Pointe.",kw={"archmage malin","kryten","refuge pointe","övergångsriter","shadow hunter knife","troll","witherbark"},ang={["faction:Alliance"]="Som Alliance-resenär bidrar Krytens arbete vid Refuge Pointe till Archmage Malins forskning i Arathi."},sec={{t="Ett trollblad",b="Apprentice Kryten söker efter Shadow Hunter Knife vid Refuge Pointe för Archmage Malins forskning. Han säger att de starkaste Witherbark-skuggjägarna får det särskilda bladet när de har fullbordat sina övergångsriter. Deras by ligger sydost om Arathi, och Kryten kan inte avgöra vilken jägare som bär ett förrän striden är över."}},faq={{q="Vem vill ha Shadow Hunter Knife?",a="Apprentice Kryten vid Refuge Pointe söker efter Shadow Hunter Knife för Archmage Malins forskning.",al={"vem behöver kniven","kryten kniv","vem vill ha den"}},{q="Vem bär Shadow Hunter Knife?",a="De starkaste Witherbark-skuggjägarna kan bära den särskilda kniven som ges efter deras övergångsriter.",al={"vem har kniven","vilket troll har den","skuggjägarblad"}},{q="Varför är kniven speciell?",a="Kryten säger att Witherbark ger kniven till sina starkaste skuggjägare när de har fullbordat sina övergångsriter.",al={"varför särskild kniv","trollkniv betydelse","vad är speciellt med den"}},{q="Var bor Witherbark?",a="Witherbark bor sydost om Arathi, nära Witherbark Village.",al={"var finns witherbark","trollby plats","withbark var"}}},fp="19,154,15.328.0,34.97.0,36.103.0,25.119.0,29.65.0"}
P.entries["item:shadowhide-pendant"] = {n="Shadowhide Pendant",s="Shadowhide Pendants är grovt tillverkade prydnadssmycken som bärs av Shadowhide-kobolderna som strövar omkring i Redridge Mountains. De samlas in som lagligt bevis på att belöningen verkställts och visar att lokala försvarare har upprätthållit Lakeshires lag mot kobolder som samarbetar med den avfällige magikern Morganth.",h="Shadowhide Pendants är grovt tillverkade prydnadssmycken som bärs av Shadowhide-kobolderna som strövar...",kw={"bailiff conacher","kobold","lakeshire","lieutenant fangore","morganth","hänge","redridge","shadowhide","solomons lag"},ang={["class:Warrior"]="Shadowhide-kobolderna är aggressiva och fysiskt imponerande motståndare vars styrka sätter frontförsvararna på prov när de skyddar vägarna till Lakeshire.",["faction:Alliance"]="Gränsbosättningar som Lakeshire får knapphändig hjälp från Stormwinds garnison, så de lokala magistraterna måste förlita sig på lojala äventyrare från Alliansen för att upprätthålla rikets lagar."},sec={{t="Trotsens tecken",b="Dessa hängen bärs av krigare, bestar och trollkarlar i Shadowhide-klanen och fungerar som enkla personliga totem eller rangtecken. Djupt inne i Redridges kullar har klanen samlats under Lieutenant Fangore och hamnat under Morganths inflytande, en avfällig utövare av den arkana magin. För invånarna i Lakeshire är smyckena inte bara primitiva prydnader; de är kännetecken på ett organiserat hot som trakasserar bosättningar i hela regionen på kronans fiendes vägnar."},{t="Lakeshires rättvisa",b="Enligt Magistrate Solomons befogenhet och Stormwinds lagar straffas den som aktivt hjälper en känd brottsling i riket med döden. Eftersom det saknas tillräckligt med kungliga förstärkningar förlitar sig Bailiff Conacher i Lakeshire Town Hall på oberoende äventyrare för att upprätthålla freden. Om du lämnar in tio Shadowhide Pendants får du konkret bevis på att kobolder som lyder Morganths order har fått möta gränsbygdens rättvisa."}},faq={{q="Vad är en Shadowhide Pendant?",a="Det är ett smycke som bärs av medlemmar i Shadowhide-koboldklanen i Redridge Mountains. Den lokala magistraten godtar dem som bevis på att invaderande kobolder har dödats till försvar för samhället.",al={"vad är shadowhide pendants","shadowhide pendant – bakgrund","redridge-hänge"}},{q="Varför vill Bailiff Conacher ha dessa hängen?",a="Bailiff Conacher samlar in dem som bevis på att belöningen enligt Solomons lag har verkställts. Eftersom Shadowhide-klanen samarbetar med renegaten och trollkarlen Morganth för att terrorisera lokalbefolkningen betraktar staden varje kobold med anknytning till klanen som en fiende som kan dömas till döden.",al={"varför samla in hängen","bailiff conachers belöning","conachers uppdrag"}},{q="Vem bär dessa hängen?",a="De bärs av kobolder på alla nivåer inom Shadowhide-klanen, från vanliga stråtrövare, bestar och rabiata kobolder till gestalter som Rohh the Silent och Lieutenant Fangore i Redridge-vildmarken.",al={"vem släpper hängen","vilka kobolder har hängen","shadowhide pendant – källa"}},{q="Hur hänger Shadowhide-klanen och Morganth ihop?",a="Morganth, en avfällig utövare av den arkana magin som håller till i de östra fotkullarna, har använt sina lömska krafter för att kuva Shadowhide-kobolderna och göra dem till fotsoldater som terroriserar Lakeshire och genomdriver hans planer.",al={"kobolder och morganth","varför arbetar kobolder med morganth","shadowhide och morganth"}}},fp="18,127,18.341.0,19.340.0,29.212.0,46.256.0,27.145.0,66.218.0"}
P.entries["item:shadowmaw-claw"] = {n="Shadowmaw Claw",s="En Shadowmaw Claw kommer från en panter i Stranglethorn Vale. Far Seer Mok'thardin behöver klorna till en förtrollning för Horde.",h="En Shadowmaw Claw kommer från en panter i Stranglethorn Vale.",kw={"elder shadowmaw panther","grom'gol base camp","mok'thardin","mok'thardins förtrollning","pristine tigress fang","shadowmaw claw","shadowmaw panther","stranglethorn vale"},ang={["faction:Horde"]="Mok'thardin söker klorna för att tämja djungelns magi till en särskild förtrollning för Horde."},sec={{t="Panterklor",b="På andra sidan floden från Mizjah Ruins jagar Shadowmaw Panthers och Elder Shadowmaw Panthers i djungeln. Far Seer Mok'thardin vid Grom'gol Base Camp söker deras klor och en Pristine Tigress Fang till sin förtrollning. Han tror att djungelns magi kan tämjas för Horde."}},faq={{q="Var kommer Shadowmaw Claws från?",a="Shadowmaw Panthers och Elder Shadowmaw Panthers i Stranglethorn Vale har dessa klor.",al={"källa till shadowmaw claw","panterklo","var finns klon"}},{q="Vem vill ha Shadowmaw Claws?",a="Far Seer Mok'thardin vid Grom'gol Base Camp söker åtta Shadowmaw Claws och en Pristine Tigress Fang.",al={"vem behöver klor","mokthardin klor","klor till vem"}},{q="Varför behöver Mok'thardin klorna?",a="Mok'thardin behöver Shadowmaw Claws och en Pristine Tigress Fang till en förtrollning som han tänker skapa för Horde.",al={"varför klor","mokthardins förtrollning","vad till"}},{q="Var finns pantrarna?",a="Mok'thardin säger att Shadowmaw Panthers lurar på andra sidan floden från Mizjah Ruins, åt sydost.",al={"shadowmaw plats","pantrar nära gromgol","var finns pantrarna"}}},fp="14,137,13.273.0,35.87.0,26.99.0,36.112.0,23.94.0"}
P.entries["item:shadowstalker-scalp"] = {n="Shadowstalker Scalp"}
P.entries["item:shadra-s-venom"] = {n="Shadra's Venom",s="Shadra's Venom hämtas från spindelguden i The Hinterlands. Apothecary Lydon i Tarren Mill behöver det efter att Shadra har tillkallats.",h="Shadra's Venom hämtas från spindelguden i The Hinterlands.",kw={"apothecary lydon","gadrins pergament","hinterlands","shadra","shadra'alor","shadras gift","spindelgud","tarren mill"},sec={{t="Gift till Lydon",b="Vid Shadra'Alor i The Hinterlands kallar pergamentet Shadra från hennes lya. Hennes gift förs till Apothecary Lydon i Tarren Mill, som väntar på det."}},faq={{q="Vad är Shadra's Venom?",a="Shadra's Venom tas från Shadra, spindelguden i The Hinterlands.",al={"shadras gift","vilket gift"}},{q="Vem behöver Shadra's Venom?",a="Apothecary Lydon i Tarren Mill ber dig ta med Shadra's Venom till honom.",al={"vem vill ha giftet","lydons gift"}},{q="Var får du tag på Shadra's Venom?",a="Shadra's Venom kommer från Shadra vid altaret i Shadra'Alor i The Hinterlands.",al={"var finns giftet","hitta shadras gift"}},{q="Hur tillkallas Shadra?",a="Läs Gadrin's Parchment vid altaret i Shadra'Alor, djupt inne i Witherbark realm i The Hinterlands.",al={"tillkalla shadra","shadras altare"}}},fp="14,130,15.151.0,23.71.0,25.72.0,32.80.0,23.105.0"}
P.entries["item:shaman-voodoo-charm"] = {n="Shaman Voodoo Charm",s="Shaman Voodoo Charm är en mörk ritualamulett som bärs av Gnarlpine furbolg-schamaner djupt inne i Ban'ethil Barrow Den. Amuletten utstrålar en vidrig aura och kanaliserar en onaturlig magi som kan skilja en sovande druids ande från dess kropp.",h="Shaman Voodoo Charm är en mörk ritualamulett som bärs av Gnarlpine furbolg-schamaner djupt inne i Ban'ethil...",kw={"ban'ethil barrow den","emerald dream","furbolg","gnarlpine","oben rageclaw","shaman voodoo charm","sovande druid","teldrassil"},ang={["class:Druid"]="För en druid är amuletten en fasansfull förvrängning av den heliga sömnen. Mörk magi fångar drömmaren i The Emerald Dream och styr samtidigt kroppen som en marionett.",["race:NightElf"]="Upptäckten av dessa amuletter i Ban'ethil Barrow Den visar hur djupt Gnarlpine har skändat en av kaldoreiernas heligaste gemensamma viloplatser."},sec={{t="Förvriden magi",b="Gnarlpine-stammen på Teldrassil har fallit i vansinne och fördärv, men i Ban'ethil Barrow Den utövar deras schamaner krafter långt bortom vanlig vildmarksmagi. Med dessa märkliga voodooamulett­er upptäckte schamanerna ett sätt att slita en sovande druids medvetande från den dödliga världen och fånga det hjälplöst i The Emerald Dream. Genom att skilja själen från kroppen kan furbolgerna ge liv åt den tomma kroppen och förvandla vördnadsvärda Night Elf-beskyddare till tanklösa väktare som slaktar alla som tar sig in i gravhögarna."},{t="Att lösa förbannelsen",b="När druiden Oben Rageclaw föll offer för ritualen blev hans ande fångad i The Emerald Dream, medan hans besjälade kropp terroriserade de djupa gravhögarna. Oben nådde genom slöjan och gav äventyrarna i uppdrag att döda Gnarpine-schamanerna och hämta en av deras voodooamuletter. Genom att undersöka den vidriga förtrollningen i amuletten hoppades Oben kunna tyda furbolgernas förvridna hantverk och hitta ett sätt att bryta bandet till hans stulna kropp."}},faq={{q="Vad används Shaman Voodoo Charm till?",a="Gnarlpine-schamaner använder amuletten i en kraftfull ritual som skiljer en sovande druids ande från kroppen. Sinnet fångas i The Emerald Dream, medan den tomma kroppen får liv och anfaller inkräktare.",al={"voodooamulettens syfte","vad gör amuletten","schamanamulett användning"}},{q="Vem bär dessa amuletter?",a="Amuletterna bärs av Gnarlpine-schamaner i de slingrande djupen av Ban'ethil Barrow Den på Teldrassil.",al={"vem släpper amuletten","var hittar man shaman voodoo charm","gnarlpine-schamanamulett"}},{q="Varför behöver Oben Rageclaw en?",a="Oben Rageclaw är just nu fångad i The Emerald Dream medan hans besjälade kropp härjar fritt. Han behöver undersöka amulettens vidriga aura och magiska väv för att komma på hur furbolgernas förtrollning kan brytas.",al={"varför vill oben ha den","oben rageclaw-amulett","föremålet för den sovande druiden"}},{q="Varför använder furbolger voodoomagi?",a="Traditionella furbolg-schamaner vördar naturandar och elementen, men fördärvet som plågar Teldrassil har drivit Gnarlpine att utöva mörk och förvriden magi. Amuletten har en onaturlig, vidrig aura som skiljer sig helt från traditionell naturdyrkan.",al={"varför använder furbolger voodoo","furbolgers voodoolore"}}},fx={["6bf5e1a6"]={q="Vad är Shaman Voodoo Charm?",a="Det är en förtrollad furbolg-amulett som används av korrumperade Gnarlpine-schamaner i Ban'ethil Barrow Den. Amuletten utstrålar en vidrig magisk aura och bär på mörka ritualer som kan skilja en sovande nattalvdruids ande från hennes kropp. Då blir anden hjälplös medan furbolgerna väcker kroppen och tar kontroll över den.",al={"vad är shaman voodoo charm","berättelsen om voodoo charm","vad är det här för amuletter"}}},fp="19,134,17.393.0,20.378.1,41.170.0,25.89.0,32.180.0,34.204.0"}
P.entries["item:shard-of-water"] = {n="Shard of Water",s="Längs The Barrens kust tar Islen Waterseer emot Shard of Water från en schaman som har mött korruption.",h="Längs The Barrens kust tar Islen Waterseer emot Shard of Water från en schaman som har mött korruption.",kw={"the barrens","call of water","islen waterseer","shard of water","silverpine","water totem"},ang={["class:Shaman"]="Som schaman fullbordar du din samklang med vattnets andar och den långa färden mot att få en Water Totem när du skaffar skärvan."},sec={{t="Tecken på elementär renhet",b="Schamaner måste förstå balans, liv och bevarande för att bemästra vatten. Under Call of Water färdas de till fördärvade källor och korsar till och med havet till det härjade Silverpine Forest. Efter att ha renat de besmittade vattnen får en schaman Shard of Water. När kristalltoken återlämnas till Islen Waterseer på The Barrens klippiga strand bevisar det den blivande schamanens värde och ger den sista nyckeln till att skapa en Water Totem."}},faq={{q="Vad används Shard of Water till?",a="Du tar skärvan till Islen Waterseer på The Barrens östra kust som bevis på din prövning. När du överlämnar den fullbordas din förbindelse med vatten och du får en Water Totem.",al={"vad shard of water används till","vad shard of water gör","varför jag har shard of water"}},{q="Vem behöver det här föremålet?",a="Islen Waterseer, en schaman i en hydda söder om Ratchet längs The Merchant Coast, ber om skärvan för att bekräfta att du har renat besmittat vatten.",al={"vem vill ha shard of water","var lämna in shard of water","islen waterseer shard"}},{q="Varför ägde prövningen rum så långt bort som i Silverpine?",a="Vatten står för läkande och bevarande, medan korruption hejdar livet. Silverpines besmittade vatten prövar om du kan återställa elementär harmoni mitt i ett djupt förfall.",al={"silverpine vattenuppdrag","varför silverpine forest","schaman silverpine"}}},fx={aaf07767={q="Vad är Shard of Water?",a="Shard of Water är en helig elementarisk skärva som ges till schamaner som genomgår vattnets prövningar. Den är ett konkret bevis på att du har utfört ritualen för att rena förorenat vatten och förstått vattnets sanna natur som livets givare och beskyddare.",al={"vad är shard of water","föremålet shard of water","vad är det här för skärva"}},["47314211"]={q="Varifrån kommer Shard of Water, och vem skapade den?",a="Du får skärvan i slutet av din andliga resa i Silverpine Forest, när du har fullbordat ritualen för att rena regionens förorenade vatten. Den förkroppsligar den rena vattnets elementarkraft som väcktes genom ritualen.",al={"var får man shard of water","vem ger shard of water","ursprunget till shard of water"}}},fp="14,108,25.403.0,36.165.0,23.141.0,48.163.0"}
P.entries["item:sharpbeak-s-feather"] = {n="Sharpbeak's Feather",s="Sharpbeaks fjäder bär spår av den unga gripen som söks i The Hinterlands. Thadius Grimshade hoppas att dess band till Sharpbeak ska låta hans spådomsmagi hitta honom.",h="Sharpbeaks fjäder bär spår av den unga gripen som söks i The Hinterlands.",kw={"aerie peak","spådom","grip","sharpbeak","sharpbeaks fjäder","thadius grimshade","wildhammer"},ang={["race:Dwarf"]="Som dvärg berör sökandet efter Sharpbeak Wildhammerfolket: Thadius Grimshade lämnade Aerie Peak, men har fortfarande Wildhammerhjärta."},sec={{t="En gripfjäder",b="I Nethergarde Keep ber Thadius Grimshade om en fjäder från boet där Sharpbeak sover. Spåmannen lämnade Aerie Peak för flera år sedan för att söka mörkare kunskap, men i hjärtat är han fortfarande Wildhammer. Han tror att fjädern kan hjälpa honom att hitta den unga gripen."},{t="Ett löftestecken",b="Thadius känner igen fjädern som tillhörande en fin grip. Han tror att Sharpbeak är ämnad för stordåd, om han överlever till vuxen ålder utan att skadas. Med fjädern i handen ber han dig lyssna noga medan han börjar spå gripens vistelseort."}},faq={{q="Vad används Sharpbeak's Feather till?",a="Thadius Grimshade använder Sharpbeak's Feather som en länk för att spå den unga gripens vistelseort.",al={"sharpbeak-fjäder","vad fjädern används till","fjäderns användning"}},{q="Varifrån kommer fjädern?",a="Fjädern togs från boet där gripungen Sharpbeak sover.",al={"sharpbeak-fjäderns ursprung","varifrån fjädern kommer","gripfjäder från bo"}},{q="Vem är Thadius Grimshade?",a="Thadius Grimshade är en Wildhammer-spåman som lämnade Aerie Peak för flera år sedan för att söka mörkare kunskap. Du hittar honom i magitornet i Nethergarde Keep i Blasted Lands.",al={"thadius bakgrund","vem är thadius","grimshade"}},{q="Vad tycker Thadius om Sharpbeak?",a="Thadius kallar Sharpbeak en fin grip, ämnad för stordåd om han överlever till vuxen ålder utan skador.",al={"sharpbeaks öde","vad thadius tycker","gripunge"}}},fp="19,167,19.271.0,17.259.0,32.98.0,32.77.0,25.170.0,37.104.0"}
P.entries["item:shaw-s-report"] = {n="Shaw's Report",s="I Westfall förmedlar Shaw's Report hemliga underrättelser från SI:7 till Gryan Stoutmantle. Den är skriven av Master Mathias Shaw och beskriver Stonemasons Guild, Edwin VanCleef och deras missnöje med kronan efter återuppbyggnaden av Stormwind.",h="I Westfall förmedlar Shaw's Report hemliga underrättelser från SI:7 till Gryan Stoutmantle.",kw={"defias","edwin vancleef","gryan stoutmantle","mathias shaw","shaw's report","si:7","stonemasons guild","westfall"},ang={["class:Rogue"]="Shaw's Report visar vilken räckvidd och vilka metoder Master Mathias Shaw, ledare för SI:7 och Stormwinds spionnätverk, har.",["faction:Alliance"]="Rapporten blottlägger Stormwinds inre förfall: en obetald skuld till rikets arkitekter bidrog till att utlösa ett uppror som hotar rikets jordbruksmarker."},sec={{t="Underrättelser om Stonemasons",b="Shaw's Report når Sentinel Hill från SI:7:s hemliga högkvarter i Stormwind. Rapporten ger People's Militia sin första tydliga redogörelse för vem som leder banditerna som härjar i Westfall. Under Edwin VanCleefs ledning byggde Stonemasons Guild omsorgsfullt upp Stormwind City efter dess förstörelse i det första kriget. När kronan och adeln vägrade att betala stenhuggarna skäligt för deras arbete slog missnöjet rot. Shaws underrättelser knyter de fördrivna hantverkarna till det kriminella uppror som nu tar över rikets utkanter."}},faq={{q="Vad är Shaw's Report?",a="Shaw's Report är en förseglad underrättelserapport sammanställd av Master Mathias Shaw, ledare för Stormwinds hemliga SI:7-byrå, åt Gryan Stoutmantle. Den innehåller kronans underrättelser om Stonemasons Guild och Edwin VanCleefs historia.",al={"shaw's report","vad skriver shaw","innehållet i shaw's report"}},{q="Vad avslöjar rapporten om Edwin VanCleef?",a="Rapporten pekar ut Edwin VanCleef som Stonemasons Guilds tidigare ledare, som övervakade återuppbyggnaden av Stormwind efter det första kriget. Där står att han och hans hantverkare gjorde uppror efter att rikets härskare nekat dem skälig betalning.",al={"vancleef i rapporten","vad står det om vancleef"}},{q="Varför behöver Gryan Stoutmantle rapporten?",a="Gryan Stoutmantle behöver rapporten eftersom han leder People's Militia mot samordnade banditanfall i Westfall. Utan hjälp från rikets reguljära trupper förlitar han sig på Mathias Shaws underrättelser för att ta reda på vem som styr laglösa och vad som driver dem.",al={"varför skickas rapporten till gryan","varför behöver stoutmantle rapporten"}},{q="Hur reagerar Stoutmantle på rapporten?",a="Rapporten gör Gryan Stoutmantle djupt oroad. Han minns Edwin VanCleef som en flitig och skicklig hantverkare och har svårt att tro att en så respekterad byggmästare blev en skurk utan ytterligare bevis.",al={"gryans reaktion","stoutmantles reaktion"}}},fx={c86c6e50={q="Varifrån kommer Shaw's Report, och vem skrev den?",a="Rapporten skrevs av Master Mathias Shaw, chefen för Stormwinds underrättelsetjänst SI:7. Från sitt högkvarter i Old Town sammanställde Shaw SI:7:s insamlade uppgifter om Stonemasons Guilds historia och Edwin VanCleef, för att skicka dem till Gryan Stoutmantle i Sentinel Hill.",al={"vem skrev shaw's report","vem skapade shaw's report","varifrån kommer shaw's report"}}},fp="13,221,31.491.1,22.250.0,49.224.0,44.254.0,41.211.0"}
P.entries["item:shay-s-bell"] = {n="Shay's Bell",s="Shay’s Bell är en kär ägodel som förvaras i en kista i Feralas. Shay Leafrunner säger att ljudet kan kalla henne tillbaka när hon vandrar bort.",h="Shay’s Bell är en kär ägodel som förvaras i en kista i Feralas.",kw={"feralas","rockbiter","shay","shay leafrunner","shay’s bell","shay’s chest","shay vandrar bort"},sec={{t="Ett välbekant ljud",b="Shay Leafrunner förvarar sin klocka i en kista i Feralas. Hon älskar ljudet och säger att det får henne att springa tillbaka om hon vandrar bort. Rockbiter väntar på Shay vid sitt läger, och klockan ska hjälpa henne att hitta hem."}},faq={{q="Vad är Shay’s Bell till för?",a="Shay säger att ljudet från klockan fångar hennes uppmärksamhet och får henne att komma tillbaka om hon vandrar bort.",al={"shay-klocka","klockans användning","kalla på shay"}},{q="Var hittar jag Shay’s Bell?",a="Shay’s Bell förvaras i Shay’s Chest i Feralas.",al={"klockans plats","shay-kista","var är klockan"}},{q="Vem tillhör klockan?",a="Klockan är värdefull för Shay Leafrunner, som älskar ljudet.",al={"vems klocka","shay-föremål","klockans ägare"}},{q="Vem försöker Shay hitta?",a="Shay Leafrunner försöker hitta sin vän Rockbiter, som är vid sitt läger.",al={"vart går shay","shays vän","rockbiter"}}},fp="11,128,16.225.0,26.90.0,31.51.0,28.61.0,27.75.0"}
P.entries["item:sheathed-trol-kalar"] = {n="Sheathed Trol'kalar",s="Trol'kalar ligger frigjord i sitt stenhölje i Arathi Highlands. Zengu i Hammerfall väntar på svärdet, som Darkspear Trolls värdesätter.",h="Trol'kalar ligger frigjord i sitt stenhölje i Arathi Highlands.",kw={"darkspear","hammerfall","nimboya","sheathed trol'kalar","stenhölje","trol'kalar","trollbane's tomb","zengu"},ang={["race:Troll"]="Som troll bär du ett vapen som Zengu kallar Stroms och Arathors främsta. Darkspear Trolls står i skuld till dig för att du återlämnar det."},sec={{t="Stenhöljet",b="Från Trollbane's Tomb i Arathi Highlands bär du Trol'kalar i dess stenhölje. Ljuset som höll svärdet falnar och frigör vapnet. Zengu väntar i Hammerfall för att ta emot det."}},faq={{q="Vad är Sheathed Trol'kalar?",a="Sheathed Trol'kalar rymmer svärdet Trol'kalar i ett stenhölje. Det falnande ljuset frigör vapnet.",al={"sheathed trol'kalar","svärd i stenhölje"}},{q="Var hittade jag Trol'kalar?",a="Du hittar Sheathed Trol'kalar i Trollbane's Tomb i Arathi Highlands.",al={"var trol'kalar finns","trollbane's tomb"}},{q="Vem vill ha svärdet?",a="Zengu i Hammerfall väntar på Trol'kalar. Han säger att det ska levereras till Nimboya i Grom'gol.",al={"vem får trol'kalar","zengus svärd"}},{q="Varför är Trol'kalar viktig för trollen?",a="Trol'kalar kallas Stroms och Arathors främsta vapen. Zengu säger att Darkspear Trolls står i skuld till dig för att du återlämnar det.",al={"trol'kalars betydelse","varför trollen vill ha svärdet"}}},fp="19,136,16.186.0,28.107.0,28.69.0,20.91.0,41.132.0"}
P.entries["item:shellfish"] = {n="Shellfish",s="Skaldjur samlas i fällor under bryggorna vid Shadowprey Village. Jinar'Zillen vill ha dem insamlade och erbjuder en Bloodbelly fish i utbyte.",h="Skaldjur samlas i fällor under bryggorna vid Shadowprey Village.",kw={"bloodbelly fish","desolace","bryggor","jinar'zillen","shadowprey village","skaldjur","skaldjursfällor"},sec={{t="Under bryggorna",b="I vattnen väster om Shadowprey Village finns skaldjursfällor under bryggorna. Jinar'Zillen ber dig samla in fem skaldjur från dem, så att han kan låta någon annan sköta arbetet. I utbyte erbjuder han en fin Bloodbelly fish."}},faq={{q="Var hittar jag skaldjur?",a="Du kan samla skaldjur från fällor i vattnen väster om Shadowprey Village, under bryggorna där.",al={"skaldjur plats","var skaldjur","skaldjursfällor"}},{q="Vem vill ha skaldjuren?",a="Jinar'Zillen i Shadowprey Village ber dig samla skaldjur från fällorna under bryggorna.",al={"vem behöver skaldjur","jinar'zillen skaldjur","skaldjur till vem"}},{q="Hur många skaldjur behöver Jinar'Zillen?",a="Jinar'Zillen ber dig samla in fem skaldjur.",al={"antal skaldjur","hur många skaldjur","fem skaldjur"}},{q="Vad erbjuder Jinar'Zillen för skaldjur?",a="För varje fem skaldjur du lämnar till honom erbjuder Jinar'Zillen en Bloodbelly fish.",al={"skaldjursbelöning","bloodbelly fish","vad för skaldjur"}}},fp="9,146,15.223.0,26.96.0,24.96.0,42.48.0,43.78.0"}
P.entries["item:shimmering-frond"] = {n="Shimmering Frond",s="En Shimmering Frond är ett exemplar från en märklig, lysande växt som växer i The Oracle Glade på Teldrassil. Dess ovanliga sken och slingrande aura visar att den är en exotisk art, helt främmande för Världsträdets grenar.",h="En Shimmering Frond är ett exemplar från en märklig, lysande växt som växer i The Oracle Glade på Teldrassil.",kw={"botanik","denalan","lake al'ameth","the oracle glade","shimmering frond","märklig växt med fransiga blad","swamp of sorrows","teldrassil"},ang={["class:Druid"]="Att en invasiv kärrväxt frodas på Teldrassils nyfödda grenar är en märklig ekologisk avvikelse som förtjänar varje druids uppmärksamhet.",["profession:Herbalism"]="Örtkunniga som vandrar på Teldrassil kan uppskatta den sällsynta motståndskraft som krävs för att en växt från Swamp of Sorrows ska ta sig över havet och frodas i främmande jord."},sec={{t="Ett exemplar från fjärran",b="När resande vandrar bland de grönskande trädkronorna kring The Oracle Glade kan de stöta på märklig växtlighet med en pulserande, strålande aura. Bladen som plockas från växten fångar skogens silade ljus på onaturliga sätt och skimrar av livskraft. Denalan, en botaniker som sköter sina planteringslådor vid Lake Al'Ameth, känner genast igen växten som en art från det avlägsna Swamp of Sorrows i Eastern Kingdoms. Hur frön från ett träsk så långt bort på andra sidan Stora havet lyckats slå rot och frodas på det nyresta Teldrassil är fortfarande ett fängslande mysterium. Det får Denalan att gro och studera exemplar i sin egen jord."}},faq={{q="Var kommer Shimmering Frond ifrån?",a="Bladet skördas från en märklig växt med fransiga blad i The Oracle Glade på Teldrassil. Växten utmärker sig genom sitt slingrande, pulserande sken som lyser över bladen i skogens ljus.",al={"var får jag tag på shimmering frond","shimmering frond plats","märklig växt med fransiga blad"}},{q="Vem är intresserad av Shimmering Frond?",a="Denalan, en Night Elf-naturkännare som bedriver botanisk forskning vid Lake Al'Ameth, vill gärna undersöka exemplaret. Han är mycket intresserad av märklig växtlighet som slår rot runt om på Teldrassil.",al={"vem vill ha shimmering frond","vem ska få shimmering frond","denalan shimmering frond"}},{q="Vad gör växten så ovanlig på Teldrassil?",a="Växten hör inte hemma i Kalimdor eller på Världsträdet. Denalan känner igen den som en art som hör hemma i Swamp of Sorrows grumliga vatten, långt bort på andra sidan Stora havet i Eastern Kingdoms. Därför är dess frodiga växtlighet på Teldrassil mycket oväntad.",al={"varför är shimmering frond speciell","växtens ursprung","växt från swamp of sorrows"}},{q="Vad händer när du ger bladet till Denalan?",a="Denalan planterar och odlar genast exemplaret i sina planteringslådor vid Lake Al'Ameth för att testa dess snabba tillväxt och exotiska egenskaper.",al={"vad gör denalan med den","berättelsen om grodda blad"}}},fx={["7be1ca60"]={q="Vad är Shimmering Frond?",a="Det är ett blad från den ovanliga, övervuxna växt som kallas Strange Fronded Plant och finns i The Oracle Glade. Bladet skimrar ständigt under skogens trädkronor och utstrålar en virvlande, pulserande aura som är ovanlig bland Teldrassils grenar.",al={"vad är shimmering frond","föremålet shimmering frond","vad är det här för blad"}}},fp="16,152,20.421.0,42.151.0,42.139.0,47.183.0,47.116.0"}
P.entries["item:shimmerweed"] = {n="Shimmerweed",s="Shimmerweed är en särskild ört som Frostmane-trollen odlar på Shimmer Ridge, bland Dun Moroghs snöiga höjder. Trollen skördar den till sina stamriter, medan lokala dvärgbryggare trånar efter dess skarpa, unika smak till experimentella ölsorter.",h="Shimmerweed är en särskild ört som Frostmane-trollen odlar på Shimmer Ridge, bland Dun Moroghs snöiga höjder.",kw={"brewnall village","dun morogh","frostmane","perfekt stout","rejold barleybrew","shimmer ridge","shimmerweed"},ang={["profession:Herbalism"]="Shimmerweed ingår kanske inte i en vanlig fältbotanikers utrustning, men visar hur regionala växter ofta anpassas både till lokala bryggtraditioner och rituell alkemi.",["race:Dwarf"]="Med dvärgarnas uppfinningsrikedom är det bara en tidsfråga innan någon försöker jäsa en märklig växt som växer på en närbelägen klippsida till öl."},sec={{t="En trollsk gröda",b="Högt ovanför Dun Moroghs lågland sköter Frostmane-trollen sina odlingar av shimmerweed längs Shimmer Ridges isiga klippor. Trollen skördar och förvarar växten i flätade korgar runt sina läger och använder den i sina heliga och gåtfulla riter. Utanför trollens samhälle bryr sig få bergsbor om örten, men dess kraftfulla egenskaper har väckt uppfinningsrika främlingars intresse."},{t="En hemlig ingrediens",b="I närbelägna Brewnall Village har bryggmästaren Rejold Barleybrew fattat stort intresse för örten. Han tror att bryggandet ligger i blodet och vill skapa den ultimata dvärgstouten. Han misstänker att shimmerweeds skarpa, omisskännliga smak kan vara den saknade ingrediensen. Han anlitar ofta äventyrslystna resenärer som smyger in i Frostmane-lägren, undviker de fientliga trollen och släpar tillbaka korgar fulla att hälla i hans jäskar."}},faq={{q="Var växer shimmerweed?",a="Shimmerweed växer uppe på Shimmer Ridge, en isig höjd nordväst om Brewnall Village i Dun Morogh. Frostmane-trollen odlar och skördar den och förvarar den i korgar runt sina läger.",al={"shimmerweed plats","var hittar man shimmerweed","växt på shimmer ridge"}},{q="Vad använder Frostmane-trollen shimmerweed till?",a="Frostmane-trollen använder shimmerweed i sina mystiska stamriter och ceremonier. Utomstående känner inte till de exakta detaljerna i ritualerna, men örten spelar en aktiv roll i deras kulturella och andliga sedvänjor på Shimmer Ridge.",al={"trollens användning av shimmerweed","varför vill troll ha shimmerweed"}},{q="Varför vill Rejold Barleybrew ha shimmerweed?",a="Rejold Barleybrew strävar efter att brygga den perfekta dvärgstouten i Brewnall Village. Han har upptäckt en unik smak hos den vilda örten och vill hälla färska korgar med shimmerweed i sin experimentella mäsk för att se om den ger den kraftfulla smakprofil som receptet behöver.",al={"rejold barleybrew uppdrag","vem vill ha shimmerweed","varför brygga med shimmerweed"}},{q="Växer shimmerweed någon annanstans än i Dun Morogh?",a="Olika varianter av shimmerweed har samlats in i torra trakter som Durotar, där andeskådare som Drek'Thar värdesätter växten för kraftfulla örtblandningar och läkande brygder. Det visar att örten kan anpassa sig även utanför Khaz Modans frusna toppar.",al={"shimmerweed durotar","shimmerweed utanför dun morogh"}}},fx={["1978b4f9"]={q="Vad är Shimmerweed?",a="Shimmerweed är en säregen växt som Frostmane-trollen odlar högt uppe i de snöiga bergen i Dun Morogh, särskilt kring Shimmer Ridge. Örten är känd för sin ovanliga smak och sina egenskaper. Trollen samlar den i korgar och använder den i lokala stamritualer, men driftiga dvärgbryggare har nyligen börjat intressera sig för dess kraftfulla egenskaper och testar den i experimentella ölsorter.",al={"vad är shimmerweed","växten shimmerweed","om shimmerweed"}},d2fd1cd1={q="Varifrån kommer Shimmerweed, och vem odlade den?",a="Shimmerweed odlas naturligt av Frostmane-trollen i Dun Morogh, som sköter om växten och skördar den ur korgar uppe på Shimmer Ridge. Frostmane-trollen odlar den för sina egna ritualer, men vilda varianter av den kraftfulla örten växer också i avlägsna länder som Durotar, där vildmarksörter och schamaner uppskattar den för att brygga drycker.",al={"varifrån kommer shimmerweed","vem odlade shimmerweed","shimmerweeds ursprung"}}},fp="11,155,15.319.0,19.352.0,28.175.0,49.209.0,44.230.0,50.210.0"}
P.entries["item:shindrell-s-note"] = {n="Shindrell's Note",s="Shindrell's Note är ett skriftligt meddelande med färska iakttagelser om korruption kring Astranaar och Ashenvales kust. Det skrevs av Night Elf-sentineln Shindrell Swiftfire och fungerar som en underrättelserapport som skickats österut genom skogen till druiden Kayneth Stillwind.",h="Shindrell's Note är ett skriftligt meddelande med färska iakttagelser om korruption kring Astranaar och...",kw={"ashenvale","astranaar","forest song","kayneth stillwind","nightsong woods","shindrell swiftfire","shindrell's note"},ang={["class:Druid"]="När Shindrells iakttagelser förs vidare till Kayneth Stillwind kan druiderna tillsammans avslöja rötterna till den onaturliga farsot som plågar skogen.",["race:NightElf"]="Meddelandet visar det pågående samarbetet mellan sentinelerna som försvarar Ashenvales bosättningar och Cenarion-druiderna som studerar skogens ekologiska sjukdom."},sec={{t="Ett meddelande genom skogen",b="När oron sprider sig i Ashenvale samarbetar Night Elf-sentineler och druider för att bevaka skogens gränser. Sentinel Shindrell Swiftfire skrev rapporten i Astranaar. Den beskriver oroande störningar som upptäckts längs västkusten och bland de centrala trädkronorna. Den är adresserad till Kayneth Stillwind, en druid som är stationerad vid Forest Songs helgedom i Nightsong Woods i öster. Genom att skicka budbärare med sina egna iakttagelser hjälper Shindrell Kayneth att undersöka den subtila korruption som sprider sig genom de heliga dungarna."}},faq={{q="Vad är Shindrell's Note?",a="Det är en fältrapport skriven av Sentinel Shindrell Swiftfire, med detaljer om störningar och misstänkt korruption som upptäckts nära Astranaar och längs Ashenvales kust.",al={"vad är det här för meddelande","shindrells meddelande","vad står det i meddelandet"}},{q="Vem ska få meddelandet?",a="Meddelandet är adresserat till Kayneth Stillwind, en Night Elf-druid vid Forest Song i den östra delen av Ashenvale som kallas Nightsong Woods.",al={"vem ska jag ge det till","vart ska det skickas","vem är meddelandet till"}},{q="Varför skrevs meddelandet?",a="Kayneth Stillwind bad om underrättelser om ovanliga händelser i de västra skogarna, eftersom han fruktade att en lömsk korruption höll på att slå rot där. Shindrell sammanställde sina iakttagelser för att hjälpa honom att bedöma hotet.",al={"varför skrevs meddelandet","vilken korruption menar shindrell","rapportens syfte"}},{q="Var bor Shindrell Swiftfire?",a="Shindrell Swiftfire är en Night Elf-sentinel stationerad i bosättningen Astranaar, mitt i Ashenvale.",al={"var är shindrell","shindrell swiftfires plats","vem skickade det här"}}},fx={ed6c40b2={q="Varifrån kommer Shindrell's Note, och vem skrev den?",a="Anteckningen skrevs av väktaren Shindrell Swiftfire i Astranaar. Den är utformad som en formell fältrapport och beskriver de oroande händelser hon iakttog längs Ashenvales kust och i skogarna runt omkring.",al={"vem skrev shindrell's note","vem skapade shindrell's note","ursprunget till shindrell's note"}}},fp="16,162,26.450.0,25.139.0,33.121.0,25.183.0,38.102.0"}
P.entries["item:shipment-of-boots"] = {n="Shipment of Boots",s="Utanför The Barrens kust ligger Shipment of Boots i ett Southsea-läger söder om Ratchet. Drizzlik skickade lådan från Booty Bay åt Gazlowes handelsnätverk, men piraterna lade beslag på den innan den nådde hamnen.",h="Utanför The Barrens kust ligger Shipment of Boots i ett Southsea-läger söder om Ratchet.",kw={"booty bay","drizzlik","gazlowe","ratchet","shipment of boots","southsea freebooters","stulet byte"},ang={["class:Rogue"]="Som rogue kan du smyga genom Southsea-lägren längs kusten. Deras piratpatruller är täta, så ett ljudlöst tillvägagångssätt är det säkraste sättet att återta Gazlowes stulna last."},sec={{t="Ett plundrat lass",b="Gazlowe ordnade så att Drizzlik, en klädhandlare i Booty Bay, skickade stövlar till Ratchet. Southsea Freebooters som patrullerade The Merchant Coast överföll skeppet och förde lådorna till sina strandläger söder om hamnen. De spred det stulna godset bland sina tält och skjul, och leveransen finns fortfarande där, långt från Ratchets kajer."}},faq={{q="Vem skickade den här skosändningen?",a="Drizzlik, en goblinhandlare i Booty Bay, skickade stövlarna från den södra hamnen.",al={"vem tillverkade skorna","var kom skorna ifrån","drizzliks skor"}},{q="Vem skulle få skorna?",a="Gazlowe beställde stövlarna till Ratchet. Han är chefsingenjör och förvaltare där, och leveransen skulle stödja hans lokala arbetsstyrka och handel.",al={"vem äger skorna","gazlowes skosändning"}},{q="Hur hamnade skorna hos piraterna?",a="Southsea Freebooters överföll lastfartyget längs The Barrens kust, plundrade det och förde lådorna till sina läger söder om Ratchet.",al={"varför har southsea-piraterna skor","vem stal skorna"}},{q="Var finns sändningen?",a="Leveransen finns i Southsea-piraternas läger längs kusten söder om Ratchet, bland deras plundrade gods.",al={"skornas plats","var finns shipment of boots","hitta skosändningen"}}},fx={["06b396e7"]={q="Vad är Shipment of Boots?",a="Shipment of Boots är en låda med skor som skickades över Stora havet från Booty Bay till Ratchet. Den skickades av goblinköpmannen Drizzlik direkt till Gazlowe, men Southsea Freebooters lade beslag på handelsfartyget som fraktade hans varor.",al={"vad är shipment of boots","föremålet shipment of boots","vad är det här för stövlar"}}},fp="17,211,17.348.0,32.80.0,38.152.0,42.149.0,32.107.0"}
P.entries["item:shipment-of-iron"] = {n="Shipment of Iron",s="En låda med råmetall förvaras i människornas smedja i Hillsbrad Fields. Den är ett livsviktigt lager för den lokala vapentillverkningen och därför ett prioriterat mål för Forsaken, som vill skära av försörjningslinjerna till Hillsbrads invånare.",h="En låda med råmetall förvaras i människornas smedja i Hillsbrad Fields.",kw={"slaget om hillsbrad","darthalia","hillsbrad fields","shipment of iron","tarren mill","verringtan"},ang={["faction:Horde"]="När Hillsbrad berövas förnödenheter försvagas böndernas väpnade motstånd innan fälttåget går vidare mot Southshore.",["profession:Blacksmithing"]="Lagret är själva livsnerven i människornas vapentillverkning i dalen. Utan tackor av råjärn står Verringtans smedja helt oanvändbar."},sec={{t="Motståndets drivkraft",b="I den pågående kampen i Hillsbrad Foothills har människornas bönder bjudit på oväntat hårt motstånd mot Tarren Mill. Mycket av deras stridsförmåga kommer direkt från smedjan vid Hillsbrad Fields sydvästra kant. Där arbetar Blacksmith Verringtan och hans lärlingar dygnet runt med att tillverka vapen och rustningar av stora järnleveranser. För att knäcka böndernas motstånd beordrade Forsakens befälhavare att smedjan skulle släckas, smederna dödas och det lagrade järnet beslagtas till Hordens krigsinsats."}},faq={{q="Var förvaras järnleveransen?",a="Leveransen finns inne i smedjan vid Hillsbrad Fields sydvästra utkant. Blacksmith Verringtan och hans lärlingar vaktar den noga.",al={"plats för järnleveransen","var finns järnet","järnets plats i hillsbrad"}},{q="Varför vill Forsaken ha järnet?",a="Genom att ta järnet skär man av vapenleveranserna till den lokala människomilisen. High Executor Darthalia tänker också använda järnlagren till Hordens krigsmaskin när offensiven riktas mot att jämna Southshore med marken.",al={"varför stjäla järn","järn i tarren mill","järnets syfte i slaget om hillsbrad"}},{q="Vem använde järnet från början?",a="Blacksmith Verringtan och hans fyra lärlingar använde järnet för att utrusta stadsborna och fältarbetarna. På så sätt förvandlade de enkla bönder till en beväpnad lokal försvarsstyrka mot de odöda.",al={"vem äger järnet","verringtans järn","smeder i hillsbrad"}},{q="Vem beordrar att järnleveransen ska hämtas?",a="High Executor Darthalia leder Forsakens operationer från Tarren Mill och ger den direkta ordern att döda smederna och ta järnet under slaget om Hillsbrad.",al={"vem ger uppdraget","darthalias järnuppdrag"}}},fx={["8a003d21"]={q="Vad är Shipment of Iron?",a="Shipment of Iron är ett lager råmetall som förvaras i människornas smedja i Hillsbrad Fields. Det är det främsta materialet som smeden Verringtan och hans lärlingar använder för att smida vapen och rustningar åt Hillsbrads invånare, som gör motstånd mot Forsaken.",al={"vad är shipment of iron","shipment of iron","järnleveransen i hillsbrad"}}},fp="16,106,22.445.0,35.153.0,37.217.0,35.182.0,46.154.0"}
P.entries["item:shipment-to-nethergarde"] = {n="Shipment to Nethergarde",s="Biggs karavan skickar livsviktiga förnödenheter från Swamp of Sorrows till Nethergarde Keep. Fästningen behöver dem för att hålla uppsikt över Dark Portal.",h="Biggs karavan skickar livsviktiga förnödenheter från Swamp of Sorrows till Nethergarde Keep.",kw={"azoran crystals","biggs","blasted lands","the dark portal","nethergarde keep","ogreangrepp","quartermaster lungertz","leverans till nethergarde"},ang={["faction:Alliance"]="Som Alliance-resenär för du förnödenheter till Nethergarde Keep, som håller uppsikt över Dark Portal."},sec={{t="En nödvändig leverans",b="Biggs ber dig föra förnödenheter som räddats undan ogreangrepp till Quartermaster Lungertz vid Nethergarde Keep. Fästningen håller uppsikt över Dark Portal från Blasted Lands norra kullar. Biggs reparerar sin vagn, så lasten måste färdas längs vägen utan honom."}},faq={{q="Vad finns i lasten?",a="Lasten innehåller livsviktiga förnödenheter som räddats undan ogreangrepp. Quartermaster Lungertz hoppas att den innehåller Azoran Crystals, som Nethergardes förråd börjar få ont om.",al={"lastens innehåll","vad finns i paketet","azoran crystals"}},{q="Vem skickade lasten?",a="Biggs packade förnödenheterna till Nethergarde Keep efter att ogreangrepp hotat karavanen.",al={"vem packade det","biggs paket","varifrån kommer lasten"}},{q="Vem ska ta emot lasten?",a="Quartermaster Lungertz vid Nethergarde Keep väntar på lasten.",al={"vem får paketet","leverans till nethergarde","quartermaster lungertz"}},{q="Varför behöver Nethergarde den?",a="Nethergarde Keep behöver förnödenheterna, och Quartermaster Lungertz säger att lagret av Azoran Crystals börjar sina.",al={"varför förnödenheter","vad behöver fästningen","nethergardes lager"}}},fp="23,147,17.266.0,24.163.0,22.89.0,32.71.0,29.113.0"}
P.entries["item:shipping-schedule"] = {n="Shipping Schedule",s="Vid Jerod's Landing smugglar Defias Brotherhood varor längs Elwynns vattenvägar. Hamnmästaren vaktar ett schema över transporter mellan Redridge och Westfall, och SI:7 vill ha det.",h="Vid Jerod's Landing smugglar Defias Brotherhood varor längs Elwynns vattenvägar.",kw={"defias","hamnmästare","elwynn forest","jerod's landing","mathias shaw","shipping schedule","si:7","smuggling"},ang={["class:Rogue"]="Som skurk prövas din smygförmåga och ficktjuvskonst när du tar schemat ur hamnmästarens fickor, sådant SI:7 förväntar sig av agenter som vill ansluta sig."},sec={{t="Smuggling vid Jerod's Landing",b="Söder om Goldshire ligger Jerod's Landing vid Nazferiti Rivers strand i Elwynn. Defias Brotherhood tog över platsen som knutpunkt för flodtrafiken. Därifrån smugglar de varor mellan Redridge och Westfall längs vattenvägar som Stormwind Guard inte håller uppsikt över. Deras hamnmästare håller Shipping Schedule nära sig och antecknar transporterna."},{t="I SI:7:s sikte",b="Master Mathias Shaw leder SI:7, Stormwinds underrättelsetjänst, och har beordrat att schemat ska stjälas. Det kan kartlägga Defias försörjningslinjer, samtidigt som stölden prövar nya agenter. Stölden måste ske inne i hamnhuset, ur hamnmästarens fickor. Om agenten ertappas förnekar SI:7 all inblandning, så att inget spår leder till dess kaserner i Stormwind."}},faq={{q="Vad är Shipping Schedule?",a="Shipping Schedule registrerar smuggelförsändelser som hanteras av Defias Brotherhoods hamnmästare vid Jerod's Landing. Det håller reda på last som fraktas mellan Redridge och Westfall genom Elwynn Forests inre vattenvägar.",al={"defias shipping schedule","vad är dokumentet","hamnmästarens schema"}},{q="Vem vill få tag på schemat?",a="Master Mathias Shaw, chef för SI:7, vill få tag på schemat. Han använder det för att spåra Defias smuggling och sätta lovande skurkar på prov ute i fält.",al={"vem behöver schemat","mathias shaw schema","vem tar shipping schedule"}},{q="Var finns schemat?",a="Defias Dockmaster bär schemat inne i hamnhuset vid Jerod's Landing. Platsen ligger vid Nazferiti River söder om Goldshire i Elwynn Forest. Dokumentet måste tas från honom där.",al={"shipping schedule plats","var finns hamnmästaren","hur får man tag på schemat"}},{q="Vad används Jerod's Landing till?",a="Defias Brotherhood tog över Jerod's Landing som en knutpunkt för smuggling. Flodförbindelsen knyter deras verksamhet i Redridge till deras fästen i Westfall.",al={"jerod's landing defias","varför har defias jerod's landing","defias hamn elwynn"}}},fx={["45ccd8c3"]={q="Varifrån kommer Shipping Schedule, och vem skrev den?",a="Defias Brotherhoods hamnmästare vid Jerod's Landing, söder om Goldshire, förvarar schemat. Det beskriver brottssyndikatets flodtransporter och håller reda på hur olagliga varor och smuggelgods fraktas mellan Redridge Mountains och Westfall.",al={"vem skrev shipping schedule","shipping schedules ursprung","vem skapade defias shipping schedule"}}},fp="17,181,28.335.0,25.350.0,30.208.0,34.141.0,28.208.0,33.167.0"}
P.entries["item:shrunken-head"] = {n="Shrunken Head"}
P.entries["item:sida-s-bag"] = {n="Sida's Bag",s="Sida's Bag är Sida personliga väska, som tillhör en invånare i Menethil Harbor. Under hennes utflykt till Ironbeard's Tomb svalde ett krypande slemmonstrum väskan hel. För att återfå den och dess mystiska innehåll måste du leta noggrant bland Wetlands frätande slem.",h="Sida's Bag är Sida personliga väska, som tillhör en invånare i Menethil Harbor.",kw={"dun modr","ironbeard's tomb","menethil harbor","slemmonster","sida","sida's bag","wetlands"},ang={["faction:Alliance"]="Menethil Harbors utsatta flyktingar och stadsbor är helt beroende av förbipasserande resenärer för att hantera de rovgiriga fasor som kryper in från de översvämmade Wetlands."},sec={{t="Ett panikartat försvar",b="När Sida gjorde sitt vanliga veckobesök vid Ironbeard's Tomb nära Dun Modr överfölls hon av de fasansfulla, droppande slemmonstren som hemsöker området. I panik inför den framträngande sörjan kastade hon sin personliga väska rakt mot en av varelserna. I stället för att driva bort besten sög slemmet helt enkelt in väskan i sin geléartade kropp. Avledningen gav Sida några dyrbara ögonblick att fly med livet i behåll tillbaka till tryggheten i Menethil Harbor, medan hennes ägodelar blev kvar i ett okänt slemmonster."},{t="Återfunnen i slemmet",b="Eftersom de böljande slemmonstren som stryker omkring vid Ironbeard's Tomb – från röda till monstruösa varianter – ser nästan likadana ut, måste du fälla kärrslemmen tills den sväljda väskan kommer fram hel. Trots att den legat i frätande matsmältningssörja bevarar den tåliga säcken sitt innehåll. När Sida får tillbaka den samlar hon ivrigt ihop sina ägodelar och kastar det förstörda, slemtäckta ytterhöljet. Hon erbjuder den urtvättade väskan till den som vågade sig ut i kärret för hennes skull."}},faq={{q="Varför låg Sidas väska i ett slemmonster?",a="Sida fick panik när droppande slemmonster anföll henne under ett besök vid Ironbeard's Tomb. I desperation efter att komma undan slungade hon sin väska mot ett av monstren, som genast omslöt och svalde den hel.",al={"hur hamnade väskan i slemmet","varför ligger väskan i slemmet","hur tappade sida väskan"}},{q="Vilka slemmonster bär på Sida's Bag?",a="Sida kan inte skilja slemmonstren åt, så vilket som helst av rovdjursslemmen kring Ironbeard's Tomb i nordöstra Wetlands – däribland Crimson Oozes, Black Oozes eller Monstrous Oozes – kan ha svalt den.",al={"var hittar man sida's bag","vad släpper sida's bag","vilket slemmonster har väskan"}},{q="Varför besöker Sida Ironbeard's Tomb?",a="Sida gör en veckovis vandring från Menethil Harbor till den forntida dvärgkryptan nära Dun Modr, men hon håller skälen bakom sina regelbundna besök för sig själv.",al={"sidas koppling till ironbeard","varför ironbeard's tomb"}},{q="Vad fanns i Sidas väska?",a="Sida tömmer snabbt ut de återfunna föremålen på marken och samlar ihop dem utan att visa vad de är. Hon konstaterar bara att innehållet var alldeles för viktigt för att lösas upp inuti ett slemmonster.",al={"vad tar sida ur väskan","väskans innehåll"}}},fx={["113113dd"]={q="Vad är Sida's Bag?",a="Sida's Bag är en personlig väska som tillhör Sida, en invånare i Menethil Harbor. Under ett av sina vanliga besök vid Ironbeard's Tomb i Wetlands överfölls hon av slemvarelser och kastade sin packning mot en av dem i ett desperat försök att fly. Varelsen svalde den hel, så väskan fastnade i dess geléaktiga kropp.",al={"vad är sida's bag","sida's bag","vem äger sida's bag"}},afbd2451={q="Varför vill Sida ha tillbaka sin väska?",a="Sida behöver desperat innehållet i sin försvunna väska, snarare än själva väskan. När du bänder loss den från resterna av slemvarelserna vid Ironbeard's Tomb och lämnar tillbaka den till henne i Menethil Harbor, tömmer hon genast det slemmiga innehållet på marken, plockar upp det och ger dig den tomma, slembemängda påsen.",al={"varför vill sida ha sin väska","varför sida's bag","varför vill någon ha sida's bag"}}},fp="10,224,18.300.0,24.369.0,34.160.0,29.204.0,37.154.0,27.179.0"}
P.entries["item:sigil-fragment"] = {n="Sigil Fragment",s="Sigil Fragment är en del av en skyddssigil som söks i Arathi Highlands. Tor’gan i Hammerfall kan binda ihop de insamlade delarna.",h="Sigil Fragment är en del av en skyddssigil som söks i Arathi Highlands.",kw={"arathi highlands","trasig sigil","galen","hammerfall","sigil fragment","sigil of thoradin","stromgarde","thoras trollbane","tor'gan"},ang={["class:Shaman"]="Som schaman kanske du känner igen Tor’gans uppgift: trollschamanen kan binda ihop delarna till en hel sigil."},sec={{t="Delar av en sigil",b="Stromgarde-försvarare håller sigilens delar i ruinerna av Stromgarde. Galen, son till Thoras Trollbane, delade Sigil of Thoradin i elva delar och spred ut dem bland försvararna. Tor’gan, en trollschaman i Hammerfall, kan binda ihop delarna till en hel sigil igen."}},faq={{q="Vad är en Sigil Fragment?",a="En Sigil Fragment är en del av Sigil of Thoradin, som Galen delade i elva delar.",al={"sigildel","vad är den här delen","delens betydelse"}},{q="Vem har delarna?",a="Stromgarde-försvarare i Arathi Highlands håller delarna.",al={"var hittar man delar","vem har sigildelarna","stromgarde-delar"}},{q="Vem kan sätta ihop sigilen igen?",a="Tor’gan, trollschamanen i Hammerfall, kan binda ihop delarna till en hel Sigil of Thoradin.",al={"vem lagar sigilen","tor'gan delar","sätta ihop trasig sigil"}},{q="Varför delades sigilen?",a="Galen, son till Thoras Trollbane, delade Sigil of Thoradin i elva delar och spred ut dem bland Stromgarde-försvarare.",al={"varför delades sigilen","vem delade den","galen sigil"}}},fp="14,151,17.297.0,25.94.0,22.64.0,36.102.1,31.127.1"}
P.entries["item:sigil-of-arathor"] = {n="Sigil of Arathor",s="Sigil of Arathor innehas av Lieutenant Valorcall, ledaren för Stromgardes kavalleri. Zengu i Hammerfall vill ha det för att hitta Trol’kalar.",h="Sigil of Arathor innehas av Lieutenant Valorcall, ledaren för Stromgardes kavalleri.",kw={"arathi highlands","kavalleri","hammerfall","lieutenant valorcall","sigil of arathor","stromgarde","trol'kalar","zengu"},ang={["faction:Horde"]="Som medlem av Horde kan du höra Zengu i Hammerfall söka efter sigillet för att försvaga Stromgardes försvarare."},sec={{t="Ett kavallerisigill",b="Lieutenant Valorcall bär Sigil of Arathor genom Arathi Highlands. Han leder kavalleriet som tjänar den mänsklige prinsen och försvararna i Stromgarde. Zengu i Hammerfall söker efter sigillet, och Valorcalls häst låter honom färdas snabbt genom landsbygden."},{t="Zengus syfte",b="Zengu vill att sigillet återlämnas till honom i Hammerfall. Han tror att om han tar det från Valorcall försvagas Stromgardes försvarare. Han säger också att sigillet för honom ett steg närmare att göra anspråk på Trol’kalar."}},faq={{q="Vad är Sigil of Arathor?",a="Sigil of Arathor är ett tecken som bärs av Lieutenant Valorcall, ledaren för Stromgardes kavalleri.",al={"sigil of arathor","arathors sigill"}},{q="Vem har sigillet?",a="Lieutenant Valorcall bär Sigil of Arathor medan han rider genom Arathi Highlands.",al={"valorcalls sigill","vem har det"}},{q="Var är Lieutenant Valorcall?",a="Lieutenant Valorcall rider genom Arathi Highlands, där hans häst låter honom färdas snabbt.",al={"var är valorcall","hitta valorcall"}},{q="Vem vill ha Sigil of Arathor?",a="Zengu i Hammerfall vill att Sigil of Arathor återlämnas till honom.",al={"vem vill ha sigillet","zengu vill ha"}},{q="Varför vill Zengu ha sigillet?",a="Zengu tror att om han tar sigillet försvagas Stromgardes försvarare och att han kommer närmare att göra anspråk på Trol’kalar.",al={"varför zengu vill ha det","trolkalar sigill"}}},fp="16,149,15.259.0,17.203.1,29.102.0,18.91.0,30.97.0,31.63.0,30.115.0"}
P.entries["item:sigil-of-ignaeus"] = {n="Sigil of Ignaeus",s="Sigil of Ignaeus består av fyra forntida sigill från Hammerfall. Dess ljus kan öppna vägen genom skyddet kring Trollbane's tomb.",h="Sigil of Ignaeus består av fyra forntida sigill från Hammerfall.",kw={"hammerfall","igneaus","sanctum","sigill","sigil of ignaeus","stromgarde","trol'kalar","trollbane","zengu"},sec={{t="De förenade sigillen",b="I Hammerfall ger Zengu dig Sigil of Ignaeus när de fyra separata sigillen har förenats. Dess lysande linjer stämmer överens med ristningarna på framsidan av Trollbane's tomb i Sanctum i Stromgarde. Gravens skydd spärrar vägen till det som finns där inne."},{t="Vid Trollbane's Tomb",b="När du låter sigillets linjer följa ristningarna på Trollbane's tomb slukar en ljusblixt det. Stenhänderna släpper det legendariska svärdet Trol'kalar."}},faq={{q="Vad är Sigil of Ignaeus?",a="Sigil of Ignaeus är ett enda sigill som bildas när Sigils of Strom, Thoradin, Arathor och Trollbane förenas.",al={"sigill of ig","igneaus sigill","vad är sigillet"}},{q="Vem ger dig Sigil of Ignaeus?",a="Zengu ger dig Sigil of Ignaeus i Hammerfall.",al={"vem har ig-sigillet","var får man sigillet","zengu sigill"}},{q="Vad gör sigillet?",a="Dess lysande linjer stämmer överens med ristningarna på Trollbane's tomb och bryter skyddet som vaktar den.",al={"sigillets användning","varför behövs ig-sigillet","bryt gravens skydd"}},{q="Var ligger Trollbane's tomb?",a="Trollbane's tomb ligger i Sanctum bakom kapellet i Stromgarde.",al={"trollbane's tomb plats","var ligger graven","sanctums plats"}},{q="Vad händer med sigillet vid graven?",a="En ljusblixt slukar Sigil of Ignaeus när dess linjer stämmer överens med gravens ristningar.",al={"sigillet förbrukas","vad händer med sigillet","blixt vid graven"}}},fp="16,139,17.256.0,19.155.1,29.126.0,35.51.0,23.94.1,26.69.0,38.97.1"}
P.entries["item:sigil-of-strom"] = {n="Sigil of Strom",s="Sigil of Strom är ett av sigillen som skyddar Trol'kalar i Trollbanes grav. Zengu från Hammerfall söker efter det bland Syndicate i Stromgarde.",h="Sigil of Strom är ett av sigillen som skyddar Trol'kalar i Trollbanes grav.",kw={"hammerfall","sigil of strom","stromgarde","syndicate","trol'kalar","trollslaktare","trollbane","zengu"},sec={{t="Ett sigill från Stromgarde",b="Syndicate tog ett av sigillen som vaktar Trol'kalar, det uråldriga trollsdräparsvärdet. Zengu från Hammerfall behöver det som första steg för att samla sigillen som skyddar klingan i Trollbanes grav."}},faq={{q="Vad är Sigil of Strom?",a="Sigil of Strom är ett av flera sigill som skyddar Trol'kalar i Trollbanes grav.",al={"sigil of strom betydelse","stromsigillet","vad är sigillet"}},{q="Vem vill ha Sigil of Strom?",a="Zengu i Hammerfall söker efter Sigil of Strom för att börja samla sigillen som skyddar Trol'kalar.",al={"vem behöver sigillet","zengu sigill","vem vill ha det"}},{q="Var hittar jag Sigil of Strom?",a="Syndicate tog Sigil of Strom, och en av dess agenter i Stromgarde bär det.",al={"sigillets plats","var finns stromsigillet","hitta sigillet"}},{q="Varför behöver Zengu sigillet?",a="Sigillet är ett av flera sigill som Zengu behöver för att ta bort Trol'kalar från Trollbanes grav.",al={"varför hämta sigillet","varför zengu vill ha det","trol'kalars sigill"}},{q="Vad är Trol'kalar?",a="Trol'kalar är ett uråldrigt svärd vars namn betyder trollsdräpare på trollens språk. Lord Ignaeus of Strom, kallad Trollbane, svingade det i strid.",al={"trol'kalars svärd","trollslaktare","trol'kalar betydelse"}}},fp="14,145,18.204.0,27.85.0,29.98.0,36.86.0,30.89.1,19.146.0"}
P.entries["item:sigil-of-the-hammer"] = {n="Sigil of the Hammer",s="Sigil of the Hammer är ett tecken för att söka upp lärda som har Yagyin’s Digest. Det öppnar vägen till kunskap som söks för att ge skydd.",h="Sigil of the Hammer är ett tecken för att söka upp lärda som har Yagyin’s Digest.",kw={"forlorn cavern","gerrig bonegrip","hammer sigil","ironforge","keeper bel'dugur","sigil of the hammer","undercity","yagyin's digest"},sec={{t="Ett tecken på lärdom",b="En tavla pekar mot en skrift sammanställd av Yagyin, och Sigil of the Hammer är tecknet som öppnar vägen till den. I Ironforge har Gerrig Bonegrip en butik i Forlorn Cavern. I Undercity sköter Keeper Bel'dugur en boksamling. Visa sigillet för någon av de lärda och be om skriften."}},faq={{q="Vad används Sigil of the Hammer till?",a="Sigil of the Hammer visar lärda vem som bär det, så att du kan be dem om Yagyin's Digest.",al={"sigillets användning","hammer sigil syfte"}},{q="Vem ska jag visa sigillet för?",a="Visa Sigil of the Hammer för Gerrig Bonegrip i Ironforge eller Keeper Bel'dugur i Undercity.",al={"vem får sigillet","sigillets mottagare"}},{q="Var finns Gerrig Bonegrip?",a="Gerrig Bonegrip har en butik i Forlorn Cavern i Ironforge.",al={"gerrigs plats","gerrigs butik"}},{q="Var finns Keeper Bel'dugur?",a="Keeper Bel'dugur finns i Undercity, där han sköter en boksamling.",al={"bel'dugurs plats","lärd i undercity"}},{q="Varför är skriften viktig?",a="Skriften innehåller kunskap som de som söker den vill använda för att skydda andra.",al={"varför yagyin digest","skriftens betydelse"}}},fp="19,139,18.303.0,36.95.0,27.98.0,25.64.0,26.75.0,27.63.0"}
P.entries["item:sigil-of-thoradin"] = {n="Sigil of Thoradin",s="Sigil of Thoradin är ett återställt sigill kopplat till Trollbanes grav i Arathi Highlands. Zengu i Hammerfall behöver det för att hjälpa till att öppna graven.",h="Sigil of Thoradin är ett återställt sigill kopplat till Trollbanes grav i Arathi Highlands.",kw={"arathi","hammerfall","sigil of thoradin","thoradin","grav","trol'kalar","trollbane","zengu"},sec={{t="Ett återställt sigill",b="Zengu i Hammerfall behöver Sigil of Thoradin för att hjälpa till att låsa upp sigillet på Trollbanes grav. Återuppbyggnaden har lyckats, och arbetet med att nå Trol'kalar kan fortsätta. Zengu säger att sökandet bara är halvvägs; de som bär det tredje sigillet rör sig runt i Arathi."}},faq={{q="Vad öppnar Sigil of Thoradin?",a="Det återställda Sigil of Thoradin kan hjälpa till att låsa upp sigillet på Trollbanes grav.",al={"vad öppnar sigillet","gravens sigill"}},{q="Vem behöver sigillet?",a="Zengu i Hammerfall behöver det återställda Sigil of Thoradin.",al={"vem vill ha sigillet","vem ska få sigillet"}},{q="Varför är sigillet viktigt?",a="Det behövs för att hjälpa till att avlägsna Trol'kalar från Trollbanes grav.",al={"varför sigillet är viktigt","sigillets syfte"}},{q="Var finns det tredje sigillet?",a="Zengu vet inte var det tredje sigillet finns; de som bär det rör sig runt i Arathi.",al={"det tredje sigillets plats","var finns det tredje"}}},fp="17,138,15.265.0,37.76.0,20.57.0,27.61.1,25.77.0"}
P.entries["item:sigil-of-trollbane"] = {n="Sigil of Trollbane",s="Prins Galen Trollbane håller Sigil of Trollbane i Stromgarde. Zengu i Hammerfall söker den, och du måste möta prinsen för att ta den.",h="Prins Galen Trollbane håller Sigil of Trollbane i Stromgarde.",kw={"galen trollbane","prins galen","sigill of trollbane","stromgarde","thoras trollbane","trol'kalar","trollbane","zengu"},ang={["class:Warrior"]="Som krigare kanske du tycker att prins Galen är en passande väktare för det sista sigillet; han är själv en erfaren kämpe."},sec={{t="Det sista sigillet",b="Zengu i Hammerfall söker det sista sigillet, som prins Galen förvarar i Stromgarde. Galen bor i ett kapell i stadsdelen som milisen håller och är väl bevakad. Ta sigillet till Zengu, så kan vägen till Thoras Trollbanes grav öppnas."}},faq={{q="Vad används Sigil of Trollbane till?",a="Sigil of Trollbane är det sista sigillet som behövs för att öppna Thoras Trollbanes grav och göra anspråk på Trol’kalar.",al={"sigillets syfte","varför behövs sigillet","trollbanes sigill"}},{q="Vem har Sigil of Trollbane?",a="Prins Galen Trollbane har Sigil of Trollbane i Stromgarde.",al={"vem har det","sigillets innehavare","galen sigill"}},{q="Var hittar jag prins Galen?",a="Prins Galen bor i ett kapell i den del av Stromgarde som milisen håller.",al={"var är galen","galens plats","hitta prins trollbane"}},{q="Vem vill ha sigillet?",a="Zengu i Hammerfall söker Sigil of Trollbane.",al={"vem vill ha det","sigill till zengu","hammerfall sigill"}},{q="Vad händer när sigillen har samlats in?",a="Med sigillen i sin ägo planerar Zengu att slå till mot trollen i Zul’Gurub och ta Trol’kalar från Thoras Trollbanes grav.",al={"vad händer efter sigillen","trolkalar härnäst","öppna graven"}}},fp="18,142,14.244.0,35.106.2,31.66.0,30.76.0,20.49.0,41.134.1"}
P.entries["item:sign-of-the-earth"] = {n="Sign of the Earth",s="Sign of the Earth är ett sigill smitt av Dark Iron som eftersöks i Badlands. Det är nyckeln till ett fängelse i Lethlor Ravine.",h="Sign of the Earth är ett sigill smitt av Dark Iron som eftersöks i Badlands.",kw={"angor fortress","badlands","blacklash","deathwing","garek","gorn","hematus","lethlor ravine","sign of the earth","tho'grun"},ang={["class:Mage"]="Som magiker känner du kanske igen Krasus som en mästare i Kirin Tor. Han skickade Garek till Badlands för att stoppa oroligheterna som håller på att blossa upp i Lethlor Ravine.",["faction:Horde"]="Som medlem av Horde påminner Sign dig om den gamla alliansen med Deathwing under andra kriget. Gorn söker det för att befria Blacklash och Hematus, fastän han menar att de ska gå under."},sec={{t="Ett stulet sigill",b="Garek, som skickats till Badlands av Krasus från Kirin Tor, ber dig hämta Sign of the Earth. Vandrade ogres tog det och rör sig i närheten av Camp Boff. Dark Iron-dvärgar vid Angor Fortress skapade märket, som håller två fångar bundna i Lethlor Ravine."},{t="Fängelsets nyckel",b="I Kargath berättar Gorn att Horde en gång var allierade med Deathwing under andra kriget. Tho'grun och hans ogres anlitades för att hämta Sign, men Tho'grun förrådde Horde och behöll det. När sigillet återlämnats tänker Gorn öppna drakarnas fängelse och släppa dem fria till deras undergång."}},faq={{q="Vad är Sign of the Earth?",a="Sign of the Earth är ett sigill skapat av Dark Iron-dvärgarna vid Angor Fortress. Det håller Blacklash och Hematus bundna i Lethlor Ravine.",al={"sign of earth","jordens sigill","vad är sign"}},{q="Vem vill ha Sign of the Earth?",a="Garek, som skickats av Krasus från Kirin Tor, ber dig hämta Sign. Gorn i Kargath söker det också åt Horde.",al={"vem behöver sign","garek sign","gorn sign"}},{q="Vem stal Sign?",a="En grupp vandrande ogres tog Sign of the Earth. Deras ledare, Tho'grun, behöll det efter att ha förrått Horde.",al={"vem har sign","tho grun sign","ogres stal det"}},{q="Vad låser Sign upp?",a="Sign of the Earth är nyckeln till fängelset där de svarta drakarna Blacklash och Hematus hålls i Lethlor Ravine.",al={"sign fängelsenyckel","vad låser det upp","svarta drakars fängelse"}},{q="Var hittar jag Sign?",a="De vandrande ogres färdas ibland genom Camp Boff i Badlands, där Tho'grun kan finnas.",al={"sign plats","var finns sign of earth","camp boff sign"}}},fp="17,118,13.251.0,16.281.1,30.130.0,32.115.0,19.112.1,26.112.0,26.100.0"}
P.entries["item:signed-recruitment-letter"] = {n="Signed Recruitment Letter",s="Kargal Battlescar skickar Signed Recruitment Letter västerut från Far Watch Post. Hans sigill instruerar nya rekryter att inställa sig för tjänstgöring vid The Crossroads.",h="Kargal Battlescar skickar Signed Recruitment Letter västerut från Far Watch Post.",kw={"värnplikt","crossroads","far watch post","kargal battlescar","sergra darkthorn","signed recruitment letter","the barrens","thrall"},ang={["class:Shaman"]="Som schaman rapporterar du till Sergra Darkthorn, en orkschaman som Thrall har anförtrott uppgiften att hjälpa till att säkra The Barrens.",["faction:Horde"]="Som medlem av Horde bär du med dig det här brevet från grundläggande tjänstgöring i Durotar till Hordens större styrkor vid gränslandet."},sec={{t="En värnpliktigs förflyttning",b="Vid Far Watch Post förbereder Kargal Battlescar rekryter för tjänstgöring i The Barrens. Utposten ligger öster om Southfury River, där nykomlingar kommer över från Durotar. När en värnpliktig visar Kargal att han är redo stämplar och undertecknar han ett introduktionsbrev. Ordern skickar rekryterna västerut längs vägen till The Crossroads. Där samordnar Sergra Darkthorn förnödenheterna och försvaret av de torra slätterna."},{t="Spänningar vid utposterna",b="Kargals order bär på hans personliga förakt för officeren som väntar på rekryten. Han kallar Sergra Darkthorn en bitsk schaman som pratar i cirklar med soldaterna. Kargal ifrågasätter öppet hövding Thralls höga tankar om henne. Ändå måste brevet nå Sergra innan några fler uppdrag delas ut vid The Crossroads."}},faq={{q="Vad är Signed Recruitment Letter till för?",a="Signed Recruitment Letter förflyttar dig från Kargal Battlescar vid Far Watch Post till tjänstgöring i The Barrens. Det visar Sergra Darkthorn vid The Crossroads att Kargal har bedömt dig som redo.",al={"vad gör brevet","använda rekryteringsbrev","undertecknat brev barrens"}},{q="Vem undertecknade brevet?",a="Kargal Battlescar undertecknar brevet. Den erfarne orchen ansvarar för Far Watch Post vid gränsen mellan Durotar och The Barrens, och undertecknar efter att en rekryt har slutfört sina inledande uppgifter där.",al={"vem skrev brevet","kargals brev","vem undertecknade det"}},{q="Vem ska jag lämna brevet till?",a="Du lämnar brevet till Sergra Darkthorn, en inflytelserik orkschaman som är stationerad vid den centrala korsningen i The Crossroads.",al={"var lämnar jag brevet","vem ska få brevet","brevets mottagare"}},{q="Varför talar Kargal illa om Sergra Darkthorn?",a="Kargal kallar Sergra skarp i tonen och besvärlig, och tycker att hon slösar tid på prat när det finns arbete att göra. Hövding Thrall håller henne högt, men Kargal tvivlar på hennes ledarskap.",al={"kargal och sergras konflikt","varför hatar kargal sergra"}}},fx={ea3ee62a={q="Vad är Signed Recruitment Letter?",a="Det är ett officiellt värvningsdokument från horden, som ges till rekryter som anländer till The Barrens från Durotar. Det har utformats och godkänts av Kargal Battlescar vid Far Watch Post och intygar formellt att du har granskats, värvats och skickats för att hjälpa bosättningen vid The Crossroads.",al={"vad är signed recruitment letter","recruitment letter","vad är det här brevet"}},ea22ddb8={q="Varför vill Sergra Darkthorn ha Signed Recruitment Letter?",a="Sergra Darkthorn leder verksamheten vid The Crossroads och förlitar sig på att nya rekryter hjälper till att säkra The Barrens åt horden. Brevet bekräftar att du har värvats under Kargals befäl och visar att du är redo att ta order, bevisa ditt värde och ta itu med det brådskande arbetet och hoten som bosättningen står inför.",al={"varför vill sergra ha brevet","varför lämna över recruitment letter","vem behöver recruitment letter"}}},fp="25,164,22.389.0,23.320.0,53.190.0,22.183.0,31.120.0,49.182.0"}
P.entries["item:silithid-egg-the-barrens"] = {n="Silithid Egg",s="Över Field of Giants ligger silithidägg begravda under jorden. Hordens forskare samlar in dem för att lära sig mer om svärmen som sprider sig genom södra The Barrens.",h="Över Field of Giants ligger silithidägg begravda under jorden.",kw={"the crossroads","digging claw","äggjakt","field of giants","korran","högar","silithider","silithid egg","the barrens"},ang={["faction:Horde"]="För Horden hotar intelligenta insektssvärmar nära The Crossroads handelsvägar och territorium i centrala Kalimdor."},sec={{t="En mystisk svärm",b="Silithidstackar reser sig ur Field of Giants medan märkliga, insektslika varelser rör om i jorden. Deras ägg ligger under den hårdnade marken, bevakade av revirhävdande silithider. Horden vet föga om dessa varelser, men spejare vid The Crossroads har sett tecken på samordning och intelligens utöver vanliga vilddjurs. Okläckta ägg kan hjälpa lärda i Orgrimmar att förstå silithidernas livscykel och natur."},{t="Utgrävning och fara",b="Silithidägg måste grävas upp ur stackarna med en anpassad Digging Claw. Varelserna försvarar sina underjordiska yngelkammare våldsamt och svärmar över alla som hotar deras okläckta ungar. Korran, en trollforskare, behöver oskadade exemplar att studera innan svärmen sprider sig längre över Kalimdor."}},faq={{q="Vad är Silithid Eggs?",a="Silithid Eggs är okläckta äggsamlingar begravda i jordhögar i södra The Barrens, särskilt kring Field of Giants.",al={"silithid egg","vad är silithid egg","silithidhögar"}},{q="Vem vill att äggen samlas in?",a="Korran, en trollforskare vid The Crossroads, samlar in äggen åt sina överordnade i Orgrimmar, som vill studera silithidernas biologi och beteende.",al={"vem behöver ägg","korrans uppdrag","uppdragsgivare för äggjakten"}},{q="Varför studeras silithiderna?",a="Horden vet föga om silithiderna. Korran har sett tecken på intelligens och samordning utöver typiska vilda djurs, något som oroar Hordens ledare när varelserna dyker upp i The Barrens.",al={"varför studera silithider","silithidhot","är silithider smarta"}},{q="Hur samlas äggen in?",a="En anpassad Digging Claw används för att bända loss ägg ur silithidstackarna medan den aggressiva svärmen försvarar sina bon.",al={"hur får man ägg","digging claw","samla silithidägg"}}},fx={["04f05afd"]={q="Varifrån kommer Silithid Eggs?",a="De här äggen läggs av de märkliga, insektslika silithiderna djupt inne i deras jordhögar i södra The Barrens, särskilt runt Field of Giants. Silithiderna gräver omsorgsfullt ner sina kullar i de väldiga jordhögarna och vaktar dem. De angriper ursinnigt alla som vågar störa bona.",al={"silithid egg ursprung","varifrån kommer silithid eggs","vem lade silithid eggs"}}},fp="12,168,18.405.0,21.294.0,23.125.0,31.142.0,35.191.0,26.96.0"}
P.entries["item:silixiz-s-tower-key"] = {n="Silixiz's Tower Key",s="Förman Silixiz bär på nyckeln till Venture Companys torn nära The Sludge Fen. Shattered Hand-agenter måste ta den ur hans ficka som en del av ett sabotageuppdrag under täckmantel.",h="Förman Silixiz bär på nyckeln till Venture Companys torn nära The Sludge Fen.",kw={"barrens","foreman silixiz","shattered hand","shenthul","silixiz","the sludge fen","tornnyckel","venture co"},ang={["class:Rogue"]="Som horderog är Silixiz's Tower Key ett prov för att bli upptagen i Shattered Hand. Det kräver skicklighet i smygande och fickstöld.",["faction:Horde"]="Som medlem av Horde bär du på en trofé knuten till kampen mot Venture Companys exploatering och kemiska experiment i norra Barrens."},sec={{t="Ett prov på finkänslighet",b="Norr om The Sludge Fen håller Venture Company sitt torn under sträng bevakning. Stor förman Puzik Gallywix övervakar den avskilda utkiken, medan goblinlegosoldater patrullerar området. Utanför bär förman Silixiz på tornnyckeln. En Shattered Hand-agent från Orgrimmar måste stjäla den och behålla den. Våld fungerar inte: agenten måste ta sig in obemärkt och stjäla Silixizs ficka, som prov på sin smygförmåga innan hen klättrar upp i tornets giftiga övre våningar."}},faq={{q="Var hittar jag Foreman Silixiz?",a="Förman Silixiz står utanför Venture Companys torn, rakt norr om The Sludge Fen i nordöstra Barrens.",al={"silixiz plats","var finns foreman silixiz","hitta silixiz"}},{q="Kan jag få tag på nyckeln genom att döda Foreman Silixiz?",a="Nej. Nyckeln kan inte tas från Silixizs lik. En agent måste stjäla den ur hans ficka medan han lever.",al={"silixiz nyckel byte","kan jag döda silixiz","plundra silixiz nyckel"}},{q="Vem behöver nyckeln?",a="Shattered Hands kontakter ger order om att nyckeln ska levereras till Shenthul, skurktränaren i Orgrimmar.",al={"vem vill ha nyckeln","lämna in silixiz nyckel","uppdrag med silixiz tower key"}},{q="Vad används nyckeln till?",a="Nyckeln bevisar att en agent infiltrerat Venture Companys torn nära The Sludge Fen. Den levereras till Shattered Hand tillsammans med stor förman Puzik Gallywixs huvud och Cache of Zanzil's Altered Mixture.",al={"vad låser silixiz nyckel upp","silixiz-nyckelns syfte","använd tornnyckeln"}}},fx={["163c94d7"]={q="Vad är Silixiz's Tower Key?",a="Det är en nyckel som förmannen Silixiz bär på utanför Venture Companys torn norr om The Sludge Fen. Agenten får order om att stjäla den och behålla den ifall Shattered Hands kontakt behöver den senare.",al={"vad är silixiz's tower key","silixiz nyckel","nyckel till venture companys torn"}}},fp="19,195,18.451.0,32.115.0,48.103.0,22.94.0,25.198.1"}
P.entries["item:silver-dawning-s-lockbox"] = {n="Silver Dawning's Lockbox",s="Silver Dawning's Lockbox är en stadig kista i de sjunkna resterna av fartyget Silver Dawning, utanför Darkshores kust. Den innehåller föremål som tillhörde fartygets fallne kapten och skeppsloggen, som gick förlorad när kustens murlocer överföll fartyget.",h="Silver Dawning's Lockbox är en stadig kista i de sjunkna resterna av fartyget Silver Dawning, utanför...",kw={"auberdine","darkshore","gorbold steelhand","kista","murloc","skeppsvrak","silver dawning"},ang={["race:Dwarf"]="Gorbold Steelhand tar på sig att se till att de fallna kaptenerna hedras och att deras tillhörigheter återbördas till deras överlevande kamrater.",["race:NightElf"]="Kistan bevarar de sista skrifterna och relikerna efter en kaldoreisk kapten som dog när hen försvarade sitt fartyg precis utanför norra Kalimdors kust."},sec={{t="Sjunkna rester",b="Fartyget Silver Dawning var på väg över havet mot hamnen i Auberdine när katastrofen slog till. Kustens murlocer svärmade över fartyget och drev ner det i det mörka vågskvalpet norr om hamnen. Kaptenen dog i angreppet, och vraket blev kvar under vågorna som ett dystert monument över varelsernas erövring. Inne i det översvämmade skrovet finns kaptenens personliga kista, med skeppsloggen och privata tillhörigheter. Om dessa föremål återbördas får de överlevande besättningsmedlemmarna i land en sista möjlighet till frid."}},faq={{q="Var finns Silver Dawning's Lockbox?",a="Kistan finns i det sjunkna vraket av Silver Dawning, ett uppochnervänt fartyg på havsbottnen norr om Auberdine, utanför Darkshores kust.",al={"kistans plats","var finns silver dawning-kistan","silver dawning-vraket"}},{q="Vad hände med Silver Dawning?",a="När Silver Dawning seglade över havet mot Auberdine överfölls fartyget av lokala murlocer. Fartyget övermannades, gick i vrak och sjönk under vågorna. Kaptenen miste livet.",al={"varför sjönk silver dawning","silver dawning-bakgrund","hur förliste fartyget"}},{q="Vad finns i kistan?",a="Kistan innehåller kaptenen på Silver Dawning personliga tillhörigheter och skeppslogg, bevarade i havsdjupet.",al={"silver dawning-innehåll","vad finns i kistan"}},{q="Vem letar efter kistan?",a="Gorbold Steelhand, en dvärg stationerad i Auberdine, ber modiga simmare dyka ner till vraken och hämta kistan, så att den fallne kaptenens överlevande besättning kan hedra minnet på rätt sätt.",al={"vem vill ha kistan","vem ger uppdraget","lämna in kistan"}}},fx={["9cc39920"]={q="Vad är Silver Dawning's Lockbox?",a="Det är kistan som tillhörde den avlidne kaptenen på Silver Dawning. När murlocer övermannade och sänkte fartyget utanför Darkshores norra kust gick kistan ner med vraket. Den innehåller kaptenens loggbok och de personliga tillhörigheter som finns kvar, djupt under vattnet bland de kringströvande varelserna.",al={"vad är silver dawning's lockbox","silver dawning-kistans bakgrund","kaptenens kista på silver dawning"}}},fp="24,179,15.344.0,46.130.0,36.149.0,27.76.0,27.167.0"}
P.entries["item:silvermane-stalker-flank"] = {n="Silvermane Stalker Flank",s="Silvermane Stalker Flanks är rått kött som Agnar Beastamer söker efter i The Hinterlands. Han behöver dem för att mata en Sprite Darter-unge.",h="Silvermane Stalker Flanks är rått kött som Agnar Beastamer söker efter i The Hinterlands.",kw={"agn ar beastamer","agnarbeastamer","mat till unge","the hinterlands","rått kött","silvermane stalker","silvermane stalker flank","sprite darter"},sec={{t="En första måltid",b="Agnar Beastamer förbereder sig på att ägget ska kläckas och oroar sig för att den unga Sprite Darter kanske inte överlever utan en ordentlig första måltid. Han ber dig hämta fem Silvermane Stalker Flanks. Köttet är tänkt för ungen när den kläcks."}},faq={{q="Vem vill ha Silvermane Stalker Flanks?",a="Agnar Beastamer i The Hinterlands vill ha fem Silvermane Stalker Flanks för att mata en Sprite Darter-unge.",al={"vem behöver flankerna","agnars kött","vem vill ha köttet"}},{q="Vad ska flankerna användas till?",a="Agnar tänker mata en Sprite Darter med det råa köttet när ägget kläcks.",al={"varför köttet","mat till en sprite-unge","vad ska flanken användas till"}},{q="Hur många flankbitar behöver Agnar?",a="Agnar Beastamer ber dig hämta fem Silvermane Stalker Flanks.",al={"hur många bitar","fem flankbitar","mängd kött"}},{q="Varifrån kommer Silvermane Stalker Flanks?",a="Silvermane Stalker Flanks kommer från Silvermane Stalkers i The Hinterlands.",al={"var hittar man flankerna","stalkerkött","källa till silvermane stalker flanks"}},{q="Vad äter en Sprite Darter?",a="Sprite Darters äter både kött och växtlighet. Agnar ber om råa Silvermane Stalker Flanks som första måltid åt ungen.",al={"sprite darters kost","vad äter darters","mat till drakunge"}}},fp="24,129,12.235.0,36.106.0,24.73.0,32.65.0,45.75.0,30.124.0"}
P.entries["item:silvery-spinnerets"] = {n="Silvery Spinnerets",s="Silvery Spinnerets skördas från den stora spindeln Lady Sathrah i norra Teldrassil. Förr vävde de nät som fångade läkande kvällsdagg åt Temple of the Moon. Priestesses of Elune söker dem för att hedra den fallna varelsens själ genom en helig återfödselritual.",h="Silvery Spinnerets skördas från den stora spindeln Lady Sathrah i norra Teldrassil.",kw={"lady sathrah","priestess a'moora","sathrah's sacrifice","silvery spinnerets","tears of the moon","temple of the moon","wellspring lake"},ang={["class:Priest"]="För Elunes tjänare är det inte ett utrotningsuppdrag att hämta spinnvårtorna, utan en helig begravningsritual där man ber Månemodern om en varelses försoning.",["race:NightElf"]="Lady Sathrahs tragiska slut påminner Kaldorei om att även varelser som älskas av Elune är sårbara för den smygande farsot som gör Teldrassil sjukt."},sec={{t="Heliga nät och korruption",b="Lady Sathrah räknades en gång bland Elunes gunstlingar och var känd för att spinna skimrande nät i månljuset nära Wellspring Lake. Hennes silversilke samlade kvällsdimman och bildade läkande daggdroppar som Sisterhood of Elune i Darnassus satte stort värde på. Tyvärr skonades hon inte från korruptionen som spred sig genom Teldrassils grenar. Sathrah föll in i våldsamt vansinne och blev en fara för sin egen avkomma och den omgivande skogen. Priestess A'moora ber resenärer att göra slut på spindelns lidande och hämta hennes spinnvårtor som en nådehandling, så att en vördad invånare i de stora grenarna får ro."},{t="Ett offer för återfödelse",b="De återfunna spinnvårtorna söks inte som en enkel trofé eller ett hantverksmaterial. I stället offrar Sisterhood dem direkt till Mångudinnan vid den centrala fontänen inne i Temple of the Moon. Under denna invigning, känd som Sathrah's Sacrifice, ber prästinnorna att Elune ska ta emot varelsens ande, rena vansinnet som tog hennes dödliga kropp i besittning och skänka henne frid i återfödelsen."}},faq={{q="Var får du tag på Silvery Spinnerets?",a="De tas från Lady Sathrah, en stor spindel som finns längs Teldrassils norra gränser nära Wellspring Lake.",al={"var hittar man silvery spinnerets","silvery spinnerets byte","vem släpper silvery spinnerets"}},{q="Varför vill Priestess A'moora ha spinnvårtorna?",a="Priestess A'moora vill offra dem till Elune som ett heligt offer. Ritualen hedrar Lady Sathrahs tidigare renhet och vädjar till gudinnan att rena odjurets ande och skänka henne frid och återfödelse.",al={"varför vill amoora ha spinnvårtor","vad används tears of the moon till"}},{q="Varför var Lady Sathrahs nät speciella?",a="Lady Sathrah spann lysande silkes trådar som fångade kvällsdimman under månljuset. Daggen som samlades i hennes nät hade starkt läkande magi, och Sisterhood of Elune förvarade den i Temple of the Moon för att använda vid läkedom.",al={"lady sathrahs nät","vad gjorde lady sathrah"}},{q="Varför dödades Lady Sathrah om hon var helig?",a="Hon föll in i ett obotligt vansinne tillsammans med andra fördärvade djur i Teldrassil. Hennes aggressivitet hotade skogen och hennes framtida kullar, så prästinnorna ansåg att det var en sorglig nådehandling att dräpa henne.",al={"varför döda lady sathrah","varför blev sathrah galen"}}},fx={["6e94bdc8"]={q="Vad är Silvery Spinnerets?",a="Silvery Spinnerets är de silkesproducerande organ som togs från den heliga spindeln Lady Sathrah i norra Teldrassil. I bättre tider använde hon dem för att väva skimrande silvertrådar i månljuset. Näten fångade kvällsdimman och gav en mirakulös dagg med kraftfulla läkande egenskaper, högt värderad av Elunes prästinnor.",al={"vad är silvery spinnerets","information om silvery spinnerets","lady sathrahs spinnerets"}},["48fdca9c"]={q="Varifrån kommer Silvery Spinnerets?",a="De utvinns från Lady Sathrah, en jättespindel som bor nära Wellspring Lake längs Teldrassils norra gräns. En gång vördad som en graciös och ren varelse välsignad av Elune, dukade Sathrah nyligen under för vansinne. Nattalverna tvingades göra slut på hennes lidande och återta hennes heliga kvarlevor.",al={"silvery spinnerets ursprung","vem skapade silvery spinnerets","var får man tag på silvery spinnerets"}}},fp="18,177,29.453.0,23.332.1,40.123.0,47.192.0,37.213.0,46.220.0"}
P.entries["item:simple-memorandum"] = {n="Simple Memorandum",s="Simple Memorandum är ett officiellt meddelande till gnomernas nybörjarkrigare som tränar i Coldridge Valley. Det kortfattade gnomiska direktivet uppmanar dem att inställa sig hos krigartränaren Thran Khorman i Anvilmar för att förbereda sig inför kriget för att återta Gnomeregan.",h="Simple Memorandum är ett officiellt meddelande till gnomernas nybörjarkrigare som tränar i Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","gnomeregan","simple memorandum","thran khorman","krigarträning"},ang={["class:Warrior"]="Den här lappen markerar en krigares första steg från enkla skärmytslingar till formell stridsundervisning under Thran Khorman i Anvilmar.",["race:Gnome"]="För gnomiska landsflyktingar påminner memorandumet om deras gemensamma mål: att vässa stridsfärdigheterna tillsammans med sina dvärgallierade inför Gnomeregans kommande befrielse."},sec={{t="En kallelse till Anvilmar",b="Nybörjaräventyrare i Coldridge Valley får ofta förtroendet att överlämna introduktionsbrev när de visar sitt mod mot traktens vilda djur och troggar. För unga gnomiska krigare är detta memorandum en formell order att inställa sig hos Thran Khorman, krigartränaren i Anvilmar. Dvärgveteraner inser att även om gnomer kan förlita sig på intelligens och uppfinningar, kommer återerövringen av Gnomeregan att kräva ren fysisk beslutsamhet och krigisk disciplin. Memorandumet uppmanar mottagaren att lägga de inledande uppgifterna åt sidan och söka personlig undervisning i krigskonsten."}},faq={{q="Vad är Simple Memorandum?",a="Det är ett skriftligt meddelande till gnomernas nybörjarkrigare i Coldridge Valley, med instruktioner om att inställa sig hos dvärgkrigartränaren i Anvilmar.",al={"simple memorandum","vad är den här lappen","memorandumföremål"}},{q="Vem skrev Simple Memorandum?",a="Det är inte undertecknat. Sten Stoutarm gissar att det kommer från Thran Khorman, men eftersom det talar om att återta vårt hem Gnomeregan är det ett gnomiskt direktiv som beordrar dig att inställa dig hos Thran, dvärgkrigartränaren i Anvilmar.",al={"vem skrev memorandumet","vem skickade lappen","författare till simple memorandum"}},{q="Vad händer när man har läst Simple Memorandum?",a="När du har läst dokumentet tar du det till Thran Khorman i Anvilmar. Han erkänner din beslutsamhet att återta ditt förlorade hem och erbjuder sig att träna dig i krigarens grundläggande tekniker.",al={"vad gör jag med memorandumet","var ska jag lämna det","lämna in simple memorandum"}},{q="Varför tränar en dvärg gnomiska krigare?",a="Efter Gnomeregans fall slog sig gnomiska flyktingar ner under Ironforges och Anvilmars beskydd. Dvärgveteraner som Thran Khorman har lovat att dela med sig av sin krigiska expertis för att hjälpa sina landsförvisade allierade att träna och till sist återta sin bestrålade stad.",al={"varför tränar thran gnomer","dvärgar tränar gnomer"}}},fx={b027c55a={q="Varför fick jag Simple Memorandum?",a="Memorandumet är ett gnomiskt direktiv som beordrar dig att rapportera till Thran Khorman, krigartränaren bland dvärgarna i Anvilmar. Som en fördriven gnomisk krigare är ditt främsta uppdrag att förbereda dig för kriget som ska återta Gnomeregan, och Thran har lovat att hjälpa dig och ditt folk att bli redo. Sten Stoutarm lämnade över meddelandet medan du hjälpte honom i Coldridge Valley.",al={"varför simple memorandum","syftet med simple memorandum","varför behöver jag simple memorandum"}}},fp="17,142,21.407.0,30.159.0,32.237.0,49.185.0,39.244.0"}
P.entries["item:simple-rune"] = {n="Simple Rune",s="En Simple Rune är en ristad stenbricka som ges till unga dvärgkrigare under träning i Coldridge Valley. Den fungerar som en kallelse från krigartränaren Thran Khorman och visar rekryterna att söka undervisning inne i Anvilmar.",h="En Simple Rune är en ristad stenbricka som ges till unga dvärgkrigare under träning i Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","dvärgruna","simple rune","thran khorman","krigarträning"},ang={["class:Warrior"]="För dvärgkrigare markerar den här ristade stenen det första steget mot formell militär träning under den erfarne instruktören Thran Khorman.",["race:Dwarf"]="Thran Khormans runa lovar en ung dvärg stridens grunder: yxans grepp, rustningens tyngd och svetten från verklig strid."},sec={{t="En kallelse till vapen",b="Simple Rune är ristad med enkla stridsmärken och ges till lovande rekryter som har börjat röja undan hoten runt Coldridge Valley. Den är ingen magisk amulett, utan fungerar som en formell kallelsebricka från Thran Khorman, den krigartränare som håller till i Anvilmar. När en ung kämpe läser de ingraverade anvisningarna förväntas hen genast inställa sig hos Thran för att lära sig grundläggande stridstekniker och få praktiska råd om hur man överlever Dun Moroghs fientliga vildmarker."}},faq={{q="Vad är Simple Runes syfte?",a="Simple Rune är en instruktionstavla som ges till blivande krigare i Coldridge Valley. När rekryten läser den får hen veta att hen ska inställa sig hos Thran Khorman inne i Anvilmar för formell träning.",al={"simple rune användning","vad gör runan","simple rune uppdragsföremål"}},{q="Vem skickar Simple Rune?",a="Den skickas av Thran Khorman, dvärgkrigartränaren som är stationerad inne i Anvilmar och håller utkik efter lovande kämpar som hjälper till i dalen.",al={"vem ristade runan","vem gav mig simple rune","runans avsändare"}},{q="Var ska jag lämna Simple Rune?",a="Ta den till Thran Khorman i Anvilmars stora smedjehall, mitt i Coldridge Valley.",al={"vart ska jag gå","lämna in runan","thran khorman plats"}}},fx={["0f0eb9fb"]={q="Vad är Simple Rune?",a="Simple Rune är en inskriven dvärgisk sten som ges till lovande krigare i Coldridge Valley. Den bär inga mystiska förtrollningar, utan fungerar som en skriftlig kallelse från Thran Khorman, som ber nybörjarkrigare att inställa sig hos honom i Anvilmar för att påbörja sin formella stridsutbildning.",al={"vad är simple rune","simple runes bakgrund","föremålet simple rune"}},["2d1fc984"]={q="Varför vill Thran Khorman att du ska ha Simple Rune?",a="Thran Khorman skickar runan för att rekrytera dig till formell krigarutbildning. Han ser potential i dina tidiga bedrifter runt Coldridge Valley och vill ge dig en grund i dvärgisk stridsdisciplin och lära dig vad som krävs för att kämpa för Ironforge medan hoten i trakten växer.",al={"varför skickar thran en runa","varför behöver jag simple rune","varför vill de ha simple rune"}}},fp="11,120,17.305.0,39.169.0,26.137.0,32.83.0"}
P.entries["item:simple-sigil"] = {n="Simple Sigil",s="En Simple Sigil är en anspråkslös träningstoken som ges till nattalvernas nybörjarkrigare i Shadowglen. Den bärs som en kallelse från krigarinstruktören Alyissia och markerar en ung krigares formella inträde i Teldrassils militära försvar.",h="En Simple Sigil är en anspråkslös träningstoken som ges till nattalvernas nybörjarkrigare i Shadowglen.",kw={"alyissia","ilthalaine","kaldoreisk krigare","shadowglen","simple sigil","teldrassil","krigarträning"},ang={["class:Warrior"]="För kaldoreiska krigare är denna enkla token ditt allra första intyg och introducerar dig till de krigstraditioner som krävs för att skydda Teldrassil.",["race:NightElf"]="Sigillet visar hur brådskande läget är för kaldoreierna, då instruktörer som Alyissia rekryterar alla dugliga händer för att hejda den växande korruptionen bland Världsträdets grenar."},sec={{t="En kallelse till vapen",b="I Shadowglens skyddade trädkronor får unga nattalver vägledning av Conservator Ilthalaine när de söker sin uppgift. Till blivande krigare överlämnar Ilthalaine en Simple Sigil som skickats av ett bud från krigarinstruktören Alyissia. Token har en inskription som uppmanar rekryten att inställa sig för undervisning och markerar början på disciplinerad krigsträning i en orolig tid för Världsträdet."},{t="Försvarets börda",b="När sigillet överlämnas till Alyissia leder det till ett samtal om kaldoreiernas utsatta läge. Teldrassils senaste tillväxt, den krypande korruptionen som förgiftar skogens bestar och återupptäckten av avlägsna länder som Feralas har spritt nattalvernas beskyddare tunt. Sigillet är ingen kraftfull artefakt, utan ett praktiskt bevis som välkomnar rekryten till den skara väktare som ska skydda sitt folk från nya hot."}},faq={{q="Vad är Simple Sigil?",a="Det är en inskriven introduktionstoken som Conservator Ilthalaine ger till nattalvernas nybörjarkrigare i Shadowglen. Den uppmanar bäraren att inställa sig hos Alyissia för formell krigarträning.",al={"föremålet simple sigil","vad gör simple sigil","vad är det här sigillet"}},{q="Vem skickar Simple Sigil?",a="Sigillet skickas med ett bud på uppdrag av Alyissia, Shadowglens krigarinstruktör, som vill börja utbilda nya krigare i försvaret av Teldrassil.",al={"vem gjorde sigillet","vem skickade simple sigil"}},{q="Vad ska jag göra med det?",a="Läs den inskrivna texten och lämna sigillet till Alyissia nära foten av Aldrassil i Shadowglen för att påbörja din krigarutbildning.",al={"var lämnar man in simple sigil","vem tar emot simple sigil"}},{q="Ger sigillet några särskilda förmågor?",a="Nej. Det är bara ett skriftligt meddelande och ett intyg som ska presentera blivande krigare för deras mentor.",al={"sigillets krafter","simple sigil egenskaper"}}},fp="12,138,17.341.0,21.366.0,25.193.0,27.150.0,25.131.0,43.91.0"}
P.entries["item:simple-tablet"] = {n="Simple Tablet",s="I Valley of Trials ger Gornek nya trollkrigare ett meddelande att ta med till Frang.",h="I Valley of Trials ger Gornek nya trollkrigare ett meddelande att ta med till Frang.",kw={"darkspear","durotar","frang","gornek","simple tablet","the den","valley of trials","krigartränare"},ang={["class:Warrior"]="Som krigare introducerar tavlan dig för Frang för stridsträning.",["race:Troll"]="Som en Darkspear-troll i Durotar kallar denna uppmaning dig att stärka Hordens främsta led tillsammans med orcherna."},sec={{t="En kallelse till strid",b="Gornek ger nya trollkrigare ett meddelande från Tar'sere, adresserat till Frang, krigarinstruktören nära The Den. Det introducerar rekryten till stridsträning i Durotar och ber dem att anmäla sig hos Frang. Meddelandet uppmanar dem att ta till vapen för Horden."}},faq={{q="Vad är Simple Tablet?",a="Gornek ger blivande trollkrigare i Valley of Trials ett meddelande som hänvisar dem till Frang för stridsträning.",al={"simple tablet","vad är den här tavlan","trollkrigares tavla"}},{q="Vem skickar tavlan?",a="Tar'sere undertecknar meddelandet och hänvisar rekryten till Frang, krigarinstruktören utanför The Den i Valley of Trials.",al={"vem skickade simple tablet","vem skrev tavlan","tavlans avsändare"}},{q="Vart ska jag ta tavlan?",a="Ta Simple Tablet till Frang, som vilar utanför The Den i Valley of Trials.",al={"vem ska jag ge simple tablet till","vart ska tavlan lämnas","var finns frang"}},{q="Vem får den här tavlan?",a="Simple Tablet ges till trollkrigare som påbörjar sina övergångsriter i Valley of Trials.",al={"kan vem som helst få simple tablet","vilken klass får simple tablet"}}},fx={["219776b3"]={q="Varför skickar Frang dig Simple Tablet?",a="Frang skriver den faktiskt inte. Gornek gissar att den kommer från Frang, men tavlan är undertecknad av trollen Tar'sere, som skickar dig till Frang utanför The Den. Frang behöver listiga trollkrigare som kan visa orcherna hur man slåss med mer än bara muskler, och han kan träna dig inför hordens kommande strider.",al={"varför simple tablet","varför vill frang ha mig","syftet med simple tablet"}}},fp="13,85,19.269.0,26.116.0,21.121.0,27.83.0,25.98.0"}
P.entries["item:singed-scale"] = {n="Singed Scale",s="I Durotar kommer Singed Scale från de förkolnade plattorna på elektrifierade åsködlor. Hordens krigare tar med sig fjällen för att bevisa sin uthållighet och lära sig försvarsstrid.",h="I Durotar kommer Singed Scale från de förkolnade plattorna på elektrifierade åsködlor.",kw={"far watch post","blixtskinn","försvarets väg","singed scale","åsködla","thunder ridge","uzzek"},ang={["class:Warrior"]="Som krigare under utveckling markerar det att du tar med fjällen till Uzzek en viktig milstolpe i att lära dig skydd och bli en ogenomtränglig sköld för Horden.",["faction:Horde"]="Vid Far Watch Post ser prövningar till att vakter och förtrupper vid Durotars och The Barrens gränser har okuvlig uthållighet."},sec={{t="Ett uthållighetsprov",b="Hordens veteraner bedömer en krigare efter vilka slag hen kan uthärda medan hen skyddar sina allierade. I Thunder Ridge, en kanjon i västra Durotar, döljer sig blixtar och åsködlor sprakar av stormenergi. Att jaga dessa bestar innebär att uthärda oupphörliga elektriska stötar och förkrossande slag. Deras svärtade fjäll visar att en kämpe kan stå emot våldsamma angrepp och hålla stånd under press."},{t="Sköldens väg",b="Vid Far Watch Post, på gränsen mellan Durotar och The Barrens, ber veteranen Uzzek nykomlingar om fem fjäll innan han undervisar dem. Han anser att de behöver fysisk styrka innan de kan lära sig ställningar och taktiskt försvar. Att ta med fjällen bevisar att de har uthålligheten som krävs för att förena tjock hud, tung rustning och noggrant fotarbete till ett stadigt försvar mot Hordens fiender."}},faq={{q="Vad används singed scales till?",a="Svedda fjäll bevisar uthållighet i strid. Uzzek, en krigartränare, kräver fem innan han lär en nykomling avancerade försvarstekniker.",al={"användning av singed scale","vem vill ha singed scales","uppdrag med singed scale"}},{q="Var hittar du singed scales?",a="Du hittar svedda fjäll på åsködlor och blixtgömmare i Thunder Ridge, en kanjon i västra Durotar på andra sidan floden från The Barrens.",al={"singed scale plats","var hittar man singed scales","hur får man tag på singed scale"}},{q="Varför är fjällen brända?",a="Åsködlor leder blixtar och elektriska stormar genom sina kroppar. Det ihållande sprakandet från elementenergi sveder och svärtar deras yttre hud, vilket ger fjällen deras förkolnade struktur.",al={"varför brända","varför är fjällen brända"}},{q="Vem är Uzzek och varför bryr han sig om de här fjällen?",a="Uzzek är en veteran bland krigarna vid Far Watch Post i östra The Barrens. Han tränar blivande krigare i Horden i försvarsstrid och kräver att de först bevisar sin motståndskraft mot dödliga bestar.",al={"vem är uzzek","uzzek"}}},fx={c263d0cb={q="Vad är Singed Scale?",a="Singed Scale är en tålig kräldjursskal som tagits från de vilda åsködlorna och blixtflådda varelserna i Thunder Ridge. De här varelserna sprakar ständigt av naturlig elektrisk energi och bär plattor som svärtats och ärrats av deras egna våldsamma blixturladdningar. Kvar blir förkolnade men anmärkningsvärt tåliga pansarplattor.",al={"vad är singed scale","singed scales bakgrund","information om singed scale"}}},fp="12,138,19.371.0,21.395.0,32.137.0,32.142.0,26.201.0,53.197.0"}
P.entries["item:singed-scroll-fragment"] = {n="Singed Scroll Fragment",s="Singed Scroll Fragment är en av tre bitar av en förstörd skriftrulle som Theldurin the Lost söker efter. Återfinnandet kan hjälpa till att skydda mot Myzrael.",h="Singed Scroll Fragment är en av tre bitar av en förstörd skriftrulle som Theldurin the Lost söker efter.",kw={"badlands","crumpled scroll fragment","enraged rock elemental","myzrael","scroll of myzrael","singed scroll fragment","theldurin the lost","torn scroll fragment"},sec={{t="En svedd bit",b="Enraged Rock Elementals i kullarna bakom Theldurin the Lost bär på Singed Scroll Fragment. Han söker efter den tillsammans med två andra bitar av Scroll of Myzrael, i hopp om att kunna foga samman fragmenten igen."}},faq={{q="Vad är Singed Scroll Fragment?",a="Det är ett av tre fragment från den förstörda Scroll of Myzrael.",al={"svedt fragment","svedd skriftrullebit"}},{q="Var kommer fragmentet ifrån?",a="Enraged Rock Elementals i kullarna bakom Theldurin the Lost bär på det.",al={"var hitta svedt fragment","svedt fragments plats"}},{q="Vem vill ha fragmentet?",a="Theldurin the Lost ber om det tillsammans med Torn Scroll Fragment och Crumpled Scroll Fragment.",al={"vem behöver svedt fragment","theldurin fragment"}},{q="Varför vill Theldurin ha fragmenten?",a="Han hoppas kunna foga ihop dem igen så att Scroll of Myzrael kan användas mot Myzrael.",al={"varför samla fragment","varför myzraels skriftrulle"}}},fp="22,146,16.198.0,35.66.0,34.72.0,23.99.0,38.79.0"}
P.entries["item:singing-blue-crystal"] = {n="Singing Blue Crystal",s="Singing Blue Crystals bryts av Venture Company i kullarna runt Crystalvein Mine. Crank Fizzlebub i Booty Bay vill ha dem som bevis på att goblinerna förlorar mark.",h="Singing Blue Crystals bryts av Venture Company i kullarna runt Crystalvein Mine.",kw={"basilisker","booty bay","crank fizzlebub","crystalvein mine","singing blue crystal","sjungande kristaller","stranglethorn vale","venture company"},sec={{t="Kristaller i kullarna",b="Nära Crystalvein Mine gräver Venture Companys arbetare fram Singing Blue Crystals ur de omgivande kullarna. De hade tänkt arbeta inne i gruvan, men basiliskerna drev bort dem. Crank Fizzlebub i Booty Bay ber dig hämta kristaller från företagets gruvarbetare. Han säger att deras reträtt skulle ge mer utrymme åt hederlig handel i Stranglethorn."}},faq={{q="Vad är Singing Blue Crystals?",a="Det är kristaller som Venture Company bryter i kullarna runt Crystalvein Mine.",al={"sjungande kristaller","blå kristall","vad är det här för kristaller"}},{q="Var bryter Venture Company dem?",a="Venture Company gräver fram Singing Blue Crystals ur kullarna runt Crystalvein Mine i Stranglethorn Vale.",al={"var finns kristallerna","kristallernas plats","var bryter venture company"}},{q="Varför bryter de inte kristaller inne i Crystalvein Mine?",a="Basilisker i Crystalvein Mine drev bort Venture Company, så dess arbetare bryter kristaller i de omgivande kullarna i stället.",al={"varför inte i gruvan","basiliskgruva","basilisker i crystalvein"}},{q="Vem vill ha kristallerna?",a="Crank Fizzlebub i Booty Bay vill ha Singing Blue Crystals som bevis på att Venture Company förlorar mark.",al={"vem behöver sjungande kristaller","crank fizzlebubs kristaller","kristaller åt crank"}},{q="Vad vill Venture Company göra med kristallerna?",a="Venture Company planerade att bryta Singing Blue Crystals i Crystalvein Mine, men gick över till kullarna när basiliskerna drev bort dem.",al={"varför bryta kristaller","venture companys kristaller","vad gräver goblinerna efter"}}},fp="20,177,21.344.0,31.84.0,41.113.0,47.109.0,23.108.0,53.137.0"}
P.entries["item:singing-crystal-shard"] = {n="Singing Crystal Shard",s="Singing Crystal Shards är värdefulla blå kristaller som finns i Stranglethorn Vale. Basilisker där äter kristallerna, vilket gör deras hud hårdare.",h="Singing Crystal Shards är värdefulla blå kristaller som finns i Stranglethorn Vale.",kw={"basilisk","blå skärvor","crank fizzlebub","singing crystal shard","sjungande kristaller","stranglethorn vale","venture company"},sec={{t="Kristall och fjäll",b="I Stranglethorn Vale äter basilisker Singing Crystals, och kristallerna gör deras hud hårdare. Ibland kan en skärva skördas från dem. Crank Fizzlebub säger att kristallerna bara finns i Stranglethorn och är värdefulla för vissa parter. Venture Company gör det svårt för honom att samla in dem."}},faq={{q="Vad är Singing Crystal Shards?",a="Singing Crystal Shards är bitar av kristaller som finns i Stranglethorn Vale. Basilisker äter kristallerna, vilket gör deras hud hårdare.",al={"sjungande kristallskärvor","blå kristallskärvor"}},{q="Varför har basilisker hård hud?",a="Basilisker i Stranglethorn Vale äter Singing Crystals, och kristallerna gör deras hud hårdare.",al={"basiliskers hårda hud","varför är basilisker tåliga"}},{q="Var hittar jag skärvorna?",a="Singing Crystal Shards kan skördas från basilisker i Stranglethorn Vale.",al={"skärvornas plats","var finns sjungande kristaller"}},{q="Varför vill Crank Fizzlebub ha dem?",a="Crank Fizzlebub säger att kristallerna är värdefulla för vissa parter och att han kan sälja dem med vinst.",al={"crank vill ha skärvor","vad behöver crank"}},{q="Vad har Venture Company med kristallerna att göra?",a="Venture Company gör det svårt för Crank Fizzlebub att samla in kristallerna.",al={"venture company och kristaller","varför venture company"}}},fp="21,134,17.294.0,32.127.0,36.89.0,28.77.0,35.101.0,59.82.0"}
P.entries["item:skeleton-finger"] = {n="Skeleton Finger",s="Ett avhugget, benigt finger från vandöda som stryker omkring i Duskwoods förbannade lundar och på kyrkogårdar. Madame Eva i Darkshire samlar dessa makabra lämningar, tillsammans med ghoulhuggtänder och spindelgift, för att skapa skyddande talismaner.",h="Ett avhugget, benigt finger från vandöda som stryker omkring i Duskwoods förbannade lundar och på kyrkogårdar.",kw={"darkshire","duskwood","ghoul fang","madame eva","skeletal raider","skeleton finger","totem of infliction"},ang={["class:Mage"]="Magiker som studerar folklig spådom finner att Madame Evas metod att förvandla skelettfingrar och naturliga gifter till en vedergällande förtrollning är en ovanlig blandning av hedge witchcraft och sympatisk magi.",["class:Paladin"]="Paladiner kan rysa vid tanken på att skända skelettrester och bära med sig avhuggna kroppsdelar, men i Duskwoods dystra mörker är det en bister nödvändighet att återanvända de oheligas ben för att skydda de levande."},sec={{t="De rastlösas ben",b="Duskwoods förbannade skogar översvämmas av de dödas rastlösa kvarlevor, från skelettplundrare och krigare till nekrotiska magiker och djävlar. Vanliga resenärer undviker att röra vid de vedervärdiga lämningarna efter de återuppståndna, men spåkvinnor och mystiker värdesätter deras kalla essens. Madame Eva, Darkshires siare, samlar dessa beniga fingrar för att binda deras kvardröjande nekrotiska energier till en skyddande amulett med vedergällande magi, känd som Totem of Infliction."}},faq={{q="Vilka varelser släpper Skeleton Finger?",a="Skeleton Fingers samlas in från olika skelettlevande odöda i Duskwood, däribland Skeletal Raiders, Healers, Warders, Warriors, Horrors, Fiends och Skeletal Mages.",al={"var faller skeleton fingers","vad släpper skeleton fingers","källa till skeleton finger"}},{q="Vem vill ha Skeleton Fingers i Duskwood?",a="Madame Eva, sierskan som bor i Darkshire, behöver dem som en del av ritualkomponenterna för att förtrolla en skyddande amulett.",al={"vem behöver skeleton fingers","uppdragsgivare för skeleton finger","vad används skeleton fingers till"}},{q="Vad är Totem of Infliction?",a="Det är en förtrollad amulett som Madame Eva skapar av skelettfingrar, ghoulhuggtänder och spindelgift. Hon väver samman deras mörka energier till en aura som tillfogar vedergällande skada på alla som försöker skada bäraren.",al={"syftet med totem of infliction","vad skapar madame eva"}},{q="Varför behöver Madame Eva odöda kvarlevor till en skyddsamulett?",a="Madame Evas ritualer kanaliserar den dolda besmittelsen och aggressiviteten hos traktens monster. Genom att binda samman de våldsamma essenserna från Duskwoods skelett, ghouler och giftiga bestar förvandlar hon deras kvardröjande illvilja till en amulett som straffar angripare.",al={"varför benmagi","varför skeleton fingers till totem"}}},fx={["7c732e26"]={q="Vad är Skeleton Finger?",a="Skeleton Finger är ett avhugget, uttorkat benfragment från ett av de animerade skelettmonster som strövar omkring i Duskwoods pestdrabbade skogar och kryptor. Den nekromantiska smitta som tagit över trakten har bevarat dessa fingrar, som fortfarande bär spår av den mörka magi som håller de odöda rastlösa och i rörelse.",al={"vad är skeleton finger","vad är skeleton fingers","identifiera skeleton finger"}},a7de6990={q="Varifrån kommer Skeleton Finger?",a="Fingrarna kommer från skelett som väckts till liv på Duskwoods hemsökta kyrkogårdar och i dess ruiner. De tillverkas inte, utan tas direkt från animerade lik, som skelettkrigare, vidunder, väktare och plundrare. De krälar genom dunklet, animerade av den mystiska smitta som sakta fördärvar skogen.",al={"skeleton finger ursprung","varifrån kommer skeleton fingers","vem skapade skeleton finger"}}},fp="15,157,21.373.0,38.125.0,39.84.0,32.179.0,63.206.0"}
P.entries["item:skeleton-key-mold"] = {n="Skeleton Key Mold",s="Skeleton Key Mold formar ett nyckelskaft av thorium och ben i lavan vid Fire Plume Ridge. Apothecary Dithers behöver den ofärdiga nyckeln i kampen mot Scourge i Andorhal.",h="Skeleton Key Mold formar ett nyckelskaft av thorium och ben i lavan vid Fire Plume Ridge.",kw={"andorhal","apothecary dithers","fire plume ridge","scourge","skeleton key","skeleton key mold","thorium","un'goro crater","ofärdig skelettnyckel"},ang={["faction:Horde"]="Dithers ber dig hjälpa till att bekämpa Scourge, vars makt håller Andorhal.",["profession:Mining"]="Thorium behövs för att smida nyckelskaftet, men Dithers låter dig själv skaffa det."},sec={{t="En form till nyckeln",b="Apothecary Dithers ger dig Skeleton Key Mold för arbetet vid Fire Plume Ridge i Un'Goro Crater. Med två Thorium Bars kan du använda formen intill lavasjön och smälta samman thorium och ben till ett ofärdigt nyckelskaft. Dithers säger att lavans hetta sköter smidet, men att du måste skaffa thorium separat."}},faq={{q="Vad används Skeleton Key Mold till?",a="Skeleton Key Mold formar ett nyckelskaft av thorium och ben i lavan vid Fire Plume Ridge.",al={"syftet med skelettformen","vad formen gör"}},{q="Vem ger mig formen?",a="Apothecary Dithers ger dig Skeleton Key Mold för arbetet vid Fire Plume Ridge.",al={"var få tag på skelettformen","dithers form"}},{q="Vad behöver jag till formen?",a="Du behöver två Thorium Bars tillsammans med Skeleton Key Mold för att smida det ofärdiga nyckelskaftet.",al={"formens ingredienser","thoriumstänger till nyckel"}},{q="Var används formen?",a="Använd Skeleton Key Mold intill lavasjön på toppen av Fire Plume Ridge i Un'Goro Crater.",al={"var använda skelettformen","lavan vid fire plume"}},{q="Varför tillverkar Dithers en skelettnyckel?",a="Dithers förbereder nyckeln som en del av försöket att slå till mot Scourge i Andorhal.",al={"nyckel till andorhal","varför skelettnyckel"}}},fp="17,177,18.318.0,34.89.0,22.83.0,29.88.0,23.96.0,37.88.0"}
P.entries["item:skin-of-sweet-rum"] = {n="Skin of Sweet Rum",s="Skin of Sweet Rum är en särskild sorts sprit från Lion's Pride Inn i Goldshire. Barkeep Daniels i Lakeshire är på jakt efter den och kämpar för att hålla sitt värdshus med varor medan Blackrock-orcher skär av Redridge från de vanliga handelsvägarna.",h="Skin of Sweet Rum är en särskild sorts sprit från Lion's Pride Inn i Goldshire.",kw={"barkeep daniels","dry times","goldshire","lakeshire","lion's pride inn","skin of sweet rum","söt rom"},ang={["faction:Alliance"]="Att få tag på den här rommen visar hur Blackrock-orchernas invasion har satt de små bosättningarna som försvarar Stormwinds östra gränser under logistisk press."},sec={{t="En sällsynt tröst för Lakeshire",b="I den krigströtta staden Lakeshire börjar tavernans förråd sina oroväckande snabbt. Blackrock-orchernas invasion har strypt tillförselvägarna till Redridge Mountains, och Barkeep Daniels kämpar för att släcka törsten hos utmattade stadsvakter och flyktingar. För att fylla på de sinande hyllorna skickar Daniels resenärer genom kungariket för att hämta regionala specialiteter, däribland en vattensäck fylld med det karaktäristiska söta rom som bryggs och serveras på Lion's Pride Inn i Goldshire."}},faq={{q="Var hittar jag Skin of Sweet Rum?",a="Skin of Sweet Rum kan köpas direkt av värdshusvärden eller bartendern på Lion's Pride Inn i Goldshire, som ligger i Elwynn Forest.",al={"plats för söt rom","var köpa söt rom","vem säljer söt rom"}},{q="Vem vill ha den här rommen?",a="Barkeep Daniels, som driver tavernan i Lakeshire, ber om en Skin of Sweet Rum tillsammans med flera andra regionala brygder för att fylla på sina sinande förråd under uppdraget Dry Times.",al={"vem behöver söt rom","lämna in söt rom","uppdrag om söt rom"}},{q="Varför börjar spriten ta slut i Lakeshire?",a="Den plötsliga upptrappningen av Blackrock-orchernas invasion i Redridge har brutit handelsförbindelserna och försenat leveranserna till staden. Vanliga handelsvagnar kan inte färdas säkert längs vägarna, så de lokala förråden är nästan tomma.",al={"varför har spriten tagit slut","varför är lakeshire torrt","orsaken till dry times"}},{q="Vilka andra spritsorter behövs utöver rommen?",a="Utöver Skin of Sweet Rum från Goldshire behöver Barkeep Daniels även en kagge Thunderbrew Lager från Westfall, en tunna Merlot från Stormwind City och en flaska Moonshine från Darkshire.",al={"drycker i dry times","daniels lista över drycker","annan sprit som behövs"}}},fx={efbd5e13={q="Vad är Skin of Sweet Rum?",a="Skin of Sweet Rum är en läderbehållare fylld med sötat brännvin som säljs i Goldshire i Elwynn Forest. Den är en av flera regionala spritsorter som uppskattas i de mänskliga rikena i södra Azeroth.",al={"vad är sött brännvin","information om skin of sweet rum","sött brännvin"}}},fp="17,123,28.311.0,37.117.0,19.140.0,39.152.0,48.148.0"}
P.entries["item:skittering-blood"] = {n="Skittering Blood",s="Skittering Blood är ett alkemiskt reagens som utvinns ur spindeldjuren i The Skittering Dark i Silverpine Forest. Det är en viktig giftig ingrediens i Royal Apothecary Societys forskning om en ny farsot, avsedd att utrota både Scourge och mänskligheten.",h="Skittering Blood är ett alkemiskt reagens som utvinns ur spindeldjuren i The Skittering Dark i Silverpine...",kw={"faranell","the new plague","renferrel","royal apothecary society","silverpine forest","skittering blood","the skittering dark","skitterweb"},ang={["faction:Horde"]="Forsaken-al kemister tar gärna emot råmaterialen för att säkra Lordaeron och bekämpa Scourge med vapen de själva har skapat.",["race:Undead"]="Genom att bidra med Skittering Blood hjälper du Queen Sylvanas och Royal Apothecary Society direkt att skapa det ultimata biologiska vapnet mot Arthas och den levande mänskligheten."},sec={{t="Ett giftigt destillat",b="Detta giftiga blod från Skitterweb lurkers, strikers och deras matriark Krethis the Shadowspinner har virulenta egenskaper som Forsaken-al kemister värdesätter. Apothecary Renferrel upptäckte att blodet, när det raffineras tillsammans med gifter utvunna ur grizzlybjörnshjärtan, blir grunden till ett synnerligen dödligt elixir. Föreningarna i vätskan innehåller kraftiga föroreningar, vilket gör den till en idealisk biologisk katalysator för Apothecariums kemiska experiment."},{t="Bränsle till The New Plague",b="Under ledning av Master Apothecary Faranell i Undercity samlar Royal Apothecary Society in reagenser som Skittering Blood för att framställa en förödande ny farsot. Inför överväldigande horder av Scourge och fientliga mänskliga kvarlevor använder Forsaken biologisk krigföring för att jämna ut oddsen. Faranell analyserar blodets giftstyrka för att skapa en smitta kraftig nog att släcka både odödligt liv och levande kött."}},faq={{q="Vad används Skittering Blood till?",a="Royal Apothecary Society använder Skittering Blood för att utveckla Forsakens nya farsot. När det blandas med gifter från björnhjärtan bildas en flyktig blandning som Master Apothecary Faranell studerar för att utrota både odöda Scourge och levande människor.",al={"användning av skittering blood","varför samla in spindelblod","vad gör faranell med skittering blood"}},{q="Var hittar man Skittering Blood?",a="Det samlas in från kropparna av Skitterweb-spindlar, däribland lurkers, strikers och Krethis the Shadowspinner, som håller till i och omkring The Skittering Dark, en dyster och spindelvävstäckt skog i nordvästra Silverpine Forest.",al={"var får man tag på skittering blood","skittering blood plats","vem släpper skittering blood"}},{q="Vem begär dessa prover?",a="Apothecary Renferrel vid The Sepulcher i Silverpine Forest beställer insamlingen av blodet och skickar äventyrare med vätskan direkt till Master Apothecary Faranell i Apothecarium i Undercity.",al={"vem vill ha skittering blood","uppdragsgivare för skittering blood"}},{q="Varför behöver Forsaken gift från lokala bestar?",a="Royal Apothecary Society isolerar ständigt naturliga gifter från Lordaerons fördärvade fauna. Jättespindlarna i Silverpine bär på naturliga biologiska smittämnen som kan koncentreras och användas som vapen i syntetiska farsoter.",al={"varför spindelgift","apotekarens forskning om bestar"}}},fx={["8eea8a63"]={q="Vad är Skittering Blood?",a="Skittering Blood är det virulenta sekret som utvinns från de väldiga spindlarna i The Skittering Dark i Silverpine Forest. Det har naturligt giftiga och smittförande egenskaper som gör det till ett ovärderligt biologiskt reagens för alkemiska experiment.",al={"vad är skittering blood","föremålet skittering blood","om skittering blood"}},f7d32240={q="Varifrån kommer Skittering Blood, och vem har tillverkat det?",a="Det tillverkas inte, utan tappas naturligt från de rovdjurslika spindeldjuren i nordvästra Silverpine Forest, däribland Skitterweb Lurkers, Skitterweb Strikers och yngelmamman Krethis the Shadowspinner. Jägare som samlar material åt de Förfallna tappar blodet direkt från deras kadaver.",al={"varifrån kommer skittering blood","vem tillverkade skittering blood","skittering blood ursprung"}}},fp="16,224,18.307.0,22.345.0,34.245.0,32.185.0,27.156.0,49.221.0"}
P.entries["item:skullsplitter-fetish"] = {n="Skullsplitter Fetish",s="En Skullsplitter Fetish är ett redskap för trollmagi som samlas in åt Brother Nimetz vid Rebel Camp. Han hoppas att den kan kasta ljus över Colonel Kurzens förfall.",h="En Skullsplitter Fetish är ett redskap för trollmagi som samlas in åt Brother Nimetz vid Rebel Camp.",kw={"brother nimetz","colonel kurzen","mystiker","skullsplitter","skullsplitter fetish","stranglethorn","trollmagi","häxdoktor"},ang={["faction:Alliance"]="Som Alliance-resenär kan du ge Brother Nimetz fetischerna och hjälpa honom att studera Colonel Kurzens förfall."},sec={{t="Trollmagi",b="Brother Nimetz vid Rebel Camp söker efter Skullsplitter Fetishes från Skullsplitter Witch Doctors och Mystics i Stranglethorn Vale. Han studerar amuletterna efter tecken på vad som har fått Colonel Kurzen att bli ond."}},faq={{q="Vad är en Skullsplitter Fetish?",a="En Skullsplitter Fetish är ett redskap för trollmagi som bärs av Skullsplitter Witch Doctors och Mystics.",al={"skullsplitter fetish betydelse","vad är fetischen","troll charm"}},{q="Vem vill ha fetischerna?",a="Brother Nimetz vid Rebel Camp vill ha Skullsplitter Fetishes för att kunna studera deras magi.",al={"vem vill ha fetischen","vart ska fetischerna","brother nimetz"}},{q="Varför vill Brother Nimetz ha dem?",a="Brother Nimetz hoppas att fetischerna kan avslöja hemligheten bakom Colonel Kurzens förfall.",al={"varför fetischer","kurzens förfall","vad vill nimetz ha"}},{q="Var hittar man Skullsplitter-fetischer?",a="Skullsplitter Witch Doctors och Mystics i Stranglethorn Vale bär på fetischerna.",al={"fetischens plats","var finns skullsplitters","hitta fetischer"}},{q="Hur många fetischer behöver Nimetz?",a="Brother Nimetz ber om fyra Skullsplitter Fetishes.",al={"antal fetischer","hur många amuletter","fyra fetischer"}}},fp="20,160,11.211.0,31.106.0,23.90.0,34.91.0,39.81.0,35.52.0"}
P.entries["item:skullsplitter-tusk"] = {n="Skullsplitter Tusk",s="En Skullsplitter Tusk är en trollhuggtand som används för att tillverka falska tigerhuggtänder för försäljning i South Seas. Kebok i Booty Bay vill ha en stor leverans till sin handel.",h="En Skullsplitter Tusk är en trollhuggtand som används för att tillverka falska tigerhuggtänder för...",kw={"booty bay","kebok","skullsplitter tusk","skullsplitter tusks","south seas","stranglethorn vale","tigerhuggtänder"},sec={{t="En falsk huggtand",b="Kebok i Booty Bay skickar dig efter Skullsplitter-trollen för att hämta deras huggtänder. Deras huggtänder blir övertygande kopior av tigerhuggtänder, som är kostsamma att samla in från själva bestarna. Förfalskningarna ska skickas till öarna i South Seas."}},faq={{q="Vad är en Skullsplitter Tusk?",a="En Skullsplitter Tusk är en trollhuggtand som Kebok använder för att göra falska tigerhuggtänder.",al={"skullsplitter tusk","trollhuggtand","vilken huggtand"}},{q="Vem vill ha Skullsplitter Tusks?",a="Kebok i Booty Bay vill ha Skullsplitter Tusks till sin leverans av förfalskade tigerhuggtänder.",al={"vem vill ha huggtänder","keboks huggtänder","köpare av huggtänder"}},{q="Varför behöver Kebok huggtänderna?",a="Kebok använder Skullsplitter Tusks som övertygande förfalskningar av tigerhuggtänder, som är kostsamma att samla in.",al={"varför huggtänder","falska tigerhuggtänder","huggtändernas syfte"}},{q="Var kommer Skullsplitter Tusks ifrån?",a="Huggtänderna kommer från Skullsplitter-troll i Stranglethorn Vale.",al={"varifrån kommer huggtänder","skullsplitters plats","trollhuggtänder"}}},fp="18,157,12.256.0,29.83.0,30.84.0,30.98.0,39.63.0"}
P.entries["item:skylord-plume"] = {n="Skylord Plume",s="Skylord Plume tas från en Razorbeak Skylord i Hinterlands. Huntsman Markhor i Revantusk Village vill ha den som bevis på att en av dessa farliga gripar har dödats.",h="Skylord Plume tas från en Razorbeak Skylord i Hinterlands.",kw={"grip","hinterlands","markhor","razorbeak skylord","revantusk village","skylord plume","trolljägare"},ang={["class:Hunter"]="Huntsman Markhor ber dig jaga en sällsynt grip som jagar jägare i Hinterlands.",["race:Troll"]="Markhor säger att Razorbeak Skylords har slukat trolljägare i Hinterlands, så hotet finns nära inpå."},sec={{t="Ett jägarbevis",b="I Revantusk Village ber Huntsman Markhor dig att hämta en Skylord Plume åt honom. Razorbeak Skylords är sällsynta gripar i Hinterlands, och Markhor säger att de jagar trolljägare. Han vill att du dödar en och återvänder med dess fjäder som bevis."}},faq={{q="Vad är Skylord Plume?",a="Skylord Plume kommer från en Razorbeak Skylord, en sällsynt grip i Hinterlands.",al={"skylord plume","vilken fjäder","gripfjäder"}},{q="Vem vill ha Skylord Plume?",a="Huntsman Markhor i Revantusk Village vill att du hämtar en Skylord Plume åt honom.",al={"vem vill ha fjädern","markhors fjäder","jägare i revantusk"}},{q="Varför vill Markhor ha den?",a="Markhor ber dig döda en Razorbeak Skylord och återvända med dess fjäder som bevis.",al={"varför fjädern","markhor vill ha fjäder","vad är den till för"}},{q="Var hittar jag en Razorbeak Skylord?",a="Razorbeak Skylords är sällsynta gripar som håller till i vildmarken i Hinterlands.",al={"var finns skylord","hitta razorbeak","skylord plats"}},{q="Varför är Skylords farliga för troll?",a="Markhor säger att de äldre griparna jagar trolljägare och föder upp avkomma som också dödar troll.",al={"skylords och troll","griphot","varför döda skylord"}}},fp="13,180,16.235.0,26.84.0,28.75.0,25.80.0,37.78.0,41.96.0"}
P.entries["item:slagtree-s-lost-tools"] = {n="Slagtree's Lost Tools",s="Slagtree’s Lost Tools är en stulen uppsättning smidesverktyg som Smith Slagtree söker efter i Revantusk Village. Han ber dig leta efter dem efter att Vilebranch-troller invaderat byn.",h="Slagtree’s Lost Tools är en stulen uppsättning smidesverktyg som Smith Slagtree söker efter i Revantusk...",kw={"agol'watha","gnom","förlorade verktyg","revantusk village","shaol'watha","skulk rock","slagtree","smith slagtree","vilebranch","vilebranch busar"},ang={["race:Gnome"]="En gnom gav Slagtree verktygen efter att ha räddat hans liv när han var en ung orch. Gåvan är fortfarande dyrbar för smeden.",["race:Orc"]="Slagtree minns verktygen som en gåva från gnomen som räddade hans liv när han var en ung orch."},sec={{t="En stulen gåva",b="I Revantusk Village ber Smith Slagtree dig leta efter verktygen som togs när Vilebranch-troller invaderade. Han har en reservuppsättning, men de här verktygen fick han av en godhjärtad gnom som räddade hans liv när han var ung. De kan finnas nära templen Agol'watha eller Shaol'watha, eller vid Skulk Rock. Slagtree vill få tillbaka den gamla gåvan."}},faq={{q="Vem vill ha Slagtree's Lost Tools?",a="Smith Slagtree i Revantusk Village vill få tillbaka sina stulna verktyg.",al={"vem vill ha verktygen","slagtree verktyg","smith slagtree"}},{q="Varför betyder verktygen så mycket för Slagtree?",a="En godhjärtad gnom gav Slagtree verktygen efter att ha räddat hans liv när han var en ung orch.",al={"varför är verktygen viktiga","verktygens betydelse","varför vill han ha dem"}},{q="Vem stal verktygen?",a="Vilebranch-troller stal Slagtree's verktyg när de invaderade Revantusk Village.",al={"vem tog slagtree verktyg","vilebranch stal verktyg","stulna verktyg"}},{q="Var kan verktygen finnas?",a="Verktygen sågs nära templen Agol'watha och Shaol'watha i nordöstra Hinterlands. Slagtree föreslår också att du letar vid Skulk Rock.",al={"var finns verktygen","verktygens plats","hitta slagtree verktyg"}},{q="Har Slagtree andra verktyg?",a="Slagtree har en reservuppsättning, men de stulna verktygen är dyrbara eftersom de kom från gnomen som räddade hans liv.",al={"reservverktyg","har han reservverktyg","andra smidesverktyg"}}},fp="21,180,13.340.0,32.68.0,36.94.1,20.77.0,25.143.0,31.113.1"}
P.entries["item:sleepers-key"] = {n="Sleepers' Key",s="Sleepers' Key är en av tre förtrollade nycklar som Night Elf-druider skapade för att försegla sitt heliga valv i The Talon Den på toppen av Stonetalon Peak. Den förvaras säkert i ett gömt gömställe som öppnas med Gatekeeper's Key och är en av de tre nycklar som behövs för att öppna druidernas skattkammare.",h="Sleepers' Key är en av tre förtrollade nycklar som Night Elf-druider skapade för att försegla sitt heliga...",kw={"gatekeeper's key","sleepers' cache","sleepers' key","stonetalon peak","talon den","talon den hoard","the den"},ang={["class:Druid"]="Nycklarna och gömställena i The Talon Den visar hur Night Elf-druiderna byggde upp sitt försvar i flera lager, med gömda gömställen och lås som kräver särskilda nycklar för att försegla mäktiga reliker.",["faction:Horde"]="Att skaffa Sleepers' Key är en del av en samordnad räd in i hjärtat av Stonetalon Peak. Då bryter man ner Night Elf-druidernas skydd för att göra anspråk på relikerna i deras skattkammare."},sec={{t="Druidernas skydd",b="The Talon Den är uthuggen högt uppe på Stonetalon Peak och tjänar som tillflyktsort och helgedom för Kalimdors druider. Medvetna om att deras heliga reliker och mäktiga skatter kunde väcka oönskad uppmärksamhet utformade Night Elf-förvaltarna ett invecklat system av lås och gömda gömställen för att skydda sina skatter. Sleepers' Key är en tredjedel av detta skydd. Den placerades i ett avskilt gömställe i den djupaste delen av The Den och kan bara hämtas med Gatekeeper's Key, som gömts nära ingången. Tillsammans med Claw Key och Barrow Key måste Sleepers' Key sättas i stenlåsen till Talon Den Hoard för att skingra skyddet och blotta de uråldriga föremålen därinne."}},faq={{q="Vad används Sleepers' Key till?",a="Sleepers' Key används tillsammans med Barrow Key och Claw Key för att öppna Talon Den Hoard, ett skyddat stenvalv som är gömt djupt inne i gravkammaren på Stonetalon Peak.",al={"vad gör sleepers' key","sleepers' keys syfte","nycklar till talon den hoard"}},{q="Hur låstes Sleepers' Key in?",a="Druiderna placerade den i Sleepers' Cache i de nordvästra tunnlarna i The Talon Den. För att öppna gömstället krävs Gatekeeper's Key, som druiderna gömde i en oansenlig lykta nära ingången till The Den.",al={"var finns sleepers' key","öppna sleepers' cache","krav för gatekeeper's key"}},{q="Varför gömde druiderna sina reliker med flera nycklar?",a="Night Elf-druiderna skapade invecklade skydd så att deras mäktiga föremål och heliga arvegods aldrig skulle hamna i fiendens händer om The Den angreps. Genom att fördela nycklarna mellan gömda gömställen såg de till att inkräktare inte enkelt kunde plundra deras skatter.",al={"varför så många nycklar","talon dens försvar","druidernas skattkammarproblem"}},{q="Varför heter den Sleepers' Key?",a="Druiderna förklarar aldrig namnet. Nyckeln delar helt enkelt namn med Sleepers' Cache, den gömda kistan i The Talon Den där den förvaras.",al={"vilka är sleepers","sleepers' keys namn betydelse"}}},fx={["0a862a33"]={q="Vad är Sleepers' Key?",a="Sleepers' Key är en av tre specialnycklar som skapats av nattalvdruiderna på Stonetalon Peak. Den är gömd i ett låst gömställe djupt inne i The Talon Den och utgör en viktig del av det skyddssystem som vaktar druidernas centrala skattkammare med heliga reliker.",al={"vad är sleepers' key","sleepers' keys bakgrund","om sleepers' key"}},["8275ad63"]={q="Varifrån kommer Sleepers' Key, och vem har tillverkat den?",a="Nyckeln smiddes av druiderna som grundade The Talon Den på Stonetalon Peak. För att skydda sina kraftfulla artefakter från inkräktare utformade de ett sinnrikt säkerhetssystem och låste in nyckeln i en särskild kista som kallas Sleepers' Cache.",al={"vem skapade sleepers' key","sleepers' keys ursprung","varifrån kommer sleepers' key"}},["3884172c"]={q="Varför vill någon ha Sleepers' Key?",a="Horden vill ha nyckeln för att ta sig förbi druidernas flera lager av försvar och låsa upp The Talon Den Hoard. Tillsammans med Claw Key och Barrow Key öppnar den stenvalvet där de kraftfulla reliker som druiderna gömde på Stonetalon Peak förvaras.",al={"varför hitta sleepers' key","varför behövs sleepers' key","vem vill ha sleepers' key"}}},fp="13,149,19.546.0,35.148.0,38.200.0,56.237.0,35.141.0"}
P.entries["item:small-brass-key"] = {n="Small Brass Key",s="Small Brass Key är gömd i en liggare vid Kurzen’s Compound. Den kan passa i ett kassaskrin i Stockpile.",h="Small Brass Key är gömd i en liggare vid Kurzen’s Compound.",kw={"bookie herod","herod","gömd nyckel","kurzen's compound","muddy note","small brass key","stockpile","stranglethorn vale","kassaskrin"},sec={{t="En nyckel i liggaren",b="Herods papper leder dig mot Stockpile, en grotta bakom Kurzen’s Compound i Stranglethorn Vale. Small Brass Key är instucken i ryggen på en av hans liggare. Där kan den öppna det säkra kassaskrin som nämns i hans anteckningar."},{t="I skrinet",b="I kassaskrinet finns Herods mer värdefulla mynt och föremål. När du öppnar det med Small Brass Key hittar du också en Muddy Note, som för sökandet efter förrädaren vidare."}},faq={{q="Var hittar jag Small Brass Key?",a="Small Brass Key är gömd i ryggen på en av Bookie Herods liggare.",al={"small brass key plats","var finns brass key","herods nyckel"}},{q="Vad öppnar Small Brass Key?",a="Small Brass Key öppnar Bookie Herods säkra kassaskrin i Stockpile vid Kurzen’s Compound.",al={"vilken nyckel öppnar","brass key kassaskrin","nyckel till kassaskrin"}},{q="Vad finns i Herods kassaskrin?",a="Herod förvarar sina mer värdefulla mynt och föremål i kassaskrinet. Där finns också en Muddy Note.",al={"herods kassaskrins innehåll","vad finns i skrinet","bookie herods skrin"}},{q="Vad betyder Muddy Note?",a="Muddy Note leder sökandet vidare mot att avslöja förrädaren.",al={"muddy note ledtråd","anteckning från skrinet","förrädarens anteckning"}}},fp="15,111,19.248.0,14.172.1,36.85.0,35.100.0,31.97.0,30.71.1"}
P.entries["item:smithing-tuyere"] = {n="Smithing Tuyere",s="Smithing Tuyere är ett smidesverktyg som Dark Iron dwarves har stulit i Searing Gorge. Thorium Brotherhood vill få det återlämnat till Taskmaster Scrange.",h="Smithing Tuyere är ett smidesverktyg som Dark Iron dwarves har stulit i Searing Gorge.",kw={"smidesverktyg","dark iron dwarves","ugn","searing gorge","smithing tuyere","taskmaster scrange","thorium brotherhood","blästerör"},ang={["profession:Blacksmithing"]="Som smed vet du att ett blästerör leder in luft i en ugn och får elden het nog för att bearbeta metall."},sec={{t="Ett stulet verktyg",b="Thorium Brotherhood söker efter Smithing Tuyere i Searing Gorge, där Dark Iron dwarves har stulit det. Verktyget hör hemma vid en smedja. Luften som blåses genom röret får ugnen att brinna hetare, så att metallen mjuknar och går att bearbeta."}},faq={{q="Vad är Smithing Tuyere?",a="Smithing Tuyere är ett rör som blåser in luft i en ugn och får elden att brinna hetare, så att metallen går att bearbeta.",al={"vad är ett blästerör","blästerverktyg","smidesrör"}},{q="Vem stal blästeröret?",a="Thorium Brotherhood tror att Dark Iron dwarves i Searing Gorge stal Smithing Tuyere.",al={"vem tog det","stöld av dark iron","vem stal verktyget"}},{q="Vem vill ha tillbaka blästeröret?",a="Thorium Brotherhood vill att Smithing Tuyere återlämnas till Taskmaster Scrange i Searing Gorge.",al={"vem vill ha det","återlämna blästeröret","föremål från thorium brotherhood"}},{q="Var stals blästeröret?",a="Dark Iron dwarves stal Smithing Tuyere i Searing Gorge.",al={"var saknas det","blästerörets plats","var hittar man verktyget"}}},fp="15,154,13.240.0,26.105.0,21.94.0,26.98.0,28.69.0"}
P.entries["item:smoky-iron-ingot"] = {n="Smoky Iron Ingot",s="Vid utgrävningsplatserna vid Windshear smälter kobolder Smoky Iron Ingots av malm som de bryter i Stonetalon Mountains. Orciska rustningsmakare värdesätter tackorna som råmaterial till slitstark ringbrynjeutrustning för Hordens krigare.",h="Vid utgrävningsplatserna vid Windshear smälter kobolder Smoky Iron Ingots av malm som de bryter i Stonetalon...",kw={"brutal armor","kobold","smoky iron ingot","stonetalon","thun'grim firegaze","krigare","windshear"},ang={["class:Warrior"]="För Hordens krigare prövar insamlingen av dessa tackor deras uthållighet i Stonetalon. De behövs för att smida Brutal Hauberk.",["profession:Blacksmithing"]="Dessa tackor visar de enkla smältmetoder som koboldgrävare använder, jämförda med utbildade smeders förfinade tekniker."},sec={{t="Koboldernas grova metallurgi",b="Kobolder smälter Smoky Iron Ingots i tunnlarna vid Windshear Crag i Stonetalon Mountains. De bryter malm ur de klippiga sluttningarna och hettar upp den över enkla, rykande eldar. Slagg och träkol fastnar på tackorna, men metallen förblir tät och stark."},{t="Smidandet av Brutal Armor",b="Thun'grim Firegaze, en nästan blind orcisk rustningsmakare, arbetar från ett kargt läger med utsikt över The Barrens. Han ber om dessa tackor för att tillverka rustningar åt beprövade krigare i Horden. Tillsammans med förädlade järntackor, Powdered Azurite och flyktigt flogiston bildar den rökiga metallen en motståndskraftig kärna i Brutal Hauberks."}},faq={{q="Var kommer Smoky Iron Ingots från?",a="Kobolder vid utgrävningsplatserna och i tunnlarna i östra Stonetalon Mountains bär på Smoky Iron Ingots. Bland dem finns grävare, stenhuggare, skadedjur, geomantiker och deras överordnade.",al={"var hittar man smoky iron ingot","smoky iron ingot plats","vem släpper smoky iron ingots"}},{q="Vad används Smoky Iron Ingots till?",a="Krigare som svarar på Thun'grim Firegazes uppmaning samlar Smoky Iron Ingots. Rustningsmästaren bor på topparna nära Crossroads i The Barrens och behöver femton tackor för att smida Brutal Hauberk.",al={"användning av smoky iron ingot","vad används smoky iron ingot till","uppdragsföremål för brutal armor"}},{q="Varför beskrivs tackorna som ”rökiga”?",a="Kobolder använder enkla, svagt brinnande smälteldar i sina dunkla tunnlar. Sot, träkolsdamm och aska fastnar på metallen i stället för att ge den en ren glans.",al={"varför är den rökig","smoky iron-bakgrund"}},{q="Kan vilken smed som helst arbeta med dessa tackor?",a="Nej. De oregelbundna, sotiga tackorna duger inte för vanligt smidesarbete i handeln. Bara smeder som Thun'grim Firegaze vet hur de ska bearbetas till särskild stridsutrustning.",al={"kan spelare smida smoky iron","är smoky iron en handelsvara"}}},fx={["18404e72"]={q="Vad är Smoky Iron Ingot?",a="Smoky Iron Ingots är grovt smälta tackor av mörkt järn med sotiga strimmor, som finns hos Windshear-kobolderna när de gräver djupt i Stonetalon Mountains. De är råa jämfört med förädlat smide, men har ändå den tåliga styrka som skickliga smeder behöver för att smida tung rustning som håller länge.",al={"vad är smoky iron ingot","information om smoky iron ingot","berätta om smoky iron ingot"}},["9ee5c553"]={q="Varifrån kommer Smoky Iron Ingot, och vem tillverkade den?",a="Kobolderna i Windshear Crag i Stonetalon Mountains bryter malmen och smälter tackorna. Djupt nere i sina underjordiska tunnlar gräver arbetare och ohyra fram råmalmen och gjuter den till användbara järntackor, som förstärker deras underjordiska verksamhet och beväpnar deras krigsband.",al={"smoky iron ingots ursprung","varifrån kommer smoky iron ingots","vem tillverkar smoky iron ingot"}},["8ab45f92"]={q="Varför vill någon ha Smoky Iron Ingot?",a="Den nästan blinde orkmästaren till smed, Thun'grim Firegaze, som bor högst uppe på klipporna i The Barrens, behöver femton sådana tackor för att skapa Brutal Armor åt värdiga Horde-krigare. Tillsammans med andra sällsynta alkemiska och mineraliska ämnen blir den råa metallen grundmaterialet till en rustning som ska tåla brutalt krig.",al={"varför skaffa smoky iron ingot","vem vill ha smoky iron ingot","smoky iron ingot i berättelsen"}}},fp="16,164,23.242.0,24.281.0,37.182.0,36.194.0,40.159.0,43.166.0"}
P.entries["item:smoldering-embers"] = {n="Smoldering Embers",s="Smoldering Embers är glödande, hettade rester som hämtas från de rasande eldelementalerna i The Charred Vale. Night Elf-väktare följer dessa glödbitar som fysiska bevis på att de brinnande fasor som härjar i den ödelagda skogen kuvas.",h="Smoldering Embers är glödande, hettade rester som hämtas från de rasande eldelementalerna i The Charred Vale.",kw={"burning destroyer","burning ravager","the charred vale","ursinniga andar","kaela shadowspear","rogue flame spirit","smoldering embers","stonetalon","venture company"},ang={["class:Druid"]="Druider ser glödbitarna som ett tragiskt bevis på en natur i obalans på grund av industriell girighet, där elementär vrede hindrar den askfyllda jorden från att någonsin återhämta sig.",["race:NightElf"]="För Night Elf är det en hjärtskärande skada på Kalimdor att se The Charred Vale stå i lågor. Att samla dessa glödbitar är en högtidlig plikt: att rena landet från främmande skändning och återföra friden under Elunes blick."},sec={{t="Rester från The Charred Vale",b="Venture Companys skoningslösa kalhuggning och industriella förödelse skar genom The Charred Vale, satte skogen i brand och släppte lös en förödande vrede från jordens djup. I deras spår vällde elementaler av levande eld fram över den förkolnade sänkan: Burning Ravagers, Burning Destroyers och kringströvande Rogue Flame Spirits. Dessa Smoldering Embers är de kvardröjande, askhöljda kärnor som blir kvar när en elemental släcks. De tjänar som bevis på att de våldsamma bränderna i dalen systematiskt kuvas."}},faq={{q="Var kommer Smoldering Embers ifrån?",a="Smoldering Embers samlas in från eldelementalerna som hemsöker The Charred Vale i södra Stonetalon Mountains, däribland Burning Ravagers, Burning Destroyers och Rogue Flame Spirits.",al={"var hittar jag smoldering embers","vem släpper smoldering embers","källa till smoldering embers"}},{q="Varför vill Kaela Shadowspear ha dessa glödbitar?",a="Kaela Shadowspear vill ha dem som obestridliga bevis på att de våldsamma eldelementalerna i The Charred Vale gallras ut. Hon tror att det sargade landet aldrig kan läka under Elunes nåd medan dessa våldsamma andar strövar fritt.",al={"varför samla smoldering embers","kaela shadowspear glödbitar","målet med ursinniga andar"}},{q="Vad fick eldelementalerna att dyka upp i The Charred Vale?",a="Venture Company använde kraftfulla maskiner och urskillningslös bränning för att röja den uråldriga skogen. Deras hänsynslösa exploatering destabiliserade landet och grävde fram och släppte lös fientliga elementaler av eld och sten, som till slut drev bort goblinerna.",al={"vad hände med charred vale","varför finns det eldelementaler i stonetalon","venture companys eldandar"}}},fx={["4d13fc7e"]={q="Vad är Smoldering Embers?",a="Smoldering Embers är de brinnande fysiska rester som lämnas efter de destruktiva eldelementalerna som hemsöker The Charred Vale. De glödande resterna finns kvar när varelser som Burning Ravagers, Rogue Flame Spirits och Burning Destroyers har dödats och är ett påtagligt bevis på att deras eldiga härjningar genom den förstörda skogen har stoppats.",al={"vad är smoldering embers","smoldering embers i berättelsen","vad är smoldering ember"}}},fp="17,159,28.404.0,37.182.0,45.208.0,62.277.0"}
P.entries["item:smotts-cutlass"] = {n="Smotts' Cutlass",s="Captain Smotts vill ha tillbaka sin sabel i Stranglethorn Vale. Han ber dig ta med vin och Barbecued Buzzard Wings till hans gamla livbåt vid kusten.",h="Captain Smotts vill ha tillbaka sin sabel i Stranglethorn Vale.",kw={"barbecued buzzard wings","captain smotts","sabel","negolash","förstörd livbåt","smotts' cutlass","stranglethorn vale"},sec={{t="En kaptens klinga",b="Captain Smotts ber dig ta med vin och Barbecued Buzzard Wings till hans gamla livbåt vid kusten. Negolash, den hungriga jätten som förstörde kaptens skepp, tycker om båda. Smotts tänker locka jätten nära och återta sin sabel. Klingan är i Negolashs händer."}},faq={{q="Vem äger Smotts' Cutlass?",a="Captain Smotts äger sabern och ber att få den tillbaka.",al={"smotts cutlass ägare","kaptens svärd","vem är smotts"}},{q="Hur fick Negolash tag på sabern?",a="Negolash tog sabern efter att jätten förstört Captain Smotts skepp.",al={"negolash cutlass","hur fick jätten tag på den","stulen sabel"}},{q="Varför vill Smotts ha vin och fågelvingar?",a="Negolash längtar efter vin och Captain Smotts Barbecued Buzzard Wings, så Smotts använder dem för att locka jätten till sin gamla livbåt.",al={"negolash lockbete","varför vin och vingar","smotts mat"}},{q="Var finns Smotts' Cutlass?",a="Negolash har Smotts' Cutlass i Stranglethorn Vale.",al={"sabelns plats","var finns smotts klinga","negolash föremål"}}},fp="15,148,17.273.0,25.56.0,33.73.1,44.124.0,25.51.1"}
P.entries["item:snellig-s-snuffbox"] = {n="Snellig's Snuffbox",s="Snellig's Snuffbox är ett personligt minne som bärgats från den rastlöse odöde First Mate Snellig bland vrakresterna efter The Lost Fleet. När du återlämnar detta föremål till First Mate Fitzsimmons i Menethil Harbor får han bevis för att hans förbannade forna besättningskamrat äntligen har fått vila.",h="Snellig's Snuffbox är ett personligt minne som bärgats från den rastlöse odöde First Mate Snellig bland...",kw={"förbannad besättning","fitzsimmons","kul tiras","the lost fleet","snellig","snusdosa","tredje flottan","wetlands"},ang={["faction:Alliance"]="Att återfinna fallna Kul Tiran-sjömäns ägodelar och ge deras förbannade andar ro är en dyster plikt i tjänst hos en gammal sjöburen allierad till Alliansen."},sec={{t="Ett minne från den tredje flottan",b="När Kul Tiras tredje flotta gick på grund längs Wetlands norra stränder fick dess sjömän och officerare ingen fridfull död. Bundna av en mystisk och mörk kraft knuten till en gömd skatt ombord på skeppen reste sig den drunknade besättningen på nytt som plågade andar och skelettodöda. Bland dem fanns First Mate Snellig, som fortfarande hemsöker det murknande lastrummet i vraket närmast kusten. Även i döden höll han fast vid sin snusdosa, en liten och alldaglig påminnelse om sitt jordiska liv till sjöss. För katastrofens enda levande överlevare, First Mate Fitzsimmons, är denna lilla ägodel ett påtagligt bevis på att åtminstone en av hans förlorade skeppskamrater har befriats från en evighet av plåga."}},faq={{q="Vad är Snellig's Snuffbox?",a="Det är en liten personlig dosa som en gång tillhörde First Mate Snellig, en officer i Kul Tiras olycksdrabbade tredje flotta. Den bärs av hans odöda skepnad ombord på skeppsvraken utanför Wetlands norra kust.",al={"vad är det här för föremål","snelligs snuffbox","snusdosa"}},{q="Var hittar jag Snellig's Snuffbox?",a="Snusdosan tas från First Mate Snellig, som hemsöker lastrummet i skeppsvraket närmast stranden vid The Lost Fleet i nordvästra Wetlands.",al={"var släpper snellig snusdosan","hitta snellig","first mate snellig plats"}},{q="Vem vill ha den här snusdosan?",a="First Mate Fitzsimmons, den tredje flottans enda levande överlevare, ber äventyrare att ta med snusdosan till honom i Menethil Harbor som bevis på att Snellig har fått vila.",al={"vem tar emot snusdosan","vem lämnar jag in den till","fitzsimmons uppdrag"}},{q="Varför är First Mate Snellig förbannad?",a="Enligt Fitzsimmons ledde en mörk och fruktansvärd skatt, gömd ombord på ett av den tredje flottans fartyg, besättningarna i fördärvet när skeppen förliste. Deras själar blev fångade i de murknande timren och nekades vila.",al={"varför är snellig odöd","the lost fleet förbannelse","tredje flottans förbannelse"}}},fp="18,184,29.620.0,27.168.0,35.152.0,24.167.0,33.194.0"}
P.entries["item:snufflenose-command-stick"] = {n="Snufflenose Command Stick",s="Snufflenose Command Stick är en dressyrstav som goblinentreprenören Mebok Mizzyrix tillhandahåller i Ratchet. Den används för att styra tränade snufflenose-gophers så att de hittar och gräver fram värdefulla Blueleaf Tuber som ligger djupt begravda i Razorfen Kraul.",h="Snufflenose Command Stick är en dressyrstav som goblinentreprenören Mebok Mizzyrix tillhandahåller i Ratchet.",kw={"blueleaf tuber","command stick","gopher","mebok mizzyrix","ratchet","razorfen kraul","snufflenose","the barrens"},ang={["profession:Cooking"]="Blueleaf Tuber betraktas som en utsökt kulinarisk delikatess världen över, men för att gräva upp dem krävs ett tränat djur och en styrstav, inte vanliga köksredskap."},sec={{t="En stav för gnagare",b="Blueleaf Tuber är eftertraktade delikatesser i hela Azeroth, men det är nästan omöjligt att hitta dem utan specialiserad hjälp. Rötterna ligger begravda i de taggiga underjordiska djupen i Razorfen Kraul och är helt dolda. För att utnyttja den lukrativa marknaden utan att själv våga sig in i quilboarhålorna tränade handelsmannen Mebok Mizzyrix från Ratchet snufflenose-gophers med skarpt luktsinne att gräva upp dem. Äventyrare använder Snufflenose Command Stick för att styra de tränade djuren och få dem att nosa upp och blottlägga rotknölar på upp till femtio stegs avstånd."}},faq={{q="Vad används Snufflenose Command Stick till?",a="Command Stick används för att beordra en tränad snufflenose-gopher att leta efter gömda Blueleaf Tuber i de taggiga tunnlarna i Razorfen Kraul. När staven riktas mot en tillkallad gopher får varelsen följa dofter och gräva upp rotknölar.",al={"hur använder man command stick","vad gör command stick","command sticks syfte"}},{q="Var får du tag på Snufflenose Command Stick?",a="Du hämtar den i Ratchet i The Barrens, precis utanför Mebok Mizzyrix verkstad, bredvid en låda med en tränad gopher och en instruktionsbok.",al={"var får man command stick","command sticks plats","vem ger command stick"}},{q="Varför vill Mebok Mizzyrix ha Blueleaf Tuber?",a="Blueleaf Tuber är sällsynta delikatesser som säljs med stor vinst till välbärgade matkontakter runtom i världen. Eftersom de bara växer djupt under The Barrens, i quilboarernas område, anlitar Mebok äventyrare för att skörda dem.",al={"varför knölar","blueleaf tubers användning","varför vill mebok ha knölar"}},{q="Får du behålla staven när du hittat knölarna?",a="Nej. När du har samlat ihop de efterfrågade knölarna kräver Mebok att du lämnar tillbaka både Snufflenose Command Stick och transportlådan till honom i Ratchet, tillsammans med skörden.",al={"kan jag behålla command stick","lämna tillbaka command stick"}}},fx={["8cc828c2"]={q="Vad är Snufflenose Command Stick?",a="Snufflenose Command Stick är det patenterade styrredskapet från Snuff Inc., som följer med de tränade jordekorrarna hos goblinföretagaren Mebok Mizzyrix i Ratchet. Det är särskilt utformat för att styra tränade snufflenose-jordekorrar och ge dem signalen att gräva fram begravda, svårfunna läckerheter som en vanlig spejare helt skulle missa.",al={"vad är en styrstav","snufflenose-stav","vad är snufflenose command stick"}},["9fdd5faa"]={q="Varifrån kommer Snufflenose Command Stick, och vem tillverkade den?",a="Styrstaven är en patenterad produkt från Snuff Inc., vars ägare Marwig Rustbolt förklarar hur den används i Snufflenose Owner's Manual. Mebok Mizzyrix i Ratchet har tränat sina snufflenose-jordekorrar att skörda sällsynta läckerheter och förvarar styrstavarna, lådorna och manualerna tillsammans så att inhyrda arbetare kan hantera djuren ordentligt.",al={"vem tillverkade styrstaven","styrstavens ursprung","varifrån kommer styrstaven"}},fb1cfa60={q="Varför vill någon ha Snufflenose Command Stick?",a="Sällsynta blueleaf-knölar är omöjliga att upptäcka utan hjälp under snåren i Razorfen Kraul. Styrstaven är oumbärlig eftersom den får en tränad snufflenose-jordekorre att nosa upp knölarna på femtio stegs avstånd och gräva upp dem. Sedan kan du lämna dem till Mebok Mizzyrix mot en rejäl belöning.",al={"varför behövs staven","varför efterfrågas styrstaven","varför skaffa snufflenose command stick"}}},fp="25,93,17.432.0,47.178.0,50.166.0,45.247.0,54.141.0"}
P.entries["item:snufflenose-owner-s-manual"] = {n="Snufflenose Owner's Manual",s="Snufflenose Owner's Manual är ett instruktionshäfte från Marwig Rustbolt på Snuff Inc., som finns bredvid goblinentreprenören Mebok Mizzyrix i Ratchet. Det beskriver hur man släpper ut och styr en tränad Snufflenose Gopher för att hitta sällsynta Blueleaf Tubers begravda i Razorfen Kraul.",h="Snufflenose Owner's Manual är ett instruktionshäfte från Marwig Rustbolt på Snuff Inc., som finns bredvid...",kw={"blueleaf tuber","gopher","handbok","mebok mizzyrix","ratchet","razorfen kraul","snufflenose"},ang={["profession:Cooking"]="Handboken beskriver hur man hämtar Blueleaf Tubers, en underjordisk rot som anses vara en sällsynt delikatess av finsmakare och handelsmän i hela Azeroth."},sec={{t="En goblins handbok",b="Den här korta handboken är skriven av Marwig Rustbolt, ägare till Snuff Inc., och beskriver hur man arbetar med företagets tränade snufflenose-gophers. Dessa djur har ett skarpt luktsinne som kan upptäcka underjordiska Blueleaf Tubers på femtio stegs avstånd. Handboken instruerar uppletare att släppa ut en gopher ur en ventilerad bur och styra dess instinkt att böka med en kommandostav. På så sätt leder man djuret genom Razorfen Krauls fientliga törnsnår och quilboar-tunnlar för att säkra de eftertraktade kulinariska läckerheterna."}},faq={{q="Vad är syftet med Snufflenose Owner's Manual?",a="Den innehåller instruktioner för hur man hanterar Mebok Mizzyrix tränade snufflenose-gophers. Äventyrare läser den för att förstå hur de ska släppa ut djuret ur buren och styra det med en kommandostav för att hitta begravda Blueleaf Tubers i Razorfen Kraul.",al={"vad handboken används till","varför läsa handboken","handbokens syfte"}},{q="Var kan jag hitta handboken?",a="Handboken finns i Ratchet i The Barrens, alldeles intill Mebok Mizzyrix och de specialbyggda burarna och kommandostavarna som behövs för att samla in knölar.",al={"handbokens plats","var boken finns","hur man får tag på handboken"}},{q="Varför behövs snufflenose-gophers för att hitta Blueleaf Tubers?",a="Blueleaf Tubers växer dolda djupt nere i jorden i Razorfen Kraul och är nästan omöjliga för humanoider att upptäcka. De tränade gopher-djuren har skarpa nosar som kan känna lukten av en begravd knöl på femtio stegs avstånd.",al={"varför använda gophers","kan jag hitta knölar utan gophers"}},{q="Vem skrev handboken?",a="Den är undertecknad av Marwig Rustbolt, ägare till Snuff Inc., som skrev den för att lära nya ägare att mata, rasta och styra sina gophers med den patenterade kommandostaven.",al={"handbokens författare","vem som skapade den"}}},fx={["1c231f00"]={q="Vad är Snufflenose Owner's Manual?",a="Det är en instruktionsbok som följer med en tränad snufflenose-jordekorre och en styrstav. Manualen visar äventyrare hur de ska hantera varelsen i Razorfen Krauls underjordiska tunnlar och förklarar hur du får jordekorren att nosa upp svårfunna Blueleaf Tubers under jord.",al={"vad är snufflenose owners manual","vad är snufflenose-manualen","vad är manualen"}}},fp="26,193,26.388.0,54.184.0,28.114.0,59.142.0,21.165.0"}
P.entries["item:sodium-nitrate"] = {n="Sodium Nitrate",s="Vid Bael Modan hjälper Sodium Nitrate dvärgarna att spränga sig genom stenen i södra Barrens. Gann Stonespire söker kemikalien för sprängladdningar mot fästningen.",h="Vid Bael Modan hjälper Sodium Nitrate dvärgarna att spränga sig genom stenen i södra Barrens.",kw={"bael modan","bael'dun","blackforge","gann stonespire","nitroglycerin","ganns hämnd","sodium nitrate","wood pulp"},ang={["profession:Engineering"]="Ingenjörer känner igen natriumnitrat, nitroglycerin och trämassa som receptet på stabiliserad dynamit, grunden för Ganns improviserade laddningar.",["race:Tauren"]="Som tauren tar Gann Stonespire till dvärgarnas kemikalier för att slå tillbaka förstörelsen av sina förfäders marker."},sec={{t="Industriell sprängning",b="Dvärgarnas grävarbetare vid Bael Modan använder Sodium Nitrate för att ta sig genom klippan i södra Barrens. Bael'dun-expeditionen trängde in i Stonespire-stammens förfädersmarker med jordförflyttare och sprängämnen. Gevärsskyttar, soldater och officerare bär kemikalien inne på utgrävningsområdet och i den närliggande fästningen."},{t="Vändning och vedergällning",b="Gann Stonespire höll invaderarna under uppsikt efter att de ödelagt hans stams hemland och stulit deras konstruktionsritningar. Eftersom han inte kunde inta den försvarade borgen med vanliga angrepp vänder den landsförvisade tauren deras sprängämnen mot dem. Han blandar stulet Sodium Nitrate med nitroglycerin och trämassa för att tillverka laddningar som ska skaka Bael Modans grundvalar."}},faq={{q="Vad används Sodium Nitrate till i Barrens?",a="Dvärgarna från Ironforge använder Sodium Nitrate i sprängämnen för att spränga loss stenig mark vid sin utgrävning. Gann Stonespire blandar det med nitroglycerin och trämassa för att tillverka laddningar mot Bael Modan.",al={"sodium nitrate användning","vad gör sodium nitrate"}},{q="Var kommer Sodium Nitrate ifrån?",a="Dvärgstyrkor som är stationerade vid Bael Modan i södra Barrens bär på Sodium Nitrate. Gevärsskyttar, soldater, officerare och befälhavare som Lord Cyrik Blackforge har det till hands.",al={"vem släpper sodium nitrate","var hittar man sodium nitrate"}},{q="Varför behöver Gann Stonespire den här kemikalien?",a="Gann Stonespire förlorade sin förfädersby till dvärgarnas utgrävning. Utan tung belägringsutrustning studerade han deras ritningar och började tillverka laddningar som kunde bryta igenom deras befästa ställningar med deras egna förråd.",al={"varför vill gann ha sodium nitrate","gann stonespire sprängämnen"}},{q="Är Sodium Nitrate farligt på egen hand?",a="Natriumnitrat är i sig ett oxidationsmedel och ett kemiskt salt, inte ett sprängämne som exploderar omedelbart. Blandat med en bränslekälla och stötkänsliga kemikalier som nitroglycerin blir det farligt och instabilt.",al={"är sodium nitrate ett sprängämne"}}},fx={caaef0db={q="Vad är Sodium Nitrate?",a="Sodium nitrate är ett flyktigt kemiskt ämne som de dvärgiska expeditionsstyrkorna vid Bael Modan har i lager. Dvärgarna förvarar det relativt säkert, men använder det som en viktig beståndsdel när de blandar högklassiga sprängladdningar för att spränga sig genom solid sten vid sina utgrävningsplatser. I händerna på en listig sabotör kan det däremot lika gärna användas för att rasera själva fästningen.",al={"vad är sodium nitrate","sodium nitrate i berättelsen","sodium nitrate i the barrens"}}},fp="14,175,21.313.0,25.375.1,47.185.0,36.176.0,44.233.0,39.199.0"}
P.entries["item:soft-shelled-clam-meat"] = {n="Soft-Shelled Clam Meat",s="Soft-Shelled Clam Meat är lockande bete för fisken nära Shadowprey Village. Mai'Lahii ber dig hämta lite från skeppsvraket i norr.",h="Soft-Shelled Clam Meat är lockande bete för fisken nära Shadowprey Village.",kw={"musslebete","desolace","fiske","mai'lahii","shadowprey village","soft-shelled clam meat","skeppsvrak"},sec={{t="Bete åt Mai'Lahii",b="Mai'Lahii i Shadowprey Village föredrar Soft-Shelled Clam Meat när han fiskar. Han säger att fisken inte kan motstå det och ber dig hämta tio bitar från musslorna nära skeppsvraket norr om byn."}},faq={{q="Vad används Soft-Shelled Clam Meat till?",a="Mai'Lahii i Shadowprey Village använder Soft-Shelled Clam Meat som fiskebete.",al={"användning av musselkött","musselkött med mjukt skal","musslebete"}},{q="Var hittar jag musslor med mjukt skal?",a="Musslor med mjukt skal finns nära skeppsvraket utanför kusten norr om Shadowprey Village.",al={"musslornas plats","var finns musslor","musslor vid skeppet i norr"}},{q="Vem vill ha musselköttet?",a="Mai'Lahii i Shadowprey Village ber dig hämta tio bitar Soft-Shelled Clam Meat åt honom.",al={"vem vill ha musselkött","mai'lahiis bete","vem behöver musslor"}},{q="Varför vill Mai'Lahii fiska?",a="Mai'Lahii säger att hans witch doctor rådde honom att fiska mot huvudvärken, och han mår bättre när du har hämtat musselköttet.",al={"mai'lahiis huvudvärk","varför fiska","råd från witch doctor"}}},fp="22,153,18.205.0,35.80.0,36.87.0,24.91.0,38.126.1"}
P.entries["item:solomon-s-plea-to-darkshire"] = {n="Solomon's Plea to Darkshire",s="Solomon's Plea to Darkshire är ett brådskande brev från Magistrate Solomon i Lakeshire till Lord Ello Ebonlocke. När hotet från Blackrock-orcher och gnoller växer ber brevet Darkshires ledning att skicka sin elitmilis, Night Watch, för att förstärka Lakeshires hårt pressade försvar.",h="Solomon's Plea to Darkshire är ett brådskande brev från Magistrate Solomon i Lakeshire till Lord Ello...",kw={"darkshire","duskwood","lakeshire","lord ello ebonlocke","magistrate solomon","budbärare till darkshire","night watch","redridge","solomon's plea"},ang={["faction:Alliance"]="Budskapet visar hur Grand Alliances södra områden splittras, där avlägsna bosättningar måste vädja till varandra för att överleva medan Stormwind förblir likgiltigt.",["race:Human"]="För mänskliga resenärer visar det att de som bär brevet möter samma fara vid Redridges gränsland som i Duskwoods skuggiga skogar."},sec={{t="En desperat vädjan om hjälp",b="Lakeshire står på randen till att övermannas av invaderande Blackrock-orcher, gnoller och murlocer, medan nästan inga officiella förstärkningar kommer från Stormwind. I desperation skrev Magistrate Solomon denna formella vädjan till borgmästare Ello Ebonlocke i Darkshire och bad honom skicka medlemmar av Night Watch norrut till Redridge. Dokumentet speglar hur det centrala militära stödet i södra Azeroth har brutit samman, så att enskilda mänskliga bosättningar tvingas vända sig till varandra för att överleva."},{t="Darkshires dystra läge",b="Solomons brådskande begäran visar hur isolerat Lakeshire är från de fasor som plågar dess grannar. Duskwood belägras av odöda, glupska bestar och ett genomträngande mörker, så Night Watch är redan hårt pressade av att bara hålla byns gränser. I stället för att finna en outnyttjad reserv av färska soldater upptäcker budbärarna som levererar vädjan att staden är lika hårt ansatt och helt oförmögen att avvara försvarare till Redridge."}},faq={{q="Vad är Solomon's Plea to Darkshire?",a="Det är ett officiellt brev från Magistrate Solomon i Lakeshire till Lord Ello Ebonlocke, Darkshires borgmästare. I brevet ber han enträget Darkshire att låna ut sin milis, Night Watch, för att hjälpa till att försvara Redridge mot Blackrock-orcher och gnoller.",al={"solomons brev till darkshire","vad är solomon's plea","brev från lakeshire till duskwood"}},{q="Varför ber Lakeshire Darkshire om militär hjälp i stället för Stormwind?",a="Stormwinds centralregering har i stort sett misslyckats med att förse sina avlägsna områden med tillräckligt många garnisonssoldater på grund av politisk tröghet och interna stridigheter. Magistrate Solomon har lämnats att ensam försvara Lakeshire mot allt fler angrepp och vänder sig därför till närliggande mänskliga samhällen i hopp om att få hjälp från allierade styrkor.",al={"varför be darkshire","varför inte stormwind","varför behöver solomon night watch"}},{q="Vem är Lord Ello Ebonlocke?",a="Lord Ello Ebonlocke är borgmästare och främsta civila ledare i Darkshire i Duskwood. Han styr staden och samordnar Night Watch, den civila försvarsstyrka som ska hålla fasorna i skogen stången.",al={"vem är ebonlocke","borgmästare i darkshire","lord ello"}},{q="Kan Darkshire verkligen avvara Night Watch för att hjälpa Lakeshire?",a="Nej. Duskwood är fångat i sin egen mardröm, omgivet av odöda, vilda worgen och mörk magi. Night Watch har knappt nog med folk för att hålla Darkshires gränser och kan inte avvara en enda stridskämpe för en resa till Redridge.",al={"hjälper darkshire till","kommer night watch","skickade ebonlocke vakter"}}},fx={a3b7e1d6={q="Varifrån kommer Solomon's Plea to Darkshire, och vem skrev den?",a="Brevet skrevs av Magistrate Solomon själv, ledaren i Lakeshire i Redridge. Blackrock-orcherna pressade hårt mot staden, och Stormwind kunde inte skicka kungliga förstärkningar. Därför skrev Solomon sin brådskande vädjan i Lakeshires rådhus i hopp om att få hjälp från närliggande bosättningar.",al={"vem skrev solomon's plea","solomon's plea to darkshire: ursprung"}},["5061acb5"]={q="Varför vill Lord Ello Ebonlocke ha Solomon's Plea to Darkshire?",a="Lord Ello Ebonlocke behöver brevet eftersom det redogör för Lakeshires desperata försvar och Magistrate Solomons direkta begäran om militär hjälp. Som borgmästare i Darkshire och befälhavare för Night Watch förlitar sig Ebonlocke på officiella meddelanden som detta för att förstå hoten mot deras Alliance-grannar och avgöra om staden kan avvara vakter.",al={"varför lämna över solomon's plea","varför behöver ebonlocke brevet","syftet med solomon's plea to darkshire"}}},fp="27,149,24.361.0,23.222.1,36.139.0,73.206.0,27.193.0,63.165.1"}
P.entries["item:solomon-s-plea-to-westfall"] = {n="Solomon's Plea to Westfall",s="Solomon's Plea to Westfall är en brådskande skriftlig vädjan från Magistrate Solomon i Lakeshire. Desperat efter förstärkning mot Blackrock-orcherna och gnollerna skickar Solomon meddelandet till Gryan Stoutmantle i Westfall, i hopp om att den nybildade People's Militia kan hjälpa till medan Stormwinds kungliga armé uteblir.",h="Solomon's Plea to Westfall är en brådskande skriftlig vädjan från Magistrate Solomon i Lakeshire.",kw={"gryan stoutmantle","lakeshire","magistrate solomon","peoples militia","redridge","solomons vädjan","stormwinds armé","westfall"},ang={["faction:Alliance"]="Dokumentet visar den växande administrativa handlingsförlamningen i Alliansens kärnland, där avlägsna städer måste förlita sig på lokala frivilliga i stället för kungliga trupper.",["race:Human"]="För människor i de södra provinserna visar vädjan hur hårt landsbygdens bosättningar pressas när den försvunne kungen och politisk försummelse lämnar gränslanden sårbara."},sec={{t="En desperat vädjan om hjälp",b="Hotet från Blackrock-klanen och fientliga gnoller tornar upp sig över Redridge, och Magistrate Solomon är farligt isolerad i Lakeshire. Den kungliga armén från Stormwind har av oförklarliga skäl inte anlänt i tillräckligt stort antal för att försvara regionens gränser. Solomon kan inte vänta på officiellt stöd från rikets huvudstad och skriver därför denna vädjan i ett desperat försök att få hjälp utanför den reguljära militären. Han har hört att en frivillig försvarsstyrka håller på att samlas i Elwynn, västerut, och vänder sig direkt till People's Militia."},{t="Hjälp över gränsen",b="Meddelandet är direkt adresserat till Gryan Stoutmantle, en erfaren krigare som organiserar gränsförsvaret i Westfall. Solomon hoppas att Stoutmantle kan avvara soldater som förstärkning till Lakeshire tills Stormwinds krona till slut skickar reguljära reserver. Dokumentet har anförtrotts åt en äventyrare som agerar kurir och visar hur samordningen mellan Stormwinds avlägsna territorier har fallerat. Där tvingas lokala magistrater på eget initiativ förhandla om ömsesidigt bistånd."}},faq={{q="Vad är Solomon's Plea to Westfall?",a="Det är en officiell skriftlig vädjan från Magistrate Solomon i Lakeshire, där han ber Gryan Stoutmantle och People's Militia i Westfall att skicka militära förstärkningar för att hjälpa till att försvara Redridge.",al={"vad är solomons vädjan","solomons vädjan till westfall brev","brev mellan lakeshire och westfall"}},{q="Varför ber Magistrate Solomon Westfall om hjälp i stället för Stormwind?",a="Solomon skriver att något märkligt händer med Stormwinds armé, eftersom de kungliga trupperna inte har anlänt i tillräckligt stort antal trots att faran i Lakeshire förvärras. Solomon har inte tid att vänta på kronan och vänder sig därför till varje närliggande stridsstyrka som kan hjälpa till.",al={"varför be westfall om hjälp","varför inte be stormwind","varför skicka vädjan till westfall"}},{q="Vem är Gryan Stoutmantle?",a="Gryan Stoutmantle leder People's Militia, ett lokalt försvarsförbund som organiserats av bönder och nybyggare för att skydda Westfall från Defias Brotherhood.",al={"vem är stoutmantle","gryan stoutmantles roll"}},{q="Vilka hot får Solomon att skicka brevet?",a="Lakeshire utsätts för aggressiva angrepp från Blackrock-orcherna och plundrande gnoller i hela Redridge Mountains, vilket pressar den lokala stadsvakten bortom dess förmåga.",al={"varför är lakeshire i fara","vad hotar redridge"}}},fx={["7804da1c"]={q="Varifrån kommer Solomon's Plea to Westfall, och vem skrev den?",a="Brevet skrevs av Magistrate Solomon själv i Lakeshire, den hårt ansatta staden i Redridge Mountains. Stormwind Army skickade inte de utlovade förstärkningarna för att försvara hans folk, så Solomon skrev själv detta brådskande meddelande för att vädja om hjälp från närliggande allierade.",al={"vem skrev solomon's plea to westfall","varifrån kommer solomon's plea","vem skrev solomon's plea"}},["6d6e291d"]={q="Varför vill Gryan Stoutmantle ha Solomon's Plea to Westfall?",a="Gryan Stoutmantle leder People's Militia i Westfall, och det här meddelandet berättar för honom hur allvarligt läget i Lakeshire är. Solomon hoppas att milisen kan avvara kämpar för att stärka Redridges krympande försvar medan staden väntar på besked och trupper från kung Anduins hov i Stormwind.",al={"varför lämna över solomon's plea","varför vill stoutmantle ha vädjan","vad är brevet till för"}}},fp="26,207,24.381.0,26.355.0,35.148.0,72.165.0,25.151.0,53.124.0"}
P.entries["item:soran-ruk-fragment"] = {n="Soran'ruk Fragment",s="I Blackfathom Deeps håller kultister skärvor av Soran'ruk, en krossad fängelsekula. Delarna bär fortfarande på demonisk energi från demonen som en gång var fångad inuti.",h="I Blackfathom Deeps håller kultister skärvor av Soran'ruk, en krossad fängelsekula.",kw={"blackfathom deeps","doan karhan","fel","orb of soran'ruk","soran'ruk","soranruk","twilight acolyte"},ang={["class:Warlock"]="Som häxmästare kan du använda demoniska fängelsekärl som Orb of Soran'ruk för att kanalisera rå demonisk energi utan att kuva en demon direkt."},sec={{t="Ett krossat fängelse",b="Soran'ruks fängelsekula slogs sönder efter att demonen fallit i onåd hos Burning Legion. Demoner som misshagar sina herrar kan få sina andar förseglade i kulor, som sedan ges till demoniska magiker som kraftkällor. Twilight's Hammer-kultisterna i de översvämmade ruinerna av Blackfathom Deeps har mindre skärvor från ena halvan av kulan. De utnyttjar den kvardröjande demoniska essensen i sina egna ritualer."},{t="Återuppbyggnad i The Barrens",b="Varje fragment bär fortfarande spår av den fängslade demonens livskraft. Doan Karhan, en tillbakadragen lärd i södra Barrens, har ägnat ett helt liv åt att studera demoniska kärl och äger en liknande kula, Orb of Zargain. En ambitiös häxmästare kan ta med sig tre små fragment och den större biten som finns i Silverpine. Han kan smida samman reliken igen till ett kraftfullt redskap."}},faq={{q="Vad är Soran'ruk?",a="Soran'ruk var en demon i Burning Legion som föll i onåd hos dess ledare. Som straff slets dess ande ut och fångades i en kristallkula, där den tjänade dödliga häxmästare och magiker som energikälla.",al={"vem är soranruk","soran'ruks historia","är soranruk en demon"}},{q="Var finns skärvorna?",a="Twilight Acolytes bär de mindre skärvorna genom de väldiga salarna i Blackfathom Deeps längs The Zoram Strand.",al={"var hittar man soran'ruk fragment","vem släpper soran'ruk-skärvor","soran'ruk fragment plats"}},{q="Varför har Twilight's Hammer skärvorna?",a="Twilight's Hammer-kultisterna samlar skärvorna eftersom de fortfarande innehåller den fångade demonens magiska essens. De använder korrumperade artefakter för att ge kraft åt sina mörka ritualer och kanalisera förbjuden magi.",al={"varför har kultister den","twilight's hammer soran'ruk"}},{q="Vem kan återställa Orb of Soran'ruk?",a="Doan Karhan kan återställa Orb of Soran'ruk. Den ensamme eremiten bor i södra Barrens nära gränsen till Thousand Needles och studerar och smider om Burning Legions demoniska kulor.",al={"vem lagar klotet","var lämnar man in soran'ruk fragment","doan karhan klot"}}},fx={["49c59cce"]={q="Varifrån kommer Soran'ruk Fragments, och vem tillverkade dem?",a="De är splittrade rester av Orb of Soran'ruk, ett demoniskt kärl som smiddes av Burning Legion. När demoner faller i onåd fängslar Legion deras andar i sådana klot och överlämnar dem till sina magiker och häxmästare. Klotet Soran'ruk splittrades senare, och de mindre skärvorna hamnade hos Twilight's Hammer-akolyterna i Blackfathom Deeps.",al={"soran'ruk fragments ursprung","vem tillverkade soran'ruk fragments","varifrån kommer soran'ruk fragments"}},["5e1e8c12"]={q="Varför vill någon ha Soran'ruk Fragments?",a="Trots att skärvorna är trasiga sjunger de fortfarande av den fängslade demonens väsen och kraft. Eremithäxmästaren Doan Karhan i The Barrens har vigt sitt liv åt att studera och återskapa Legion-klot. Om du tar med de mindre skärvorna och den stora skärvan från Shadowfang Keep kan han smida om Orb of Soran'ruk till ett kraftfullt redskap för ditt hantverk.",al={"varför samla soran'ruk fragments","vem vill ha soran'ruk fragments","varför behövs soran'ruk fragments"}}},fp="18,150,18.407.0,29.373.1,18.217.0,32.115.0,49.168.0,37.191.0"}
P.entries["item:southsea-treasure"] = {n="Southsea Treasure",s="Southsea Treasure är en värdefull skatt som förvaras djupt nere i lastrummet på Southsea Freebooter-fartyget Tide Razor. Wrenix the Wretched i Ratchet vill åt den, och att hämta den sätter unga tjuvars låsdyrknings- och infiltrationsförmåga på prov.",h="Southsea Treasure är en värdefull skatt som förvaras djupt nere i lastrummet på Southsea Freebooter-fartyget...",kw={"e.c.a.c.","låsdyrkning","polly","ratchet","shattered hand","southsea treasure","tide razor","wrenix the wretched"},ang={["class:Rogue"]="Att återta Southsea Treasure är ett mandomsprov för blivande skurkar. Det ger både praktisk övning i låsdyrkning och en introduktion till den skumma organisationen Shattered Hand.",["faction:Horde"]="Southsea Freebooters trakasserar regelbundet handeln kring The Barrens och hamnen i Ratchet. Därför är det välkommet för de lokala myndigheterna när någon stjäl deras viktigaste skatt."},sec={{t="En livsfarlig kupp",b="Piratskeppet Tide Razor ligger för ankar längs Merchant Coast, söder om Ratchet, och fungerar som framskjuten bas och övningsplats för Southsea Freebooters. Djupt nere i fartygets nedersta lastrum finns en eftertraktad mängd plundringsgods som kallas Southsea Treasure. Wrenix the Wretched, en goblinskurk med bas i Ratchet, ser den som det ultimata provet för blivande ficktjuvar. Enligt Wrenix kom de fem senaste agenterna som skickades för att stjäla kistan tillbaka i bitar, på grund av de vaksamma piraterna ombord och en förvånansvärt våldsam väktare som vaktar lastrummet."},{t="Pollys minnessak",b="Tjuvar som lyckas ta sig förbi piraternas tränare och dyrka upp låset på kistan möts av en våldsam överraskning. Den verkliga Southsea Treasure ligger inte löst i kistan, utan vaktas av Polly, en onaturligt fientlig papegoja. Det enda sättet att besegra den våldsamma fågeln, ofta med hjälp av goblinteknik som Wrenix E.C.A.C.-anordning, är att få loss skatten och föra den tillbaka till Ratchet oskadd."}},faq={{q="Var finns Southsea Treasure?",a="Skatten finns ombord på Tide Razor, ett Southsea Freebooter-fartyg som ligger för ankar längs kusten söder om Ratchet i The Barrens. Den finns i det nedersta lastrummet, under piraternas träningsutrymmen.",al={"var finns skatten","var ligger tide razor","hur hittar man southsea treasure"}},{q="Vem vill ha Southsea Treasure?",a="Wrenix the Wretched, en skrupelfri goblin i Ratchet, anlitar hemliga agenter för att infiltrera skeppet och hämta bytet åt honom.",al={"vem ger uppdraget","vem är wrenix","vem vill ha den"}},{q="Varför är kistan tom när den dyrkas upp?",a="När låset på skattkistan dyrkas upp dyker Polly upp, en monstruöst aggressiv papegoja som vaktar lastrummet. Det är först när du besegrar Polly som du får Southsea Treasure.",al={"var kommer polly ifrån","varför dök polly upp","varför ligger skatten inte i kistan"}},{q="Vad är en E.C.A.C. och varför behövs den?",a="E.C.A.C. är en experimentell goblinanordning som Wrenix the Wretched tillhandahåller. Den är utformad för att försvaga ovanligt våldsamma luftburna hot, närmare bestämt den dödliga väktarpapegojan Polly, som lurar i piratskeppets lastrum.",al={"vad är ecac","hur besegrar man polly","fientlig papegoja"}},{q="Vad använder Southsea Freebooters skeppet till?",a="Tide Razor fungerar som samlingsplats och tillhåll för Southsea Freebooters. På den andra nivån finns övningskistor med lås där besättningen tränar sina ficktjuvar.",al={"vad är tide razor","pirattillhåll i the barrens","southsea-skeppets lastrum"}}},fx={c9f033cd={q="Vad är Southsea Treasure?",a="Southsea Treasure är bytet som Southsea Freebooters har samlat på sig ombord på sitt skepp, Tide Razor, som ligger för ankar utanför kusten i The Barrens. Det förvaras djupt nere i skeppets lastrum och vaktas av den ökända, våldsamma piratpapegojan Polly. Skatten består av orättmätiga rikedomar som kaparna samlat in genom sina räder längs The Merchant Coast.",al={"vad är southsea treasure","southsea treasure: föremål","vad är det för skatt i southsea treasure"}}},fp="17,189,14.462.0,16.299.1,39.172.0,32.139.0,35.155.1,41.195.0,50.159.0"}
P.entries["item:spectral-comb"] = {n="Spectral Comb",s="Spectral Comb är ett eteriskt redskap för hårvård som används för att interagera med The Restless Dead i Duskwood. Den är utformad för att glida genom ogripbara former och förs till den sorgsna anden Blind Mary för att samla spökhårstrån.",h="Spectral Comb är ett eteriskt redskap för hårvård som används för att interagera med The Restless Dead i...",kw={"blind mary","kam","darkshire","duskwood","spöke","ghost hair thread","spectral comb"},ang={["faction:Alliance"]="När du beger dig söder om Darkshire med kammen blir du skarpt påmind om det tragiska öde som drabbade Duskwoods tidigare bosättare.",["profession:Tailoring"]="Spectral Comb visar att sömnad på mörka platser kräver ovanliga insamlingsmetoder: eteriska fibrer hämtas från villiga spöken i stället för genom traditionell klippning."},sec={{t="Ett redskap för rastlösa döda",b="Vanliga redskap kan inte röra vid eller vårda en ande, så det är nästan omöjligt för dödliga hantverkare att samla eteriska material. Spectral Comb är särskilt utformad för att användas på vålnader och glider genom lockar som annars inte går att ta på. Den förs söder om Darkshire till den förfallna gården där den gråtande vålnaden Blind Mary jämrar sig i ensamhet. Mary finner tröst i den välbekanta handlingen att kamma sitt förstörda hår och använder gärna kammen, så att de spektrala fibrer som behövs för att väva Ghost Hair Thread blir kvar."}},faq={{q="Vad används Spectral Comb till?",a="Kammen ges till Blind Mary, en gråtande vålnad som bor söder om Darkshire. När hon använder den för att kamma håret samlar den eteriska hårstrån som senare kan spinnas till övernaturlig tråd.",al={"spectral combs syfte","varför behöver jag spectral comb","vad gör kammen"}},{q="Vem är Blind Mary?",a="Blind Mary är en plågad ande som hemsöker ett övergivet hus i kullarna söder om Darkshire. Driven till vansinne av en tragedi slet hon ut sina egna ögon och är fortfarande livrädd för att andra ska tycka att hon är motbjudande även efter döden.",al={"blind marys bakgrund","vem är spöket med kammen","blind mary"}},{q="Varför går det inte att använda en vanlig kam?",a="Andar kan inte beröras med vanliga fysiska redskap utan särskild magi eller förtrollningar. Spectral Comb är särskilt utformad för att komma åt en vålnads ogripbara hår.",al={"varför spectral comb","vanlig kam spöke"}}},fx={e893aa2f={q="Vad är Spectral Comb?",a="Spectral Comb är ett eteriskt hårvårdsredskap som är särskilt förtrollat för att påverka det okroppsliga. Vanliga redskap skulle gå rakt genom ett spöke utan verkan, men den här kammen kan faktiskt röra vid, reda ut och samla upp en vålnads hårstrån.",al={"vad är spectral comb","spectral comb"}}},fp="13,95,24.375.0,35.177.0,18.186.0,37.119.0"}
P.entries["item:spells-of-shadow"] = {n="Spells of Shadow",s="Under Orgrimmar finns Spells of Shadow i Searing Blade-kultisternas händer. De Fördömdas ledare i Undercity vill få tillbaka grimoaren.",h="Under Orgrimmar finns Spells of Shadow i Searing Blade-kultisternas händer.",kw={"incantations from the nether","ragefire chasm","searing blade","spells of shadow","sylvanas","kraften att förgöra","undercity","varimathras"},ang={["class:Warlock"]="Som häxmästare ser du hur Searing Blade-kultister brukar skuggans och Netherns konster med demoniska gåvor från Legionen.",["race:Undead"]="Som odöd hjälper du Lady Sylvanas att lägga beslag på farlig demonisk kunskap under Orgrimmar och stärka Undercity mot Scourge."},sec={{t="Searing Blades böcker",b="Searing Blade-kultister förvarar Spells of Shadow bland sina bevakade skatter i Ragefire Chasm. Den splittrade kulten har band till Shadow Council, och dess medlemmar utövar mörka riter som demonmästarna i Burning Legion har skänkt dem. Boken innehåller skuggmagi och felmagi. Kultister och häxmästare håller den nära medan de smider planer under Horden i Durotar."},{t="Den mörka damens ambition",b="Ryktet om Searing Blades demoniska gåvor nådde Undercitys kungliga kvarter. Lady Sylvanas Windrunner och hennes dreadlordlöjtnant, Varimathras, beslöt att relikerna gick till spillo hos kultister med mindre visioner. Varimathras skickar Hordens äventyrare in i Ragefire Chasm för att lägga beslag på Spells of Shadow och dess följeslagare, Incantations from the Nether. Deras kraft är tänkt att tjäna De Fördömdas sak mot Scourge och Lich King."}},faq={{q="Vad är Spells of Shadow?",a="Spells of Shadow är en trollformelsbok som Searing Blade-kultisterna har i Ragefire Chasm. Den innehåller skuggmagi skänkt av Burning Legion.",al={"boken spells of shadow","vad är spells of shadow","skuggbok rfc"}},{q="Vem vill ha den här boken?",a="Varimathras vill ha boken åt Lady Sylvanas Windrunner. Han är hennes dreadlordrådgivare och bor i Undercitys Royal Quarter.",al={"vem behöver spells of shadow","vem lämnar in spells of shadow","uppdragsgivare för spells of shadow"}},{q="Var finns boken?",a="Searing Blade-kultister och häxmästare bär boken i Ragefire Chasm, de eldiga grottorna under Orgrimmar.",al={"spells of shadow plats","var hittar man spells of shadow","hur får man spells of shadow"}},{q="Varför vill de Fördömda ha den här grimoaren?",a="Lady Sylvanas anser att Legionens mörka gåvor hör hemma hos De Fördömda, inte hos mindre kultister. Hon vill använda magin för att stärka De Fördömda mot Scourge och Lich King.",al={"varför vill sylvanas ha boken","varför vill varimathras ha spells of shadow"}}},fp="16,148,26.335.0,24.437.0,29.130.0,20.133.0,28.114.0,39.193.0"}
P.entries["item:spirit-of-silverpine-charts"] = {n="Spirit of Silverpine Charts",s="Spirit of Silverpine Charts är fartygets kartor, som nu söks i vraket i Arathi Highlands. First Mate Nilzlix vill säkra dem innan informationen når nyfikna ögon.",h="Spirit of Silverpine Charts är fartygets kartor, som nu söks i vraket i Arathi Highlands.",kw={"arathi highlands","kartor","bärgning på djupt vatten","first mate nilzlix","fleet master seahorn","spirit of silverpine","spirit of silverpine charts"},sec={{t="Strandad i viken",b="Vrakets kartor efterfrågas tillsammans med fartygets loggbok, så First Mate Nilzlix ber dig hämta båda. Besättningen säger att Spirit of Silverpine gick på grund på ett tempel i revet när tidvattnet sjönk. Kartorna innehåller information som besättningen fruktar kan hamna i fiendens händer, och Fleet Master Seahorn väntar sig att de förs tillbaka till Booty Bay."}},faq={{q="Vad är Spirit of Silverpine Charts?",a="De är sjökort som tillhör Spirit of Silverpine, ett fartyg som förliste i Arathi Highlands.",al={"silverpine-kartor","spirit-kartor"}},{q="Var hittar jag kartorna?",a="Spirit of Silverpine Charts söks i vraket efter Spirit of Silverpine i Arathi Highlands.",al={"var kartorna finns","silverpine-kartornas plats"}},{q="Vem vill ha kartorna?",a="First Mate Nilzlix vill att kartorna och loggböckerna från Spirit of Silverpine och Maiden's Folly bärgas.",al={"vem behöver kartorna","nilzlix kartor"}},{q="Varför vill de ha kartorna?",a="Besättningen fruktar att kartorna kan röja information för nyfikna ögon om de lämnas kvar.",al={"varför kartorna är viktiga","vad kartorna innehåller"}},{q="Hur sjönk Spirit of Silverpine?",a="Besättningen säger att Spirit of Silverpine gick på grund på ett tempel i revet när tidvattnet började sjunka.",al={"silverpine-vraket","varför fartyget sjönk"}},{q="Vart förs kartorna?",a="De bärgade kartorna ska säkras åt Fleet Master Seahorn och befälet i Booty Bay.",al={"kartor till booty bay","vem får kartorna"}}},fp="27,187,19.336.0,41.98.0,28.110.0,21.108.0,26.81.0,38.105.0,33.99.0"}
P.entries["item:spirit-of-silverpine-log"] = {n="Spirit of Silverpine Log",s="Spirit of Silverpine Log är kaptenens anteckningar från ett skepp som förliste på revet i Arathi Highlands. Sjökorten och loggboken innehåller information som besättningen vill hålla borta från fienden.",h="Spirit of Silverpine Log är kaptenens anteckningar från ett skepp som förliste på revet i Arathi Highlands.",kw={"arathi highlands","booty bay","kaptenens loggbok","bärgning på djupt vatten","first mate nilzlix","fleet master seahorn","skeppsvrak","spirit of silverpine","spirit of silverpine log"},sec={{t="De förlista skeppen",b="First Mate Nilzlix vill att skeppets loggbok och sjökort bärgas innan besättningen lämnar viken. Spirit of Silverpine och Maiden’s Folly gick på grund när tidvattnet sjönk och stötte mot det som verkade vara ett tempel på revet. Båda skeppen sjönk snabbt. Deras dokument är nu viktiga för befälet i Booty Bay, som fruktar att informationen kan nå fienden."}},faq={{q="Vad är Spirit of Silverpine Log?",a="Det är loggboken från Spirit of Silverpine, ett av skeppen som förliste i Arathi Highlands.",al={"silverpine-loggbok","skeppsloggbok","kaptenens loggbok"}},{q="Var sjönk Spirit of Silverpine?",a="Spirit of Silverpine gick på grund vid det som verkade vara ett tempel på revet i en vik i Arathi Highlands.",al={"var ligger spirit of silverpine","spirit of silverpine-vraket","skepp i arathi highlands"}},{q="Varför vill First Mate Nilzlix ha loggboken?",a="First Mate Nilzlix vill att Spirit of Silverpines loggbok och sjökort bärgas innan besättningen ger sig av, så att informationen inte hamnar i fiendens händer.",al={"varför hämta loggboken","vad vill nilzlix ha","bärga spirit of silverpine log"}},{q="Vad hände med Spirit of Silverpine?",a="När tidvattnet sjönk gick Spirit of Silverpine på grund vid det som verkade vara ett tempel på revet och sjönk snabbt.",al={"spirit of silverpine-vraket","vad hände med skeppet","hur sjönk skeppet"}},{q="Varför är sjökorten och loggböckerna viktiga?",a="Besättningen fruktar att dokumenten kan hamna i fiendens händer, och Fleet Master Seahorn skulle hålla dem ansvariga om det hände.",al={"varför bärga sjökorten","fiendens händer","dokument i booty bay"}}},fp="24,168,17.358.0,37.111.0,40.113.0,41.155.0,42.117.0,38.126.0"}
P.entries["item:split-bone-necklace"] = {n="Split Bone Necklace",s="Split Bone Necklaces är troféer tagna från Skullsplitter-trollen i Stranglethorn Vale. Kin'weelay ber om dem för att hjälpa Darkspears i deras långa krig.",h="Split Bone Necklaces är troféer tagna från Skullsplitter-trollen i Stranglethorn Vale.",kw={"darkspear","grom'gol base camp","kin'weelay","halsband","skullsplitter","split bone necklace","stranglethorn vale","troll"},ang={["race:Troll"]="Som troll ser du ett gammalt krig mellan stammar föras vidare av en annan. Darkspears bor inte längre i Stranglethorn, men Kin'weelay säger att de fortfarande är bundna till konflikten med Skullsplitters."},sec={{t="Darkspears räkning",b="Från Grom'gol Base Camp skickar Kin'weelay dig sydost mot Skullsplitter-stammen. Deras krigare bor bland trollruinerna i Stranglethorn Vale, och Darkspears har stridit mot dem i åratal. Darkspears bor inte längre i dalen, men Kin'weelay säger att de fortfarande är bundna till konflikten. Ta halsbanden till honom, så hjälper dina dåd hans folk."}},faq={{q="Vem vill ha Split Bone Necklaces?",a="Kin'weelay från Darkspear-stammen ber dig ta Split Bone Necklaces till honom vid Grom'gol Base Camp.",al={"vem vill ha halsbanden","kin'weelay halsband","halsband till vem"}},{q="Vem bär de här halsbanden?",a="Skullsplitter-trollen bär Split Bone Necklaces. Kin'weelay vill ha dem som troféer i Darkspears krig mot Skullsplitters.",al={"varifrån kommer halsbanden","betydelsen av split bone necklace","skullsplitter-halsband"}},{q="Varför vill Kin'weelay ha dem?",a="Kin'weelay vill ha halsbanden för att hjälpa Darkspears i deras långa konflikt med Skullsplitter-stammen.",al={"varför samla split bone","varför behöver kin'weelay dem","darkspear-kriget"}},{q="Var finns Skullsplitters?",a="Skullsplitters bor sydost om Grom'gol Base Camp, bland trollruinerna i Stranglethorn Vale.",al={"var hittar man skullsplitters","skullsplitters plats","trollruiner"}},{q="Hur många halsband ber Kin'weelay om?",a="Kin'weelay ber dig ta med tjugofem Split Bone Necklaces till honom.",al={"antal halsband","hur många split bone","25 halsband"}}},fp="19,158,17.364.0,35.106.0,26.137.0,30.105.0,29.100.0,43.66.0"}
P.entries["item:spotted-sunfish"] = {n="Spotted Sunfish",s="Spotted Sunfish är sötvattensfiskar som hör hemma i Lake Everstill i Redridge Mountains. De är kända lokalt för sin smak och är en viktig handelsvara vid Lakeshires bryggor, men den växande murloc-plågan gör det farligt att få tag på dem.",h="Spotted Sunfish är sötvattensfiskar som hör hemma i Lake Everstill i Redridge Mountains.",kw={"dockmaster baren","lake everstill","lakeshire","murloc","redridge mountains","sälja fisk","spotted sunfish"},ang={["profession:Cooking"]="Inhemska sötvattensfiskar som Spotted Sunfish utgör grunden för Lake Everstills matkultur och är därför ett stående inslag på värdshusborden i Redridge."},sec={{t="En uppskattad fångst",b="Lake Everstill har länge varit känt för sina Spotted Sunfish, som betingar ett stadigt pris bland både lokala köpmän och besökare. Dockmaster Baren håller igång en stadig handel med dem vid Lakeshires bryggor och förser en pressad stad med mat och handel. De aggressiva murloc-stammarna som stryker omkring på grundvattnet har dock stört det vanliga fisket. De lägger ofta undan egna fångster som äventyrare måste återta med våld."}},faq={{q="Var hittar man Spotted Sunfish?",a="De trivs i vattnen i Lake Everstill i Redridge Mountains. Fiskare kan fånga dem direkt i sjön, men de lokala murlocerna skördar dem också ständigt. Därför är murlocläger längs stranden bra platser att leta efter dem.",al={"var man hittar spotted sunfish","spotted sunfish plats","fisk i lake everstill"}},{q="Vem köper eller behöver Spotted Sunfish?",a="Dockmaster Baren på Lakeshires bryggor köper partier av Spotted Sunfish. Han bedriver handel med delikatessen och betalar alla som vill komma med ett färskt lager.",al={"vem vill ha spotted sunfish","dockmaster baren fisk","uppdrag sälja fisk"}},{q="Varför bär murlocer på de här fiskarna?",a="Murlocer som lever längs Lake Everstill samlar och tjuvfiskar områdets djurliv för att föda sina växande stammar. De drar upp sunfish ur sjön precis som mänskliga fiskare och förvarar dem i sina läger längs de grunda stränderna.",al={"murloc spotted sunfish","varför murlocer tappar fisk"}},{q="Kan du få tag på dem utan att fiska?",a="Ja. Dockmaster Baren berättar att resande utan fiskespö helt enkelt kan besegra de fientliga murlocer som håller till längs Lake Everstills stränder och ta fisken de har samlat på sig.",al={"få sunfish utan fiskespö","sunfish utan fiskespö"}}},fx={["723094c5"]={q="Vad är Spotted Sunfish?",a="Spotted Sunfish är en uppskattad sötvattensfisk som hör hemma i Lake Everstill i Redridge Mountains. Den är känd i hela regionen för sin smak och sitt handelsvärde, trivs i sjöns djupa vatten och är en stapelvara för Lakeshires fiskare samt en viktig födokälla för traktens murlocs.",al={"vad är spotted sunfish","information om spotted sunfish","spotted sunfish i berättelsen"}},["1a933976"]={q="Varifrån kommer Spotted Sunfish?",a="Spotted Sunfish finns naturligt i det svala vattnet i Lake Everstill i Redridge Mountains. De tillverkas eller odlas inte, utan är vilda fiskar som fångas direkt ur sjön. Du kan meta dem vid bryggorna och stränderna eller ta tillbaka dem från traktens murloc-tjuvfiskare.",al={"spotted sunfish: ursprung","varifrån kommer spotted sunfish","spotted sunfish: källa"}}},fp="15,149,14.293.0,32.145.0,34.109.0,36.126.0,36.137.0"}
P.entries["item:spy-s-report"] = {n="Spy's Report",s="Spy’s Report av Marg Nighteye är en orkspions skrift som hittats nära Swamplight Manor i Dustwallow Marsh. Captain Garran Vimes i Theramore ombeds läsa den eftersom han kan orkiska.",h="Spy’s Report av Marg Nighteye är en orkspions skrift som hittats nära Swamplight Manor i Dustwallow Marsh.",kw={"captain vimes","dustwallow marsh","horde-spioner","marg nighteye","orkspion","spy’s report","swamplight manor","theramore","witch hill"},ang={["faction:Alliance"]="Rapporten varnar för Horde-spioner nära Theramore, en bosättning tillhörande Alliance vid Dustwallow Marshs kust."},sec={{t="En begravd rapport",b="Nära Witch Hill döljer lös jord intill Swamplight Manor en rapport skriven av Marg Nighteye. Skriften har koppling till orkspioner nära Theramore, och Captain Garran Vimes ombeds undersöka den. Han kan mer orkiska än de flesta i Theramore."}},faq={{q="Vem skrev Spy’s Report?",a="Marg Nighteye skrev Spy’s Report.",al={"vem skrev rapporten","rapportens författare","marg nighteyes rapport"}},{q="Var hittades rapporten?",a="Spy’s Report begravdes i lös jord intill Swamplight Manor vid Witch Hill i Dustwallow Marsh.",al={"var rapporten hittades","spionrapportens plats","rapport i lös jord"}},{q="Vem bör läsa rapporten?",a="Captain Garran Vimes i Theramore Isle bör läsa rapporten eftersom han kan mer orkiska än de flesta.",al={"vem får rapporten","captain vimes rapport","rapport till vimes"}},{q="Vad handlar rapporten om?",a="Rapporten är en orkspions skrift och kan berätta för Captain Garran Vimes om Horde-spioner nära Theramore.",al={"vad innehåller rapporten","orkspionsrapport","horde-spioner theramore"}}},fp="12,186,15.237.0,29.39.0,27.102.0,27.103.0,29.104.0"}
P.entries["item:stable-ectoplasm"] = {n="Stable Ectoplasm",s="Nära spökena i Eastern Plaguelands kan en Ectoplasmic Distiller samla in Stable Ectoplasm. Mux Manascrambler behöver det för att nå andar vars själar inte har lämnat den här världen.",h="Nära spökena i Eastern Plaguelands kan en Ectoplasmic Distiller samla in Stable Ectoplasm.",kw={"bansheer","eastern plaguelands","ektoplasma","ectoplasmic distiller","gadgetzan","spöken","mux manascrambler","northdale","stable ectoplasm"},ang={["profession:Engineering"]="Mux kallar Ectoplasmic Distiller ett fint ingenjörsarbete. Hans arbete visar hur goblinernas manicker kan användas för att studera andevärlden."},sec={{t="Bland spökena",b="Mux Manascrambler ber om Stable Ectoplasm från spöken och bansheer i Eastern Plaguelands. Han behöver det tillsammans med två andra sorters ektoplasma, som samlas in i Silithus och Winterspring. Destillatorn utvinner ämnet ur okroppsliga odöda i närheten. Northdale är ett bra ställe att hitta dem på."}},faq={{q="Vad är Stable Ectoplasm?",a="Stable Ectoplasm är ett ämne som samlas in från spöken och bansheer i Eastern Plaguelands med en Ectoplasmic Distiller.",al={"stable ectoplasm","vad är ektoplasma","spökgegga"}},{q="Vem behöver Stable Ectoplasm?",a="Mux Manascrambler i Gadgetzan behöver Stable Ectoplasm, tillsammans med Scorched Ectoplasm och Frozen Ectoplasm, i sitt arbete med Ectoplasmic Distiller.",al={"vem vill ha stable ectoplasm","mux ektoplasma","vad behöver mux"}},{q="Var hittar jag Stable Ectoplasm?",a="Spöken och bansheer i Eastern Plaguelands ger Stable Ectoplasm. Northdale är ett bra ställe att hitta dem på.",al={"stable ectoplasm plats","var finns ektoplasma","spöken i northdale"}},{q="Varför vill Mux ha ektoplasma?",a="Mux hoppas kunna använda ektoplasmans övernaturliga energi för att nå andar vars själar ännu inte helt har lämnat den här världen.",al={"varför ektoplasma","mux plan","nå andar"}}},fp="16,179,16.303.0,25.123.0,27.141.0,34.110.0,28.118.0"}
P.entries["item:stalker-claws"] = {n="Stalker Claws",s="Stalker Claws är klorna från präriejägare som strövar över The Rolling Plains i Mulgore. Taurenschamaner använder dem som viktiga delar när de snidar traditionella reningstotemer för att rena förorenade vattenkällor.",h="Stalker Claws är klorna från präriejägare som strövar över The Rolling Plains i Mulgore.",kw={"reningstotem","mulgore","mull thunderhorn","präriejägare","stalker claws","thunderhorn-totem","vattenkälla"},ang={["class:Shaman"]="Klor från vilda slättrovdjur fångar naturens vilda renhet och är ett oumbärligt material för att binda samman och stärka reningstotemer.",["race:Tauren"]="Att samla in klorna hjälper din stam att fullgöra sin heliga plikt att återställa de heliga vattnen som förgiftats av vårdslösa inkräktare från industrin."},sec={{t="Slättens rovdjur",b="Mulgore gräsbevuxna stäpper är hem åt dödliga rovdjur, däribland de smygande präriejägarna. Dessa bestar överlever med rå instinkt och dödlig precision, en viktig balans i Moder Jordas skapelse. Mull Thunderhorn vill läka det fördärvade landet och behöver klorna, inte av illvilja mot djuren, utan för att deras rena, naturliga jaktvildhet har den andliga kraft som krävs för att motverka konstgjord förorening."},{t="Reningen av källorna",b="När gobliners företag började borra och gräva efter malm i centrala Kalimdor sipprade kemiska gifter djupt ner i grundvattnet som försörjer taurenfolkets förfäders vattenkällor. I synnerhet Thunderhorn Water Well föll offer för en vidrig förorening. Genom att binda samman Stalker Claws och Cougar Claws i en Thunderhorn Cleansing Totem skapar stamschamaner en andlig kanal som kan skura bort smutsen och det onaturliga slammet från jordens naturliga källor."}},faq={{q="Var hittar man Stalker Claws?",a="De samlas in genom jakt på präriejägare bland Mulgore gräsbevuxna kullar, främst öster och väster om Bloodhoof Village.",al={"var hittar man stalker claws","vem släpper stalker claws","stalker claws källa"}},{q="Varför behöver Mull Thunderhorn klorna?",a="Mull Thunderhorn använder klorna tillsammans med klor från slättens pumor för att tillverka en Thunderhorn Cleansing Totem. De inhemska jägarnas medfödda renhet och styrka behövs för att rena de förgiftade vattenkällorna.",al={"varför samla stalker claws","mull thunderhorns syfte","användning av stalker claws"}},{q="Varför är Thunderhorn Water Well förorenad?",a="Källan lider av onaturliga industriföroreningar från goblinernas verksamhet i Mulgore, som rubbar den naturliga balansen och förgiftar den lokala grundvattennivån.",al={"vem förgiftade källan","varför är thunderhorn-källan förorenad","förorening i thunderhorn"}},{q="Vad händer när klorna har samlats in?",a="När klorna har samlats in snidar Mull dem till en reningstotem, som sedan måste bäras direkt till Thunderhorn Water Well för att driva bort den kvarvarande föroreningen.",al={"what comes next","nästa steg efter klorna","ritual för reningstotem"}}},fx={a496bd75={q="Vad är Stalker Claws?",a="Stalker Claws är de naturliga klor som tas från prairie stalkers, våldsamma kattdjur som jagar på Mulgore-slätterna. För en utomstående är de bara enkla jakttroféer, men tauren-schamaner ser dem som uttryck för varelsens naturliga jaktinstinkt och samhörighet med landet.",al={"vad är stalker claws","stalker claws: föremål","stalker claw"}}},fp="13,148,23.364.0,19.338.0,33.136.0,43.173.0,42.141.0,42.152.0"}
P.entries["item:star-of-xil-yeh"] = {n="Star of Xil'yeh",s="Star of Xil'yeh är en mäktig ädelsten som sägs låta sin bärare tala med varelser från andra världar. Gerrig Bonegrip söker den bland tre reliker i Ironforge.",h="Star of Xil'yeh är en mäktig ädelsten som sägs låta sin bärare tala med varelser från andra världar.",kw={"ädelsten","gerrig bonegrip","hand of dagun","legacy heart","andra världar","star of xil'yeh","xil'yeh","yagyin's digest"},ang={["faction:Alliance"]="Som Alliance-äventyrare kan du bära den här reliken till Gerrig Bonegrip i Ironforge, där han söker den åt sin orden."},sec={{t="En eftersökt relik",b="I Ironforge ber Gerrig Bonegrip om Star of Xil'yeh som en av tre reliker han behöver. Han söker föremålen för att byta till sig Yagyin's Digest, en bok knuten till början på ett nytt kapitel för hans orden."}},faq={{q="Vad gör Star of Xil'yeh?",a="Star of Xil'yeh sägs låta sin bärare tala med varelser från andra världar.",al={"star of xil'yeh kraft","vad är stjärnädelstenen","xil'yeh-ädelsten"}},{q="Varför vill Gerrig Bonegrip ha stjärnan?",a="Gerrig behöver Star of Xil'yeh tillsammans med Hand of Dagun och Legacy Heart. Han söker de tre relikerna i utbyte mot Yagyin's Digest.",al={"varför gerrig vill ha stjärnan","bonegrip stjärna","gerrigs reliker"}},{q="Var kan stjärnan hittas?",a="Grel'borg the Miser i Alterac Mountains har Star of Xil'yeh.",al={"stjärnans plats","var finns xil'yeh","hitta stjärnan"}},{q="Vad är Yagyin's Digest?",a="Yagyin's Digest är en bok som Gerrig Bonegrip erbjuder i utbyte mot tre reliker. Han tror att den kan hjälpa hans orden att inleda ett nytt kapitel.",al={"yagyin digest","varför bonegrip vill ha digest","bonegrips bok"}},{q="Vilka är de andra relikerna Gerrig söker?",a="Förutom Star of Xil'yeh ber Gerrig om Hand of Dagun och Legacy Heart.",al={"hand och hjärta","tre reliker","bonegrips föremål"}}},fp="15,153,14.201.0,33.80.0,39.141.0,28.69.0,24.137.0,39.87.0"}
P.entries["item:stave-of-equinex"] = {n="Stave of Equinex",s="Stave of Equinex är en laddad stav knuten till Equinex Monolith i Feralas. Dess kraft behövs för att öppna den urgamla stenen.",h="Stave of Equinex är en laddad stav knuten till Equinex Monolith i Feralas.",kw={"byltan","equinex monolith","feralas","imbel","lahassa","morrow stone","ruins of ravenwind","samha","stave of equinex","troyas stav"},sec={{t="Den tysta monoliten",b="Vid Ruins of Ravenwind i Feralas kan Troyas stav förvandlas till Stave of Equinex. Fyra lågor brinner fortfarande i närheten: Samha, Imbel, Byltan och Lahassa. Deras essenser väcker staven till liv intill Equinex Monolith. Staven är en nyckel, och stenmonumentet rymmer något."},{t="En kraft som falnar",b="När den laddade Stave of Equinex vidrör monoliten öppnas en liten dörr i dess kalla yta. Ljusstrålar fyller ruinerna när den dolda artefakten tas ut. Stavens kraft börjar sedan falna, och Troyas Moonbreeze vid Feathermoon Stronghold kan undersöka fyndet."}},faq={{q="Vad gör Stave of Equinex?",a="Stave of Equinex är en nyckel som öppnar Equinex Monolith i Ruins of Ravenwind.",al={"stavens syfte","vad är equinex-staven"}},{q="Hur förändras Troyas stav?",a="Essenserna från de fyra lågorna Samha, Imbel, Byltan och Lahassa laddar Troyas stav intill Equinex Monolith.",al={"ladda troyas stav","skapa equinex-staven"}},{q="Var finns Equinex Monolith?",a="Equinex Monolith står bland Ruins of Ravenwind i Feralas, väster om Dream Bough.",al={"monolitens plats","var finns equinex"}},{q="Vad finns inuti monoliten?",a="En liten dörr i monoliten öppnas och blottar en artefakt. Troyas Moonbreeze identifierar stenen som togs ut som Morrow Stone.",al={"monolitens artefakt","vad finns i equinex"}},{q="Varför förlorar staven sin kraft?",a="Stave of Equinex börjar förlora sin energi så snart artefakten tas ut ur monoliten.",al={"staven falnar","varför är staven svag"}}},fp="16,130,19.283.0,14.273.1,34.88.0,29.117.0,30.93.0,28.131.1,30.100.1"}
P.entries["item:steelgrill-s-tools"] = {n="Steelgrill's Tools",s="Steelgrill's Tools är en särskild uppsättning mekanikerverktyg som beställts åt Beldin Steelgrill, chefsteknikern på Steelgrill's Depot. Beldin är känd för att pressa belägringsmaskiner och sin egen utrustning till bristningsgränsen. Han har ofta sönder verktyg och förlitar sig på leveranser från närliggande Kharanos för att hålla verkstaden igång.",h="Steelgrill's Tools är en särskild uppsättning mekanikerverktyg som beställts åt Beldin Steelgrill...",kw={"beldin","förråd","kharanos","ratchet","belägringsmaskin","skiftnyckel","steelgrill","verktyg"},ang={["profession:Engineering"]="Alla ingenjörer kan förstå Beldins dilemma, eftersom reparationer med högt vridmoment på tunga belägringsmaskiner regelbundet sliter ut arclight-nycklar och ömtåliga skiftnycklar.",["race:Dwarf"]="Att underhålla Alliansens bepansrade belägringsmaskiner är en fråga om dvärgisk stolthet, och om Beldin har de verktyg han behöver förblir Ironforges bepansrade förtrupp redo för strid."},sec={{t="En hårdhänt hantverkare",b="Beldin Steelgrill anses allmänt vara en av de främsta teknikerna för belägringsmaskiner i Dun Morogh, men hans hårdhänta reparationsmetoder är ökända bland lokala köpmän. Beldin arbetar outtröttligt med bepansrade stridsvagnar och mekaniska konstruktioner, men har sönder ömtålig utrustning nästan lika snabbt som den kan smidas. Han knäcker arclight-nycklar och sliter ut fang-spärrskaft, så mekanikern beställer ständigt nya verktyg från Kharanos för att hålla reparationsbänkarna utrustade."},{t="Hålla maskinerna igång",b="Den här verktygsleveransen är avgörande för att Ironforges krigsmaskiner ska fungera. På sitt förråd nordost om Kharanos servar Beldin stridsfordon åt erfarna förare som Pilot Stonegear. Utan nytillförda skiftnycklar och spärrskaft skulle viktiga belägringsmaskiner stå halvmonterade i snön och både förrådet och det lokala försvaret bli stillastående."}},faq={{q="Vad används Steelgrill's Tools till?",a="De är ersättningsverktyg för mekaniker som levereras till Beldin Steelgrill på Steelgrill's Depot. Beldin behöver dem för att rusta upp tung dvärgisk maskinutrustning, särskilt den skadade belägringsmaskinen som tillhör Pilot Stonegear.",al={"vad är det här för verktyg","steelgrill tools användning"}},{q="Varför gör Beldin Steelgrill av med så många verktyg?",a="Beldin är en ovanligt hårdhänt mekaniker som pressar sin utrustning till bristningsgränsen. Enligt leverantörer i Kharanos knäcker han arclight-nycklar och har sönder fang-spärrskaft nästan snabbare än lokala hantverkare hinner tillverka nya.",al={"varför trasiga verktyg","varför behöver beldin verktyg"}},{q="Varifrån kommer den här verktygslådan?",a="Leveransen sätts ihop och skickas från den närliggande bosättningen Kharanos innan den lämnas över till resande som beger sig nordost mot Steelgrill's Depot.",al={"var får jag tag på verktyg","verktygsleveransens ursprung"}},{q="Vem är Beldin Steelgrill?",a="Beldin är en mästermekaniker av dvärgfolk som äger och driver Steelgrill's Depot, nordost om Kharanos. Han anses vara regionens främsta tekniker för belägringsmaskiner.",al={"vem är beldin","beldin steelgrill bakgrund"}}},fx={["8eb066d8"]={q="Vad är Steelgrill's Tools?",a="Steelgrill's Tools är en nyförpackad beställning med tung mekanisk utrustning, bland annat arclight-nycklar och fang-spärrar. Den är förberedd för direkt leverans till Beldin Steelgrill, den främste teknikern för belägringsmaskiner som arbetar från Steelgrill's Depot nära Kharanos.",al={"vad är steelgrill's tools","steelgrill's tools verktygslåda"}},["11454cb4"]={q="Varför behöver Beldin Steelgrill den här verktygslådan?",a="Beldin är en expertmekaniker, men han kör sin utrustning till bristningsgränsen när han servar tunga maskiner. Han har just knäckt sin sista fang-spärr och behöver omgående den här nya leveransen för att utföra kritiska reparationer på belägringsmaskiner, som Pilot Stonegears.",al={"varför vill beldin ha verktyg","varför behövs steelgrill's tools","varför behövs verktygen"}}},fp="18,182,24.349.0,27.287.0,37.180.0,52.151.0,40.99.0,25.147.0"}
P.entries["item:steelsnap-s-rib"] = {n="Steelsnap's Rib",s="Steelsnap's Rib är en dyster trofé från kadavret efter den våldsamma hyenan Steelsnap i Thousand Needles. När den förs tillbaka till Thunder Bluff blir den ett fysiskt bevis på att en varelse som anses stå utanför Jordmoderns välsignelse har fällts.",h="Steelsnap's Rib är en dyster trofé från kadavret efter den våldsamma hyenan Steelsnap i Thousand Needles.",kw={"camp e'thok","hunter rise","hyena","melor stonehoof","steelsnap","steelsnap's rib","thousand needles","thunder bluff"},ang={["class:Hunter"]="Att ta revbenet från en flockledare på toppen av näringskedjan prövar jägarens förmåga att spåra farligt villebråd och undanröja hot som rubbar vildmarkens balans.",["race:Tauren"]="För tauren innebär det att föra tillbaka den här trofén att fullgöra en plikt mot Jordmodern genom att fördriva en varelse vars tygellösa grymhet fläckar den heliga balansen."},sec={{t="En jakt utanför välsignelsen",b="De flesta tauren-jakter bedrivs för föda, för ärans skull eller för att söka harmoni med naturen. Steelsnap är däremot ett annat slags villebråd. Den här våldsamma alfahyenan strövar omkring på kanjonens botten i Thousand Needles, söder om Camp E'thok, där den terroriserar fredliga djur och hetsar flockar av mindre rovdjur till meningslös blodsutgjutelse. När jaktmästaren Melor Stonehoof på Hunter Rise utser Steelsnap till ett mål som ska dödas, kräver han ett kraftigt ben – Steelsnap's Rib – som obestridligt bevis på att tyrannen har dräpts och att kanjonen befriats från sin plåga."}},faq={{q="Vad används Steelsnap's Rib till?",a="Revbenet förs till Melor Stonehoof på Hunter Rise i Thunder Bluff för att slutföra jakten på Steelsnap. Det är ett påtagligt bevis på att den våldsamma hyenan har besegrats.",al={"steelsnap's rib-uppdrag","vem vill ha steelsnap's rib","vad gör jag med steelsnap's rib"}},{q="Var hittar jag Steelsnap för att få tag på revbenet?",a="Steelsnap strövar omkring i den nordvästra delen av Thousand Needles, på kanjonens botten söder om Camp E'thok, vanligtvis med trogna flockmedlemmar vid sin sida.",al={"steelsnap-plats","var finns steelsnap","hitta steelsnap"}},{q="Varför vill Melor Stonehoof att Steelsnap dödas?",a="Melor anser att Steelsnap är en onaturlig tyrann som står utanför Jordmoderns välsignelse. Till skillnad från vanliga rovdjur, som jagar för att överleva, sprider Steelsnap omotiverat våld och skräck bland fredliga djur, så han måste förgöras.",al={"varför döda steelsnap","melor stonehoofs motiv","steelsnap-bakgrund"}},{q="Vem är Melor Stonehoof?",a="Melor Stonehoof är en erfaren tauren-jägare på Hunter Rise i Thunder Bluff. Han ger blivande spårare i uppdrag att hitta farliga bestar runtom i Kalimdor.",al={"vem är melor","melor stonehoofs plats","melor på hunter rise"}}},fx={["27efcb35"]={q="Vad är Steelsnap's Rib?",a="Det är ett tungt ben från kadavret efter Steelsnap, en ökänd och vild hyena som terroriserar ravinerna i Thousand Needles. I stället för att vara användbart hantverksmaterial eller kött tjänar det som ett obestridligt fysiskt bevis på att det våldsamma odjuret har fällts.",al={"vad är steelsnap's rib","steelsnaps ben"}},["57ae26da"]={q="Var kommer Steelsnap's Rib ifrån?",a="Revbenet kommer direkt från kvarlevorna efter Steelsnap, en ovanligt våldsam hyena som strövar på de torra slätterna i Thousand Needles söder om The Barrens. För att få tag på det måste en jägare spåra upp odjuret och besegra både Steelsnap och hans flock.",al={"var får man tag på steelsnap's rib","steelsnap's ribs ursprung","vilken fiende släpper steelsnap's rib"}},["4a69fb67"]={q="Varför vill Melor Stonehoof ha Steelsnap's Rib?",a="Melor Stonehoof ber om revbenet som fysiskt bevis på Steelsnaps död. Till skillnad från jakter som bedrivs för mat eller ära skickar Melor jägare för att utrota Steelsnap, eftersom odjuret står utanför Jordmoderns välsignelse och sprider blodspillan och rädsla bland fredligare varelser. När benet återlämnas bekräftar det att ravinen har renats från denna smitta.",al={"varför lämna steelsnap's rib till melor","varför behöver melor revbenet","varför samla in steelsnap's rib"}}},fp="15,181,27.428.0,33.118.0,42.121.0,47.180.0,23.142.0"}
P.entries["item:stolen-silver"] = {n="Stolen Silver",s="Vid The Crossroads har en kista med silver från Horden försvunnit från vakttornet. Sunscale-raptorer bar mynten till sina bon vid Raptor Grounds söder om Ratchet.",h="Vid The Crossroads har en kista med silver från Horden försvunnit från vakttornet.",kw={"löneutbetalning i the barrens","the crossroads","gazrog","raptor grounds","silverfyllt kassaskrin","stolen silver","sunscale-raptor"},ang={["faction:Horde"]="The Crossroads är hjärtat i Hordens närvaro i The Barrens. Att återta lönen håller de lokala fotsoldaterna mätta, avlönade och redo att hålla stånd mot kentaurernas och Alliansens intrång."},sec={{t="Ett bestialiskt rån",b="Sunscale-raptorer bar en kista med silver från vakttornet vid The Crossroads. Mynten var avsedda som lön åt garnisonens vakter. Raptorerna släpade lådan till sina gemensamma bon vid Raptor Grounds, söder om Ratchet. Gazrog och de andra tillsyningsmännen kan inte förklara varför rovdjuren tog den. Stölden får dem att undra om raptorerna värdesätter glänsande saker eller besitter en list utöver vanliga vilda djurs."}},faq={{q="Vad är Stolen Silver?",a="Stolen Silver är en tung låda med mynt som ska betala vakterna vid The Crossroads. Raptorer stal den från vakttornet och bar den till sina boplatser.",al={"vad är stolen silver","vad är silvret"}},{q="Varför stal raptorerna ett kassaskrin med mynt?",a="Inte ens Gazrog kan förklara varför raptorerna tog lådan. De kan ha lockats av dess glänsande metall, eller så ledde deras ovanliga list dem till att bära den djupt in i sitt näste.",al={"varför vill raptorer ha silver","raptorernas intelligens","varför silver"}},{q="Vart fördes silvret?",a="Raptorerna tog lådan till Raptor Grounds, en karg kanjon med bon söder om Ratchet i östra The Barrens.",al={"stolen silver plats","var finns silvret"}},{q="Vem letar efter Stolen Silver?",a="Gazrog, en orch stationerad vid The Crossroads, letar efter kistan. Silvret motsvarar en hel månadslön för utpostens hårt ansatta försvarare.",al={"vem vill ha silvret","vem lämnar in stolen silver"}}},fp="13,157,15.406.0,26.160.0,41.157.0,27.120.0,37.146.0"}
P.entries["item:stoley-s-bottle"] = {n="Stoley's Bottle",s="Stoley’s Bottle innehåller Steamwheedle bilge rum, som skickats till Booty Bay åt Sea Wolf MacKinley. MacKinley ska smaka på rommen och bedöma hur sträv den är.",h="Stoley’s Bottle innehåller Steamwheedle bilge rum, som skickats till Booty Bay åt Sea Wolf MacKinley.",kw={"booty bay","sea wolf mackinley","steamwheedle bilge rum","stoley","stoley's bottle","stoleys skuld"},sec={{t="En besk flaska",b="I Booty Bay får Sea Wolf MacKinley en flaska Steamwheedle bilge rum från Stoley. MacKinley hoppas att drycken ska stilla hans tvivel om spriten i Booty Bay. En enda smakbit visar att rommen är hemsk. Den är tjock som grus och bränner som lava, precis som Stoley lovade."}},faq={{q="Vad finns i Stoley’s Bottle?",a="Stoley’s Bottle innehåller Steamwheedle bilge rum.",al={"vad finns i flaskan","innehållet i stoleys flaska"}},{q="Vem är flaskan till?",a="Sea Wolf MacKinley i Booty Bay ska få Stoley’s Bottle.",al={"vem får flaskan","vem ska få flaskan"}},{q="Varför vill MacKinley ha flaskan?",a="MacKinley vill stilla sina tvivel om spriten i Booty Bay genom att smaka på Stoleys Steamwheedle bilge rum.",al={"varför sprit åt mackinley","mac kinley flaska"}},{q="Hur smakar rommen?",a="MacKinley tycker att rommen är hemsk, tjock som grus och bränner som lava.",al={"är rommen god","smak på bilge rum"}},{q="Gör flaskan upp med Stoleys skuld?",a="Efter att ha smakat på rommen säger MacKinley att Stoley kan behålla pengarna han är skyldig. Drycken är så sträv som Stoley lovade.",al={"stoleys skuld flaska","förlåter mac kinley stoley"}}},fp="15,150,15.272.0,29.50.0,22.70.0,35.109.0,29.72.1,39.114.1"}
P.entries["item:stoley-s-shipment"] = {n="Stoley's Shipment",s="Stoley’s Shipment är en stulen romlast som piraterna håller i Lost Rigger Cove. Stoley vill ha tillbaka den för att lösa ett vad med “Sea Wolf” MacKinley.",h="Stoley’s Shipment är en stulen romlast som piraterna håller i Lost Rigger Cove.",kw={"booty bay","captain cuergo","lost rigger cove","rom","sea wolf mackinley","steamwheedle port","stoley","stoley’s shipment","tanaris","vad"},sec={{t="Rom för ett vad",b="I Lost Rigger Cove ligger Stoley’s Shipment bland piraternas stulna last. Captain Cuergo tog Stoleys sista romlast och förvarar den i piratstaden bakom murar. Stoley behöver få lasten återlämnad till Steamwheedle Port så att han kan lösa sitt vad med “Sea Wolf” MacKinley i Booty Bay."}},faq={{q="Vad är Stoley’s Shipment?",a="Stoley’s Shipment är en stulen romlast som Captain Cuergo tog från Stoley.",al={"stoleys last","stoleys rom"}},{q="Vem stal rommen?",a="Captain Cuergo stal Stoleys sista romlast.",al={"vem tog stoleys rom","cuergos last","pirat stal rom"}},{q="Var finns Stoley’s Shipment?",a="Stoley’s Shipment förvaras i piratstaden bakom murar i Lost Rigger Cove i Tanaris.",al={"var finns rommen","last i lost rigger","lastens plats"}},{q="Varför vill Stoley ha tillbaka lasten?",a="Stoley vill ha tillbaka rommen så att han kan lösa ett vad med “Sea Wolf” MacKinley i Booty Bay.",al={"varför lämna tillbaka rommen","stoleys vad","spritvad"}},{q="Vem är MacKinley?",a="“Sea Wolf” MacKinley är sjömannen i Booty Bay som Stoley slog vad med om Kalimdors rom.",al={"sea wolf","mackinleys vad","person i booty bay"}}},fp="17,151,15.287.0,28.82.0,18.53.0,29.85.0,39.94.0,17.102.0"}
P.entries["item:stone-circle"] = {n="Stone Circle",s="Stone Circle är en sten med en ormsymbol som förvaras i Marvon Rivetseekers verkstad i Ratchet. Den påminner om en rund kammare i Sunken Temple.",h="Stone Circle är en sten med en ormsymbol som förvaras i Marvon Rivetseekers verkstad i Ratchet.",kw={"rund kammare","marvon rivetseeker","ratchet","ormsymbol","stone circle","sunken temple"},sec={{t="Ett ormmärke",b="Marvon Rivetseeker förvarar Stone Circle i sin verkstad i Ratchet, där han ber dig hämta den. Han minns att han fann en liknande ormsymbol efter att ha flytt från Sunken Temple. Stenen kan hjälpa honom att minnas mer av det han såg där."}},faq={{q="Vad är Stone Circle?",a="Stone Circle är en rund sten med en ormsymbol, som förvaras i Marvon Rivetseekers verkstad i Ratchet.",al={"stone circle","vilken sten är det här"}},{q="Var finns Stone Circle?",a="Marvon Rivetseeker har Stone Circle i sin verkstad i Ratchet.",al={"var finns stone circle","hitta stenen"}},{q="Vem vill ha Stone Circle?",a="Marvon Rivetseeker ber dig hämta Stone Circle från hans verkstad i Ratchet.",al={"vem vill ha den här stenen","marvons sten"}},{q="Vad betyder ormmärket?",a="Ormsymbolen liknar symbolerna på statyerna som Marvon minns från en rund kammare i Sunken Temple.",al={"ormsymbol","ormmärkets betydelse"}},{q="Varför vill Marvon ha den?",a="Marvon hoppas att stenen ska hjälpa honom att minnas flykten från Sunken Temple och berätta mer om platsen.",al={"varför stone circle","marvon vill ha stenen"}}},fp="12,146,14.238.0,25.115.0,26.67.0,27.86.0,32.99.0,24.114.0"}
P.entries["item:stone-of-relu"] = {n="Stone of Relu",s="Stone of Relu är en forntida arkeologisk relik som återfunnits i Wetlands. Archaeologist Flagongut tror att den är nyckeln till att väcka slumrande krafter i urtidsfossil. Den försvann en kort tid när lokala rovfåglar överföll forskaren på vägen.",h="Stone of Relu är en forntida arkeologisk relik som återfunnits i Wetlands.",kw={"archaeologist flagongut","explorers' league","fossil","fläckig rovfågel","prospector whelgar","stone of relu","wetlands"},ang={["faction:Alliance"]="Alliansens expeditioner i Menethil Harbor förlitar sig på återfunna artefakter som Stone of Relu för att rättfärdiga de mödosamma utgrävningarna i de förrädiska träskmarkerna.",["race:Dwarf"]="För Explorers' League är Stone of Relu ett viktigt verktyg för att pussla ihop det forntida livets ursprung och världens bortglömda arv."},sec={{t="En nyckel till forntida reliker",b="Stone of Relu upptäcktes under Explorers' League-uppdrag och tros ha kraften att tyda förhistoriska fossil från Kalimdor och Eastern Kingdoms. Archaeologist Flagongut identifierade föremålet som katalysatorn som krävs för att frigöra hemligheterna i både hans egna fynd från Wetlands och fossilet som Prospector Remtravel grävde fram i Darkshore."},{t="Förlorad i träskmarkerna",b="När Flagongut färdades längs vägarna i Wetlands för att möta Prospector Whelgar överföll en flock fläckiga rovfåglar honom. I tumultet försvann reliken och svaldes av ett av de glupska djuren, vilket tvingade ligan att ta hjälp av äventyrare för att jaga träskens rovfåglar och skära ut den forntida stenen ur deras svalg."}},faq={{q="Vad är Stone of Relu?",a="Stone of Relu är ett forntida föremål som Archaeologist Flagongut söker efter. Han tror att den fungerar som en kodnyckel eller katalysator som kan låsa upp de dolda mysterierna och krafterna som slumrar i förhistoriska fossil.",al={"stone of relu","vad är den här stenen","relu-artefakt"}},{q="Hur hamnade stenen inuti en rovfågel?",a="Archaeologist Flagongut bar reliken längs vägen genom Wetlands för att möta Prospector Whelgar när fläckiga rovfåglar anföll hans sällskap. I kaoset försvann stenen och svaldes av ett av asätarna.",al={"varför har rovfåglar den","vem tappade stenen","hur gick den förlorad"}},{q="Vad tänker Flagongut göra med stenen?",a="Flagongut tänker använda stenen tillsammans med sitt återfunna fossil och fossilet som Prospector Remtravel hittade i Darkshore för att tyda och frigöra deras slumrande magiska hemligheter.",al={"vad vill flagongut","stone of relu syfte"}}},fp="13,142,23.275.0,19.285.0,26.146.0,41.160.0,48.179.0"}
P.entries["item:stone-of-the-tides"] = {n="Stone of the Tides",s="Stone of the Tides är en uråldrig Gurubashi-relik som Baron Revilgaz vill ha till sin samling. Den styr vatten och kan frammana vattenelementarer.",h="Stone of the Tides är en uråldrig Gurubashi-relik som Baron Revilgaz vill ha till sin samling.",kw={"baron revilgaz","förbannelse","gurubashi","stone of the tides","trollartefakt","vatten","vattenelementarer"},ang={["faction:Alliance"]="Som Alliance-resenär i Stranglethorn Vale kan du hjälpa Baron Revilgaz att återta stenen till sin samling av uråldriga trollföremål.",["race:Troll"]="Som troll kan du känna igen Stone of the Tides som en artefakt som en gång användes av Gurubashi Empire."},sec={{t="En sjunken relik",b="Baron Revilgaz söker efter Stone of the Tides till sin samling av uråldriga trollföremål. Reliken tillhörde en gång det mäktiga Gurubashi Empire och kan styra vatten och frammana vattenelementarer. Men dess kraft är förbannad: den som använder den bleknar långsamt bort ur tillvaron."}},faq={{q="Vad är Stone of the Tides?",a="Stone of the Tides är en kraftfull magisk artefakt som en gång användes av Gurubashi Empire. Den styr vatten och frammana vattenelementarer.",al={"stone of the tides","vad är tide-stenen"}},{q="Vad gör Stone of the Tides?",a="Stone of the Tides låter användaren kontrollera vatten och frammana vattenelementarer.",al={"stenens krafter","vad kan tide-stenen göra"}},{q="Vad är förbannelsen över Stone of the Tides?",a="Stone of the Tides får långsamt användaren att blekna bort ur tillvaron.",al={"tide-stenens förbannelse","varför bleknar man bort"}},{q="Varför vill Baron Revilgaz ha stenen?",a="Baron Revilgaz vill ha Stone of the Tides till sin samling av uråldriga trollföremål.",al={"revilgaz vill ha stenen","varför vill baronen ha den"}},{q="Var kommer stenen ifrån?",a="Stone of the Tides användes en gång av Gurubashi Empire.",al={"stenens ursprung","gurubashi tide-sten"}}},fp="18,149,14.263.0,31.136.0,36.79.0,44.65.1,39.90.0,30.61.0"}
P.entries["item:stonetalon-sap"] = {n="Stonetalon Sap",s="Stonetalon Sap är ett klibbigt och kraftfullt ämne som utvinns direkt ur de trögfotade savbestarna som strövar omkring på Stonetalon Mountains klippiga höjder. Det är ett viktigt reagens för Darkspear Witch Doctor Jin'Zil, som använder dess råa skogsegenskaper för att koka ihop en illvillig brygd.",h="Stonetalon Sap är ett klibbigt och kraftfullt ämne som utvinns direkt ur de trögfotade savbestarna som...",kw={"jin'zil","malaka'jin","mirkfallon lake","savbest","stonetalon peak","stonetalon sap"},ang={["race:NightElf"]="Att en häxdoktor från Horde vanhelgar Stonetalon-trakternas inhemska krafter för att förgifta tillfångatagna alver är en skymf mot naturen och Elune.",["race:Troll"]="Witch Doctor Jin'Zil visar hur Darkspear-folket kan förvandla fiendens älskade omgivning till ett dödligt voodoo-redskap."},sec={{t="En bitter skörd",b="Den här trögflytande vätskan droppar från savbestarna nära Mirkfallon Lake och Stonetalon Peak och bär på den koncentrerade essensen från bergens uråldriga flora. I sitt naturliga, vilande tillstånd är den harmlös, men en erfaren alkemist eller häxdoktor kan lätt förvandla saven till något långt mörkare. Jin'Zil från Malaka'jin vill ha den för att brygga det han hånfullt kallar ”skogsmagi” – en dödlig dryck som ska plåga hans tillfångatagna Night Elf-fångar med själva essensen av deras älskade vildmark."}},faq={{q="Vilka varelser bär på Stonetalon Sap?",a="Den samlas in från savbestar, de märkliga skogsvarelser som finns nära Mirkfallon Lake och högre upp längs sluttningarna mot Stonetalon Peak.",al={"var får man tag på stonetalon sap","vem släpper stonetalon sap","savbestar"}},{q="Vad använder Witch Doctor Jin'Zil saven till?",a="Jin'Zil blandar saven med courserögon, skymningsmorrhår och en Fey Dragon Scale för att skapa en giftig brygd som han använder mot sina tillfångatagna Night Elf-fångar.",al={"varför vill jin'zil ha sav","jin'zils recept på skogsmagi"}},{q="Var hittar man lättast savbestar?",a="Savbestar lever i dungarna runt Mirkfallon Lake och längs de frodiga stigarna upp mot Stonetalon Peak.",al={"savbestarnas plats","savbestar vid mirkfallon lake"}},{q="Är saven magisk i sig?",a="Den är naturligt genomsyrad av den uråldriga livskraften från Stonetalon-bergen, men det krävs trollmagi och särskilda reagenser för att förvandla den till ett dödligt gift.",al={"är stonetalon sap magisk","stonetalon saps egenskaper"}}},fx={b24da591={q="Vad är Stonetalon Sap?",a="Stonetalon Sap är ett klibbigt, naturligt harts som samlas från savbestarna som strövar i Stonetalon Mountains, särskilt kring platser som Mirkfallon Lake och Stonetalon Peak. Det är tjockt, trögflytande och fullt av rå naturkraft, vilket gör det till en idealisk ingrediens i brygder och voodoo-elixir som använder den säregna magin i den lokala vildmarken.",al={"vad är stonetalon sap","föremålet stonetalon sap","om stonetalon sap"}},["7615d27b"]={q="Var kommer Stonetalon Sap ifrån?",a="Den här bärnstensfärgade saven utvinns direkt från de levande savbestarna som vandrar genom skogarna och längs sjöstränderna i Stonetalon Mountains. Den tillverkas eller destilleras inte av någon dödlig hantverkare, utan utsöndras naturligt av dessa besynnerliga, uråldriga växtvarelser.",al={"stonetalon saps källa","var hittar man sav","stonetalon saps ursprung"}}},fp="14,172,16.241.1,36.94.0,47.141.1,43.96.0,30.123.0"}
P.entries["item:stormpike-banner"] = {n="Stormpike Banner",s="Stormpike Banner är ett baner som gömts djupt inne i den förrädiska Icewing Cavern i Alterac Valley. Alliansens rekryter måste trotsa vilda harpyor för att hämta det som ett inträdesprov och visa att de förtjänar att bära Stormpikes insignier.",h="Stormpike Banner är ett baner som gömts djupt inne i den förrädiska Icewing Cavern i Alterac Valley.",kw={"alterac valley","dun baldar","haggerdin","icewing caverns","insignier","inträdesprov","stormpike banner"},ang={["faction:Alliance"]="När du hämtar baneret blir du formellt medlem i Stormpike Guard och får rätt att bära deras stridsinsignier mot Frostwolf Clan.",["race:Dwarf"]="Baneret står för Ironforges suveräna anspråk och Stormpike-klanens heliga uppdrag att hitta reliker från sitt förflutna i hela dalen."},sec={{t="Ett inträdesprov",b="För att officiellt ansluta sig till Stormpike-expeditionen i Alterac Valley måste blivande rekryter visa vad de går för innan de ens drabbar samman med Frostwolf-orcherna. Lieutenant Haggerdin skickar nyanlända soldater från Alliansen till Icewing Caverns, sydväst om Dun Baldar. Stormpike Banner står djupt inne i den frusna underjordiska hålan och fungerar som ett prov: den som vågar möta de harpyor som bor där, ta baneret och återvända med livet i behåll får rang och insignier som rekryt i Stormpike Guard."}},faq={{q="Var finns Stormpike Banner?",a="Baneret står djupt inne i Icewing Caverns, ett isande grottsystem sydväst om Dun Baldar i Alterac Valley.",al={"banerets plats","var finns stormpike banner","hur hittar man baneret"}},{q="Varför måste rekryterna hämta baneret?",a="Lieutenant Haggerdin kräver att alla rekryter från Alliansen visar sitt mod innan de ansluter sig till stridslinjerna. Den som hämtar tillbaka baneret från den farliga grottan, full av harpyor, får sin första Stormpike Insignia.",al={"inträdesprov","varför hämta baneret","haggerdins uppdrag"}},{q="Vilka faror vaktar baneret inne i grottan?",a="Icewing Caverns försvaras hårt av vilda lokala harpyor som går till våldsamt angrepp mot alla inkräktare som söker efter baneret.",al={"monster nära baneret","fiender i icewing cavern"}},{q="Vem ska jag lämna tillbaka baneret till när jag hittat det?",a="Lämna det återhämtade baneret till Lieutenant Haggerdin, Alliansens officer som är stationerad utanför ingången i Alterac Mountains.",al={"lämna in baneret","inlämning av baneret"}}},fx={["27f01085"]={q="Vad är Stormpike Banner?",a="Stormpike Banner är en militär fana som representerar Stormpike Guard, dvärgexpeditionen som för närvarande utkämpar ett krig i Alterac Valley. Fanan har rests djupt inne i de farliga, harpystinna Icewing Caverns sydväst om Dun Baldar och fungerar som ett prövningsmärke. Rekryter måste ta sig in i det frusna djupet, trotsa de vilda bestarna därinne och återta fanan för att bevisa sin duglighet och att de förtjänar att bära Stormpike-insignian.",al={"vad är stormpike banner","stormpike banners bakgrund","om stormpike banner"}}},fp="16,139,19.286.0,38.96.0,44.167.0,46.90.0,41.125.0"}
P.entries["item:stormpike-s-request"] = {n="Stormpike's Request",s="Mountaineer Stormpike skickar en skriftlig beställning från Loch Modan till Stormwind City. Han ber Furen Longbeard att smida en sköld av exceptionell dvärgkvalitet åt honom.",h="Mountaineer Stormpike skickar en skriftlig beställning från Loch Modan till Stormwind City.",kw={"smed","dun morogh","dwarven district","furen longbeard","beställning","sköld","stormpike","stormwind"},ang={["profession:Blacksmithing"]="Stormpikes beställning visar vilken ställning mästarrustningssmeder har: uppdragsgivare i andra riken söker skickliga dvärgsmeder.",["race:Dwarf"]="Som dvärg för du samman klan och hantverk mellan bergsvakterna som försvarar Khaz Modan och hantverkarna som bor utomlands i människornas städer."},sec={{t="En beställning från norr",b="Mountaineer Stormpike behöver en stadig sköld medan han är stationerad i Loch Modan. Han litar inte på arbetet åt någon vanlig smed och ber Furen Longbeard, vars hantverk han beundrar djupt. Furen bor numera bland människorna i Stormwinds Dwarven District efter att ha lämnat Ironforge. Stormpike antar att en kunglig lösensumma lockade honom söderut, så resande äventyrare för beställningen mellan rikena."},{t="Stormpike-klanens anseende",b="Furen Longbeard tar emot Stormpikes brev i Stormwinds Dwarven District och går med på att tillverka skölden. Som en stolt och etablerad medlem av Stormpike-klanen, känd i hela Khaz Modan för sin stridsduglighet och rikedom, välkomnar Furen nyheter och affärer från sitt nordliga hemland. Han sätter igång med bergsvaktens beställning."}},faq={{q="Vad är Stormpike's Request?",a="I sitt brev från Loch Modan ber Mountaineer Stormpike Furen Longbeard att smida en sköld av hög kvalitet åt honom.",al={"vad är det här för brev","stormpikes beställningsföremål","stormpikes beställning"}},{q="Vem skrev brevet?",a="Mountaineer Stormpike skrev brevet. Han är en dvärgisk väktare som bevakar bergspassen i Loch Modan och beundrar Furen Longbeards smide djupt.",al={"vem skickade stormpikes beställning","vem skrev det","mountaineer stormpike"}},{q="Vart ska brevet?",a="Brevet är adresserat till Furen Longbeard vid hans smedja i Stormwind Citys Dwarven District.",al={"var lämnar jag stormpikes beställning","vem ska få brevet","lämna stormpikes beställning"}},{q="Varför anlitar Stormpike en smed ända borta i Stormwind?",a="Stormpike anser att ingen kan mäta sig med Furens skicklighet och godtar ingen annan rustningssmed. Furen lämnade Ironforge för att arbeta bland människorna i söder.",al={"varför furen","varför inte smida i ironforge","varför skicka till stormwind"}}},fx={["181a24c8"]={q="Varför vill Furen Longbeard ha Stormpike's Request?",a="Den här skriftliga beställningen gäller en fint tillverkad dvärgsköld. Furen Longbeard, en rustningssmed i Stormwinds Dwarven District, uppskattar affärer från den berömda Stormpike-klanen. Han vet att familjen inte bara är stolt och högt ansedd i hela Khaz Modan, utan också rik nog att betala ordentligt för enastående hantverk.",al={"varför vill furen ha den här","varför vill man ha stormpike's request","varför behövs stormpike's request"}}},fp="19,161,21.380.0,18.322.0,28.103.0,22.143.0,34.93.0,57.137.0"}
P.entries["item:stormwind-armor-marker"] = {n="Stormwind Armor Marker",s="Stormwind Armor Marker låter dem som hjälper riket hämta utrustning från godkända hantverkare. Sara Timberlain tar emot den vid Eastvale Logging Camp.",h="Stormwind Armor Marker låter dem som hjälper riket hämta utrustning från godkända hantverkare.",kw={"rustningsmarkör","rustning av tyg och läder","eastvale logging camp","elwynn forest","rekvisition","sara timberlain","stormwind armor marker"},ang={["faction:Alliance"]="Som medlem i Alliansen kan du se hur Eastvale Logging Camp knyter gränsbosättningar till Stormwinds militära befäl."},sec={{t="Militära rekvisitioner",b="Stormwinds befälhavare utfärdar rustningsmarkörer till dem som tjänar riket. Att upprätthålla lag och ordning i hela Elwynn Forest tänjer på Stormwinds resurser, så befälhavarna använder ibland dessa officiella rekvisitionssedlar i stället för att dela ut standardutrustning vid militärposteringar. En markör bekräftar bärarens tjänst och ger lokala hantverkare med kontrakt tillstånd att tillverka anpassad rustning."},{t="Förnödenheter vid Eastvale",b="Vid Eastvale Logging Camp arbetar Sara Timberlain och andra hantverkare på uppdrag av Stormwind-armén. Lägrets ligger vid Elwynns östra gräns, där de använder lokala material för att tillverka skyddande plagg av tyg och läder. Visa upp en markör där för att få skräddarsytt skydd för att vakta de omgivande skogarna."}},faq={{q="Vad används Stormwind Armor Marker till?",a="Stormwind Armor Marker är en officiell militär värdehandling för dem som hjälper Stormwinds vakter. Den bevisar att du har tjänat och låter dig hämta skyddande rustning från en hantverkare med kontrakt hos armén.",al={"vad är en rustningsmarkör","markörens syfte","använda stormwind-markör"}},{q="Vem tar emot markören?",a="Sara Timberlain tar emot markören vid Eastvale Logging Camp, strax österut på andra sidan floden i Elwynn Forest. Hon har kontrakt med Stormwind-armén om att tillhandahålla skräddarsydd utrustning av tyg och läder.",al={"vem tar emot markören","var lämnar man in markören","sara timberlain markör"}},{q="Varför använder Stormwind markörer i stället för att dela ut rustning direkt?",a="Stormwind använder markörer eftersom avlägsna vaktposter kan sakna förvaringsutrymme och utrustning för smide eller sömnad, så att rekryter kan utrustas på plats. Befälhavare i fält kan skicka rekryter till lokala hantverkare som Sara Timberlain, som har egna verkstäder.",al={"varför polletter i stället för rustning","varför armémarkörer","militära värdehandlingar elwynn"}},{q="Vilken sorts utrustning ger markören?",a="Markören låter bäraren välja en nytillverkad rustningsdel av tyg eller läder, skräddarsydd av en arméleverantör med kontrakt.",al={"vilken rustning får jag","markörbelöningar","tyg eller läder"}}},fx={e5398b12={q="Vad är Stormwind Armor Marker?",a="Det är en officiell militär rekvisition utfärdad på Stormwind-arméns vägnar. I stället för att släpa skrymmande skyddsutrustning genom Elwynn Forest utfärdar lokala befälhavare denna symbol som en garanti för rekvisition. Den ger bäraren rätt att hämta nygjord tyg- eller läderrustning hos en auktoriserad rustningssmed.",al={"vad är stormwind armor marker","rustningsmärket","vad är märket"}},["3e7f2980"]={q="Varifrån kommer Stormwind Armor Marker, och vem tillverkade den?",a="Märket utfärdas på Stormwind-arméns vägnar av Guard Thomas vid hans post nära den östra bron i Elwynn. Det tilldelas försvarare som visar prov på klokhet och mod. Det bär kungarikets armés auktoritet och ger lokala hantverkare i uppdrag att förse rekryter med utrustning på kronans bekostnad.",al={"vem tillverkade rustningsmärket","varifrån kommer märket","vem utfärdar rustningsmärket"}},["618263b5"]={q="Varför vill Sara Timberlain ha Stormwind Armor Marker?",a="Stormwind-armén har gett Sara Timberlain i uppdrag att utrusta sina rekryter och frivilliga med tyg- och läderrustning. Hon behöver märket som officiellt bevis på sitt tillstånd innan hon lämnar ut sin handgjorda utrustning, så att kungarikets förråd bara går till erkända försvarare.",al={"varför vill sara ha märket","varför ta märket till eastvale","varför behövs rustningsmärket"}}},fp="22,177,21.341.0,21.324.0,50.195.0,23.195.0,69.244.0,47.128.0"}
P.entries["item:stoutmantle-s-response-to-solomon"] = {n="Stoutmantle's Response to Solomon",s="Gryan Stoutmantle skickar ett hårt svar från Sentinel Hill till Lakeshire. Hans meddelande berättar för Magistrate Solomon att People's Militia inte kan avvara en enda soldat till Redridge Mountains.",h="Gryan Stoutmantle skickar ett hårt svar från Sentinel Hill till Lakeshire.",kw={"gryan","lakeshire","brev","magistrate solomon","budbärare till westfall","people's militia","redridge","solomon","stoutmantle","westfall"},ang={["faction:Alliance"]="För Alliansen visar brevet hur avlägsna bosättningar vädjar till varandra om hjälp medan huvudstaden håller sina styrkor tillbaka.",["race:Human"]="Som mänsklig försvarare ser du hur Westfall och Redridge delar en desperat kamp för att överleva utan Stormwinds kungliga vakter."},sec={{t="En vädjan avslås",b="Magistrate Solomon i Lakeshire ber Sentinel Hill om förstärkningar när Blackrock-orcher och gnoller tränger sig på staden. Gryan Stoutmantle svarar skriftligen och beklagar Lakeshires förluster, men Westfall står inför ett eget krig. People's Militia bildades ur desperation efter att kronan drog tillbaka sin garnison. Bönder och frivilliga strider nu ensamma mot Defias Brotherhood. Stoutmantles styrkor blöder redan och är hårt pressade, utan några män att avvara till ännu en övergiven gränsbygd."},{t="Kungarikets försummelse",b="Redridge och Westfall delar ett dystert öde: båda har övergivits av hovet i Stormwind City. Kung Varian Wrynn är försvunnen, och rikets stående armé hålls av okänd anledning borta från provinsernas gränser. Avlägsna städer måste bilda frivilliga vakter eller gå under. Solomon tar emot det förseglade svaret och inser att ingen av städerna kan rädda den andra. Riket faller sönder medan huvudstaden tiger."}},faq={{q="Vad står det i Stoutmantles svar?",a="Gryan Stoutmantle skriver att Westfall utkämpar ett brutalt krig mot Defias Brotherhood och, precis som Redridge, har förlorat Stormwinds armé. Han sörjer de stupade försvararna men avslår Magistrate Solomons begäran om förstärkningar.",al={"vad står det i brevet","innehållet i stoutmantles brev","texten i svaret till solomon"}},{q="Varför bad Solomon Westfall om hjälp från början?",a="Lakeshire utsätts för hårda angrepp från gnoller och Blackrock-orcher, och Magistrate Solomons vädjan till General Marcus Jonathan i Stormwind har inte lett till några trupper. Utan officiell hjälp ber Solomon People's Militia i Elwynn om stöd från andra gränsförsvarare.",al={"varför be westfall om hjälp","solomon ber stoutmantle","varför bad lakeshire milisen om hjälp"}},{q="Varför kan People's Militia inte avvara några trupper?",a="People's Militia är en frivillig armé som kämpar för att hålla Sentinel Hill och de omgivande slätterna mot Defias Brotherhood. Förlusterna ökar dagligen, och utan stöd från den reguljära armén skulle trupper till Lakeshire lämna Westfall försvarslöst.",al={"varför hjälper inte milisen","kan westfall hjälpa redridge","varför avslå solomon"}},{q="Varför skyddar inte Stormwind-armén de här städerna?",a="Ingen i de båda städerna vet varför Stormwind-armén är frånvarande. Stoutmantle skriver att Stormwind drog tillbaka sina trupper och lämnade Westfall försvarslöst, medan Solomon undrar vad som kan kalla bort armén från dess folk. Båda regionerna måste förlita sig på lokala frivilliga.",al={"var är stormwind-armén","varför hjälper inte stormwind","stormwinds övergivande"}}},fx={["399f6159"]={q="Vad är Stoutmantle's Response to Solomon?",a="Det är ett officiellt skriftligt meddelande från Gryan Stoutmantle, befälhavare för Folkets milis i Sentinel Hill, adresserat till Magistrate Solomon i Redridge. Brevet kommer med det dystra beskedet att Westfall är indraget i sitt eget desperata krig mot Defias Brotherhood och inte kan skicka soldater eller förnödenheter för att hjälpa Lakeshire.",al={"vad är stoutmantle's response","stoutmantles brev till solomon","gryan svarar lakeshire"}},["945d8c3a"]={q="Varifrån kommer Stoutmantle's Response to Solomon, och vem skrev det?",a="Det skrevs av Gryan Stoutmantle själv i Sentinel Hill i Westfall. Efter att ha läst Magistrate Solomons vädjan om förstärkningar skrev Stoutmantle sitt svar och anförtrodde det åt dig, så att du kan föra det genom kungariket tillbaka till Redridge Mountains.",al={"vem skrev stoutmantle's response","vem skrev stoutmantle's response to solomon","varifrån kommer stoutmantles response"}},c46920a1={q="Varför vill någon ha Stoutmantle's Response to Solomon?",a="Magistrate Solomon väntar på svaret i Lakeshire och hoppas på militär hjälp för att hålla den svartstensorkiska invasionen som hotar Redridge stången. Han behöver Stoutmantles besked för att veta om Folkets milis kan rida till Lakeshires försvar eller om staden måste möta farorna ensam.",al={"vem vill ha stoutmantle's response","varför leverera stoutmantles brev","varför ta svaret till solomon"}}},fp="33,116,13.458.0,21.393.1,42.230.0,57.236.0,48.253.0,52.254.0"}
P.entries["item:strange-smelling-powder"] = {n="Strange Smelling Powder",s="Strange Smelling Powder är en gåtfull rest som hittats under utredningen av misstänkt sabotage kring Loch Modan. Den befaras vara ett instabilt sprängämne, och därför skickar Chief Engineer Hinderweir en brådskande kurir norrut för att söka upp en sprängämnesexpert.",h="Strange Smelling Powder är en gåtfull rest som hittats under utredningen av misstänkt sabotage kring Loch...",kw={"ett mörkt hot tornar upp sig","ashlan stonesmirk","dun modr","hinderweir","loch modan","strange smelling powder","thandol span"},ang={["profession:Engineering"]="Ingenjörer känner igen lukten av svavelhaltiga, instabila sprängblandningar som inte liknar standardformlerna vid Alliansens gruvutposter.",["race:Dwarf"]="För dvärgarna är det av största vikt att skydda Loch Modans stenverk och vattenmagasin. Därför blir varje tecken på fiendesprängämnen genast en kris för klanen."},sec={{t="Ett flyktigt fynd",b="Detta märkliga pulver upptäcktes bland tecken på sabotage mot Loch Modans infrastruktur och väckte genast oro hos Chief Engineer Hinderweir. Den starka lukten och fina konsistensen tyder på en tillverkad sprängblandning snarare än vanligt sprängpulver för gruvdrift. Eftersom Hinderweir inte känner till blandningens kemiska natur eller ursprung vägrar han att själv röra den. Han vet att minsta gnista kan utlösa en katastrof."},{t="Vägen norrut",b="Dvärgiska ingenjörer tar inga risker med instabila reagenser, så Hinderweir skickar pulverprover genom Algaz Gate till Wetlands. Där, vid Dun Modr nära Thandol Span, får den erfarna sprängämnesexperten Ashlan Stonesmirk i uppdrag att undersöka kornen och avgöra vilken sorts katastrofal explosion sabotörerna förbereder."}},faq={{q="Vad är Strange Smelling Powder?",a="Det är en misstänkt kemisk rest som återfanns i Loch Modan under utredningen av lokalt sabotage. Den starka stanken och sammansättningen får dvärgiska ingenjörer att misstänka att det är ett sprängämne.",al={"vad är strange smelling powder","vad är det här pulvret","pulver i loch modan"}},{q="Varför vill Chief Engineer Hinderweir att pulvret undersöks?",a="Hinderweir misstänker att pulvret är ett specialiserat sprängämne. För att förstå omfattningen av och hotet från planen mot Loch Modan behöver han en professionell analys från någon med djup kunskap om sprängningar.",al={"varför undersöka pulvret","hinderweirs pulver","vem behöver pulvret"}},{q="Vem kan identifiera pulvret?",a="Chief Engineer Hinderweir ber resande att ta provet till Ashlan Stonesmirk, en sprängämnesexpert som är stationerad långt norrut med regementet vid Dun Modr, nära Thandol Span.",al={"vem identifierar pulvret","vart ska jag ta pulvret","pulverexpert"}},{q="Varför är det farligt att transportera pulvret?",a="Utöver den inneboende flyktigheten hos ett okänt sprängämne måste den som bär provet trotsa den farliga färden genom Algaz Gate och vidare längs Wetlands sumpiga, fientliga vägar.",al={"är pulvret farligt","varför farligt"}}},fp="23,168,20.322.0,14.284.1,32.196.0,52.153.0,28.158.0,41.130.0"}
P.entries["item:strangely-marked-box"] = {n="Strangely Marked Box",s="En Strangely Marked Box är en lastlåda som hittats i selar fastspända på döda havssköldpaddor längs Darkshores kust. Dess gåtfulla utsida bär nagas slingrande runskrift och ger Night Elf-lärda bevis för att dessa havsdjur inte strandade av en slump.",h="En Strangely Marked Box är en lastlåda som hittats i selar fastspända på döda havssköldpaddor längs...",kw={"auberdine","vagn","darkshore","greymist","gwennyth bly'leggonde","naga","havssköldpadda","strangely marked box"},ang={["class:Priest"]="Genom att säkra reliker från stranden hjälper du Temple of the Moons lärda i Auberdine att skydda kusten från havets korrumperande inflytande.",["race:NightElf"]="När naga-förrådslådor hittas fastspända på inhemska havssköldpaddor längs Darkshore får kaldorei en varning: deras uråldriga, muterade släktingar tränger systematiskt upp ur Stora havet."},sec={{t="Troféer från djupet",b="Medan flera jättelika havssköldpaddor och havsdjur helt enkelt spolas upp på Darkshores dimhöljda stränder, berättar andra en långt mer illavarslande historia. På vissa kadaver finns rester av söndersplittrade ridselar och övergivna vagnar som varit fastspända direkt på skalen. I ruinerna av dessa buckliga fordon ligger förseglade behållare täckta av främmande, slingrande runor. Asätande Greymist-murlocker bosätter sig ofta i de ihåliga bröstkorgarna och trasiga vagnarna, där de kalasar på kadavren och vaktar kvarlevorna."},{t="Bevis på nagas expansion",b="När lådan visas för Gwennyth Bly'Leggonde, en forskare som företräder Temple of the Moon i Auberdine, avslöjar märkningarna dess verkliga ursprung. Skriften och de fastspända vagnarna tillhör naga, som använder jättelika sköldpaddor som lastdjur för att frakta förnödenheter och krigsmateriel upp på land. Upptäckten av dessa förrådslådor bekräftar att naga medvetet opererar längs de norra stränderna och kan vara på väg söderut mot Ashenvale med sina riddjur. Därför skickar prästerskapet i Auberdine relikerna direkt till Darnassus för vidare studier."}},faq={{q="Var hittas Strangely Marked Box?",a="Lådan hittas i övergivna vagnar som varit fastspända på skalen hos strandade havssköldpaddor längs Darkshores kust. Kadavren omringas och vaktas ofta av Greymist-murlocker som äter av dem.",al={"var hittar man strangely marked box","lådans plats","låda i sköldpaddsvagn"}},{q="Vem tillverkade Strangely Marked Box?",a="Lådan och dess inskrifter skapades av naga. De fäster lastvagnar på levande havssköldpaddor för att frakta proviant, vapen och utrustning från havets djup upp till Kalimdors stränder.",al={"vem tillverkade lådan","märkningar på lådan","runor på lådan","vad betyder märkningarna"}},{q="Vem vill ha lådan i Auberdine?",a="Gwennyth Bly'Leggonde, en forskare som arbetar i Auberdine på uppdrag av Temple of the Moon, samlar in lådan för att analysera de märkliga strandningarna och förstå det växande hotet från naga.",al={"vem ska jag lämna den till","lämna in lådan","vem vill ha lådan"}},{q="Varför bar havssköldpaddorna lådorna?",a="Naga tämjer eller förslavar jättelika havssköldpaddor och använder dem som lastdjur. De spänner selar och vagnar på deras ryggar för strid och för att frakta förnödenheter upp på land. Gwennyth misstänker att en sådan sköldpadda dödades på väg längre söderut, kanske mot Ashenvale.",al={"varför har sköldpaddor lådor","sköldpaddsvagnar","varför är sköldpaddorna fastspända"}},{q="Vad händer med lådan när du lämnar den till Gwennyth?",a="Gwennyth Bly'Leggonde skickar lådan och resten av kustundersökningens fynd vidare till Temple of the Moon i Darnassus, så att Night Elf-ledarna kan studera omfattningen av nagas intrång.",al={"vart skickas lådan","lådan skickas till darnassus"}}},fx={["981461f5"]={q="Vad är Strangely Marked Box?",a="Det är en last som upptäcktes i en bucklig vagn fastspänd på skalet av en strandad havssköldpadda längs Darkshores kust. Lådan är märkt med märkliga runor och utgör ett fysiskt bevis på organiserad sjötransport längs kusten. Den övergavs efter att transportdjuret dog och därefter blev övermannat av asätare.",al={"vad är den märkta lådan","vad är strangely marked box","föremålet strangely marked box"}},b4ce745f={q="Varför vill Gwennyth Bly'Leggonde ha Strangely Marked Box?",a="Gwennyth Bly'Leggonde söker lådan på uppdrag av Temple of the Moon för att undersöka varför enorma havsvarelser strandar på Darkshore. Om märkningarna tyds bekräftar det att fientliga naga spände fast sköldpaddorna och använde dem som lastdjur för att transportera förnödenheter inåt land. Hon skickar dessa ledtrådar direkt till lärda i Darnassus.",al={"varför vill gwennyth ha lådan","varför leverera strangely marked box","den märkta lådans syfte"}}},fp="20,168,20.323.0,26.395.1,40.154.0,34.171.0,32.145.0,46.218.0,52.162.0"}
P.entries["item:strigid-owl-feather"] = {n="Strigid Owl Feather",s="Strigid Owl Feathers samlas in från vilda strigid-ugglor som häckar bland Teldrassils grenar. Deras fjädrar är vanliga skogsfynd, men de eftertraktas av skumma typer som söker råmaterial för sina hemliga affärer.",h="Strigid Owl Feathers samlas in från vilda strigid-ugglor som häckar bland Teldrassils grenar.",kw={"dolanaar","ingredienser","strigid-uggla","strigid owl feather","strigid-skrikuggla","teldrassil","zenn foulhoof"},ang={["class:Druid"]="Druiderna vördar Teldrassils rovfåglar, så det känns obehagligt att se deras fjädrar samlas in under falska förespeglingar för misstänkta ingredienser.",["race:NightElf"]="Ugglorna i Teldrassil anses vara Elunes skapelser. Därför är det en förolämpning mot den heliga skogen när en satyr som Zenn Foulhoof utnyttjar dem."},sec={{t="Skogsfjädrar och skumma affärer",b="Teldrassils trädkronor är hem åt strigid-ugglor och strigid-skrikugglor, inhemska rovfåglar som jagar över hela Crown of the Earth. Deras dun och fjädrar är vanliga rester på skogsmarken, men ibland lockar de blickarna hos utövare som söker organiska ingredienser. Utanför Dolanaar utnyttjar den avfälliga satyren Zenn Foulhoof oerfarna resenärer som färdas längs vägen från Shadowglen. Han lurar dem att samla strigid-fjädrar, spindelsilke och nightsaber-huggtänder åt hans skumma verksamhet."}},faq={{q="Var hittar jag Strigid Owl Feathers?",a="Fjädrarna samlas från strigid-ugglor och strigid-skrikugglor i skogarna kring Dolanaar och på andra håll i Teldrassil.",al={"fjäderplats","var faller strigid owl feathers","ugglfjäderfarm"}},{q="Vem vill ha Strigid Owl Feathers?",a="En satyr vid namn Zenn Foulhoof, som lurar längs leden in mot Dolanaar, ber godtrogna äventyrare att hämta dem tillsammans med webwood-silke och nightsaber-huggtänder.",al={"vem behöver ugglefjädrar","lämna in ugglefjädrar","zenn ugglefjäder"}},{q="Vad använder Zenn Foulhoof fjädrarna till?",a="Zenn påstår att de är ingredienser som krävs för hans hemliga verksamhet i skogen, men han tycker mest om att lura godtrogna rekryter att göra grovjobbet åt honom.",al={"varför vill zenn ha fjädrar","zenns syfte med ingredienserna"}}},fx={c56fcaa2={q="Vad är en Strigid Owl Feather?",a="En Strigid Owl Feather är en fjäder från de rovlevande strigidugglor som hör hemma bland Teldrassils grenar. De ser ut som vanliga fågelfjädrar, men är kraftfulla naturliga reagenser för dem som ägnar sig åt hantverk, alkemi eller mörkare skogsriter.",al={"strigid owl feather","vad är strigid owl feather","uggelfjäder från teldrassil"}},["91562481"]={q="Var kommer en Strigid Owl Feather ifrån?",a="De här fjädrarna samlas direkt från strigidugglor och strigid skriugglor som häckar i Teldrassils skogar, särskilt kring Dolanaar. Som naturligt biologiskt material som fälls eller tas från skogens fågelrovdjur växer de fram av naturen och skapas inte av dödliga händer.",al={"varifrån kommer strigid owl feathers","strigid owl feathers källa","vem tillverkade strigid owl feather"}}},fp="19,121,32.327.1,38.133.0,31.125.0,45.147.1"}
P.entries["item:sturdy-dragonmaw-shinbone"] = {n="Sturdy Dragonmaw Shinbone",s="Stadiga Dragonmaw Shinbone är slitstarka skeletttroféer från de utbrytarorcher av Dragonmaw-klanen som finns i Wetlands. Rustningssmeden Velora Nitely i Undercity behöver dem som förstärkningsstag i måttbeställda rustningar för krigare.",h="Stadiga Dragonmaw Shinbone är slitstarka skeletttroféer från de utbrytarorcher av Dragonmaw-klanen som finns...",kw={"angerfang encampment","dragonmaw shinbone","benskenor","sturdy dragonmaw shinbone","undercity","velora nitely","wetlands"},ang={["class:Warrior"]="Genom att skaffa och pröva de här täta orchbenen med bara händerna visar en krigare sin fysiska styrka och samlar samtidigt in delar till stommen i en specialtillverkad rustning.",["race:Undead"]="Velora Nitely visar prov på typisk pragmatism hos de Förkastade och gör om sina fienders ben till användbar utrustning åt Mörka damens mästare."},sec={{t="Ben till stommen",b="När smeder smider brutala benskenor åt krigare i frontlinjen behöver de råmaterial som tål hårda slag. I Undercity värdesätter Velora Nitely den täta benstommen hos utbrytarorcherna av Dragonmaw-klanen, som håller till i Angerfang Encampment i centrala Wetlands. Dragonmaw-orcher är kända för sin kraftiga, stadiga benstomme, vilket gör deras skenben väl lämpade som förstärkningar i stommen. Men alla ben som samlas in håller inte måttet. Krigarna måste pröva varje ben med bara händerna och kasta bort dem som knäcks under tryck."}},faq={{q="Vad gör de här skenbenen stadigare än vanliga skenben?",a="Dragonmaw-orcher har naturligt kraftiga benstommar, men små sprickor eller sköra ben gör många exemplar oanvändbara till rustningar. För att kontrollera att ett ben är stadigt böjer en krigare det råa benet med bara händerna. Bara ben som står emot och inte går av anses starka nog att användas i stommen till benskenor.",al={"varför stadiga skenben","dragonmaw-benens styrka","pröva skenben"}},{q="Vem vill ha stadiga Dragonmaw Shinbone?",a="Velora Nitely, en rustningssmed i Undercity, vill ha dem. Hon använder dem som bärande stag när hon tillverkar brutala benskenor åt lovande krigare i Horde.",al={"vem behöver skenben","velora nitely ben","lämna in dragonmaw shinbone"}},{q="Var samlas de här benen in?",a="De tas från utbrytarorcherna av Dragonmaw-klanen som håller till i Wetlands söder om Arathi Highlands, framför allt vid Angerfang Encampment i kullarna sydväst om Thandol Span.",al={"var hittar man dragonmaw shinbone","dragonmaw shinbone plats","angerfang-ben"}},{q="Varför använder Velora Nitely orchben till rustningar?",a="De Förkastades hantverkare blandar ofta ben, senor och metall till krigsutrustning som är makaber men mycket slitstark. Dragonmaw-klanen är fortfarande fientlig mot Thralls Horde, så deras kvarlevor är lovligt byte för de Förkastades smeder som söker tåligt material för krävande hantverk.",al={"varför orchben","de förkastades benrustning","veloras bentillverkning"}}},fp="25,163,19.292.0,58.180.0,37.166.0,31.189.0,47.185.0"}
P.entries["item:sully-balloo-s-letter"] = {n="Sully Balloo's Letter",s="Sully Balloo's Letter är ett vattenmättat, ömsint brev som återfanns bland de sjunkna lämningarna efter en dvärgsoldat under Thandol Span. Det är adresserat till hans hustru Sara i Ironforge och vittnar om de stillsamma, personliga tragedier som dröjer sig kvar under Khaz Modans storslagna konflikter.",h="Sully Balloo's Letter är ett vattenmättat, ömsint brev som återfanns bland de sjunkna lämningarna efter en...",kw={"arathi highlands","ironforge","brev","sara balloo","sully balloo","thandol span","vattenmättat kuvert","wetlands"},ang={["faction:Alliance"]="Att lämna brevet skänker en sorgsen stund av medkänsla och ser till att en fallen soldats sista tankar når hans änka i stället för att glömmas under bron.",["race:Dwarf"]="För dvärgarna står brevet för de hjärtskärande uppoffringar som vanliga bergsbor och soldater gör för att skydda Khaz Modans höga broar och bergspass."},sec={{t="Ett sista farväl under vågorna",b="Under de väldiga stenpelarna i Thandol Span, som förbinder Wetlands med Arathi Highlands, ligger kvarlevorna av en dvärg, fastkilad djupt under det strömmande vattnet. I hans grepp finns ett skört, vattenmättat kuvert med brevet inuti. Det skrevs med stor omsorg under hans sista dagar eller timmar och börjar med de gripande orden: ”Min kära Sara....” Pergamentet har legat länge under vatten, men bläcket bär fortfarande spår av den okuvliga kärleken hos en dvärgförespråkare som aldrig kom hem till Ironforge."},{t="Leverans till Ironforge",b="Att lämna brevet till Sara Balloo i Ironforge ger ett sorgset och förkrossande avslut. Sara bor i dvärgarnas huvudstad och uthärdar den plågsamma ovisshet som delas av så många vars närstående drog ut i krig. När hon läser sin make Sullys sista tankar bekräftas hennes värsta farhågor: han dog långt hemifrån, under det nordliga övergångsställets iskalla strömmar. Ändå bevarar brevet hans hängivenhet bortom döden."}},faq={{q="Var hittas Sully Balloo's Letter?",a="Brevet hämtas ur ett vattenmättat kuvert som hålls i handen på ett skelett av en dvärg, nedsänkt på botten under Thandol Span, som skiljer Wetlands från Arathi Highlands.",al={"brevets plats","var finns sullys brev","var hittar man sully balloos brev"}},{q="Vem var Sully Balloo?",a="Sully Balloo var en dvärgsoldat som miste livet nära Thandol Span när han försvarade den viktiga norra övergången. Hans kvarlevor blev kvar under flodströmmarna.",al={"vem är sully balloo","sully balloos historia","vad hände med sully"}},{q="Vem är brevet adresserat till?",a="Brevet är adresserat till Mrs. Sara Balloo, Sullys sörjande hustru, som bor i den stora dvärgastaden Ironforge inne i berget.",al={"vem får brevet","vem är sara balloo","var lämnar man in sullys brev"}},{q="Vad händer när du lämnar brevet till Sara Balloo?",a="När Sara Balloo får brevet blir hon förkrossad över att få veta att hennes make ligger död och fastkilad under det iskalla vattnet. Samtidigt värdesätter hon chansen att läsa hans sista ord, kärleksfullt skrivna till henne.",al={"sara balloos reaktion","att lämna in brevet","slutföra uppdraget med sullys brev"}}},fx={efe638b9={q="Vad är Sully Balloo's Letter?",a="Det är ett ömt, krigshärjat brev som skrevs med stor omsorg av en dvärgsoldat vid namn Sully Balloo. Det hittades bevarat under det iskalla vattnet vid Thandol Span och innehåller de sista innerliga orden han skrev till sin hustru i Ironforge före sin död i strid.",al={"vad är sullys brev","sully balloos brev","om sully balloo's letter"}},b8624ec6={q="Varifrån kommer Sully Balloo's Letter, och vem skrev det?",a="Brevet skrevs av Sully Balloo, en soldat i Alliansen som tjänstgjorde vid frontlinjen på Thandol Span mellan Wetlands och Arathi Highlands. Det överlevde under vatten i ett genomblött kuvert, som hölls i greppet på hans nedsänkta kvarlevor under den väldiga bron.",al={"vem skrev sully balloo's letter","varifrån kom sully balloo's letter","skaparen av sully balloo's letter"}},b54d6872={q="Varför vill någon ha Sully Balloo's Letter?",a="Brevets mottagare, Sara Balloo, bor i Ironforge utan att känna till sin makes tragiska död. När du överlämnar brevet uppfyller du en fallen soldats sista önskan och ger ett bitterljuvt avslut åt en sörjande änka som väntar på nyheter om sin älskade.",al={"varför lämna över sully balloo's letter","vem vill ha sully balloo's letter","varför lämna brevet till sara balloo"}}},fp="21,158,34.417.0,21.302.1,37.168.0,21.155.0,31.82.0,56.160.1"}
P.entries["item:sundried-driftwood"] = {n="Sundried Driftwood",s="Sundried Driftwood ligger längs kusten vid Swamp of Sorrows. Watcher Biggs behöver starkt, torrt trä för att reparera sin vagn.",h="Sundried Driftwood ligger längs kusten vid Swamp of Sorrows.",kw={"kust","drivved","nethergarde","sundried driftwood","swamp of sorrows","vagn","watcher biggs"},sec={{t="Trä från kusten",b="Watcher Biggs behöver virke för att reparera sin vagn, men träden i träsket är för svampiga och snåriga. Längs den östra kusten torkar solen drivveden till lätta, tåliga stycken som passar hans behov."}},faq={{q="Var kan jag hitta Sundried Driftwood?",a="Sundried Driftwood finns längs kusten vid Swamp of Sorrows. Watcher Biggs hänvisar dig österut för att leta.",al={"var finns sundried driftwood","var finns drivved","trä från kusten"}},{q="Vem behöver drivveden?",a="Watcher Biggs behöver Sundried Driftwood för att reparera sin vagn.",al={"vem vill ha drivved","biggs trä","vem behöver träet"}},{q="Varför behöver Biggs det här träet?",a="Watcher Biggs behöver starkt, torrt trä för att reparera sin vagn så att han kan ta sig till Nethergarde.",al={"varför biggs behöver trä","reparation av vagn","laga biggs vagn"}},{q="Varför inte använda träden i träsket?",a="Watcher Biggs säger att träden i träsket är svampiga och snåriga, så han letar efter torr drivved från kusten.",al={"trä från träskets träd","varför inte trä från träsket","svampigt trä"}},{q="Hurdan är drivveden?",a="Watcher Biggs beskriver träet som lätt men tåligt och säger att det passar bra till hans vagn.",al={"är drivveden tålig","träets kvalitet","lätt tåligt trä"}},{q="Hur många stycken behöver Biggs?",a="Watcher Biggs ber om åtta stycken Sundried Driftwood.",al={"hur mycket drivved","antal stycken","åtta stycken drivved"}}},fp="18,115,19.189.0,36.111.0,24.59.0,30.85.0,28.102.0,27.89.0,32.58.0"}
P.entries["item:sunscorched-shell"] = {n="Sunscorched Shell",s="Sunscorched Shells är de tåliga resterna av wyvernägg som samlas under Highperchs boplatser i Thousand Needles. Den hårda ökenhettan gör dem eftertraktade bland skickliga rustningsmakare, som kan förädla dem till en skyddande lack för ringbrynjor.",h="Sunscorched Shells är de tåliga resterna av wyvernägg som samlas under Highperchs boplatser i Thousand...",kw={"darnassus","furen longbeard","highperch","ringbrynja","mathiel","sunscorched shell","thousand needles","wyvern"},ang={["class:Warrior"]="Krigare som söker skräddarsytt skydd i ringbrynja hjälper Mathiel att samla in de här tåliga äggskalen för att tillverka förstärkta rustningar.",["profession:Blacksmithing"]="Skalen visar hur uppfinningsrika smeder ser bortom vanliga malmer och förädlar naturliga mineralbeläggningar till skyddande lack för ringrustningar."},sec={{t="Ökenkullar",b="Högt uppe bland de nålvassa mesas i södra Kalimdor lägger Highperchs wyverner ägg som står emot den obevekliga ökensolen och de brännande vindarna. Kasserade skalbitar samlas under deras boplatser, där det torra klimatet bakar dem ovanligt hårda. För en vanlig vandrare ser de kanske bara ut som sprött avfall, men de här solbrända resterna har en naturlig hållfasthet som gör dem till en intressant ingrediens för specialiserade hantverkare."},{t="En hantverkares lack",b="I Darnassus studerar rustningsmakaren Mathiel tillverkningsmetoder som hans kollega, dvärgasmiden Furen Longbeard, har utvecklat. Mathiel lockas av Furens upptäckter och använder skalen för att skapa en fin lack som kan förstärka ringbrynjor. När den bearbetas och appliceras på rätt sätt fäster den mineralrika beläggningen vid metallringarna och ger dem avsevärt större tålighet utan att tynga ner bäraren."}},faq={{q="Var hittar man Sunscorched Shells?",a="De ligger utspridda på marken under wyvernbon runt Highperch, en hög mesa som reser sig från kanjonbottnen i västra Thousand Needles.",al={"sunscorched shell plats","var hitta skal","highperchskal"}},{q="Vilken varelse kommer skalen från?",a="De är krossade äggskal från Highperchs wyverner, som har sina boplatser uppe på platåerna i Thousand Needles.",al={"vad lade äggen","wyvernägg","skalens ursprung"}},{q="Varför vill Mathiel ha Sunscorched Shells?",a="Mathiel vill pröva rustningssmidestekniker som Furen Longbeard upptäckt. Han förädlar de hårdnade skalen till en tålig lack som täcker och förstärker ringarna i ringbrynjor.",al={"mathiels skal","vad används skal till","rustningslack"}},{q="Vem är Furen Longbeard och hur är han inblandad?",a="Furen Longbeard är kollega till Mathiel inom järnsmide och håller till i Dwarven District i Stormwind. Hans experiment med ovanliga ingredienser och härdningstekniker inspirerade Mathiel att experimentera med lack av wyverns skal.",al={"furens koppling","furen longbeards skal"}}},fx={f589915a={q="Vad är Sunscorched Shell?",a="Sunscorched Shell är det tåliga, kasserade äggskalet från en wyvern i Highperch. Skalen hittas soltorkade under den hårda solen i Thousand Needles, nedanför varelsernas högt belägna bon. De har en anmärkningsvärd naturlig styrka som gör dem eftertraktade bland skickliga rustningsmakare.",al={"vad är sunscorched shell","föremålet sunscorched shell","solbränt äggskal"}}},fp="17,131,15.237.0,21.234.0,35.126.0,40.102.0,41.153.0,46.211.0"}
P.entries["item:super-reaper-6000-blueprints"] = {n="Super Reaper 6000 Blueprints",s="Super Reaper 6000 Blueprints är de tekniska ritningarna till en enorm mekanisk skogshuggare som Venture Company använder i Stonetalon Mountains. Den har konstruerats under uppsikt av gnomingenjören Gerenzo Wrenchwhistle, och hans missnöjda rivaler bland goblinerna åtrår ritningarna starkt.",h="Super Reaper 6000 Blueprints är de tekniska ritningarna till en enorm mekanisk skogshuggare som Venture...",kw={"ritningar","gerenzo","sputtervalve","stonetalon","super reaper 6000","venture company","windshear crag","ziz fizziks"},ang={["profession:Engineering"]="Ritningarna visar en märklig blandning av rå goblinföretagsmakt och noggrann gnomisk mekanisk formgivning. De tekniska schemana förbryllar vanliga mekaniker.",["race:Gnome"]="Gerenzo Wrenchwhistles ritningar visar att även skoningslösa goblinsyndikat som Venture Company i slutändan förlitar sig på gnomisk uppfinningsrikedom för att bygga komplicerade tunga maskiner."},sec={{t="Industrispionage i Windshear Crag",b="Venture Companys skoningslösa kalhuggning i Windshear Crag bygger på enorma mekaniska timmermaskiner som kallas Super Reapers. Till traditionella gobliningenjörers stora förtret satte företaget en gnom vid namn Gerenzo att utforma modellen Super Reaper 6000. Ritningarna innehåller scheman till maskinen och bärs av Venture Co.-operatörer som arbetar med maskinerna runt klippan. När gobliningenjören Ziz Fizziks kastades ut ur verksamheten anställdes han snabbt av Sputtervalve för att stjäla ritningarna. Men att tyda Gerenzos täta, excentriska tekniska anteckningar på gnomiska visar sig vara nästan lika svårt som att ta ritningarna med våld."}},faq={{q="Vad är Super Reaper 6000?",a="Det är en enorm mekanisk skogshuggarmaskin som utvecklats för Venture Companys kalhuggning i Stonetalon Mountains. Den fäller och bearbetar timmer med skoningslös industriell effektivitet.",al={"vad är super reaper","super reaper-maskin"}},{q="Vem utformade Super Reaper 6000?",a="Ritningarna utarbetades under ledning av Gerenzo Wrenchwhistle, en gnomingenjör som Venture Company anställde för att leda deras mekaniska verksamhet i Windshear Crag, till de lokala goblinmekanikernas stora förtret.",al={"vem gjorde ritningarna","vem utformade super reaper"}},{q="Varför vill Ziz Fizziks ha ritningarna?",a="Ziz fick sparken från Venture Company och anställdes genast av Sputtervalve. Att stjäla ritningarna till Super Reaper är Ziz chans att bevisa sitt värde och sitt mekaniska geni för sin nya chef.",al={"varför vill ziz ha ritningarna","vem vill ha ritningarna"}},{q="Vem bär ritningarna i Windshear Crag?",a="De fysiska ritningarna bärs av Venture Co.-operatörer som övervakar maskinerna och avverkar timmer runtom i Windshear Crag.",al={"var får man ritningarna","vem släpper ritningarna"}}},fp="28,235,38.481.0,30.131.0,35.214.0,43.156.0,43.120.0"}
P.entries["item:super-snapper-fx"] = {n="Super Snapper FX",s="Super Snapper FX är Curgles kamera, som Daryn Lightwind lånar ut till dig i Rut'theran Village. Hon vill ha en bild på Gammerita, en varelse från The Hinterlands.",h="Super Snapper FX är Curgles kamera, som Daryn Lightwind lånar ut till dig i Rut'theran Village.",kw={"c amatör","c kamera","kamera","cargle","daryn lightwind","gammerita","ögonblicksbild","super snapper","super snapper fx"},sec={{t="En ny uppfinning",b="Daryn Lightwind skickar dig till Curgle för att hämta hans nya uppfinning, Super Snapper FX. Hon ber dig ta en bild på Gammerita, varelsen från The Hinterlands, och vill att du tar med bilden tillbaka till Rut'theran Village. Curgle säger att du ska rikta kameran mot motivet och trycka på knappen."}},faq={{q="Vad är Super Snapper FX?",a="Super Snapper FX är en kamera som Curgle har tillverkat. Daryn Lightwind lånar ut den till dig så att du kan ta en bild på Gammerita.",al={"super snapper","snapperkamera"}},{q="Vem vill ha en bild på Gammerita?",a="Daryn Lightwind i Rut'theran Village ber dig ta med en bild på Gammerita från The Hinterlands.",al={"vem behöver bilden","daryn bild"}},{q="Vem tillverkade Super Snapper FX?",a="Curgle byggde Super Snapper FX åt Daryn Lightwind.",al={"vem byggde snapper","curgle uppfinning"}},{q="Vad gör Super Snapper FX?",a="Rikta Super Snapper FX mot det du vill fotografera och tryck på knappen.",al={"hur fungerar snapper","kameraknapp"}}},fp="16,161,15.275.0,29.112.0,33.106.0,30.54.0,34.77.0"}
P.entries["item:super-sticky-tar"] = {n="Super Sticky Tar",s="I norra Un'Goro Crater fastnar tjäran från bestarna nära groparna ovanligt hårt. Tran'rek i Gadgetzan vill ha prover till en lönsam idé om lim.",h="I norra Un'Goro Crater fastnar tjäran från bestarna nära groparna ovanligt hårt.",kw={"klorofyll","gadgetzan","lim","superklibbig","super sticky tar","tjära","tjärbestar","tran'rek","un'goro crater"},sec={{t="Tjära från groparna",b="Tran'rek ber dig samla tjära från bestarna nära groparna i norra Un'Goro Crater. Deras hud innehåller klorofyll, som enligt honom gör tjäran mycket klibbigare än vanlig tjära. Han hoppas kunna göra blandningen till ett användbart lim."}},faq={{q="Varifrån kommer Super Sticky Tar?",a="Du samlar Super Sticky Tar från tjärbestarna nära groparna i norra Un'Goro Crater.",al={"varifrån tjära","super sticky källa"}},{q="Vem vill ha tjäran?",a="Tran'rek i Gadgetzan vill ha prover på Super Sticky Tar till sin idé om lim.",al={"vem behöver tjära","tran'rek tjära"}},{q="Varför är tjäran så klibbig?",a="Tran'rek säger att bestarnas klorofyllrika hud blandas med tjäran och gör den ovanligt klibbig.",al={"varför klibbig","orsak till klibbig tjära"}},{q="Vad planerar Tran'rek att göra med den?",a="Tran'rek hoppas kunna göra ett lönsamt lim av tjäran och klorofyllet i bestarnas hud.",al={"tran'reks plan","vad ska limmet användas till"}}},fp="16,152,17.228.0,38.90.0,18.74.0,26.97.0,38.94.0"}
P.entries["item:supplies-for-sven"] = {n="Supplies for Sven",s="Supplies for Sven är ett knippe livsviktiga förnödenheter som packats i Darkshire och ska till Sven Yorgens avskilda läger.",h="Supplies for Sven är ett knippe livsviktiga förnödenheter som packats i Darkshire och ska till Sven Yorgens...",kw={"läger","carevin","darkshire","duskwood","proviant","supplies for sven","sven yorgen"},ang={["class:Paladin"]="De fromma ser Svens orubbliga motstånd mot mörkret i Duskwood som ett sant verk av Ljuset. Därför är dessa förnödenheter en livsviktig tjänst åt en trosbroder.",["faction:Alliance"]="Night Watch är hårt ansatt i försvaret av Darkshire, så resenärer från Alliance fungerar ofta som den enda pålitliga kurirförbindelsen till avlägsna utposter som Svens läger."},sec={{t="En livlina till lägret",b="Att föra överlevnadsutrustning och basförnödenheter genom Duskwood är ingen enkel uppgift. Sven Yorgen och hans fåtaliga följeslagare slår läger i skogens nordvästra vildmark, långt från tryggheten i Darkshire. De är så få och deras vakthållning så krävande att de inte kan avvara en enda kämpe för att ta sig till staden. Paketet är en livlina från familjen Carevin och ser till att det isolerade lägret får mat, bandage och material som behövs för att hålla stånd."}},faq={{q="Vem skickade förnödenheterna?",a="Förnödenheterna skickas genom familjen Carevin i Darkshire. De inser hur desperat Sven Yorgen kämpar i vildmarken och ordnar proviant till hans läger.",al={"vem skickade supplies for sven","vem packade svens förnödenheter","familjen carevins förnödenheter"}},{q="Varför kan inte Sven hämta sina egna förnödenheter?",a="Svens grupp är alltför hårt ansatt. Bara några få överlevande följeslagare vaktar lägret i nordvästra Duskwood mot odjur och odöda, så de kan inte avvara någon som går längs de farliga vägarna till Darkshire.",al={"varför hämtar inte sven mat","varför leverans till sven","varför behövs förnödenheter"}},{q="Var ligger Svens läger?",a="Svens läger ligger längs Duskwoods nordvästra utkant, undangömt bland kullarna långt utanför Night Watchs direkta beskydd.",al={"var finns sven yorgen","svens lägerplats","hitta sven i duskwood"}},{q="Vem är Sven Yorgen?",a="Sven Yorgen är en nybyggare och hängiven troende på Ljuset som en gång brukade jord i Duskwood. Efter att en tragedi drabbat hans gård upprättade han ett beväpnat läger vid gränslandet för att slå tillbaka mot de mörka krafter som plågar trakten.",al={"vem är sven","sven yorgens bakgrund"}}},fx={["0c0166a3"]={q="Vad är Supplies for Sven?",a="Det här är ett stödpaket som samlats ihop åt Sven Yorgen och hans lilla grupp anhängare, som håller stånd i Duskwood. Familjen Carevin förbereder regelbundet sådan hjälp så att dessa hängivna korsfarare kan fortsätta utföra Ljusets arbete mot fasorna i den mörka skogen utan att överge sin vakt.",al={"vad är supplies for sven","vad är sven's supplies","föremålet supplies for sven"}}},fp="17,177,23.274.0,24.125.0,38.195.0,29.114.0,19.227.0"}
P.entries["item:supply-crate-blasted-lands"] = {n="Supply Crate",s="Supply Crate är övergiven utgrävningsutrustning som Sigrun Ironhew söker efter i Badlands. Innehållet kan hjälpa hennes hungriga kompani.",h="Supply Crate är övergiven utgrävningsutrustning som Sigrun Ironhew söker efter i Badlands.",kw={"badlands","camp kosh","utgrävning","mat","hägringar","sigrun ironhew","supply crate","uldu-man"},sec={{t="Kvarlämnad",b="Efter att i all hast ha lämnat utgrävningsplatsen i Uldaman övergav Sigrun Ironhews kompani vagnar och förrådslådor. Ogrer från Camp Kosh lade beslag på utrustningen, däribland en kärra med vapen. Kompaniet har blivit utan mat, och Sigrun ber dig hämta en Supply Crate."}},faq={{q="Vem vill ha Supply Crate?",a="Sigrun Ironhew vill att du hämtar Supply Crate åt hennes kompani i Badlands.",al={"vem behöver lådan","sigrun låda"}},{q="Var lämnades Supply Crate?",a="Lådan fanns bland förråden som övergavs när Sigrun Ironhews kompani flydde från utgrävningsplatsen i Uldaman.",al={"lådans plats","var är lådan"}},{q="Varför behöver Sigrun lådan?",a="Sigrun Ironhews kompani förlorade sina matförråd efter att og rer från Camp Kosh lade beslag på utrustningen. Hon ber dig hämta en Supply Crate.",al={"varför lådan","de behöver förråd"}},{q="Vad tog ogrerna?",a="Ogrer från Camp Kosh lade beslag på kompaniets övergivna utrustning, däribland en kärra med vapen.",al={"camp kosh ogrer","vad stal ogrerna"}},{q="Vad händer när du kommer tillbaka?",a="Sigrun tackar dig och säger sedan att kompaniet ska ge sig ut för att leta efter mat den kvällen.",al={"låduppdrag klart","sigruns svar"}}},fp="12,131,11.279.0,27.86.0,32.106.0,31.130.0,24.97.0,29.77.1"}
P.entries["item:surena-s-choker"] = {n="Surena's Choker",s="I Stormwind söker Gakin the Darkbinder efter halskedjan han gav sin före detta lärling, Surena Caledon. Efter att Surena flydde för att ansluta sig till Defias Brotherhood skickade Gakin aspirerande akolyter för att ta tillbaka den med våld.",h="I Stormwind söker Gakin the Darkbinder efter halskedjan han gav sin före detta lärling, Surena Caledon.",kw={"bloodstone choker","brackwell pumpkin patch","erlan drudgemoor","gakin the darkbinder","slaughtered lamb","surena caledon","surena's choker"},ang={["class:Warlock"]="För en mänsklig eller gnomisk häxmästare är återhämtandet av Surena Caledons halskedja ett grundläggande prov. Det visar att sentimentalitet inte hör hemma i jakten på demonisk makt."},sec={{t="En mästares förlorade investering",b="Gakin the Darkbinder verkar i tysthet under Slaughtered Lamb i Stormwind, där han tog sig an Surena Caledon som en lovande elev i de mörka konsterna. Fängslad av hennes ungdomliga charm och magiska fallenhet gav han henne en värdefull Bloodstone Choker för att hjälpa henne med studierna. Surena övergav sin utbildning och flydde med Erlan Drudgemoor, en skurk som stod i förbund med Defias Brotherhood. Gakin tänker inte låta en förrädare behålla en mäktig artefakt. Han skickar noviser som söker mästerskap över tomrummet för att hitta Surena vid Brackwell Pumpkin Patch och återta halskedjan med våld. Deras handling ska visa var den sanna lojaliteten finns."}},faq={{q="Varför vill Gakin the Darkbinder ha tillbaka Surena's Choker?",a="Gakin gav Surena halskedjan av blodsten när hon var hans lärling. Hon övergav sina studier och flydde med en medlem av Defias Brotherhood, men Gakin tänker inte låta en förrädare behålla en eftertraktad artefakt med mörk magi.",al={"varför vill gakin ha halskedjan","gakin surena halsband","varför ta tillbaka halskedjan"}},{q="Vem är Surena Caledon?",a="Surena Caledon är en före detta lärlingshäxmästare i Stormwind, där hon visade naturlig talang under Gakin the Darkbinder. Hon vände sig bort från sin läromästare och flydde med Erlan Drudgemoor. Nu gömmer hon sig bland Defias laglösa i Elwynn Forest.",al={"vem är surena","surena caledons bakgrund","vem har halskedjan"}},{q="Var finns halskedjan?",a="Surena Caledon bär halskedjan vid Brackwell Pumpkin Patch i östra Elwynn Forest, där hon håller sig gömd bland Defias banditer.",al={"var är surena","halskedjans plats","var är surena caledon"}},{q="Vad används halskedjan till när den har återtagits?",a="Att ta tillbaka halskedjan visar att en akolyt är hänsynslös och lojal mot Gakin the Darkbinder. Han säger inte vad han ska göra med den. Han sörjer Surenas bortkastade talang och hoppas att hans investering i den nya eleven ger andra resultat.",al={"vad gör gakin med halskedjan","halskedjans syfte","varför behöver häxmästare halskedjan"}}},fx={["195efbf9"]={q="Vad är Surena's Choker?",a="Det är ett utsmyckat halsband av blodsten som ursprungligen ägdes av Gakin the Darkbinder, mästerhäxmästaren som håller till på Slaughtered Lamb i Stormwind. Gakin gav det dyrbara smycket till sin före detta lärling Surena Caledon, när han var förtrollad av hennes ungdom och skönhet, innan hon förrådde honom.",al={"vad är surena's choker","vad är surena's choker för något","bloodstone choker"}},["7b9593ae"]={q="Varifrån kommer Surena's Choker, och vem tillverkade det?",a="Det är okänt vem som tillverkade halsbandet, men det tillhörde ursprungligen Gakin the Darkbinder. Gakin gav blodstenshalsbandet till sin unga elev Surena Caledon medan hon studerade för honom, långt innan hon rymde med en Defias-rövare till pumpaplatsen i Elwynn.",al={"vem tillverkade surena's choker","surena's choker ursprung","varifrån kom halsbandet"}}},fp="15,236,26.570.0,56.212.0,22.220.0,30.138.0,50.235.0"}
P.entries["item:swoop-gizzard"] = {n="Swoop Gizzard",s="En swoop kräva är en kroppsdel som samlas in från rovfåglarna som svävar över Mulgore. Den är mycket eftertraktad inom traditionell folkmedicin och är en viktig ingrediens för att rena kroppen från dödliga gifter.",h="En swoop kräva är en kroppsdel som samlas in från rovfåglarna som svävar över Mulgore.",kw={"bloodhoof village","kräva","maur raincaller","mazzranache","mulgore","botemedel","swoop"},ang={["race:Tauren"]="För taurenjägare och schamaner är insamlingen av sådana delar ett sätt att hedra traditionen att använda allt från Mulgore vilda djur för att försörja och läka stammen."},sec={{t="En sällsynt ingrediens inom folkmedicin",b="Swoops är rovfåglar som hör hemma på Mulgore slätter och platåberg. De är kända för sin skarpa syn och vana att äta as. Deras fjädrar och kött används till vardags av tauren, men deras inre organ, särskilt krävan, är högt värderade av örtmedicinare och helare. Tillsammans med andra kraftfulla djurrester, som cougarben och varghjärtan, hjälper den täta muskelvävnaden till att neutralisera giftiga bett och hejda infektioner som sprider sig i kroppen."},{t="Ett botemedel mot Mazzranaches bett",b="I Bloodhoof Village blev medicinarbetaren Maur Raincaller offer för den legendariska plainstridern Mazzranache och fick ett svårt, giftigt sår i axeln. Giftet spred sig och fick Maur att bli omtöcknad. Han förlitar sig på en swoop kräva, ett prairie wolf heart, ett Flatland Cougar Femur och en Plainstrider Scale för att blanda ett läkande omslag som kan driva ut odjurets dödliga gift."}},faq={{q="Vad används en swoop kräva till?",a="Det är en viktig medicinalingrediens som Maur Raincaller behöver i Bloodhoof Village. Tillsammans med tre andra djurdelar blir den ett botemedel som kan rena infektionen från den giftiga plainstridern Mazzranaches våldsamma bett.",al={"användning av swoop kräva","varför behöver jag swoop kräva","syftet med swooporgan"}},{q="Var kommer swoop krävor ifrån?",a="De samlas in från olika swooparter som glider över Mulgore slätter, däribland vanliga swoops, spensliga swoops och kloswoops.",al={"var hittar man swoop kräva","vad släpper swoop kräva","swoopjakt"}},{q="Varför behöver Maur Raincaller just den här kroppsdelen?",a="Maur blev biten av Mazzranache, en ovanligt våldsam plainstrider vars bett sprider ett gift som orsakar hög feber och mardrömmar. Taurenernas traditionella läkekonst använder kraftfulla djurdelar, däribland krävan, för att motverka de särskilda gifterna i hans blod.",al={"maurs botemedel","varför en kräva","botemedel mot mazzranache"}},{q="Används krävan till något annat än Maurs botemedel?",a="Nej. Förutom Maur Raincallers särskilda folkmedicin i Bloodhoof Village har swoop krävor inga vanliga användningsområden inom matlagning, alkemi eller hantverk.",al={"andra användningar av swoop kräva","tillaga swoop kräva","alkemi med swoop kräva"}}},fx={["8f6be1e3"]={q="Vad är Swoop Gizzard?",a="Swoop Gizzard är ett inre organ från rovfåglarna som kallas swoops och glider fram över Mulgore-slätterna. Liksom många fågelorgan hjälper det till att bryta ner segt byte. I traditionell taurenmedicin värdesätts sådana kraftfulla, specialiserade djurdelar för sina naturliga egenskaper och används som ingredienser i örtmediciner och stärkande brygder.",al={"vad är swoop gizzard","föremålet swoop gizzard","vad är en swoop gizzard"}}},fp="13,123,22.322.0,31.338.0,33.200.0,34.128.0,49.218.0,56.147.0"}
P.entries["item:symbol-of-ragnaros"] = {n="Symbol of Ragnaros",s="Symbol of Ragnaros är en relik från Twilight's Hammer som hittats i Searing Gorge. Velarok söker dess orena magi för att skapa ett hölje åt Torch of Retribution.",h="Symbol of Ragnaros är en relik från Twilight's Hammer som hittats i Searing Gorge.",kw={"facklans hölje","oren magi","ragnaros","searing gorge","symbol of ragnaros","torch of retribution","twilight's hammer","velarok"},sec={{t="Oren magi",b="Velarok Windblade behöver en Symbol of Ragnaros till Torch of Retribution. Han tror att Twilight's Hammers läger i bergen nordväst härifrån rymmer symboler och avgudar med tillräcklig kraft för att forma facklans hölje. Symbolens magi passar hans syfte."}},faq={{q="Vad är Symbol of Ragnaros?",a="Det är en symbol som bärs av Twilight's Hammer, och dess magi kan hjälpa till att forma ett hölje åt Torch of Retribution.",al={"symbol of ragnaros","ragnaros symbol"}},{q="Vem vill ha symbolen?",a="Velarok Windblade behöver Symbol of Ragnaros för att göra höljet till Torch of Retribution.",al={"vem vill ha den","vad behöver velarok"}},{q="Varför behöver Velarok den?",a="Velarok hoppas kunna utvinna dess orena magi och använda den för att forma ett hölje åt Torch of Retribution.",al={"varför behövs symbolen","facklans hölje"}},{q="Var kan jag hitta en?",a="Det ryktas att Twilight's Hammers läger i bergen nordväst härifrån rymmer symboler och avgudar.",al={"var finns symbolen","hitta ragnaros symbol"}}},fp="18,151,10.262.0,31.115.0,21.89.0,25.97.0,21.105.0"}
P.entries["item:tablet-of-verga"] = {n="Tablet of Verga",s="I Skull Rock ligger Tablet of Verga i Burning Blades händer. Warlocks i Orgrimmar söker dess demoniska runor.",h="I Skull Rock ligger Tablet of Verga i Burning Blades händer.",kw={"burning blade","cleft of shadow","durotar","gan'rul bloodeye","skull rock","tablet of verga","voidwalker"},ang={["class:Warlock"]="Som warlocklärling i Orgrimmar visar du med återtagandet av tavlan att du är värdig Horde och tar ett steg mot att lära dig binda en voidwalker som försvarstjänare.",["faction:Horde"]="Som medlem av Horde möter du Burning Blade nära Orgrimmars portar. När du tar stulna reliker från kulten slår du mot dess inflytande över Thralls unga nation."},sec={{t="En stulen relik",b="Tablet of Verga bär rituella runor för att åkalla varelser från Nether och böja dem efter en mästares vilja. Kulten Burning Blade stal stenen och gömde den i en kista inne i Skull Rock, strax öster om Orgrimmar. Warlocks i The Cleft of Shadow söker den för att studera tecknen och lära sig att åkalla en voidwalker. Om du återtar den hindrar du också kulten från att få samma fördel."}},faq={{q="Var finns Tablet of Verga?",a="Tablet of Verga är gömd i en Burning Blade Stash inne i Skull Rock, ett grottkomplex som kryllar av kultister strax öster om Orgrimmar i Durotar.",al={"tablet of verga plats","var hittar man tablet of verga","var finns verga tablet"}},{q="Vem vill att Tablet of Verga återtas?",a="Gan'rul Bloodeye, en mästerwarlock i The Cleft of Shadow under Orgrimmar, skickar lärlingar för att hämta tavlan så att han kan lära dem att åkalla mäktigare tjänare.",al={"vem behöver tablet of verga","vem ska jag lämna tablet of verga till","gan'ruls tavla"}},{q="Vilken kraft innehåller tavlan?",a="Stenen bär uråldriga runor som behövs för att åkalla och binda en voidwalker, en varelse från Twisting Nether.",al={"vad gör tavlan","tablet of verga bakgrund","tablet of verga runor"}},{q="Varför stal Burning Blade den?",a="Kulten Burning Blade försöker störa Horde och öka sin demoniska makt. När du stjäl tavlan undanhåller du Orgrimmars utövare viktig ritualkunskap, medan kulten behåller den för egen del.",al={"varför har burning blade tavlan","burning blade verga"}}},fx={["5fa1e5b5"]={q="Vad är Tablet of Verga?",a="Tablet of Verga är en relik med inristad mystisk kunskap om häxmästare, särskilt runorna och ritualerna som krävs för att åkalla och binda en voidwalker. Den stals av kultister från Burning Blade och innehåller mörka hemligheter som häxmästare värdesätter när de vill bemästra Twisting Nether och kalla demoner till sin tjänst.",al={"vad är tablet of verga","tablet of verga","verga-tabletten"}}},fp="15,117,14.387.0,37.143.0,40.162.0,35.112.0,35.197.0"}
P.entries["item:tablet-shard"] = {n="Tablet Shard",s="Tablet Shard kommer från en uråldrig trolltavla under Vile Reef. Kin'weelay söker den till en helig plats i Orgrimmar, där den kan hedra Darkspear-hjälten Gri'lek.",h="Tablet Shard kommer från en uråldrig trolltavla under Vile Reef.",kw={"darkspear","gri'lek","gri'lek the wanderer","kin'weelay","the savage coast","tablet shard","trolltavla","the vile reef"},ang={["faction:Horde"]="Darkspear-stammen söker Tablet Shard till en helig plats i sitt nya hem i Orgrimmar.",["race:Troll"]="Som troll bär Tablet Shard den heliga berättelsen om Gri'lek, en hjälte i trolllegenderna, och ska hedra honom bland Darkspear."},sec={{t="Ett fragment av Gri'lek",b="Under Savage Coasts vatten hämtas Tablet Shard från en tavla med berättelsen om Gri'lek the Wanderer. Kin'weelay vill ha ett fragment till Darkspear-stammens nya hem i Orgrimmar. Där ska det påminna stammen om Gri'leks styrka och ära."}},faq={{q="Vad är Tablet Shard?",a="Tablet Shard är ett fragment av en uråldrig trolltavla under Vile Reef. Den bär berättelsen om Gri'lek the Wanderer.",al={"tablet shard","vilken skärva","trolltavlebit"}},{q="Vem vill ha Tablet Shard?",a="Kin'weelay i Grom'gol Base Camp vill ha Tablet Shard till en helig plats i Orgrimmar.",al={"vem vill ha skärvan","kin'weelay skärva","vem ska få den"}},{q="Varför vill Darkspear-stammen ha den?",a="Skärvan ska hedra Gri'lek the Wanderer och påminna Darkspear-stammen om hans styrka och ära.",al={"varför skärvan","darkspear-tavla","vad används den till"}},{q="Var finns tavlan?",a="Tavlan ligger under Savage Coasts vatten, i ruinerna som kallas Vile Reef.",al={"tavlans plats","varifrån kommer skärvan","vile reef-tavla"}}},fp="12,174,21.260.0,25.123.0,27.88.0,37.96.0,20.92.0"}
P.entries["item:tainted-heart"] = {n="Tainted Heart",s="Tainted Heart är en vanhelgad blomkärna som utvunnits ur Teldrassils fördärvade växtlighet. Botanisten Denalan ger den till äventyrare. Den måste renas med magi och näring för att bli fri från kvarvarande onda energier.",h="Tainted Heart är en vanhelgad blomkärna som utvunnits ur Teldrassils fördärvade växtlighet.",kw={"rening","fördärv","denalan","lake al'ameth","planteringskruka","tainted heart","teldrassil"},ang={["class:Druid"]="För cenariska druider ger arbetet med att rena Tainted Heart direkt insikt i det smygande fördärv som hotar det unga världsträdets hälsa.",["profession:Herbalism"]="Örtalister och botanister kan uppskatta Denalans hantverk när han blandar särskilt berikad jord som kan dra ut onaturlig röta ur levande växtmaterial."},sec={{t="En Corrupted Core",b="Teldrassils naturliga balans lider av en onaturlig sjukdom som förvrider dess inhemska växter och djur. Efter att ha avlägsnat den onda mossan som klamrade sig fast vid en vanhelgad växt visar Denalan upp kärnan som blivit kvar: Tainted Heart. Även om den befriats från sin yttre röta genomsyrar mörkret fortfarande vävnaden. Denalan vill ta reda på om särskilt berikad, näringsrik jord kan motverka den kvarvarande smittan och återställa livet i det som fördärvats."},{t="Denalans botemedel",b="När hjärtat placeras i Denalans förtrollade planteringskruka uppvisar det en märklig, kvardröjande livskraft. Det borrar sig ivrigt ner i den näringsrika jorden och tar upp de läkande ämnena. Inom några ögonblick bränner jorden bort fördärvet, och det renade hjärtat kommer fram levande och pulserande av ren energi, ivrigt att försvara dem som helade det."}},faq={{q="Vad är Tainted Heart?",a="Det är den inre kärnan från en fördärvad växt på Teldrassil. Botanisten Denalan avlägsnade den yttre, onda mossan, men själva hjärtat är fortfarande genomsyrat av fördärv tills det renas.",al={"vad är tainted heart","föremålet tainted heart"}},{q="Vem renar Tainted Heart?",a="Denalan ber äventyrare att plantera det i hans särskilt förberedda planteringskruka vid Lake Al'Ameth. Den näringsrika jorden renar naturligt hjärtat och sköljer bort dess onaturliga fördärv.",al={"vem renar det","hur rena tainted heart"}},{q="Vad händer efter att det planterats?",a="Hjärtat borrar sig aktivt ner i planteringskrukans jord. Några ögonblick senare kommer det upp igen, helt renat och pulserande av livskraft, redo att knyta an till den som återställde det.",al={"vad händer med hjärtat","resultat av planterat hjärta"}},{q="Varför är hjärtat fördärvat från början?",a="En märklig farsot har spridit sig över världsträdet Teldrassil och fördärvat dess inhemska växter, timberlings och djurliv bland grenarna.",al={"varför fördärvat","teldrassils fördärvade hjärta"}}},fx={ae8829e0={q="Varför vill Denalan att du planterar Tainted Heart?",a="Denalan har lyckats skrapa bort den vidriga mossan som täcker hjärtat, men dess inre kärna är fortfarande djupt fördärvad. Han hoppas att den näringsrika jorden i den specialpreparerade planteringslådan ska läka skadan, dra ut fördärvet och återställa det levande fröet till sin forna kraft.",al={"varför plantera tainted heart","tainted hearts syfte","varför vill denalan ha tainted heart"}}},fp="13,150,16.325.0,16.267.1,26.165.0,31.186.0,33.144.1,46.132.0"}
P.entries["item:tainted-keg"] = {n="Tainted Keg",s="Tainted Keg är en tunna med stulet dvärgstout spetsat med en dödlig Forsaken-brygd som Apothecary Lydon har blandat till.",h="Tainted Keg är en tunna med stulet dvärgstout spetsat med en dödlig Forsaken-brygd som Apothecary Lydon har...",kw={"apothecary lydon","tillfångatagna bönder","dun garok","elixir of agony","shindigger stout","tainted keg","tarren mill"},ang={["race:Human"]="Massakern på tillfångatagna lantarbetare med spetsat öl visar de fasansfulla, skoningslösa metoder som de levande kvarlevorna i Hillsbrad ställs inför.",["race:Undead"]="För Royal Apothecary Society är det förgiftade ölet ett praktiskt framsteg i utvecklingen av biologiska vapen som kan utrota mänskligheten."},sec={{t="En dödlig årgång",b="Tunnan började som en tunna Shindigger Stout, plundrad från dvärgarnas gevärsskyttar som förskansat sig i Dun Garok. I stället för att dricka ölet förgiftade Apothecary Lydon det mustiga ölet med sitt nyförfinade Elixir of Agony. Genom att spetsas en vanlig dryck skapade Forsaken ett lömskt sätt att sprida giftet, utformat för att undgå misstankar och förvandla något välbekant för de levande till en snabb dödsdom."},{t="Prövning på de dödsdömda",b="Flera mänskliga bönder hölls fångna på övervåningen i värdshuset i Tarren Mill efter att High Executor Darthalia misstänkt att en militärstrateg från Stormwind gömde sig bland dem. När beskedet kom att strategen hade dött någon annanstans blev de tillfångatagna arbetarna förbrukningsbara. Darthalia överlämnade dem till Lydon, som ordnade ett grymt firande genom att låta ställa den förgiftade tunnan på mattan i deras rum. Törstiga och desperata drack fångarna obehindrat och bevisade elixirets omedelbara, dödliga verkan."}},faq={{q="Vad finns i Tainted Keg?",a="Den innehåller Shindigger Stout, ett mustigt dvärgårt stulet från Dun Garok, blandat med Elixir of Agony, ett experimentellt gift som Apothecary Lydon skapade i Tarren Mill.",al={"innehållet i tainted keg","vilket gift finns i tunnan","vad finns i tunnan"}},{q="Varifrån kom ölet ursprungligen?",a="Grundbrygden togs från dvärgarnas bergsjägare och gevärsskyttar som höll Dun Garok, en välförsvarad dvärgfästning i sydöstra Hillsbrad Foothills.",al={"vem tillverkade ölet","var stals ölet","shindigger stout ursprung"}},{q="Vem dricker ur tunnan?",a="En grupp mänskliga bönder som hålls som gisslan i ett rum på övervåningen i värdshuset i Tarren Mill dricker ur tunnan, faller ihop och dör nästan omedelbart av den förgiftade brygden.",al={"vem dricker det","offer för tainted keg","tillfångatagna bönder"}},{q="Varför hölls bönderna fångna?",a="High Executor Darthalia grep dem eftersom hon misstänkte att en militärstrateg från Alliansen i Stormwind gömde sig i deras led. När det bekräftades att strategen hade dött i Plaguelands ansågs de tillfångatagna bönderna vara värdelösa och överlämnades till apotekarna.",al={"varför fångna bönder","varför grep darthalia bönder","varför finns bönder i tarren mill"}}},fx={fd5e0197={q="Vad är Tainted Keg?",a="Tainted Keg är en tunna med stulet dvärgöl av sorten Shindigger Stout, spetsat med en dödlig brygd som Forsaken har blandat till. Apothecary Lydon skapade den här förgiftade satsen som ett praktiskt försök i sin pågående alkemiska forskning.",al={"vad är tainted keg","föremålet tainted keg","vad är det här för tunna"}},["5c778a45"]={q="Varför vill Apothecary Lydon att Tainted Keg används?",a="Apothecary Lydon vill få tunnan levererad för att pröva effekten av sin nyfärdiga Elixir of Agony. High Executor Darthalia har överlämnat tillfångatagna mänskliga bönder åt honom. Genom att bjuda dem på förgiftat öl får Royal Apothecary Society ett bekvämt sätt att på nära håll studera giftets dödliga effekter.",al={"varför använda tainted keg","varför vill lydon ha tainted keg","tainted kegs syfte"}}},fp="11,201,16.276.0,24.458.1,31.151.0,39.136.0,24.115.1,41.243.0"}
P.entries["item:tainted-letter"] = {n="Tainted Letter",s="Drusilla La Salle skickar Tainted Letter till mänskliga häxmästaradepter nära Northshire Abbey. Det bär hennes sigill och uppmanar dem att söka hennes undervisning i hemlighet.",h="Drusilla La Salle skickar Tainted Letter till mänskliga häxmästaradepter nära Northshire Abbey.",kw={"drusilla la salle","elwynn forest","northshire abbey","tainted letter","twisting nether","häxmästare"},ang={["class:Warlock"]="Som häxmästare får du Tainted Letter som din introduktion till den skuggfyllda konsten i kungariket Stormwind. Makt över Nether kräver ständig vaksamhet och diskretion.",["race:Human"]="Som människa lever du i ett samhälle som i stort värnar det heliga ljuset. Utövare av mörk magi tränar i hemlighet i utkanterna av platser som Northshire Abbey."},sec={{t="En hemlig kallelse",b="Tainted Letter bär Drusilla La Salles insignier och når adepter som återvänder från närliggande koboldläger. Medan präster, paladiner och soldater tränar öppet på Northshire Abbeys gräsmattor måste utövare av felmagi hålla sin väg hemlig. Brevet uppmanar novisa häxmästare att söka upp sin mentor nära klosterområdet utan att dra till sig stadsvakternas eller prästernas uppmärksamhet."},{t="Ambitionens pris",b="Drusilla La Salle träffar sina elever i utkanterna, där vakter är mindre benägna att snoka. Elwynns vanliga folk misstror häxmästare, så brevet inleder en lektion i disciplin. Arkana och magi från Nether innebär risk för fördärv. De som samtalar med varelser från Twisting Nether måste tygla sin ambition med tålmodig självbehärskning."}},faq={{q="Vem skickade Tainted Letter?",a="Drusilla La Salle, häxmästartränaren nära Northshire Abbey, skickade brevet.",al={"vem skrev tainted letter","drusillas brev","avsändaren av tainted letter"}},{q="Varför anses brevet vara besmittat?",a="Brevet bär Drusilla La Salles insignier och spår av felmagi, vilket visar att det är verk av en utövare av demoniska konster.",al={"varför är det besmittat","vad gör brevet besmittat","besmittat sigill"}},{q="Varför håller vakterna i Northshire Drusilla La Salle under uppsikt?",a="Northshires vakter och präster misstror felmagi och demonisk frammaning. Drusilla håller sig i klostrets utkanter för att undvika myndigheternas noggranna uppsikt.",al={"drusilla och vakterna","varför misstänker vakterna drusilla","häxmästare gömmer sig i northshire"}},{q="Vilka råd ger Drusilla när man läser brevet?",a="Drusilla varnar för att umgänge med väsen från Twisting Nether medför frestelser och fördärv. Hon uppmanar sina elever att visa självbehärskning och eftertanke samtidigt som de håller fast vid sin ambition.",al={"drusillas råd","vad säger drusilla","drusillas undervisning"}}},fx={["63258adc"]={q="Vad är Tainted Letter?",a="Tainted Letter är ett förseglat meddelande som lämnats åt dig när du återvänder till Northshire Abbey, stämplat med Drusilla La Salles omisskännliga personliga sigill. Det är adresserat till nybörjare inom mörka konster och kallar dig skyndsamt till ett personligt samtal med henne. Det bär svaga spår av felkorruption, vilket tydligt skiljer det från den fromma och ordnade utövningen av det Heliga Ljuset innanför klostrets murar.",al={"vad är tainted letter","tainted letters identitet","om tainted letter"}},["3c923280"]={q="Varför får du Tainted Letter?",a="Du får brevet så att du kan ta kontakt med din tränare, Drusilla La Salle, så snart dina första uppgifter i Northshire är avklarade. Drusilla verkar i det tysta i klostrets utkanter och håller utkik efter blivande häxmästare. Brevet ber dig söka upp henne innan andra ärenden i klostret kommer emellan, så att hon kan ge dig viktiga varningar om självbehärskning, ambition och Twisting Nethers fördärvande natur.",al={"varför behöver jag tainted letter","vem vill ha tainted letter","varför ge tainted letter"}}},fp="14,130,16.336.0,21.323.0,28.78.0,37.117.0,53.145.0,55.187.0"}
P.entries["item:tainted-memorandum"] = {n="Tainted Memorandum",s="Tainted Memorandum är en diskret lapp som ges till unga gnomiska häxmästare i Coldridge Valley. Häxmästarläraren Alamar Grimm har skrivit den och uppmanar läsaren att överge traditionella vägar och söka den sanna kraft som de mörka konsterna erbjuder.",h="Tainted Memorandum är en diskret lapp som ges till unga gnomiska häxmästare i Coldridge Valley.",kw={"alamar grimm","anvilmar","coldridge valley","gnomisk häxmästare","gnomeregan","tainted memorandum"},ang={["class:Warlock"]="Lappen markerar din formella introduktion till häxmästarträning under Alamar Grimm och framställer mörk åkallan som en nödvändig strävan efter kontroll och makt.",["race:Gnome"]="Grimms budskap spelar på gnomernas bitterhet över förlusten av Gnomeregan och deras upplevda ställning som beroende flyktingar i dvärgarnas länder."},sec={{t="En diskret kallelse",b="I den kyliga dvärgiska utposten Anvilmar är utövare av felmagi varken hyllade eller särskilt betrodda. För unga gnomer som prövar förbjudna konster fungerar Tainted Memorandum som en inbjudan från Alamar Grimm. Budskapet avvisar beroendet av det heliga ljuset eller vanligt stridsstål och pekar i stället på Gnomeregans fall som bevis för att traditionella metoder och uppfinningsrikedom har svikit deras folk. För Grimm leder det ingenstans att förlita sig på dvärgisk välgörenhet. Gnomer måste ta obestridlig makt i egna händer och kalla fram lydiga tjänare om de någonsin ska kunna säkra sin egen framtid."}},faq={{q="Vem skrev Tainted Memorandum?",a="Memorandumet skrevs av Alamar Grimm, den gnomiska häxmästarläraren som är stationerad i Anvilmar i Coldridge Valley.",al={"författare tainted memorandum","vem skickade tainted memorandum","alamar grimm lapp"}},{q="Varför anses memorandumet vara ”besudlat”?",a="Det handlar direkt om förbjuden häxmästarmagi. Titeln speglar misstron och stigmat kring demonisk kraft och felkraft i Dun Morogh, där de dvärgiska värdarna håller utövarna på avstånd.",al={"varför besudlad","tainted letter bakgrund"}},{q="Vad säger Alamar Grimm om Gnomeregan?",a="Grimm känner bitterhet över den gnomiska huvudstadens fall och skyller på traditionell arkana magi och vårdslöst experimenterande för att ha fört deras folk nära utrotning. Han tror att dvärgarna ser gnomer som andra klassens medborgare och uppmanar häxmästare att finna sin egen absoluta kraft i stället för att vänta på hjälp från Alliansen.",al={"alamar grimm gnomeregan","alamar grimms åsikter"}}},fx={["0c729b68"]={q="Vad är Tainted Memorandum?",a="Tainted Memorandum är ett diskret, personligt meddelande till lovande gnombaserade häxmästare som just har påbörjat sin träning i Coldridge Valley. Allierade på ytan förmedlar lappen i hemlighet. Den bjuder in dig att se bortom Heliga Ljusets traditioner och fysisk strid, och i stället söka upp likasinnade, fördomsfria utövare av mörka konster.",al={"vad är tainted memorandum","tainted memorandum","vad är det här för lapp"}},e7be2e4a={q="Varför vill någon att du ska ha Tainted Memorandum?",a="Memorandumet ges till dig för att rekrytera dig till häxmästarnas krets. Häxmästartränaren Alamar Grimm skickar det för att hitta nybörjare som förkastar vanliga dvärg- och gnomdogmer. Han uppmanar dig att träffa honom i Anvilmar för att bemästra lydiga, åkallade bundsförvanter och upptäcka den sanna källan till demonisk kraft.",al={"varför fick jag memorandumet","varför tainted memorandum","vem vill ha tainted memorandum"}}},fp="18,125,18.486.0,33.82.0,43.180.0,44.277.0"}
P.entries["item:talisman-of-corruption"] = {n="Talisman of Corruption",s="Talisman of Corruption är en vidrig demonisk prydnad som satyren Xabraxxis använder för att förgifta Blackwoodfurbolgernas sinnen i Darkshore. Den bärs i satyrens personliga pung och fungerar som en magisk kanal som binder stammen till kaos från avgrunden.",h="Talisman of Corruption är en vidrig demonisk prydnad som satyren Xabraxxis använder för att förgifta...",kw={"auberdine","blackwood","darkshore","furbolg","satyr","talisman of corruption","thundris windweaver","xabraxxis"},ang={["class:Druid"]="Druider ser föremål som talismanen som direkta förvrängningar av naturens ordning. De förvandlar heliga bestar till vilda brickor åt Burning Legions kvarvarande tjänare.",["race:NightElf"]="För Kaldorei i Auberdine är det ett viktigt steg mot att befria sina furbolgallierade från demonisk förnedring och läka landet att återfinna talismanen."},sec={{t="En kanal till vansinne",b="Nattalverna i Auberdine har länge försökt förstå varför Blackwoodfurbolgerna vände sig så aggressivt mot sina forna allierade. Thundris Windweaver upptäckte att stammens fall inte var en naturlig utveckling, utan ett medvetet sabotage utfört av satyrerna. Med talismaner som den här sprider demoniska agenter fördärvande trolldom över vildmarken, förgiftar matförråd och förvandlar fridfulla skogsandar till ursinniga bestar. Genom att kanalisera vidrig magi direkt genom dessa föremål håller satyrerna ett obevekligt grepp om de lokala stammarnas sinnen och vilja."},{t="Bryta greppet",b="För att locka fram den ansvariga satyren måste äventyrare rena prover av furbolgernas mat med välsignat månskensbrunnsvatten och rena lägret tillräckligt länge för att reta upp dess övervakare. När Xabraxxis dödas bryts hans omedelbara grepp, och hans demonväska blir deras byte. Talismanen ligger inuti. Om talismanen lämnas till Thundris Windweaver i Auberdine kan Kaldorei oskadliggöra dess vidriga utstrålning och undersöka hur den demoniska plåga som härjar i skogen kan upphävas för gott."}},faq={{q="Vad är Talisman of Corruption?",a="Det är ett demoniskt föremål som satyren Xabraxxis använder för att kanalisera vidrig magi och fördärva Blackwoodfurbolgernas sinnen och matförråd i Darkshore.",al={"vad är talisman of corruption","talismanens syfte","vad gör talismanen"}},{q="Vem bär talismanen?",a="Den förvaras i demonväskan som bärs av Xabraxxis, en satyr som övervakar det norra Blackwoodfurbolglägret nära Cliffspring River.",al={"vem droppar talisman of corruption","var hittar man talisman of corruption","hur får man tag på talismanen"}},{q="Hur lockar du fram talismanens ägare?",a="Du måste samla prover av furbolgernas frukt, säd och nötter, blanda dem med månskensbrunnsvatten i en reningsskål och ställa fram offret vid bålet nära floden. När furbolgerna renas blir Xabraxxis rasande och går till attack.",al={"hur tillkallar man xabraxxis","hur hittar man xabraxxis","tillkalla satyr i darkshore"}},{q="Vad händer med talismanen när den återfunnits?",a="Den lämnas över till Thundris Windweaver i Auberdine. Han säkrar artefakten för att den ska kunna förstöras och studerar den för att lära sig hur furbolgerna kan befrias från demoniskt fördärv för gott.",al={"vem ska jag lämna talismanen till","lämna in talisman of corruption","thundris windweaver talisman"}}},fp="22,194,20.379.0,17.350.1,35.126.0,25.134.0,46.205.0,51.160.0"}
P.entries["item:tallonkai-s-jewel"] = {n="Tallonkai's Jewel",s="Tallonkai's Jewel är en lysande smaragd som stals från en förtrollad druidsk talisman på Teldrassil. Den dyrkas av furbolgmystikern Ferocitas the Dream Eater och är den avgörande mittstenen som krävs för att laga Emerald Dreamcatcher.",h="Tallonkai's Jewel är en lysande smaragd som stals från en förtrollad druidsk talisman på Teldrassil.",kw={"dolanaar","emerald dreamcatcher","ferocitas the dream eater","gnarlpine-mystiker","starbreeze village","tallonkai swiftroot","tallonkai's jewel"},ang={["class:Druid"]="Smaragden är en druidisk komponent som är avstämd för att genljuda med The Emerald Dream. Att missbruka den är därför en kränkning av balansen.",["race:NightElf"]="När juvelen återtas bidrar det till att återställa ordningen på Teldrassil genom att rycka heligt hantverk ur händerna på de framryckande Gnarlpine."},sec={{t="En stulen kärna",b="Tallonkai Swiftroot fick Emerald Dreamcatcher av Gaerolas Talvethen, druidernas väktare i Ban'ethil Barrow Den, som ett kraftfullt fokus som suger åt sig energi från The Emerald Dream. När hans talisman skadades bändes den strålande smaragden i mitten loss och fördes bort till östra Teldrassils vildmarker. Juvelen hamnade i Ferocitas the Dream Eaters klor, en korrumperad ledare för Gnarlpine som gjorde den glänsande stenen till ett personligt halsband. Den gröna stenen spred ett kusligt sken i skogens mörker, men dess verkliga, harmoniska resonans var helt oanvändbar för furbolgen och fungerade bara som en trofé tills den återtogs."}},faq={{q="Vad är Tallonkai's Jewel?",a="Det är en förtrollad, lysande smaragd som utgör mittstenen i Emerald Dreamcatcher, ett druidiskt fokus som Gaerolas Talvethen gav till Tallonkai Swiftroot i Dolanaar.",al={"vad är juvelen","tallonkai jewel berättelse"}},{q="Vem stal Tallonkai's Jewel?",a="Den stals av Ferocitas the Dream Eater, en ledare bland de korrumperade Gnarlpine-mystikerna som bor norr om Starbreeze Village.",al={"vem har juvelen","vem stal den","vem tog tallonkai's jewel"}},{q="Kan Gnarlpine-furbolgarna använda juvelens kraft?",a="Nej. Ferocitas bar smaragden runt halsen som en lysande prydnad, men Tallonkai säger att stenens druidiska kraft är helt oanvändbar för de korrumperade furbolgarna.",al={"kan ferocitas använda den","gnarlpine smaragdens kraft"}},{q="Vart förs juvelen när den återtas?",a="Stenen återlämnas till Tallonkai Swiftroot på den övre nivån i Dolanaar, där han använder den för att återställa och laga Emerald Dreamcatcher helt.",al={"vad händer med juvelen","laga dreamcatcher"}}},fx={["4dd99e12"]={q="Varför vill någon ha Tallonkai's Jewel?",a="Tallonkai Swiftroot behöver desperat få tillbaka den lysande smaragden för att kunna laga sin skadade Emerald Dreamcatcher. Ferocitas the Dream Eater, den fördärvade mystikern bland Gnarlpine-furbolgerna, tog den för att bära den som ett glänsande halsband. Han lockades av dess magiska sken utan att förstå att dess drömbundna kraft är helt värdelös i hans händer.",al={"varför vill någon ha tallonkai's jewel","varför vill tallonkai ha juvelen","varför stjäla tallonkai's jewel"}}},fp="17,157,13.586.0,26.159.0,28.119.0,49.113.0,46.135.0"}
P.entries["item:talon-of-tethis"] = {n="Talon of Tethis",s="Tethis klo är ett bevis på en jakt i Stranglethorn Vale. Hemet Nesingwary ber dig ta med den tillbaka efter att du besegrat den svårfångade raptorn.",h="Tethis klo är ett bevis på en jakt i Stranglethorn Vale.",kw={"gurubashi arena","hemet nesingwary","raptor","mästerskap som raptorjägare","stranglethorn","tethis klo","tethis"},ang={["class:Hunter"]="Som jägare sätts din skicklighet på prov när Hemet utmanar dig att möta Tethis, en raptor som han inte har lyckats döda."},sec={{t="En jägares bevis",b="Hemet Nesingwary säger att Tethis är en raptor som få jägare kan skryta med att ha dödat. Ta med klon till honom, så kallar han dig en mästerlig raptorjägare."}},faq={{q="Vad är Tethis klo?",a="Tethis klo är ett bevis på att du besegrade raptorn Tethis åt Hemet Nesingwary.",al={"tethis klo","klo föremål","vad används klon till"}},{q="Vem vill ha Tethis klo?",a="Hemet Nesingwary vill ha Tethis klo som bevis på jakten.",al={"vem vill ha klon","hemet klo","vart ska jag ta tethis klo"}},{q="Var kan jag hitta Tethis?",a="Tethis strövar omkring vid Gurubashi Arena, främst norr om den.",al={"var finns tethis","tethis plats","hitta raptorn"}},{q="Varför vill Hemet ha klon?",a="Hemet ber om klon som bevis på att du dödade Tethis, en raptor som han själv inte har lyckats fälla.",al={"varför klon","varför jaga tethis","vad vill hemet ha"}}},fp="15,140,18.140.0,28.86.0,25.59.0,24.63.0,30.103.0"}
P.entries["item:taming-rod"] = {n="Taming Rod",s="I Durotar hjälper Taming Rods nybörjarjägare att lära sig styra bestar. Tränare ger dem till elever så att de kan öva innan de knyter varaktiga band till djurkamrater.",h="I Durotar hjälper Taming Rods nybörjarjägare att lära sig styra bestar.",kw={"bepansrad skorpion","vildsvin med mörka fläckar","jägarens husdjur","razor hill","taming rod","taming the beast","thotar"},ang={["class:Hunter"]="Som jägare använder du Taming Rod för att öva innan du kan knyta varaktiga band till vildbestar.",["faction:Horde"]="I Durotar och Mulgore använder tränare som Thotar Taming Rods för att pröva om unga rekryter har disciplin nog att bemästra Kalimdors hårda vildmark."},sec={{t="En vägledares träningsredskap",b="I Razor Hill ger tränare som Thotar Taming Rods till blivande jägarna bland orcher och troll. De förtrollade verktygen hjälper nybörjare som ännu inte kan binda en vild varelse för gott. En stav lugnar ett rovdjur från trakten, som ett dire mottled boar eller en armored scorpid, så att jägaren kan öva på att ge order och slåss tillsammans med en djurkamrat. Bandet varar bara en kort stund, så eleven kan lära sig utan att knyta ett varaktigt band till besten."},{t="Ett steg mot mästerskap",b="Magin i varje Taming Rod försvinner efter en kort stund, och varje stav är anpassad för särskilda sorters vildbestar. Nybörjare ställs inför flera prov mot bestar med olika temperament, från fogliga födosökare till aggressiva giftiga jägare. När en elev har visat att hen kan styra dem går staven tillbaka till tränaren. Tränaren lär sedan eleven att tämja, kalla på och avvisa livslånga följeslagare utan en artefakt."}},faq={{q="Vad används en Taming Rod till?",a="Jägare använder en Taming Rod för att öva på att styra en best i strid. Tränaren ger den till en ung jägare, och dess magi lugnar och förtrollar varelsen en kort stund.",al={"vad gör en taming rod","använda taming rod","varför har jag en taming rod"}},{q="Behåller jag husdjuret jag tämjer med staven?",a="Nej. En best som påverkas av en Taming Rod är där endast för träning, och bandet upphör när magin klingar av eller du lämnar tillbaka staven. Efter dina prov lär du dig att tämja en varaktig följeslagare.",al={"är husdjuret permanent","behåller jag vildsvinet","behåller jag skorpionen"}},{q="Kan jag använda vilken Taming Rod som helst på vilket djur som helst?",a="Nej. Varje Taming Rod är anpassad för en viss målvarelse i sitt träningsskede, som ett dire mottled boar eller en armored scorpid.",al={"fungerar staven på alla djur","mål för taming rod"}},{q="Får jag behålla Taming Rod efter träningen?",a="Nej. Du lämnar tillbaka Taming Rod till din jägartränare efter ditt uppdrag. Efter ditt sista prov lär tränaren dig att tämja, kalla på och avvisa bestar på egen hand.",al={"behålla taming rod","kan jag spara staven"}}},fx={c3dba9d3={q="Vad är Taming Rod?",a="Taming Rod är ett träningsredskap som tränare ger åt nybörjarjägare. Den är förtrollad så att den tillfälligt kan böja en vild varelses vilja efter din, och fungerar som ett hjälpmedel under träningen. Med den får en blivande jägare uppleva den fina balans som krävs för att styra vilda djur i strid, utan att knyta ett permanent band innan grundkunskaperna är helt inlärda.",al={"vad är taming rod","föremålet taming rod","taming rods bakgrund"}},da578f9f={q="Varför vill en jägare ha Taming Rod?",a="Nybörjarjägare behöver spöet för att visa att deras förmåga att styra naturen växer. När du lyckas kuva farliga bestar som vildsvin eller skorpider visar du den beslutsamhet och självbehärskning som krävs för att kontrollera ett vilt sinne. När du har visat din tränare att du kan styra dessa varelser i strid får du lära dig konsten att knyta ett varaktigt band till bestar.",al={"varför behöver man taming rod","taming rods syfte","varför använda taming rod"}}},fp="10,164,28.377.0,21.391.0,30.160.0,38.189.0,39.141.0,56.172.0"}
P.entries["item:tapped-dowsing-widget"] = {n="Tapped Dowsing Widget",s="En Tapped Dowsing Widget innehåller ett vattenprov från en pöl nära Sandsorrow Watch i Tanaris. Gadgetzan Water Company behöver sådana undersökningar när öknens brunnar sinar.",h="En Tapped Dowsing Widget innehåller ett vattenprov från en pöl nära Sandsorrow Watch i Tanaris.",kw={"fizzledowser","gadgetzan","sandsorrow watch","tanaris","tapped dowsing widget","untapped dowsing widget","vattenprov","vattenundersökning"},sec={{t="Ett ökenprov",b="Senior Surveyor Fizzledowser skickar dig från Gadgetzan för att undersöka pölen nära Sandsorrow Watch. Widgeten tar ett prov åt Gadgetzan Water Company, som söker efter fria vattenkällor när nomader tar över dess brunnar. Men pölen ligger inom synhåll från trollen, och undersökningen innebär ännu en fara från öknen."}},faq={{q="Vad är Tapped Dowsing Widget?",a="Det är en Untapped Dowsing Widget som har samlat in ett vattenprov från pölen nära Sandsorrow Watch i Tanaris.",al={"tapped widget","vattenprov från en pryl","spårningspryl"}},{q="Var använder jag dowsing-widgeten?",a="Använd Untapped Dowsing Widget vid pölen nära Sandsorrow Watch, väster om Gadgetzan och söder om Zul'Farrak.",al={"var använda widgeten","pölens plats","vatten vid sandsorrow"}},{q="Vem vill ha vattenprovet?",a="Senior Surveyor Fizzledowser i Gadgetzan ber dig lämna tillbaka Tapped Dowsing Widget till honom åt Gadgetzan Water Company.",al={"vem behöver provet","fizzledowser","gadgetzan water company"}},{q="Varför undersöker företaget vatten?",a="Gadgetzan Water Company söker fria vattenkällor eftersom nomader tar över dess brunnar.",al={"varför undersöka vatten","inga brunnar","vattenbrist"}},{q="Vilken fara finns nära pölen?",a="Rapporter berättar om märkliga insektvarelser som suger vatten ur öknen. De som undersöker området kan också vara inom synhåll från trollen vid pölen.",al={"fara vid pölen","insekter vid sandsorrow","läskiga kryp"}}},fp="21,172,15.314.0,34.114.0,34.109.0,27.130.0,35.90.0,29.131.1"}
P.entries["item:taragaman-the-hungerer-s-heart"] = {n="Taragaman the Hungerer's Heart",s="Under Orgrimmar söker Neeru Fireblade efter Taragaman the Hungerer's Heart som bevis på att den demoniska närvaron har utplånats. Den makabra trofén kommer från demonvakten som härskar i djupet av Ragefire Chasm.",h="Under Orgrimmar söker Neeru Fireblade efter Taragaman the Hungerer's Heart som bevis på att den demoniska...",kw={"felguard","hjärta","hungerer","neeru fireblade","orgrimmar","ragefire chasm","searing blade","taragaman"},ang={["class:Warlock"]="Som häxmästare känner du till den känsliga väven av skuggor och svek som råder i Cleft of Shadow. Att göra upp med Neeru Fireblade och ta hand om demoniska kvarlevor är välbekanta saker.",["faction:Horde"]="Som medlem av Horde hjälper du till att skydda Orgrimmar från inre fördärv. Odjurets avhuggna hjärta vittnar om Hordes vaksamhet."},sec={{t="En trofé av svek",b="Taragaman the Hungerer's ångande hjärta bevisar att demonvakten har fallit. Neeru Fireblade berättar för Thrall och ivriga äventyrare att Taragaman leder Searing Blade-kultisterna i Ragefire Chasm. Att lämna hjärtat till Neeru verkar uppfylla krigshövdingens order att skydda Orgrimmar mot demonisk förvrängning. Att skylla på en brutal demonvakt för att ha lett kulten håller också de dödligas nätverk under staden utom synhåll."}},faq={{q="Vem vill ha Taragaman the Hungerer's Heart?",a="Neeru Fireblade, en orcisk häxmästare i Orgrimmars Cleft of Shadow, ber dig hämta hjärtat som bevis på att demonen har dödats.",al={"vem tar taragamans hjärta","lämna in taragamans hjärta","vem vill ha hjärtat"}},{q="Var får jag tag på hjärtat?",a="Du tar hjärtat från Taragaman the Hungerer's lik i de centrala magmakamrarna i Ragefire Chasm under Orgrimmar. Den respektingivande demonvakten håller till där.",al={"hur får man tag på taragamans hjärta","var får man taragamans hjärta","taragamans hjärta plats"}},{q="Får Thrall någonsin se hjärtat?",a="Nej. Du tar hjärtat direkt till Neeru Fireblade. Han säger att han ska ta hand om de demoniska kvarlevorna och berätta för krigshövding Thrall om segern åt dig.",al={"får thrall hjärtat","ge hjärtat till thrall","thrall taragamans hjärta"}},{q="Var Taragaman verkligen ledare för Searing Blade?",a="Neeru Fireblade pekar ut Taragaman the Hungerer som ledare för Searing Blade och säger att det kommer att blidka Thrall om du dödar honom och tar tillbaka hans hjärta.",al={"är taragaman ledaren","vem leder searing blade","taragaman verklig boss"}}},fx={a71e3ad9={q="Vad är Taragaman the Hungerer's Heart?",a="Det är det utskurna hjärtat från Taragaman the Hungerer, en väldig felguard som lurar i de brinnande djupen av Ragefire Chasm under Orgrimmar. Äventyrare har burit ut det ur grottorna. Det är ett fysiskt bevis på att demonen som Neeru Fireblade kallar Searing Blades ledare har fällts.",al={"vad är taragaman the hungerer's heart","taragaman the hungerer's heart","taragaman the hungerer's heart bakgrund"}},d8388abb={q="Varifrån kommer Taragaman the Hungerer's Heart?",a="Hjärtat har skurits ut ur bröstet på Taragaman the Hungerer, en enorm felguard som håller till djupt inne i Ragefire Chasm. Kultisterna från Searing Blade åkallade Taragaman och höll honom i tunnlarna under Orgrimmar. Hjärtat är en kvarleva från den demoniska korruption som infekterar stadens underjord.",al={"taragaman the hungerer's heart ursprung","varifrån kom hjärtat","vem tillverkade taragaman the hungerer's heart"}}},fp="30,182,18.408.1,41.130.0,29.153.0,31.144.0,52.144.1"}
P.entries["item:tattered-manuscript"] = {n="Tattered Manuscript",s="Tattered Manuscript består av lösa, skändade sidor som rivits ur det enda exemplaret av Tome of the Cabal. Undangömd i södra Kalimdors dammiga djup rymmer denna slitna del av texten magiska hemligheter som är oumbärliga för häxmästare som vill bemästra feljägare.",h="Tattered Manuscript består av lösa, skändade sidor som rivits ur det enda exemplaret av Tome of the Cabal.",kw={"feljägare","jorah annison","krom stoutarm","moldy tome","splithoof hold","tattered manuscript","thousand needles","tome of the cabal"},ang={["class:Warlock"]="Att hämta manuskriptet är en viktig övergångsrit för blivande häxmästare och ger dem kunskapen som krävs för att kuva rovgiriga feljägare."},sec={{t="Ett skändat grimoar",b="Tome of the Cabal var en gång en hel och unik volym som förvarades i det fallna kungariket Lordaeron. Vid något tillfälle slet en okänd vandalisatör nästan halva skriften direkt ur dess bindning. Medan den bevarade ryggen och resten av boken, som nu kallas Moldy Tome, skeppades söderut mot Khaz Modan och försvann till havs, drev dessa sönderrivna pergamentblad långt över Stora havet till Kalimdor, där de till slut hamnade hos Galak-kentaurerna i Splithoof Hold."},{t="Återta orden",b="Manuskriptet förvarades i en sliten kista djupt inne i Splithoof Holds labyrintiska grottor och överlevde Thousand Needles hårda, torra vindar. Trots sitt sköra och sönderrivna skick vågar utövare av de mörka konsterna, både allianshäxmästare som arbetar med Krom Stoutarm i Ironforge och hordens utövare som hjälper Jorah Annison i Undercity, möta de aggressiva kentaurerna för att förena de förlorade bladen med Moldy Tome. När de sammanförts innehåller den fullständiga skriften de mörka ritualer som krävs för att åkalla och binda en demonisk feljägare."}},faq={{q="Vad är Tattered Manuscript?",a="Det är en samling sönderrivna pergamentblad som utgör ungefär halva Tome of the Cabal, ett legendariskt och unikt grimoar om demonologi.",al={"lore om tattered manuscript","vad är manuskriptet","sidor ur tome of the cabal"}},{q="Hur hamnade de här sidorna i Thousand Needles?",a="Efter att grimoaren skändats i Lordaeron korsade de bortrivna sidorna på något sätt havet och hamnade hos Galak-kentaurerna, som gömde dem i en kista i Splithoof Hold.",al={"varför i splithoof hold","kentaur och tome","manuskript i thousand needles"}},{q="Vad används manuskriptet till?",a="Häxmästare måste återförena Tattered Manuscript med den vattendränkta Moldy Tome för att återskapa hela Tome of the Cabal och låsa upp ritualen för att åkalla en feljägare.",al={"varför behöver jag manuskriptet","feljägaruppdragets sidor"}},{q="Vem slet sönder originalboken?",a="Den skyldige är fortfarande okänd. Både Krom Stoutarm i Ironforge och Jorah Annison i Undercity beklagar skändningen och kan inte förstå vem som skulle begå en sådan handling mot ett unikt lärdomsverk.",al={"vem slet sönder tome","vem skändade tome of the cabal"}}},fp="19,178,21.399.0,20.415.0,32.126.0,47.167.0,32.166.0,56.168.0"}
P.entries["item:tazan-s-satchel"] = {n="Tazan's Satchel",s="Nära Ratchet bär Tazan på en låst väska medan han gör upp med pirater längs kusten. The Shattered Hand vill åt den hemliga informationen därinne.",h="Nära Ratchet bär Tazan på en låst väska medan han gör upp med pirater längs kusten.",kw={"the barrens","cleft of shadow","gamon","ratchet","shattered hand","tazan","tazan's satchel","therzok"},ang={["class:Rogue"]="Som rogue i Horde måste du hämta väskan och ta nyckeln från Gamon för att förtjäna din plats i The Shattered Hand.",["faction:Horde"]="I Orgrimmar söker The Shattered Hand fördelar i det fördolda medan hövding Thrall följer en mer återhållsam kurs."},sec={{t="The Barrens hemligheter",b="Tazan gör upp med pirater som slagit läger längs The Barrens kust nära Ratchet. Therzok, en skråmästare i The Shattered Hand under Orgrimmar i The Cleft of Shadow, får upp ögonen för honom. Skrået söker dold makt bortom hövding Thralls försiktiga diplomati och märker ut Tazan för döden för att lägga beslag på uppgifterna i hans väska."},{t="Ett invecklat lås",b="Väskans lås gör den svår att öppna ute i fält. Tazan gav nyckeln till Gamon, sin kompanjon, som är ett fyllo och ett välbekant inslag på en krog i Orgrimmar. Rogues som är ute efter väskan måste ta nyckeln ur Gamons ficka utan att väcka uppmärksamhet. Sedan kan de läsa Tazans loggbok."}},faq={{q="Vem tillhör den här väskan?",a="Väskan tillhör Tazan, en troll som gör upp med pirater nära Ratchet i The Barrens.",al={"vem är tazan","tazans ägare","väskans ägare"}},{q="Varför vill Shattered Hand ha Tazan's Satchel?",a="Therzok och The Shattered Hand vill åt uppgifterna om Tazans affärer med kustpirater för att utöka sitt nätverk och återta sin krigiska stolthet i skuggorna.",al={"varför vill therzok ha den","shattered hands väska","varför stjäla väskan"}},{q="Var finns nyckeln som öppnar väskan?",a="Tazan lämnade nyckeln hos sin kompanjon Gamon, en berusad gäst på en krog i Orgrimmar.",al={"hur öppnar man väskan","tazans nyckel","var finns nyckeln"}},{q="Vad finns i Tazan's Satchel?",a="Tazans loggbok ligger i den låsta väskan och beskriver hans hemliga affärer och band till kustens sjörövare.",al={"väskans innehåll","vad finns i påsen","tazans loggbok"}}},fp="15,130,22.331.0,14.260.1,32.87.0,49.170.0,37.85.1,31.108.1"}
P.entries["item:tear-of-the-moons"] = {n="Tear of the Moons",s="Vid Bael Modan i södra Barrens har dvärgiska utgrävare grävt fram Tear of the Moons. Dess märkliga kraft driver Feegly in i besatthet, medan General Twinbraid fruktar vad kristallen kan göra.",h="Vid Bael Modan i södra Barrens har dvärgiska utgrävare grävt fram Tear of the Moons.",kw={"bael modan","bael'dun keep","the barrens","utgrävning","feegly","tear of the moons","trogg","twinbraid"},ang={["faction:Horde"]="Som medlem av horden hjälper du till att återta reliken från Bael'dun Keep och stör därmed Ironforges militära närvaro, som tränger in på taurenfolkets förfäders marker.",["race:Dwarf"]="Som dvärg varnar Feeglys öde för faran med vad expeditionen vid Bael'dun riskerar att väcka under Kalimdor."},sec={{t="En uppgrävd relik",b="Dvärgiska utgrävare grävde fram Tear of the Moons under den första utgrävningen vid Bael Modan. Kristallens märkliga sken fängslade gruvarbetarna, särskilt Feegly. Han hävdade att den gav honom stor styrka, men blev sedan instabil och vände sig mot sina kamrater. General Twinbraid, expeditionens befälhavare, fruktade relikens inflytande och förklarade den förbannad. Han tog kristallen och låste in den i sin personliga kassaskrin på Bael'dun Keep. Sedan förvisade han Feegly till Barrens."},{t="Besatthetens pris",b="Den förvisade Feegly kan inte tygla sitt begär efter kristallens kraft. Han ber förbipasserande resenärer ur horden att hjälpa honom bryta sig in i dvärgarnas fästning och ta kristallen ur Twinbraids valv. När Feegly får tag på Tear och gnider den undslipper märkliga grymtningar honom. Kristallen faller ur hans händer och krossas mot marken. Feegly förvandlas till en trogg och dör kort därefter."}},faq={{q="Varifrån kom Tear of the Moons?",a="Dwarven Prospectors och utgrävare grävde fram Tear of the Moons vid Bael Modan, en arkeologisk utgrävningsplats i södra Barrens.",al={"tears ursprung","var hittades tear","bakgrund om tear of the moons"}},{q="Varför låstes kristallen in i Bael'dun Keep?",a="General Twinbraid fruktade att kristallen var förbannad efter att Feegly blivit besatt av den och vänt sig mot sina medgruvarbetare. Han låste in den i sitt kassaskrin på Bael'dun Keep för att skydda expeditionen.",al={"varför låstes den in","twinbraids kassaskrin och tear","varför tog twinbraid den"}},{q="Vad händer när Feegly får tillbaka Tear?",a="Feegly gnider kristallen, som faller ur hans händer och krossas. Han förvandlas till en trogg och dör kort därefter.",al={"feegly förvandlas till trogg","vad händer med feegly","feeglys troggförvandling"}},{q="Går det att rädda eller laga Tear of the Moons?",a="Tear krossas när Feegly får tillbaka den. Berättelsen säger inget om att någon lagar den efteråt.",al={"kan man behålla tear","krossad tear","laga tear of the moons"}}},fx={f703febe={q="Vad är Tear of the Moons?",a="Tear of the Moons är en mystisk, lysande kristall som dvärgiska utgrävare grävde fram under sin expedition i Bael Modan i södra Barrens. Den hyllades som platsens första stora upptäckt, men artefakten visade sig vara mycket instabil. Den utstrålade en fördärvande kraft som förvrängde sinnet hos dvärgen som höll i den och fick expeditionens ledning att låsa in den.",al={"tear of the moons","vad är tear of the moons","vad är tåren"}}},fp="17,170,17.458.0,22.354.1,42.133.0,48.194.0,44.115.1,47.103.1"}
P.entries["item:tear-of-tilloa"] = {n="Tear of Tilloa",s="I Duskwood växer Tear of Tilloa på godset Mistmantle nära Darkshire. Dess användning inom alkemi väcker intresse hos dem som söker sällsynta reagenser.",h="I Duskwood växer Tear of Tilloa på godset Mistmantle nära Darkshire.",kw={"en brygd åt adeln","darkshire","mistmantle","stalvan","tear of tilloa","tilloa","wishock","zardeth"},ang={["class:Warlock"]="Som häxmästare kanske du känner till Tear of Tilloa som en reagens som ockulta agenter under huvudstaden söker efter till brygder avsedda att tysta nyfikna adelsmän.",["profession:Herbalism"]="Som örtmästare kan du hitta Tear of Tilloa växande i Duskwoods sargade jord, långt från de vanliga frodiga fälten."},sec={{t="En trädgård i dunklet",b="Tear of Tilloa växer på ägorna kring Stalvan Mistmantles gods utanför Darkshire. Duskwoods jord har blivit ogästvänlig för frisk växtlighet, men den lilla vita blomman håller sig kvar bland de skuggiga odlingslotterna. Den växer sällan och på en undangömd plats, vilket lockar dem som söker ovanliga reagenser utanför lagliga marknader."},{t="En brygd åt adeln",b="Under Stormwinds gator söker Zardeth of the Black Claw Tear of Tilloa för att brygga en dryck åt Lord Wishock. Wishock är medlem av House of Nobles och hotar att undersöka skumma verksamheter under huvudstaden. Zardeth blandar blomman med Musquash Root från området under Stonewrought Dam för att skapa en brygd som ska distrahera och oskadliggöra Wishock innan en officiell undersökning kan inledas."}},faq={{q="Var växer Tear of Tilloa?",a="Blomman växer i utkanten av Darkshire i Duskwood, i den igenvuxna trädgården på familjen Mistmantles gods.",al={"tear of tilloa plats","var finns tear of tilloa","tilloa plats"}},{q="Vem vill ha Tear of Tilloa?",a="Zardeth of the Black Claw söker blomman medan han verkar i hemlighet under Stormwind City, där han behöver den till en särskild dryck.",al={"vem behöver tear of tilloa","uppdragsgivare för tear of tilloa","vem vill ha den"}},{q="Vad används blomman till?",a="Blomman blandas med Musquash Root för att skapa en brygd som ska oskadliggöra Lord Wishock och tysta hans krav på en undersökning av mörka förehavanden under huvudstaden.",al={"tear of tilloa användning","vad gör tear of tilloa","blomma till adelsbrygd"}},{q="Vem är Lord Wishock?",a="Lord Wishock är en adelsman i Stormwinds House of Nobles. När han fick höra talas om omstörtande verksamhet under staden började han uppmana rådet att undersöka saken.",al={"wishock","vem är wishock","lord wishock"}}},fx={e7b72a0d={q="Vad är Tear of Tilloa?",a="Tear of Tilloa är en skir, sällsynt vit blomma som blommar i Duskwood. Den växer särskilt i den vanskötta Garden of Stalvan i utkanten av Darkshire. Denna stillsamma växt har kraftfulla egenskaper som eftertraktas av utövare av mörk magi långt borta i tunnlarna under Stormwind.",al={"vad är tear of tilloa","tear of tilloa-blomma","tear of tilloa"}},d8c5f010={q="Var kommer Tear of Tilloa ifrån?",a="Blomman växer naturligt i den igenvuxna Garden of Stalvan, strax utanför Darkshires skydd i Duskwoods skuggiga skog. Ingen dödlig hantverkare skapade den. Den blommar helt enkelt ostört på ägorna till det forna hemmet för familjen Mistmantle, där tragedin en gång slog till.",al={"var kommer tear of tilloa ifrån","vem skapade tear of tilloa","tear of tilloas ursprung"}}},fp="14,135,21.284.0,27.398.1,35.115.0,29.124.0,28.155.1,20.162.0"}
P.entries["item:techbot-s-memory-core"] = {n="Techbot's Memory Core",s="Techbot's Memory Core är det polariserade centrala lagret i Tinkmaster Oversparks mekaniska assistent Techbot. Den återfanns i den felande automaten, djupt inne i det fördärvade Gnomeregan, och innehåller viktiga data som Overspark hoppas kunna använda för att häva maskinens omvända negatroniska beteende.",h="Techbot's Memory Core är det polariserade centrala lagret i Tinkmaster Oversparks mekaniska assistent Techbot.",kw={"hjärna","gnomeregan","minneskärna","negatronisk","overspark","positronisk","techbot","tinker town"},ang={["profession:Engineering"]="Ingenjörer kan uppskatta de märkliga riskerna med positronisk polarisering, där en enda elektrisk kortslutning kan vända en automats logikrutiner helt.",["race:Gnome"]="För gnomerna är Techbot ännu ett tragiskt offer för Gnomeregans fall och en symbol för hur lysande ingenjörskonst från fredstid gått förlorad i kaos och ruiner."},sec={{t="En polariserad hjärna",b="Innan katastrofen tvingade gnomerna i exil tjänade Techbot Tinkmaster Overspark och hans uppfinnarkollegor som en oumbärlig assistent, fullpackad med manicker och encyklopediska kunskaper. När Gnomeregan föll träffades automaten av en elektrisk urladdning, som vände dess positroniska hjärna till ett fientligt negatroniskt tillstånd. Galen av omkastningen vandrar Techbot nu genom stadens förgiftade salar och anfaller alla som kommer i sikte. Att återfå minneskärnan är Oversparks enda hopp om att analysera felet och återställa hans älskade skapelse till sina sinnens fulla bruk."}},faq={{q="Vad är Techbot's Memory Core?",a="Det är Techbots främsta datalager och beräkningscentral. Techbot är en automat byggd av Tinkmaster Overspark. Kärnan innehåller maskinens kunskap och registrerar den elektriska störning som förvred dess beteende när Gnomeregan föll.",al={"techbots minneskärna","techbots hjärnpryl","vad är techbots kärna"}},{q="Vem vill ha Techbot's Memory Core?",a="Tinkmaster Overspark söker efter kärnan. Han har tagit sin tillflykt till Tinker Town i Ironforge tillsammans med andra gnomer i exil. Där ber han modiga äventyrare att bege sig till Gnomeregan, oskadliggöra Techbot och ta med kärnan tillbaka så att han kan försöka reparera den.",al={"vem behöver techbots minneskärna","vem lämnar in techbots kärna","var lämnar jag techbots kärna"}},{q="Varför blev Techbot våldsam?",a="När Gnomeregan föll träffades Techbots positroniska hjärna av en elektrisk gnista. Den plötsliga strömstöten polariserade mekanismen och gjorde den negatronisk. Automatens personlighet och protokoll vändes helt från hjälpsamma till våldsamt ursinniga.",al={"varför är techbot fientlig","vad hände med techbot","techbot har blivit galen"}},{q="Var får man tag på kärnan?",a="Kärnan tas från Techbot själv, som strövar omkring i de övre mekaniska korridorerna och entréerna till den fallna staden Gnomeregan i Dun Morogh.",al={"var får man techbots minneskärna","techbots plats","hur får man tag på techbots hjärna"}}},fx={a503508b={q="Var kommer Techbot's Memory Core ifrån, och vem skapade den?",a="Minneskärnan kommer från Techbot, en avancerad mekanisk konstruktion som Tinkmaster Overspark byggde i Gnomeregan. Overspark utformade maskinen för att hjälpa honom och hans uppfinnarkollegor med ett outsinligt förråd av data och mojänger. När Gnomeregan föll för troggarna träffades Techbot dock av en okontrollerad elektrisk stöt. Den polariserade dess positroniska hjärna till ett negatroniskt tillstånd och drev maskinen till vansinne.",al={"vem skapade techbot's memory core","techbots ursprung","vem byggde techbot"}}},fp="21,108,17.433.0,30.204.0,32.231.0,27.207.0,27.116.0"}
P.entries["item:telescopic-lens"] = {n="Telescopic Lens",s="Gazlowe behöver Telescopic Lens för att färdigställa observatorieteleskopet ovanför Ratchets hamn. Southsea-pirater tog den från ett skepp, och linsen finns kvar i deras läger söder om staden.",h="Gazlowe behöver Telescopic Lens för att färdigställa observatorieteleskopet ovanför Ratchets hamn.",kw={"låda","gazlowe","observatorium","ratchet","southsea freebooters","stulet byte","telescopic lens"},ang={["profession:Engineering"]="Som ingenjör kan du se det fina optiska hantverket i den här linsen. Den behövs för att fokusera observationsmekanismer på långt håll utan sfärisk aberration.",["race:Gnome"]="Som gnom kanske du hånler åt goblinernas raketteknik, men Gazlowes hängivenhet åt optisk astronomi visar att gobliningenjörskonst inte bara handlar om sprängämnen."},sec={{t="Blick mot himlen",b="Ratchet är främst känt för hänsynslös handel, men dess förvaltare och chefsingenjör, Gazlowe, har större mekaniska ambitioner. Hans observatorium reser sig ovanför hamnen och rymmer ett teleskop för att hålla uppsikt över sjötrafiken och stjärnorna. Den större linsen kom säkert landvägen från Durotar. Den mindre, oumbärliga linsen färdades till sjöss, där Southsea Freebooters jagar handelsskepp utanför The Barrens kust."},{t="Piratbyte",b="Southsea Freebooters tog allt av värde när de plundrade transportfartyget, inklusive den ömtåliga optiken. Piraterna kan ha lämnat linsen bland bråten i sitt strandläger söder om Ratchet eftersom de inte kunde uppskatta dess hantverk eller inte visste hur de skulle sälja den vidare. Gazlowe behöver få tillbaka det felfria glaset så att observationsdäcket kan ställas in i fokus."}},faq={{q="Varför behöver Gazlowe linsen?",a="Gazlowe behöver Telescopic Lens för att färdigställa teleskopet i Ratchets observatorium. Den större linsen kom landvägen från Durotar, men den mindre linsen gick förlorad till havs.",al={"gazlowes lins","vad linsen används till","varför teleskoplins"}},{q="Vem stal Telescopic Lens?",a="Southsea Freebooters stal Telescopic Lens. De är opportunistiska pirater, både människor och gastar, som jagar handelsskepp nära The Merchant Coast, och de förvarar linsen i en märkt låda i sitt kustläger söder om Ratchet.",al={"vem tog linsen","vem har linsen","telescopic lens plats"}},{q="Var kom linsen ursprungligen ifrån?",a="Telescopic Lens skeppades till Ratchet, medan dess motsvarighet kom landvägen från Durotar. Leveranser till hamnen kommer ofta från andra sidan Great Sea eller från sydliga goblinbosättningar som Booty Bay.",al={"var linsen tillverkades","linsens ursprung","var gazlowe beställde linsen"}},{q="Är linsen oskadd trots att den stals?",a="Mirakulöst nog klarade sig linsen oskadd. En låda märkt ”Ömtåligt – tappa inte” skyddade precisionsglaset från piraternas hårdhänta hantering.",al={"är linsen trasig","låda märkt ömtåligt tappa inte"}}},fx={ddcd39c0={q="Vad är Telescopic Lens?",a="Det är en precisionsslipad optisk lins avsedd för ett observatorieteleskop. Gazlowe beställde två speciallinser till teleskopet på toppen av sitt torn i Ratchet. Denna mindre sekundära lins skeppades över havet innan Southsea Freebooters lade beslag på den.",al={"vad är telescopic lens","föremålet telescopic lens","vad är den här linsen"}}},fp="15,186,15.371.0,14.346.0,32.171.0,30.203.0,40.213.0,43.136.0"}
P.entries["item:teronis-journal"] = {n="Teronis' Journal",s="Teronis' Journal är en fältanteckningsbok som återfanns bland kvarlevorna efter en Night Elf-spejare i Ashenvale. Den hittades intill den dödade utredaren och dokumenterar hans sökande efter en mystisk ädelsten. Den utgör viktig bevisning för Sentinels i Astranaar.",h="Teronis' Journal är en fältanteckningsbok som återfanns bland kvarlevorna efter en Night Elf-spejare i...",kw={"ashenvale","astranaar","glowing gem","raene wolfrunner","raenes rening","sentinels","teronis","teronis' journal"},ang={["faction:Alliance"]="Om du tar med Teronis' fältanteckningar tillbaka till Astranaar kan garnisonen samordna hjälp och återfinna sin fallne spejares kvarlevor.",["race:NightElf"]="Dagboken vittnar om de farofyllda uppgifter som Night Elf-spejare tar på sig när de försöker skydda Ashenvales urgamla skogar från en annalkande korruption."},sec={{t="En spejares sista anteckningar",b="Teronis, en gammal vän till Raene Wolfrunner som hjälpte Sentinels, gav sig ut i Ashenvales vildmark för att söka efter en ädelsten till en stav. Han trodde att staven kunde hejda furbolgarnas attacker mot hans folk. Uppdraget fick ett abrupt slut när han föll i fält, omringad av aggressiva varelser nära stranden. Dagboken återfanns bland hans personliga tillhörigheter och är i förvånansvärt gott skick trots hans våldsamma död. Den redogör för hans fynd om en strålande ädelsten som en gång var en del av staven. Astranaars försvarare får därmed det viktiga spår de behöver för att slutföra hans oavslutade uppdrag."}},faq={{q="Vem tillhörde dagboken?",a="Dagboken tillhörde Teronis, en Night Elf och vän till Raene Wolfrunner i Astranaar. Han sökte i Ashenvale efter ett sätt att hejda furbolgarnas attacker. Han dödades i vildmarken innan han hann återvända med sina fynd.",al={"vem skrev dagboken","vem är teronis","teronis bakgrund"}},{q="Var hittar man dagboken?",a="Dagboken får du genom att leta igenom Teronis' tillhörigheter efter att ha hittat hans döda kropp i Ashenvales vildmark, nära stränderna där traktens murlocs håller till.",al={"var hittar man dagboken","teronis dagboks plats","hur får man tag på dagboken"}},{q="Varför ska man ta med dagboken till Astranaar?",a="När du återlämnar dagboken till Raene Wolfrunner får Astranaar veta att Teronis har dött. Sentinels får också anteckningarna de behöver för att fortsätta hans sökande efter staven som han hoppades skulle hejda furbolgarnas attacker.",al={"varför lämna dagboken till raene","vem ska jag ge dagboken till","lämna in dagboken"}},{q="Vilket föremål letade Teronis efter under sitt uppdrag?",a="Teronis sökte efter en glödande ädelsten, en av delarna till en stav som den döde magikern Dartol hade tillverkat. Hans undersökning tydde på att murlocs i närheten kan ha rotat åt sig föremålet.",al={"vad jagade teronis","vilken ädelsten sökte han efter","teronis ädelsten"}}},fx={["5fb93f8f"]={q="Vad är Teronis' Journal?",a="Teronis' Journal är en personlig anteckningsbok som tillhörde nattalvsspejaren Teronis. Den hittades bland hans tillhörigheter intill hans kropp i Ashenvale. Den beskriver hans uppdrag och de första spaningsinsatserna kring en märklig ädelsten som han skickades för att hitta innan han mötte sin för tidiga död.",al={"vad är teronis' journal","föremålet teronis' journal","om teronis' journal"}}},fp="16,115,22.463.0,31.224.0,27.158.0,57.192.0,59.156.0"}
P.entries["item:tharil-zun-s-head"] = {n="Tharil'zun's Head",s="Den här makabra trofén är det avhuggna huvudet från Tharil'zun, ledaren för Blackrock-orchernas Outrunners som ockuperar Stonewatch. Marshal Marris kräver det som obestridligt bevis på att befälhavaren som terroriserat Redridges tillfartsvägar har dödats.",h="Den här makabra trofén är det avhuggna huvudet från Tharil'zun, ledaren för Blackrock-orchernas Outrunners...",kw={"blackrock outrunners","lakeshire","marshal marris","stonewatch","stonewatch keep","tharil'zun","tharil'zun's head"},ang={["faction:Alliance"]="Varje dödad Blackrock-hövding lättar trycket på den hårt ansatta staden Lakeshire, som kämpar för sin överlevnad utan officiella förstärkningar från Stormwind."},sec={{t="Stonewatchs trofé",b="Blackrock-orcherna som slagit sig ner i Stonewatch Keep har utsatt Lakeshire för skoningslöst tryck genom att plundra gårdar och överfalla resande längs vägarna. I spetsen för dessa plundringståg stod Blackrock Outrunners, som leddes av Tharil'zun. Eftersom garnisonen i Lakeshire inte har råd att agera på rykten eller halva segrar kräver Marshal Marris konkreta bevis på ledarens död. Att föra honom Tharil'zuns avhuggna huvud visar att de samordnade bakhållen från borgen har fått ett hårt slag."}},faq={{q="Vem var Tharil'zun?",a="Tharil'zun var en slug och våldsam Blackrock-orkbefälhavare stationerad i Stonewatch Keep. Han ledde Blackrock Outrunners, som genomförde ihärdiga bakhåll tillsammans med Renegades mellan Lakeshire och borgen.",al={"tharil'zuns bakgrund","vem är tharil'zun","tharil'zuns ledare"}},{q="Varför vill Marshal Marris ha hans huvud?",a="Eftersom Stormwind håller inne med större militär hjälp till Redridge förlitar sig Marshal Marris och Lakeshires vakter på legosoldater för att slå ut viktiga hot. Marris kräver obestridliga bevis på Tharil'zuns död för att försäkra sig om att Outrunners ledning verkligen är krossad.",al={"varför tharil'zuns huvud","marris bevis huvud","marris belöning"}},{q="Var finns Tharil'zun?",a="Tharil'zun håller Stonewatch Keep i de östra kullarna i Redridge Mountains, omgiven av Blackrock-orcher och gnoller.",al={"tharil'zuns plats","var finns tharil'zun","hitta tharil'zun"}},{q="Tar hotet från Blackrock slut när Tharil'zuns huvud tas?",a="Nej. Att döda Tharil'zun stör visserligen Outrunners bakhåll, men Blackrock-klanen har fortfarande en stor förskansad styrka i Stonewatch Keep och över hela Redridge Mountains.",al={"har orcherna försvunnit","räddade vi redridge","efter tharil'zun"}}},fx={a015b31b={q="Vad är Tharil'zun's Head?",a="Det här avhuggna huvudet är ett fysiskt bevis på att Tharil'zun, befälhavaren bakom svartklippiga orkers bakhåll kring Stonewatch Keep, har dödats. När det förs tillbaka till Lakeshire visar det stadens hårt ansatta vakter att en av svartklippaklanens farligaste fältledare i Redridge Mountains inte längre kommer att terrorisera vägarna.",al={"föremålet tharil'zun's head","historien om tharil'zuns huvud"}},f673cecf={q="Var kommer Tharil'zun's Head ifrån?",a="Det tas direkt från liket efter Tharil'zun, en framstående svartklippig orkledare som utgår från ruinerna av Stonewatch Keep. När han stupar i strid mot dig eller Lakeshires försvarare tas huvudet som ett obestridligt trofé och ett bistert bevis på hans död.",al={"vem tog tharil'zun's head","tharil'zuns huvuds ursprung","varifrån kom tharil'zuns huvud"}}},fp="17,139,20.381.0,19.185.0,38.234.0,26.121.0,55.167.0"}
P.entries["item:tharnariun-s-hope"] = {n="Tharnariun's Hope",s="Tharnariun's Hope är en specialfälla som nattalven Tharnariun Treetender tillverkat i Darkshore. Den är utformad för att lugna sjuka vilda djur i stället för att skada dem och sprider ett rogivande ljus som ska tämja rabiata tisteltaggarbjörnar, så att de kan undersökas i jakten på ett botemedel.",h="Tharnariun's Hope är en specialfälla som nattalven Tharnariun Treetender tillverkat i Darkshore.",kw={"darkshore","plågade länder","rabiat tisteltaggarbjörn","tharnariun","tharnariun's hope","tisteltaggarbjörn","fälla"},ang={["class:Druid"]="Fällan förkroppsligar Cenarion-idealet att bevara i stället för att utrota. Den visar en ovilja att slå ner korrumperade bestar så länge det finns en chans att rädda dem.",["race:NightElf"]="Förfallet hos Darkshores älskade tisteltaggarbjörnar slår mot kärnan i kaldoreiernas band till naturen och gör fällan till en gripande symbol för desperat medkänsla."},sec={{t="En mild snara",b="En mystisk åkomma sprider sig genom Darkshore, och områdets tisteltaggarbjörnar har blivit alltmer ursinniga och våldsamma. I stället för att beordra att de sjuka djuren ska avlivas tillverkade druiden Tharnariun Treetender den här unika fällan i hopp om att kunna studera och bota sjukdomen. När den läggs på marken avger Tharnariun's Hope ett lugnande sken. En rabiat tisteltaggarbjörn som kliver in i fällans ljus blir tillfälligt av med sitt raseri och så tam att en äventyrare kan leda den tillbaka till Tharnariuns läger för behandling."},{t="Det svårfunna botemedlet",b="Fällan lyckas kuva de ursinniga djuren utan att utgjuta blod, men den underliggande korruptionen visar sig vara mycket våldsammare än väntat. När Tharnariun kanaliserar sin läkande magi in i den fångade björnen kolliderar den återställande kraften våldsamt med den virulenta infektionen, så att det sjuka djuret faller ihop och dör. Trots att hans första försök slutar i hjärtesorg hävdar Tharnariun att hans beslutsamhet inte ska svikta förrän skogens sjukdom har avslöjats."}},faq={{q="Vad gör Tharnariun's Hope?",a="Det är en förtrollad markfälla som är utformad för att lugna en rabiat tisteltaggarbjörn. När den placeras på skogsmarken skapas ett ljusfält som tillfälligt lugnar en björn som går in i det, så att den lugnt kan ledas tillbaka till Tharnariun Treetender.",al={"använda tharnariun's hope","hur fungerar fällan","vad är det här för fälla"}},{q="Varför vill Tharnariun fånga en levande björn?",a="Tharnariun tror att sjukdomen som drabbat Darkshores vilda djur kan botas i stället för att bekämpas genom slakt. Han behöver ett levande försöksdjur för att pröva sina renande kurer direkt.",al={"varför fånga tisteltaggarbjörn","varför fånga en rabiat björn","vad vill tharnariun"}},{q="Kan du få en ny fälla om du tappar bort den?",a="Ja. Tharnariun försäkrar resenärer om att hans hopp är evigt. Om en fälla utlöses i onödan eller försvinner i vildmarken får du en ny av honom när du återvänder, så att du kan slutföra uppdraget.",al={"tappat bort tharnariun's hope","misslyckad fälla","fällan försvunnen"}},{q="Vad händer med björnen när den förs tillbaka?",a="När björnen anländer kastar Tharnariun en läkande förtrollning för att driva ut korruptionen. Den vidriga sjukdomen har tyvärr fått för djupt fäste. Magin överväldigar besten, som dör inom några ögonblick.",al={"överlever björnen","kan tharnariun bota björnen","björnen dör hos tharnariun"}}},fx={["820181a1"]={q="Vad är Tharnariun's Hope?",a="Tharnariun's Hope är en förtrollad snara som Tharnariun Treetender har utformat. När den läggs på marken utstrålar den ett lugnande sken som tillfälligt kan stilla de drabbade, rabiata tistlebjörnarna som strövar omkring i Darkshore. Den rogivande förtrollningen gör ett rasande odjur milt och villigt att följa med dig tillbaka till Auberdine.",al={"vad är tharnariun's hope","föremålet tharnariun's hope","tharnariuns fälla"}},["88ba9e19"]={q="Var kommer Tharnariun's Hope ifrån, och vem skapade den?",a="Fällan tillverkades och förtrollades av Tharnariun Treetender, en nattalvsnaturkännare som är stationerad i Darkshore. Förfärad över den mystiska sjukdom som driver skogens djur till vansinne skapade han den här anordningen med mild magi för att kuva smittade bestar utan att skada dem ytterligare.",al={"vem skapade tharnariun's hope","tharnariun's hopes ursprung","vem skapade tharnariuns fälla"}},c80e933b={q="Varför vill någon ha Tharnariun's Hope?",a="Tharnariun behöver att fällan används för att fånga en levande, rabiat tistlebjörn så att han kan studera fördärvet som härjar i Darkshore. Vanlig jakt skulle bara döda besten, men den här snarans lugnande verkan håller djuret stilla tillräckligt länge för att du ska kunna leda det säkert till Tharnariun, i hopp om att hitta ett botemedel.",al={"varför använda tharnariun's hope","varför behövs tharnariuns fälla","syftet med tharnariun's hope"}}},fp="17,135,14.402.0,18.413.1,31.184.0,46.168.0,40.122.0,49.144.1"}
P.entries["item:the-book-of-ur"] = {n="The Book of Ur",s="The Book of Ur är en lärd magisk avhandling, författad av den avlidne Dalaran-magikern Ur. Den beskriver hans forskning om märkliga varelser från andra dimensioner. Den lämnades kvar i Shadowfang Keep och hamnade i Archmage Arugals händer, innan Forsaken-forskare i Undercity började intressera sig för den.",h="The Book of Ur är en lärd magisk avhandling, författad av den avlidne Dalaran-magikern Ur.",kw={"apothecarium","arugal","the book of ur","dalaran","keeper bel'dugur","shadowfang keep","silverpine","ur"},ang={["class:Mage"]="Urs skrifter påminner om Dalarans lärdomars räckvidd i andra världar och om de dödliga följderna när ambitiösa magiker som Arugal missbrukar den förbjudna kunskapen.",["race:Undead"]="Att säkra Urs verk hjälper direkt den Mörka damens lärda i Apothecarium. Den försiktige mänsklige magikerns forskning blir därmed till praktisk makt för Forsaken."},sec={{t="Magikern från Dalaran",b="Innan Dalaran föll för Scourge var Ur känd bland Kirin Tor för sina esoteriska undersökningar av andra existensplan och utomvärldsliga varelser. Trots sin fascination för magi från andra plan lät sig Ur vägledas av försiktighet och etisk återhållsamhet. Han valde att dokumentera sina upptäckter i stället för att vårdslöst bryta igenom slöjan mellan världarna. När Scourge angrep den violetta staden räckte hans magiska skicklighet och moraliska tvekan tragiskt nog inte för att rädda honom."},{t="Forsakens ambitioner",b="Efter Urs död hamnade hans skrifter hos Archmage Arugal, som använde forskningen för att kalla monstruösa worgen till Silverpine Forest. Boken står nu i Shadowfang Keeps bokhyllor. Ryktet om att den fanns fångade Keeper Bel'dugurs intresse i Undercitys Apothecarium. Till skillnad från sin ursprunglige författare tvekar Forsaken inte inför att använda farlig, obehindrad magi för att säkra sin överlevnad och erövring."}},faq={{q="Vem var Ur?",a="Ur var en framstående mänsklig magiker från Dalaran före det tredje kriget. Han forskade ingående om andra dimensioner och varelser från andra plan, men vägrade att kalla på dem eftersom de utgjorde en enorm fara.",al={"vem skrev the book of ur","ur magiker från dalaran"}},{q="Var finns The Book of Ur?",a="Boken står på en hylla inne i Shadowfang Keep i Silverpine Forest, närmare bestämt i kammaren där det väldiga odjuret Fenrus håller till.",al={"the book of ur plats","var finns the book of ur"}},{q="Varför vill Keeper Bel'dugur ha boken?",a="Keeper Bel'dugur samlar in Urs skrifter åt intresserade i Undercity. Forsaken anser att Urs moraliska samvete hindrade honom från att nå verklig makt. De vill använda hans forskning om andra plan utan etiska begränsningar för att stärka sin egen makt.",al={"keeper bel'dugur the book of ur","varför vill undercity ha boken"}},{q="Hur hamnade boken i Shadowfang Keep?",a="Efter att Ur dött när Dalaran föll fick Archmage Arugal tag på hans forskning. I sin desperation att försvara sig mot Scourge förde Arugal anteckningarna till Silverpine Forest och använde Urs teorier om frammaning för att locka worgen till Azeroth.",al={"arugal och the book of ur","hur fick arugal tag på boken"}}},fx={["62a01830"]={q="Vad är The Book of Ur?",a="The Book of Ur är en lärd skrift med den esoteriska forskningen från Ur, en framstående magiker från Dalaran. Den beskriver hans omfattande studier av andra världar och farliga mystiska fenomen. Kunskapen var så kraftfull att ärkemagikern Arugal senare använde Urs skrifter för att kalla fram de monstruösa varulvarna i Silverpine Forest.",al={"vad är the book of ur","historien om the book of ur"}},["905bb2c4"]={q="Var kommer The Book of Ur ifrån, och vem skrev den?",a="Boken skrevs i det magiska kungariket Dalaran av magikern Ur innan staden förstördes av Scourge. Ur dokumenterade sina mystiska teorier och utforskningar av andra dimensioner, men arbetet övergavs efter hans död under Dalarans fall.",al={"vem skrev the book of ur","the book of urs ursprung","varifrån kom the book of ur"}}},fp="14,174,19.378.0,17.359.1,11.167.0,32.128.0,40.215.0,43.216.0"}
P.entries["item:the-collector-s-schedule"] = {n="The Collector's Schedule",s="Nära Brackwell Pumpkin Patch anger The Collector's Schedule när olovliga guldsändningar passerar genom Elwynn Forest. Gnoller bär den handskrivna resplanen, och Marshal Dughan känner igen namnet som står där.",h="Nära Brackwell Pumpkin Patch anger The Collector's Schedule när olovliga guldsändningar passerar genom Elwynn...",kw={"brackwell","the collector","dughan","elwynn","guld","goldshire","gruvor","schema"},ang={["faction:Alliance"]="Som medlem i Alliansen kan du se hur liten kontroll Stormwind har över sitt eget territorium när obehöriga arbetslag tar dess resurser nära huvudstaden.",["profession:Mining"]="Som gruvarbetare kan du se att Elwynns gruvor inte ligger öde: rika guldfyndigheter bryts och fraktas bort."},sec={{t="Stulet guld och hemliga sändningar",b="The Collector's Schedule anger datum och tider för guldsändningar från Elwynns gruvor. Stormwind har inte bedrivit officiell gruvdrift där på flera månader, efter att ha drivits bort av banditer och varelser som trängt in i området, men malm förs fortfarande bort i ett ordnat flöde. Resplanen anger vilka dagar och tider en person som kallas The Collector tar emot varje sändning. Spåren leder till ett läger nära Brackwell Pumpkin Patch i östra Elwynn Forest. När Marshal Dughan ser schemat känner han igen namnet på The Collector. Vem som betalar för det stulna guldet är fortfarande okänt."}},faq={{q="Vad är The Collector's Schedule?",a="The Collector's Schedule anger när guldsändningar lämnar Elwynn Forests övergivna gruvor för en agent som kallas The Collector.",al={"vad är den här anteckningen","föremålet the collector's schedule","guldplan"}},{q="Varifrån kommer schemat?",a="Gnoller bär schemat längs Elwynn Forests flodbankar och sluttningar. De kan ha tagit det från en kurir eller vara inblandade i att transportera guldet.",al={"vem släpper schemat","var hittar man schemat"}},{q="Vem är The Collector?",a="The Collector är en agent stationerad nära Brackwell Pumpkin Patch i östra Elwynn Forest. Marshal Dughan känner igen namnet men vet inte vem agenten tjänar.",al={"vem är the collector","the collectors identitet"}},{q="Varför oroar sig Marshal Dughan över schemat?",a="Marshal Dughan oroar sig eftersom Stormwind inte har haft några officiella gruvarbetare i Elwynns gruvor på flera månader, men betydande guldsändningar lämnar dem fortfarande. Det tyder på en organiserad, olaglig gruvverksamhet inom kungariket.",al={"varför bryr sig dughan","guld i elwynns gruvor"}}},fp="24,216,32.467.0,33.129.0,33.150.0,21.170.0,47.231.0"}
P.entries["item:the-embalmer-s-heart"] = {n="The Embalmer's Heart",s="The Embalmer's Heart är en ohelig relik som bultar i Elizas odöda kropp, djupt begravd i Duskwood. Den tillhörde en gång en sorgtyngd alkemist känd som the Embalmer. Genom mörk magi transplanterade han hjärtat för att återuppliva sin avlidna hustru, och det blev källan till hans förvridna kraft.",h="The Embalmer's Heart är en ohelig relik som bultar i Elizas odöda kropp, djupt begravd i Duskwood.",kw={"the embalmers brud","darkshire","duskwood","eliza","ello ebonlocke","embalmer's heart","the embalmer"},ang={["class:Warlock"]="Att transplantera ett fortfarande bultande, själsbundet organ som ankare för nekromantisk odödlighet är en djärv, om än kaotisk, bedrift inom köttkonst och själsmanipulation.",["race:Human"]="Den vänlige alkemistens tragiska fall är en mörk varning som viskas bland Duskwoods hårt prövade invånare."},sec={{t="En kärlek som trotsade döden",b="Enligt Darkshires folklore var the Embalmer en gång en mild alkemist vars sinne brast när hans älskade hustru Eliza dog. Desperat att återta henne från graven tog han sin tillflykt till vidrig trolldom och skar ut sitt eget hjärta. Han placerade det i Elizas livlösa bröst. Den oheliga överföringen väckte hennes lik till odödlighet, men uppståndelsen förvandlade henne till ett glupskt monster med en omättlig hunger efter levande människokött. Den skräckslagne alkemisten tvingades begrava henne på nytt."},{t="En sköld för Darkshire",b="Trots att hjärtat slets ur hans bröst är det fortfarande källan till the Embalmer's bestående mörka kraft, och det fortsätter att slå i Elizas grav. Borgmästare Ello Ebonlocke inser att det enda sättet att beröva the Embalmer hans trolldom är att krossa den återupplivade bruden och ta hjärtat. Genom att säkra hjärtat medan det fortfarande slår hoppas Darkshires ledare vända nekromantikerns egen ondskefulla magi mot honom och använda dess kraft som skydd mot hans fasor."}},faq={{q="Varför har Eliza the Embalmer's hjärta?",a="The Embalmer, förkrossad av sin hustru Elizas död, använde förbjuden magi för att placera sitt eget bultande hjärta i hennes lik och återuppliva henne. Ritualen väckte henne till liv, men förbannade henne med en omättlig hunger efter människokött.",al={"varför har eliza hjärtat","embalmer-hjärtat i eliza","vem satte hjärtat i eliza"}},{q="Varför vill borgmästare Ebonlocke att hjärtat förs tillbaka till Darkshire?",a="Borgmästare Ello Ebonlocke tänker använda den mörka magi som fortfarande genljuder i det bultande hjärtat för att skapa ett skyddande värn över Darkshire. På så sätt kan han neutralisera the Embalmer's kraft och göra den till ett skydd för staden.",al={"varför vill ello ha hjärtat","ebonlockes plan för hjärtat","vad gör darkshire med hjärtat"}},{q="Hur överlever the Embalmer utan sitt hjärta?",a="Med hjälp av den mörka trolldom han utövade band the Embalmer sin livskraft och makt direkt till det transplanterade hjärtat. Därför kan han bestå trots att organet slår i hans hustrus begravda kvarlevor.",al={"lever the embalmer","hur lever embalmer utan hjärta"}},{q="Var finns hjärtat?",a="Hjärtat finns i Eliza, som fortfarande ligger begravd på en undangömd gravplats i Duskwood. Det går bara att ta genom att möta och besegra den glupska, återupplivade bruden.",al={"var finns embalmer-hjärtat","var ligger elizas grav","hur får man embalmer-hjärtat"}}},fx={cac9cdef={q="Vad är The Embalmer's Heart?",a="Det är den upproriske alkemisten som kallas Embalmerns verkliga, magiskt vidmakthållna, bultande hjärta. Förblindad av sorgen över sin hustru Elizas död skar han ut sitt eget hjärta och lade det i hennes lik för att återuppliva henne. Även när hjärtat är skilt från hans bröst fungerar det som kärlet och kanalen för hans nekromantiska kraft. Det upprätthåller både Elizas förbannade odöda tillstånd och hans egen oheliga livskraft.",al={"vad är the embalmer's heart","historien om embalmers hjärta","the embalmer's heart"}}},fp="20,173,24.367.0,22.376.1,41.169.0,66.117.0,48.156.0,29.163.0"}
P.entries["item:the-first-troll-legend"] = {n="The First Troll Legend"}
P.entries["item:the-fourth-troll-legend"] = {n="The Fourth Troll Legend",s="Vid Ruins of Zul'Kunda leder Fourth Troll Legend Brother Nimetzs sökande bland Stranglethorns gamla stenar. Dess tecken kan bidra till att förklara Colonel Kurzens fördärv.",h="Vid Ruins of Zul'Kunda leder Fourth Troll Legend Brother Nimetzs sökande bland Stranglethorns gamla stenar.",kw={"brother nimetz","colonel kurzen","emperor's tomb","fjärde trolllegenden","stranglethorn","trolltavla","zul'kunda"},ang={["faction:Alliance"]="Som resenär från Alliance kan du hjälpa Brother Nimetz att undersöka Colonel Kurzens fall genom att ta med tecknen från Zul'Kunda till honom."},sec={{t="En stentavla i Zul'Kunda",b="Bland de norra ruinerna i Zul'Kunda finns Emperor's Tomb, som bär Fourth Troll Legend. Brother Nimetz söker efter dess tecken och tre andra trolllegender. Han hoppas att de gamla orden ska kasta ljus över Colonel Kurzens fall och har skickat dig för att hämta dem för studier."}},faq={{q="Vad är Fourth Troll Legend?",a="Fourth Troll Legend är en samling tecken på en stentavla som kallas Emperor's Tomb i Ruins of Zul'Kunda.",al={"fjärde trolllegenden","fjärde tavlan","trolllegend fyra"}},{q="Var kan jag hitta Fourth Troll Legend?",a="Emperor's Tomb ligger bland Ruins of Zul'Kunda i nordvästra Stranglethorn Vale.",al={"platsen för fjärde legenden","var ligger emperor's tomb","zul'kunda-tavlan"}},{q="Vem vill ha Fourth Troll Legend?",a="Brother Nimetz i Rebel Camp vill ha tecknen från Fourth Troll Legend så att han kan studera dem.",al={"vem behöver fjärde legenden","brother nimetzs tavla","nimetzs legender"}},{q="Varför studerar Brother Nimetz trolllegender?",a="Brother Nimetz hoppas att trolllegenderna kan avslöja vad som orsakade Colonel Kurzens fördärv.",al={"kurzens gåta","varför trolllegender","kurzens fördärv"}},{q="Vilka är de andra trolllegenderna?",a="De andra tavlorna bär First, Second och Third Troll Legends. De finns i Stranglethorns Bal'lal Ruins, The Vile Reef och Ruins of Zul'Kunda.",al={"första andra tredje legenden","andra tavlor","alla fyra legender"}}},fp="23,177,21.271.0,32.115.0,41.90.0,34.102.0,45.90.0,33.150.0"}
P.entries["item:the-general-s-response"] = {n="The General's Response",s="General Marcus Jonathan skickar besked till Lakeshire medan Redridge väntar på hjälp. Hans skrivelse bekräftar att han tagit emot Magistrate Solomons vädjan om hjälp mot Blackrock-orcherna och gnollerna, men erbjuder inga omedelbara förstärkningar från Stormwind.",h="General Marcus Jonathan skickar besked till Lakeshire medan Redridge väntar på hjälp.",kw={"general marcus jonathan","lakeshire","magistrate solomon","budbärare till stormwind","redridge","stormwind","generalens svar"},ang={["faction:Alliance"]="Stormwinds svar visar påfrestningarna inom Grand Alliance. Lakeshire blöder medan hovet verkar märkligt ointresserat av dess svåra situation.",["race:Human"]="För människor i de södra rikena visar det försenade svaret den växande sprickan mellan folket i provinserna, som kämpar för sin överlevnad, och den avskilda adeln i Stormwind Keep."},sec={{t="En diplomatisk låsning",b="Magistrate Solomon skickar en brådskande vädjan till Stormwind City om trupper som kan försvara Redridge mot de samlande Blackrock-orchstammarna och gnollernas krigarskaror. General Marcus Jonathan svarar att vädjan har vidarebefordrats till tronen, men att inga soldater skickas just nu. Han beordrar att brevet skickas tillbaka till Lakeshire. Solomon oroar sig över Stormwinds dröjsmål och misstänker att något är fel bland dess ledare."}},faq={{q="Vad står det i The General's Response?",a="General Marcus Jonathan sörjer de döda och säger att han ska göra kungen uppmärksam på Lakeshires svåra situation. Han hoppas kunna ta dit förstärkningar och anförtro sig åt Solomon om att Hans Majestät har varit svår att få tag på och betett sig märkligt.",al={"brevets innehåll","vad står det i brevet","generalens brev"}},{q="Varför kan General Marcus Jonathan inte skicka trupper till Lakeshire?",a="General Jonathan inväntar kungens svar innan han lovar förstärkningar. I förtroende berättar han för Solomon att Hans Majestät har varit svår att få tag på och betett sig märkligt.",al={"varför inga förstärkningar","varför hjälper stormwind inte lakeshire","varför ingen hjälp"}},{q="Hur reagerar Magistrate Solomon på brevet?",a="Magistrate Solomon blir djupt skakad av skrivelsen. Stormwinds långsamhet är obegriplig för honom när Lakeshire står inför en sådan fara, och han fruktar att försummelsen tyder på ännu värre problem i kungariket.",al={"solomons reaktion","vad tycker solomon","solomons svar"}}},fx={["3ebc4cbb"]={q="Vad är The General's Response?",a="Det är ett officiellt, förseglat brev skrivet av General Marcus Jonathan, befälhavare för Stormwind Citys garde, och adresserat till Magistrate Solomon i Redridge. Budbärare för brevet mellan huvudstaden och Lakeshire. Det innehåller överkommandots formella svar på Redridges desperata vädjan om kungliga förstärkningar.",al={"vad är the general's response","föremålet the general's response","vad är det här brevet"}},["174955dc"]={q="Var kommer The General's Response ifrån, och vem skrev den?",a="Brevet skrevs direkt av General Marcus Jonathan i Stormwind City. Efter att ha tagit emot Magistrate Solomons brådskande vädjan vid Valley of Heroes skriver Jonathan detta formella svar medan han väntar på besked från det kungliga hovet. Han anförtror dig uppgiften att ta tillbaka det till magistraten i Lakeshire.",al={"vem skrev the general's response","varifrån kom the general's response","vem skickade the general's response"}},d0ef00e9={q="Varför vill någon ha The General's Response?",a="Magistrate Solomon väntar otåligt på brevet för att få veta om Stormwind tänker skicka soldater för att rädda Lakeshire från svartklippiga orker och gnoller. När du levererar det får den hårt ansatta stadens ledning ett tydligt besked om vilken hjälp kungariket kan eller inte kan erbjuda.",al={"varför vill solomon ha brevet","vem vill ha the general's response","varför leverera the general's response"}}},fp="22,247,21.365.0,42.193.0,59.176.0,48.190.0"}
P.entries["item:the-legacy-heart"] = {n="The Legacy Heart",s="Mörk magi omger Legacy Heart, en relik som söks tillsammans med två andra kraftföremål. Gerrig Bonegrip i Ironforge vill ha den för ett syfte kopplat till Yagyin's Digest.",h="Mörk magi omger Legacy Heart, en relik som söks tillsammans med två andra kraftföremål.",kw={"bonegrips anteckning","mörk magi","gerrig bonegrip","hand of dagun","legacy heart","star of xil'yeh","yagyin's digest"},ang={["faction:Alliance"]="Som Alliance-resenär kan du lämna Legacy Heart och två andra reliker till Gerrig Bonegrip i Ironforge i utbyte mot Yagyin's Digest."},sec={{t="En kraftrelik",b="Gerrig Bonegrip ber om Legacy Heart bland tre reliker som han har skrivit upp på Bonegrip's Note. Han byter dem mot digesten, men håller deras namn borta från andras öron. Hjärtats mörka förtrollning har gett det ett fruktansvärt rykte."}},faq={{q="Vad är Legacy Heart?",a="Legacy Heart är en kraftrelik som Gerrig Bonegrip söker i utbyte mot Yagyin's Digest.",al={"legacy heart","hjärtrelik","hjärta med mörk magi"}},{q="Vem vill ha Legacy Heart?",a="Gerrig Bonegrip i Ironforge ber om Legacy Heart och två andra reliker.",al={"vem vill ha hjärtat","gerrig och hjärtat","bonegrips relik"}},{q="Varför vill Gerrig ha den?",a="Gerrig behöver Legacy Heart och två andra reliker innan han lämnar ifrån sig Yagyin's Digest.",al={"varför bonegrip vill ha det","hjärtats syfte","gerrigs skäl"}},{q="Vad sägs hjärtat kunna göra?",a="Det sägs att mörk magi ger Legacy Hearts bärare odödlighet. Dess nuvarande ägare bär titeln the Undying.",al={"hjärtats kraft","legacy hearts magi","hjärta som ger odödlighet"}},{q="Vilka andra reliker söker Gerrig?",a="Gerrig ber om Star of Xil'yeh, Hand of Dagun och Legacy Heart.",al={"andra reliker","stjärna hand hjärta","bonegrips lista"}}},fp="16,166,16.236.0,25.95.0,27.76.0,24.91.0,29.113.2,35.76.0"}
P.entries["item:the-lich-s-spellbook"] = {n="The Lich's Spellbook",s="The Lich's Spellbook är en volym med nekromantisk kunskap som förvaras i en kista på ön i Brightwater Lake. Bethor Iceshard i Undercity fick tag på boken, som avslöjar den tillbakadragne odöde lichens sanna identitet och enorma magiska kraft. Han bor strax norr om de Fördömdas huvudstad.",h="The Lich's Spellbook är en volym med nekromantisk kunskap som förvaras i en kista på ön i Brightwater Lake.",kw={"bethor iceshard","brightwater lake","gunther arcanus","lich","nekromanti","besvärjelsebok","tirisfal glades","undercity"},ang={["class:Mage"]="Besvärjelseboken utgör en sällsynt länk mellan Dalarans klassiska magi och mörk nekromanti. Den visar hur dödliga magiker utvecklade sina konster kraftigt efter att ha dukat under för odöden.",["race:Undead"]="Boken visar att alla som bröt sig fria från Lich King inte genast anslöt sig till de Fördömda. Den belyser den kvardröjande misstron bland förrymda odöda som överlevt och spritts över Tirisfal."},sec={{t="En tillbakadragen mästares böcker",b="På en isolerad ö i Brightwater Lake står en gåtfull lich omgiven av skelettväktare. Trots sin fria vilja misstror denne trollkarl omvärlden, tror att alla andra odöda är plågans trälbundna tjänare och befaller sina undersåtar att förgöra alla som närmar sig. Bethor Iceshard söker begåvade nekromantiker för att stärka de Fördömdas led under drottning Sylvanas Windrunner. Han gav ett sändebud i uppdrag att infiltrera lägret på ön och hämta lichens besvärjelsebok. Genom att studera den hoppades Bethor kunna bedöma mästarens magiska förmåga och ta reda på vem han var innan döden tog Lordaeron."},{t="Avslöjandet av Gunther Arcanus",b="När Bethor Iceshard öppnade de glödande sidorna i den återfunna besvärjelseboken gjorde han en häpnadsväckande upptäckt: den tillbakadragne var hans gamle vän och vapendragare från tiden före det tredje kriget, Gunther Arcanus. Gunthers skrifter visade att hans nekromantiska konster, som redan i livet varit enastående, hade blivit ännu mäktigare i odöden. Bethor insåg att Gunthers lojalitet skulle ge de Fördömda en ovärderlig mästare i mörka konster, om någon kunde övertyga den misstänksamme lichen om att de Fördömda verkligen är fria från Lich Kings grepp."}},faq={{q="Var hittar man The Lich's Spellbook?",a="Besvärjelseboken ligger i en behållare med namnet Gunther's Books, i lägret på den centrala ön i Brightwater Lake i norra Tirisfal Glades.",al={"var finns boken","besvärjelsebokens plats","gunther's books"}},{q="Vem äger den här besvärjelseboken?",a="Den tillhör lichen på ön i Brightwater Lake, som lever tillbakadraget och har fri vilja. Bethor Iceshard hoppas att en studie av bokens sidor ska avslöja ägarens identitet och förmågor.",al={"vems bok är det här","lichens identitet","vem skrev besvärjelseboken"}},{q="Varför vill Bethor Iceshard ha boken?",a="Bethor Iceshard sökte efter boken för att lista ut den mystiske lichens identitet och bedöma hans kunskaper i nekromanti. Han hoppades kunna rekrytera den tillbakadragne till Lady Sylvanas och de Fördömdas tjänst.",al={"varför hämta boken","bethors skäl för uppdraget","varför vill undercity ha den här"}},{q="Varför attackerar lichen besökare på sin ö?",a="Lichen tror att alla andra odöda i trakten fortfarande är viljelösa slavar under plågan. Förlamad av misstänksamhet befaller han sina undersåtar att angripa alla som närmar sig hans helgedom.",al={"varför är gunther fientlig","varför attackerar undersåtarna","fientlig vid brightwater lake"}},{q="Vad hoppas Bethor få veta om författaren?",a="Bethor hoppas få veta vem den isolerade lichen var i livet och om hans nekromantiska kunskaper kan hjälpa de Fördömda.",al={"vad får bethor veta","studie av lichens författarskap","bethors studie av besvärjelseboken"}}},fx={["44ee6981"]={q="Var kommer The Lich's Spellbook ifrån, och vem skrev den?",a="Besvärjelseboken tillhör den tillbakadragna, självständiga lich som bor på ön i Brightwater Lake. Han skrev och underhöll själv boken och fyllde dess lysande sidor med sina nekromantiska konster, både i livet och efter sin förvandling till en lich. Bethor Iceshard vill ha den för att ta reda på vem lichen var.",al={"vem skrev the lich's spellbook","the lich's spellbooks ursprung","varifrån kom the lich's spellbook"}}},fp="20,161,26.483.0,25.432.1,36.140.0,24.154.1,39.145.0,48.149.0,48.117.1"}
P.entries["item:the-second-troll-legend"] = {n="The Second Troll Legend"}
P.entries["item:the-state-of-lakeshire"] = {n="The State of Lakeshire",s="The State of Lakeshire är en brådskande skriftlig rapport från Magistrate Solomon, som beskriver den desperata militära kris som plågar Lakeshire. Den är direkt riktad till General Marcus Jonathan i Stormwind och vädjar till huvudstaden att skicka förstärkningar från kungens armé innan bosättningen i Redridge faller.",h="The State of Lakeshire är en brådskande skriftlig rapport från Magistrate Solomon, som beskriver den...",kw={"rapport","magistrate solomon","marcus jonathan","redridge","förstärkningar","lakeshires tillstånd","stormwind"},ang={["faction:Alliance"]="Rapporten visar hur sårbara rikets utposter är och hur politisk tröghet just nu fördröjer militär hjälp från huvudstaden.",["race:Human"]="För rikets människor understryker det att bära detta dokument de allt svagare banden mellan vanligt folk i Redridge och den avlägsna kronan i Stormwind."},sec={{t="Ett rop på hjälp",b="Magistrate Solomon skrev ”The State of Lakeshire” under de oupphörliga attackerna mot Redridge. Rapporten beskriver de svåra omständigheter som hotar samhället. Lakeshire är belägrat av fientliga Blackrock-orcher och gnoller och saknar lokal mansstyrka för att hålla gränserna hur länge som helst. Kurirer som färdas västerut mot Elwynn Forest har fått i uppdrag att bära med sig Solomons formella begäran om att Stormwind Army ska ingripa och bevara rikets östra gräns."},{t="Byråkrati och dödläge",b="När rapporten levereras till General Marcus Jonathan vid Stormwinds portar erkänner generalen Solomons höga ställning och rapportens allvar. Jonathan kan dock inte mobilisera armén på egen hand. Truppförflyttningar kräver kronans uttryckliga samtycke, så Lakeshires brådskande vädjan måste invänta rådslag på hög nivå med den unge kungen och regenten Bolvar Fordragon."}},faq={{q="Vad är The State of Lakeshire?",a="Det är en officiell skriftlig rapport av Magistrate Solomon, som beskriver den militära fara som hotar Lakeshire och ber Stormwind om truppförstärkningar.",al={"dokument om lakeshires tillstånd","vad är den här rapporten","solomons meddelande"}},{q="Vem ska ta emot rapporten?",a="Rapporten är direkt riktad till General Marcus Jonathan, befälhavare för Stormwinds stadsvakt och kungliga styrkor, som är stationerade vid Stormwinds portar.",al={"vem får rapporten","vem ska den levereras till","rapport till marcus jonathan"}},{q="Varför behöver Lakeshire förstärkningar från kungamakten?",a="Bosättningen är ständigt belägrad av Blackrock-orcher, Shadowhide-gnoller och lokala murlocer, vilket pressar stadsvakten bortom dess gränser.",al={"varför är lakeshire i fara","vad hotar redridge"}},{q="Skickar General Marcus Jonathan hjälp omedelbart?",a="Nej. Generalen håller med om att krisen är allvarlig, men han kan inte sätta in armén utan kungens formella godkännande. Därför måste begäran först granskas av kungamakten.",al={"hjälper stormwind","skickar jonathan trupper"}}},fx={["629511cc"]={q="Var kommer The State of Lakeshire ifrån, och vem skrev den?",a="Magistrate Solomon, Lakeshires ledare och domare, skrev denna viktiga rapport. Staden är utsatt för obevekliga angrepp från fientliga styrkor. Solomon skrev själv brevet för att formellt beskriva Redridges farliga läge och be Stormwinds överkommando om omedelbar militär hjälp.",al={"vem skrev the state of lakeshire","författaren till the state of lakeshire"}},["09d61feb"]={q="Varför behövs The State of Lakeshire så brådskande?",a="Lakeshire är under ständig belägring, och Magistrate Solomon vet att staden inte kan hålla stånd ensam utan kungliga förstärkningar. General Marcus Jonathan behöver den officiella redogörelsen för att motivera att delar av Stormwind-armén skickas ut och för att lägga fram Lakeshires desperata situation direkt inför kungen och Highlord Bolvar Fordragon.",al={"varför behövs the state of lakeshire","varför leverera the state of lakeshire","varför vill marcus jonathan ha the state of lakeshire"}}},fp="22,188,13.289.0,24.301.0,31.130.0,41.150.0,45.150.0,51.161.0"}
P.entries["item:the-third-troll-legend"] = {n="The Third Troll Legend",s="Vid Ruins of Zul'Kunda finns Third Troll Legend, en av fyra tavletexter som Brother Nimetz söker. Han hoppas att de gamla ristningarna ska kasta ljus över Colonel Kurzens fördärv.",h="Vid Ruins of Zul'Kunda finns Third Troll Legend, en av fyra tavletexter som Brother Nimetz söker.",kw={"brother nimetz","colonel kurzen","fall of gurubashi","kurzens mysterium","third troll legend","trolltavla","zul'kunda"},ang={["faction:Alliance"]="Brother Nimetz oro gäller Colonel Kurzen, en Alliance-officer vars fördärv har oroat honom. Legenderna kan hjälpa till att förklara vad som drabbade Kurzen."},sec={{t="Sten i Zul'Kunda",b="Bland de taklösa rummen i Ruins of Zul'Kunda finns Third Troll Legend på en stentavla som kallas Fall of Gurubashi. Brother Nimetz vid Rebel Camp söker efter ristningarna. Han studerar fyra trolllegender för att undersöka om de kan ha koppling till Colonel Kurzens fördärv."}},faq={{q="Vad är Third Troll Legend?",a="Third Troll Legend är en avskrift av ristningarna på tavlan Fall of Gurubashi i Ruins of Zul'Kunda.",al={"third troll legend","trolltavla","zul'kunda-legend"}},{q="Var finns tavlan Fall of Gurubashi?",a="Tavlan Fall of Gurubashi finns i det sydvästra rummet i Ruins of Zul'Kunda, på platån.",al={"fall of gurubashi plats","var finns tredje tavlan","zul'kunda-tavla"}},{q="Vem söker Third Troll Legend?",a="Brother Nimetz vid Rebel Camp söker de fyra trolllegenderna för att undersöka deras möjliga koppling till Colonel Kurzens fördärv.",al={"vem söker tavlan","brother nimetz legend","kurzen-mysteriet"}},{q="Varför samlar Brother Nimetz på trolllegender?",a="Brother Nimetz misstänker att trollmagi kan ha koppling till Colonel Kurzens fördärv och hoppas att legenderna ska hjälpa honom att undersöka saken.",al={"varför nimetz vill ha legender","kurzen trollmagi","varför kurzen-mysteriet"}}},fp="22,182,18.270.0,31.114.0,38.99.0,33.128.0,47.138.0"}
P.entries["item:theramore-medal"] = {n="Theramore Medal",s="Vid Northwatch Hold visar Theramore Medal att marinsoldater och officerare har tjänstgjort för att försvara utposten längs The Merchant Coast. Märket bär Theramores symbol och identifierar Alliansens garnison.",h="Vid Northwatch Hold visar Theramore Medal att marinsoldater och officerare har tjänstgjort för att försvara...",kw={"the barrens","captain fairmount","the merchant coast","northwatch hold","thalo'thas brightsun","theramore medal"},ang={["faction:Alliance"]="För Alliansens lojala visar Theramore-medaljer som samlats in som blodspengar hur isolerat och aggressivt Northwatch Hold har blivit vid Kalimdors gräns.",["faction:Horde"]="För hordäventyrare är dessa medaljer bevis på Alliansens växande militära närvaro vid The Barrens stränder."},sec={{t="Northwatchs brickor",b="Marinsoldater, skarpskyttar, kommandosoldater och officerare som tjänstgör från Northwatch Hold bär stämplade medaljer med Theramores symbol. Soldaterna är lojala mot Lady Jaina Proudmoores rike. För människotrupperna på klipporna ovanför The Barrens visar medaljerna att deras tjänst är legitim och att deras auktoritet kommer från Theramore. Andra ser dessa märken som troféer från en överdrivet nitisk utländsk garnison, som betraktar varje fartyg på väg mot kusten som ett dödligt hot."},{t="Piratisk hämnd",b="Northwatch Holds kanonbatterier hotar fartyg längs The Merchant Coast och beskjuter ofta både kapare och handelsfartyg. Efter att ha förlorat fartyg till kanonerna söker Ratchet-kaparen Captain Thalo'thas Brightsun medaljerna. Han vill ha bevis för att Northwatchs avfyrningsglada led har betalat med blod för att ha sänkt hans fartyg, och att de ansvariga soldaterna har dödats som hämnd."}},faq={{q="Vad är en Theramore Medal?",a="En Theramore Medal är ett märke som bärs av Theramores militärpersonal i tjänst vid Northwatch Hold. Den identifierar bäraren som en aktiv marinsoldat, sjöman eller officer i Alliansens garnison i The Barrens.",al={"theramore medal","vad är theramore-medaljer","northwatch-medalj"}},{q="Vem bär dessa medaljer?",a="Marinsoldater, prickskyttar, däcksmän, kommandosoldater, seniora kanonjärer och officerare som tjänstgör vid Northwatch Hold bär dessa medaljer längs The Merchant Coast.",al={"vem har theramore-medaljer","vem släpper theramore-medaljer","var kommer theramore-medaljer ifrån"}},{q="Varför vill Captain Thalo'thas Brightsun ha dem?",a="Northwatch Holds artilleri har beskjutit passerande fartyg, däribland fartyg som tillhör Captain Thalo'thas Brightsun flotta. Han kräver medaljerna som bevis för att de ansvariga soldaterna har dödats som hämnd.",al={"varför vill ratchet ha medaljer","brightsuns medaljer","varför samla theramore-medaljer"}},{q="Varför anfaller Northwatch Hold förbipasserande skepp?",a="Northwatch Holds garnison är paranoid vid gränsen till hordterritorium. Dess kanonjärer har blivit vårdslösa och avfyrningsglada och skjuter mot nästan alla fartyg som närmar sig deras kustnära enklav.",al={"varför skjuter northwatch på skepp","northwatchs aggression","varför anfaller northwatch ratchet"}}},fp="15,169,20.455.0,16.386.0,26.153.0,25.150.0,48.222.0,47.193.0"}
P.entries["item:thick-bear-fur"] = {n="Thick Bear Fur",s="Thick Bear Fur är ett eftertraktat skinn från de köldtåliga björnar som strövar bland snödrivorna i Dun Morogh. Det håller värmen väl och används ofta av spejare och soldater på resa för att tillverka isolering och varma bäddar mot den bitande alp kylan.",h="Thick Bear Fur är ett eftertraktat skinn från de köldtåliga björnar som strövar bland snödrivorna i Dun...",kw={"bellowfiz","dun morogh","the grizzled den","ice claw bear","jetsteam","steelgrill's depot","thick bear fur"},ang={["class:Hunter"]="När unga jägare ger sig ut i den kalla snårskogen för att spåra björnarna i Dun Morogh lär de sig att ta sig fram bland farliga bergsdjur och ta till vara på hållbara material från vildmarken.",["race:Gnome"]="Förare av belägringstankar som Bellowfiz, verksam kring Steelgrill's Depot, måste förlita sig på praktisk jakt i dvärgarnas trakter för att hålla sina maskiner funktionsdugliga under långa alpina fälttåg."},sec={{t="Värme mot bergsfrosten",b="Björnarna som stryker omkring på åsarna i Dun Morogh uthärdar några av de hårdaste snövidderna i Eastern Kingdoms. Deras tjocka, tåliga päls skyddar dem mot snöstormar och gör skinnen till en ovärderlig resurs för både lokalbor och resande. I stället för att kastas som avfall tas de tunga skinnen regelbundet till vara av jägare och används till att fodra kläder, isolera dragiga utposter och stoppa kalla sovrullar."},{t="Bäddar åt belägringsbrigaden",b="När Pilot Bellowfiz började utrusta sin belägringstank, Jetsteam, vid Steelgrill's Depot, insåg han att han skulle få tillbringa en hel månad ute i fält på ett långt uppdrag för Siege Brigade. Kallt järn ger föga tröst i snödrivor på hög höjd, så han gav lokala spejare i uppdrag att samla in tjock björnpäls från snöfälten söder om The Grizzled Den och tillverka varma bäddar åt hans hytt."}},faq={{q="Varifrån kommer Thick Bear Fur?",a="Thick Bear Fur kommer från de inhemska björnarna i Dun Morogh, särskilt Young Black Bears och Ice Claw Bears. De jagar över de snötäckta tundrorna och tallskogarna söder om The Grizzled Den.",al={"var får man tag på thick bear fur","vem släpper thick bear fur","björnpälsens plats"}},{q="Varför behöver Pilot Bellowfiz den här pälsen?",a="Pilot Bellowfiz utrustar sin tank, Jetsteam, för ett månadslångt uppdrag för Siege Brigade. Han behöver tunga pälsar för att tillverka varma bäddar inuti metallchassit och uthärda de bitande kalla nätterna i bergen.",al={"bellowfiz päls","varför behöver bellowfiz päls","samla päls åt jetsteam"}},{q="Vilka varelser i Dun Morogh ger detta skinn?",a="Både Young Black Bears och de större, våldsammare Ice Claw Bears som strövar omkring i höglandets snö har den täta päls som behövs för tunga vinterbäddar och isolering.",al={"vilka björnar släpper päls","björnarter i dun morogh"}}},fx={a2edc513={q="Vad är Thick Bear Fur?",a="Thick Bear Fur är den tjocka, isolerande päls som tas från de vilda björnarna som strövar bland Dun Moroghs iskalla klippor och snödrivor. Den täta huden har utvecklats för att stå emot bitande snöstormar långt under noll och ger livsviktig värme och skydd mot Khaz Modans obevekliga alpkyla.",al={"thick bear fur","vad är den här pälsen","björnpäls från dun morogh"}}},fp="14,164,33.281.0,29.350.0,36.162.0,39.213.0,45.160.0"}
P.entries["item:thick-yeti-hide"] = {n="Thick Yeti Hide",s="I Feralas lockar yetiskinn läderarbetare som uppskattar fina material. Pratt McGrubben och Jangdor Swiftstrider söker dem för sitt hantverk.",h="I Feralas lockar yetiskinn läderarbetare som uppskattar fina material.",kw={"feral scar vale","feralas","the forgotten coast","jangdor swiftstrider","läderarbete","pratt mcgrubben","garvning","tjockt yetiskinn","yeti"},ang={["profession:Tailoring"]="Som läderarbetare kanske du förstår varför Pratt McGrubben och Jangdor Swiftstrider uppskattar skinn som de tror kan behandlas så att de blir anmärkningsvärt starka."},sec={{t="En läderarbetares märke",b="Yetis i Feralas uppskattas av två läderarbetare för sina tjocka skinn. Pratt McGrubben vid Feathermoon Stronghold och Jangdor Swiftstrider vid Camp Mojache ber vardera om tio Thick Yeti Hides. De lovar ett val bland sina lädervaror i utbyte. Båda tror att noggrann garvning kan göra skinnen anmärkningsvärt slitstarka."}},faq={{q="Varifrån kommer tjocka yetiskinn?",a="Thick Yeti Hides kommer från yetis i Feralas. Många finns i Feral Scar Vale, strax inåt land från The Forgotten Coast.",al={"källa till tjocka skinn","var finns yetiskinn","yetiskinn feralas"}},{q="Vem vill ha tjocka yetiskinn?",a="Pratt McGrubben vid Feathermoon Stronghold och Jangdor Swiftstrider vid Camp Mojache söker vardera tio Thick Yeti Hides.",al={"vem behöver skinn","pratt skinn","jangdor skinn"}},{q="Vad används skinnen till?",a="Pratt McGrubben och Jangdor Swiftstrider vill ha skinnen för sitt läderarbete. De tror att skicklig garvning kan göra dem exceptionellt slitstarka.",al={"användning av yetiskinn","vad används skinn till","läderarbete skinn"}},{q="Vad erbjuder läderarbetarna?",a="Varje läderarbetare erbjuder ett val bland tillverkade lädervaror i utbyte mot en bunt med tio Thick Yeti Hides.",al={"skinnbyte","belöning för tio skinn","vad får jag"}}},fp="15,152,24.298.0,36.117.0,27.114.0,28.149.0,33.96.0"}
P.entries["item:thistlenettle-s-badge"] = {n="Thistlenettle's Badge",s="Thistlenettle's Badge är en officiell insignia för dvärgarnas Explorers' League, som Foreman Thistlenettle en gång bar med stolthet in i The Deadmines djup. Efter ett katastrofalt ras och ett rövarinfall är märket allt som återstår för att bekräfta förmannens tragiska öde för hans överlevande bror i Stormwind.",h="Thistlenettle's Badge är en officiell insignia för dvärgarnas Explorers' League, som Foreman Thistlenettle en...",kw={"the deadmines","explorers' league","moonbrook","oh brother","thistlenettle","thistlenettle's badge","westfall","wilder"},ang={["faction:Alliance"]="När insignian återbördas får en sörjande dvärg i Stormwinds Dwarven District ett avslut.",["race:Dwarf"]="Foreman Thistlenettle förde Explorers' Leagues fana och märke till Westfall. När märket återtas glöms inte en fallen son av Ironforge bort i mörkret."},sec={{t="Explorers' League i The Deadmines",b="Innan Defias Brotherhood stängde Moonbrook och de väldiga tunnlarna under byn, grävde dvärgiska guldletare med band till Ironforges Explorers' League i Westfalls gamla guldgruvor. Foreman Thistlenettle och hans arbetslag arbetade djupt under jord tills en plötslig tunnelkollaps skilde gruppen åt. Medan hans bror Wilder lyckades fly till Stormwind City, blev förmannen och flera arbetare kvar i mörkret under jord."},{t="En dyster bekräftelse",b="I stället för en hedervärd begravning eller en flyktväg dukade Foreman Thistlenettle under för de mörka faror som frodades i de osäkrade tunnlarna och reste sig som ett viljelöst odött vidunder bland de rasade schakten utanför huvudgjuteriet. Hans Explorers' League-märke låg fortfarande i hans hand och blev det enda obestridliga beviset på hans död när det återfanns och överlämnades till hans sörjande bror."}},faq={{q="Vem tillhör märket?",a="Märket tillhörde Foreman Thistlenettle, en dvärgisk gruvarbetare och medlem av Explorers' League som blev instängd djupt under Westfall vid en plötslig tunnelkollaps.",al={"vem ägde thistlenettles badge","ägare till thistlenettles badge"}},{q="Var hittar man märket?",a="Det bärs av Foreman Thistlenettle i The Deadmines övre korridorer, fulla av monster, utanför huvudingången till Defias fäste.",al={"märkets plats","hur får man thistlenettles badge","var hittar man thistlenettle"}},{q="Vem vill ha Thistlenettle's Badge?",a="Märket lämnas till Wilder Thistlenettle, förmannens bror, som för närvarande bor i Dwarven District i Stormwind City och väntar på besked om sin släktings öde.",al={"vem tar emot thistlenettles badge","vem lämnar in oh brother","wilder thistlenettles plats"}},{q="Varför var bröderna Thistlenettle i The Deadmines?",a="Bröderna undersökte och letade efter fyndigheter i de vidsträckta, mineralrika grottorna under Moonbrook på uppdrag av Explorers' League, innan fientliga rövare och ras förstörde deras expedition.",al={"varför var dvärgar i the deadmines","thistlenettles uppdrag i the deadmines"}}},fp="21,326,38.447.0,19.414.1,30.179.0,25.148.0,32.165.0,53.213.0"}
P.entries["item:thistleshrub-dew"] = {n="Thistleshrub Dew",s="I Gadgetzan lämnar Thistleshrub Dew Marin Noggenfogger med en bitter smak och en ny idé. Han skickar den till Sprinkle i hopp om att hon kan göra brygden lättare att dricka.",h="I Gadgetzan lämnar Thistleshrub Dew Marin Noggenfogger med en bitter smak och en ny idé.",kw={"bitter brygd","matlagning","gadgetzan","marin noggenfogger","sprinkle","thistleshrub dew"},ang={["profession:Cooking"]="Som kock kan du förstå varför Marin vänder sig till Sprinkle: han hoppas att hennes skicklighet ska göra den bittra brygden lättare att dricka."},sec={{t="En bitter smak",b="Marin Noggenfogger har smakat på Thistleshrub Dew, och den smakar förfärligt. I stället för att ge upp idén ber han dig ta den till Sprinkle, hans vän i Gadgetzan. Hon är en utmärkt kock, och Marin hoppas att hon kan ge drycken lite mer sting."}},faq={{q="Vad ska Thistleshrub Dew användas till?",a="Marin Noggenfogger vill att Sprinkle använder daggen för att göra hans obehagliga brygd lättare att dricka.",al={"användning av thistleshrub dew","vad ska daggen användas till"}},{q="Varför vill Marin ha Sprinkles hjälp?",a="Marin tycker att brygden smakar förfärligt och tror att Sprinkle, en utmärkt kock, kan förbättra den.",al={"varför sprinkle","marin behöver hjälp"}},{q="Vem är Sprinkle?",a="Sprinkle är kock i Gadgetzan och vän till Marin Noggenfogger.",al={"sprinkle gadgetzan","vem är sprinkle"}},{q="Vart ska Thistleshrub Dew?",a="Marin ber dig ta Thistleshrub Dew till Sprinkle i Gadgetzan.",al={"leverans av dagg","vart ska daggen"}}},fp="16,169,14.241.0,29.99.0,36.98.0,16.67.0,31.69.0"}
P.entries["item:thorium-plated-dagger"] = {n="Thorium Plated Dagger",s="En Thorium Plated Dagger är ett förtrollat vapen som bärs av Dark Iron taskmasters och slavers i Cauldron. Velarok Windblade behöver dess thoriumlegering till ett stadigt skaft.",h="En Thorium Plated Dagger är ett förtrollat vapen som bärs av Dark Iron taskmasters och slavers i Cauldron.",kw={"cauldron","dark iron-slavdrivare","dark iron-uppsyningsman","förtrollad legering","thorium","thorium plated dagger","velarok windblade"},sec={{t="Förtrollat thorium",b="Dark Iron taskmasters och slavers i Cauldron bär Thorium Plated Daggers av förtrollat thorium. Velarok Windblade söker den stadiga legeringen för att smida om ett skaft till flawless flame."}},faq={{q="Vilka använder Thorium Plated Daggers?",a="Dark Iron taskmasters och slavers i Cauldron bär Thorium Plated Daggers.",al={"vem har thoriumdolkar","dark iron-användare av dolkar"}},{q="Varför vill Velarok ha dolkarna?",a="Velarok Windblade kan bryta ner deras förtrollade thoriumlegering och smida om ett skaft.",al={"varför velarok behöver dolkar","dolkens syfte"}},{q="Vad är dolken gjord av?",a="Dolken är gjord av förtrollat thorium, en extremt stadig legering.",al={"thoriumdolkens material","vad dolken innehåller"}},{q="Hur många dolkar behöver Velarok?",a="Velarok Windblade behöver åtta Thorium Plated Daggers.",al={"antal dolkar","hur många thoriumdolkar"}}},fp="21,170,17.191.0,32.79.0,34.83.0,27.61.0,35.53.0"}
P.entries["item:thresher-eye"] = {n="Thresher Eye",s="Thresher Eye är biologiska prover som samlas in från threshers som stryker omkring i Darkshores kustvatten. De efterfrågas av den excentriske gnomingenjören Wizbang Cranktoggle för att serva hans automatiserade fältapparater, kallade Buzzboxes.",h="Thresher Eye är biologiska prover som samlas in från threshers som stryker omkring i Darkshores kustvatten.",kw={"auberdine","buzzbox 411","darkshore","darkshore thresher","thresher eye","wizbang cranktoggle"},ang={["profession:Engineering"]="Wizbangs vana att laga komplicerade mekaniska reläer med råa djurdelar ger en förbryllande men humoristisk inblick i gnomernas oortodoxa manicker.",["race:Gnome"]="Wizbang Cranktoggle står för de vildare ytterkanterna av gnomisk uppfinningsrikedom. Han pysslar med fältmaskiner i Kalimdors vildmark mellan koppar crawler wine."},sec={{t="Ekologiska prover till gnomernas manicker",b="Utanför Darkshores dimmiga stränder jagar vattenlevande rovdjur som kallas Darkshore Threshers i bränningarna och de yttre grunden. De är farliga för lokala fiskare och resenärer, men dessa bestar har stora ögonorgan som väckt Wizbang Cranktoggles märkliga intresse. Den gnomiske ingenjören håller till i närheten och är mycket förtjust i crawler wine. Han kräver ögonen som nödvändiga delar för att reparera Buzzbox 411, en av hans fjärrkommunikationsmaskiner, som står på stranden norr om Auberdine."},{t="Ögonens syfte",b="Wizbang förklarar aldrig riktigt hur slemmiga ögon från havsdjur kan reparera ömtåliga mekaniska apparater. Kanske fungerar de som grova optiska linser, kemiska ämnen eller esoteriska biologiska kugghjul. Oavsett den tvivelaktiga ingenjörslogiken återställer maskinen sin kommunikationslänk när tre insamlade ögon matas in i underhållsluckan på Buzzbox 411. Då kan Wizbang dela ut belöningar genom brusiga sändningar."}},faq={{q="Var kommer Thresher Eye ifrån?",a="Thresher Eye samlas in från Darkshore Threshers och Elder Darkshore Threshers som simmar i havet utanför Darkshores kust, särskilt nära Auberdine.",al={"var får man thresher eye","hur får man thresher eye","källa till thresher eye"}},{q="Varför vill Wizbang Cranktoggle ha Thresher Eye?",a="Wizbang hävdar att ögonen behövs för att reparera Buzzbox 411, en gnomisk manick på strandkanten norr om Auberdine. När de stoppas in i maskinens lucka aktiveras dess system igen.",al={"varför behövs thresher eye","ögon till buzzbox 411","vad används thresher eye till"}},{q="Hur kan ett öga laga en maskin?",a="Gnomisk ingenjörskonst trotsar ofta vanlig logik, särskilt när Wizbang Cranktoggles berusade planer styr arbetet. Oavsett om han använder näthinnorna för optisk fokusering eller helt enkelt bygger in organiska delar i sina excentriska konstruktioner, tar apparaten emot dem och slås på igen.",al={"varför ögon i en maskin","gnomisk maskin biologiska delar"}},{q="Vad är Buzzbox 411?",a="Buzzbox 411 är en av flera kommunikations- och övervakningsapparater som Wizbang Cranktoggle har placerat ut i Darkshore. När den laddats med de efterfrågade materialen kan Wizbang kommunicera på distans och dela ut förnödenheter.",al={"buzzbox 411 syfte","vem byggde buzzbox 411"}}},fx={eb2ee385={q="Vad är ett Thresher Eye?",a="Ett Thresher Eye är det ögonorgan som tas från rovfiskarna threshers, som simmar i kustvattnen utanför Darkshore. För de flesta är det bara vanlig biologisk materia, men den excentriske uppfinnaren Wizbang Cranktoggle hittar märkliga mekaniska eller kemiska användningsområden för dem när han reparerar sina maskiner för fjärrkommunikation, så kallade buzzboxar.",al={"vad är thresher eye","thresher-ögon"}}},fp="12,168,38.344.0,23.314.0,33.128.0,48.213.0,30.217.0,20.205.0"}
P.entries["item:thule-s-head"] = {n="Thule's Head",s="Thule's Head är det makabra bevis som Forsaken kräver för att bekräfta att Thule Ravenclaw, befälhavaren för Scourge-styrkorna på Fenris Isle, har dödats. När trofén förs till High Executor Hadrec vid The Sepulcher befästs Forsakens grepp om Silverpine Forest.",h="Thule's Head är det makabra bevis som Forsaken kräver för att bekräfta att Thule Ravenclaw, befälhavaren för...",kw={"fenris","hadrec","nekromantiker","ravenclaw","scourge","the sepulcher","thule"},ang={["faction:Horde"]="När Thule Ravenclaw oskadliggörs säkras Silverpine Forests östra gränser och Horde:s nyvunna områden skyddas från Scourge-infall.",["race:Undead"]="För Forsaken innebär det att hugga av Thules huvud både en militär seger och personlig hämnd på Lich Kings grepp om Lordaeron."},sec={{t="Trofé från Fenris Isle",b="Fenris Isle är Lich Kings främsta fäste för Scourge i Silverpine Forest. Djupt inne i Fenris Keep leder nekromantikern Thule Ravenclaw sina legioner av rot hides och odöda undersåtar. De hotar direkt Forsakens utposter, som The Sepulcher. High Executor Hadrec kräver full visshet om att den mörke befälhavaren har fallit och godtar inget vittnesmål som inte styrks av Thules avhuggna huvud. Den våldsamma urladdningen av mörk magi när Ravenclaw dog kändes genom skogen, men hans huvud är fortfarande det fysiska bevis Hadrec behöver för att förklara Fenris Isle besegrat."}},faq={{q="Vem vill ha Thule's Head?",a="High Executor Hadrec, som leder Forsakens militära operationer vid The Sepulcher i Silverpine Forest, kräver Thule's Head för att bekräfta att Scourge-ledaren har oskadliggjorts.",al={"vem behöver thules huvud","vem lämnade in thules huvud till","vem tar thules huvud"}},{q="Vem var Thule Ravenclaw?",a="Thule Ravenclaw är en mäktig nekromantiker som leder Scourge på Fenris Isle. Från hjärtat av Fenris Keep organiserar han attacker mot Forsaken och använder ondskefulla förtrollningar som Hex of the Ravenclaw.",al={"thules historia","vem är thule","thule ravenclaws bakgrund"}},{q="Varför kräver Forsaken just hans huvud?",a="Forsaken har inte råd att låta Scourge-hot dröja kvar i Silverpine. Eftersom nekromantiker är ökända för bedrägeri och mörka återuppståndelser godtar High Executor Hadrec inget mindre än fysiska, obestridliga bevis på att Thule är fullständigt förintad.",al={"varför thules huvud","varför vill de ha hans huvud"}},{q="Vad händer när Thule Ravenclaw dödas?",a="När Thule besegras sprider sig en våldsam våg av nekrotisk energi över regionen. Den är så kraftfull att Forsakens lärda och apotekare vid The Sepulcher kan känna den magiska chockvågen på avstånd.",al={"vad händer när thule dör","energi som frigörs när thule dör"}}},fx={["3fe7e40b"]={q="Var kommer Thule's Head ifrån?",a="Det här avhuggna huvudet kommer direkt från nekromantikern Thule Ravenclaw i salarna i Fenris Keep. Thule ledde Scourge-styrkorna som intog Fenris Isle i norra Silverpine Forest och förvandlade fästet till ett tillhåll för de odöda, tills du fällde honom.",al={"thule's head ursprung","var får man tag på thule's head","thule's head källa"}}},fp="12,201,21.432.1,23.152.0,24.198.0,49.193.0,43.163.1"}
P.entries["item:thunder-lizard-blood"] = {n="Thunder Lizard Blood",s="I södra Barrens tar jägare med sig Thunder Lizard Blood tillbaka som bevis på att de överlevt. Blodet kommer från de väldiga bestar som strövar över slätterna.",h="I södra Barrens tar jägare med sig Thunder Lizard Blood tillbaka som bevis på att de överlevt.",kw={"the barrens","camp taurajo","jorn skyseer","stormhide","stormsnout","thunder lizard blood","thunderhead"},ang={["class:Hunter"]="Som jägare behöver du stadigt fotfäste och smidighet för att överlista en åsködla. Att ta dess blod bevisar att du behärskar savannens största bestar.",["race:Tauren"]="Som taurenjägare från Camp Taurajo möter du åsködlor i ett traditionellt överlevnadsprov, sida vid sida med ditt hemlands väldiga jättar."},sec={{t="Jaktens trofé",b="Åsködlor kallas Stormsnouts, Stormhides och Thunderheads ute på slätterna. Deras tunga steg får marken att skaka, och deras krossande tyngd kan platta till oförsiktiga jägare. Att ta med sig deras blod tillbaka visar skickligheten att jaga dem och uthålligheten att överleva under deras dånande fötter."}},faq={{q="Vilka varelser ger detta blod?",a="Stormsnouts, Stormhides och Thunderheads ger blodet. Dessa fullvuxna åsködlor strövar på savannen kring Camp Taurajo i södra Barrens.",al={"vem släpper thunder lizard blood","var får man thunder lizard blood","vilka åsködlor"}},{q="Varför är Thunder Lizard Blood eftertraktat?",a="Jorn Skyseer i Camp Taurajo ber jägare samla blodet som en del av prövningar runt om i The Barrens. Att ta med det tillbaka oskadat visar att en jägare kan möta Kalimdors största stampande bestar.",al={"vem vill ha thunder lizard blood","syftet med thunder lizard blood"}},{q="Var brukar man hitta åsködlorna?",a="Åsködlor strövar på gräsmarkerna norr, öster och söder om Camp Taurajo, där de betar sida vid sida med de andra stora djuren i södra Barrens.",al={"åsködlornas platser","var finns stormsnouts"}}},fx={["25735f1e"]={q="Vad är Thunder Lizard Blood?",a="Thunder Lizard Blood är en livsviktig vätska som tas från de enorma åsködlorna som strövar omkring i södra The Barrens. De väldiga bestarna får slätterna att skaka vid varje steg, och deras blod är ett obestridligt bevis på att en jägare hade skickligheten och uthålligheten att fälla sådana mäktiga varelser utan att bli krossad under deras fötter.",al={"vad är thunder lizard blood","föremålet thunder lizard blood","om thunder lizard blood"}},d2820178={q="Var kommer Thunder Lizard Blood ifrån, och vem tillverkade det?",a="Blodet tappas naturligt från de mäktiga åsködlorna i södra The Barrens, särskilt de raser som kallas Stormsnouts, Stormhides och Thunderheads. Det tillverkas eller skapas inte av dödliga händer, utan tas direkt från dessa kolossala bestar av jägare som vågar möta deras trampande hovar på savannen.",al={"var kommer thunder lizard blood ifrån","vem tillverkade thunder lizard blood","thunder lizard blood ursprung"}}},fp="20,118,18.304.0,34.152.0,41.186.0,46.152.0"}
P.entries["item:thunder-lizard-horn"] = {n="Thunder Lizard Horn",s="I The Barrens söker Brewmaster Drohn ett Thunder Lizard Horn till Chen Stormstouts legendariska brygd.",h="I The Barrens söker Brewmaster Drohn ett Thunder Lizard Horn till Chen Stormstouts legendariska brygd.",kw={"the barrens","brewmaster drohn","chen stormstout","owatanka","ratchet","stormsnout","stormstout","thunder lizard horn","thunderhead"},ang={["class:Hunter"]="Som jägare bör du vara försiktig när du spårar åsködlor över den öppna savannen. Deras blixtar gör dem dödligare än vanliga kodoer eller slättlöpare i The Barrens.",["profession:Cooking"]="Som kock kan du tycka att Dohns recept är ovanligt: det blandar slättlöparinälvor, rovdjursbetar och ett odjurshorn till en berusande dryck."},sec={{t="En kraftfull bryggingrediens",b="Åsködlor strövar omkring i The Barrens, med kammarprydda kroppar som knastrar av blixtar. Brewmaster Drohn i Ratchet värdesätter deras horn som ingrediens i Stormstout-öl. Hans mentor lärde sig receptet av den kringvandrande pandaren Brewmaster Chen Stormstout och förde det vidare till Drohn. Hornet ger drycken dess kraftiga sting."}},faq={{q="Vad används hornet till?",a="Brewmaster Drohn i Ratchet använder hornet som ingrediens i brygden som Chen Stormstout gjorde berömd.",al={"användning av thunder lizard horn","vad används thunder lizard horn till","varför behöver jag thunder lizard horn"}},{q="Vilka bestar lämnar efter sig ett Thunder Lizard Horn?",a="Thunderheads, stormsnouts, thunderstomps, stormhides och den svårfångade Owatanka kan ge ett thunder lizard horn.",al={"var hittar man thunder lizard horn","vem lämnar thunder lizard horn","källor till thunder lizard horn"}},{q="Vem är Brewmaster Drohn?",a="Brewmaster Drohn brygger i Ratchet. Hans tidigare mentor lärde sig Stormstout-receptet av Chen Stormstout och förde det vidare till honom.",al={"vem är drohn","brewmaster drohns historia","drohn ratchet"}},{q="Är thunder lizards farliga att jaga för deras horn?",a="Åsködlor kan avge blixtar och släppa loss dånande tramp när de blir provocerade, vilket gör dem farliga att jaga ensam.",al={"hur tåliga är thunder lizards","jakt på thunder lizards"}}},fx={["6ace69b3"]={q="Vad är ett Thunder Lizard Horn?",a="Ett Thunder Lizard Horn är en stadig naturtrofé från de stora åsködlorna som strövar omkring på The Barrens slätter. De imponerande reptilerna, som är knutna till stormar, leder elektrisk energi genom sina väldiga kroppar. Därför är hornen en kraftfull naturkomponent som uppskattas av sällsynta hantverkare med ovanliga recept.",al={"vad är thunder lizard horn","information om thunder lizard horn","om thunder lizard horn"}},["1dc3a738"]={q="Var kommer ett Thunder Lizard Horn ifrån?",a="Det är inte konstgjort, utan ett horn som tas direkt från de fruktade åsködlorna i The Barrens, däribland stormsnouts, thunderheads och den svårfångade Owatanka. När du fäller en av dessa väldiga bestar kan du ta hornet utan att skada det.",al={"var kommer thunder lizard-horn ifrån","vem tillverkar thunder lizard horn","thunder lizard horn källa"}}},fp="19,98,24.297.0,26.82.0,41.111.0,24.130.0,54.117.0"}
P.entries["item:thunderhawk-saliva-gland"] = {n="Thunderhawk Saliva Gland",s="I The Barrens ger större åskhökar en körtel som Brewmaster Drohn värdesätter. Han behöver den för att återskapa Chen Stormstouts eldiga Trogg Ale.",h="I The Barrens ger större åskhökar en körtel som Brewmaster Drohn värdesätter.",kw={"the barrens","drohn","körtel","fat","ratchet","saliv","thunderhawk","trogg ale"},ang={["faction:Horde"]="Som medlem av Horde kan du bevisa ditt värde genom att jaga vildsinta åskhökar över The Barrens medan du färdas genom Kalimdor.",["profession:Cooking"]="Som kock kanske du drar dig för att använda spottkörtlar, men uppfinningsrika bryggmästare värdesätter märkliga djuresser för deras kryddiga smak och kraft."},sec={{t="En vild ingrediens",b="Större åskhökar jagar över The Barrens torra savanner. Dessa bevingade ormar är kända för att tygla stormar, och de äldre, farligare exemplaren producerar en spottkörtel laddad med naturlig kraft. Resenärer håller sig undan de dödliga bestarna, men bryggmästare värdesätter körteln som en sällsynt bas för exotiska drycker."},{t="Chens hemliga recept",b="Brewmaster Drohn slog sig ner utanför Ratchet efter att Chen Stormstout rest genom Kalimdor. Drohn studerar den kringvandrande bryggmästarens jäsningsmetoder och behöver en färsk åskhöks spottkörtel, stormhide lightning glands och kodo liver för att brygga Trogg Ale. Den eldiga drycken har ett omisskännligt sting och är tänkt att stärka härdade äventyrare."}},faq={{q="Var hittar du en Thunderhawk Saliva Gland?",a="Större åskhökar jagar över The Barrens öppna savanner, och deras spottkörtlar skördas där.",al={"byte från thunderhawk saliva gland","var får man tag på spottkörtel","thunderhawk-körtelns plats"}},{q="Vad används spottkörteln till?",a="Brewmaster Drohn utanför Ratchet behöver körteln för att brygga Trogg Ale, ett kraftfullt recept som Chen Stormstout lämnade efter sig.",al={"spottkörtelns användning","vad används thunderhawk saliva gland till","thunderhawk-spottkörtelns syfte"}},{q="Vem är Brewmaster Drohn?",a="Brewmaster Drohn bor nära Ratchets hamn. Han lärde sig exotisk bryggning av den kringvandrande resenären Chen Stormstout och byter till sig kraftfulla ölsorter från äventyrare som trotsar det lokala djurlivet för att få tag på ingredienser.",al={"drohn ratchet","vem är drohn","brewmaster drohns historia"}},{q="Vad är Trogg Ale?",a="Chen Stormstout skapade Trogg Ale som en ytterst kraftfull dryck. Brewmaster Drohn gör den med en större åskhöks spottkörtel, lightning glands och kodo liver.",al={"trogg ales historia","vad är trogg ale","chens trogg ale"}}},fx={bfe8bf39={q="Vad är en Thunderhawk Saliva Gland?",a="Det är ett organ som tas från fullvuxna, rovgiriga greater thunderhawks, som svävar över The Barrens torra slätter. Körteln är fylld av dessa fågelbestars naturliga energier och giftiga vätskor. Den ger en skarp och flyktig utsöndring som uppskattas av djärva bryggare som söker ovanliga blandningar med tydlig verkan.",al={"vad är thunderhawk saliva gland","berättelsen om thunderhawk saliva gland","om thunderhawk saliva gland"}},dda65d1e={q="Var kommer en Thunderhawk Saliva Gland ifrån?",a="Det är ingen tillverkad vara, utan ett biologiskt organ från greater thunderhawks som strövar över The Barrens öppna himmel och klippor. Jägare måste spåra upp dessa kraftfulla bevingade rovdjur och försiktigt ta ut körteln hel ur deras kroppar.",al={"thunderhawk saliva gland ursprung","var kommer thunderhawk saliva glands ifrån","vem tillverkade thunderhawk saliva gland"}}},fp="24,125,17.286.0,21.332.0,45.104.0,34.112.0,24.197.0,18.166.0"}
P.entries["item:thunderhawk-wings"] = {n="Thunderhawk Wings",s="Över centrala och södra Barrens tar jägare Thunderhawk Wings från vindormarna som svävar ovanför. I Camp Taurajo tar Jorn Skyseer emot dem som bevis på en jägares styrka, list och uthållighet.",h="Över centrala och södra Barrens tar jägare Thunderhawk Wings från vindormarna som svävar ovanför.",kw={"the barrens","camp taurajo","jorn skyseer","sergra darkthorn","thunderhawk","vindorm","vingar"},ang={["class:Hunter"]="Som jägare markerar det en övergångsrit att ta vingarna från en thunderhawk som svävar högt. Det prövar din spårningsförmåga, ditt tålamod och din träffsäkerhet mot snabba luftburna bestar.",["race:Tauren"]="Som tauren hedrar du savannens ande genom att skörda dessa vingar och visa respekt för Jordmoderns våldsamma varelser."},sec={{t="Jaktens trofé",b="Jägare som är stationerade i Camp Taurajo värdesätter ett par hela Thunderhawk Wings. Vindormar, som de lokala jägarna kallar thunderhawks, är våldsamma bevingade reptiler som slår till snabbt från ovan. Att spåra dem över de öppna slätterna och ta deras vingar i strid prövar jägarens skicklighet. För en lärling bevisar vingarna att hen är redo att följa den livslånga vägen som fullärd jägare."}},faq={{q="Var hittar man Thunderhawk Wings?",a="Thunderhawk Wings kommer från thunderhawks som glider över åsarna och slätterna i centrala och södra Barrens, särskilt kring Camp Taurajo.",al={"var hittar man vingarna","thunderhawk wings plats","hur får man thunderhawk wings"}},{q="Vem vill ha vingarna?",a="Jorn Skyseer, en erfaren taurenjägare stationerad i Camp Taurajo, ber om vingarna som bevis på att en lärling har bemästrat savannens jaktriter.",al={"vem tar thunderhawk wings","lämna in thunderhawk wings","jorn skyseer vingar"}},{q="Vad betyder det att ta vingarna?",a="Att ta vingarna till Jorn Skyseer fullbordar en krävande övergångsrit. Det visar att jägaren har styrkan, modet och tålamodet att möta våldsamma luftburna rovdjur.",al={"varför jaga thunderhawk","vingarnas syfte","betydelsen av thunderhawkjakten"}}},fx={["1074baa7"]={q="Vad är Thunderhawk Wings?",a="Dessa vingar tas från thunderhawks, de ståtliga fjäderklädda vindormarna som svävar över södra The Barrens slätter. Thunderhawks är vilda och stolta rovdjur, och tauren vördar dem som symboler för styrka och vild storhet. Man tar inte deras vingar lättvindigt; de är ett konkret bevis på jägarens skicklighet, mod och respekt när hen möter ett av himlens mäktigaste odjur.",al={"vad är thunderhawk wings","berättelsen om thunderhawk wings","thunderhawk-vingar"}},dd263964={q="Var kommer Thunderhawk Wings ifrån?",a="Vingarna tas direkt från dödade thunderhawks som strövar på den öppna himlen kring Camp Taurajo. Dessa bevingade ormar har naturlig blixtkraft och stor smidighet. De är rovdjur som hör hemma i luften över The Barrens, så vingarna är naturliga troféer från slutet av en krävande jakt.",al={"var kommer thunderhawk wings ifrån","thunderhawk wings källa","vilka fäller thunderhawk wings"}}},fp="17,133,18.340.0,34.144.0,22.144.0,37.168.0"}
P.entries["item:thunderhorn-cleansing-totem"] = {n="Thunderhorn Cleansing Totem",s="Thunderhorn Cleansing Totem är ett välsignat rituellt redskap som Mull Thunderhorn har tillverkat i Bloodhoof Village. Det är laddat med förfädernas magi för att rena det förorenade vattnet i Thunderhorn Water Well.",h="Thunderhorn Cleansing Totem är ett välsignat rituellt redskap som Mull Thunderhorn har tillverkat i Bloodhoof...",kw={"bloodhoof","rening","mulgore","mull","ritual","thunderhorn","totem","vattenbrunn"},ang={["class:Shaman"]="Schamaner förstår att reningstotemer fungerar som kanaler som stillar upprörda naturandar och återställer balansen där elementens energier har blivit bittra.",["race:Tauren"]="För tauren är reningen av förfädernas brunnar inte bara en syssla, utan en helig plikt gentemot Jordmodern och klanens förfäder, som vakar över Mulgore."},sec={{t="Reningen av Thunderhorn Well",b="Över Mulgore's vidsträckta slätter förgiftas jordens livsblod av en osedd korruption. Taurenstammarnas förfädersbrunnar ger hjordarna och jaktmarkerna livsviktig näring, men illasinnade agenter har besmittat vattnet. På uppdrag av den äldre Mull Thunderhorn bär äventyrare denna förberedda totem norr om Bloodhoof Village för att driva bort föroreningen som lagt sig över Thunderhorn-klanens heliga källa. Genom en rituell åkallan lugnar totemen vattnets upprörda andar och renar förfädernas plats."}},faq={{q="Vad är syftet med Thunderhorn Cleansing Totem?",a="Totemen är särskilt förberedd för att rena det förorenade vattnet i Thunderhorn Water Well, norr om Bloodhoof Village. När du använder den drivs det onda inflytandet som förgiftar brunnen bort, och förfädernas andar som vakar över den blir nöjda.",al={"vad gör totemen","varför använda thunderhorn totem","reningstotemens syfte"}},{q="Vem tillverkade totemen?",a="Totemen har tillverkats och skänkts av Mull Thunderhorn, en äldre person som bor i Bloodhoof Village, vakar över landets välmående och talar med förfäderna.",al={"vem gjorde totemen","vem ger thunderhorn totem","mull thunderhorns totem"}},{q="Var måste totemen användas?",a="Totemen måste användas vid själva Thunderhorn Water Well, norr om Bloodhoof Village i centrala Mulgore.",al={"var använder jag totemen","totemens plats","var ligger thunderhorn well"}},{q="Vad händer när ritualen är utförd?",a="När brunnen renas får Thunderhorn-klanens förfädersandar frid. Mull Thunderhorn får i en dröm syner av deras tacksamhet, och de lovordar den som renade deras marker och skänker förfädersgåvor.",al={"efter att brunnen renats","ritualens resultat","förfädernas reaktion"}}},fx={["0770e0ea"]={q="Vad är Thunderhorn Cleansing Totem?",a="Thunderhorn Cleansing Totem är ett invigt ritualföremål som skapats särskilt för att rena Thunderhorn Water Well i Mulgore från den korrumperande smittan. Det är fyllt av förfädersmagi och elementarmagi och fungerar som en helig kanal som leder andliga energier direkt till den förorenade källan, så att dess rena, livgivande vatten återställs för de lokala tauren.",al={"vad är thunderhorn cleansing totem","vad är thunderhorn totem","berättelsen om thunderhorn cleansing totem"}},d3c4386d={q="Varför behövs Thunderhorn Cleansing Totem?",a="Thunderhorn-klanens förfädersbrunn har drabbats av en onaturlig korrumpering som hotar landet och djuren som dricker därifrån. Vanliga metoder kan inte häva en sådan förbannelse. Mull Thunderhorn förberedde denna förtrollade totem så att ett sändebud kan utföra den högtidliga ritual som krävs för att driva bort smittan och blidka förfädernas andar som vakar över brunnen.",al={"varför behövs thunderhorn totem","varför behöver jag cleansing totem","thunderhorn cleansing totems syfte"}}},fp="27,151,30.355.0,55.217.0,22.153.0,29.91.0,43.188.1"}
P.entries["item:thurman-s-remains"] = {n="Thurman's Remains",s="Thurman's Remains är de kroppsliga kvarlevorna efter Thurman Agamand, återfunna i familjens förstörda kvarnar i norra Tirisfal Glades. En gång var han en förmögen kvarnägare som övertalade sina arbetare att stå emot Scourge, men Thurman föll för pesten och vandrar nu omkring på sin forna egendom som en odöd träl.",h="Thurman's Remains är de kroppsliga kvarlevorna efter Thurman Agamand, återfunna i familjens förstörda kvarnar...",kw={"agamand","agamand mills","coleman farthing","familjens döda","thurman agamand","thurman's remains","tirisfal glades"},ang={["race:Undead"]="För Forsaken är återtagandet av dessa kvarlevor en bister uppgörelse med aristokratiska herrar vars övermod ledde arbetarna rakt i Scourges våld."},sec={{t="Ett arv av förstörelse",b="Före det tredje kriget var familjen Agamand de mest välmående jordägarna i Tirisfal Glades. De drev omfattande kvarnar och hade dussintals lokala arbetare anställda. När Scourge svepte över Lordaeron befäste Thurman Agamand och hans släkt sin egendom i stället för att fly. Övertygade om att deras rikedom och befästa kvarnar skulle stå emot anfallet övertalade de sina trogna arbetare att ta till vapen vid deras sida. Försvaret misslyckades totalt. Agamandfamiljen och deras arbetare slaktades och förvandlades till Lich Kings viljelösa tjänare. I dag kräver Coleman Farthing, en före detta anställd som återuppstått som Forsaken, att hans forna herrar ska förgöras. Han söker Thurmans kvarlevor som bevis på att den dåraktige patriarken har fått betala för att ha dömt sitt hushåll till undergång."}},faq={{q="Vem var Thurman Agamand?",a="Thurman Agamand var en framstående medlem av den välbärgade Agamanddynastin, som ägde Agamand Mills i norra Tirisfal Glades. När Scourge slog till mot Lordaeron fick hans stolthet honom att övertala sina arbetare att stanna och slåss. Det ledde till att alla på egendomen slaktades och återuppväcktes.",al={"thurman agamand","vem är thurman","vem var thurman"}},{q="Varför vill Coleman Farthing ha Thurmans kvarlevor?",a="Coleman Farthing var en kvarnarbetare som litade på Agamandfamiljen och dog när han försvarade deras egendom. Nu tillhör Coleman Forsaken och hyser djup bitterhet mot sina forna arbetsgivare för att de dömde arbetarna till ett liv som odöda. Han söker Thurmans kvarlevor för att få sin hämnd.",al={"varför coleman vill ha kvarlevor","coleman farthings motiv","varför döda thurman"}},{q="Hade Thurman fri vilja när han förgjordes?",a="Nej. Till skillnad från Forsaken i Undercity förblev Thurman Agamand mentalt kontrollerad av Scourge efter sin död. Han tjänade som en tanklös undersåte tills han förgjordes vid kvarnarna.",al={"hade thurman fri vilja","var thurman scourge","är thurman forsaken"}},{q="Vilka andra i Agamandfamiljen är måltavlor?",a="Förutom Thurman söker Coleman Farthing förgöra Gregor Agamand och Nissa Agamand och återta deras kvarlevor. Därmed gör han slut på blodslinjen som en gång härskade över kvarnarna.",al={"andra i agamandfamiljen","medlemmar av agamandfamiljen","måltavlor bland familjens döda"}}},fx={["559ae8e6"]={q="Vad är Thurman's Remains?",a="Det här är de fysiska kvarlevorna efter Thurman Agamand, som återfanns sedan hans rastlösa odöda gestalt hade fällts vid Agamand Mills. Thurman tillhörde en gång den välbärgade Agamand-ätten, som ägde kvarnarna i området. Han föll offer för Plague of Undeath och blev kvar som en viljelös träl under Scourge tills han till slut fälldes.",al={"vad är thurman's remains","föremålet thurman's remains","vem är thurman's remains"}},["0ea47aa9"]={q="Var kommer Thurman's Remains ifrån?",a="De tas direkt från Thurman Agamands förstörda lik vid Agamand Mills i norra Tirisfal Glades. När Scourge drog genom landet befäste Thurman och hans släkt sin egendom och övertalade arbetarna att göra motstånd. Försvaret misslyckades, och familjen förvandlades till bestar i Scourge innan deras kroppar till slut slogs sönder.",al={"var får man tag på thurman's remains","thurman's remains ursprung","hur skapas thurman's remains"}}},fp="17,207,16.697.0,24.260.0,49.216.0,49.188.0,51.171.0"}
P.entries["item:thurman-s-sewing-kit"] = {n="Thurman's Sewing Kit",s="Hos Larson Clothiers behövs Thurman's Sewing Kit i hans skrädderiarbete. Verktygen tillhör den unge lärlingen Thurman Schneider, som lämnade dem hemma hos sin familj vid kanalen för att slippa en lång dag med sömnad.",h="Hos Larson Clothiers behövs Thurman's Sewing Kit i hans skrädderiarbete.",kw={"larson clothiers","mage quarter","rema schneider","sykit","stormwinds kanaler","thurman schneider","thurman's sewing kit"},ang={["profession:Tailoring"]="Varje skräddare känner till det träliga med den tidiga lärlingstiden, men få går så långt som den unge Thurman Schneider och lämnar saxarna bakom sig."},sec={{t="En motvillig lärlings verktyg",b="Thurman's Sewing Kit innehåller en skräddarlärlings vardagliga verktyg: nålar, saxar och tråd. Den unge Thurman Schneider studerar skrädderi hos Larson Clothiers, djupt inne i Stormwinds Mage Quarter nära Mage Tower. Hans mor, Rema Schneider, vet att han inte kan utföra sitt arbete utan kitet, så hon ber förbipasserande längs kanalerna att bära det till butiken. När Thurman får verktygen visar hans reaktion att han lämnade dem med flit, i hopp om att byta ut en dag med sömnad av kläder mot lite ledighet."}},faq={{q="Vad finns i Thurman's Sewing Kit?",a="Kitet innehåller nålar, saxar och tråd, verktygen som Thurman Schneider behöver i sitt skrädderiarbete hos Larson Clothiers.",al={"vad finns i kitet","sykitets innehåll","thurmans saxar"}},{q="Vem tillhör sykitet?",a="Kitet tillhör Thurman Schneider, en ung lärling som arbetar under familjen Larson i Stormwinds Mage Quarter.",al={"vem äger kitet","thurmans ägare","vem är thurman"}},{q="Varför lämnades kitet hemma hos Thurman?",a="Rema trodde att Thurman hade skyndat iväg och glömt kitet, men han lämnade det med flit i hopp om att slippa dagens arbete hos Larson Clothiers.",al={"varför glömde thurman sitt kit","glömde thurman det med flit","varför lämna sykit"}},{q="Vart ska kitet levereras?",a="Ta kitet till Larson Clothiers, djupt inne i Stormwind Citys Mage Quarter nära Mage Tower.",al={"vart ska jag ta kitet","var ligger larson clothiers","var finns thurman"}}},fx={["128c9147"]={q="Varför vill Rema Schneider att Thurman's Sewing Kit ska levereras?",a="Thurman är skräddarlärling hos Larson Clothiers i Mage Quarter. Hans mor, Rema Schneider, ber dig leverera sybehören så att han kan utföra sina dagliga skräddaruppgifter. Men Thurman lämnade i hemlighet kvar sina verktyg med flit, i hopp om att slippa dagens sysslor och smita från arbetet.",al={"varför leverera thurman's sewing kit","varför behöver thurman sitt sykit","varför vill någon ha sykitet"}}},fp="20,191,30.450.0,36.101.0,35.124.0,46.139.0,41.87.0"}
P.entries["item:timberling-seed"] = {n="Timberling Seed",s="Timberling Seeds är botaniska frön som skördas från de upprörda växtvarelser som bebor Teldrassil. Naturkunniga och druider studerar fröna för att förstå varför skogens växtliv har blivit ovanligt aggressivt.",h="Timberling Seeds är botaniska frön som skördas från de upprörda växtvarelser som bebor Teldrassil.",kw={"fördärvelse","darnassus","denalan","lake al'ameth","rellian greenspyre","teldrassil","timberling","timberling seed"},ang={["class:Druid"]="De fläckade fröna är tidiga varningstecken på en onaturlig fördärvelse som sprider sig bland Teldrassils växtvarelser, ett allvarligt bekymmer för Cenarion Enclaves beskyddare.",["profession:Herbalism"]="För botaniker och örtsamlare visar studiet av fröna hur starkt jordmånen och den omgivande fördärvelsen påverkar vildfloran."},sec={{t="Frön från en rastlös skog",b="Teldrassils timberlings är naturandar vars temperament återspeglar Världsträdets balans. På senare tid har dessa varelser blivit fientliga och arga, till nattalvernas bekymmer när de vårdar grenarna. Örtkunniga som Denalan vid Lake Al'Ameth tror att problemet har sina rötter i jorden. De samlar frön från vilda timberlings i hopp om att de ska gro till fogliga avkommor om de får växa under kontrollerade, renade förhållanden."},{t="En rotad fördärvelse",b="Försöken att odla milda timberlings möter en dyster verklighet. När fröprover undersöks av cenariska lärda som Rellian Greenspyre i Darnassus, uppdagas djupare problem. Fröna bär på fläcken från sina fördärvade föräldrar, vilket tyder på att oron bland Teldrassils växtandar inte bara beror på dålig tillväxt, utan på en underliggande fördärvelse som får fäste i det stora trädets ekosystem."}},faq={{q="Vad är ett timberlingfrö?",a="Ett Timberling Seed är en timberlings fortplantningsfrö, en växtlik naturande som finns över hela Teldrassil. Naturkunniga samlar in dem för att studera timberlingars tillväxt och ekologi.",al={"timberlingfrön","vad är timberlingfrön","timberlingens frön"}},{q="Var samlas fröna in?",a="De samlas in från vilda timberlings och sumpbestar som strövar längs Lake Al'Ameths stränder och grund.",al={"var får man tag på frön","timberling seed byte","vem släpper timberling seed"}},{q="Varför vill Denalan ha Timberling Seeds?",a="Denalan misstänker att olämplig jord driver timberlings till raseri. Han hoppas kunna plantera vilda frön i särskilt preparerad jord och se om han kan få fogliga, ofördärvade timberlings att gro.",al={"denalans syfte","varför samla frön","denalans plan"}},{q="Vad upptäcker Rellian Greenspyre om fröna?",a="Rellian upptäcker att en fördärvelse har fått fäste i timberlings, och att fröna bär på föräldrarnas fläck. Han inser att det ligger bortom hans förmåga att läka dem, så hoppet står till Denalans trädgårdsexperiment.",al={"rellians fröstudie","vad upptäckte rellian","är fröna fläckade"}}},fp="15,176,26.377.0,19.278.1,26.185.0,31.97.0,39.156.0,54.168.1"}
P.entries["item:timberling-sprout"] = {n="Timberling Sprout",s="Timberling Sprouts är unga, nybildade växtandar som slår rot nära Lake Al'Ameths stränder i Teldrassil. Redan tidigt visar de tecken på fördärv, så nattalvernas väktare drar upp dem innan de växer till aggressiva timberlings.",h="Timberling Sprouts är unga, nybildade växtandar som slår rot nära Lake Al'Ameths stränder i Teldrassil.",kw={"aldrassil","fördärv","lake al'ameth","shadowglen","teldrassil","timberling","timberling sprout"},ang={["class:Druid"]="För druider som står i samklang med Kalimdors växtliv och elementarer är det ett dystert omen för Teldrassils framtid att se naturliga skogsandar gro ur jorden redan fördärvade.",["race:NightElf"]="Unga nattalver som påbörjar sin träning i Shadowglen får i uppdrag att rensa bort groddarna för att skydda sitt nya skogshem."},sec={{t="Fördärvade groddar",b="Timberlings är växtandar med stark koppling till Teldrassils naturliga livskraft, men groddarna längs Lake Al'Ameth har oroat de lokala nattalverna. I stället för att växa fram friska och i harmoni med vildmarken slår de rot redan fördärvade och aggressiva. Eftersom dessa späda groddar verkar omöjliga att rena eller läka på naturlig väg måste vårdarna vid Lake Al'Ameth samla in och förstöra dem, så att fientliga timberlings inte sprider sig okontrollerat över den nyplanterade världsträdets sköra grenar."}},faq={{q="Var finns Timberling Sprouts?",a="Timberling Sprouts växer nära vattenbrynet längs Lake Al'Ameths stränder, söder om Dolanaar i Teldrassil.",al={"groddarnas plats","var finns timberling sprouts","hitta groddar"}},{q="Varför drar nattalverna upp Timberling Sprouts?",a="Groddarna slår rot fördärvade redan från början. Om de lämnas åt sitt öde växer de till våldsamma timberlings som hotar Teldrassils trygghet och balans. Eftersom de anses vara bortom all hjälp tar vårdarna bort dem medan de fortfarande är små.",al={"varför döda groddar","timberling sprouts syfte","varför förstöra groddar"}},{q="Vad får groddarna att bli fördärvade?",a="En mystisk sjukdom har börjat drabba Teldrassils djurliv och växtandar. Den exakta källan till fördärvet är fortfarande en olöst gåta för botanisten Denalan, men det påverkar unga timberlings från det ögonblick de slår rot.",al={"varför är timberlings fördärvade","vad fördärvar dem","groddsjuka"}},{q="Vem ber om att Timberling Sprouts ska samlas in?",a="Denalan, botanisten som sköter Lake Al'Ameth, ber äventyrare att samla in och rensa bort groddarna från sjökanten för att hålla marken ren.",al={"vem vill ha groddar","uppdragsgivare för groddar","lämna in timberling sprouts"}}},fx={f13cc7b7={q="Vad är en Timberling Sprout?",a="En Timberling Sprout är en ung timberling, en liten växtliknande elementarvarelse som slår rot längs de fuktiga stränderna vid Lake Al'Ameth. Om skotten lämnas i fred växer de så småningom upp till fullvuxna timberlings. Tyvärr är skotten som spirar kring sjön smittade och aggressiva, så botanisten Denalan vid Lake Al'Ameth vill att de rycks upp innan de växer till farliga hot.",al={"vad är timberling sprout","vad är timberling sprouts","information om timberling sprout"}}},fp="17,136,18.399.0,35.99.0,63.206.0,46.180.0,48.139.0"}
